def _public_studio_payload(value: Any) -> Any:
    """Remove provider-local coordinates from browser-facing payloads."""

    hidden_roots: set[str] = set()

    def collect(item: Any) -> None:
        if isinstance(item, Mapping):
            authority = item.get("source_authority")
            if item.get("provider_path_hidden") is True or (
                isinstance(authority, Mapping)
                and authority.get("kind") == "configured-catalog-source"
            ):
                for key in ("root", "source_path", "source_root"):
                    path = item.get(key)
                    if isinstance(path, str) and Path(path).is_absolute():
                        hidden_roots.add(path.rstrip(os.sep))
            for child in item.values():
                collect(child)
        elif isinstance(item, (list, tuple)):
            for child in item:
                collect(child)

    collect(value)

    def sanitize(item: Any) -> Any:
        if isinstance(item, Mapping):
            result = {str(key): sanitize(child) for key, child in item.items()}
            if result.get("provider_path_hidden") is True:
                for key in ("root", "source_path", "source_root"):
                    result.pop(key, None)
            authority = result.get("source_authority")
            if (
                isinstance(authority, Mapping)
                and authority.get("kind") == "configured-catalog-source"
            ):
                result.pop("publisher_id", None)
                result.pop("source_authority", None)
                result.pop("source_root", None)
            return result
        if isinstance(item, list):
            return [sanitize(child) for child in item]
        if isinstance(item, tuple):
            return [sanitize(child) for child in item]
        if isinstance(item, str):
            result = item
            for root in hidden_roots:
                if root and root in result:
                    result = result.replace(root, "[connected folder]")
            return result
        return item

    return sanitize(value)


class CatalogWorkspaceCreationUnsupported(RealmConflict):
    """Stable public capability failure for mutable catalog import sources."""

    code = "catalog_source_unpublished"


class ConfiguredPackagePublishPublicError(RealmConflict):
    """Path-free typed failure for the configured-package HTTP boundary."""

    def __init__(self, message: str, *, code: str):
        super().__init__(message)
        self.code = code


class InterfaceLaunchRuntimeUnavailable(RealmConflict):
    """Stable public failure when the isolated interface runtime is unavailable."""

    code = "interface_runtime_unavailable"


class InterfaceLaunchProcessExited(RuntimeError):
    """A detached interface command ended before its readiness contract passed."""

    def __init__(self, exit_code: int, diagnostic: str = "") -> None:
        self.exit_code = int(exit_code)
        # This value is never rendered directly.  It is deliberately bounded
        # here and passes through the launch's path/secret redactor before it
        # crosses the HTTP boundary.
        self.diagnostic = str(diagnostic or "").strip()[-2000:]
        super().__init__(
            f"Interface launch process exited with code {self.exit_code} "
            "before preview readiness."
        )


class InterfaceLaunchReadinessTimeout(TimeoutError):
    """An interface process stayed alive but missed its readiness deadline."""

    def __init__(
        self,
        *,
        port: int,
        timeout_seconds: int,
        diagnostic: str = "",
    ) -> None:
        self.port = int(port)
        self.timeout_seconds = max(0, int(timeout_seconds))
        self.diagnostic = str(diagnostic or "").strip()[-2000:]
        super().__init__(
            "Interface launch did not become reachable "
            f"on port {self.port} within {self.timeout_seconds}s."
        )


