CONFIGURED_PACKAGE_MAX_YAML_FILE_BYTES = 4 * 1024**2
CONFIGURED_PACKAGE_MAX_YAML_TOTAL_BYTES = 64 * 1024**2
CONFIGURED_PACKAGE_MAX_YAML_EVENTS = 50_000
CONFIGURED_PACKAGE_MAX_YAML_DEPTH = 128
# Generated simulation Workspaces are student-authored content.  Keep their
# vendored dependency inspection bounded before doing any content hashing; the
# retained runtime preparer performs its own independent checks after the
# package is sealed.
GENERATED_SIMULATION_MAX_RUNTIME_WHEELS = 64
GENERATED_SIMULATION_MAX_RUNTIME_WHEEL_BYTES = 64 * 1024**2
GENERATED_SIMULATION_MAX_RUNTIME_TOTAL_BYTES = 256 * 1024**2
CATALOG_PROJECTION_TTL_SECONDS = 24 * 60 * 60
# Read-path debounce for catalog discovery.  Consecutive catalog reads inside
# this window reuse the last projection refresh and the last scanned index
# instead of re-heartbeating every head and re-walking package source folders
# per request.  A value of 0 disables the cache entirely, which is the
# ``UiState`` default so directly constructed states (tests, helpers) keep
# strictly fresh reads; the served UI opts in via ``run_ui``.  Projection
# consumer leases outlive this window by orders of magnitude
# (CATALOG_PROJECTION_TTL_SECONDS), so debounced heartbeats remain ample.
CATALOG_REFRESH_TTL_SECONDS = 5.0
#: Studio advances a busy conversation itself. Before this, a turn only moved
#: while a browser tab polled it: the agent-server finished a run in 23
#: seconds and the session sat on "waiting_for_agent" for 4.6 hours because
#: the only open tab was in the background, where the page stops polling.
#: 5s matches the page's own cadence, so an unattended turn is no slower.
STUDIO_AGENT_TICK_INTERVAL_SECONDS = 5.0
#: The same ceiling the page uses for concurrent session syncs.
_AGENT_TICK_MAX_SESSIONS_PER_CYCLE = 4
_AGENT_TICK_BACKOFF_CEILING_SECONDS = 300.0
#: The poll loop sleeps 2s unconditionally between reads, so any window under
#: that yields exactly one read. A repeating tick wants that: what this cycle
#: misses, the next one catches 5s later.
_AGENT_TICK_POLL_SECONDS = 0.75
_PACKAGE_PLAN_APPLY_LOCK = threading.RLock()
