def _prepare_code_server_profile(user_data_dir: Path, extensions_dir: Path) -> None:
    settings_path = user_data_dir / "User" / "settings.json"
    settings_path.parent.mkdir(parents=True, exist_ok=True)
    extensions_dir.mkdir(parents=True, exist_ok=True)
    settings: JsonDict = {}
    if settings_path.exists():
        try:
            existing = json.loads(settings_path.read_text(encoding="utf-8"))
            if isinstance(existing, dict):
                settings.update(existing)
        except json.JSONDecodeError:
            settings = {}
    settings.update(CODE_SERVER_DEFAULT_USER_SETTINGS)
    settings_path.write_text(
        json.dumps(settings, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


class WorkspaceRuntimeStorageIdentityChanged(RuntimeError):
    """Studio can no longer prove ownership of a persisted runtime directory."""

    def __init__(self, *, workspace_id: str, runtime_path: Path) -> None:
        self.workspace_id = workspace_id
        self.runtime_path = runtime_path
        super().__init__(
            "Workspace runtime directory identity changed or its ownership claim "
            "is invalid. OptPilot left the "
            "runtime state untouched because its durable claim marker is missing "
            "or mismatched, or the directory was replaced while attached. "
            "OptPilot's provider-private runtime storage must be on a supported "
            "local, non-synchronized filesystem; partial copying, restoring, or "
            "syncing can invalidate that claim. Keep this directory for operator "
            f"inspection: {runtime_path}. The source workspace was not modified."
        )


def _workspace_runtime_record_proves_terminal(record: Mapping[str, Any]) -> bool:
    """Return whether a persisted stop receipt proves the runtime terminal."""

    proof = record.get("terminal_proof")
    return bool(
        record.get("status") == "stopped"
        and isinstance(proof, Mapping)
        and proof.get("terminal_confirmed")
    )


def _workspace_runtime_record_is_prestart(record: Mapping[str, Any]) -> bool:
    """Return whether durable state proves no container start was submitted."""

    if record.get("status") != "preparing":
        return False
    if any(
        record.get(key)
        for key in (
            "container_name",
            "host_port",
            "started_at",
            "launched_processes",
        )
    ):
        return False
    marker = record.get("container_may_exist")
    return marker is False or "container_may_exist" not in record


def _check_interface_launch_cancelled(
    should_stop: Optional[Callable[[], bool]],
) -> None:
    if should_stop is not None and should_stop():
        raise RuntimeError("Interface launch was stopped.")


#: Runs inside a workspace container and prints one canonical JSON document
#: describing the software present: the Python packages of every interpreter on
#: the path -- not only the default one, because software installed into a
#: second interpreter is still software the code may need -- and the system
#: packages. The comparison of two of these is how registration decides whether
#: anything was installed: file changes cannot decide it, because editing
#: anything leaves shell history and caches behind, but package managers are
#: how software actually arrives.
_SOFTWARE_INVENTORY_PROBE = r"""
import json, os, re, subprocess, sys

def interpreters():
    seen, found = set(), []
    for directory in (os.environ.get("PATH") or "").split(os.pathsep):
        try:
            names = sorted(os.listdir(directory))
        except OSError:
            continue
        for name in names:
            if name == "python" or re.fullmatch(r"python\d(?:\.\d+)?", name):
                path = os.path.join(directory, name)
                real = os.path.realpath(path)
                if real not in seen and os.access(path, os.X_OK):
                    seen.add(real)
                    found.append(real)
    return found

def python_packages(interpreter):
    try:
        listing = subprocess.run(
            [interpreter, "-m", "pip", "list", "--format=json",
             "--disable-pip-version-check"],
            capture_output=True, text=True, timeout=120,
        )
        if listing.returncode != 0:
            return []
        return sorted(
            (str(item.get("name", "")), str(item.get("version", "")))
            for item in json.loads(listing.stdout or "[]")
        )
    except Exception:
        return []

def system_packages():
    try:
        listing = subprocess.run(
            ["dpkg-query", "-W", "-f", "${Package}\t${Version}\n"],
            capture_output=True, text=True, timeout=120,
        )
        if listing.returncode != 0:
            return []
        return sorted(
            tuple(line.split("\t", 1))
            for line in listing.stdout.splitlines()
            if "\t" in line
        )
    except Exception:
        return []

inventory = {
    "python": {path: python_packages(path) for path in interpreters()},
    "system": system_packages(),
    "schema": "optpilot.workspace-software-inventory.v1",
}
print(json.dumps(inventory, sort_keys=True, separators=(",", ":")))
"""


class WorkspaceRuntimeManager:
    """Owns one long-lived container runtime per Studio workspace."""

    def __init__(
        self,
        *,
        studio_root: Path,
        runtime_root: Path,
        options: WorkspaceRuntimeOptions,
        prepared_runtime_cache_root: Optional[Path] = None,
        runtime_authority_root: Optional[Path] = None,
    ):
        lexical_studio_root = Path(os.path.abspath(studio_root.expanduser()))
        self.studio_root = lexical_studio_root.resolve()
        lexical_runtime_authority_root = Path(
            os.path.abspath(
                (runtime_authority_root or studio_root).expanduser()
            )
        )
        if lexical_runtime_authority_root.is_symlink():
            raise ValueError("Workspace runtime authority must not be a symlink.")
        self.runtime_authority_root = lexical_runtime_authority_root.resolve()
        runtime_path = Path(os.path.abspath(runtime_root.expanduser()))
        try:
            runtime_relative = runtime_path.relative_to(
                lexical_runtime_authority_root
            )
        except ValueError as error:
            # macOS exposes the same temporary directory through both /var and
            # /private/var. Runtime collaborators may return the resolved form
            # even when Studio received the lexical alias. Compare that form
            # without resolving the runtime's own descendants, whose symlinks
            # are rejected by the component walk below.
            try:
                runtime_relative = runtime_path.relative_to(
                    self.runtime_authority_root
                )
            except ValueError:
                raise ValueError(
                    f"Workspace runtime storage escapes its root: {runtime_path!s}."
                ) from error
        cursor = lexical_runtime_authority_root
        for component in runtime_relative.parts:
            cursor = cursor / component
            if cursor.is_symlink():
                raise ValueError(
                    "Workspace runtime storage contains a symlink: "
                    f"{runtime_relative!s}."
                )
        self.runtime_root = self.runtime_authority_root / runtime_relative
        self.prepared_runtime_cache_root = (
            Path(os.path.abspath(prepared_runtime_cache_root.expanduser())).resolve()
            if prepared_runtime_cache_root is not None
            else None
        )
        if self.prepared_runtime_cache_root is not None:
            linked = self.prepared_runtime_cache_root.lstat()
            if (
                self.prepared_runtime_cache_root.is_symlink()
                or not stat.S_ISDIR(linked.st_mode)
            ):
                raise ValueError(
                    "Prepared-runtime cache storage must be a real directory."
                )
        self.options = options
        self._health_cache: tuple[float, JsonDict] = (0.0, {})
        # Device/inode values are live attachment fences, not persisted
        # identities.  Filesystems may assign another device number after a
        # normal remount.  A manager instance remembers the first observation
        # so a same-process path replacement still fails closed.
        self._runtime_attachments: Dict[str, tuple[str, int, int]] = {}
        self._runtime_attachment_lock = threading.RLock()
        self.runtime_root.mkdir(parents=True, mode=0o700, exist_ok=True)
        if self.runtime_root.is_symlink() or not self.runtime_root.is_dir():
            raise ValueError("Workspace runtime storage must be a real directory.")

    def prepared_runtime_provider_identity(self) -> JsonDict:
        """Return the exact local builder identity used in cache keys."""

        executable = self._require_container_executable()
        self._enforce_image_policy()
        self._ensure_image_available(executable)
        inspected = subprocess.run(
            [executable, "image", "inspect", self.options.image],
            capture_output=True,
            text=True,
            timeout=30,
            check=False,
        )
        if inspected.returncode != 0:
            raise RuntimeError(
                "Workspace runtime image identity is unavailable: "
                + (inspected.stderr.strip() or inspected.stdout.strip())
            )
        try:
            payload = json.loads(inspected.stdout)
            image = payload[0]
        except (IndexError, KeyError, TypeError, json.JSONDecodeError) as error:
            raise RuntimeError(
                "Workspace runtime image identity is not canonical JSON."
            ) from error
        image_id = str(image.get("Id") or "")
        if (
            not image_id.startswith("sha256:")
            or len(image_id) != 71
            or any(character not in "0123456789abcdef" for character in image_id[7:])
        ):
            raise RuntimeError("Workspace runtime image has no immutable digest.")
        return {
            "executor": "workspace-container",
            "engine": Path(executable).name,
            "imageReference": self.options.image,
            "imageDigest": image_id,
            "os": str(image.get("Os") or ""),
            "architecture": str(image.get("Architecture") or ""),
            "network": str(self.options.network or "bridge"),
        }

    def _health_probe_timeout(self) -> int:
        """Seconds a single readiness probe may take before it is unanswered."""

        configured = int(self.options.health_probe_timeout_seconds or 0)
        return max(1, configured)

    def health(self) -> JsonDict:
        cached_at, cached = self._health_cache
        if cached and time.monotonic() - cached_at < 2:
            return dict(cached)
        executable = self._container_executable()
        configured = bool(self.options.executable)
        if not executable:
            payload = {
                "ok": False,
                "available": False,
                "configured": configured,
                "executable": self.options.executable or "",
                "engine": "",
                "image": self.options.image,
                "base_image": self.options.base_image,
                "build_image": self.options.build_image,
                "dockerfile": str(self._image_dockerfile()),
                "probe_timed_out": False,
                "error": "No Docker/Podman-compatible executable found. Install Docker or Podman, or set OPTPILOT_WORKSPACE_RUNTIME_EXECUTABLE.",
            }
            self._health_cache = (time.monotonic(), payload)
            return dict(payload)
        allowlist_error = self._image_policy_error()
        if allowlist_error:
            payload = {
                "ok": False,
                "available": True,
                "configured": configured,
                "executable": executable,
                "engine": Path(executable).name,
                "image": self.options.image,
                "base_image": self.options.base_image,
                "build_image": self.options.build_image,
                "dockerfile": str(self._image_dockerfile()),
                "image_allowlist": list(self.options.image_allowlist_patterns),
                "probe_timed_out": False,
                "error": allowlist_error,
            }
            self._health_cache = (time.monotonic(), payload)
            return dict(payload)
        probe_timeout = self._health_probe_timeout()
        try:
            version_completed = subprocess.run(
                [executable, "--version"],
                capture_output=True,
                text=True,
                timeout=probe_timeout,
                check=False,
            )
            info_completed = subprocess.run(
                [executable, "info"],
                capture_output=True,
                text=True,
                timeout=probe_timeout,
                check=False,
            )
        except subprocess.TimeoutExpired as exc:
            # A probe that never answered is not proof the engine is stopped:
            # say so, so operators do not chase a container runtime that is
            # merely slow (cold start, load) instead of absent.
            payload = {
                "ok": False,
                "available": True,
                "configured": configured,
                "executable": executable,
                "engine": Path(executable).name,
                "image": self.options.image,
                "base_image": self.options.base_image,
                "build_image": self.options.build_image,
                "dockerfile": str(self._image_dockerfile()),
                "probe_timed_out": True,
                "error": (
                    f"Workspace runtime readiness probe "
                    f"`{_probe_command_text(exc.cmd) or Path(executable).name}` "
                    f"did not answer within "
                    f"{probe_timeout}s. The engine may be starting or "
                    "unresponsive; retry, or raise "
                    "OPTPILOT_WORKSPACE_RUNTIME_HEALTH_TIMEOUT_SECONDS."
                ),
            }
            self._health_cache = (time.monotonic(), payload)
            return dict(payload)
        except Exception as exc:
            payload = {
                "ok": False,
                "available": True,
                "configured": configured,
                "executable": executable,
                "engine": Path(executable).name,
                "image": self.options.image,
                "base_image": self.options.base_image,
                "build_image": self.options.build_image,
                "dockerfile": str(self._image_dockerfile()),
                "probe_timed_out": False,
                "error": str(exc),
            }
            self._health_cache = (time.monotonic(), payload)
            return dict(payload)
        text = (
            (version_completed.stdout or version_completed.stderr).strip().splitlines()
        )
        ok = version_completed.returncode == 0 and info_completed.returncode == 0
        error = ""
        if version_completed.returncode:
            error = version_completed.stderr.strip() or version_completed.stdout.strip()
        elif info_completed.returncode:
            error = info_completed.stderr.strip() or info_completed.stdout.strip()
        payload = {
            "ok": ok,
            "available": True,
            "configured": configured,
            "executable": executable,
            "engine": Path(executable).name,
            "image": self.options.image,
            "base_image": self.options.base_image,
            "build_image": self.options.build_image,
            "dockerfile": str(self._image_dockerfile()),
            "image_allowlist": list(self.options.image_allowlist_patterns),
            "version": text[0] if text else "",
            "probe_timed_out": False,
            "error": error,
        }
        self._health_cache = (time.monotonic(), payload)
        return dict(payload)

    def status(self, workspace: JsonDict) -> JsonDict:
        workspace_id = str(workspace.get("id") or "")
        root = Path(str(workspace.get("root") or self.studio_root)).resolve()
        record = self._read_record(workspace_id)
        container_name = str(
            record.get("container_name") or self._container_name(workspace_id)
        )
        health = self.health()
        executable = str(health.get("executable") or "") or self._container_executable()
        engine_available = bool(health.get("ok"))
        has_runtime_record = bool(record.get("container_name") or record.get("status"))
        running = (
            self._container_running(container_name)
            if engine_available and executable and workspace_id and has_runtime_record
            else False
        )
        current_image = str(record.get("image") or "")
        # A workspace on its package's image is compared against that image,
        # which the record carries; only default-image workspaces are compared
        # against the operator's configured default.
        expected_image = (
            current_image
            if record.get("image_source") == "package" and current_image
            else self.options.image
        )
        image_matches = (not current_image) or current_image == expected_image
        host_port = int(record.get("host_port") or 0) or None
        code_url = self._code_server_base_url(host_port) if host_port else ""
        code_reachable = bool(code_url and _code_server_reachable(code_url))
        mount_mode = self._mount_mode(workspace)
        active_references = {
            "attached_sessions": len(
                list(workspace.get("attached_sessions", []) or [])
            ),
            "code_server_open": code_reachable,
            "active_processes": 1 if running else 0,
        }
        status = "running" if running else "stopped"
        message = ""
        if not engine_available:
            status = "unavailable"
            message = str(
                health.get("error") or "Workspace containers require Docker or Podman."
            )
        elif running and not image_matches:
            status = "stale"
            message = (
                f"Workspace container uses {current_image}; restart it to "
                f"use {expected_image}."
            )
        return {
            "target": "per-workspace-container",
            "status": status,
            "containerized": running,
            "executor": "container" if running else "container-manager",
            "engine": health.get("engine") or Path(executable).name
            if executable
            else "",
            "engine_available": engine_available,
            "executable": executable,
            "image": self.options.image,
            "current_image": current_image or self.options.image,
            "image_matches": image_matches,
            "base_image": self.options.base_image,
            "build_image": self.options.build_image,
            "dockerfile": str(self._image_dockerfile()),
            "image_allowlist": list(self.options.image_allowlist_patterns),
            "cpu_limit": self.options.cpu_limit,
            "memory_limit": self.options.memory_limit,
            "pids_limit": self.options.pids_limit,
            "no_new_privileges": self.options.no_new_privileges,
            "container_name": container_name,
            "container_running": running,
            "code_server_running": code_reachable,
            "active": running or code_reachable or any(active_references.values()),
            "active_references": active_references,
            "mount_mode": mount_mode,
            "workspace_root": str(root),
            "runtime_dir": str(self._workspace_runtime_dir(workspace_id)),
            "host": self.options.host,
            "port": host_port,
            "url": code_url,
            "started_at": record.get("started_at"),
            "stdout_log": record.get("stdout_log") or "",
            "stderr_log": record.get("stderr_log") or "",
            "message": message,
        }

    def global_status(
        self, *, active_workspace: Optional[JsonDict] = None, port: Optional[int] = None
    ) -> JsonDict:
        health = self.health()
        active_status = self.status(active_workspace) if active_workspace else {}
        host_port = int(active_status.get("port") or port or self.options.port_start)
        url = str(active_status.get("url") or self._code_server_base_url(host_port))
        running = bool(active_status.get("code_server_running")) and bool(
            active_status.get("image_matches", True)
        )
        port_conflict = _port_listening(self.options.host, host_port) and not bool(
            active_status.get("container_running")
        )
        return {
            "available": bool(health.get("ok")),
            "installed": bool(health.get("ok")),
            "running": running,
            "managed": bool(active_status.get("container_running")),
            "containerized": bool(active_status.get("container_running")),
            "port_conflict": port_conflict,
            "pid": None,
            "url": url,
            "host": self.options.host,
            "port": host_port,
            "auth": self.options.auth,
            "started_at": active_status.get("started_at"),
            "workspace_root": str(active_status.get("workspace_root") or ""),
            "stdout_log": str(active_status.get("stdout_log") or ""),
            "stderr_log": str(active_status.get("stderr_log") or ""),
            "runtime": active_status
            or {
                "target": "per-workspace-container",
                "status": "ready" if health.get("ok") else "unavailable",
                "containerized": False,
                "engine_available": bool(health.get("ok")),
                "engine": health.get("engine") or "",
                "image": self.options.image,
                "base_image": self.options.base_image,
                "build_image": self.options.build_image,
                "dockerfile": str(self._image_dockerfile()),
                "image_allowlist": list(self.options.image_allowlist_patterns),
                "cpu_limit": self.options.cpu_limit,
                "memory_limit": self.options.memory_limit,
                "pids_limit": self.options.pids_limit,
                "no_new_privileges": self.options.no_new_privileges,
                "runtime_dir": str(self.runtime_root),
            },
            "engine": health.get("engine") or "",
            "engine_available": bool(health.get("ok")),
            "image": self.options.image,
            "base_image": self.options.base_image,
            "build_image": self.options.build_image,
            "dockerfile": str(self._image_dockerfile()),
            "image_allowlist": list(self.options.image_allowlist_patterns),
            "error": health.get("error") or "",
            "install_hint": "Install Docker or Podman, or configure OPTPILOT_WORKSPACE_RUNTIME_EXECUTABLE. The workspace image must include code-server.",
        }

    def start(
        self,
        workspace: JsonDict,
        *,
        image: Optional[str] = None,
        should_stop: Optional[Callable[[], bool]] = None,
    ) -> JsonDict:
        """Start one workspace container.

        ``image`` is the package's own image when the workspace belongs to a
        package that declares one -- the design has a workspace run in the
        image its code will run in, so what works while building works in a
        run. The caller has already put it through the same checks a run
        performs (pinned, approved for execution, present with the right
        fingerprint and architecture), which is why the operator allowlist --
        the policy for the DEFAULT image -- does not apply to it.
        """

        _check_interface_launch_cancelled(should_stop)
        resolved_image = image or self.options.image
        explicit_image = image is not None
        workspace_id = str(workspace.get("id") or "")
        if not workspace_id:
            raise ValueError("Workspace id is required to start a runtime container.")
        root = Path(str(workspace.get("root") or "")).resolve()
        if not root.exists() or not root.is_dir():
            raise FileNotFoundError(f"Workspace root not found: {root}")
        executable = self._require_container_executable()
        if not explicit_image:
            self._enforce_image_policy()
        container_name = self._container_name(workspace_id)
        # A valid claim is the ownership boundary. The first runtime record is
        # written only after container absence has been proven, so a claimed
        # marker-only namespace is a recoverable pre-record interruption.
        runtime_dir = self._ensure_workspace_runtime_dir(workspace_id)
        record = self._read_record(workspace_id)
        running = self._container_running(container_name)
        removal_before_fresh_start: Optional[JsonDict] = None
        record_binds_container = bool(record) and (
            str(record.get("container_name") or "") == container_name
            and record.get("container_may_exist") is True
            and str(record.get("workspace_root") or "") == str(root)
            and str(record.get("status") or "")
            in {"starting", "running", "failed"}
            and not _workspace_runtime_record_proves_terminal(record)
        )
        if running and not record_binds_container:
            # The deterministic engine name is not ownership authority.  In
            # particular, a marker-only claimed namespace can coexist with a
            # legacy container whose writable runtime mount points at an
            # unclaimed directory.  Never manufacture a current record around
            # that process: remove it, prove name absence, and start from the
            # claimed namespace below.
            removal_before_fresh_start = self._remove_container(container_name)
            if not (
                removal_before_fresh_start.get("terminal_confirmed")
                and removal_before_fresh_start.get("state") == "absent"
            ):
                raise RuntimeError(
                    "Could not prove that the unrecorded workspace container "
                    "was removed before a fresh start."
                )
            running = False
        record_image_source = "package" if explicit_image else "default"
        if (
            running
            and record.get("image")
            and str(record.get("image")) != resolved_image
        ):
            removal_before_fresh_start = self._remove_container(container_name)
            if not (
                removal_before_fresh_start.get("terminal_confirmed")
                and removal_before_fresh_start.get("state") == "absent"
            ):
                raise RuntimeError(
                    "Could not prove that the stale workspace container was "
                    "removed before a fresh start."
                )
            running = False
        if not running:
            removal = (
                removal_before_fresh_start
                if removal_before_fresh_start is not None
                else self._remove_container(container_name)
            )
            if not (
                removal.get("terminal_confirmed")
                and removal.get("state") == "absent"
            ):
                raise RuntimeError(
                    "Could not prove that the previous workspace container was "
                    "absent before a fresh start."
                )
            # Image preparation can be slow or fail while the container engine
            # later becomes unavailable. Persist the already-known boundary:
            # this provider has not issued a start command, so launch-owned
            # execution cannot be live and its private files remain cleanable.
            record.update(
                {
                    "status": "preparing",
                    "updated_at": _now_iso(),
                    "workspace_root": str(root),
                    "container_may_exist": False,
                    "terminal_proof": removal,
                }
            )
            self._write_record(workspace_id, record)
            self._ensure_image_available(
                executable, resolved_image, pullable=not explicit_image
            )
            # Image preparation may take minutes. A Stop requested while it
            # was running must leave the durable pre-start proof intact and
            # must never fall through to ``docker run``.
            _check_interface_launch_cancelled(should_stop)
            host_port = self._host_port(workspace_id)
            command = self._container_run_command(
                executable, workspace, container_name, host_port,
                image=resolved_image,
            )
            _check_interface_launch_cancelled(should_stop)
            record.pop("terminal_proof", None)
            record.update(
                {
                    "container_name": container_name,
                    "host_port": host_port,
                    "status": "starting",
                    "updated_at": _now_iso(),
                    "image": resolved_image,
                    "image_source": record_image_source,
                    "workspace_root": str(root),
                    # This is intentionally set before ``docker run``. A
                    # timeout or interrupted subprocess may still have created
                    # the container and therefore requires engine proof.
                    "container_may_exist": True,
                    "prepared_runtime_entry": str(
                        workspace.get("_prepared_runtime_entry") or ""
                    ),
                    "prepared_runtime_cache_key": str(
                        workspace.get("_prepared_runtime_cache_key") or ""
                    ),
                }
            )
            self._write_record(workspace_id, record)
            _check_interface_launch_cancelled(should_stop)
            completed = subprocess.run(
                command,
                capture_output=True,
                text=True,
                timeout=int(self.options.start_timeout_seconds),
                check=False,
            )
            if completed.returncode != 0:
                record.update(
                    {
                        "status": "failed",
                        "updated_at": _now_iso(),
                        "stderr": completed.stderr.strip(),
                    }
                )
                self._write_record(workspace_id, record)
                raise RuntimeError(
                    f"Workspace container failed to start: {completed.stderr.strip() or completed.stdout.strip()}"
                )
            record.update(
                {
                    "status": "running",
                    "started_at": time.time(),
                    "updated_at": _now_iso(),
                    "last_used_at": _now_iso(),
                    "image": resolved_image,
                    "image_source": record_image_source,
                    "base_image": self.options.base_image,
                    "dockerfile": str(self._image_dockerfile()),
                    "cpu_limit": self.options.cpu_limit,
                    "memory_limit": self.options.memory_limit,
                    "pids_limit": self.options.pids_limit,
                    "no_new_privileges": self.options.no_new_privileges,
                    "workspace_root": str(root),
                    "container_may_exist": True,
                }
            )
            self._write_record(workspace_id, record)
            # The baseline the design's "nothing was installed" comparison
            # reads. Taken at the fresh start, because that is the moment the
            # container provably holds exactly what its image holds; an attach
            # to an already-running container keeps the existing baseline.
            self.record_baseline_inventory(workspace_id)
            _check_interface_launch_cancelled(should_stop)
        else:
            _check_interface_launch_cancelled(should_stop)
            record["container_name"] = container_name
            record["container_may_exist"] = True
            record["status"] = "running"
            record["last_used_at"] = _now_iso()
            record["updated_at"] = _now_iso()
            self._write_record(workspace_id, record)
        return self.status(workspace)

    def software_inventory(self, workspace_id: str) -> Optional[JsonDict]:
        """What software the workspace's container holds, right now.

        Returns None when the probe cannot run -- a workspace stays usable
        without an inventory; what is lost is only the later proof that
        nothing was installed, so registration must then assume something was.
        """

        executable = self._container_executable()
        if not executable:
            return None
        container_name = self._container_name(workspace_id)
        try:
            probe = subprocess.run(
                [
                    executable,
                    "exec",
                    container_name,
                    "python3",
                    "-c",
                    _SOFTWARE_INVENTORY_PROBE,
                ],
                capture_output=True,
                text=True,
                timeout=300,
            )
        except (OSError, subprocess.TimeoutExpired):
            return None
        if probe.returncode != 0:
            return None
        payload = (probe.stdout or "").strip().splitlines()
        if not payload:
            return None
        try:
            listing = json.loads(payload[-1])
        except json.JSONDecodeError:
            return None
        if not isinstance(listing, dict):
            return None
        canonical = json.dumps(listing, sort_keys=True, separators=(",", ":"))
        return {
            "digest": hashlib.sha256(canonical.encode("utf-8")).hexdigest(),
            "listing": listing,
        }

    def record_baseline_inventory(self, workspace_id: str) -> Optional[str]:
        """Take and store the starting inventory; later comparisons read it."""

        inventory = self.software_inventory(workspace_id)
        record = self._read_record(workspace_id)
        if inventory is None:
            record.pop("software_inventory_digest", None)
            record["software_inventory_state"] = "unavailable"
        else:
            record["software_inventory_digest"] = inventory["digest"]
            record["software_inventory_state"] = "recorded"
            runtime_dir = self._ensure_workspace_runtime_dir(workspace_id)
            (runtime_dir / "software-inventory.json").write_text(
                json.dumps(inventory["listing"], sort_keys=True, indent=1)
                + "\n",
                encoding="utf-8",
            )
        record["updated_at"] = _now_iso()
        self._write_record(workspace_id, record)
        return None if inventory is None else inventory["digest"]

    def capture_workspace_image(
        self, workspace_id: str, *, tag: str
    ) -> Optional[JsonDict]:
        """Commit the workspace container as an image and name its fingerprint.

        Returns the bare fingerprint and the platform the image reports, or
        None when there is nothing to capture -- no engine, no running
        container, or a commit the engine refused. The image lands in the
        machine's local store; making it shareable is the separate, explicit
        publish step the design describes.
        """

        executable = self._container_executable()
        if not executable:
            return None
        container_name = self._container_name(workspace_id)
        if not self._container_running(container_name):
            return None
        try:
            commit = subprocess.run(
                [executable, "commit", container_name, tag],
                capture_output=True,
                text=True,
                timeout=600,
            )
            if commit.returncode != 0:
                return None
            inspect = subprocess.run(
                [executable, "image", "inspect", tag],
                capture_output=True,
                text=True,
                timeout=60,
            )
        except (OSError, subprocess.TimeoutExpired):
            return None
        if inspect.returncode != 0:
            return None
        try:
            payload = json.loads(inspect.stdout or "[]")
        except json.JSONDecodeError:
            return None
        if isinstance(payload, list):
            payload = payload[0] if payload else {}
        digest = str(payload.get("Id") or "")
        os_name = str(payload.get("Os") or "linux")
        architecture = str(payload.get("Architecture") or "")
        if not digest.startswith("sha256:") or not architecture:
            return None
        return {"image": digest, "platform": f"{os_name}/{architecture}"}

    def start_code_server(
        self,
        workspace: JsonDict,
        *,
        image: Optional[str] = None,
        should_stop: Optional[Callable[[], bool]] = None,
    ) -> JsonDict:
        _check_interface_launch_cancelled(should_stop)
        normalized_network = str(self.options.network or "bridge").lower()
        if normalized_network in {"disabled", "none", "off"}:
            raise RuntimeError(
                "Code Server requires workspace runtime network access; configure the workspace runtime network as bridge/default."
            )
        runtime_status = (
            self.start(workspace, image=image)
            if should_stop is None
            else self.start(workspace, image=image, should_stop=should_stop)
        )
        _check_interface_launch_cancelled(should_stop)
        executable = self._require_container_executable()
        workspace_id = str(workspace["id"])
        record = self._read_record(workspace_id)
        container_name = str(
            record.get("container_name") or self._container_name(workspace_id)
        )
        host_port = int(
            record.get("host_port")
            or runtime_status.get("port")
            or self.options.port_start
        )
        root = Path(str(workspace["root"])).resolve()
        log_dir = self._workspace_runtime_dir(workspace_id) / "logs"
        user_data_dir = (
            self._workspace_runtime_dir(workspace_id) / "code-server" / "user-data"
        )
        extensions_dir = (
            self._workspace_runtime_dir(workspace_id) / "code-server" / "extensions"
        )
        for path in (log_dir, user_data_dir, extensions_dir):
            path.mkdir(parents=True, exist_ok=True)
        _prepare_code_server_profile(user_data_dir, extensions_dir)
        stdout_path = log_dir / "code-server.stdout.log"
        stderr_path = log_dir / "code-server.stderr.log"
        url = self._code_server_base_url(host_port)
        if _code_server_reachable(url):
            _check_interface_launch_cancelled(should_stop)
            record.update(
                {
                    "container_name": container_name,
                    "host_port": host_port,
                    "stdout_log": str(stdout_path),
                    "stderr_log": str(stderr_path),
                    "updated_at": _now_iso(),
                    "last_used_at": _now_iso(),
                }
            )
            self._write_record(workspace_id, record)
            status = self.status(workspace)
            return {
                **self.global_status(active_workspace=workspace, port=host_port),
                "open_url": f"{url}?folder={quote(str(root), safe='')}",
                "folder": str(root),
                "workspace_id": workspace_id,
                "workspace_root": str(root),
                "stdout_log": str(stdout_path),
                "stderr_log": str(stderr_path),
                "user_data_dir": str(user_data_dir),
                "extensions_dir": str(extensions_dir),
                "layout_persistent": True,
                "runtime": status,
                "managed": True,
                "containerized": True,
            }
        runtime_env = self._runtime_env(workspace)
        command = (
            "set -e; "
            f"mkdir -p {shlex.quote(str(user_data_dir))} {shlex.quote(str(extensions_dir))} {shlex.quote(str(log_dir))}; "
            "command -v code-server >/dev/null 2>&1; "
            "nohup code-server "
            f"--bind-addr 0.0.0.0:{int(self.options.container_port)} "
            f"--auth {shlex.quote(str(self.options.auth or 'none'))} "
            f"--user-data-dir {shlex.quote(str(user_data_dir))} "
            f"--extensions-dir {shlex.quote(str(extensions_dir))} "
            "--disable-telemetry --disable-update-check --disable-workspace-trust "
            "--disable-getting-started-override "
            f"{shlex.quote(str(root))} "
            f"> {shlex.quote(str(stdout_path))} 2> {shlex.quote(str(stderr_path))} &"
        )
        exec_env = dict(runtime_env)
        if self.options.password:
            exec_env["PASSWORD"] = self.options.password
        with self._docker_exec_env_file(exec_env) as env_file:
            _check_interface_launch_cancelled(should_stop)
            exec_command = [
                executable,
                "exec",
                "--env-file",
                str(env_file),
                container_name,
                "sh",
                "-lc",
                command,
            ]
            completed = subprocess.run(
                exec_command, capture_output=True, text=True, timeout=15, check=False
            )
        _check_interface_launch_cancelled(should_stop)
        if completed.returncode != 0:
            raise RuntimeError(
                f"Code Server failed to start in workspace container: {completed.stderr.strip() or completed.stdout.strip()}"
            )
        for _ in range(20):
            _check_interface_launch_cancelled(should_stop)
            if _code_server_reachable(url):
                break
            time.sleep(0.25)
        _check_interface_launch_cancelled(should_stop)
        record.update(
            {
                "container_name": container_name,
                "host_port": host_port,
                "code_server_started_at": time.time(),
                "stdout_log": str(stdout_path),
                "stderr_log": str(stderr_path),
                "updated_at": _now_iso(),
                "last_used_at": _now_iso(),
            }
        )
        self._write_record(workspace_id, record)
        status = self.status(workspace)
        open_url = f"{url}?folder={quote(str(root), safe='')}"
        return {
            **self.global_status(active_workspace=workspace, port=host_port),
            "open_url": open_url,
            "folder": str(root),
            "workspace_id": workspace_id,
            "workspace_root": str(root),
            "stdout_log": str(stdout_path),
            "stderr_log": str(stderr_path),
            "user_data_dir": str(user_data_dir),
            "extensions_dir": str(extensions_dir),
            "layout_persistent": True,
            "runtime": status,
            "managed": True,
            "containerized": True,
        }

    def exec(
        self,
        workspace: JsonDict,
        command: List[str],
        *,
        cwd: Path,
        env: Optional[Dict[str, str]] = None,
        timeout: int = 30,
    ) -> tuple[subprocess.CompletedProcess[str], JsonDict]:
        runtime_status = self.start(workspace)
        executable = self._require_container_executable()
        container_name = str(
            runtime_status.get("container_name")
            or self._container_name(str(workspace["id"]))
        )
        runtime_env = self._runtime_env(workspace)
        runtime_env.update(env or {})
        with self._docker_exec_env_file(runtime_env) as env_file:
            exec_command = [
                executable,
                "exec",
                "--env-file",
                str(env_file),
                "-w",
                str(cwd),
                container_name,
                *command,
            ]
            completed = subprocess.run(
                exec_command,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
        record = self._read_record(str(workspace["id"]))
        record["last_used_at"] = _now_iso()
        record["updated_at"] = _now_iso()
        self._write_record(str(workspace["id"]), record)
        return completed, self.status(workspace)

    def process_log_paths(self, workspace_id: str, name: str) -> JsonDict:
        """Return bounded-process log paths inside one runtime namespace."""

        safe_name = _slug_text(name or "process") or "process"
        log_dir = self._workspace_runtime_dir(workspace_id) / "logs"
        log_dir.mkdir(parents=True, exist_ok=True)
        return {
            "stdout_log": str(log_dir / f"{safe_name}.stdout.log"),
            "stderr_log": str(log_dir / f"{safe_name}.stderr.log"),
        }

    @contextmanager
    def _docker_exec_env_file(self, env: Mapping[str, str]) -> Any:
        """Pass exec environment without exposing values in host process args."""

        descriptor, raw_path = tempfile.mkstemp(
            prefix="optpilot-exec-env-", suffix=".list"
        )
        path = Path(raw_path)
        try:
            os.fchmod(descriptor, 0o600)
            with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
                for raw_key, raw_value in sorted(env.items()):
                    key = str(raw_key)
                    value = str(raw_value)
                    if (
                        not key
                        or "=" in key
                        or any(character in key for character in "\x00\r\n")
                    ):
                        raise ValueError("Container environment variable name is invalid.")
                    if any(character in value for character in "\x00\r\n"):
                        raise ValueError(
                            f"Container environment variable {key!r} contains a newline."
                        )
                    handle.write(f"{key}={value}\n")
                handle.flush()
                os.fsync(handle.fileno())
            yield path
        finally:
            try:
                path.unlink()
            except FileNotFoundError:
                pass

    def exec_logged(
        self,
        workspace: JsonDict,
        command: List[str],
        *,
        cwd: Path,
        env: Optional[Dict[str, str]] = None,
        timeout: int = 30,
        name: str = "process",
        should_stop: Optional[Callable[[], bool]] = None,
    ) -> tuple[subprocess.CompletedProcess[str], JsonDict, JsonDict]:
        """Run a foreground command while exposing live stdout/stderr files."""

        if not command:
            raise ValueError("command is required.")
        runtime_status = self.start(workspace, should_stop=should_stop)
        _check_interface_launch_cancelled(should_stop)
        executable = self._require_container_executable()
        workspace_id = str(workspace["id"])
        container_name = str(
            runtime_status.get("container_name") or self._container_name(workspace_id)
        )
        log_paths = self.process_log_paths(workspace_id, name)
        runtime_env = self._runtime_env(workspace)
        runtime_env.update(env or {})
        stdout_path = Path(str(log_paths["stdout_log"]))
        stderr_path = Path(str(log_paths["stderr_log"]))
        with self._docker_exec_env_file(runtime_env) as env_file:
            exec_command = [
                executable,
                "exec",
                "--env-file",
                str(env_file),
                "-w",
                str(cwd),
                container_name,
                *command,
            ]
            with stdout_path.open(
                "w", encoding="utf-8"
            ) as stdout_handle, stderr_path.open(
                "w", encoding="utf-8"
            ) as stderr_handle:
                raw_completed = subprocess.run(
                    exec_command,
                    stdout=stdout_handle,
                    stderr=stderr_handle,
                    text=True,
                    timeout=timeout,
                    check=False,
                )
        stdout = _read_log_file_tail(stdout_path, max_chars=64_000)
        stderr = _read_log_file_tail(stderr_path, max_chars=64_000)
        completed = subprocess.CompletedProcess(
            args=raw_completed.args,
            returncode=raw_completed.returncode,
            stdout=stdout,
            stderr=stderr,
        )
        record = self._read_record(workspace_id)
        record["last_used_at"] = _now_iso()
        record["updated_at"] = _now_iso()
        self._write_record(workspace_id, record)
        _check_interface_launch_cancelled(should_stop)
        return completed, self.status(workspace), log_paths

    def exec_detached(
        self,
        workspace: JsonDict,
        command: List[str],
        *,
        cwd: Path,
        env: Optional[Dict[str, str]] = None,
        name: str = "process",
        timeout: int = 15,
        should_stop: Optional[Callable[[], bool]] = None,
    ) -> JsonDict:
        if not command:
            raise ValueError("command is required.")
        runtime_status = self.start(workspace, should_stop=should_stop)
        _check_interface_launch_cancelled(should_stop)
        executable = self._require_container_executable()
        workspace_id = str(workspace["id"])
        container_name = str(
            runtime_status.get("container_name") or self._container_name(workspace_id)
        )
        safe_name = _slug_text(name or "process") or "process"
        log_paths = self.process_log_paths(workspace_id, safe_name)
        stdout_path = Path(str(log_paths["stdout_log"]))
        stderr_path = Path(str(log_paths["stderr_log"]))
        exit_code_path = stdout_path.parent / f"{safe_name}.exit-code"
        exit_code_path.unlink(missing_ok=True)
        runtime_env = self._runtime_env(workspace)
        runtime_env.update(env or {})
        runtime_env["OPTPILOT_PROCESS_STDOUT"] = str(stdout_path)
        runtime_env["OPTPILOT_PROCESS_STDERR"] = str(stderr_path)
        runtime_env["OPTPILOT_PROCESS_EXIT_CODE"] = str(exit_code_path)
        script = (
            '"$@" > "$OPTPILOT_PROCESS_STDOUT" 2> "$OPTPILOT_PROCESS_STDERR"; '
            'rc=$?; tmp="$OPTPILOT_PROCESS_EXIT_CODE.tmp.$$"; '
            'printf "%s\\n" "$rc" > "$tmp"; '
            'mv "$tmp" "$OPTPILOT_PROCESS_EXIT_CODE"; exit "$rc"'
        )
        with self._docker_exec_env_file(runtime_env) as env_file:
            exec_command = [
                executable,
                "exec",
                "--env-file",
                str(env_file),
                "-d",
                "-w",
                str(cwd),
                container_name,
                "sh",
                "-lc",
                script,
                safe_name,
                *command,
            ]
            completed = subprocess.run(
                exec_command,
                capture_output=True,
                text=True,
                timeout=timeout,
                check=False,
            )
        if completed.returncode != 0:
            raise RuntimeError(
                f"Workspace command failed to start: {completed.stderr.strip() or completed.stdout.strip()}"
            )
        _check_interface_launch_cancelled(should_stop)
        record = self._read_record(workspace_id)
        launches = [
            item
            for item in record.get("launched_processes", []) or []
            if isinstance(item, dict)
        ]
        launch = {
            "name": safe_name,
            "command": list(command),
            "cwd": str(cwd),
            "stdout_log": str(stdout_path),
            "stderr_log": str(stderr_path),
            "exit_code_file": str(exit_code_path),
            "started_at": _now_iso(),
        }
        launches.append(launch)
        record["launched_processes"] = launches[-20:]
        record["last_used_at"] = _now_iso()
        record["updated_at"] = _now_iso()
        self._write_record(workspace_id, record)
        return {
            **launch,
            "runtime": self.status(workspace),
            "returncode": completed.returncode,
        }

    def garbage_collect(
        self, workspaces: Iterable[JsonDict], *, active_workspace_id: str = ""
    ) -> JsonDict:
        now = time.time()
        stopped: List[JsonDict] = []
        skipped: List[JsonDict] = []
        for workspace in workspaces:
            workspace_id = str(workspace.get("id") or "")
            if not workspace_id:
                continue
            record = self._read_record(workspace_id)
            container_name = str(
                record.get("container_name") or self._container_name(workspace_id)
            )
            if not record or not self._container_running(container_name):
                continue
            if self._workspace_has_active_reference(
                workspace, record, active_workspace_id=active_workspace_id
            ):
                skipped.append(
                    {"workspace_id": workspace_id, "reason": "active_reference"}
                )
                continue
            idle_for = now - _parse_time_or_iso(
                record.get("last_used_at")
                or record.get("updated_at")
                or record.get("started_at")
                or now
            )
            if idle_for < int(self.options.idle_timeout_seconds):
                skipped.append(
                    {
                        "workspace_id": workspace_id,
                        "reason": "idle_timeout",
                        "idle_for_seconds": int(idle_for),
                    }
                )
                continue
            removal = self._remove_container(container_name)
            if not removal["terminal_confirmed"]:
                skipped.append(
                    {"workspace_id": workspace_id, "reason": "stop_unconfirmed"}
                )
                continue
            record.update(
                {
                    "status": "stopped",
                    "stopped_at": _now_iso(),
                    "updated_at": _now_iso(),
                    "idle_stopped": True,
                    "idle_for_seconds": int(idle_for),
                    "terminal_proof": removal,
                }
            )
            self._write_record(workspace_id, record)
            stopped.append(
                {
                    "workspace_id": workspace_id,
                    "container_name": container_name,
                    "idle_for_seconds": int(idle_for),
                }
            )
        return {
            "stopped": stopped,
            "skipped": skipped,
            "idle_timeout_seconds": int(self.options.idle_timeout_seconds),
        }

    def stop(self, workspace: JsonDict) -> JsonDict:
        workspace_id = str(workspace.get("id") or "")
        if not workspace_id:
            raise ValueError("Workspace id is required to stop a runtime container.")
        container_name = self._container_name(workspace_id)
        removal = self._remove_container(container_name)
        if not removal["terminal_confirmed"]:
            raise RuntimeError(
                "Workspace runtime stop is unconfirmed; its files were left intact."
            )
        record = self._read_record(workspace_id)
        record.update(
            {
                "status": "stopped",
                "updated_at": _now_iso(),
                "terminal_proof": removal,
            }
        )
        self._write_record(workspace_id, record)
        return self.status(workspace)

    def delete(self, workspace_id: str) -> bool:
        runtime_dir = self._workspace_runtime_dir(workspace_id)
        container_name = self._container_name(workspace_id)
        if not runtime_dir.exists():
            return False
        if not self._record_path(workspace_id).is_file():
            # A path name alone is not provider ownership. Leave an unmarked
            # directory intact for operator inspection instead of deleting it.
            return False
        parent_fd, runtime_fd, runtime_identity = self._open_runtime_namespace(
            workspace_id
        )
        try:
            record = self._read_record(workspace_id)
            already_terminal = _workspace_runtime_record_proves_terminal(record)
            if not already_terminal:
                removal = self._remove_container(container_name)
                if not removal["terminal_confirmed"]:
                    return False
            _remove_workspace_runtime_contents(
                runtime_fd, expected_device=runtime_identity[0]
            )
            storage_name = runtime_dir.name
            try:
                linked = os.stat(
                    storage_name, dir_fd=parent_fd, follow_symlinks=False
                )
            except FileNotFoundError:
                return False
            if (linked.st_dev, linked.st_ino) != runtime_identity:
                # The opened, owned directory was cleaned through its
                # descriptor, but its path now names another object. Never
                # remove the replacement merely because it reused the name.
                return False
            os.rmdir(storage_name, dir_fd=parent_fd)
            os.fsync(parent_fd)
            with self._runtime_attachment_lock:
                self._runtime_attachments.pop(workspace_id, None)
            return True
        finally:
            os.close(runtime_fd)
            os.close(parent_fd)

    def _container_run_command(
        self,
        executable: str,
        workspace: JsonDict,
        container_name: str,
        host_port: int,
        *,
        image: Optional[str] = None,
    ) -> List[str]:
        workspace_id = str(workspace["id"])
        root = Path(str(workspace["root"])).resolve()
        runtime_dir = self._workspace_runtime_dir(workspace_id)
        self._ensure_runtime_dirs(workspace_id)
        command = [
            executable,
            "run",
            "-d",
            "--name",
            container_name,
            "--label",
            "optpilot.runtime=workspace",
            "--label",
            f"optpilot.workspace_id={workspace_id}",
            "--entrypoint",
            "sh",
        ]
        command.extend(network_args(self.options.network))
        normalized_network = str(self.options.network or "bridge").lower()
        if normalized_network not in {"disabled", "none", "off", "host"}:
            command.extend(
                [
                    "-p",
                    f"{self.options.host}:{int(host_port)}:{int(self.options.container_port)}",
                ]
            )
        if self.options.cpu_limit:
            command.extend(["--cpus", str(self.options.cpu_limit)])
        if self.options.memory_limit:
            command.extend(["--memory", str(self.options.memory_limit)])
        if int(self.options.pids_limit or 0) > 0:
            command.extend(["--pids-limit", str(int(self.options.pids_limit))])
        if self.options.no_new_privileges:
            command.extend(["--security-opt", "no-new-privileges"])
        command.extend(
            [
                "-v",
                f"{root}:{root}:{self._mount_mode(workspace)}",
                "-v",
                f"{runtime_dir}:{runtime_dir}:rw",
            ]
        )
        command.extend(self._prepared_runtime_mount_args(workspace))
        command.extend(
            [
                image or self.options.image,
                "-lc",
                "trap 'exit 0' TERM INT; while true; do sleep 3600; done",
            ]
        )
        return command

    def _prepared_runtime_mount_args(self, workspace: JsonDict) -> List[str]:
        raw_entry = str(workspace.get("_prepared_runtime_entry") or "")
        if not raw_entry:
            return []
        if self.prepared_runtime_cache_root is None:
            raise RuntimeError("Prepared-runtime cache mounting is unavailable.")
        entry = Path(os.path.abspath(Path(raw_entry).expanduser()))
        entries_root = (self.prepared_runtime_cache_root / "entries").resolve()
        try:
            entry.relative_to(entries_root)
        except ValueError as error:
            raise PermissionError(
                "Prepared-runtime entry escapes the managed cache."
            ) from error
        linked = entry.lstat()
        if entry.is_symlink() or not stat.S_ISDIR(linked.st_mode):
            raise RuntimeError("Prepared-runtime entry must be a real directory.")
        mode = str(workspace.get("_prepared_runtime_mount_mode") or "ro")
        if mode not in {"ro", "rw"}:
            raise ValueError("Prepared-runtime mount mode is invalid.")
        if mode == "rw" and str(workspace.get("source_type") or "") != (
            "prepared-runtime-build"
        ):
            raise PermissionError(
                "Only the prepared-runtime builder may write a cache entry."
            )
        return ["-v", f"{entry}:{entry}:{mode}"]

    def _host_port(self, workspace_id: str) -> int:
        record = self._read_record(workspace_id)
        existing = int(record.get("host_port") or 0)
        reserved = self._reserved_host_ports(exclude_workspace_id=workspace_id)
        if (
            existing
            and existing not in reserved
            and not _port_listening(self.options.host, existing)
        ):
            return existing
        start = max(int(self.options.port_start), int(existing or 0) + 1)
        for port in range(start, start + 200):
            if port in reserved:
                continue
            if not _port_listening(self.options.host, port):
                return port
        raise OSError(f"No available workspace runtime port found near {start}.")

    def _reserved_host_ports(self, *, exclude_workspace_id: str = "") -> set[int]:
        reserved: set[int] = set()
        if not self.runtime_root.exists():
            return reserved
        for path in self.runtime_root.glob("*/runtime.json"):
            try:
                raw = json.loads(path.read_text(encoding="utf-8"))
                workspace_id = str(raw.get("workspace_id") or "")
            except (OSError, AttributeError, json.JSONDecodeError):
                continue
            if not workspace_id or self._workspace_runtime_dir(workspace_id) != path.parent:
                continue
            if exclude_workspace_id and workspace_id == exclude_workspace_id:
                continue
            try:
                payload = self._read_record(workspace_id)
            except (OSError, RuntimeError, ValueError):
                continue
            proof = payload.get("terminal_proof")
            if (
                payload.get("status") == "stopped"
                and isinstance(proof, dict)
                and proof.get("terminal_confirmed")
            ):
                continue
            try:
                port = int(payload.get("host_port") or 0)
            except (TypeError, ValueError):
                port = 0
            if port:
                reserved.add(port)
        return reserved

    def _ensure_image_available(
        self,
        executable: str,
        image: Optional[str] = None,
        *,
        pullable: bool = True,
    ) -> None:
        target = image or self.options.image
        if pullable:
            self._enforce_image_policy()
        inspect = subprocess.run(
            [executable, "image", "inspect", target],
            capture_output=True,
            text=True,
            timeout=15,
            check=False,
        )
        if inspect.returncode == 0:
            return
        if not pullable:
            # A package's own image is fetched deliberately, never as a side
            # effect of opening a workspace -- the same rule a run applies.
            raise RuntimeError(
                f"The package's image {target} is not on this machine. "
                "Fetch it first, then open the workspace."
            )
        if self._should_build_image():
            dockerfile = self._image_dockerfile()
            if not dockerfile.exists():
                raise RuntimeError(
                    f"Workspace runtime Dockerfile is missing: {dockerfile}"
                )
            build = subprocess.run(
                [
                    executable,
                    "build",
                    "--build-arg",
                    f"BASE_IMAGE={self.options.base_image}",
                    "-t",
                    self.options.image,
                    "-f",
                    str(dockerfile),
                    str(dockerfile.parent),
                ],
                capture_output=True,
                text=True,
                timeout=int(self.options.image_build_timeout_seconds),
                check=False,
            )
            if build.returncode != 0:
                raise RuntimeError(
                    f"Workspace runtime image build failed: {build.stderr.strip() or build.stdout.strip()}"
                )
            return
        pull = subprocess.run(
            [executable, "pull", self.options.image],
            capture_output=True,
            text=True,
            timeout=int(self.options.image_pull_timeout_seconds),
            check=False,
        )
        if pull.returncode != 0:
            raise RuntimeError(
                f"Workspace runtime image pull failed: {pull.stderr.strip() or pull.stdout.strip()}"
            )

    def _should_build_image(self) -> bool:
        return (
            bool(self.options.build_image)
            and self.options.image == DEFAULT_WORKSPACE_RUNTIME_IMAGE
        )

    def _image_policy_error(self) -> str:
        patterns = list(self.options.image_allowlist_patterns or [])
        if not patterns:
            return ""
        images = [self.options.image]
        if self._should_build_image():
            images.append(self.options.base_image)
        for image in images:
            if not any(fnmatch.fnmatchcase(image, pattern) for pattern in patterns):
                return f"Workspace runtime image is not allowed by OPTPILOT_WORKSPACE_RUNTIME_IMAGE_ALLOWLIST: {image}"
        return ""

    def _enforce_image_policy(self) -> None:
        error = self._image_policy_error()
        if error:
            raise RuntimeError(error)

    def _workspace_has_active_reference(
        self, workspace: JsonDict, record: JsonDict, *, active_workspace_id: str
    ) -> bool:
        workspace_id = str(workspace.get("id") or "")
        if active_workspace_id and workspace_id == active_workspace_id:
            return True
        if workspace.get("attached_sessions"):
            return True
        host_port = int(record.get("host_port") or 0)
        if host_port and _code_server_reachable(self._code_server_base_url(host_port)):
            return True
        return False

    def _image_dockerfile(self) -> Path:
        if self.options.dockerfile:
            return Path(self.options.dockerfile).expanduser().resolve()
        return Path(__file__).resolve().parent / "workspace_runtime" / "Dockerfile"

    def _ensure_runtime_dirs(self, workspace_id: str) -> None:
        runtime_dir = self._ensure_workspace_runtime_dir(workspace_id)
        for child in (
            runtime_dir / "home",
            runtime_dir / "cache" / "pip",
            runtime_dir / "cache" / "uv",
            runtime_dir / "cache" / "npm",
            runtime_dir / "code-server" / "user-data",
            runtime_dir / "code-server" / "extensions",
            runtime_dir / "logs",
        ):
            child.mkdir(parents=True, exist_ok=True)

    def _runtime_env(self, workspace: JsonDict) -> Dict[str, str]:
        workspace_id = str(workspace.get("id") or "")
        runtime_dir = self._workspace_runtime_dir(workspace_id)
        self._ensure_runtime_dirs(workspace_id)
        home = runtime_dir / "home"
        return {
            "HOME": str(home),
            "PIP_CACHE_DIR": str(runtime_dir / "cache" / "pip"),
            "UV_CACHE_DIR": str(runtime_dir / "cache" / "uv"),
            "NPM_CONFIG_CACHE": str(runtime_dir / "cache" / "npm"),
            "OPTPILOT_WORKSPACE_ROOT": str(
                Path(str(workspace.get("root") or self.studio_root)).resolve()
            ),
            "OPTPILOT_WORKSPACE_RUNTIME_DIR": str(runtime_dir),
        }

    def _mount_mode(self, workspace: JsonDict) -> str:
        mode = str(workspace.get("mode") or "editable")
        source_type = str(workspace.get("source_type") or "workspace")
        return (
            "ro"
            if mode in {"read-only", "analysis"} or source_type in {"catalog", "run"}
            else "rw"
        )

    def _code_server_base_url(self, port: Optional[int]) -> str:
        return f"http://{self.options.host}:{int(port or self.options.port_start)}/"

    def _workspace_runtime_candidates(
        self, workspace_id: str
    ) -> tuple[Path, ...]:
        safe_workspace_id = _safe_artifact_identifier(
            workspace_id, "workspace runtime id"
        )
        if len(safe_workspace_id.encode("utf-8")) > 180:
            raise ValueError("workspace runtime id is too long.")
        primary = self.runtime_root / safe_workspace_id
        fallback_stem = (
            ".claimed-v2-"
            + hashlib.sha256(
                safe_workspace_id.encode("utf-8")
            ).hexdigest()
        )
        fallbacks = tuple(
            self.runtime_root
            / (
                fallback_stem
                if index == 0
                else f"{fallback_stem}-{index:02d}"
            )
            for index in range(
                _WORKSPACE_RUNTIME_FALLBACK_CANDIDATE_LIMIT
            )
        )
        return (primary, *fallbacks)

    def _workspace_runtime_dir(self, workspace_id: str) -> Path:
        candidates = self._workspace_runtime_candidates(workspace_id)
        available: Optional[Path] = None
        claimed: Optional[Path] = None
        for candidate in candidates:
            if candidate.is_symlink():
                raise RuntimeError("Workspace runtime namespace must not be a symlink.")
            if candidate.exists() and not candidate.is_dir():
                raise RuntimeError("Workspace runtime namespace must be a directory.")
            if not candidate.exists():
                if available is None:
                    available = candidate
                continue
            marker = candidate / _WORKSPACE_RUNTIME_CLAIM_FILENAME
            if marker.is_symlink() or marker.exists():
                # A marker-bearing candidate must validate rather than being
                # skipped. Otherwise corruption or a copied foreign claim
                # could silently redirect ownership to a fresh directory.
                self._read_runtime_claim(workspace_id, candidate)
                if claimed is None:
                    claimed = candidate
                continue
            try:
                is_empty = next(candidate.iterdir(), None) is None
            except OSError as error:
                raise RuntimeError(
                    "Workspace runtime namespace cannot be inspected."
                ) from error
            if is_empty and available is None:
                # Empty state is the only recoverable pre-claim interruption.
                available = candidate
            # Nonempty unclaimed state is foreign. Leave it untouched and keep
            # searching for an existing claim or a fresh bounded sibling.
        if claimed is not None:
            return claimed
        if available is not None:
            return available
        raise RuntimeError(
            "Workspace runtime namespace allocation is exhausted by existing "
            "unclaimed state. OptPilot left every candidate untouched."
        )

    def _runtime_directories(
        self, *, workspace_prefix: str
    ) -> List[tuple[str, Path]]:
        """Return claimed current-contract directories for logical workspace ids."""

        matches: List[tuple[str, Path]] = []
        for record_path in self.runtime_root.glob("*/runtime.json"):
            try:
                raw = json.loads(record_path.read_text(encoding="utf-8"))
                workspace_id = str(raw.get("workspace_id") or "")
            except (OSError, AttributeError, json.JSONDecodeError):
                continue
            if not workspace_id.startswith(workspace_prefix):
                continue
            try:
                selected = self._workspace_runtime_dir(workspace_id)
            except (OSError, RuntimeError, ValueError):
                continue
            if selected == record_path.parent:
                matches.append((workspace_id, selected))
        return sorted(matches, key=lambda item: item[0])

    def _ensure_workspace_runtime_dir(self, workspace_id: str) -> Path:
        path = self._workspace_runtime_dir(workspace_id)
        created = False
        try:
            path.mkdir(parents=True, mode=0o700, exist_ok=False)
            created = True
        except FileExistsError:
            pass
        # Revalidate after creation so a pre-existing or concurrently replaced
        # symlink is never accepted as provider-owned runtime storage.
        path = self._workspace_runtime_dir(workspace_id)
        claim_path = path / _WORKSPACE_RUNTIME_CLAIM_FILENAME
        if created:
            self._create_runtime_claim(workspace_id, path)
        elif not claim_path.exists():
            # An empty directory is an interrupted pre-claim creation and can
            # be claimed.  Anything else is legacy, copied, or foreign state;
            # never adopt it by manufacturing a new marker.
            if any(path.iterdir()):
                raise WorkspaceRuntimeStorageIdentityChanged(
                    workspace_id=workspace_id,
                    runtime_path=path,
                )
            self._create_runtime_claim(workspace_id, path)
        claim = self._read_runtime_claim(workspace_id, path)
        self._attach_runtime_directory(workspace_id, path, claim)
        return path

    def _record_path(self, workspace_id: str) -> Path:
        return self._workspace_runtime_dir(workspace_id) / "runtime.json"

    def _read_record(self, workspace_id: str) -> JsonDict:
        path = self._record_path(workspace_id)
        if not path.exists():
            return {}
        runtime_path = path.parent
        claim = self._read_runtime_claim(workspace_id, runtime_path)
        claim_digest = request_digest(claim)
        self._attach_runtime_directory(workspace_id, runtime_path, claim)
        if path.is_symlink():
            raise RuntimeError("Workspace runtime record must not be a symlink.")
        if not path.is_file():
            raise RuntimeError("Workspace runtime record must be a regular file.")
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError) as error:
            raise RuntimeError("Workspace runtime record is unreadable.") from error
        if not isinstance(payload, dict):
            raise RuntimeError("Workspace runtime record must be an object.")
        if (
            payload.get("schema") != _WORKSPACE_RUNTIME_RECORD_SCHEMA
            or payload.get("workspace_id") != workspace_id
            or payload.get("runtime_claim_digest") != claim_digest
        ):
            raise WorkspaceRuntimeStorageIdentityChanged(
                workspace_id=workspace_id,
                runtime_path=runtime_path,
            )
        return payload

    def _write_record(self, workspace_id: str, record: JsonDict) -> None:
        path = self._record_path(workspace_id)
        runtime_dir = self._ensure_workspace_runtime_dir(workspace_id)
        if path.is_symlink():
            raise RuntimeError("Workspace runtime record must not be a symlink.")
        claim = self._read_runtime_claim(workspace_id, runtime_dir)
        self._attach_runtime_directory(workspace_id, runtime_dir, claim)
        payload = dict(record)
        payload.update(
            {
                "schema": _WORKSPACE_RUNTIME_RECORD_SCHEMA,
                "workspace_id": workspace_id,
                "runtime_claim_digest": request_digest(claim),
            }
        )
        _atomic_write_text(path, json.dumps(payload, indent=2, sort_keys=True) + "\n")

    def _create_runtime_claim(self, workspace_id: str, runtime_path: Path) -> None:
        claim = {
            "schema": _WORKSPACE_RUNTIME_CLAIM_SCHEMA,
            "workspace_id": workspace_id,
            "claim_nonce": uuid.uuid4().hex + uuid.uuid4().hex,
        }
        payload = (
            json.dumps(claim, sort_keys=True, separators=(",", ":")) + "\n"
        ).encode("utf-8")
        directory_flags = (
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        file_flags = (
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        directory_fd = os.open(runtime_path, directory_flags)
        marker_fd: Optional[int] = None
        try:
            try:
                marker_fd = os.open(
                    _WORKSPACE_RUNTIME_CLAIM_FILENAME,
                    file_flags,
                    0o400,
                    dir_fd=directory_fd,
                )
            except FileExistsError:
                return
            written = 0
            while written < len(payload):
                count = os.write(marker_fd, payload[written:])
                if count <= 0:  # pragma: no cover - defensive OS boundary
                    raise OSError("Workspace runtime claim write made no progress.")
                written += count
            os.fchmod(marker_fd, 0o400)
            os.fsync(marker_fd)
            os.fsync(directory_fd)
        finally:
            if marker_fd is not None:
                os.close(marker_fd)
            os.close(directory_fd)

    def _read_runtime_claim(
        self, workspace_id: str, runtime_path: Path
    ) -> JsonDict:
        claim_path = runtime_path / _WORKSPACE_RUNTIME_CLAIM_FILENAME
        flags = (
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        descriptor: Optional[int] = None
        try:
            descriptor = os.open(claim_path, flags)
            opened = os.fstat(descriptor)
            if (
                not stat.S_ISREG(opened.st_mode)
                or stat.S_IMODE(opened.st_mode) & 0o377
                or (hasattr(os, "geteuid") and opened.st_uid != os.geteuid())
            ):
                raise ValueError("claim marker permissions or type are unsafe")
            chunks: List[bytes] = []
            remaining = _WORKSPACE_RUNTIME_CLAIM_MAX_BYTES + 1
            while remaining:
                chunk = os.read(descriptor, min(remaining, 4096))
                if not chunk:
                    break
                chunks.append(chunk)
                remaining -= len(chunk)
            payload_bytes = b"".join(chunks)
            if len(payload_bytes) > _WORKSPACE_RUNTIME_CLAIM_MAX_BYTES:
                raise ValueError("claim marker is too large")
            linked = os.stat(claim_path, follow_symlinks=False)
            if (linked.st_dev, linked.st_ino) != (opened.st_dev, opened.st_ino):
                raise ValueError("claim marker changed while it was read")
            claim = json.loads(payload_bytes.decode("utf-8"))
            if (
                not isinstance(claim, dict)
                or set(claim) != {"schema", "workspace_id", "claim_nonce"}
                or claim.get("schema") != _WORKSPACE_RUNTIME_CLAIM_SCHEMA
                or claim.get("workspace_id") != workspace_id
                or not isinstance(claim.get("claim_nonce"), str)
                or len(claim["claim_nonce"]) != 64
                or any(character not in "0123456789abcdef" for character in claim["claim_nonce"])
            ):
                raise ValueError("claim marker is invalid")
            return claim
        except (OSError, UnicodeDecodeError, json.JSONDecodeError, ValueError) as error:
            changed = WorkspaceRuntimeStorageIdentityChanged(
                workspace_id=workspace_id,
                runtime_path=runtime_path,
            )
            add_exception_note(changed, f"runtime claim validation failed: {error}")
            raise changed from error
        finally:
            if descriptor is not None:
                os.close(descriptor)

    def _attach_runtime_directory(
        self, workspace_id: str, runtime_path: Path, claim: Mapping[str, Any]
    ) -> tuple[int, int]:
        linked = self._observe_runtime_directory(runtime_path)
        if not stat.S_ISDIR(linked.st_mode):
            raise WorkspaceRuntimeStorageIdentityChanged(
                workspace_id=workspace_id,
                runtime_path=runtime_path,
            )
        claim_digest = request_digest(dict(claim))
        identity = (linked.st_dev, linked.st_ino)
        with self._runtime_attachment_lock:
            attached = self._runtime_attachments.get(workspace_id)
            if attached is not None and attached != (
                claim_digest,
                identity[0],
                identity[1],
            ):
                raise WorkspaceRuntimeStorageIdentityChanged(
                    workspace_id=workspace_id,
                    runtime_path=runtime_path,
                )
            self._runtime_attachments[workspace_id] = (
                claim_digest,
                identity[0],
                identity[1],
            )
        return identity

    @staticmethod
    def _observe_runtime_directory(runtime_path: Path) -> os.stat_result:
        """Observe one live attachment; this value is intentionally not persisted."""

        return os.stat(runtime_path, follow_symlinks=False)

    def _container_name(self, workspace_id: str) -> str:
        safe_workspace_id = _safe_artifact_identifier(
            workspace_id, "workspace runtime id"
        )
        suffix = "".join(
            ch.lower() if ch.isascii() and ch.isalnum() else "-" for ch in workspace_id
        ).strip("-")
        if not suffix:
            suffix = "workspace"
        identity = hashlib.sha256(safe_workspace_id.encode("utf-8")).hexdigest()[:16]
        return f"optpilot-ws-{suffix[:30]}-{identity}"

    def _open_runtime_namespace(
        self, workspace_id: str
    ) -> tuple[int, int, tuple[int, int]]:
        safe_workspace_id = _safe_artifact_identifier(
            workspace_id, "workspace runtime id"
        )
        directory_flags = (
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        parent_fd = os.open(self.runtime_root, directory_flags)
        storage_name = self._workspace_runtime_dir(workspace_id).name
        try:
            runtime_fd = os.open(storage_name, directory_flags, dir_fd=parent_fd)
        except BaseException:
            os.close(parent_fd)
            raise
        info = os.fstat(runtime_fd)
        if not stat.S_ISDIR(info.st_mode):
            os.close(runtime_fd)
            os.close(parent_fd)
            raise RuntimeError("Workspace runtime namespace is not a directory.")
        return parent_fd, runtime_fd, (info.st_dev, info.st_ino)

    def _container_executable(self) -> Optional[str]:
        if self.options.executable:
            path = Path(self.options.executable).expanduser()
            if path.exists() and path.is_file():
                return str(path.resolve())
            return shutil.which(self.options.executable)
        return shutil.which("docker") or shutil.which("podman")

    def _require_container_executable(self) -> str:
        executable = self._container_executable()
        if not executable:
            raise RuntimeError(
                "No Docker/Podman-compatible executable found for workspace runtime."
            )
        return executable

    def _container_running(self, container_name: str) -> bool:
        executable = self._container_executable()
        if not executable or not container_name:
            return False
        completed = subprocess.run(
            [executable, "inspect", "-f", "{{.State.Running}}", container_name],
            capture_output=True,
            text=True,
            timeout=5,
            check=False,
        )
        return completed.returncode == 0 and completed.stdout.strip().lower() == "true"

    def _remove_container(self, container_name: str) -> JsonDict:
        executable = self._container_executable()
        if not container_name:
            return {
                "container_name": "",
                "terminal_confirmed": True,
                "state": "absent",
            }
        if not executable:
            return {
                "container_name": container_name,
                "terminal_confirmed": False,
                "state": "unknown",
                "error": "container_engine_unavailable",
            }
        try:
            daemon = subprocess.run(
                [executable, "info"],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            removed = subprocess.run(
                [executable, "rm", "-f", container_name],
                capture_output=True,
                text=True,
                timeout=15,
                check=False,
            )
            inspected = subprocess.run(
                [executable, "inspect", "-f", "{{.State.Running}}", container_name],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            listed = subprocess.run(
                [
                    executable,
                    "ps",
                    "-a",
                    "--filter",
                    f"name=^/{container_name}$",
                    "--format",
                    "{{.Names}}",
                ],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
        except Exception as error:
            return {
                "container_name": container_name,
                "terminal_confirmed": False,
                "state": "unknown",
                "error": type(error).__name__,
            }
        daemon_ready = daemon.returncode == 0
        if inspected.returncode == 0:
            running = inspected.stdout.strip().lower() == "true"
            terminal_confirmed = daemon_ready and not running
            state = "running" if running else "stopped"
        else:
            listed_names = {
                item.strip() for item in listed.stdout.splitlines() if item.strip()
            }
            absent = removed.returncode == 0 or (
                listed.returncode == 0 and container_name not in listed_names
            )
            terminal_confirmed = daemon_ready and absent
            state = "absent" if terminal_confirmed else "unknown"
        result: JsonDict = {
            "container_name": container_name,
            "terminal_confirmed": terminal_confirmed,
            "state": state,
            "remove_returncode": removed.returncode,
        }
        if not terminal_confirmed:
            result["error"] = "container_terminal_state_unconfirmed"
        return result


def _remove_workspace_runtime_contents(
    directory_fd: int, *, expected_device: int
) -> None:
    """Remove one terminal runtime through its already-authorized descriptor."""

    current = os.fstat(directory_fd)
    if not stat.S_ISDIR(current.st_mode) or current.st_dev != expected_device:
        raise RuntimeError("Workspace runtime cleanup crossed a filesystem boundary.")
    os.fchmod(directory_fd, 0o700)
    for name in sorted(os.listdir(directory_fd)):
        linked = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if linked.st_dev != expected_device:
            raise RuntimeError(
                "Workspace runtime cleanup encountered an external mount."
            )
        if stat.S_ISDIR(linked.st_mode):
            flags = (
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0)
            )
            child_fd = os.open(name, flags, dir_fd=directory_fd)
            try:
                opened = os.fstat(child_fd)
                if (opened.st_dev, opened.st_ino) != (
                    linked.st_dev,
                    linked.st_ino,
                ):
                    raise RuntimeError(
                        "Workspace runtime directory changed during cleanup."
                    )
                _remove_workspace_runtime_contents(
                    child_fd, expected_device=expected_device
                )
                current_link = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                if (current_link.st_dev, current_link.st_ino) != (
                    opened.st_dev,
                    opened.st_ino,
                ):
                    raise RuntimeError(
                        "Workspace runtime directory changed during cleanup."
                    )
                os.rmdir(name, dir_fd=directory_fd)
            finally:
                os.close(child_fd)
        else:
            # Unlinking through the directory descriptor never follows a
            # symlink, FIFO, socket, device node, or external hardlink.
            os.unlink(name, dir_fd=directory_fd)
    os.fsync(directory_fd)


class UiState:
    def __init__(
        self,
        *,
        cwd: Path,
        catalog_roots: List[Path],
        run_roots: List[Path],
        realm_runtime: Optional[LocalRealmRuntime] = None,
        code_server: Optional[CodeServerOptions] = None,
        workspace_runtime: Optional[WorkspaceRuntimeOptions] = None,
        runtime_supervisor_claim: Optional[StudioRuntimeSupervisorClaim] = None,
        catalog_refresh_ttl_seconds: float = 0.0,
        agent_tick_interval_seconds: float = 0.0,
    ):
        self.cwd = cwd.resolve()
        # Off unless asked for: hundreds of tests build a UiState directly and
        # must not each leak a polling thread. run_ui opts in.
        self.agent_tick_interval_seconds = max(0.0, float(agent_tick_interval_seconds))
        self._runtime_supervisor_claim = runtime_supervisor_claim
        if runtime_supervisor_claim is not None:
            runtime_supervisor_claim.assert_active_for(self.cwd)
        # An operator who names catalog roots means exactly those. Adding the
        # person's own packages folder on top would quietly widen a deliberate
        # choice -- and did, until a test that names its roots started seeing
        # whatever happened to be installed on the machine.
        self.catalog_roots_are_explicit = bool(catalog_roots)
        self.catalog_roots = (
            _expand_catalog_roots(catalog_roots)
            if catalog_roots
            else _default_catalog_roots(self.cwd)
        )
        self._configured_catalog_source_roots: Dict[str, Path] = {
            _configured_catalog_source_id(root): root for root in self.catalog_roots
        }
        self.run_roots = _dedupe_paths(run_roots or _default_run_roots(self.cwd))
        self._realm_catalog_projections: Dict[str, JsonDict] = {}
        self._realm_catalog_package_ids: Dict[Path, str] = {}
        self._catalog_workspace_projections: Dict[str, CatalogSourceProjection] = {}
        self._catalog_projection_lock = threading.RLock()
        # Catalog and compatibility requests start together.  Only one may
        # perform the expensive package walk; followers reuse its completed
        # cache instead of duplicating the same filesystem scan.
        self._catalog_index_build_lock = threading.Lock()
        # Read-path debounce state, guarded by _catalog_projection_lock: the
        # monotonic stamp of the last complete projection refresh and the last
        # built catalog index payload.  Both stay unused while the TTL is 0.
        self.catalog_refresh_ttl_seconds = max(
            0.0, float(catalog_refresh_ttl_seconds)
        )
        self._catalog_projections_refreshed_monotonic: Optional[float] = None
        self._catalog_index_cache: Optional[tuple[float, JsonDict]] = None
        #: Compatibility pairs for one exact catalog index, same reuse window.
        self._compatibility_cache: Optional[tuple[JsonDict, float, JsonDict]] = None
        # Study saves write into persistent managed checkouts before advancing
        # their retained heads.  Keyed critical sections keep that checkout
        # write, its optimistic revision fence, and the saved-draft record one
        # process-local unit without serializing unrelated Study workspaces.
        self._study_draft_mutation_locks: Dict[str, _StudyDraftMutationLock] = {}
        self._study_draft_mutation_locks_guard = threading.Lock()
        # Production injects one server-owned runtime from ``run_ui``.  Keeping
        # this optional preserves cheap, isolated construction for authoring-
        # only tests and helpers without silently opening a second authority.
        self.realm_runtime = realm_runtime
        self.interface_launches: Dict[str, UiLaunchJob] = {}
        self.jobs_dir = self.cwd / ".optpilot-ui" / "jobs"
        self.jobs_dir.mkdir(parents=True, exist_ok=True)
        self.sessions_dir = self.cwd / ".optpilot-ui" / "sessions"
        self.sessions_dir.mkdir(parents=True, exist_ok=True)
        self.workspaces_dir = self.cwd / ".optpilot-ui" / "workspaces"
        self.workspaces_dir.mkdir(parents=True, exist_ok=True)
        self._workspace_index_lock = threading.RLock()
        legacy_workspace_index_path = self.workspaces_dir / "index.json"
        self.workspace_index_path = (
            studio_project_state_directory(
                self.cwd,
                authority_root=self.realm_runtime.root,
            )
            / "workspace-index.json"
            if self.realm_runtime is not None
            else legacy_workspace_index_path
        )
        _prepare_workspace_index_storage(
            self,
            legacy_path=legacy_workspace_index_path,
        )
        coordination_path = (
            prepare_coordination_database(
                self.cwd,
                authority_root=self.realm_runtime.root,
            )
            if self.realm_runtime is not None
            else coordination_database_path(self.cwd)
        )
        self.coordination = StudioCoordinationStore(coordination_path)
        if self.realm_runtime is not None:
            runtime_namespace = request_digest(
                {
                    "schema": "optpilot.studio-runtime-namespace.v1",
                    "coordination_instance_id": self.coordination.instance_id,
                    "studio_root": str(self.cwd),
                }
            )
            self.runtime_dir = prepare_private_directory(
                self.realm_runtime.root
                / "runtime-cache"
                / "studio-workspace-runtimes"
                / runtime_namespace
            )
            runtime_authority_root = self.realm_runtime.root
        else:
            # Realm-less construction exists only for isolated helpers and
            # tests. Production runtime/output state belongs to the OS-local
            # Realm, never to a user's potentially synchronized checkout.
            self.runtime_dir = self.cwd / ".optpilot-ui" / "runtime"
            self.runtime_dir.mkdir(parents=True, exist_ok=True)
            runtime_authority_root = self.cwd
        self.prepared_runtime_cache_dir = (
            self.realm_runtime.root / "runtime-cache" / "studio-prepared-runtimes"
            if self.realm_runtime is not None
            else self.cwd / ".optpilot-ui" / "prepared-runtimes"
        )
        self.prepared_runtime_cache = PreparedRuntimeCache(
            self.prepared_runtime_cache_dir
        )
        self.agent_sessions_dir = self.cwd / ".optpilot-ui" / "agent_sessions"
        self.agent_sessions_dir.mkdir(parents=True, exist_ok=True)
        self._agent_session_index_lock = threading.RLock()
        # The Run-list response is rebuilt only when a cheap fingerprint over
        # the run catalog, study-launch job records, and this process's own
        # mutation counter changes.  Rebuilding it on every poll re-reads one
        # full snapshot per Run, which alone kept an idle Studio near one CPU.
        self._runs_response_cache_lock = threading.Lock()
        self._runs_response_cache: Optional[JsonDict] = None
        self._runs_mutation_generation = 0
        self._runtime_gc_lock = threading.Lock()
        self._runtime_gc_last: Optional[tuple[float, JsonDict]] = None
        self.code_server_dir = self.cwd / ".optpilot-ui" / "code-server"
        self.code_server_dir.mkdir(parents=True, exist_ok=True)
        self.settings_path = self.cwd / ".optpilot-ui" / "settings.json"
        self._settings_lock = threading.RLock()
        self.agent_adapter = OpenHandsAdapter(
            _openhands_config_from_settings(_read_ui_settings(self))
        )
        code_server_options = code_server or CodeServerOptions()
        if not code_server_options.executable:
            local_code_server = _local_code_server_executable(self.cwd)
            if local_code_server.exists():
                code_server_options.executable = str(local_code_server)
        self.code_server = CodeServerState(code_server_options)
        # Catalog source views are intentionally hidden and short-lived, but a
        # slow image preparation must not let list pruning reclaim the source
        # while Code Server is starting. Counts include lock waiters, which
        # both fences the reference and serializes starts for the same id.
        self._code_workspace_start_locks: Dict[str, threading.Lock] = {}
        self._code_workspace_start_counts: Dict[str, int] = {}
        self._code_workspace_start_guard = threading.Lock()
        runtime_options = workspace_runtime or WorkspaceRuntimeOptions.from_env()
        runtime_options.host = runtime_options.host or code_server_options.host
        if (
            runtime_options.port_start == WorkspaceRuntimeOptions.port_start
            and code_server_options.port != CodeServerOptions.port
        ):
            runtime_options.port_start = code_server_options.port
        runtime_options.auth = runtime_options.auth or code_server_options.auth
        runtime_options.password = (
            runtime_options.password or code_server_options.password
        )
        self.workspace_runtime = WorkspaceRuntimeManager(
            studio_root=self.cwd,
            runtime_root=self.runtime_dir,
            options=runtime_options,
            prepared_runtime_cache_root=self.prepared_runtime_cache.root,
            runtime_authority_root=runtime_authority_root,
        )
        if self._runtime_supervisor_claim is not None:
            self._cleanup_orphaned_interface_runtimes()
            self._cleanup_orphaned_resource_action_runtimes()
        presentation_port_start = max(
            19000, int(runtime_options.port_start) + 1000
        )
        if presentation_port_start > 64536:
            # Keep a full 1,000-port allocation window when the workspace
            # runtime starts near the end of the TCP port range.
            presentation_port_start = 19000
        self.presentation_broker = WebPresentationBroker(
            host=runtime_options.host or "127.0.0.1",
            port_start=presentation_port_start,
        )
        self.active_code_workspace_id = ""
        self.agent_session_locks: Dict[str, threading.Lock] = {}
        self._agent_session_locks_lock = threading.Lock()
        # Opaque Assistant selection handles are process-local and bound to
        # the Studio session that minted them.  Canonical run data is never
        # stored here; every message re-resolves its exact Realm head.
        self.assistant_run_selections: Dict[str, AssistantRunSelectionRecord] = {}
        # The browser sees only these random process-local coordinates.  The
        # exact SelectionRef and content authority remain server-side and are
        # revalidated for every list/read operation.
        self.selection_content_sessions: Dict[str, SelectionContentSessionRecord] = {}
        self.selection_content_views: Dict[str, SelectionContentViewRecord] = {}
        # This map is only an in-process scheduling guard.  Durable Operator
        # Job state and recovery authority live in Realm, never in UiState.
        self._operator_job_threads: Dict[str, threading.Thread] = {}
        # Study launches have the same ownership rule: this map only prevents
        # duplicate pre-handoff dispatch. Canonical run execution moves to the
        # shared run-id guard below as soon as the durable handoff exists.
        self._study_launch_threads: Dict[str, threading.Thread] = {}
        # Preparing exact Study inputs happens before the durable Operator Job
        # exists.  ActionIntentRecord remains the durable authority; this map
        # only prevents duplicate local workers for the same browser request.
        self._study_preparation_threads: Dict[str, threading.Thread] = {}
        # One process-local duplicate guard serves every canonical run origin.
        # Core owns plans, controller fences, recovery, and terminal state.
        self._run_execution_threads: Dict[str, threading.Thread] = {}
        # Headless resource actions (F4) are local operations with no durable
        # job record yet; results live for the Studio process lifetime only.
        self._resource_action_runs: Dict[str, JsonDict] = {}
        self._resource_action_threads: Dict[str, threading.Thread] = {}
        self._agent_tick_threads: Dict[str, threading.Thread] = {}
        #: session id -> (next attempt monotonic, current delay). A session
        #: that never progresses backs off to one sync every few minutes
        #: instead of hammering a dead conversation forever.
        self._agent_tick_backoff: Dict[str, tuple[float, float]] = {}
        # Closing Studio stops new process-local scheduling and joins these
        # tracked reconcilers before coordination/Realm storage is closed.
        self._background_execution_closing = threading.Event()
        self._lock = threading.Lock()
        _reconcile_visible_study_launch_preparations(self)
        _reconcile_visible_study_launches(self)
        _reconcile_visible_operator_jobs(self)
        _reconcile_visible_run_executions(self)
        _start_agent_session_tick(self)
        # The person's packages must be launchable, not merely listed. Costs
        # one cheap lookup each once they are published; never fatal.
        try:
            _register_user_packages(self)
        except Exception as error:  # pragma: no cover - defensive
            print(
                "OptPilot could not set up its example packages: "
                f"{type(error).__name__}: {error}",
                file=sys.stderr,
            )

    def launch_study(
        self,
        study_path: Optional[Path] = None,
        *,
        catalog_entry: Any = None,
        workspace_id: Optional[str] = None,
        study_relative_path: Optional[str] = None,
        expected_workspace_revision: Optional[int] = None,
        study_name: Optional[str] = None,
        environment_id: Optional[str] = None,
        operation_id: Optional[str] = None,
        method_request_timeout_seconds: float | None = None,
        launch_inputs: Optional[Mapping[str, Any]] = None,
    ) -> StudyLaunchView:
        selected_operation_id = operation_id or new_local_study_operation_id()
        method_request_timeout = (
            None
            if method_request_timeout_seconds is None
            else _canonical_method_request_timeout_seconds(
                method_request_timeout_seconds
            )
        )
        package_selection: SelectionRef | None = None
        selected_study_relative_path: str | None = None
        selected_display_name: str | None = None
        if workspace_id is not None:
            if catalog_entry is not None or study_path is not None:
                raise ValueError(
                    "Use a catalog study ref, a managed workspace study, or a "
                    "configured study path, not more than one."
                )
            relative = _portable_relative_path(
                study_relative_path, "study_relative_path"
            )
            if (
                isinstance(expected_workspace_revision, bool)
                or not isinstance(expected_workspace_revision, int)
                or expected_workspace_revision <= 0
            ):
                raise ValueError(
                    "expected_workspace_revision is required for a managed "
                    "workspace study launch."
                )
            workspace = _require_ui_workspace(self, str(workspace_id))
            if workspace.get("ownership") != "realm-managed":
                raise ValueError(
                    "Study Builder launches require a Realm-managed workspace."
                )
            if workspace.get("reopen_required"):
                workspace = _reopen_managed_workspace(
                    self,
                    str(workspace_id),
                    {
                        "expected_workspace_revision": expected_workspace_revision,
                    },
                )
            committed = _commit_managed_workspace(
                self,
                str(workspace_id),
                {"expected_workspace_revision": expected_workspace_revision},
                operation_id=(
                    f"{selected_operation_id}/commit-study-workspace"
                ),
            )
            workspace = committed["workspace"]
            committed_revision = int(workspace["realm_workspace_revision"])
            runtime = _require_realm_runtime(self)
            selection = runtime.ledger.mint_workspace_selection(
                actor_principal_id=runtime.actor_principal_id,
                workspace_id=str(workspace_id),
                expected_workspace_revision=committed_revision,
            )
            package_selection = selection
            selected_study_relative_path = relative
            selected_display_name = study_name or PurePosixPath(relative).stem

        selected_catalog = (
            _catalog_entry_ref_selection(self, "study", catalog_entry)
            if catalog_entry is not None and package_selection is None
            else None
        )
        if selected_catalog is not None:
            package_selection = selected_catalog.selection
            selected_study_relative_path = selected_catalog.relative_path
            selected_display_name = study_name or selected_catalog.entry_ref.entry_id

        source_projection = None
        if package_selection is None and catalog_entry is not None:
            study_path = _resolve_catalog_identifier(self, "study", catalog_entry)
        if package_selection is None and study_path is None:
            raise ValueError("study_path or catalog_entry is required.")
        if package_selection is None:
            assert study_path is not None
            study_path = study_path.resolve(strict=True)
            source_projection = _borrow_realm_catalog_source_projection(
                self,
                study_path,
                consumer_kind="catalog-study-launch",
                consumer_metadata={"component_kind": "study"},
            )
            if source_projection is not None:
                study_path = source_projection.source_path
                package_root = source_projection.root_path
            else:
                package_root = _configured_study_package_root(self, study_path)
        try:
            runtime = _require_realm_runtime(self)
            execution_profile = (
                None
                if method_request_timeout is None
                else RunExecutionProfile(
                    method_request_timeout_seconds=method_request_timeout
                )
            )
            if package_selection is not None:
                assert selected_study_relative_path is not None
                identities = local_study_operation_identities(selected_operation_id)
                preparation = runtime.retained_study_service.prepare_selected_package(
                    operation_id=selected_operation_id,
                    actor_principal_id=runtime.actor_principal_id,
                    package_selection=package_selection,
                    study_config_relative_path=selected_study_relative_path,
                    source_owner_id=identities["source_owner_id"],
                    study_definition_owner_id=identities["definition_owner_id"],
                    launch_inputs=launch_inputs,
                )
                method_environment_binding = _studio_method_environment_binding(
                    self,
                    method_environment_names(
                        preparation.study_definition.manifest.run_definition
                    ),
                )
                launch = runtime.study_launches.plan_definition(
                    operation_id=selected_operation_id,
                    preparation=preparation,
                    display_name=selected_display_name,
                    execution_profile=execution_profile,
                    method_environment_binding=method_environment_binding,
                )
            else:
                assert study_path is not None
                validation = _validate_study(study_path, state=self)
                _require_study_launchable(validation, launch_inputs=launch_inputs)
                method_environment_binding = _studio_method_environment_binding(
                    self,
                    [
                        item.get("name")
                        for item in validation.get("runtime_environment", {}).get(
                            "requirements", []
                        )
                        if isinstance(item, Mapping)
                    ],
                )
                launch = runtime.study_launches.plan_local_package(
                    operation_id=selected_operation_id,
                    package_root=package_root,
                    study_config_path=study_path,
                    display_name=(
                        study_name or str(validation.get("name") or "") or None
                    ),
                    execution_profile=execution_profile,
                    method_environment_binding=method_environment_binding,
                    launch_inputs=launch_inputs,
                )
        finally:
            if source_projection is not None:
                source_projection.close()
        # Environment identity is compiled from the retained definition. The
        # caller-provided value remains an ignored display-era argument until
        # the Studio call sites are simplified.
        _ = environment_id
        _schedule_study_launch_execution(self, launch_id=launch.launch_id)
        return launch

    def stop_job(
        self, job_id: str, *, operation_id: Optional[str] = None
    ) -> JsonDict:
        runtime = _require_realm_runtime(self)
        stopped = runtime.study_launches.request_cancel(
            operation_id=(
                operation_id
                or f"studio/study-launch/{job_id}/cancel/{uuid.uuid4().hex}"
            ),
            launch_id=job_id,
            reason_code="user_cancelled",
        )
        return stopped.to_dict()

    def code_server_status(self) -> JsonDict:
        workspace = self._active_code_workspace()
        return self.workspace_runtime.global_status(active_workspace=workspace)

    def start_code_server(self, folder: Optional[Path] = None) -> JsonDict:
        workspace_root = _safe_code_server_folder(self, folder or self.cwd)
        workspace = self._ensure_code_workspace(workspace_root)
        return self.start_workspace_code_server(workspace)

    @contextmanager
    def _code_workspace_start_scope(self, workspace_id: str) -> Iterator[None]:
        with self._code_workspace_start_guard:
            lock = self._code_workspace_start_locks.setdefault(
                workspace_id, threading.Lock()
            )
            self._code_workspace_start_counts[workspace_id] = (
                self._code_workspace_start_counts.get(workspace_id, 0) + 1
            )
        try:
            with lock:
                yield
        finally:
            with self._code_workspace_start_guard:
                remaining = self._code_workspace_start_counts[workspace_id] - 1
                if remaining:
                    self._code_workspace_start_counts[workspace_id] = remaining
                else:
                    self._code_workspace_start_counts.pop(workspace_id, None)
                    self._code_workspace_start_locks.pop(workspace_id, None)

    def _code_workspace_start_in_progress(self, workspace_id: str) -> bool:
        with self._code_workspace_start_guard:
            return self._code_workspace_start_counts.get(workspace_id, 0) > 0

    def start_workspace_code_server(self, workspace: Mapping[str, Any]) -> JsonDict:
        """Start Code Server from one already-authorized Workspace descriptor.

        Workspace-scoped and exact Catalog actions have already resolved their
        logical source before reaching this boundary.  Preserve that identity
        instead of looking the source up again by its provider-owned path; a
        second path lookup can both lose read-only mount policy and reclaim the
        short-lived Catalog support reference that authorized the path.
        """

        workspace = dict(workspace)
        workspace_id = str(workspace.get("id") or "")
        if not workspace_id:
            raise ValueError("Workspace Code Server source is missing its identity.")
        with self._code_workspace_start_scope(workspace_id):
            root_text = str(workspace.get("root") or "")
            if not root_text:
                raise ValueError("Workspace Code Server source is not open.")
            workspace_root = _safe_code_server_folder(self, Path(root_text))
            workspace["root"] = str(workspace_root)
            status = self.workspace_runtime.start_code_server(
                workspace, image=_workspace_package_image(self, workspace)
            )
            self.active_code_workspace_id = workspace_id
            self.code_server.started_at = time.time()
            self.code_server.workspace_root = workspace_root
            self.code_server.stdout_path = (
                Path(str(status.get("stdout_log") or ""))
                if status.get("stdout_log")
                else None
            )
            self.code_server.stderr_path = (
                Path(str(status.get("stderr_log") or ""))
                if status.get("stderr_log")
                else None
            )
            return status

    def _prepare_code_server_profile(self) -> tuple[Path, Path]:
        user_data_dir = self.code_server_dir / "user-data"
        extensions_dir = self.code_server_dir / "extensions"
        _prepare_code_server_profile(user_data_dir, extensions_dir)
        return user_data_dir, extensions_dir

    def stop_code_server(self) -> JsonDict:
        self.active_code_workspace_id = ""
        self.code_server.workspace_root = None
        return self.code_server_status()

    def code_server_open_url(self, folder: Optional[Path] = None) -> JsonDict:
        return self.start_code_server(
            folder or self.code_server.workspace_root or self.cwd
        )

    def workspace_preview_open(
        self,
        folder: Optional[Path],
        port: int,
        *,
        extra_ports: Optional[Iterable[int]] = None,
    ) -> JsonDict:
        if port < 1 or port > 65535:
            raise ValueError("Preview port must be between 1 and 65535.")
        code_server = self.start_code_server(
            folder or self.code_server.workspace_root or self.cwd
        )
        workspace = self._active_code_workspace()
        if workspace is None:
            raise RuntimeError(
                "Code Server did not retain its workspace runtime descriptor."
            )
        return self._workspace_preview_payload(
            workspace,
            code_server,
            port,
            extra_ports=extra_ports,
        )

    def transient_workspace_preview_open(
        self,
        workspace: JsonDict,
        port: int,
        *,
        extra_ports: Optional[Iterable[int]] = None,
        should_stop: Optional[Callable[[], bool]] = None,
    ) -> JsonDict:
        """Open Preview for an unregistered launch-scoped workspace descriptor."""

        if port < 1 or port > 65535:
            raise ValueError("Preview port must be between 1 and 65535.")
        preview_image = _workspace_package_image(self, workspace)
        code_server = (
            self.workspace_runtime.start_code_server(workspace, image=preview_image)
            if should_stop is None
            else self.workspace_runtime.start_code_server(
                workspace, image=preview_image, should_stop=should_stop
            )
        )
        _check_interface_launch_cancelled(should_stop)
        return self._workspace_preview_payload(
            workspace,
            code_server,
            port,
            extra_ports=extra_ports,
        )

    def _workspace_preview_payload(
        self,
        workspace: JsonDict,
        code_server: JsonDict,
        port: int,
        *,
        extra_ports: Optional[Iterable[int]] = None,
    ) -> JsonDict:
        workspace_id = str(code_server.get("workspace_id") or "")
        base_url = str(code_server.get("url") or "")
        if not base_url:
            parsed = urlparse(str(code_server.get("open_url") or ""))
            if parsed.scheme and parsed.netloc:
                base_url = f"{parsed.scheme}://{parsed.netloc}/"
        if not base_url:
            raise RuntimeError(
                "Code Server did not return a base URL for workspace preview."
            )
        target_base_url = f"{base_url.rstrip('/')}/proxy/{int(port)}"
        allowed_ports = _preview_allowed_ports(int(port), extra_ports or [])
        preview_proxy = self._workspace_preview_proxy(
            workspace_id,
            int(port),
            target_base_url,
            allowed_ports=allowed_ports,
            runtime_workspace=workspace,
        )
        return {
            "workspace_id": workspace_id,
            "folder": code_server.get("folder")
            or str(workspace.get("root") or self.cwd),
            "port": int(port),
            "preview_url": preview_proxy.preview_url,
            "proxy": "studio",
            "proxy_target": target_base_url + "/",
            "allowed_ports": list(allowed_ports),
            "code_server": code_server,
        }

    def _workspace_preview_proxy(
        self,
        workspace_id: str,
        port: int,
        target_base_url: str,
        *,
        allowed_ports: List[int],
        runtime_workspace: Optional[JsonDict] = None,
    ) -> WebPresentationLease:
        key = f"{workspace_id}:{int(port)}"
        code_server_base, separator, _tail = target_base_url.partition("/proxy/")
        if not separator:
            raise ValueError(
                "Workspace Preview target is not a Code Server proxy route."
            )
        routes = {
            logical_port: f"{code_server_base.rstrip('/')}/proxy/{logical_port}"
            for logical_port in allowed_ports
        }
        record = self.workspace_runtime._read_record(workspace_id)
        generation = request_digest(
            {
                "schema": "optpilot.workspace-presentation-generation.v1",
                "code_server_started_at": record.get("code_server_started_at"),
                "container_name": record.get("container_name"),
                "image": record.get("image"),
                "started_at": record.get("started_at"),
                "workspace_id": workspace_id,
            }
        )
        transient_workspace = (
            dict(runtime_workspace) if runtime_workspace is not None else None
        )

        def validate_owned_workspace_endpoint() -> None:
            workspace = transient_workspace or _workspace_by_id(self, workspace_id)
            if not workspace:
                raise RuntimeError("The workspace runtime descriptor no longer exists.")
            status = self.workspace_runtime.status(workspace)
            current_url = str(status.get("url") or "").rstrip("/")
            if not status.get(
                "container_running"
            ) or current_url != code_server_base.rstrip("/"):
                raise RuntimeError(
                    "The workspace runtime no longer owns this Preview endpoint."
                )

        endpoint = OwnedWebEndpoint(
            owner_kind="workspace-runtime",
            owner_id=workspace_id,
            generation=generation,
            access_policy="trusted-local-authoring",
            # code-server's /proxy/<port> WebSocket tunnel rejects browser
            # Origin values belonging to Studio's fresh presentation origin.
            # The outer broker has already authenticated that browser origin,
            # so omit Origin only on this trusted intermediary hop.
            websocket_origin_policy="omit",
            primary_port=port,
            routes=routes,
            validate=validate_owned_workspace_endpoint,
        )
        return self.presentation_broker.open(key=key, endpoint=endpoint)

    def _stop_workspace_preview_proxy(self, key: str) -> bool:
        return self.presentation_broker.close(key)

    def stop_workspace_preview_proxies(self) -> bool:
        return self.presentation_broker.close_all()

    def close_catalog_projections(self) -> None:
        """Release Studio's borrowed catalog views without touching catalog data."""

        with self._catalog_projection_lock:
            records = tuple(self._realm_catalog_projections.values())
            workspace_projections = tuple(self._catalog_workspace_projections.values())
            self._realm_catalog_projections.clear()
            self._realm_catalog_package_ids.clear()
            self._catalog_workspace_projections.clear()
            self._catalog_projections_refreshed_monotonic = None
            self._catalog_index_cache = None
        for record in records:
            projection = record.get("projection")
            if projection is not None:
                try:
                    projection.close()
                except Exception:
                    pass
        for projection in workspace_projections:
            try:
                projection.close()
            except Exception:
                pass

    def quiesce_background_execution(
        self,
        *,
        timeout_seconds: float = STUDIO_BACKGROUND_QUIESCENCE_TIMEOUT_SECONDS,
    ) -> bool:
        """Stop new scheduling and wait boundedly for tracked workers to unwind."""

        self._background_execution_closing.set()
        deadline = time.monotonic() + max(0.0, float(timeout_seconds))
        while True:
            current_thread = threading.current_thread()
            with self._lock:
                registries = (
                    getattr(self, "_study_preparation_threads", {}),
                    self._study_launch_threads,
                    self._run_execution_threads,
                    self._operator_job_threads,
                    getattr(self, "_agent_tick_threads", {}),
                )
                if any(
                    thread is current_thread
                    for registry in registries
                    for thread in registry.values()
                ):
                    return False
                threads = {
                    thread
                    for registry in registries
                    for thread in registry.values()
                    if thread.is_alive()
                }
            if not threads:
                return True
            for thread in threads:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return False
                thread.join(timeout=min(0.25, remaining))

    def close_coordination(
        self,
        *,
        timeout_seconds: float = STUDIO_BACKGROUND_QUIESCENCE_TIMEOUT_SECONDS,
        close_storage: bool = True,
    ) -> bool:
        quiesced = self.quiesce_background_execution(
            timeout_seconds=timeout_seconds
        )
        # Never close the durable intent database beneath a preparation worker
        # that is still unwinding.  The process-exit retention path will keep
        # the corresponding descriptors alive and startup reconciliation will
        # resume the exact request.
        if close_storage and quiesced:
            self.coordination.close()
        return quiesced

    def stop_transient_interface_launches(
        self, *, timeout_seconds: float = 30.0
    ) -> bool:
        """Request stop and prove every launch-owned thread has unwound.

        The one deadline covers stop publication, launch workers, output
        watchers, final settlement, and orphan reconciliation.  Slow provider
        cleanup continues only while Studio retains its Realm and supervisor
        descriptors; this method never reports quiescence merely because a
        worker published an in-function completion event.
        """

        deadline = time.monotonic() + max(0.0, float(timeout_seconds))
        with self._lock:
            jobs = [
                (launch_id, job)
                for launch_id, job in self.interface_launches.items()
                if job.launch_scope in {"catalog-transient", "workspace-transient"}
            ]
        for launch_id, job in jobs:
            job.output_watcher_stop.set()
            if job.status == "stopped":
                continue
            try:
                _request_interface_launch_stop(self, launch_id)
            except Exception:
                pass

        def join_before_deadline(thread: Optional[threading.Thread]) -> bool:
            if thread is None or not thread.is_alive():
                return True
            if thread is threading.current_thread():
                return False
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return False
            thread.join(timeout=remaining)
            return not thread.is_alive()

        # Include stopped jobs: a concurrent Stop request can publish the
        # terminal state just before its launch worker returns.
        for _launch_id, job in jobs:
            if not join_before_deadline(job.worker_thread):
                return False
        for _launch_id, job in jobs:
            if not join_before_deadline(job.output_watcher):
                return False
            for thread in tuple(job.output_action_threads.values()):
                if not join_before_deadline(thread):
                    return False

        if deadline - time.monotonic() <= 0:
            return False

        recovery_failed = threading.Event()

        def settle_and_reconcile() -> None:
            for launch_id, _job in jobs:
                with self._lock:
                    current = self.interface_launches.get(launch_id)
                    status = current.status if current is not None else ""
                if status not in {"stopping", "cleanup_pending"}:
                    continue
                try:
                    _settle_interface_launch(
                        self,
                        launch_id,
                        terminal_target="stopped",
                    )
                except Exception:
                    # This is durable cleanup debt, not permission to close
                    # storage under a still-running settlement frame.
                    pass
            try:
                self._cleanup_orphaned_interface_runtimes()
                self._cleanup_orphaned_resource_action_runtimes()
            except Exception:
                recovery_failed.set()

        settlement_thread = threading.Thread(
            target=settle_and_reconcile,
            name="optpilot-interface-shutdown-settlement",
            daemon=True,
        )
        settlement_thread.start()
        if not join_before_deadline(settlement_thread):
            return False
        if recovery_failed.is_set():
            return False

        # Settlement is allowed to leave durable cleanup debt, but it must not
        # leave another output watcher or launch worker alive.
        for _launch_id, job in jobs:
            if not join_before_deadline(job.worker_thread):
                return False
            if not join_before_deadline(job.output_watcher):
                return False
            for thread in tuple(job.output_action_threads.values()):
                if not join_before_deadline(thread):
                    return False
        return True

    def _cleanup_orphaned_resource_action_runtimes(self) -> None:
        """Remove per-run action copies whose run no longer exists.

        Each headless action on a realm-published resource runs in a
        writable per-run copy under a resource-action-copy-* runtime
        directory,
        deleted when the run settles. A crash between copy and settlement
        leaves the directory behind; this sweep removes any such directory
        not owned by a live action thread. These runtimes never submit
        containers, so deletion needs no engine.
        """

        runtime_directories = getattr(
            self.workspace_runtime, "_runtime_directories", None
        )
        items = (
            runtime_directories(workspace_prefix="resource-action-copy-")
            if callable(runtime_directories)
            else [
                (path.name, path)
                for path in self.runtime_dir.glob("resource-action-copy-*")
            ]
        )
        seen_ids = {runtime_id for runtime_id, _path in items}
        # Directories whose record write was interrupted carry no
        # runtime.json and are invisible to _runtime_directories; the claim
        # check inside deletion keeps foreign directories safe.
        recordless = [
            (path.name, path)
            for path in self.runtime_dir.glob("resource-action-copy-*")
            if path.name not in seen_ids
        ]
        for runtime_id, runtime_path in [*items, *recordless]:
            if runtime_path.parent != self.runtime_dir:
                continue
            try:
                record = self.workspace_runtime._read_record(runtime_id)
            except RuntimeError:
                continue
            request_id = str(record.get("request_id") or "")
            state_lock = getattr(self, "_lock", None)
            if request_id and state_lock is not None:
                with state_lock:
                    owner = self._resource_action_threads.get(request_id)
                if owner is not None and owner.is_alive():
                    continue
            _delete_resource_action_runtime(self, runtime_id)

    def _cleanup_orphaned_interface_runtimes(self) -> None:
        claim = self._runtime_supervisor_claim
        if claim is None:
            raise RuntimeError(
                "Orphan interface recovery requires the Studio runtime-supervisor claim."
            )
        claim.assert_active_for(self.cwd)
        service = _interface_output_service(self)
        runtime = self.realm_runtime
        reconciled_launch_ids: set[str] = set()
        runtime_directories = getattr(
            self.workspace_runtime, "_runtime_directories", None
        )
        orphan_builder_items = (
            runtime_directories(workspace_prefix="prepared-build-")
            if callable(runtime_directories)
            else [
                (path.name, path)
                for path in self.runtime_dir.glob("prepared-build-*")
            ]
        )
        for builder_id, runtime_path in orphan_builder_items:
            if runtime_path.parent != self.runtime_dir:
                continue
            runtime_is_symlink = runtime_path.is_symlink()
            try:
                record = (
                    {}
                    if runtime_is_symlink
                    else self.workspace_runtime._read_record(builder_id)
                )
            except RuntimeError:
                continue
            owner_launch_id = str(record.get("owner_launch_id") or "")
            if owner_launch_id:
                state_lock = getattr(self, "_lock", None)
                if state_lock is None:
                    owner = self.interface_launches.get(owner_launch_id)
                else:
                    with state_lock:
                        owner = self.interface_launches.get(owner_launch_id)
                if (
                    owner is not None
                    and builder_id in owner.prepared_runtime_builders
                ):
                    continue
            if runtime_is_symlink:
                removal = self.workspace_runtime._remove_container(
                    self.workspace_runtime._container_name(builder_id)
                )
                if removal.get("terminal_confirmed"):
                    try:
                        runtime_path.unlink()
                    except OSError:
                        pass
                continue
            workspace = {
                "id": builder_id,
                "root": str(record.get("workspace_root") or self.cwd),
                "source_type": "prepared-runtime-build",
                "mode": str(record.get("mode") or "read-only"),
            }
            try:
                _mark_prestart_interface_runtime_terminal(self, workspace)
                self.workspace_runtime.delete(builder_id)
            except Exception:
                # Keep the claimed namespace for the next supervised retry.
                continue

        orphan_runtime_items = (
            runtime_directories(workspace_prefix="interface-launch-")
            if callable(runtime_directories)
            else [
                (path.name, path)
                for path in self.runtime_dir.glob("interface-launch-*")
            ]
        )
        for workspace_id, runtime_path in orphan_runtime_items:
            if runtime_path.parent != self.runtime_dir:
                continue
            launch_id = workspace_id.removeprefix("interface-")
            reconciled_launch_ids.add(launch_id)
            # An in-memory job belongs to this process, even when Stop has
            # been requested. Only its quiesced worker may settle it; orphan
            # recovery must never tear resources out from under that frame.
            if launch_id in self.interface_launches:
                continue
            runtime_is_symlink = runtime_path.is_symlink()
            handle = None
            if service is not None:
                try:
                    handle = service.recover_session(launch_id=launch_id)
                except (RealmNotFound, RealmConflict):
                    handle = None

            try:
                record = (
                    {}
                    if runtime_is_symlink
                    else self.workspace_runtime._read_record(workspace_id)
                )
            except RuntimeError:
                # An untrusted or replaced namespace is not ours to stop,
                # capture from, or remove automatically.
                continue
            has_runtime_record = bool(
                not runtime_is_symlink
                and self.workspace_runtime._record_path(workspace_id).is_file()
            )
            terminal_confirmed = not has_runtime_record and not runtime_is_symlink
            if runtime_is_symlink:
                removal = self.workspace_runtime._remove_container(
                    self.workspace_runtime._container_name(workspace_id)
                )
                terminal_confirmed = bool(removal.get("terminal_confirmed"))
            elif has_runtime_record:
                workspace = {
                    "id": workspace_id,
                    "root": str(record.get("workspace_root") or self.cwd),
                    "source_type": str(record.get("source_type") or "interface-launch"),
                    "mode": str(record.get("mode") or "editable"),
                }
                # With no in-memory job, a preparing record belongs to a prior
                # Studio process. Its worker cannot later submit a start, so
                # the durable pre-submit state can be sealed without Docker.
                _mark_prestart_interface_runtime_terminal(self, workspace)
                record = self.workspace_runtime._read_record(workspace_id)
                terminal_confirmed = _workspace_runtime_record_proves_terminal(
                    record
                )
                if not terminal_confirmed:
                    try:
                        self.workspace_runtime.stop(workspace)
                        stopped = self.workspace_runtime._read_record(workspace_id)
                        terminal_confirmed = (
                            _workspace_runtime_record_proves_terminal(stopped)
                        )
                    except Exception:
                        terminal_confirmed = False
            if not terminal_confirmed:
                continue

            expired_session = bool(
                handle is not None
                and (
                    getattr(handle.lease.state, "value", str(handle.lease.state))
                    != "active"
                    or handle.lease.expires_at <= time.time()
                )
            )
            capture_succeeded = handle is None or runtime_is_symlink
            if handle is not None and not runtime_is_symlink:
                try:
                    service.capture_control_file(
                        handle=handle,
                        control_file=runtime_path / "control" / "outputs.jsonl",
                        root_handles={"output": runtime_path / "interface-outputs"},
                        retry_failed=False,
                    )
                    capture_succeeded = True
                except Exception:
                    capture_succeeded = False
            if not capture_succeeded and not expired_session:
                continue

            if runtime_is_symlink:
                try:
                    runtime_path.unlink()
                except OSError:
                    pass
                deleted = not runtime_path.exists()
            else:
                deleted = self.workspace_runtime.delete(workspace_id)
            if deleted:
                self.prepared_runtime_cache.release_launch(launch_id)
            if not deleted or handle is None or service is None or runtime is None:
                continue
            try:
                runtime.ledger.expire_stale_interface_output_capture(
                    operation_id=(
                        f"studio/interface-launch/{launch_id}/outputs/recover-expired"
                    ),
                    actor_principal_id=runtime.actor_principal_id,
                    session_id=handle.session.session_id,
                )
                service.retire_session(
                    operation_id=(
                        f"studio/interface-launch/{launch_id}/outputs/recover-finalize"
                    ),
                    handle=handle,
                )
            except (RealmConflict, RealmNotFound):
                pass

        if service is None or runtime is None:
            return
        for handle in service.reclaimable_sessions():
            # This reclaimer owns only Studio's ``launch-*`` interface
            # namespaces.  Operator Job sessions are reconciled by the Realm
            # supervisor because their final capture/adoption must precede
            # retirement and accounting release.
            if not handle.session.launch_id.startswith("launch-"):
                continue
            if handle.session.launch_id in reconciled_launch_ids:
                continue
            workspace_id = f"interface-{handle.session.launch_id}"
            if self.workspace_runtime._workspace_runtime_dir(workspace_id).exists():
                continue
            self.prepared_runtime_cache.release_launch(handle.session.launch_id)
            try:
                runtime.ledger.expire_stale_interface_output_capture(
                    operation_id=(
                        f"studio/interface-launch/{handle.session.launch_id}/"
                        "outputs/reclaim-expired"
                    ),
                    actor_principal_id=runtime.actor_principal_id,
                    session_id=handle.session.session_id,
                )
                service.retire_session(
                    operation_id=(
                        f"studio/interface-launch/{handle.session.launch_id}/"
                        "outputs/reclaim-finalize"
                    ),
                    handle=handle,
                )
            except (RealmConflict, RealmNotFound):
                pass

    def _active_code_workspace(self) -> Optional[JsonDict]:
        if not self.active_code_workspace_id:
            return None
        return _workspace_by_id(self, self.active_code_workspace_id)

    def _ensure_code_workspace(self, workspace_root: Path) -> JsonDict:
        workspace_root = workspace_root.resolve()
        for workspace in _list_ui_workspaces(self, include_support=True):
            if Path(str(workspace.get("root") or "")).resolve() == workspace_root:
                return workspace
        source_type = "external"
        mode = "editable"
        if any(
            _is_relative_to(workspace_root, root.resolve())
            for root in self.catalog_roots
        ):
            source_type = "catalog"
            mode = "read-only"
        elif any(
            _is_relative_to(workspace_root, root.resolve()) for root in self.run_roots
        ):
            source_type = "run"
            mode = "analysis"
        return _create_ui_workspace(
            self,
            {
                "id": f"ws_{slug_path(workspace_root)}",
                "title": workspace_root.name or "Workspace",
                "root": str(workspace_root),
                "source_type": source_type,
                "mode": mode,
                "description": "Workspace opened in Code Server",
                "registration_enabled": mode == "editable",
            },
        )


def run_ui(
    *,
    host: str = "127.0.0.1",
    port: int = 8765,
    catalog_roots: Optional[List[str]] = None,
    run_roots: Optional[List[str]] = None,
    code_server_bin: Optional[str] = None,
    code_server_host: str = "127.0.0.1",
    code_server_port: int = 8766,
    code_server_auth: str = "none",
    code_server_password: Optional[str] = None,
    workspace_runtime_executable: Optional[str] = None,
    workspace_runtime_image: Optional[str] = None,
    workspace_runtime_network: Optional[str] = None,
    workspace_runtime_port_start: Optional[int] = None,
    environment_preview_container_executable: Optional[str] = None,
    environment_preview_trusted_images: Optional[List[str]] = None,
    environment_preview_trust_source: str = "auto",
    open_browser: bool = False,
) -> None:
    cwd = Path.cwd().resolve()
    # Validate and pin the Realm root before deriving or creating any
    # project-local control path beneath it.  This prevents an unsafe terminal
    # symlink from receiving even the supervisor lock before Realm startup.
    realm_root = prepare_private_directory(default_realm_root())
    project_state_root = studio_project_state_directory(
        cwd,
        authority_root=realm_root,
    )
    runtime_supervisor_claim = StudioRuntimeSupervisorClaim.acquire(
        cwd,
        control_root=project_state_root,
    )
    try:
        runtime_options = WorkspaceRuntimeOptions.from_env()
        if workspace_runtime_executable:
            runtime_options.executable = workspace_runtime_executable
        if workspace_runtime_image:
            runtime_options.image = workspace_runtime_image
            runtime_options.build_image = (
                workspace_runtime_image == DEFAULT_WORKSPACE_RUNTIME_IMAGE
            )
        if workspace_runtime_network:
            runtime_options.network = workspace_runtime_network
        if workspace_runtime_port_start:
            runtime_options.port_start = workspace_runtime_port_start
        runtime_options.host = code_server_host
        runtime_options.auth = code_server_auth
        runtime_options.password = code_server_password or runtime_options.password
        preview_executable, preview_trust = _environment_preview_runtime_options(
            executable=environment_preview_container_executable,
            trusted_images=environment_preview_trusted_images,
            trust_source=environment_preview_trust_source,
        )
        realm_runtime = LocalRealmRuntime.open(
            realm_root=realm_root,
            container_web_executable=preview_executable,
            trusted_container_gateway_images=preview_trust,
        )
    except BaseException:
        runtime_supervisor_claim.close()
        raise
    state: Optional[UiState] = None
    server: Optional[ThreadingHTTPServer] = None
    try:
        state = UiState(
            cwd=cwd,
            catalog_roots=[Path(path).resolve() for path in catalog_roots or []],
            run_roots=[Path(path).resolve() for path in run_roots or []],
            realm_runtime=realm_runtime,
            code_server=CodeServerOptions(
                executable=code_server_bin,
                host=code_server_host,
                port=code_server_port,
                auth=code_server_auth,
                password=code_server_password,
            ),
            workspace_runtime=runtime_options,
            runtime_supervisor_claim=runtime_supervisor_claim,
            catalog_refresh_ttl_seconds=CATALOG_REFRESH_TTL_SECONDS,
        agent_tick_interval_seconds=STUDIO_AGENT_TICK_INTERVAL_SECONDS,
        )
        handler_cls = _handler_factory(state)
        server = ThreadingHTTPServer((host, port), handler_cls)
        # Request handlers must finish before Studio closes coordination or
        # Realm descriptors. ThreadingHTTPServer defaults to daemon handlers,
        # which server_close() deliberately does not join.
        server.daemon_threads = False
        url = f"http://{host}:{server.server_port}/"
        print(f"OptPilot UI running at {url}", flush=True)
        if open_browser:
            webbrowser.open(url)
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        background_quiesced = state is None
        interfaces_quiesced = state is None
        presentations_quiesced = state is None
        try:
            # serve_forever has returned, so closing the listener first both
            # rejects new work and joins every non-daemon request handler.
            if server is not None:
                server.server_close()
        finally:
            try:
                if state is not None:
                    interfaces_quiesced = state.stop_transient_interface_launches()
                    if interfaces_quiesced:
                        presentations_quiesced = bool(
                            state.stop_workspace_preview_proxies()
                        )
                        if presentations_quiesced:
                            state.close_catalog_projections()
                    # A timed-out interface settlement can still be finishing a
                    # final output projection, while a timed-out presentation
                    # can still be validating its runtime. Keep coordination
                    # open together with Realm and the supervisor claim.
                    background_quiesced = state.close_coordination(
                        close_storage=(
                            interfaces_quiesced and presentations_quiesced
                        )
                    )
            finally:
                fully_quiesced = (
                    background_quiesced
                    and interfaces_quiesced
                    and presentations_quiesced
                )
                if fully_quiesced:
                    try:
                        realm_runtime.close()
                    finally:
                        runtime_supervisor_claim.close()
                else:
                    runtime_supervisor_claim.retain_until_process_exit()
                    print(
                        "OptPilot Studio shutdown retained its Realm and runtime "
                        "supervisor descriptors because background execution is "
                        "still unwinding. Durable work remains recoverable after "
                        "process exit.",
                        file=sys.stderr,
                        flush=True,
                    )


def _preview_proxy_handler_factory(
    target_base_url: str, *, token: str, allowed_ports: Iterable[int]
):
    """Legacy test seam backed by the one general presentation proxy."""

    target = str(target_base_url).rstrip("/")
    routes: Dict[int, str]
    if "/proxy/" in target:
        code_server_base, port_text = target.rsplit("/proxy/", 1)
        primary_port = int(port_text)
        ports = {primary_port, *(int(item) for item in allowed_ports)}
        routes = {
            port: f"{code_server_base.rstrip('/')}/proxy/{port}" for port in ports
        }
    else:
        primary_port = 1
        routes = {primary_port: target}
    code_server_proxy = "/proxy/" in target
    endpoint = OwnedWebEndpoint(
        owner_kind=(
            "workspace-runtime"
            if code_server_proxy
            else "legacy-workspace-preview-test"
        ),
        owner_id="test-endpoint",
        generation=request_digest(
            {
                "schema": "optpilot.legacy-preview-test.v1",
                "routes": routes,
            }
        ),
        access_policy="trusted-local-authoring",
        websocket_origin_policy=("omit" if code_server_proxy else "preserve"),
        primary_port=primary_port,
        routes=routes,
        validate=lambda: None,
    )
    return _presentation_proxy_handler_factory(endpoint, token=token)


def _environment_preview_runtime_options(
    *,
    executable: Optional[str],
    trusted_images: Optional[Iterable[str]],
    trust_source: str = "auto",
) -> tuple[
    Optional[str],
    Optional[tuple[ContainerGatewayImageTrust, ...]],
]:
    """Resolve the provider executable and an optional exact session trust set.

    ``None`` means that :class:`LocalRealmRuntime` must load the durable Realm
    policy.  A tuple, including an empty tuple, is an exact session override;
    it is deliberately never unioned with durable approvals so a stale shell
    variable cannot undo an operator revocation.
    """

    requested = str(
        executable
        or os.environ.get(_ENVIRONMENT_PREVIEW_CONTAINER_EXECUTABLE_ENV)
        or ""
    ).strip()
    explicit = bool(requested)
    if requested:
        candidate = Path(requested).expanduser()
        if candidate.is_absolute():
            resolved = str(candidate.resolve()) if candidate.exists() else None
        else:
            resolved = shutil.which(requested)
    else:
        resolved = shutil.which("docker")
    if explicit and not resolved:
        raise RuntimeError("Environment Preview container executable is not available.")

    selected_source = str(trust_source or "auto").strip().casefold()
    if selected_source not in {"auto", "realm", "session", "disabled"}:
        raise ValueError("Environment Preview trust source is unsupported.")
    explicit_values = None
    if trusted_images is not None:
        explicit_values = [
            str(item).strip() for item in trusted_images if str(item).strip()
        ]
    legacy_environment = os.environ.get(
        _ENVIRONMENT_PREVIEW_TRUSTED_IMAGES_ENV
    )
    environment_values = (
        [item.strip() for item in legacy_environment.split(",") if item.strip()]
        if legacy_environment is not None
        else None
    )

    values: Optional[List[str]]
    if selected_source == "realm":
        if explicit_values is not None:
            raise ValueError(
                "--environment-preview-trust-source=realm cannot be combined "
                "with --environment-preview-trusted-image."
            )
        values = None
    elif selected_source == "disabled":
        if explicit_values is not None:
            raise ValueError(
                "--environment-preview-trust-source=disabled cannot be combined "
                "with --environment-preview-trusted-image."
            )
        values = []
    elif selected_source == "session":
        values = (
            explicit_values
            if explicit_values is not None
            else environment_values or []
        )
    elif explicit_values is not None:
        values = explicit_values
    elif environment_values is not None:
        values = environment_values
        print(
            "Warning: OPTPILOT_ENVIRONMENT_PREVIEW_TRUSTED_IMAGES is an exact "
            "session-only trust override. Use `optpilot environment-preview "
            "trust approve` for restart-persistent approval.",
            file=sys.stderr,
        )
    else:
        values = None

    trusts = (
        None
        if values is None
        else tuple(
            ContainerGatewayImageTrust(image_ref=image)
            for image in dict.fromkeys(values)
        )
    )
    return resolved, trusts


def add_ui_arguments(parser: argparse.ArgumentParser) -> argparse.ArgumentParser:
    parser.add_argument("--host", default="127.0.0.1", help="Host interface to bind")
    parser.add_argument("--port", type=int, default=8765, help="Port to bind")
    parser.add_argument(
        "--catalog",
        action="append",
        default=[],
        help="Catalog root to scan. Defaults to packages under catalog/.",
    )
    parser.add_argument("--runs", action="append", default=[], help="Run root to scan")
    parser.add_argument(
        "--code-server-bin",
        default=None,
        help="Path to the coder/code-server executable",
    )
    parser.add_argument(
        "--code-server-host",
        default="127.0.0.1",
        help="Host interface for coder/code-server",
    )
    parser.add_argument(
        "--code-server-port", type=int, default=8766, help="Port for coder/code-server"
    )
    parser.add_argument(
        "--code-server-auth",
        choices=["none", "password"],
        default="none",
        help="Authentication mode passed to coder/code-server",
    )
    parser.add_argument(
        "--code-server-password",
        default=None,
        help="PASSWORD value when --code-server-auth=password",
    )
    parser.add_argument(
        "--workspace-runtime-bin",
        default=None,
        help="Docker/Podman-compatible executable for per-workspace containers. Defaults to docker or podman on PATH.",
    )
    parser.add_argument(
        "--workspace-runtime-image",
        default=None,
        help="Container image used for workspace shells and Code Server. It must include code-server.",
    )
    parser.add_argument(
        "--workspace-runtime-network",
        default=None,
        help="Container network policy for workspace containers. Use bridge/default for embedded Code Server.",
    )
    parser.add_argument(
        "--workspace-runtime-port-start",
        type=int,
        default=None,
        help="First host port to try when publishing per-workspace Code Server.",
    )
    parser.add_argument(
        "--environment-preview-container-bin",
        default=None,
        help=(
            "Docker executable for isolated candidate Environment Preview jobs. "
            "Defaults to docker on PATH."
        ),
    )
    parser.add_argument(
        "--environment-preview-trusted-image",
        action="append",
        default=None,
        help=(
            "Exact sha256-pinned interface image trusted for this Studio session. "
            "Supplying this option replaces, rather than extends, durable Realm "
            "approvals. Repeat as needed."
        ),
    )
    parser.add_argument(
        "--environment-preview-trust-source",
        choices=("auto", "realm", "session", "disabled"),
        default="auto",
        help=(
            "Trust source for isolated Candidate interfaces. auto uses an exact "
            "CLI/environment session override when supplied, otherwise the "
            "durable Realm policy."
        ),
    )
    parser.add_argument(
        "--open-browser", action="store_true", help="Open the UI in a browser"
    )
    return parser


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="optpilot ui")
    return add_ui_arguments(parser)


def main(argv: Optional[List[str]] = None) -> int:
    args = build_parser().parse_args(argv)
    try:
        run_ui(
            host=args.host,
            port=args.port,
            catalog_roots=args.catalog,
            run_roots=args.runs,
            code_server_bin=args.code_server_bin,
            code_server_host=args.code_server_host,
            code_server_port=args.code_server_port,
            code_server_auth=args.code_server_auth,
            code_server_password=args.code_server_password,
            workspace_runtime_executable=args.workspace_runtime_bin,
            workspace_runtime_image=args.workspace_runtime_image,
            workspace_runtime_network=args.workspace_runtime_network,
            workspace_runtime_port_start=args.workspace_runtime_port_start,
            environment_preview_container_executable=(
                args.environment_preview_container_bin
            ),
            environment_preview_trusted_images=(
                args.environment_preview_trusted_image
            ),
            environment_preview_trust_source=(
                args.environment_preview_trust_source
            ),
            open_browser=args.open_browser,
        )
    except StudioRuntimeSupervisorBusy as error:
        print(f"OptPilot Studio could not start: {error}", file=sys.stderr)
        return 2
    return 0


def _handler_factory(state: UiState):
    static_dir = (Path(__file__).parent / "static").resolve()

    class OptPilotUiHandler(BaseHTTPRequestHandler):
        server_version = "OptPilotUI/0.1"

        def _send_storage_unavailable(
            self,
            error: BaseException,
            *,
            path: str,
        ) -> None:
            # Keep the underlying diagnostic in the local Studio log while
            # presenting one stable, retryable contract to the browser.  In
            # particular, never turn a transient coordination-store failure
            # into Study validation feedback or expose host paths/SQLite text.
            print(
                f"OptPilot Studio local storage unavailable for {path}: "
                f"{type(error).__name__}: {error}",
                file=sys.stderr,
            )
            message = COORDINATION_STORAGE_UNAVAILABLE_MESSAGE
            if path.startswith("/api/studies/"):
                message += " Your Study was not changed; try again."
            else:
                message += " Try again."
            self._send_json(
                {
                    "error": message,
                    "type": "CoordinationStorageUnavailable",
                    "code": "studio_storage_unavailable",
                    "retryable": True,
                },
                status=HTTPStatus.SERVICE_UNAVAILABLE,
            )

        def do_GET(self) -> None:  # noqa: N802
            parsed = urlparse(self.path)
            path = parsed.path
            query = parse_qs(parsed.query)
            try:
                if path == "/" or path == "/index.html":
                    self._send_file(static_dir / "index.html")
                    return
                if path.startswith("/static/"):
                    self._send_static_file(path.removeprefix("/static/"))
                    return
                if path == "/api/health":
                    self._send_json({"ok": True, "cwd": str(state.cwd)})
                    return
                if path == "/api/workspace":
                    self._send_json(_workspace_payload(state))
                    return
                if path == "/api/workspaces":
                    self._send_json({"workspaces": _list_ui_workspaces(state)})
                    return
                if path == "/api/studies/drafts":
                    self._send_json(_list_saved_study_drafts(state))
                    return
                if path.startswith("/api/workspaces/"):
                    self._handle_workspace_get(path)
                    return
                if path == "/api/agent-sessions":
                    summaries_only = str((query.get("summary") or [""])[0]).lower() in {
                        "1",
                        "true",
                        "yes",
                    }
                    archived_only = str(
                        (query.get("archived") or [""])[0]
                    ).lower() in {"1", "true", "yes"}
                    if archived_only:
                        # Archived Conversations are summaries only: restoring
                        # one returns it to the main list, which is the path
                        # for opening it again.
                        self._send_json(
                            {
                                "sessions": _list_archived_agent_session_summaries(
                                    state
                                )
                            }
                        )
                        return
                    self._send_json(
                        {
                            "sessions": (
                                _list_agent_session_summaries(state)
                                if summaries_only
                                else _list_agent_sessions(state)
                            )
                        }
                    )
                    return
                if path == "/api/agent/settings":
                    self._send_json(_agent_settings_payload(state))
                    return
                if path == "/api/agent/capabilities":
                    self._send_json(_assistant_capability_list(state))
                    return
                if path.startswith("/api/agent/capabilities/"):
                    parts = path.split("/")
                    if len(parts) >= 6:
                        self._send_json(
                            _assistant_capability_detail(
                                state, parts[4], unquote(parts[5])
                            )
                        )
                    else:
                        self._send_json(
                            {"error": "Missing capability kind or id"},
                            status=HTTPStatus.BAD_REQUEST,
                        )
                    return
                if path == "/api/agent/runtime/status":
                    self._send_json(state.agent_adapter.status())
                    return
                if path.startswith("/api/agent-sessions/"):
                    self._handle_agent_session_get(path)
                    return
                if path == "/api/runtime/health":
                    self._send_json(_runtime_health(state))
                    return
                if path == "/api/code-server/status":
                    self._send_json(state.code_server_status())
                    return
                if path == "/api/catalog":
                    self._send_json(_catalog_payload(state))
                    return
                if path == "/api/environments":
                    self._send_json(
                        {"environments": _catalog_payload(state)["environments"]}
                    )
                    return
                if path.startswith("/api/environments/"):
                    self._send_json(
                        _catalog_detail(state, "environment", path.split("/", 3)[3])
                    )
                    return
                if path == "/api/methods":
                    self._send_json({"methods": _catalog_payload(state)["methods"]})
                    return
                if path.startswith("/api/methods/"):
                    self._send_json(
                        _catalog_detail(state, "method", path.split("/", 3)[3])
                    )
                    return
                if path == "/api/resources":
                    self._send_json({"resources": _catalog_payload(state)["resources"]})
                    return
                if path.startswith("/api/resources/"):
                    self._send_json(
                        _catalog_detail(state, "resource", path.split("/", 3)[3])
                    )
                    return
                if path == "/api/compatibility":
                    self._send_json(_compatibility_payload(state))
                    return
                if path.startswith("/api/studies/launches/"):
                    parts = path.split("/")
                    if len(parts) != 5 or not parts[4]:
                        raise ValueError("Invalid Study launch status path.")
                    launch = _study_launch_service_for_state(state).read(
                        launch_id=unquote(parts[4])
                    )
                    self._send_json(_study_launch_response(launch))
                    return
                if path.startswith("/api/studies/launch-requests/"):
                    parts = path.split("/")
                    if len(parts) != 5 or not parts[4]:
                        raise ValueError(
                            "Invalid Study launch preparation status path."
                        )
                    self._send_json(
                        _study_launch_preparation_status(
                            state, unquote(parts[4])
                        )
                    )
                    return
                if path == "/api/runs":
                    page_token = _query_value(query, "page_token")
                    limit = _bounded_query_int(query, "limit", default=50)
                    if page_token is None and state.realm_runtime is not None:
                        entry = _runs_response_entry(state, limit=limit)
                        if (
                            self.headers.get("If-None-Match")
                            == entry["etag"]
                        ):
                            self._send_not_modified(entry["etag"])
                        else:
                            self._send_json_bytes(
                                entry["body"], etag=entry["etag"]
                            )
                        return
                    self._send_json(
                        _realm_runs_payload(
                            state,
                            page_token=page_token,
                            limit=limit,
                        )
                    )
                    return
                if path.startswith("/api/content-views/"):
                    self._handle_selection_content_view_get(path, query)
                    return
                if path.startswith("/api/runs/"):
                    self._handle_run_get(path, query)
                    return
                if path.startswith("/api/operator-jobs/"):
                    self._handle_operator_job_get(path)
                    return
                if path.startswith("/api/resource-actions/"):
                    parts = path.split("/")
                    if len(parts) != 4 or not parts[3]:
                        raise ValueError("Invalid resource action status path.")
                    try:
                        self._send_json(
                            _resource_action_run_status(state, unquote(parts[3]))
                        )
                    except KeyError:
                        self._send_json(
                            {"error": "Resource action run was not found."},
                            status=HTTPStatus.NOT_FOUND,
                        )
                    return
                if path == "/api/jobs":
                    jobs = (
                        [
                            launch.to_dict()
                            for launch in _study_launch_service_for_state(state).list()
                        ]
                        if _study_launch_provider_available(state)
                        else []
                    )
                    self._send_json(
                        {
                            "jobs": sorted(
                                jobs,
                                key=lambda item: float(item.get("started_at") or 0.0),
                                reverse=True,
                            )
                        }
                    )
                    return
                if path.startswith("/api/interface-launches/"):
                    parts = path.split("/")
                    if (
                        len(parts) == 8
                        and parts[4] == "output-action-executions"
                        and parts[6] == "files"
                        and parts[7] == "content"
                    ):
                        _require_allowed_query_keys(
                            query,
                            allowed={"path", "download"},
                            label="action result file request",
                        )
                        relative_path = _query_value(query, "path")
                        if relative_path is None:
                            raise ValueError(
                                "Action result file request requires path."
                            )
                        download_value = _query_value(query, "download")
                        if download_value not in {None, "0", "1"}:
                            raise ValueError(
                                "Action result file download must be 0 or 1."
                            )
                        self._send_interface_output_action_result_file(
                            launch_id=unquote(parts[3]),
                            request_id=unquote(parts[5]),
                            relative_path=relative_path,
                            download=download_value == "1",
                        )
                        return
                    if len(parts) == 4:
                        try:
                            self._send_json(
                                {"launch": _interface_launch_by_id(state, parts[3])}
                            )
                        except KeyError:
                            self._send_json(
                                {"error": f"Unknown id: {parts[3]}"},
                                status=HTTPStatus.NOT_FOUND,
                            )
                        return
                    if (
                        len(parts) == 6
                        and parts[4] == "outputs"
                        and parts[5] == "tree-choices"
                    ):
                        self._send_json(_interface_output_tree_choices(state, parts[3]))
                        return
                self._send_json({"error": "Not found"}, status=HTTPStatus.NOT_FOUND)
            except (BrokenPipeError, ConnectionResetError):
                # The browser can supersede an in-flight Conversation request
                # while navigating.  A closed client is not a Studio failure,
                # and attempting a second JSON response only raises again.
                return
            except (CoordinationStorageUnavailable, sqlite3.Error) as exc:
                self._send_storage_unavailable(exc, path=path)
            except RealmNotFound as exc:
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.NOT_FOUND,
                )
            except RealmConflict as exc:
                response = {"error": str(exc), "type": type(exc).__name__}
                code = getattr(exc, "code", None)
                if isinstance(code, str) and code:
                    response["code"] = code
                self._send_json(response, status=HTTPStatus.CONFLICT)
            except ValueError as exc:
                self._send_json({"error": str(exc)}, status=HTTPStatus.BAD_REQUEST)
            except Exception as exc:  # pragma: no cover - defensive HTTP boundary
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.INTERNAL_SERVER_ERROR,
                )

        def do_POST(self) -> None:  # noqa: N802
            parsed = urlparse(self.path)
            try:
                if parsed.path == "/api/studies/validate":
                    payload = self._read_json_body()
                    study_path = _resolve_user_path(
                        payload.get("study_path"), state.cwd
                    )
                    self._send_json(_validate_study(study_path, state=state))
                    return
                if parsed.path == "/api/studies/draft":
                    payload = self._read_json_body()
                    self._send_json(_draft_study(state, payload))
                    return
                if parsed.path.startswith("/api/studies/drafts/") and parsed.path.endswith("/discard"):
                    parts = parsed.path.split("/")
                    if len(parts) != 6:
                        raise ValueError("Invalid Study draft discard path.")
                    self._send_json(
                        _discard_saved_study_draft(
                            state, unquote(parts[4]), self._read_json_body()
                        )
                    )
                    return
                if parsed.path == "/api/studies/launch":
                    response, status = _submit_study_launch_request(
                        state, self._read_json_body()
                    )
                    self._send_json(response, status=status)
                    return
                if parsed.path == "/api/resource-actions/run":
                    response, status = _start_resource_action_run(
                        state, self._read_json_body()
                    )
                    self._send_json(response, status=status)
                    return
                if parsed.path.startswith("/api/studies/launches/") and parsed.path.endswith("/stop"):
                    parts = parsed.path.split("/")
                    if len(parts) != 6 or not parts[4]:
                        raise ValueError("Invalid Study launch stop path.")
                    request = _exact_json_object(
                        self._read_json_body(),
                        expected={"schema", "request_id"},
                        label="Study launch Stop request",
                    )
                    if request["schema"] != STUDY_LAUNCH_STOP_REQUEST_SCHEMA:
                        raise ValueError("Study launch Stop request schema is unsupported.")
                    request_id = _canonical_request_uuid(request["request_id"])
                    launch_id = unquote(parts[4])
                    stopped = state.stop_job(
                        launch_id,
                        operation_id=(
                            f"studio/study-launch/{launch_id}/cancel/{request_id}"
                        ),
                    )
                    self._send_json(
                        {
                            "schema": STUDY_LAUNCH_RESPONSE_SCHEMA,
                            "request_id": request_id,
                            "launch": _public_study_launch(
                                _study_launch_service_for_state(state).read(
                                    launch_id=str(stopped["launch_id"])
                                )
                            ),
                        }
                    )
                    return
                if parsed.path == "/api/studies/workspace":
                    payload = self._read_json_body()
                    self._send_json(
                        {"workspace": _open_study_workspace(state, payload)},
                        status=HTTPStatus.CREATED,
                    )
                    return
                if parsed.path == "/api/workspaces":
                    payload = self._read_json_body()
                    self._send_json(
                        {"workspace": _create_ui_workspace(state, payload)},
                        status=HTTPStatus.CREATED,
                    )
                    return
                if parsed.path == "/api/workspaces/connect-local-folder":
                    payload = self._read_json_body()
                    self._send_json(
                        {"workspace": _connect_local_folder(state, payload)},
                        status=HTTPStatus.CREATED,
                    )
                    return
                if parsed.path.startswith("/api/workspaces/"):
                    self._handle_workspace_post(parsed.path)
                    return
                if parsed.path == "/api/agent-sessions":
                    payload = self._read_json_body()
                    self._send_json(
                        {"session": _create_agent_session(state, payload)},
                        status=HTTPStatus.CREATED,
                    )
                    return
                if parsed.path == "/api/agent/settings":
                    payload = self._read_json_body()
                    self._send_json(_update_agent_settings(state, payload))
                    return
                if parsed.path.startswith("/api/agent-sessions/"):
                    self._handle_agent_session_post(parsed.path)
                    return
                if parsed.path.startswith(
                    "/api/interface-launches/"
                ) and parsed.path.endswith("/stop"):
                    parts = parsed.path.split("/")
                    if len(parts) != 5:
                        raise ValueError("Invalid interface launch stop path.")
                    self._send_json({"launch": _stop_interface_launch(state, parts[3])})
                    return
                if parsed.path.startswith("/api/interface-launches/"):
                    parts = parsed.path.split("/")
                    if (
                        len(parts) == 9
                        and parts[4] == "outputs"
                        and parts[6] == "actions"
                        and parts[8] == "run"
                    ):
                        self._send_json(
                            _run_ready_interface_output_action(
                                state,
                                parts[3],
                                unquote(parts[5]),
                                unquote(parts[7]),
                                self._read_json_body(),
                            ),
                            status=HTTPStatus.ACCEPTED,
                        )
                        return
                    if (
                        len(parts) == 6
                        and parts[4] == "outputs"
                        and parts[5] == "capture-tree"
                    ):
                        self._send_json(
                            _capture_interface_output_tree(
                                state,
                                parts[3],
                                self._read_json_body(),
                            ),
                            status=HTTPStatus.CREATED,
                        )
                        return
                    if (
                        len(parts) == 7
                        and parts[4] == "outputs"
                        and parts[6] in {"keep", "retry", "view"}
                    ):
                        payload = self._read_json_body()
                        launch_id = parts[3]
                        output_id = unquote(parts[5])
                        if parts[6] == "view":
                            request = _exact_json_object(
                                payload,
                                expected={"schema", "content_session_id"},
                                label="Interface output View request",
                            )
                            if (
                                request["schema"]
                                != INTERFACE_OUTPUT_CONTENT_VIEW_REQUEST_SCHEMA
                            ):
                                raise ValueError(
                                    "Interface output View request schema is unsupported."
                                )
                            self._send_json(
                                _view_interface_output(
                                    state,
                                    launch_id,
                                    output_id,
                                    requested_session_id=(
                                        _optional_selection_content_session_id(
                                            request["content_session_id"]
                                        )
                                    ),
                                ),
                                status=HTTPStatus.CREATED,
                            )
                        elif parts[6] == "keep":
                            request = _exact_json_object(
                                payload,
                                expected={"request_id"},
                                label="Interface output Keep request",
                            )
                            request_id = _canonical_request_uuid(
                                request["request_id"]
                            )
                            self._send_json(
                                _keep_interface_output_as_workspace(
                                    state,
                                    launch_id,
                                    output_id,
                                    request_id=request_id,
                                ),
                                status=HTTPStatus.CREATED,
                            )
                        else:
                            if payload != {}:
                                raise ValueError(
                                    "Interface output Retry accepts an empty JSON object."
                                )
                            self._send_json(
                                _retry_interface_output_capture(
                                    state, launch_id, output_id
                                )
                            )
                        return
                if parsed.path.startswith("/api/catalog/"):
                    if parsed.path.startswith("/api/catalog/sources/"):
                        self._handle_configured_catalog_source_post(parsed.path)
                        return
                    self._handle_catalog_workspace_post(parsed.path)
                    return
                if parsed.path.startswith("/api/content-views/"):
                    self._handle_selection_content_view_post(parsed.path)
                    return
                if parsed.path.startswith("/api/runs/"):
                    self._handle_run_post(parsed.path)
                    return
                if parsed.path.startswith("/api/operator-jobs/"):
                    self._handle_operator_job_post(parsed.path)
                    return
                if parsed.path == "/api/code-server/start":
                    payload = self._read_json_body()
                    folder = _optional_user_path(payload.get("folder"), state.cwd)
                    self._send_json(
                        state.start_code_server(folder), status=HTTPStatus.CREATED
                    )
                    return
                if parsed.path == "/api/code-server/open":
                    payload = self._read_json_body()
                    folder = _optional_user_path(payload.get("folder"), state.cwd)
                    self._send_json(state.code_server_open_url(folder))
                    return
                if parsed.path == "/api/workspace-preview/open":
                    payload = self._read_json_body()
                    folder = _optional_user_path(payload.get("folder"), state.cwd)
                    port = int(payload.get("port") or 5173)
                    extra_ports = (
                        payload.get("extra_ports")
                        if isinstance(payload.get("extra_ports"), list)
                        else []
                    )
                    self._send_json(
                        state.workspace_preview_open(
                            folder, port, extra_ports=extra_ports
                        ),
                        status=HTTPStatus.CREATED,
                    )
                    return
                if parsed.path == "/api/code-server/stop":
                    self._send_json(state.stop_code_server())
                    return
                if parsed.path.startswith("/api/jobs/") and parsed.path.endswith(
                    "/stop"
                ):
                    job_id = parsed.path.split("/")[3]
                    self._send_json({"job": state.stop_job(job_id)})
                    return
                self._send_json({"error": "Not found"}, status=HTTPStatus.NOT_FOUND)
            except (BrokenPipeError, ConnectionResetError):
                return
            except (CoordinationStorageUnavailable, sqlite3.Error) as exc:
                self._send_storage_unavailable(exc, path=parsed.path)
            except RealmNotFound as exc:
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.NOT_FOUND,
                )
            except RealmConflict as exc:
                response = {"error": str(exc), "type": type(exc).__name__}
                code = getattr(exc, "code", None)
                if isinstance(code, str) and code:
                    response["code"] = code
                self._send_json(response, status=HTTPStatus.CONFLICT)
            except KeyError as exc:
                self._send_json(
                    {"error": f"Unknown id: {exc.args[0]}"}, status=HTTPStatus.NOT_FOUND
                )
            except InterfaceOutputExecutionRejected as exc:
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.BAD_REQUEST,
                )
            except ValueError as exc:
                self._send_json({"error": str(exc)}, status=HTTPStatus.BAD_REQUEST)
            except Exception as exc:  # pragma: no cover - defensive HTTP boundary
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.INTERNAL_SERVER_ERROR,
                )
            finally:
                if not _runs_neutral_mutation_path(parsed.path):
                    _invalidate_runs_response_cache(state)

        def do_DELETE(self) -> None:  # noqa: N802
            parsed = urlparse(self.path)
            try:
                if parsed.path.startswith("/api/workspaces/"):
                    parts = parsed.path.split("/")
                    if len(parts) == 4:
                        self._send_json(
                            {"workspace": _delete_ui_workspace(state, parts[3])}
                        )
                        return
                self._send_json({"error": "Not found"}, status=HTTPStatus.NOT_FOUND)
            except (BrokenPipeError, ConnectionResetError):
                # The requested mutation may already have completed, but the
                # navigating browser can no longer receive its response.
                return
            except (CoordinationStorageUnavailable, sqlite3.Error) as exc:
                self._send_storage_unavailable(exc, path=parsed.path)
            except KeyError as exc:
                self._send_json(
                    {"error": f"Unknown id: {exc.args[0]}"}, status=HTTPStatus.NOT_FOUND
                )
            except RealmNotFound as exc:
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.NOT_FOUND,
                )
            except RealmConflict as exc:
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.CONFLICT,
                )
            except ValueError as exc:
                self._send_json({"error": str(exc)}, status=HTTPStatus.BAD_REQUEST)
            except Exception as exc:  # pragma: no cover - defensive HTTP boundary
                self._send_json(
                    {"error": str(exc), "type": type(exc).__name__},
                    status=HTTPStatus.INTERNAL_SERVER_ERROR,
                )
            finally:
                if not _runs_neutral_mutation_path(parsed.path):
                    _invalidate_runs_response_cache(state)

        def _handle_workspace_get(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) < 4:
                self._send_json(
                    {"error": "Missing workspace id"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            workspace = _workspace_by_id(state, parts[3])
            if not workspace:
                self._send_json(
                    {"error": "Workspace not found"}, status=HTTPStatus.NOT_FOUND
                )
                return
            if len(parts) == 5 and parts[4] == "setup":
                self._send_json(
                    {
                        "workspace_id": parts[3],
                        "setup": _public_registration_setup(
                            _current_registration_setup(state, parts[3])
                        ),
                    }
                )
                return
            if len(parts) != 4:
                self._send_json(
                    {"error": "Unknown workspace resource"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            self._send_json({"workspace": workspace})

        def _handle_workspace_post(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) < 4:
                self._send_json(
                    {"error": "Missing workspace id"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            workspace_id = parts[3]
            if len(parts) == 5 and parts[4] == "discover-configs":
                self._send_json(_discover_workspace_configs(state, workspace_id))
                return
            if len(parts) == 6 and parts[4] == "setup" and parts[5] == "configure":
                payload = self._read_json_body()
                self._send_json(
                    _configure_workspace_catalog_role(state, workspace_id, payload),
                    status=HTTPStatus.CREATED,
                )
                return
            if len(parts) == 5 and parts[4] in {
                "open-code",
                "open-code-window",
            }:
                workspace = _require_ui_workspace(state, workspace_id)
                self._send_json(state.start_workspace_code_server(workspace))
                return
            if len(parts) == 5 and parts[4] == "launch-interface-job":
                payload = self._read_json_body()
                setup_policy = str(payload.get("setup") or "auto")
                profile_id = str(payload.get("profile_id") or "")
                self._send_json(
                    _start_workspace_interface_launch(
                        state,
                        workspace_id,
                        setup_policy=setup_policy,
                        profile_id=profile_id,
                    ),
                    status=HTTPStatus.ACCEPTED,
                )
                return
            if len(parts) == 5 and parts[4] == "detach":
                payload = self._read_json_body()
                self._send_json(
                    {
                        "workspace": _detach_workspace(
                            state, workspace_id, str(payload.get("session_id", ""))
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "rename":
                payload = self._read_json_body()
                self._send_json(
                    {
                        "workspace": _rename_ui_workspace(
                            state, workspace_id, payload
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "reopen":
                payload = self._read_json_body()
                self._send_json(
                    {
                        "workspace": _reopen_managed_workspace(
                            state, workspace_id, payload
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "commit":
                payload = self._read_json_body()
                self._send_json(_commit_managed_workspace(state, workspace_id, payload))
                return
            if len(parts) == 5 and parts[4] == "package-plans":
                payload = self._read_json_body()
                self._send_json(
                    _prepare_package_plan(state, workspace_id, payload),
                    status=HTTPStatus.CREATED,
                )
                return
            if len(parts) == 7 and parts[4] == "package-plans" and parts[6] == "update":
                payload = self._read_json_body()
                self._send_json(
                    _update_package_plan(state, workspace_id, parts[5], payload)
                )
                return
            if (
                len(parts) == 7
                and parts[4] == "package-plans"
                and parts[6] == "validate"
            ):
                self._send_json(_validate_package_plan(state, workspace_id, parts[5]))
                return
            if len(parts) == 7 and parts[4] == "package-plans" and parts[6] == "smoke":
                payload = self._read_json_body()
                self._send_json(
                    _smoke_package_plan(state, workspace_id, parts[5], payload)
                )
                return
            if len(parts) == 7 and parts[4] == "package-plans" and parts[6] == "apply":
                self._send_json(_apply_package_plan(state, workspace_id, parts[5]))
                return
            self._send_json(
                {"error": "Unknown workspace action"}, status=HTTPStatus.NOT_FOUND
            )

        def _handle_agent_session_get(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) < 4:
                self._send_json(
                    {"error": "Missing agent session id"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            session_id = parts[3]
            session = _agent_session_by_id(state, session_id)
            if not session:
                self._send_json(
                    {"error": "Agent session not found"}, status=HTTPStatus.NOT_FOUND
                )
                return
            if len(parts) == 5 and parts[4] == "context":
                self._send_json(
                    {
                        "context": _agent_context_packet(
                            state, _require_agent_session(state, session_id), {}
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "events":
                self._send_json({"events": _read_agent_events(state, session_id)})
                return
            if len(parts) == 5 and parts[4] == "approvals":
                self._send_json(
                    {"approvals": _public_agent_approvals(state, session_id)}
                )
                return
            self._send_json({"session": session})

        def _handle_agent_session_post(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) < 4:
                self._send_json(
                    {"error": "Missing agent session id"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            session_id = parts[3]
            if len(parts) == 5 and parts[4] == "run-selection":
                payload = self._read_json_body()
                self._send_json(
                    _mint_assistant_run_selection(
                        state,
                        session_id=session_id,
                        payload=payload,
                    ),
                    status=HTTPStatus.CREATED,
                )
                return
            if len(parts) == 5 and parts[4] == "message":
                payload = self._read_json_body()
                with _agent_session_operation_lock(state, session_id):
                    pending_ids = _agent_pending_approval_ids(state, session_id)
                    if pending_ids:
                        self._send_json(
                            {
                                "error": "approval_required",
                                "summary": "Resolve the pending approval before sending another assistant message.",
                                "pending_approval_ids": pending_ids,
                                "session": _agent_session_payload(
                                    state, _require_agent_session(state, session_id)
                                ),
                            },
                            status=HTTPStatus.CONFLICT,
                        )
                        return
                    self._send_json(_append_agent_message(state, session_id, payload))
                return
            if len(parts) == 5 and parts[4] == "attach-workspace":
                payload = self._read_json_body()
                workspace_id = str(payload.get("workspace_id") or "")
                self._send_json(
                    {
                        "session": _attach_agent_workspace(
                            state, session_id, workspace_id, select=True
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "detach-workspace":
                payload = self._read_json_body()
                workspace_id = str(payload.get("workspace_id") or "")
                self._send_json(
                    {
                        "session": _detach_agent_workspace(
                            state, session_id, workspace_id
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "select-workspace":
                payload = self._read_json_body()
                self._send_json(
                    {
                        "session": _select_agent_workspace(
                            state, session_id, str(payload.get("workspace_id") or "")
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "archive":
                payload = self._read_json_body()
                self._send_json(
                    {
                        "session": _set_agent_session_archived(
                            state, session_id, bool(payload.get("archived", True))
                        )
                    }
                )
                return
            if len(parts) == 5 and parts[4] == "cancel":
                self._send_json({"session": _cancel_agent_session(state, session_id)})
                return
            if len(parts) == 5 and parts[4] == "sync":
                try:
                    self._send_json({"session": _sync_agent_session(state, session_id)})
                except Exception as exc:
                    if not _is_timeout_like(exc):
                        raise
                    self._send_json(
                        {
                            "session": _mark_agent_session_waiting_after_sync_timeout(
                                state, session_id, exc
                            )
                        }
                    )
                return
            if len(parts) == 6 and parts[4] == "tools":
                payload = self._read_json_body()
                self._send_json(
                    _execute_agent_tool(state, session_id, parts[5], payload)
                )
                return
            if (
                len(parts) == 7
                and parts[4] == "approvals"
                and parts[6] in {"approve", "reject"}
            ):
                if parts[6] == "approve":
                    self._send_json(_approve_agent_action(state, session_id, parts[5]))
                else:
                    payload = self._read_json_body()
                    self._send_json(
                        _reject_agent_action(
                            state,
                            session_id,
                            parts[5],
                            str(payload.get("reason") or ""),
                        )
                    )
                return
            self._send_json(
                {"error": "Unknown agent session action"}, status=HTTPStatus.NOT_FOUND
            )

        def _handle_catalog_workspace_post(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) != 6 or parts[5] not in {
                "open-workspace",
                "open-code",
                "edit-copy",
                "launch-interface-job",
            }:
                self._send_json(
                    {"error": "Unknown catalog workspace action"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            _, _, _, kind, uid, action = parts
            if kind not in {"environment", "method", "study", "resource"}:
                self._send_json(
                    {"error": "Unknown catalog kind"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            payload = self._read_json_body()
            if action == "launch-interface-job":
                request = _exact_json_object(
                    payload,
                    expected={"profile_id"},
                    label="Catalog interface launch request",
                )
                self._send_json(
                    _start_catalog_interface_launch(
                        state,
                        kind,
                        uid,
                        profile_id=str(request["profile_id"] or ""),
                    ),
                    status=HTTPStatus.ACCEPTED,
                )
                return
            if action == "open-code":
                if payload != {}:
                    raise ValueError(
                        "Catalog Open Code request accepts an empty JSON object."
                    )
                self._send_json(
                    _open_catalog_code_server(state, kind, uid),
                    status=HTTPStatus.CREATED,
                )
                return
            editable = action == "edit-copy"
            if editable:
                request = _exact_json_object(
                    payload,
                    expected={"request_id"},
                    label="Catalog Edit in Workspace request",
                )
                request_id: Optional[str] = _canonical_request_uuid(
                    request["request_id"]
                )
            else:
                if payload != {}:
                    raise ValueError(
                        "Catalog View source request accepts an empty JSON object."
                    )
                request_id = None
            workspace = _open_catalog_workspace(
                state,
                kind,
                uid,
                editable=editable,
                install=False,
                request_id=request_id,
            )
            self._send_json(
                {"workspace": workspace},
                status=HTTPStatus.CREATED,
            )

        def _handle_configured_catalog_source_post(self, path: str) -> None:
            parts = path.split("/")
            if (
                len(parts) != 6
                or parts[3] != "sources"
                or parts[5] != "workspace"
            ):
                self._send_json(
                    {"error": "Unknown configured catalog source action"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            request = _exact_json_object(
                self._read_json_body(),
                expected={"schema"},
                label="Configured source Workspace request",
            )
            if request["schema"] != CONFIGURED_SOURCE_WORKSPACE_SCHEMA:
                raise ValueError(
                    "Configured source Workspace request schema is unsupported."
                )
            self._send_json(
                {
                    "workspace": _open_configured_catalog_source_workspace(
                        state, unquote(parts[4])
                    )
                },
                status=HTTPStatus.CREATED,
            )

        def _handle_run_get(self, path: str, query: Dict[str, List[str]]) -> None:
            parts = path.split("/")
            if len(parts) < 4:
                self._send_json(
                    {"error": "Missing run id"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            run_id = unquote(parts[3])
            runtime = _require_realm_runtime(state)
            ref = RunViewRef(run_id=run_id)
            if len(parts) == 4:
                self._send_json(
                    _realm_run_detail(
                        state,
                        ref=ref,
                        focused_candidate_id=_query_value(query, "candidate_id"),
                    )
                )
                return
            resource = parts[4]
            if resource in RUN_WORKBENCH_KINDS:
                self._send_json(
                    _realm_workbench_page(
                        state,
                        ref=ref,
                        kind=resource,
                        page_token=_query_value(query, "page_token"),
                        limit=_bounded_query_int(
                            query,
                            "limit",
                            default=RUN_WORKBENCH_DEFAULT_PAGE_SIZE,
                        ),
                    )
                )
                return
            if resource == "timeline":
                revision = _required_query_int(query, "revision")
                head_sequence = _required_query_int(query, "head_sequence")
                self._send_json(
                    runtime.run_views.timeline_page(
                        ref=ref,
                        expected_run_revision=revision,
                        expected_head_sequence=head_sequence,
                        after_sequence=_bounded_query_int(
                            query,
                            "after_sequence",
                            default=0,
                            minimum=0,
                        ),
                        limit=_bounded_query_int(
                            query,
                            "limit",
                            default=50,
                        ),
                    ).to_dict()
                )
                return
            if resource in {"shortlist", "review-collection"} and len(parts) == 5:
                revision_value = _query_value(query, "revision")
                revision = (
                    None
                    if revision_value is None
                    else _positive_query_value(revision_value, "revision")
                )
                before_revision_value = _query_value(query, "before_revision")
                before_revision = (
                    None
                    if before_revision_value is None
                    else _positive_query_value(
                        before_revision_value, "before_revision"
                    )
                )
                export = _query_value(query, "format") == "export"
                response: JsonDict = {
                    "schema": REVIEW_COLLECTION_RESPONSE_SCHEMA,
                    "run_id": run_id,
                }
                if export:
                    stored_collection = runtime.review_collections.read_for_run(
                        run_id=run_id,
                        revision=revision,
                    )
                    response["collection"] = (
                        None
                        if stored_collection is None
                        else stored_collection.export_dict()
                    )
                else:
                    shortlist = runtime.shortlists.read_for_run(
                        run_id=run_id,
                        revision=revision,
                    )
                    response["shortlist"] = (
                        None if shortlist is None else shortlist.to_dict()
                    )
                history = runtime.review_collections.history_for_run(
                    run_id=run_id,
                    before_revision=before_revision,
                )
                response["history"] = _public_shortlist_history(history)
                self._send_json(response)
                return
            if resource == "file":
                self._send_json(
                    {
                        "error": "Raw run-file access is unavailable for Realm runs; use bounded Workbench pages."
                    },
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            if resource == "operator-jobs":
                limit = _bounded_operator_job_limit(query)
                if len(parts) == 5:
                    self._send_json(
                        _realm_operator_jobs_payload(
                            state,
                            run_id=run_id,
                            limit=limit,
                        )
                    )
                    return
                if len(parts) == 6:
                    self._send_json(
                        _realm_operator_job_detail_payload(
                            state,
                            run_id=run_id,
                            job_id=unquote(parts[5]),
                        )
                    )
                    return
            self._send_json(
                {"error": "Unknown run resource"}, status=HTTPStatus.NOT_FOUND
            )

        def _handle_run_post(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) < 5:
                self._send_json(
                    {"error": "Missing run action"}, status=HTTPStatus.BAD_REQUEST
                )
                return
            run_id = unquote(parts[3])
            resource = parts[4]
            if resource == "candidate-comparison" and len(parts) == 5:
                self._send_json(
                    _compare_run_candidates(
                        state,
                        run_id=run_id,
                        payload=self._read_json_body(),
                    )
                )
                return
            if resource == "review-collection" and len(parts) == 5:
                response, status = _execute_review_collection_command(
                    state,
                    run_id=run_id,
                    payload=self._read_json_body(),
                )
                self._send_json(response, status=status)
                return
            if resource == "shortlist" and len(parts) == 5:
                response, status = _execute_shortlist_command(
                    state,
                    run_id=run_id,
                    payload=self._read_json_body(),
                )
                self._send_json(response, status=status)
                return
            if resource == "actions" and len(parts) == 5:
                payload = self._read_json_body()
                response, status = _execute_run_workbench_action(
                    state,
                    run_id=run_id,
                    payload=payload,
                )
                # Emit the durable queued response before scheduling execution.
                # Persisted Operator Jobs and canonical child runs, never these
                # process-local threads, remain lifecycle authority.
                self._send_json(response, status=status)
                job = response.get("job")
                if response.get("action") in {
                    "debug_run",
                    "environment_preview",
                } and isinstance(job, dict):
                    try:
                        _schedule_operator_job_execution(
                            state, job_id=str(job["job_id"])
                        )
                    except Exception:
                        # The 202 response is already complete.  Leave the
                        # durable queued head for startup reconciliation rather
                        # than attempting an invalid second HTTP response.
                        pass
                child_run = response.get("child_run")
                if response.get("action") == "evaluate_child_run" and isinstance(
                    child_run, dict
                ):
                    try:
                        _schedule_run_execution(
                            state,
                            run_id=str(child_run["run_id"]),
                        )
                    except Exception:
                        # The atomic child run and its seeded plan are already
                        # durable. Do not manufacture a second HTTP response or
                        # a Studio-owned execution record after the 202.
                        pass
                return
            if resource == "environment-preview-trust" and len(parts) == 5:
                self._send_json(
                    _approve_candidate_environment_preview_image(
                        state,
                        run_id=run_id,
                        payload=self._read_json_body(),
                    )
                )
                return
            if resource == "cancel" and len(parts) == 5:
                self._send_json(
                    _cancel_realm_run(
                        state,
                        run_id=run_id,
                        payload=self._read_json_body(),
                    )
                )
                return
            if resource == "operator-jobs" and len(parts) == 7 and parts[6] == "stop":
                payload = self._read_json_body()
                self._send_json(
                    _stop_realm_operator_job(
                        state,
                        run_id=run_id,
                        job_id=unquote(parts[5]),
                        payload=payload,
                    )
                )
                return
            self._send_json(
                {"error": "Unknown run action"}, status=HTTPStatus.NOT_FOUND
            )

        def _handle_selection_content_view_get(
            self, path: str, query: Dict[str, List[str]]
        ) -> None:
            parts = path.split("/")
            if len(parts) != 5:
                self._send_json(
                    {"error": "Unknown content view resource"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            handle = unquote(parts[3])
            resource = parts[4]
            if resource == "tree":
                _require_allowed_query_keys(
                    query,
                    allowed={"content_session_id", "page_token", "limit"},
                    label="content tree request",
                )
                session_id = _required_selection_content_session_query(query)
                self._send_json(
                    _selection_content_tree_page(
                        state,
                        handle=handle,
                        session_id=session_id,
                        page_token=_query_value(query, "page_token"),
                        limit=_bounded_query_int(
                            query,
                            "limit",
                            default=SELECTION_CONTENT_TREE_DEFAULT_PAGE_SIZE,
                            maximum=SELECTION_CONTENT_TREE_MAX_PAGE_SIZE,
                        ),
                    )
                )
                return
            if resource == "content":
                _require_allowed_query_keys(
                    query,
                    allowed={
                        "content_session_id",
                        "relative_path",
                        "offset",
                        "limit",
                    },
                    label="content byte request",
                )
                session_id = _required_selection_content_session_query(query)
                self._send_json(
                    _selection_content_byte_range(
                        state,
                        handle=handle,
                        session_id=session_id,
                        relative_path=_query_value(query, "relative_path"),
                        offset=_bounded_query_int(
                            query,
                            "offset",
                            default=0,
                            minimum=0,
                            maximum=2**63 - 1,
                        ),
                        limit=_bounded_query_int(
                            query,
                            "limit",
                            default=SELECTION_CONTENT_READ_DEFAULT_BYTES,
                            maximum=SELECTION_CONTENT_READ_MAX_BYTES,
                        ),
                    )
                )
                return
            self._send_json(
                {"error": "Unknown content view resource"},
                status=HTTPStatus.NOT_FOUND,
            )

        def _handle_selection_content_view_post(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) != 5 or parts[4] != "close":
                self._send_json(
                    {"error": "Unknown content view action"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            payload = _exact_json_object(
                self._read_json_body(),
                expected={"schema", "content_session_id"},
                label="content view close request",
            )
            if payload["schema"] != SELECTION_CONTENT_VIEW_CLOSE_REQUEST_SCHEMA:
                raise ValueError("Content view close request schema is unsupported.")
            self._send_json(
                _close_selection_content_view(
                    state,
                    handle=unquote(parts[3]),
                    session_id=_canonical_selection_content_session_id(
                        payload["content_session_id"]
                    ),
                )
            )

        def _handle_operator_job_get(self, path: str) -> None:
            parts = path.split("/")
            if len(parts) != 4:
                self._send_json(
                    {"error": "Unknown Operator Job resource"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            record = _operator_job_by_public_id(state, job_id=unquote(parts[3]))
            self._send_json(
                _realm_operator_job_detail_payload(
                    state,
                    run_id=record.plan.target.selection.source_id,
                    job_id=record.job_id,
                )
            )

        def _handle_operator_job_post(self, path: str) -> None:
            parts = path.split("/")
            if (
                len(parts) == 7
                and parts[4] == "outputs"
                and parts[6] in {"keep", "retry", "view"}
            ):
                payload = self._read_json_body()
                record = _operator_job_by_public_id(state, job_id=unquote(parts[3]))
                output_id = unquote(parts[5])
                if parts[6] == "view":
                    request = _exact_json_object(
                        payload,
                        expected={"schema", "content_session_id"},
                        label="Candidate try result View request",
                    )
                    if (
                        request["schema"]
                        != OPERATOR_JOB_OUTPUT_CONTENT_VIEW_REQUEST_SCHEMA
                    ):
                        raise ValueError(
                            "Candidate try result View request schema is unsupported."
                        )
                    self._send_json(
                        _view_realm_operator_job_output(
                            state,
                            record=record,
                            output_id=output_id,
                            requested_session_id=_optional_selection_content_session_id(
                                request["content_session_id"]
                            ),
                        ),
                        status=HTTPStatus.CREATED,
                    )
                elif parts[6] == "keep":
                    request = _exact_json_object(
                        payload,
                        expected={"request_id"},
                        label="Operator Job output Keep request",
                    )
                    request_id = _canonical_request_uuid(request["request_id"])
                    self._send_json(
                        _keep_realm_operator_job_output(
                            state,
                            record=record,
                            output_id=output_id,
                            request_id=request_id,
                        ),
                        status=HTTPStatus.CREATED,
                    )
                else:
                    if payload != {}:
                        raise ValueError(
                            "Operator Job output Retry accepts an empty JSON object."
                        )
                    self._send_json(
                        _retry_realm_operator_job_output(
                            state,
                            record=record,
                            output_id=output_id,
                        )
                    )
                return
            if len(parts) != 5 or parts[4] != "stop":
                self._send_json(
                    {"error": "Unknown Operator Job action"},
                    status=HTTPStatus.NOT_FOUND,
                )
                return
            record = _operator_job_by_public_id(state, job_id=unquote(parts[3]))
            self._send_json(
                _stop_realm_operator_job(
                    state,
                    run_id=record.plan.target.selection.source_id,
                    job_id=record.job_id,
                    payload=self._read_json_body(),
                )
            )

        def _read_json_body(self) -> JsonDict:
            length = int(self.headers.get("Content-Length", "0") or 0)
            if length <= 0:
                return {}
            return json.loads(self.rfile.read(length).decode("utf-8"))

        def _send_file(self, path: Path) -> None:
            if not path.exists() or not path.is_file():
                self.send_error(HTTPStatus.NOT_FOUND)
                return
            data = path.read_bytes()
            mime = mimetypes.guess_type(str(path))[0] or "application/octet-stream"
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", mime)
            # Studio is a local, source-served application.  Reusing a cached
            # HTML/JS/CSS generation across a server restart can pair a new API
            # contract with an old client, so every reload must revalidate the
            # one coherent static generation served by this process.
            self.send_header("Cache-Control", "no-store, max-age=0")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _send_interface_output_action_result_file(
            self,
            *,
            launch_id: str,
            request_id: str,
            relative_path: str,
            download: bool,
        ) -> None:
            data, media_type, file_name = (
                _interface_output_action_result_file_bytes(
                    state,
                    launch_id=launch_id,
                    request_id=request_id,
                    relative_path=relative_path,
                )
            )
            preview = not download and _selection_content_is_text(media_type)
            disposition = "inline" if preview else "attachment"
            content_type = (
                "text/plain; charset=utf-8"
                if preview
                else "application/octet-stream"
            )
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", content_type)
            self.send_header(
                "Content-Disposition",
                f"{disposition}; filename*=UTF-8''{quote(file_name, safe='')}",
            )
            self.send_header("X-Content-Type-Options", "nosniff")
            self.send_header("Content-Security-Policy", "default-src 'none'; sandbox")
            self.send_header("Cache-Control", "no-store, max-age=0")
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _send_static_file(self, relative_path: str) -> None:
            requested = (static_dir / unquote(relative_path)).resolve()
            if not _is_relative_to(requested, static_dir):
                self.send_error(HTTPStatus.NOT_FOUND)
                return
            self._send_file(requested)

        def _send_json(
            self, payload: JsonDict, status: HTTPStatus = HTTPStatus.OK
        ) -> None:
            data = json.dumps(
                _public_studio_payload(payload), indent=2, sort_keys=True
            ).encode("utf-8")
            self._send_json_bytes(data, status=status)

        def _send_json_bytes(
            self,
            data: bytes,
            status: HTTPStatus = HTTPStatus.OK,
            *,
            etag: Optional[str] = None,
        ) -> None:
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            # Run heads, capability facts, and job/workspace status are live
            # projections.  A browser cache must never combine an old head with
            # a newly restarted Studio client.  The optional ETag exists for
            # the client's explicit If-None-Match polling, not browser caching.
            self.send_header("Cache-Control", "no-store, max-age=0")
            if etag is not None:
                self.send_header("ETag", etag)
            self.send_header("Content-Length", str(len(data)))
            self.end_headers()
            self.wfile.write(data)

        def _send_not_modified(self, etag: str) -> None:
            self.send_response(HTTPStatus.NOT_MODIFIED)
            self.send_header("Cache-Control", "no-store, max-age=0")
            self.send_header("ETag", etag)
            self.end_headers()

        def log_message(self, format: str, *args: Any) -> None:
            return

    return OptPilotUiHandler


def _local_authoring_realm_exists(state: UiState) -> bool:
    return (
        state.cwd / ".optpilot-ui" / "realm" / "authority" / "realm.sqlite3"
    ).is_file()


def _refresh_realm_catalog_projections(
    state: UiState, *, max_age_seconds: Optional[float] = None
) -> None:
    """Expose authorized Realm catalog heads through leased read-only views.

    When ``max_age_seconds`` is a positive number and the previous complete
    refresh finished inside that window, the call returns immediately and the
    existing projection index keeps serving.  Callers on mutation paths (for
    example right after a catalog publish) must not pass it so they always
    observe the current heads.
    """

    if state.realm_runtime is None and not _local_authoring_realm_exists(state):
        return
    if max_age_seconds is not None and max_age_seconds > 0:
        with state._catalog_projection_lock:
            refreshed = state._catalog_projections_refreshed_monotonic
        if (
            refreshed is not None
            and time.monotonic() - refreshed < max_age_seconds
        ):
            return
    runtime = _package_plan_realm_runtime(state)
    heads: List[CatalogPackageHead] = []
    cursor: Optional[str] = None
    while True:
        page = runtime.catalog.list_heads(limit=200, after_package_id=cursor)
        heads.extend(page.heads)
        cursor = page.next_after_package_id
        if cursor is None:
            break

    retired_records: tuple[JsonDict, ...] = ()
    with state._catalog_projection_lock:
        previous_records = dict(state._realm_catalog_projections)
        current_records: Dict[str, JsonDict] = {}
        current_ids: Dict[Path, str] = {}
        created_projections: List[Any] = []
        replaced_records: List[JsonDict] = []
        try:
            for head in heads:
                existing = previous_records.get(head.package_id)
                if (
                    existing is not None
                    and existing.get("manifest_digest") == head.manifest_digest
                ):
                    projection = existing.get("projection")
                    try:
                        projection.heartbeat(
                            operation_id=(
                                "studio/catalog-projection/heartbeat/"
                                + uuid.uuid4().hex
                            ),
                            ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
                        )
                        root = projection.root_path.resolve()
                        if not root.is_dir():
                            raise RealmConflict(
                                "Catalog projection root is unavailable."
                            )
                        existing["root"] = root
                        current_records[head.package_id] = existing
                        current_ids[root] = head.package_id
                        previous_records.pop(head.package_id, None)
                        continue
                    except Exception:
                        # Keep the previous index intact until its complete
                        # replacement has been constructed successfully.
                        pass

                manifest = runtime.catalog.read_revision(
                    package_id=head.package_id,
                    revision=head.revision,
                )
                memberships = runtime.ledger.list_owner_memberships(
                    actor_principal_id=runtime.actor_principal_id,
                    owner_id=manifest.owner_id,
                    permission=OwnerPermission.BYTES_READ,
                )
                roots = tuple(
                    membership
                    for membership in memberships
                    if membership.role == CATALOG_PACKAGE_ROOT_ROLE
                    and membership.content_ref == manifest.root_ref
                )
                if len(memberships) != 1 or len(roots) != 1:
                    raise RealmIntegrityError(
                        "Catalog revision does not retain exactly one package root."
                    )
                membership = roots[0]
                coordinate = uuid.uuid4().hex
                projection = runtime.projection_service.project_read_only(
                    operation_id=f"studio/catalog-projection/{coordinate}",
                    actor_principal_id=runtime.actor_principal_id,
                    store_id=membership.store_id,
                    spec=ProjectionSpec(
                        owner_id=manifest.owner_id,
                        mappings=(TreeMapping(manifest.root_ref),),
                    ),
                    holder_id=f"studio-catalog-{coordinate}",
                    ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
                    consumer_kind="studio-catalog",
                    consumer_metadata={
                        "package_id": head.package_id,
                        "revision": head.revision,
                        "manifest_digest": head.manifest_digest,
                    },
                )
                created_projections.append(projection)
                root = projection.root_path.resolve()
                current_records[head.package_id] = {
                    "head": head,
                    "manifest": manifest,
                    "manifest_digest": head.manifest_digest,
                    "projection": projection,
                    "root": root,
                }
                current_ids[root] = head.package_id
                replaced = previous_records.pop(head.package_id, None)
                if replaced is not None:
                    replaced_records.append(replaced)
        except Exception:
            for projection in created_projections:
                try:
                    projection.close()
                except Exception:
                    pass
            raise
        retired_records = tuple([*previous_records.values(), *replaced_records])
        state._realm_catalog_projections = current_records
        state._realm_catalog_package_ids = current_ids
        state._catalog_projections_refreshed_monotonic = time.monotonic()
        if created_projections or retired_records:
            # Catalog heads changed; a cached index payload would keep
            # serving superseded projection roots until its TTL expired.
            state._catalog_index_cache = None
    for record in retired_records:
        projection = record.get("projection")
        if projection is not None:
            try:
                projection.close()
            except Exception:
                pass


def _borrow_realm_catalog_source_projection(
    state: UiState,
    source_path: Path,
    *,
    consumer_kind: str,
    consumer_metadata: Optional[Mapping[str, Any]] = None,
) -> Optional[CatalogSourceProjection]:
    """Give one action its own lease on the exact catalog revision it uses.

    The catalog index projection is intentionally swappable.  Actions never
    retain its filesystem path as their lifetime boundary; they mint the
    publisher-anchored package selection and acquire a separate consumer lease.
    """

    _refresh_realm_catalog_projections(
        state, max_age_seconds=state.catalog_refresh_ttl_seconds
    )
    resolved_source = source_path.resolve(strict=True)
    runtime = _package_plan_realm_runtime(state)
    with state._catalog_projection_lock:
        candidates: List[tuple[int, Path, JsonDict]] = []
        for root, package_id in state._realm_catalog_package_ids.items():
            try:
                relative = resolved_source.relative_to(root)
            except ValueError:
                continue
            record = state._realm_catalog_projections.get(package_id)
            if record is not None:
                candidates.append((len(root.parts), relative, record))
        if not candidates:
            return None
        _depth, relative_path, record = max(candidates, key=lambda item: item[0])
        head = record.get("head")
        if not isinstance(head, CatalogPackageHead):
            raise RealmIntegrityError("Catalog index has no exact package head.")
        manifest = record.get("manifest")
        if manifest is None:
            manifest = runtime.catalog.read_revision(
                package_id=head.package_id,
                revision=head.revision,
            )
            record["manifest"] = manifest
        relative_text = relative_path.as_posix()
        publishers = {
            application.publisher_id
            for application in manifest.applications
            if any(
                relative_text == claimed
                or relative_text.startswith(claimed.rstrip("/") + "/")
                for claimed in application.owned_paths
            )
        }
        if len(publishers) != 1:
            raise RealmIntegrityError(
                "Catalog source is not covered by exactly one publisher claim."
            )
        publisher_id = next(iter(publishers))
        selection = runtime.ledger.mint_catalog_package_application_selection(
            actor_principal_id=runtime.actor_principal_id,
            package_id=head.package_id,
            publisher_id=publisher_id,
            revision=head.revision,
        )
        coordinate = uuid.uuid4().hex
        metadata = {
            "package_id": head.package_id,
            "revision": head.revision,
            "publisher_id": publisher_id,
            "relative_path": relative_text,
            **dict(consumer_metadata or {}),
        }
        projection = runtime.projection_service.project_selection_read_only(
            operation_id=f"studio/catalog-consumer/{coordinate}",
            actor_principal_id=runtime.actor_principal_id,
            selection=selection,
            holder_id=f"studio-catalog-consumer-{coordinate}",
            ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
            consumer_kind=consumer_kind,
            consumer_metadata=metadata,
        )
    projected_source = (projection.root_path / relative_path).resolve()
    try:
        if not projected_source.exists():
            raise RealmIntegrityError(
                "Catalog consumer projection omitted its selected source."
            )
        if resolved_source.is_dir() != projected_source.is_dir():
            raise RealmIntegrityError(
                "Catalog consumer projection changed the selected source kind."
            )
        return CatalogSourceProjection(
            projection=projection,
            selection=selection,
            package_id=head.package_id,
            revision=head.revision,
            publisher_id=publisher_id,
            relative_path=relative_text,
            source_path=projected_source,
        )
    except Exception:
        projection.close()
        raise


def _borrow_catalog_entry_ref_projection(
    state: UiState,
    expected_config: str,
    value: Any,
    *,
    consumer_kind: str,
    consumer_metadata: Optional[Mapping[str, Any]] = None,
) -> Optional[CatalogSourceProjection]:
    """Project the exact Realm revision named by a public catalog entry ref."""

    selected = _catalog_entry_ref_selection(state, expected_config, value)
    if selected is None:
        return None
    entry_ref = selected.entry_ref
    runtime = _package_plan_realm_runtime(state)
    publisher_id = selected.publisher_id
    selection = selected.selection
    relative_text = selected.relative_path
    coordinate = uuid.uuid4().hex
    projection = runtime.projection_service.project_selection_read_only(
        operation_id=f"studio/catalog-entry/{coordinate}",
        actor_principal_id=runtime.actor_principal_id,
        selection=selection,
        holder_id=f"studio-catalog-entry-{coordinate}",
        ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
        consumer_kind=consumer_kind,
        consumer_metadata={
            "catalog_entry_ref": entry_ref.to_dict(),
            "publisher_id": publisher_id,
            **dict(consumer_metadata or {}),
        },
    )
    source_path = (
        projection.root_path / Path(*PurePosixPath(relative_text).parts)
    ).resolve()
    try:
        if not _is_relative_to(source_path, projection.root_path):
            raise RealmIntegrityError("Catalog entry escaped its exact projection.")
        if expected_config == "resource":
            if not source_path.is_dir():
                raise RealmNotFound("Catalog resource is unavailable.")
            actual_id = str(_resource_catalog_entry(source_path).get("id") or "")
        else:
            if not source_path.is_file():
                raise RealmNotFound("Catalog config is unavailable.")
            raw = _read_yaml(source_path)
            if raw.get("config") != expected_config:
                raise RealmIntegrityError("Catalog entry kind changed.")
            actual_id = str(raw.get("id") or raw.get("name") or source_path.stem)
        if actual_id != entry_ref.entry_id:
            raise RealmIntegrityError("Catalog entry id changed.")
        return CatalogSourceProjection(
            projection=projection,
            selection=selection,
            package_id=selected.package_id,
            revision=selected.revision,
            publisher_id=publisher_id,
            relative_path=relative_text,
            source_path=source_path,
        )
    except Exception:
        projection.close()
        raise


def _catalog_entry_ref_selection(
    state: UiState,
    expected_config: str,
    value: Any,
) -> Optional[CatalogSourceSelection]:
    """Resolve one public Catalog ref to its exact path-free Realm selection."""

    entry_ref = _catalog_entry_ref_from_value(state, expected_config, value)
    if entry_ref is None or entry_ref.source_kind != "realm-catalog":
        return None
    runtime = _package_plan_realm_runtime(state)
    assert entry_ref.source_revision is not None
    manifest = runtime.catalog.read_revision(
        package_id=entry_ref.source_id,
        revision=entry_ref.source_revision,
    )
    if manifest.digest != entry_ref.source_digest:
        raise RealmConflict("Catalog entry revision digest changed.")
    relative_text = entry_ref.focus_path
    publishers = {
        application.publisher_id
        for application in manifest.applications
        if any(
            relative_text == claimed
            or relative_text.startswith(claimed.rstrip("/") + "/")
            for claimed in application.owned_paths
        )
    }
    if len(publishers) != 1:
        raise RealmIntegrityError(
            "Catalog entry is not covered by exactly one publisher claim."
        )
    publisher_id = next(iter(publishers))
    selection = runtime.ledger.mint_catalog_package_application_selection(
        actor_principal_id=runtime.actor_principal_id,
        package_id=entry_ref.source_id,
        publisher_id=publisher_id,
        revision=entry_ref.source_revision,
    )
    return CatalogSourceSelection(
        entry_ref=entry_ref,
        selection=selection,
        package_id=entry_ref.source_id,
        revision=entry_ref.source_revision,
        publisher_id=publisher_id,
        relative_path=relative_text,
    )


def _release_catalog_workspace_projection(state: UiState, workspace_id: str) -> None:
    with state._catalog_projection_lock:
        projection = state._catalog_workspace_projections.pop(workspace_id, None)
    if projection is not None:
        projection.close()


def _catalog_origin_relative_path(value: Any, label: str) -> Path:
    text = str(value or "").strip()
    if text in {"", "."}:
        return Path()
    return _safe_relative_plan_path(text, label)


def _realize_catalog_workspace_reference(
    state: UiState, workspace: JsonDict
) -> JsonDict:
    """Rebuild one path-free read-only Workspace reference from its selection."""

    workspace_id = str(workspace.get("id") or "")
    origin = workspace.get("catalog_origin")
    if not workspace_id or not isinstance(origin, dict):
        raise RealmIntegrityError("Catalog Workspace origin is invalid.")
    selection_payload = origin.get("selection")
    if not isinstance(selection_payload, dict):
        raise RealmIntegrityError("Catalog Workspace has no exact selection.")
    selection = SelectionRef.from_dict(selection_payload)
    package_id = str(origin.get("package_id") or "")
    publisher_id = str(origin.get("publisher_id") or "")
    revision = origin.get("revision")
    if (
        selection.kind != "catalog-package"
        or selection.source_kind != "catalog"
        or selection.source_id != package_id
        or selection.entity_id != publisher_id
        or isinstance(revision, bool)
        or not isinstance(revision, int)
        or revision != selection.source_revision
    ):
        raise RealmIntegrityError("Catalog Workspace selection identity changed.")
    config_relative = _catalog_origin_relative_path(
        origin.get("config_relative_path"),
        "catalog Workspace config path",
    )
    source_root_relative = _catalog_origin_relative_path(
        origin.get("source_root_relative_path"),
        "catalog Workspace source root",
    )

    with state._catalog_projection_lock:
        current = state._catalog_workspace_projections.get(workspace_id)
    if current is not None:
        try:
            current.projection.heartbeat(
                operation_id=("studio/catalog-workspace/heartbeat/" + uuid.uuid4().hex),
                ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
            )
            root = current.root_path
            source_root = (root / source_root_relative).resolve()
            if not source_root.is_dir() or not _is_relative_to(source_root, root):
                raise RealmConflict("Catalog Workspace realization is unavailable.")
            realized = dict(workspace)
            realized["root"] = str(source_root)
            realized["source_root"] = str(source_root)
            realized["realization_state"] = "open"
            realized["reopen_required"] = False
            return realized
        except Exception:
            with state._catalog_projection_lock:
                if state._catalog_workspace_projections.get(workspace_id) is current:
                    state._catalog_workspace_projections.pop(workspace_id, None)
            try:
                current.close()
            except Exception:
                pass

    runtime = _package_plan_realm_runtime(state)
    coordinate = uuid.uuid4().hex
    projection = runtime.projection_service.project_selection_read_only(
        operation_id=f"studio/catalog-workspace/realize/{coordinate}",
        actor_principal_id=runtime.actor_principal_id,
        selection=selection,
        holder_id=f"studio-catalog-workspace-{coordinate}",
        ttl_seconds=CATALOG_PROJECTION_TTL_SECONDS,
        consumer_kind="catalog-workspace",
        consumer_metadata={
            "workspace_id": workspace_id,
            "package_id": package_id,
            "revision": revision,
            "publisher_id": publisher_id,
        },
    )
    root = projection.root_path.resolve()
    source_root = (root / source_root_relative).resolve()
    config_path = (root / config_relative).resolve()
    try:
        if not source_root.is_dir() or not _is_relative_to(source_root, root):
            raise RealmIntegrityError(
                "Catalog Workspace source root is absent from its selection."
            )
        if not _is_relative_to(config_path, root):
            raise RealmIntegrityError("Catalog Workspace config escaped its selection.")
        source = CatalogSourceProjection(
            projection=projection,
            selection=selection,
            package_id=package_id,
            revision=revision,
            publisher_id=publisher_id,
            relative_path=(
                config_relative.as_posix()
                if config_relative.parts
                else source_root_relative.as_posix()
            ),
            source_path=config_path if config_path.exists() else source_root,
        )
        with state._catalog_projection_lock:
            previous = state._catalog_workspace_projections.get(workspace_id)
            state._catalog_workspace_projections[workspace_id] = source
        if previous is not None:
            previous.close()
        realized = dict(workspace)
        realized["root"] = str(source_root)
        realized["source_root"] = str(source_root)
        realized["realization_state"] = "open"
        realized["reopen_required"] = False
        return realized
    except Exception:
        projection.close()
        raise


def _catalog_index_payload(state: UiState) -> JsonDict:
    ttl_seconds = state.catalog_refresh_ttl_seconds
    if ttl_seconds > 0:
        with state._catalog_projection_lock:
            cached = state._catalog_index_cache
        if cached is not None and time.monotonic() - cached[0] < ttl_seconds:
            # Consumers only read this payload (public views deep-copy the
            # entries they expose), so the built index can be shared as-is.
            return cached[1]
    with state._catalog_index_build_lock:
        # Catalog and compatibility hydrate concurrently on startup.  The
        # first request may have populated the cache while this request waited
        # for the single-flight build lock.
        if ttl_seconds > 0:
            with state._catalog_projection_lock:
                cached = state._catalog_index_cache
            if cached is not None and time.monotonic() - cached[0] < ttl_seconds:
                return cached[1]
        return _build_catalog_index_payload(state, ttl_seconds=ttl_seconds)


def _build_catalog_index_payload(
    state: UiState, *, ttl_seconds: float
) -> JsonDict:
    _refresh_catalog_package_roots(state)
    _refresh_realm_catalog_projections(state, max_age_seconds=ttl_seconds)
    with state._catalog_projection_lock:
        realm_roots = list(state._realm_catalog_package_ids)
        package_ids = dict(state._realm_catalog_package_ids)
        realm_records = dict(state._realm_catalog_projections)
    canonical_package_ids = set(package_ids.values())
    import_roots = [
        root
        for root in state.catalog_roots
        if _catalog_package_id(root) not in canonical_package_ids
    ]
    scan_roots = _dedupe_paths([*realm_roots, *import_roots])
    source_records: Dict[Path, JsonDict] = {}
    for root in realm_roots:
        package_id = package_ids[root]
        record = realm_records.get(package_id)
        head = record.get("head") if record is not None else None
        if not isinstance(head, CatalogPackageHead):
            raise RealmIntegrityError("Realm catalog index is missing its head.")
        source_records[root.resolve()] = {
            "source_kind": "realm-catalog",
            "source_id": head.package_id,
            "source_revision": head.revision,
            "source_digest": head.manifest_digest,
        }
    for root in import_roots:
        source_records[root.resolve()] = {
            "source_kind": "configured-filesystem-import",
            "source_id": _configured_catalog_source_id(root),
            "source_revision": None,
            "source_digest": None,
        }
    entries = _scan_catalog(
        scan_roots,
        package_ids=package_ids,
        source_records=source_records,
        state=state,
    )
    grouped = {config: [] for config in INDEXED_CONFIGS}
    for entry in entries:
        grouped.setdefault(entry["config"], []).append(entry)
    payload: JsonDict = {
        "roots": [
            _package_plan_catalog_destination(
                _catalog_package_id(root, package_ids=package_ids)
            )
            for root in scan_roots
        ],
        "environments": grouped.get("environment", []),
        "methods": grouped.get("method", []),
        "studies": grouped.get("study", []),
        "resources": _scan_catalog_resources(
            scan_roots,
            package_ids=package_ids,
            source_records=source_records,
        ),
        # Configured mutable sources are an independent control surface.  They
        # remain visible after a Realm head shadows their read-only scan entry.
        "sources": _configured_catalog_sources_payload(state),
        "builtins": {
            category: sorted(implementations)
            for category, implementations in BUILTIN_COMPONENTS.items()
        },
    }
    if ttl_seconds > 0:
        with state._catalog_projection_lock:
            state._catalog_index_cache = (time.monotonic(), payload)
    return payload


def _catalog_payload(state: UiState) -> JsonDict:
    """Return the public catalog index with no provider-local coordinates."""

    index = _catalog_index_payload(state)
    entries = [
        *index["environments"],
        *index["methods"],
        *index["studies"],
        *index["resources"],
    ]
    workspace_links = (
        _catalog_workspace_link_lookup(_list_ui_workspaces(state))
        if any(_realm_catalog_entry_link_key(item) is not None for item in entries)
        else {}
    )
    return {
        **index,
        "environments": [
            _public_catalog_entry_with_workspace(
                state,
                item,
                workspace_links=workspace_links,
            )
            for item in index["environments"]
        ],
        "methods": [
            _public_catalog_entry_with_workspace(
                state,
                item,
                workspace_links=workspace_links,
            )
            for item in index["methods"]
        ],
        "studies": [
            _public_catalog_entry_with_workspace(
                state,
                item,
                workspace_links=workspace_links,
            )
            for item in index["studies"]
        ],
        "resources": [
            _public_catalog_entry_with_workspace(
                state,
                item,
                workspace_links=workspace_links,
            )
            for item in index["resources"]
        ],
    }


def _catalog_search_tags(raw: Any) -> tuple[str, ...]:
    """Normalize an optional tag filter into lowercase tag tokens."""

    if raw is None:
        return ()
    if isinstance(raw, str):
        raw = [raw]
    if not isinstance(raw, list) or any(
        not isinstance(item, str) for item in raw
    ):
        raise ValueError("tags must be a list of tag strings.")
    return tuple(
        sorted({item.strip().lower() for item in raw if item.strip()})
    )


def _catalog_entry_search_text(entry: Mapping[str, Any]) -> str:
    """Combine the entry's searchable identity fields into one haystack."""

    parts: list[str] = []
    for key in ("id", "label", "description", "package_id", "qualified_id", "purpose"):
        value = entry.get(key)
        if isinstance(value, str):
            parts.append(value)
    summary = entry.get("summary")
    if isinstance(summary, Mapping):
        purpose = summary.get("purpose")
        if isinstance(purpose, str):
            parts.append(purpose)
    tags = entry.get("tags")
    if isinstance(tags, list):
        parts.extend(item for item in tags if isinstance(item, str))
    tasks = entry.get("tasks")
    if isinstance(tasks, list):
        from optpilot.task_vocabulary import task_search_words

        parts.extend(task_search_words(tasks))
    return " ".join(parts).lower()


def _search_catalog_entries(
    entries: Iterable[Mapping[str, Any]],
    *,
    query: str = "",
    tags: tuple[str, ...] = (),
) -> list[JsonDict]:
    """Filter catalog entries by free-text terms and required tags.

    Every whitespace-separated query term must appear somewhere in the
    entry's identity text (id, name, description, package, purpose, tags),
    and every requested tag must be declared on the entry exactly.
    """

    from optpilot.task_vocabulary import expand_search_terms

    # Each term also matches the kinds of work it could mean, so "optimize"
    # reaches something that declared optimize-policy without containing the
    # word itself.
    expanded_terms = [
        expand_search_terms(term) for term in query.split() if term
    ]
    terms = [term.lower() for term in query.split() if term]
    results: list[JsonDict] = []
    for entry in entries:
        if not isinstance(entry, Mapping):
            continue
        if tags:
            entry_tags = {
                item.strip().lower()
                for item in entry.get("tags", [])
                if isinstance(item, str)
            }
            if not set(tags).issubset(entry_tags):
                continue
        if expanded_terms:
            haystack = _catalog_entry_search_text(entry)
            if not all(
                any(option in haystack for option in options)
                for options in expanded_terms
            ):
                continue
        results.append(dict(entry))
    return results


def _realm_catalog_entry_link_key(
    entry: Mapping[str, Any],
) -> Optional[tuple[str, str, int, str]]:
    raw_ref = entry.get("ref")
    if (
        not isinstance(raw_ref, Mapping)
        or raw_ref.get("source_kind") != "realm-catalog"
    ):
        return None
    kind = entry.get("config")
    package_id = raw_ref.get("source_id")
    revision = raw_ref.get("source_revision")
    entry_id = entry.get("id")
    if (
        not isinstance(kind, str)
        or not isinstance(package_id, str)
        or isinstance(revision, bool)
        or not isinstance(revision, int)
        or not isinstance(entry_id, str)
    ):
        return None
    return kind, package_id, revision, entry_id


def _catalog_workspace_link_lookup(
    workspaces: Iterable[Mapping[str, Any]],
) -> Dict[tuple[str, str, int, str], JsonDict]:
    """Index exact Catalog origins without re-enumerating Workspace state."""

    links: Dict[tuple[str, str, int, str], JsonDict] = {}
    for workspace in workspaces:
        origin = workspace.get("catalog_origin")
        registered = workspace.get("registered_entries")
        if not isinstance(origin, Mapping) or not isinstance(registered, list):
            continue
        kind = origin.get("component_kind")
        package_id = origin.get("package_id")
        revision = origin.get("revision")
        if (
            not isinstance(kind, str)
            or not isinstance(package_id, str)
            or isinstance(revision, bool)
            or not isinstance(revision, int)
        ):
            continue
        for registered_entry in registered:
            if (
                not isinstance(registered_entry, Mapping)
                or registered_entry.get("kind") != kind
                or not isinstance(registered_entry.get("id"), str)
            ):
                continue
            key = kind, package_id, revision, str(registered_entry["id"])
            links.setdefault(
                key,
                {
                    "workspace_id": str(workspace.get("id") or ""),
                    "workspace_title": str(workspace.get("title") or "Workspace"),
                },
            )
    return links


def _public_catalog_entry_with_workspace(
    state: UiState,
    entry: JsonDict,
    *,
    workspace_links: Optional[
        Mapping[tuple[str, str, int, str], JsonDict]
    ] = None,
) -> JsonDict:
    """Expose only the durable editable result linked to one exact entry."""

    result = _public_catalog_entry(entry)
    interface = result.get("interface")
    raw_config = entry.get("raw_config")
    if isinstance(interface, Mapping) and interface and isinstance(
        raw_config, Mapping
    ):
        try:
            profiles = _compile_component_interface_profiles(
                raw_config.get("interface"),
                component_kind=str(result.get("config") or result.get("kind") or ""),
            )
        except (TypeError, ValueError):
            profiles = []
        if profiles:
            decorated_interface = _interface_summary_with_launch_capabilities(
                state, interface, profiles
            )
            result["interface"] = decorated_interface
            summary = result.get("summary")
            if isinstance(summary, dict) and isinstance(
                summary.get("interface"), Mapping
            ):
                summary["interface"] = deepcopy(decorated_interface)
    link_key = _realm_catalog_entry_link_key(result)
    if link_key is None:
        return result
    if workspace_links is None:
        workspace_links = _catalog_workspace_link_lookup(
            _list_ui_workspaces(state)
        )
    linked = workspace_links.get(link_key)
    if linked is not None:
        capability = dict(result["actions"]["create_editable_workspace"])
        capability.update(linked)
        capability["code"] = "workspace_exists"
        capability["reason"] = "Open the editable Workspace created from this version."
        result["actions"]["create_editable_workspace"] = capability
    return result


def _public_catalog_entry(entry: JsonDict) -> JsonDict:
    result = {
        key: deepcopy(value)
        for key, value in entry.items()
        if not str(key).startswith("_")
    }
    raw_ref = result.get("ref")
    realm_backed = (
        isinstance(raw_ref, dict) and raw_ref.get("source_kind") == "realm-catalog"
    )
    result["actions"] = {
        **(
            deepcopy(result.get("actions"))
            if isinstance(result.get("actions"), dict)
            else {}
        ),
        "create_editable_workspace": {
            "eligible": realm_backed,
            "code": "ready" if realm_backed else "catalog_source_unpublished",
            "reason": (
                "Create an editable workspace from this exact catalog revision."
                if realm_backed
                else "Open this local source folder as a Workspace, then check "
                "and register the version you want to reuse."
            ),
        },
    }
    return result


def _configured_catalog_source_id(root: Path) -> str:
    """Identify a package folder, preferring an identity that travels with it.

    A package's published update authority is derived from this value. Deriving
    it from the folder's location meant moving the folder produced a different
    authority, silently detaching the package from its own history. A package
    that declares its own identity is therefore identified by that instead.

    A folder with no identity keeps the location-derived value, so nothing
    changes for packages that have never been published.
    """

    if not root.is_absolute():
        raise ValueError("Configured catalog roots must be absolute paths.")
    try:
        identity = package_identity(root)
    except ValueError:
        # A malformed settings file must not take the whole catalog down at
        # startup. index_package records the error against this package, so it
        # is reported rather than swallowed, and the old value keeps it usable.
        identity = None
    if identity is not None:
        return (
            "import_"
            + request_digest(
                {
                    "identity": identity,
                    "schema": "optpilot.configured-catalog-source.v2",
                }
            )[:40]
        )
    return (
        "import_"
        + request_digest(
            {
                "schema": "optpilot.configured-catalog-source.v1",
                "root": str(root),
            }
        )[:40]
    )


def _configured_catalog_sources_payload(state: UiState) -> List[JsonDict]:
    """Describe configured package sources without exposing provider paths."""

    roots = [
        root.resolve()
        for root in _dedupe_paths(state.catalog_roots)
        if root.is_dir() and _looks_like_catalog_package(root)
    ]
    package_counts: Dict[str, int] = {}
    for root in roots:
        package_id = _catalog_package_id(root)
        package_counts[package_id] = package_counts.get(package_id, 0) + 1

    with state._catalog_projection_lock:
        realm_records = dict(state._realm_catalog_projections)
    # One plain index read, not _list_ui_workspaces: building the catalog must
    # not run that lister's opportunistic pruning of support references, and a
    # test pins exactly that. Workspace storage being unavailable is not a
    # reason the catalog cannot render, so an unreadable index reports
    # "not open" rather than failing the page.
    try:
        open_ids = {
            str(item.get("id") or "") for item in _read_workspace_index(state)
        }
    except Exception:
        open_ids = set()
    result: List[JsonDict] = []
    for root in roots:
        package_id = _catalog_package_id(root)
        head_record = realm_records.get(package_id)
        head = head_record.get("head") if head_record is not None else None
        capability = _configured_catalog_setup_capability(
            state,
            package_id=package_id,
            package_id_ambiguous=package_counts.get(package_id, 0) != 1,
            package_root=root,
        )
        result.append(
            {
                "schema": CONFIGURED_PACKAGE_SOURCE_SCHEMA,
                "source_id": _configured_catalog_source_id(root),
                "source_kind": "configured-filesystem",
                "package_id": package_id,
                "label": package_id,
                "mutable": True,
                "publication_scope": "whole-package",
                "realm_head": (
                    {
                        "package_id": head.package_id,
                        "revision": head.revision,
                        "manifest_digest": head.manifest_digest,
                    }
                    if isinstance(head, CatalogPackageHead)
                    else None
                ),
                # Whether the folder is already open as a Workspace, and
                # under which id. Without this the source entry could not
                # answer "can I prepare a package plan yet, and against
                # what?" -- the one thing a caller needs from it next.
                "workspace_id": _configured_source_open_workspace_id(
                    state, _configured_catalog_source_id(root), open_ids
                ),
                "actions": {"open_workspace": capability},
            }
        )
    return sorted(result, key=lambda item: (item["label"], item["source_id"]))


def _configured_source_open_workspace_id(
    state: UiState, source_id: str, open_ids: set[str]
) -> str:
    """The id of this source's Workspace, or "" when it is not open."""

    try:
        workspace_id = _configured_source_workspace_id(state, source_id)
    except Exception:
        return ""
    return workspace_id if workspace_id in open_ids else ""


def _configured_catalog_setup_capability(
    state: UiState,
    *,
    package_id: str,
    package_id_ambiguous: bool,
    package_root: Optional[Path] = None,
) -> JsonDict:
    code = "ready"
    eligible = True
    reason = (
        "Open this authorized folder as one editable Workspace without copying it, "
        "then check and register an exact immutable version through Workspace Setup."
    )
    if package_root is not None and _is_bundled_catalog_package(package_root):
        # Registration refuses these outright (they are OptPilot's own tracked
        # files). Advertising the first step as ready sent a person -- and a
        # model -- all the way to a refusal at the end; say it here instead.
        eligible = False
        code = "ships_with_optpilot"
        reason = (
            "This package ships with OptPilot and cannot be registered into. "
            "Copy its folder under a new name, give the copy a different "
            "identity, and register that instead."
        )
    elif package_id_ambiguous:
        eligible = False
        code = "configured_package_id_ambiguous"
        reason = (
            "More than one configured source has this package identity; make "
            "the configured package directory names unique before publishing."
        )
    else:
        try:
            _package_plan_package_id(package_id)
        except ValueError:
            eligible = False
            code = "configured_package_id_invalid"
            reason = (
                "This configured package directory name is not a valid Realm "
                "package identity."
            )
    return {
        "eligible": eligible,
        "code": code,
        "reason": reason,
        "request_schema": CONFIGURED_SOURCE_WORKSPACE_SCHEMA,
        "scope": "whole-package",
        "validation": "static-immutable-tree",
        "executes_authored_code": False,
        "copies_source": False,
    }


def _reauthorized_configured_catalog_source(
    state: UiState, source_id: str
) -> tuple[Path, str]:
    """Resolve an opaque source id only against the server's current roots."""

    if (
        not isinstance(source_id, str)
        or len(source_id) != len("import_") + 40
        or not source_id.startswith("import_")
    ):
        raise RealmNotFound("Configured catalog source is not available.")
    matched = state._configured_catalog_source_roots.get(source_id)
    if matched is None:
        raise RealmNotFound("Configured catalog source is not available.")
    package_id = _package_plan_package_id(matched.name)
    package_matches = {
        str(candidate)
        for candidate in state._configured_catalog_source_roots.values()
        if candidate.name == package_id
    }
    if len(package_matches) != 1:
        raise ConfiguredPackagePublishPublicError(
            "Configured package identity is ambiguous.",
            code="configured_package_id_ambiguous",
        )
    return matched, package_id


def _configured_source_workspace_id(state: UiState, source_id: str) -> str:
    return "configured_" + request_digest(
        {
            "actor_id": _studio_actor_id(state),
            "schema": CONFIGURED_SOURCE_WORKSPACE_SCHEMA,
            "source_id": source_id,
        }
    )[:24]


def _configured_source_publisher_id(package_id: str, source_id: str) -> str:
    from optpilot.realm.configured_package_ingress import (
        configured_package_publisher_id,
        configured_package_source_identity_digest,
    )

    return configured_package_publisher_id(
        package_id,
        configured_package_source_identity_digest(source_id),
    )


def _configured_source_workspace_authority(
    state: UiState, workspace: Mapping[str, Any]
) -> JsonDict:
    """Reauthorize one path-free configured-source Workspace binding."""

    if str(workspace.get("source_type") or "") != "configured-catalog-source":
        raise RealmConflict("Workspace is not bound to a configured Catalog source.")
    source_id = str(workspace.get("configured_source_id") or "")
    root, package_id = _reauthorized_configured_catalog_source(state, source_id)
    stored_root = Path(str(workspace.get("root") or "")).expanduser()
    try:
        stored_resolved = stored_root.resolve(strict=True)
        authorized_resolved = root.resolve(strict=True)
    except (FileNotFoundError, OSError) as error:
        raise RealmNotFound("Configured catalog source is not available.") from error
    if (
        stored_resolved != authorized_resolved
        or not stored_resolved.is_dir()
        or str(workspace.get("configured_package_id") or "") != package_id
    ):
        raise RealmConflict("Configured source Workspace authority changed.")
    return {
        "kind": "configured-catalog-source",
        "source_id": source_id,
        "package_id": package_id,
        "publisher_id": _configured_source_publisher_id(package_id, source_id),
        "root": authorized_resolved,
    }


def _open_configured_catalog_source_workspace(
    state: UiState, source_id: str
) -> JsonDict:
    """Open or reuse one no-copy Workspace for an authorized configured root."""

    root, package_id = _reauthorized_configured_catalog_source(state, source_id)
    if _is_bundled_catalog_package(root):
        # The only purpose of this workspace is to register the package, and
        # registration refuses OptPilot's own tracked folders. Opening it
        # would hand out an EDITABLE workspace over OptPilot's own files for
        # a job that cannot finish.
        raise _with_remedy(
            RealmConflict(
                f"{package_id} ships with OptPilot and cannot be registered "
                "into, so it is not opened as a Workspace."
            ),
            _remedy(
                "Copy its folder under a new name, give the copy a different "
                "identity value, and open that copy instead.",
                details={"package": package_id, "reason": "ships_with_optpilot"},
            ),
        )
    workspace_id = _configured_source_workspace_id(state, source_id)
    existing = _workspace_by_id(state, workspace_id)
    if existing is not None:
        _configured_source_workspace_authority(state, existing)
        return _public_studio_payload(existing)
    workspace = _upsert_ui_workspace(
        state,
        {
            "id": workspace_id,
            "title": package_id,
            "root": str(root),
            "source_root": str(root),
            "source_path": str(root),
            "source_type": "configured-catalog-source",
            "mode": "editable",
            "status": "ready",
            "description": (
                "Connected configured Catalog source. Changes edit the existing "
                "folder; removing this Workspace never deletes that folder."
            ),
            "attached_sessions": [],
            "registered_entries": [],
            "catalog_publications": [],
            "catalog_origin": {},
            "focus_paths": [],
            "registration_enabled": True,
            "configured_source_id": source_id,
            "configured_package_id": package_id,
            "provider_path_hidden": True,
            "created_at": _now_iso(),
            "ownership": "external-reference",
            "purpose": WorkspacePurpose.USER_PROJECT.value,
        },
    )
    return _public_studio_payload(workspace)


def _configured_package_yaml_shape_error(path: Path) -> Optional[str]:
    """Return one path-free reason when YAML exceeds the static parse budget."""

    event_count = 0
    depth = 0
    try:
        with path.open("r", encoding="utf-8") as handle:
            for event in yaml.parse(handle, Loader=yaml.SafeLoader):
                event_count += 1
                if event_count > CONFIGURED_PACKAGE_MAX_YAML_EVENTS:
                    return "yaml_event_count_exceeded"
                # Alias graphs can be cyclic and make later schema/semantic
                # traversal unbounded even though SafeLoader executes no code.
                if isinstance(event, yaml.events.AliasEvent):
                    return "yaml_alias_unsupported"
                if isinstance(event, yaml.events.CollectionStartEvent):
                    depth += 1
                    if depth > CONFIGURED_PACKAGE_MAX_YAML_DEPTH:
                        return "yaml_nesting_exceeded"
                elif isinstance(event, yaml.events.CollectionEndEvent):
                    depth -= 1
                    if depth < 0:
                        return "yaml_parse_failed"
    except (OSError, UnicodeError, yaml.YAMLError):
        return "yaml_parse_failed"
    return None if depth == 0 else "yaml_parse_failed"


def _configured_package_static_validator(immutable_root: Path) -> Any:
    """Return bounded path-free facts for one Core-owned immutable tree."""

    from optpilot.realm.configured_package_ingress import (
        ConfiguredPackageValidationFact,
        ConfiguredPackageValidationResult,
    )

    try:
        yaml_count = 0
        yaml_total_bytes = 0
        for directory, directories, files in os.walk(
            immutable_root, followlinks=False
        ):
            directories.sort()
            files.sort()
            for name in files:
                if Path(name).suffix.lower() not in {".yaml", ".yml"}:
                    continue
                yaml_count += 1
                if yaml_count > CONFIGURED_PACKAGE_MAX_YAML_FILES:
                    return ConfiguredPackageValidationResult(
                        accepted=False,
                        facts=(
                            ConfiguredPackageValidationFact(
                                code="config_file_count_exceeded",
                                severity="error",
                                count=yaml_count,
                            ),
                        ),
                    )
                file_stat = os.stat(
                    Path(directory) / name,
                    follow_symlinks=False,
                )
                if file_stat.st_size > CONFIGURED_PACKAGE_MAX_YAML_FILE_BYTES:
                    return ConfiguredPackageValidationResult(
                        accepted=False,
                        facts=(
                            ConfiguredPackageValidationFact(
                                code="config_file_too_large",
                                severity="error",
                                count=1,
                            ),
                        ),
                    )
                yaml_total_bytes += file_stat.st_size
                if yaml_total_bytes > CONFIGURED_PACKAGE_MAX_YAML_TOTAL_BYTES:
                    return ConfiguredPackageValidationResult(
                        accepted=False,
                        facts=(
                            ConfiguredPackageValidationFact(
                                code="config_bytes_exceeded",
                                severity="error",
                                count=yaml_count,
                            ),
                        ),
                    )
                shape_error = _configured_package_yaml_shape_error(
                    Path(directory) / name
                )
                if shape_error is not None:
                    return ConfiguredPackageValidationResult(
                        accepted=False,
                        facts=(
                            ConfiguredPackageValidationFact(
                                code=shape_error,
                                severity="error",
                                count=1,
                            ),
                        ),
                    )
    except Exception:
        return ConfiguredPackageValidationResult(
            accepted=False,
            facts=(
                ConfiguredPackageValidationFact(
                    code="static_validation_failed",
                    severity="error",
                    count=1,
                ),
            ),
        )

    try:
        validation = validate_package(
            immutable_root,
            check_source=True,
            check_setup_files=True,
            check_imports=False,
        )
    except Exception:
        return ConfiguredPackageValidationResult(
            accepted=False,
            facts=(
                ConfiguredPackageValidationFact(
                    code="static_validation_failed",
                    severity="error",
                    count=1,
                ),
            ),
        )

    kinds = ("environment", "method", "resource", "study")
    raw_counts = (
        validation.get("counts")
        if isinstance(validation.get("counts"), Mapping)
        else {}
    )
    entries = (
        validation.get("entries")
        if isinstance(validation.get("entries"), list)
        else []
    )
    counts = {
        kind: max(0, int(raw_counts.get(kind) or 0))
        for kind in kinds
    }
    invalid_counts = {
        kind: sum(
            1
            for entry in entries
            if isinstance(entry, Mapping)
            and entry.get("config") == kind
            and entry.get("valid") is not True
        )
        for kind in kinds
    }
    facts = [
        ConfiguredPackageValidationFact(
            code=f"recognized_{kind}", severity="info", count=counts[kind]
        )
        for kind in kinds
    ]
    package_error_count = len(
        validation.get("errors")
        if isinstance(validation.get("errors"), list)
        else []
    )
    if package_error_count:
        facts.append(
            ConfiguredPackageValidationFact(
                code="package_errors",
                severity="error",
                count=package_error_count,
            )
        )
    for kind in kinds:
        if invalid_counts[kind]:
            facts.append(
                ConfiguredPackageValidationFact(
                    code=f"invalid_{kind}",
                    severity="error",
                    count=invalid_counts[kind],
                )
            )
    ignored_count = max(0, int(raw_counts.get("ignored_yaml") or 0))
    if ignored_count:
        facts.append(
            ConfiguredPackageValidationFact(
                code="ignored_yaml",
                severity="warning",
                count=ignored_count,
            )
        )
    recognized_count = sum(counts.values())
    if recognized_count == 0:
        facts.append(
            ConfiguredPackageValidationFact(
                code="no_recognized_entries",
                severity="error",
                count=1,
            )
        )
    accepted = bool(validation.get("valid")) and recognized_count > 0
    if not accepted and not any(
        str(getattr(fact.severity, "value", fact.severity)) == "error"
        for fact in facts
    ):
        facts.append(
            ConfiguredPackageValidationFact(
                code="static_validation_rejected",
                severity="error",
                count=1,
            )
        )
    return ConfiguredPackageValidationResult(
        accepted=accepted,
        facts=tuple(
            sorted(
                facts,
                key=lambda fact: (
                    fact.code,
                    str(getattr(fact.severity, "value", fact.severity)),
                    fact.count,
                ),
            )
        ),
    )


def _configured_package_validation_payload(
    validation: Any,
) -> Optional[JsonDict]:
    if validation is None:
        return None
    return {
        "accepted": bool(validation.accepted),
        "digest": str(validation.digest),
        "facts": [
            {
                "code": str(fact.code),
                "severity": str(getattr(fact.severity, "value", fact.severity)),
                "count": int(fact.count),
            }
            for fact in validation.facts
        ],
    }


def _build_catalog_entry_ref(
    source_record: Optional[JsonDict],
    *,
    kind: str,
    entry_id: str,
    focus_path: str,
) -> Optional[CatalogEntryRef]:
    if not source_record:
        return None
    return CatalogEntryRef(
        source_kind=str(source_record.get("source_kind") or ""),
        source_id=str(source_record.get("source_id") or ""),
        source_revision=source_record.get("source_revision"),
        source_digest=source_record.get("source_digest"),
        kind=kind,
        entry_id=entry_id,
        focus_path=focus_path,
    )


def _scan_catalog(
    roots: Iterable[Path],
    *,
    package_ids: Optional[Mapping[Path, str]] = None,
    source_records: Optional[Mapping[Path, JsonDict]] = None,
    state: Optional[UiState] = None,
) -> List[JsonDict]:
    entries: List[JsonDict] = []
    seen = set()
    ids_by_package: Dict[tuple[str, str, str], Path] = {}
    for root in roots:
        if not root.exists():
            continue
        package_id = _catalog_package_id(root, package_ids=package_ids)
        package_metadata = _catalog_package_metadata(root, package_id)
        for path in _iter_yaml_files(root):
            if path in seen:
                continue
            seen.add(path)
            raw = _read_yaml(path)
            config = raw.get("config")
            if (
                config not in INDEXED_CONFIGS
                or raw.get("apiVersion") != AUTHORING_API_VERSION
            ):
                continue
            entry_id = str(raw.get("id") or raw.get("name") or path.stem)
            if config in REGISTERABLE_CONFIGS:
                _reject_duplicate_catalog_id(
                    ids_by_package, package_id, config, entry_id, path
                )
            entry = _catalog_entry(
                path,
                raw,
                package_id=package_id,
                package_root=root,
                source_record=(source_records or {}).get(root.resolve()),
            )
            entry["package_metadata"] = deepcopy(package_metadata)
            if config == "study":
                entry["validation"] = _validate_study(path, state=state)
                entry["validation"]["path"] = entry["path"]
            entries.append(entry)
    return sorted(
        entries, key=lambda item: (item["config"], item["label"], item["path"])
    )


def _catalog_entry(
    path: Path,
    raw: JsonDict,
    *,
    package_id: str = "",
    package_root: Optional[Path] = None,
    source_record: Optional[JsonDict] = None,
) -> JsonDict:
    config = raw["config"]
    # `title` first: a study's `name` is its identifier, so it is the only
    # kind whose displayed label would otherwise always be a slug.
    label = raw.get("title") or raw.get("name") or raw.get("id") or path.stem
    interface_profiles: List[InterfaceLaunchProfile] = []
    interface_error = ""
    try:
        interface_profiles = _compile_component_interface_profiles(
            raw.get("interface"),
            component_kind=config,
        )
    except (TypeError, ValueError) as exc:
        interface_error = str(exc)
    interface = _interface_summary(interface_profiles)
    entry_id = str(raw.get("id") or raw.get("name") or path.stem)
    catalog_key = _qualified_catalog_id(package_id, config, entry_id)
    entry_ref = _build_catalog_entry_ref(
        source_record,
        kind=config,
        entry_id=entry_id,
        focus_path=(
            path.resolve().relative_to(package_root.resolve()).as_posix()
            if package_root is not None
            else path.name
        ),
    )
    logical_path = (
        _package_plan_catalog_destination(
            package_id,
            path.resolve().relative_to(package_root.resolve()).as_posix(),
        )
        if package_id and package_root is not None
        else str(path)
    )
    entry: JsonDict = {
        "uid": entry_ref.token() if entry_ref is not None else catalog_key,
        "ref": entry_ref.to_dict() if entry_ref is not None else None,
        "id": entry_id,
        "package": package_id,
        "package_id": package_id,
        "qualified_id": catalog_key,
        "catalog_key": catalog_key,
        "label": str(label),
        "kind": config,
        "config": config,
        "path": logical_path,
        "_source_path": str(path.resolve()),
        "description": str(raw.get("description", "")),
        "tags": list(raw.get("tags", []) or []),
        "tasks": list(raw.get("tasks", []) or []),
        "summary": {},
        "raw_config": deepcopy(raw),
        "yaml": yaml.safe_dump(raw, sort_keys=False),
    }
    if interface:
        entry["interface"] = interface
    if interface_error:
        entry["interface_error"] = interface_error
    if config == "environment":
        candidate = raw.get("candidate", {})
        candidate_format = candidate.get("format")
        editable = []
        files = (
            candidate.get("files", {})
            if isinstance(candidate.get("files"), dict)
            else candidate
        )
        for item in files.get("editable", []) or []:
            if isinstance(item, dict) and item.get("path"):
                editable.append(str(item["path"]))
        entry["summary"] = {
            "evaluate_type": _evaluator_mode(raw.get("evaluator", {})),
            "candidate_format": candidate_format,
            "runtime": _environment_runtime_summary(raw),
            "editable_files": editable,
            "capabilities": [
                capability.get("id")
                for capability in raw.get("capabilities", []) or []
                if isinstance(capability, dict) and capability.get("id")
            ],
            "interface": deepcopy(interface),
            "metrics": list(raw.get("metrics", {}).get("keys", []) or []),
        }
    elif config == "method":
        accepts = raw.get("accepts", {}) if isinstance(raw.get("accepts"), dict) else {}
        requires = (
            accepts.get("requires", {})
            if isinstance(accepts.get("requires"), dict)
            else {}
        )
        entrypoint = (
            raw.get("entrypoint", {}) if isinstance(raw.get("entrypoint"), dict) else {}
        )
        settings = (
            raw.get("settings", {}) if isinstance(raw.get("settings"), dict) else {}
        )
        entry["summary"] = {
            "implementation_type": _entrypoint_mode(entrypoint),
            "implementation": entrypoint.get("python") or entrypoint.get("command"),
            "protocol": entrypoint.get("protocol", "batch"),
            "runtime": _method_runtime_summary(raw),
            "batch_size": settings.get("batchSize"),
            "candidate_formats": list(accepts.get("formats", []) or []),
            "required_context": list(requires.get("context", []) or []),
            "required_capabilities": list(requires.get("capabilities", []) or []),
            "interface": deepcopy(interface),
        }
    elif config == "study":
        environment_ref = raw.get("environmentConfig")
        method_ref = raw.get("methodConfig")
        environment_entry_ref = _catalog_reference_entry_ref(
            package_root=package_root,
            config_path=path,
            value=environment_ref,
            expected_kind="environment",
            source_record=source_record,
        )
        method_entry_ref = _catalog_reference_entry_ref(
            package_root=package_root,
            config_path=path,
            value=method_ref,
            expected_kind="method",
            source_record=source_record,
        )
        entry["summary"] = {
            "name": raw.get("name"),
            "description": raw.get("description"),
            "tags": list(raw.get("tags", []) or []),
        "tasks": list(raw.get("tasks", []) or []),
            "environment": environment_ref,
            "environmentRef": (
                environment_entry_ref.to_dict()
                if environment_entry_ref is not None
                else None
            ),
            "method": method_ref,
            "methodRef": (
                method_entry_ref.to_dict() if method_entry_ref is not None else None
            ),
            "objective": raw.get("objective", {}),
            "budget": raw.get("budget", {}),
            "execution": raw.get("execution", {}),
            "evidence": raw.get("evidence", {}),
            "reproducibility": raw.get("reproducibility", {}),
        }
    return entry


def _catalog_reference_entry_ref(
    *,
    package_root: Optional[Path],
    config_path: Path,
    value: Any,
    expected_kind: str,
    source_record: Optional[JsonDict],
) -> Optional[CatalogEntryRef]:
    """Turn a package-local study binding into an exact focused catalog ref."""

    if not value or package_root is None or source_record is None:
        return None
    resolved = _resolve_config_path(value, config_path)
    try:
        relative = resolved.relative_to(package_root.resolve()).as_posix()
    except ValueError:
        return None
    if not resolved.is_file():
        return None
    raw = _read_yaml(resolved)
    if raw.get("config") != expected_kind:
        return None
    entry_id = str(raw.get("id") or raw.get("name") or resolved.stem)
    return _build_catalog_entry_ref(
        source_record,
        kind=expected_kind,
        entry_id=entry_id,
        focus_path=relative,
    )


def _scan_catalog_resources(
    roots: Iterable[Path],
    *,
    package_ids: Optional[Mapping[Path, str]] = None,
    source_records: Optional[Mapping[Path, JsonDict]] = None,
) -> List[JsonDict]:
    resources: List[JsonDict] = []
    seen: set[Path] = set()
    ids_by_package: Dict[tuple[str, str, str], Path] = {}
    for catalog_root in roots:
        package_id = _catalog_package_id(
            catalog_root,
            package_ids=package_ids,
        )
        package_metadata = _catalog_package_metadata(catalog_root, package_id)
        resources_root = catalog_root / "resources"
        if not resources_root.exists() or not resources_root.is_dir():
            continue
        for resource_dir in sorted(
            item for item in resources_root.iterdir() if item.is_dir()
        ):
            resolved = resource_dir.resolve()
            if resolved in seen:
                continue
            seen.add(resolved)
            entry = _resource_catalog_entry(
                resolved,
                package_id=package_id,
                package_root=catalog_root,
                source_record=(source_records or {}).get(catalog_root.resolve()),
            )
            entry["package_metadata"] = deepcopy(package_metadata)
            _reject_duplicate_catalog_id(
                ids_by_package, package_id, "resource", entry["id"], resolved
            )
            resources.append(entry)
    return sorted(resources, key=lambda item: (item["label"], item["path"]))


def _resource_catalog_entry(
    path: Path,
    *,
    package_id: str = "",
    package_root: Optional[Path] = None,
    source_record: Optional[JsonDict] = None,
) -> JsonDict:
    manifest_path, manifest = _resource_manifest(path)
    readme = _first_existing_file(path, ["README.md", "readme.md", "README.txt"])
    manifest_label = str(manifest.get("name") or manifest.get("id") or "").strip()
    label = manifest_label or path.name
    description = ""
    tags: List[str] = []
    if readme:
        try:
            text = readme.read_text(encoding="utf-8", errors="replace")
        except OSError:
            text = ""
        label = manifest_label or _readme_title(text) or label
        description = str(
            manifest.get("description") or ""
        ).strip() or _readme_description(text)
        tags = _resource_tags(path, text)
    else:
        description = str(manifest.get("description") or "").strip()
        tags = ["resource"]
    if isinstance(manifest.get("tags"), list):
        tags = ["resource", *[str(tag) for tag in manifest.get("tags", []) if str(tag)]]
    tags = list(dict.fromkeys(tags))[:4]
    interface_profiles: List[InterfaceLaunchProfile] = []
    interface_error = ""
    try:
        interface_profiles = _compile_component_interface_profiles(
            manifest.get("interface"),
            component_kind="resource",
        )
    except (TypeError, ValueError) as exc:
        interface_error = str(exc)
    interface = _interface_summary(interface_profiles)
    resource_id = str(manifest.get("id") or _slug_text(path.name))
    declared_purpose = str(manifest.get("purpose") or "").strip()
    if declared_purpose not in RESOURCE_PURPOSES:
        declared_purpose = ""
    public_config = _resource_public_config(
        manifest,
        resource_id=resource_id,
        label=label,
        description=description,
        tags=tags,
        interface=manifest.get("interface"),
    )
    summary: JsonDict = {
        "readme": _relative_path(readme, path) if readme else "",
        "file_count": _count_resource_files(path),
        "editable": False,
        "interface": deepcopy(interface),
        "purpose": declared_purpose or None,
    }
    if manifest_path:
        summary["manifest"] = _relative_path(manifest_path, path)
    catalog_key = _qualified_catalog_id(package_id, "resource", resource_id)
    entry_ref = _build_catalog_entry_ref(
        source_record,
        kind="resource",
        entry_id=resource_id,
        focus_path=(
            path.resolve().relative_to(package_root.resolve()).as_posix()
            if package_root is not None
            else path.name
        ),
    )
    logical_path = (
        _package_plan_catalog_destination(
            package_id,
            path.resolve().relative_to(package_root.resolve()).as_posix(),
        )
        if package_id and package_root is not None
        else str(path)
    )
    entry: JsonDict = {
        "uid": entry_ref.token() if entry_ref is not None else catalog_key,
        "ref": entry_ref.to_dict() if entry_ref is not None else None,
        "id": resource_id,
        "package": package_id,
        "package_id": package_id,
        "qualified_id": catalog_key,
        "catalog_key": catalog_key,
        "label": label,
        "kind": "resource",
        "config": "resource",
        "path": logical_path,
        "_source_path": str(path.resolve()),
        "description": description,
        "purpose": declared_purpose or None,
        "tags": tags,
        "summary": summary,
        "raw_config": deepcopy(public_config),
        "yaml": yaml.safe_dump(public_config, sort_keys=False),
    }
    if manifest_path:
        entry["config_path"] = (
            _package_plan_catalog_destination(
                package_id,
                manifest_path.resolve().relative_to(package_root.resolve()).as_posix(),
            )
            if package_id and package_root is not None
            else str(manifest_path)
        )
        entry["_config_source_path"] = str(manifest_path.resolve())
    if interface:
        entry["interface"] = interface
    if interface_error:
        entry["interface_error"] = interface_error
    return entry


def _resource_public_config(
    manifest: JsonDict,
    *,
    resource_id: str,
    label: str,
    description: str,
    tags: List[str],
    interface: Any,
) -> JsonDict:
    if (
        manifest.get("apiVersion") == AUTHORING_API_VERSION
        and manifest.get("config") == "resource"
    ):
        return dict(manifest)
    config: JsonDict = {
        "apiVersion": AUTHORING_API_VERSION,
        "config": "resource",
        "id": resource_id,
    }
    if label:
        config["name"] = label
    if description:
        config["description"] = description
    if tags:
        config["tags"] = tags
    if isinstance(interface, dict) and interface:
        config["interface"] = deepcopy(interface)
    return config


def _catalog_package_id(
    root: Path,
    *,
    package_ids: Optional[Mapping[Path, str]] = None,
) -> str:
    resolved = root.resolve()
    if package_ids is not None:
        package_id = package_ids.get(resolved)
        if package_id:
            return package_id
    return resolved.name


def _catalog_package_metadata(root: Path, package_id: str) -> JsonDict:
    """Return safe, human-facing metadata for one catalog package."""

    metadata: JsonDict = {
        "id": package_id,
        "title": package_id,
        "category": "local",
    }
    try:
        settings = load_package_settings(root)
    except (OSError, ValueError):
        return metadata
    if settings is None:
        return metadata
    declared = package_settings_payload(settings)
    metadata["title"] = str(declared.get("title") or package_id)
    metadata["category"] = str(declared.get("category") or "local")
    if declared.get("description"):
        metadata["description"] = declared["description"]
    if isinstance(declared.get("paper"), Mapping):
        metadata["paper"] = deepcopy(declared["paper"])
    return metadata


def _qualified_catalog_id(package_id: str, kind: str, entry_id: str) -> str:
    package = package_id or "workspace"
    return f"{package}/{kind}/{entry_id}"


def _reject_duplicate_catalog_id(
    seen: Dict[tuple[str, str, str], Path],
    package_id: str,
    kind: str,
    entry_id: str,
    path: Path,
) -> None:
    key = (package_id, kind, entry_id)
    previous = seen.get(key)
    if previous is not None and previous.resolve() != path.resolve():
        raise ValueError(
            f"Duplicate catalog id {entry_id!r} for {kind!r} in package {package_id!r}: "
            f"{previous} and {path}"
        )
    seen[key] = path


def _resource_manifest(path: Path) -> tuple[Optional[Path], JsonDict]:
    for name in [
        "optpilot.resource.yaml",
        "optpilot-resource.yaml",
        ".optpilot/resource.yaml",
        ".optpilot/interface.yaml",
    ]:
        manifest_path = path / name
        if not manifest_path.exists() or not manifest_path.is_file():
            continue
        raw = _read_yaml(manifest_path)
        if (
            raw.get("apiVersion") == AUTHORING_API_VERSION
            and raw.get("config") == "resource"
        ):
            return manifest_path, raw
        if isinstance(raw.get("interface"), dict):
            return manifest_path, {"interface": raw.get("interface")}
    return None, {}


def _first_existing_file(root: Path, names: List[str]) -> Optional[Path]:
    for name in names:
        path = root / name
        if path.exists() and path.is_file():
            return path
    return None


def _readme_title(text: str) -> str:
    for line in text.splitlines():
        stripped = line.strip()
        if stripped.startswith("#"):
            return stripped.lstrip("#").strip()
    return ""


def _readme_description(text: str) -> str:
    for line in text.splitlines():
        stripped = line.strip()
        if stripped and not stripped.startswith("#"):
            return _cap_text(stripped, 220)
    return ""


def _resource_tags(path: Path, readme_text: str) -> List[str]:
    tags = ["resource"]
    suffixes = {item.suffix.lower() for item in path.rglob("*") if item.is_file()}
    if ".py" in suffixes:
        tags.append("python")
    if ".md" in suffixes:
        tags.append("docs")
    if any(suffix in suffixes for suffix in {".csv", ".json", ".yaml", ".yml"}):
        tags.append("data")
    if "simulation" in readme_text.lower() or "simulator" in readme_text.lower():
        tags.append("simulation")
    return tags[:4]


def _count_resource_files(path: Path) -> int:
    count = 0
    for item in path.rglob("*"):
        if item.is_file() and not any(
            part in EXCLUDED_SCAN_DIRS for part in item.parts
        ):
            count += 1
            if count >= 999:
                break
    return count


def _compile_component_interface_profiles(
    raw: Any,
    *,
    component_kind: str,
) -> List[InterfaceLaunchProfile]:
    """Use the public compiler as Studio's sole interface grammar parser."""

    profiles = list(
        compile_interface_launch_profiles(
            raw,
            component_kind=component_kind,
        )
    )
    for profile in profiles:
        _require_unreserved_interface_environment(profile)
    return profiles


def _safe_interface_profile_summary(profile: InterfaceLaunchProfile) -> JsonDict:
    """Return launch metadata without authored or resolved secret values."""

    setup = profile.runtime.setup
    container = profile.runtime.container
    runtime: JsonDict = {
        "sandbox": profile.runtime.sandbox,
        "setupDeclared": setup is not None,
        "setupStepCount": len(setup.steps) if setup is not None else 0,
    }
    if container is not None:
        runtime["container"] = {
            "engine": container.engine,
            "image": container.image,
            "buildTag": container.build.tag if container.build is not None else None,
            "platform": container.platform,
        }
    result = {
        "id": profile.profile_id,
        "label": profile.label,
        "description": profile.description,
        "command": list(profile.command),
        "cwd": profile.cwd,
        "runtime": runtime,
        "grants": {
            "envFromHost": list(profile.grants.env_from_host),
            "network": profile.grants.network,
            "secretsFromHost": list(profile.grants.secrets_from_host),
        },
        "resources": profile.resources.to_dict(),
        "timeoutSeconds": profile.timeout_seconds,
        "presentation": profile.presentation.to_dict(),
        "accepts": profile.accepts.to_dict(),
    }
    if profile.outputs:
        result["outputs"] = True
    return result


def _interface_summary(profiles: Iterable[InterfaceLaunchProfile]) -> JsonDict:
    profile_list = list(profiles)
    if not profile_list:
        return {}
    profile_summaries = [
        _safe_interface_profile_summary(profile) for profile in profile_list
    ]
    default_profile_id = ""
    if any(profile.profile_id == "default" for profile in profile_list):
        default_profile_id = "default"
    elif len(profile_list) == 1:
        default_profile_id = profile_list[0].profile_id
    return {
        "defaultProfileId": default_profile_id,
        "profileCount": len(profile_summaries),
        "profiles": profile_summaries,
    }


def _interface_launch_runtime_capability(state: UiState) -> JsonDict:
    """Expose one path-free readiness gate for every Studio interface launch."""

    try:
        health = state.workspace_runtime.health()
    except Exception:
        health = {"ok": False, "available": False}
    if health.get("ok"):
        return {
            "eligible": True,
            "code": "ready",
            "reason": "Open this interface in an isolated launch runtime.",
        }
    probe_timed_out = bool(health.get("probe_timed_out"))
    if not health.get("available"):
        reason = (
            "Interface launch needs the Sandbox. Install or configure Docker "
            "or Podman, then refresh Studio."
        )
    elif probe_timed_out:
        # The engine answered nothing rather than answering "stopped": never
        # tell an operator to start a runtime that may already be running.
        reason = (
            "Interface launch could not confirm the Sandbox: Docker or Podman "
            "did not answer the readiness probe in time. Wait for the engine "
            "to settle, then retry."
        )
    else:
        reason = (
            "Interface launch needs the Sandbox. Start Docker or Podman, "
            "then refresh Studio."
        )
    return {
        "eligible": False,
        "code": "interface_runtime_unavailable",
        "reason": reason,
        "probe_timed_out": probe_timed_out,
    }


def _require_interface_launch_runtime(state: UiState) -> None:
    capability = _interface_launch_runtime_capability(state)
    if not capability.get("eligible"):
        raise InterfaceLaunchRuntimeUnavailable(str(capability["reason"]))


def _interface_profile_launch_capability(
    state: UiState,
    profile: InterfaceLaunchProfile,
    *,
    runtime_capability: Optional[JsonDict] = None,
) -> JsonDict:
    """Return the selected-profile action truth without exposing secret values."""

    if profile.runtime.sandbox == "container":
        return {
            "supported": False,
            "eligible": False,
            "code": "interface_profile_runtime_unsupported",
            "reason": (
                "This profile declares its own container runtime, which the "
                "Workspace interface launcher cannot substitute."
            ),
            "profile_id": profile.profile_id,
        }
    runtime_action = dict(
        runtime_capability or _interface_launch_runtime_capability(state)
    )
    runtime_action["profile_id"] = profile.profile_id
    if not runtime_action.get("eligible"):
        return runtime_action
    _resolved, missing = _resolve_declared_env_from_host(
        state, _interface_launch_env_requirements(profile)
    )
    if missing:
        joined = ", ".join(missing)
        return {
            "supported": True,
            "eligible": False,
            "code": "interface_environment_missing",
            "reason": (
                f"Add {joined} in Studio Settings or export "
                f"{'them' if len(missing) != 1 else 'it'} before launching."
            ),
            "profile_id": profile.profile_id,
        }
    return runtime_action


def _interface_summary_with_launch_capabilities(
    state: UiState,
    summary: Mapping[str, Any],
    profiles: Iterable[InterfaceLaunchProfile],
) -> JsonDict:
    """Attach the same action contract used by Catalog and Workspaces."""

    result = deepcopy(dict(summary))
    profile_list = list(profiles)
    if not result or not profile_list:
        return result
    runtime_capability = _interface_launch_runtime_capability(state)
    capabilities = {
        profile.profile_id: _interface_profile_launch_capability(
            state,
            profile,
            runtime_capability=runtime_capability,
        )
        for profile in profile_list
    }
    for profile_summary in result.get("profiles", []) or []:
        if not isinstance(profile_summary, dict):
            continue
        profile_summary["launch"] = deepcopy(
            capabilities.get(str(profile_summary.get("id") or ""), {})
        )
    eligible = [item for item in capabilities.values() if item.get("eligible")]
    default_profile_id = str(result.get("defaultProfileId") or "")
    declared_default = capabilities.get(default_profile_id)
    aggregate = (
        declared_default
        if declared_default is not None and declared_default.get("eligible")
        else (
            eligible[0]
            if eligible
            else declared_default or next(iter(capabilities.values()))
        )
    )
    result["actions"] = {"launch": deepcopy(aggregate)}
    return result


def _select_interface_profile(
    profiles: Iterable[InterfaceLaunchProfile],
    profile_id: Optional[str],
) -> InterfaceLaunchProfile:
    profile_list = list(profiles)
    if not profile_list:
        raise ValueError("This component does not declare a launchable interface.")
    requested = str(profile_id or "").strip()
    if requested:
        for profile in profile_list:
            if profile.profile_id == requested:
                return profile
        available = ", ".join(profile.profile_id for profile in profile_list)
        raise ValueError(
            f"Unknown interface profile {requested!r}; available profiles: {available}."
        )
    for profile in profile_list:
        if profile.profile_id == "default":
            return profile
    if len(profile_list) == 1:
        return profile_list[0]
    available = ", ".join(profile.profile_id for profile in profile_list)
    raise ValueError(
        "profile_id is required when an interface declares multiple named "
        f"profiles; available profiles: {available}."
    )


def _select_launchable_interface_profile(
    state: UiState,
    profiles: Iterable[InterfaceLaunchProfile],
    profile_id: Optional[str],
) -> InterfaceLaunchProfile:
    """Respect an explicit selection, otherwise prefer an eligible profile."""

    profile_list = list(profiles)
    selected = _select_interface_profile(profile_list, profile_id)
    if str(profile_id or "").strip():
        return selected
    if _interface_profile_launch_capability(state, selected).get("eligible"):
        return selected
    for profile in profile_list:
        if _interface_profile_launch_capability(state, profile).get("eligible"):
            return profile
    return selected


def _workspace_payload(state: UiState) -> JsonDict:
    return {
        "cwd": str(state.cwd),
        "catalog_roots": [str(path) for path in state.catalog_roots],
        "run_roots": [str(path) for path in state.run_roots],
        "jobs_dir": str(state.jobs_dir),
        "sessions_dir": str(state.sessions_dir),
        "workspaces_dir": str(state.workspaces_dir),
        "code_server": state.code_server_status(),
    }


def _read_ui_settings(state: UiState) -> JsonDict:
    lock = getattr(state, "_settings_lock", None)
    with lock if lock is not None else nullcontext():
        return _read_ui_settings_unlocked(state)


def _read_ui_settings_unlocked(state: UiState) -> JsonDict:
    settings = _default_ui_settings()
    raw = _read_json(state.settings_path)
    if isinstance(raw, dict):
        assistant = raw.get("assistant")
        if isinstance(assistant, dict):
            current = settings.setdefault("assistant", {})
            current.update(
                {key: value for key, value in assistant.items() if key != "openhands"}
            )
            openhands = assistant.get("openhands")
            if isinstance(openhands, dict):
                current_openhands = current.setdefault("openhands", {})
                current_openhands.update(openhands)
                if isinstance(current_openhands.get("native_tools"), list):
                    current_openhands["native_tools"] = list(
                        sanitize_openhands_native_tools(
                            current_openhands.get("native_tools")
                        )
                    )
            capabilities = assistant.get("capabilities")
            if isinstance(capabilities, dict):
                current["capabilities"] = _normalize_assistant_capabilities(
                    capabilities
                )
            permissions = assistant.get("permissions")
            if isinstance(permissions, dict):
                current["permissions"] = _normalize_assistant_permissions(permissions)
        environment = raw.get("environment")
        if isinstance(environment, dict):
            settings["environment"] = _normalize_environment_settings(environment)
    return settings


DEFAULT_ASSISTANT_PERMISSIONS = {
    "file_write": "attached_editable",
    "shell_run": "approval_required",
    "catalog_registration": "approval_required",
    "study_launch": "approval_required",
    "job_stop": "approval_required",
    # An interface is a component's own web application, started in a container
    # with whatever credentials it declares -- the same exposure as running a
    # resource action, so it asks first.
    "interface_launch": "approval_required",
    # A Resource action runs a command the package author wrote, on this
    # machine, with whatever credentials the action declares. That is worth
    # asking about every time, however routine the action looks.
    "resource_action": "approval_required",
    # A smoke test is the only execution the Assistant may start without
    # asking, because it is the only one that cannot outlive the question it
    # answers: it runs a throwaway copy of the package, for a handful of
    # trials, under a wall-clock cap, against a Realm that is deleted when it
    # finishes. Nothing it does is visible afterwards except the answer.
    # Writing, validating, smoke-testing and fixing is one loop, and asking
    # permission on every turn of it is where the interruptions land.
    "smoke_test": "safe_without_approval",
}

ASSISTANT_PERMISSION_VALUES = {
    "file_write": {"attached_editable", "approval_required", "disabled"},
    "shell_run": {"approval_required", "safe_without_approval", "disabled"},
    "catalog_registration": {"approval_required", "disabled"},
    "study_launch": {"approval_required", "disabled"},
    "job_stop": {"approval_required", "disabled"},
    "smoke_test": {"approval_required", "safe_without_approval", "disabled"},
    "resource_action": {"approval_required", "disabled"},
    "interface_launch": {"approval_required", "disabled"},
}

#: How many proposals a smoke test evaluates unless asked for more, and the
#: most it will evaluate however many are asked for. The point of a smoke test
#: is to prove the pieces fit together, which the first few trials settle.
ASSISTANT_SMOKE_DEFAULT_TRIALS = 3
ASSISTANT_SMOKE_MAX_TRIALS = 25


def _assistant_smoke_trial_limit(raw: Any) -> int:
    """The trial cap for one smoke test -- always a real number.

    Previously an absent value meant *no* cap, which also skipped the copy
    below, so the default behaviour was the least bounded one available: the
    person's own package folder, for as many trials as the study declared.
    """

    try:
        requested = int(raw)
    except (TypeError, ValueError):
        requested = 0
    if requested <= 0:
        requested = ASSISTANT_SMOKE_DEFAULT_TRIALS
    return min(requested, ASSISTANT_SMOKE_MAX_TRIALS)


def _default_ui_settings() -> JsonDict:
    env_config = OpenHandsRuntimeConfig.from_env()
    return {
        "assistant": {
            "runtime": "openhands",
            "openhands": {
                "enabled": env_config.enabled,
                "base_url": env_config.base_url,
                "session_endpoint": env_config.session_endpoint,
                "model": env_config.model,
                "api_key": "",
                "native_tools": list(env_config.native_tools),
            },
            "capabilities": {
                "skills": [],
                "mcp_servers": [],
                "custom_tools": [],
            },
            "permissions": dict(DEFAULT_ASSISTANT_PERMISSIONS),
        },
        "environment": {"revisions": {}, "variables": {}},
    }


def _normalize_environment_settings(raw: Optional[JsonDict]) -> JsonDict:
    variables: Dict[str, str] = {}
    revisions: Dict[str, str] = {}
    payload = raw if isinstance(raw, dict) else {}
    source = (
        payload.get("variables", {})
        if isinstance(payload.get("variables"), dict)
        else {}
    )
    for key, value in source.items():
        try:
            name = _clean_env_var_name(key)
        except ValueError:
            continue
        text = str(value or "")
        if text:
            variables[name] = text
    raw_revisions = (
        payload.get("revisions", {})
        if isinstance(payload.get("revisions"), dict)
        else {}
    )
    for name in variables:
        revision = str(raw_revisions.get(name) or "")
        if re.fullmatch(r"environment-revision-[0-9a-f]{32}", revision):
            revisions[name] = revision
    return {"revisions": revisions, "variables": variables}


def _clean_env_var_name(value: Any) -> str:
    name = str(value or "").strip()
    if not name:
        raise ValueError("Environment variable name is required.")
    if "=" in name:
        raise ValueError("Environment variable names cannot contain '='.")
    first = name[0]
    if not (first == "_" or "A" <= first <= "Z" or "a" <= first <= "z"):
        raise ValueError(f"Invalid environment variable name: {name}")
    for char in name[1:]:
        if not (
            char == "_"
            or "A" <= char <= "Z"
            or "a" <= char <= "z"
            or "0" <= char <= "9"
        ):
            raise ValueError(f"Invalid environment variable name: {name}")
    return name


def _environment_variables_from_settings(settings: JsonDict) -> Dict[str, str]:
    environment = (
        settings.get("environment", {})
        if isinstance(settings.get("environment"), dict)
        else {}
    )
    return dict(_normalize_environment_settings(environment).get("variables", {}))


def _environment_revisions_from_settings(settings: JsonDict) -> Dict[str, str]:
    environment = (
        settings.get("environment", {})
        if isinstance(settings.get("environment"), dict)
        else {}
    )
    return dict(_normalize_environment_settings(environment).get("revisions", {}))


def _safe_environment_settings(settings: JsonDict) -> JsonDict:
    variables = _environment_variables_from_settings(settings)
    records = [
        {"name": name, "configured": bool(value)}
        for name, value in sorted(variables.items())
    ]
    return {"variables": records, "count": len(records)}


def _retained_method_environment_status(
    state: UiState, names: Iterable[Any]
) -> List[JsonDict]:
    """Describe revision-bindable Studio values without treating host state as saved."""

    settings_variables = _environment_variables_from_settings(_read_ui_settings(state))
    records: List[JsonDict] = []
    for raw_name in _dedupe_strings(names):
        name = _clean_env_var_name(raw_name)
        configured = bool(settings_variables.get(name))
        records.append(
            {
                "name": name,
                "component": "Method",
                "configured": configured,
                "source": (
                    "settings"
                    if configured
                    else "host-unbound"
                    if os.environ.get(name)
                    else "missing"
                ),
            }
        )
    return records


def _studio_method_environment_binding(
    state: UiState, names: Iterable[Any]
) -> JsonDict:
    """Select immutable non-secret Settings revisions for one new Run."""

    normalized_names = tuple(_clean_env_var_name(item) for item in _dedupe_strings(names))
    with state._settings_lock:
        settings = _read_ui_settings_unlocked(state)
        variables = _environment_variables_from_settings(settings)
        revisions = _environment_revisions_from_settings(settings)
        missing = [name for name in normalized_names if not variables.get(name)]
        if missing:
            joined = ", ".join(missing)
            raise ValueError(
                f"Add {joined} in Studio Settings before launching this Run. "
                "Retained Runs bind saved Settings revisions; exported host "
                "variables are used only by transient launches."
            )
        changed = False
        for name in normalized_names:
            if name not in revisions:
                revisions[name] = f"environment-revision-{uuid.uuid4().hex}"
                changed = True
        if changed:
            environment = settings.setdefault("environment", {})
            environment["variables"] = variables
            environment["revisions"] = revisions
            _write_ui_settings_unlocked(state, settings)
        requirements = [
            {
                "name": name,
                "revision_id": revisions[name],
                "source": "studio-settings",
            }
            for name in normalized_names
        ]
        binding_revision = (
            "method-environment-"
            + request_digest(
                {
                    "requirements": requirements,
                    "schema": METHOD_ENVIRONMENT_BINDING_SCHEMA,
                }
            )[:32]
            if requirements
            else "method-environment-none"
        )
        return {
            "binding_revision": binding_revision,
            "recoverability": "settings-revision" if requirements else "none",
            "requirements": requirements,
            "schema": METHOD_ENVIRONMENT_BINDING_SCHEMA,
        }


def _studio_method_environment_values(
    state: UiState, binding: Mapping[str, Any]
) -> Dict[str, str]:
    """Resolve only the exact Settings revisions retained by one Run."""

    requirements = binding.get("requirements")
    if isinstance(requirements, (str, bytes)) or not isinstance(
        requirements, list
    ):
        raise ValueError("Retained Method environment binding is invalid.")
    with state._settings_lock:
        settings = _read_ui_settings_unlocked(state)
        variables = _environment_variables_from_settings(settings)
        revisions = _environment_revisions_from_settings(settings)
        selected: Dict[str, str] = {}
        unavailable: List[str] = []
        for item in requirements:
            if (
                not isinstance(item, Mapping)
                or item.get("source") != "studio-settings"
            ):
                raise ValueError(
                    "Retained Method environment source is unsupported in Studio."
                )
            name = _clean_env_var_name(item.get("name"))
            expected_revision = str(item.get("revision_id") or "")
            if (
                not variables.get(name)
                or revisions.get(name) != expected_revision
            ):
                unavailable.append(name)
                continue
            selected[name] = variables[name]
    if unavailable:
        joined = ", ".join(unavailable)
        raise ValueError(
            f"This Run is waiting for its original Studio Settings value"
            f"{'s' if len(unavailable) != 1 else ''}: {joined}. "
            "The value was changed or removed after the Run was launched; "
            "launch a new Run to use the current value."
        )
    return selected


def _resolve_declared_env_from_host(
    state: UiState, names: Iterable[Any]
) -> tuple[Dict[str, str], List[str]]:
    """Resolve declared host values, falling back to any declared defaults.

    Accepts both forms of declaration: a bare name is required from the host,
    while a name carrying a default is satisfied by that default when neither
    Studio Settings nor the process environment provides one. Callers that pass
    plain names -- including every secret, which never takes a default -- are
    unaffected.
    """

    declarations = compile_host_env_declarations(
        list(names), location="grants.envFromHost"
    )
    settings_variables = _environment_variables_from_settings(_read_ui_settings(state))
    resolved: Dict[str, str] = {}
    missing: List[str] = []
    for declared in declarations:
        name = _clean_env_var_name(declared.name)
        if settings_variables.get(name):
            resolved[name] = settings_variables[name]
        elif os.environ.get(name):
            resolved[name] = os.environ[name]
        elif declared.default is not None:
            resolved[name] = declared.default
        else:
            missing.append(name)
    return resolved, missing


def _require_declared_env_from_host(
    state: UiState, names: Iterable[Any], *, action: str
) -> Dict[str, str]:
    resolved, missing = _resolve_declared_env_from_host(state, names)
    if missing:
        joined = ", ".join(missing)
        raise ValueError(
            f"Missing environment variable{'s' if len(missing) != 1 else ''} for {action}: {joined}. "
            "Add them in Studio Settings or export them before launching. "
            "Only variables declared with envFromHost are injected."
        )
    return resolved


def _dedupe_strings(values: Iterable[Any]) -> List[str]:
    result: List[str] = []
    seen = set()
    for value in values:
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        result.append(text)
    return result


def _declared_env_from_host(payload: Any) -> List[str]:
    names: List[str] = []
    if isinstance(payload, dict):
        env_from_host = payload.get("envFromHost")
        if isinstance(env_from_host, list):
            names.extend(str(item) for item in env_from_host if str(item).strip())
        for value in payload.values():
            names.extend(_declared_env_from_host(value))
    elif isinstance(payload, list):
        for item in payload:
            names.extend(_declared_env_from_host(item))
    return _dedupe_strings(names)


def _study_env_requirements(study_path: Path) -> List[str]:
    compiled = compile_authoring_config(study_path)
    names: List[str] = []
    for key in ("environment", "method", "execution"):
        names.extend(_declared_env_from_host(compiled.get(key)))
    return _dedupe_strings(names)


def _study_method_env_requirements(study_path: Path) -> List[str]:
    """Return only launch-time values declared by the Study's Method."""

    compiled = compile_authoring_config(study_path)
    method = compiled.get("method")
    runtime = method.get("runtime") if isinstance(method, Mapping) else None
    names = runtime.get("envFromHost") if isinstance(runtime, Mapping) else None
    return _dedupe_strings(names if isinstance(names, list) else [])


def _interface_launch_env_requirements(
    profile: InterfaceLaunchProfile,
) -> List[str]:
    return _dedupe_strings(
        [*profile.grants.env_from_host, *profile.grants.secrets_from_host]
    )


def _study_subprocess_env(state: UiState, study_path: Path) -> Dict[str, str]:
    declared_env = _require_declared_env_from_host(
        state, _study_env_requirements(study_path), action="study launch"
    )
    env = minimal_host_env()
    pythonpath_entries = [
        str(path)
        for path in [
            _pythonpath_root_for_package("optpilot"),
            state.cwd.resolve(),
        ]
        if path
    ]
    existing_pythonpath = os.environ.get("PYTHONPATH")
    if existing_pythonpath:
        pythonpath_entries.append(existing_pythonpath)
    env["PYTHONPATH"] = os.pathsep.join(
        dict.fromkeys(item for item in pythonpath_entries if item)
    )
    env.update(declared_env)
    return env


def _pythonpath_root_for_package(package: str) -> Optional[Path]:
    spec = importlib.util.find_spec(package)
    if spec is None or not spec.origin or spec.origin in {"built-in", "namespace"}:
        return None
    path = Path(spec.origin).resolve()
    if path.name == "__init__.py":
        return path.parent.parent
    return path.parent


def _package_dir(package: str) -> Optional[Path]:
    spec = importlib.util.find_spec(package)
    if spec is None or not spec.origin or spec.origin in {"built-in", "namespace"}:
        return None
    path = Path(spec.origin).resolve()
    if path.name == "__init__.py":
        return path.parent
    return path.parent


def _normalize_assistant_permissions(raw: Optional[JsonDict]) -> JsonDict:
    permissions = dict(DEFAULT_ASSISTANT_PERMISSIONS)
    if not isinstance(raw, dict):
        return permissions
    for key in permissions:
        value = str(raw.get(key) or permissions[key]).strip()
        permissions[key] = (
            value if value in ASSISTANT_PERMISSION_VALUES[key] else permissions[key]
        )
    return permissions


def _normalize_capability_id(value: Any, fallback: str) -> str:
    text = str(value or fallback or "").strip().lower()
    normalized = "".join(
        char if char.isalnum() or char in {"-", "_", "."} else "-" for char in text
    )
    normalized = "-".join(part for part in normalized.split("-") if part)
    return normalized or fallback


def _normalize_capability_record(raw: Any, *, kind: str, index: int) -> JsonDict:
    item = raw if isinstance(raw, dict) else {}
    fallback = f"{kind}-{index + 1}"
    name = str(item.get("name") or item.get("id") or fallback).strip() or fallback
    record: JsonDict = {
        "id": _normalize_capability_id(item.get("id") or name, fallback),
        "name": name,
        "description": str(item.get("description") or "").strip(),
        "enabled": bool(item.get("enabled", True)),
        "kind": kind,
    }
    if kind == "skill":
        record["source"] = str(item.get("source") or item.get("path") or "").strip()
        triggers = item.get("triggers", [])
        record["triggers"] = (
            [str(trigger).strip() for trigger in triggers if str(trigger).strip()]
            if isinstance(triggers, list)
            else []
        )
    elif kind == "mcp_server":
        record["command"] = str(item.get("command") or "").strip()
        record["args"] = (
            [str(arg) for arg in item.get("args", [])]
            if isinstance(item.get("args"), list)
            else []
        )
        record["url"] = str(item.get("url") or "").strip()
        record["auth"] = str(item.get("auth") or "").strip()
        record["transport"] = str(item.get("transport") or "stdio").strip() or "stdio"
    elif kind == "custom_tool":
        record["module"] = str(item.get("module") or "").strip()
        record["factory"] = str(item.get("factory") or item.get("class") or "").strip()
        record["tool_name"] = str(
            item.get("tool_name") or item.get("registered_name") or record["name"]
        ).strip()
        record["approval_required"] = bool(item.get("approval_required", True))
    return record


def _normalize_assistant_capabilities(raw: Optional[JsonDict]) -> JsonDict:
    raw = raw if isinstance(raw, dict) else {}
    skills = [
        _normalize_capability_record(item, kind="skill", index=index)
        for index, item in enumerate(
            raw.get("skills", []) if isinstance(raw.get("skills"), list) else []
        )
    ]
    mcp_servers = [
        _normalize_capability_record(item, kind="mcp_server", index=index)
        for index, item in enumerate(
            raw.get("mcp_servers", [])
            if isinstance(raw.get("mcp_servers"), list)
            else []
        )
    ]
    local_tools = [
        _normalize_capability_record(item, kind="custom_tool", index=index)
        for index, item in enumerate(
            raw.get("local_tools", [])
            if isinstance(raw.get("local_tools"), list)
            else []
        )
    ]
    custom_tool_inputs = (
        raw.get("custom_tools", []) if isinstance(raw.get("custom_tools"), list) else []
    )
    custom_tools = [
        _normalize_capability_record(item, kind="custom_tool", index=index)
        for index, item in enumerate(custom_tool_inputs)
    ]
    return {
        "skills": skills,
        "mcp_servers": mcp_servers,
        "mcp_filter_regex": str(
            raw.get("mcp_filter_regex") or raw.get("filter_tools_regex") or ""
        ).strip(),
        # `local_tools` is kept as a migration alias for older settings files.
        "custom_tools": custom_tools + local_tools,
    }


def _assistant_capabilities_from_settings(settings: JsonDict) -> JsonDict:
    assistant = (
        settings.get("assistant", {})
        if isinstance(settings.get("assistant"), dict)
        else {}
    )
    return _normalize_assistant_capabilities(
        assistant.get("capabilities")
        if isinstance(assistant.get("capabilities"), dict)
        else {}
    )


def _assistant_permissions_from_settings(settings: JsonDict) -> JsonDict:
    assistant = (
        settings.get("assistant", {})
        if isinstance(settings.get("assistant"), dict)
        else {}
    )
    return _normalize_assistant_permissions(
        assistant.get("permissions")
        if isinstance(assistant.get("permissions"), dict)
        else {}
    )


def _capability_summary(record: JsonDict) -> JsonDict:
    summary = {
        "id": record.get("id"),
        "name": record.get("name"),
        "kind": record.get("kind"),
        "description": record.get("description"),
        "enabled": bool(record.get("enabled")),
    }
    if record.get("kind") == "custom_tool":
        summary["approval_required"] = bool(record.get("approval_required", True))
    return summary


def _assistant_capability_summary(state: UiState) -> JsonDict:
    settings = _read_ui_settings(state)
    capabilities = _assistant_capabilities_from_settings(settings)
    permissions = _assistant_permissions_from_settings(settings)
    buckets = {
        "skills": capabilities["skills"],
        "mcp_servers": capabilities["mcp_servers"],
        "custom_tools": capabilities["custom_tools"],
    }
    return {
        "counts": {
            key: {
                "total": len(records),
                "enabled": sum(1 for record in records if record.get("enabled")),
            }
            for key, records in buckets.items()
        },
        "enabled": {
            key: [
                _capability_summary(record)
                for record in records
                if record.get("enabled")
            ]
            for key, records in buckets.items()
        },
        "permissions": permissions,
    }


def _capability_bucket(kind: str) -> str:
    value = str(kind or "").strip().lower().replace("-", "_")
    return {
        "skill": "skills",
        "skills": "skills",
        "mcp": "mcp_servers",
        "mcp_server": "mcp_servers",
        "mcp_servers": "mcp_servers",
        "local": "custom_tools",
        "local_tool": "custom_tools",
        "local_tools": "custom_tools",
        "custom": "custom_tools",
        "custom_tool": "custom_tools",
        "custom_tools": "custom_tools",
    }.get(value, value)


def _assistant_capability_list(state: UiState, kind: str = "") -> JsonDict:
    settings = _read_ui_settings(state)
    capabilities = _assistant_capabilities_from_settings(settings)
    permissions = _assistant_permissions_from_settings(settings)
    bucket = _capability_bucket(kind)
    if bucket:
        records = capabilities.get(bucket, [])
        return {
            "capabilities": {
                bucket: [_capability_summary(record) for record in records]
            },
            "permissions": permissions,
        }
    capability_buckets = {
        "skills": capabilities.get("skills", []),
        "mcp_servers": capabilities.get("mcp_servers", []),
        "custom_tools": capabilities.get("custom_tools", []),
    }
    return {
        "capabilities": {
            key: [_capability_summary(record) for record in records]
            for key, records in capability_buckets.items()
        },
        "mcp_filter_regex": capabilities.get("mcp_filter_regex", ""),
        "permissions": permissions,
    }


def _assistant_capability_detail(
    state: UiState, kind: str, capability_id: str
) -> JsonDict:
    bucket = _capability_bucket(kind)
    if not bucket:
        raise ValueError("Capability kind is required.")
    settings = _read_ui_settings(state)
    capabilities = _assistant_capabilities_from_settings(settings)
    for record in capabilities.get(bucket, []):
        if record.get("id") == capability_id:
            return {
                "capability": record,
                "permissions": _assistant_permissions_from_settings(settings),
            }
    raise KeyError(capability_id)


def _write_ui_settings(state: UiState, settings: JsonDict) -> None:
    with state._settings_lock:
        _write_ui_settings_unlocked(state, settings)


def _write_ui_settings_unlocked(state: UiState, settings: JsonDict) -> None:
    state.settings_path.parent.mkdir(parents=True, exist_ok=True)
    state.settings_path.write_text(
        json.dumps(settings, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    try:
        state.settings_path.chmod(0o600)
    except OSError:
        pass


def _openhands_config_from_settings(settings: JsonDict) -> OpenHandsRuntimeConfig:
    assistant = (
        settings.get("assistant", {})
        if isinstance(settings.get("assistant"), dict)
        else {}
    )
    openhands = (
        assistant.get("openhands", {})
        if isinstance(assistant.get("openhands"), dict)
        else {}
    )
    config = OpenHandsRuntimeConfig.from_mapping(openhands)
    if config.api_key:
        return config
    env_config = OpenHandsRuntimeConfig.from_env()
    return OpenHandsRuntimeConfig(
        base_url=config.base_url,
        session_endpoint=config.session_endpoint,
        model=config.model,
        api_key=env_config.api_key,
        enabled=config.enabled,
        native_tools=config.native_tools,
    )


def _refresh_agent_adapter(state: UiState) -> None:
    state.agent_adapter = OpenHandsAdapter(
        _openhands_config_from_settings(_read_ui_settings(state))
    )


def _agent_settings_payload(state: UiState) -> JsonDict:
    _refresh_agent_adapter(state)
    settings = _read_ui_settings(state)
    assistant = (
        settings.get("assistant", {})
        if isinstance(settings.get("assistant"), dict)
        else {}
    )
    openhands = (
        assistant.get("openhands", {})
        if isinstance(assistant.get("openhands"), dict)
        else {}
    )
    capabilities = _assistant_capabilities_from_settings(settings)
    permissions = _assistant_permissions_from_settings(settings)
    safe_openhands = {
        "enabled": bool(openhands.get("enabled")),
        # Report the URL actually in use, not the empty box behind it. Showing
        # blank sent people looking for a value the product already knew.
        "base_url": resolve_openhands_base_url(openhands.get("base_url")),
        "session_endpoint": str(openhands.get("session_endpoint") or ""),
        "model": str(openhands.get("model") or ""),
        "native_tools": list(_openhands_config_from_settings(settings).native_tools),
        "api_key_configured": bool(
            openhands.get("api_key") or OpenHandsRuntimeConfig.from_env().api_key
        ),
    }
    return {
        "settings": {
            "assistant": {
                "runtime": "openhands",
                "openhands": safe_openhands,
                "capabilities": capabilities,
                "permissions": permissions,
            },
            "environment": _safe_environment_settings(settings),
        },
        "status": state.agent_adapter.status(),
        "settings_path": str(state.settings_path),
    }


def _native_tools_not_enabled(raw: Any) -> List[str]:
    """Which requested tools OptPilot will not switch on.

    Not an error: a caller may legitimately send OpenHands' whole tool list,
    and OptPilot narrows it deliberately -- it ships its own terminal and file
    editor, so enabling OpenHands' would give the Assistant two of each. What
    was wrong was doing that in silence, leaving a person to believe they had
    switched something on.
    """

    if not isinstance(raw, list):
        return []
    skipped: List[str] = []
    for name in raw:
        text = str(name or "").strip()
        if text and text not in ALLOWED_OPENHANDS_NATIVE_TOOLS and text not in skipped:
            skipped.append(text)
    return skipped


def _require_usable_capability_entries(raw: Any) -> None:
    """Refuse an entry that could never do anything.

    An MCP server with neither a command to start nor an address to reach was
    accepted and stored as an enabled entry with both fields blank -- which
    reads on screen as configured and can never work.
    """

    if not isinstance(raw, Mapping):
        return
    for entry in raw.get("mcp_servers") or []:
        if not isinstance(entry, Mapping):
            continue
        if not str(entry.get("command") or "").strip() and not str(
            entry.get("url") or ""
        ).strip():
            label = str(entry.get("name") or entry.get("id") or "this server")
            raise ValueError(
                f"{label} needs either a command to start it or a URL to reach "
                "it. Add one, or remove the entry."
            )


def _require_supported_assistant_permissions(raw: Any) -> None:
    """Refuse a permission this build cannot act on, naming what is allowed."""

    if not isinstance(raw, Mapping):
        return
    for key, value in raw.items():
        name = str(key)
        allowed = ASSISTANT_PERMISSION_VALUES.get(name)
        if allowed is None:
            known = ", ".join(sorted(ASSISTANT_PERMISSION_VALUES))
            raise ValueError(
                f"{name!r} is not a permission OptPilot knows about. "
                f"Choose one of: {known}."
            )
        text = str(value or "").strip()
        if text not in allowed:
            choices = ", ".join(sorted(allowed))
            raise ValueError(
                f"{text!r} is not a setting for {name!r}. "
                f"Choose one of: {choices}."
            )


def _update_agent_settings(state: UiState, payload: JsonDict) -> JsonDict:
    with state._settings_lock:
        return _update_agent_settings_unlocked(state, payload)


def _update_agent_settings_unlocked(state: UiState, payload: JsonDict) -> JsonDict:
    notices: List[str] = []
    settings = _read_ui_settings(state)
    assistant = settings.setdefault("assistant", {})
    assistant["runtime"] = "openhands"
    openhands = assistant.setdefault("openhands", {})
    incoming = (
        payload.get("openhands")
        if isinstance(payload.get("openhands"), dict)
        else payload
    )
    # Only touch the OpenHands connection fields the caller actually sent.
    # A partial save (e.g. environment variables only) must not silently
    # disable the Assistant or clear its base_url/model.
    if "enabled" in incoming:
        openhands["enabled"] = bool(incoming.get("enabled"))
    if "base_url" in incoming:
        openhands["base_url"] = (
            str(incoming.get("base_url") or "").strip().rstrip("/")
        )
    if "session_endpoint" in incoming:
        openhands["session_endpoint"] = str(
            incoming.get("session_endpoint") or ""
        ).strip()
    if "model" in incoming:
        openhands["model"] = str(incoming.get("model") or "").strip()
    if isinstance(incoming.get("native_tools"), list):
        skipped = _native_tools_not_enabled(incoming.get("native_tools"))
        if skipped:
            notices.append(
                "Not switched on: "
                + ", ".join(skipped)
                + ". OptPilot provides its own for these."
            )
        openhands["native_tools"] = list(
            sanitize_openhands_native_tools(incoming.get("native_tools"))
        )
    if incoming.get("clear_api_key"):
        openhands["api_key"] = ""
    elif "api_key" in incoming and str(incoming.get("api_key") or "").strip():
        openhands["api_key"] = str(incoming.get("api_key") or "").strip()
    if isinstance(payload.get("capabilities"), dict):
        _require_usable_capability_entries(payload.get("capabilities"))
        assistant["capabilities"] = _normalize_assistant_capabilities(
            payload.get("capabilities")
        )
    if isinstance(payload.get("permissions"), dict):
        # Reject a value we cannot honour instead of quietly substituting the
        # default. Normalising on the way IN meant a save could report success
        # while discarding what was asked for, so the setting a person thought
        # they had changed silently stayed as it was. Normalising on the way
        # OUT is still right, and deliberately unchanged: a settings file
        # written by a newer version must not stop Studio from starting.
        _require_supported_assistant_permissions(payload.get("permissions"))
        assistant["permissions"] = _normalize_assistant_permissions(
            payload.get("permissions")
        )
    if isinstance(payload.get("environment"), dict):
        environment = settings.setdefault(
            "environment", {"revisions": {}, "variables": {}}
        )
        variables = _environment_variables_from_settings(settings)
        revisions = _environment_revisions_from_settings(settings)
        for name in variables:
            if name not in revisions:
                revisions[name] = f"environment-revision-{uuid.uuid4().hex}"
        incoming_environment = payload["environment"]
        for raw_name in incoming_environment.get("clear", []) or []:
            try:
                name = _clean_env_var_name(raw_name)
                variables.pop(name, None)
                revisions.pop(name, None)
            except ValueError:
                continue
        for item in incoming_environment.get("set", []) or []:
            if not isinstance(item, dict):
                continue
            name = _clean_env_var_name(item.get("name"))
            value = str(item.get("value") or "")
            if value:
                if variables.get(name) != value or name not in revisions:
                    revisions[name] = f"environment-revision-{uuid.uuid4().hex}"
                variables[name] = value
        environment["variables"] = variables
        environment["revisions"] = revisions
    _write_ui_settings_unlocked(state, settings)
    _refresh_agent_adapter(state)
    saved = _agent_settings_payload(state)
    if notices:
        # Anything the save did not apply travels back with it, so a person is
        # told rather than left to notice on their own.
        saved["notices"] = notices
    return saved


def _runtime_health(state: Optional[UiState] = None) -> JsonDict:
    docker = _cached_executable_health("docker", ["docker", "--version"])
    podman = _cached_executable_health("podman", ["podman", "--version"])
    code_server = _cached_executable_health(
        "code-server", ["code-server", "--version"]
    )
    runtime_gc: JsonDict = {}
    if state:
        runtime_gc = _rate_limited_runtime_gc(state)
    workspace_runtime = (
        state.workspace_runtime.global_status(
            active_workspace=state._active_code_workspace()
        )
        if state
        else {}
    )
    return {
        "python": {
            "ok": True,
            "executable": sys.executable,
            "version": sys.version.split()[0],
        },
        "docker": docker,
        "podman": podman,
        "code_server": code_server,
        "workspace_runtime": workspace_runtime.get("runtime")
        or {
            "target": "per-workspace-container",
            "status": "unconfigured",
            "containerized": False,
            "engine_available": False,
            "runtime_root": "",
            "message": "Workspace runtime status is available after Studio starts.",
        },
        "workspace_runtime_gc": runtime_gc,
    }


def _workspace_records_for_runtime_gc(state: UiState) -> List[JsonDict]:
    attachment_map = _workspace_attachment_map(state)
    records = []
    for workspace in _read_workspace_index(state):
        item = dict(workspace)
        item["attached_sessions"] = attachment_map.get(str(item.get("id") or ""), [])
        records.append(item)
    return records


def _code_server_executable(options: CodeServerOptions) -> Optional[str]:
    if options.executable:
        path = Path(options.executable).expanduser()
        if path.exists() and path.is_file():
            return str(path.resolve())
        resolved = shutil.which(options.executable)
        return resolved
    return shutil.which("code-server")


def _local_code_server_executable(cwd: Path) -> Path:
    standalone_root = cwd / ".optpilot-ui" / "code-server-standalone"
    direct = standalone_root / "bin" / "code-server"
    if direct.exists():
        return direct
    candidates = sorted(
        standalone_root.glob("lib/code-server-*/bin/code-server"),
        key=lambda path: path.stat().st_mtime if path.exists() else 0,
        reverse=True,
    )
    return candidates[0] if candidates else direct


def _code_server_reachable(url: str) -> bool:
    try:
        request = Request(url, method="HEAD")
        with urlopen(request, timeout=0.4) as response:
            server = response.headers.get("Server", "")
            return 200 <= response.status < 400 and "OptPilotUI" not in server
    except Exception:
        return False


def _port_listening(host: str, port: int) -> bool:
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as sock:
        sock.settimeout(0.2)
        return sock.connect_ex((host, int(port))) == 0


def _find_available_port(
    host: str, start_port: int, *, reserved: Optional[set[int]] = None
) -> int:
    reserved = reserved or set()
    for port in range(int(start_port), int(start_port) + 100):
        if port in reserved:
            continue
        if not _port_listening(host, port):
            return port
    raise OSError(f"No available port found near {start_port}.")


def _preview_allowed_ports(port: int, extra_ports: Iterable[int]) -> List[int]:
    ports = {int(port)}
    for raw in extra_ports:
        try:
            candidate = int(raw)
        except (TypeError, ValueError):
            raise ValueError(
                f"Preview extra port must be an integer: {raw!r}"
            ) from None
        if candidate < 1 or candidate > 65535:
            raise ValueError("Preview ports must be between 1 and 65535.")
        ports.add(candidate)
    return sorted(ports)


def _preview_ready_url(proxy_target: str, ready_path: str) -> str:
    path = str(ready_path or "/")
    if not path.startswith("/") or path.startswith("//") or "://" in path:
        raise ValueError("Preview readiness path must be one local HTTP path.")
    return f"{str(proxy_target).rstrip('/')}{path}"


def _wait_for_preview_ready(
    proxy_target: str,
    ready_path: str,
    timeout_seconds: int,
    *,
    should_stop: Optional[Any] = None,
    launch: Optional[JsonDict] = None,
) -> JsonDict:
    timeout = max(0, int(timeout_seconds or 0))
    ready_url = _preview_ready_url(proxy_target, ready_path)
    if timeout <= 0:
        return {
            "ready": False,
            "skipped": True,
            "url": ready_url,
            "timeoutSeconds": 0,
        }
    deadline = time.monotonic() + timeout
    last_error = ""
    while time.monotonic() <= deadline:
        if should_stop and should_stop():
            raise RuntimeError("Interface launch was stopped.")
        process_exit = _detached_process_exit(launch or {})
        if process_exit is not None:
            exit_code, logs = process_exit
            error = f"launch process exited with code {exit_code} before preview readiness"
            detail = str(logs.get("stderr") or logs.get("stdout") or "").strip()
            if detail:
                error = f"{error}: {detail[-2000:]}"
            return {
                "ready": False,
                "skipped": False,
                "url": ready_url,
                "timeoutSeconds": timeout,
                "processExited": True,
                "exitCode": exit_code,
                "error": error,
                "diagnostic": detail[-2000:],
            }
        remaining = max(0.1, deadline - time.monotonic())
        request = Request(
            ready_url,
            method="GET",
            headers={"Accept": "text/html,application/json,*/*"},
        )
        try:
            with urlopen(request, timeout=min(1.5, remaining)) as response:
                if response.status < 500:
                    return {
                        "ready": True,
                        "status": response.status,
                        "url": ready_url,
                        "timeoutSeconds": timeout,
                    }
                last_error = f"HTTP {response.status}"
        except HTTPError as exc:
            if exc.code < 500:
                return {
                    "ready": True,
                    "status": exc.code,
                    "url": ready_url,
                    "timeoutSeconds": timeout,
                }
            last_error = f"HTTP {exc.code}"
        except URLError as exc:
            last_error = str(exc.reason)
        except Exception as exc:
            last_error = str(exc)
        time.sleep(0.5)
    return {
        "ready": False,
        "skipped": False,
        "url": ready_url,
        "timeoutSeconds": timeout,
        "error": last_error or "preview target did not respond",
    }


def _detached_process_exit(launch: JsonDict) -> Optional[tuple[int, JsonDict]]:
    exit_path = str(launch.get("exit_code_file") or "")
    if not exit_path:
        return None
    path = Path(exit_path)
    if not path.is_file():
        return None
    try:
        exit_code = int(path.read_text(encoding="utf-8").strip())
    except (OSError, ValueError):
        return None
    return exit_code, _launch_log_tail(
        {
            "stdout": launch.get("stdout_log"),
            "stderr": launch.get("stderr_log"),
        },
        max_chars=4000,
    )


def _preview_readiness_failure(port: int, readiness: JsonDict) -> BaseException:
    error = str(readiness.get("error") or readiness.get("url") or "")
    if readiness.get("processExited"):
        return InterfaceLaunchProcessExited(
            int(readiness.get("exitCode") or 0),
            str(readiness.get("diagnostic") or error),
        )
    return InterfaceLaunchReadinessTimeout(
        port=port,
        timeout_seconds=int(readiness.get("timeoutSeconds") or 0),
        diagnostic=error,
    )


def _int_env(name: str, default: int) -> int:
    value = os.environ.get(name)
    if value in (None, ""):
        return default
    try:
        return int(value)
    except ValueError:
        return default


def _split_env_patterns(name: str) -> List[str]:
    value = os.environ.get(name, "")
    return [
        part.strip() for part in value.replace("\n", ",").split(",") if part.strip()
    ]


def _parse_time_or_iso(value: Any) -> float:
    if isinstance(value, (int, float)):
        return float(value)
    text = str(value or "").strip()
    if not text:
        return time.time()
    try:
        return float(text)
    except ValueError:
        pass
    try:
        return float(calendar.timegm(time.strptime(text, "%Y-%m-%dT%H:%M:%SZ")))
    except ValueError:
        return time.time()


def _ui_env_flag(name: str, default: bool = False) -> bool:
    value = os.environ.get(name)
    if value in (None, ""):
        return default
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _safe_code_server_folder(state: UiState, folder: Path) -> Path:
    folder = folder.resolve()
    allowed_roots = [
        state.cwd,
        *state.catalog_roots,
        *state.run_roots,
        state.sessions_dir,
        state.workspaces_dir,
    ]
    if any(_is_relative_to(folder, root) for root in allowed_roots):
        return folder
    if _is_active_catalog_workspace_projection_path(state, folder):
        return folder
    if _is_registered_managed_workspace_root(state, folder):
        return folder
    raise ValueError(f"Folder is outside the OptPilot workspace: {folder}")


def _is_active_catalog_workspace_projection_path(state: UiState, path: Path) -> bool:
    """Authorize only paths covered by a live catalog Workspace consumer."""

    resolved = path.resolve()
    with state._catalog_projection_lock:
        projections = tuple(state._catalog_workspace_projections.values())
    return any(_is_relative_to(resolved, item.root_path) for item in projections)


def _is_registered_managed_workspace_root(state: UiState, root: Path) -> bool:
    """Return whether ``root`` is an open, provider-verified Realm checkout.

    Realm checkouts normally live outside Studio's project-local path roots.
    Authorizing the provider's whole checkout namespace would also expose
    checkout wrappers, stale trees, and any unrelated directory created there.
    The reconciled workspace list contains only roots reminted by the active
    Realm provider, so require an exact registered-root match.
    """

    if not _managed_workspace_provider_available(state):
        return False
    resolved = root.resolve()
    for workspace in _list_ui_workspaces(state, include_support=True):
        if str(workspace.get("ownership") or "") != "realm-managed" or bool(
            workspace.get("reopen_required")
        ):
            continue
        registered = str(workspace.get("root") or "")
        if registered and Path(registered).resolve() == resolved:
            return True
    return False


# ``<engine> --version`` output only changes when the host installs or removes
# software, yet the health endpoint is polled continuously; without a TTL every
# poll spawns three subprocesses.
_EXECUTABLE_HEALTH_TTL_SECONDS = 300.0
_executable_health_cache: Dict[str, tuple[float, JsonDict]] = {}
_executable_health_cache_lock = threading.Lock()

# Idle-container reclamation compares minutes-scale idle timers; sweeping the
# container engine once a minute preserves the policy without a subprocess
# storm on every status poll.
_RUNTIME_GC_MIN_INTERVAL_SECONDS = 60.0


def _cached_executable_health(name: str, command: List[str]) -> JsonDict:
    now = time.monotonic()
    with _executable_health_cache_lock:
        entry = _executable_health_cache.get(name)
        if entry is not None and now - entry[0] < _EXECUTABLE_HEALTH_TTL_SECONDS:
            return dict(entry[1])
    result = _executable_health(name, command)
    with _executable_health_cache_lock:
        _executable_health_cache[name] = (time.monotonic(), result)
    return dict(result)


def _rate_limited_runtime_gc(state: UiState) -> JsonDict:
    now = time.monotonic()
    with state._runtime_gc_lock:
        last = state._runtime_gc_last
        if last is not None and now - last[0] < _RUNTIME_GC_MIN_INTERVAL_SECONDS:
            return dict(last[1])
        result = state.workspace_runtime.garbage_collect(
            _workspace_records_for_runtime_gc(state),
            active_workspace_id=state.active_code_workspace_id,
        )
        state._runtime_gc_last = (time.monotonic(), result)
        return dict(result)


def _executable_health(name: str, command: List[str]) -> JsonDict:
    path = shutil.which(name)
    if not path:
        return {"ok": False, "available": False, "path": None, "version": None}
    try:
        completed = subprocess.run(
            command, capture_output=True, text=True, timeout=3, check=False
        )
    except Exception as exc:
        return {
            "ok": False,
            "available": True,
            "path": path,
            "version": None,
            "error": str(exc),
        }
    text = (completed.stdout or completed.stderr).strip().splitlines()
    return {
        "ok": completed.returncode == 0,
        "available": True,
        "path": path,
        "version": text[0] if text else None,
        "error": completed.stderr.strip() if completed.returncode else "",
    }


#: What the Assistant needs in order to *choose* a catalog entry, as opposed to
#: what it needs in order to use one. Everything omitted here -- the file's full
#: text, its parsed settings, the expanded source reference, the derived runtime
#: summary -- is still one `optpilot_catalog_detail` call away.
#:
#: A bare listing used to return every field of every entry: 348,000 characters
#: for the shipped example packages, spent before the Assistant had done anything.
#: The ref token is deliberately NOT here. It is ~490 characters, and handing
#: one to a language model invites it to echo the thing back wrongly -- one
#: decoded a token, re-encoded it, dropped a field, and sent 485 characters
#: that were not a prefix of the original, so the lookup failed and the
#: conversation stalled. Tools now accept `qualified_id`, which is short enough
#: to reproduce and readable enough to explain.
ASSISTANT_CATALOG_LIST_FIELDS = (
    "id",
    "kind",
    "config",
    "label",
    "package",
    "package_id",
    "qualified_id",
    "description",
    "tags",
    "tasks",
    "path",
    # Without this the Assistant cannot tell which entries even have an
    # interface to open, and guesses at what it was asked for.
    "has_interface",
)


def _assistant_catalog_entry(entry: Any) -> JsonDict:
    """One catalog entry, reduced to what choosing between entries needs."""

    if not isinstance(entry, dict):
        return {}
    slim = {
        field: entry[field]
        for field in ASSISTANT_CATALOG_LIST_FIELDS
        if field in entry
    }
    summary = entry.get("summary") if isinstance(entry.get("summary"), dict) else {}
    slim["has_interface"] = bool(summary.get("interface"))
    return slim


def _assistant_catalog_entries(entries: Any) -> List[JsonDict]:
    if not isinstance(entries, list):
        return []
    return [_assistant_catalog_entry(entry) for entry in entries]


def _catalog_detail(state: UiState, expected_config: str, uid: str) -> JsonDict:
    expected_config = {
        "environments": "environment",
        "methods": "method",
        "studies": "study",
        "study_plan": "study",
        "study_plans": "study",
        "resources": "resource",
    }.get(str(expected_config or ""), str(expected_config or ""))
    source_projection = _borrow_catalog_entry_ref_projection(
        state,
        expected_config,
        uid,
        consumer_kind="catalog-detail",
    )
    try:
        if source_projection is not None:
            entry_ref = _catalog_entry_ref_from_value(
                state, expected_config, uid, allow_readable_id=True
            )
            assert entry_ref is not None
            path = source_projection.source_path
            source_record = {
                "source_kind": entry_ref.source_kind,
                "source_id": entry_ref.source_id,
                "source_revision": entry_ref.source_revision,
                "source_digest": entry_ref.source_digest,
            }
            if expected_config == "resource":
                indexed_entry = _resource_catalog_entry(
                    path,
                    package_id=source_projection.package_id,
                    package_root=source_projection.root_path,
                    source_record=source_record,
                )
            else:
                raw = _read_yaml(path)
                indexed_entry = _catalog_entry(
                    path,
                    raw,
                    package_id=source_projection.package_id,
                    package_root=source_projection.root_path,
                    source_record=source_record,
                )
        else:
            path = _resolve_catalog_identifier(state, expected_config, uid)
            indexed_entry = _catalog_index_entry_for_source(
                state, expected_config, path
            )

        entry = _public_catalog_entry_with_workspace(state, indexed_entry)
        if expected_config == "resource":
            config_yaml = str(entry.get("yaml") or "")
            config_raw = yaml.safe_load(config_yaml) or {}
            config_source = str(indexed_entry.get("_config_source_path") or "")
            if config_source:
                validation = _public_catalog_validation(
                    validate_authoring_config(config_source),
                    str(entry.get("config_path") or entry.get("path") or ""),
                )
            else:
                schema_result = validate_public_config_schema(
                    config_raw, config_path="optpilot.resource.yaml"
                )
                validation = {
                    "valid": schema_result.valid,
                    "path": str(entry.get("path") or ""),
                    "errors": [
                        f"{issue.path}: {issue.message}"
                        for issue in schema_result.errors
                    ],
                }
            return {
                "entry": entry,
                "config": config_raw,
                "yaml": config_yaml,
                "validation": validation,
                "compatibility": {"compatible": [], "incompatible": []},
            }

        raw = _read_yaml(path)
        if (
            raw.get("config") != expected_config
            or raw.get("apiVersion") != AUTHORING_API_VERSION
        ):
            raise FileNotFoundError(
                f"{expected_config} config is absent from the selected revision."
            )
        if expected_config == "study":
            return {
                "entry": entry,
                "config": raw,
                "yaml": entry.get("yaml") or yaml.safe_dump(raw, sort_keys=False),
                "validation": _public_catalog_validation(
                    _validate_study(path, state=state),
                    str(entry.get("path") or ""),
                ),
                "compatibility": {"compatible": [], "incompatible": []},
            }
        compatibility = _compatibility_payload(state)
        related = [
            item
            for item in compatibility["pairs"]
            if item[expected_config]["uid"] == entry["uid"]
        ]
        return {
            "entry": entry,
            "config": raw,
            "yaml": entry.get("yaml") or yaml.safe_dump(raw, sort_keys=False),
            "validation": _public_catalog_validation(
                validate_authoring_config(path), str(entry.get("path") or "")
            ),
            "compatibility": {
                "compatible": [item for item in related if item["compatible"]],
                "incompatible": [item for item in related if not item["compatible"]],
            },
        }
    finally:
        if source_projection is not None:
            source_projection.close()


_MAX_RESOURCE_ACTION_RUNS = 64
_RESOURCE_ACTION_RUN_SCHEMA = "optpilot.studio-resource-action-run.v1"


def _resolve_resource_action_source(state: UiState, resource_uid: str) -> Path:
    """Resolve one readable resource config path from a catalog uid.

    For a configured filesystem import this is the author's own writable
    folder and is directly runnable. For a realm-published entry it points
    INSIDE a sealed read-only projection: good for reading and compiling the
    manifest, never for executing setup -- core's setup contract requires an
    editable copy, which _prepare_resource_action_execution provides.
    """

    path = _resolve_catalog_identifier(state, "resource", resource_uid)
    manifest_path, raw = _resource_manifest(path if path.is_dir() else path.parent)
    if manifest_path is None or raw.get("config") != "resource":
        raise FileNotFoundError(
            "This Resource has no runnable optpilot.resource.yaml manifest."
        )
    return manifest_path


def _public_resource_action_run(record: JsonDict) -> JsonDict:
    payload = {
        "schema": _RESOURCE_ACTION_RUN_SCHEMA,
        "request_id": record.get("request_id"),
        "resource_uid": record.get("resource_uid"),
        "resource_id": record.get("resource_id"),
        "action_id": record.get("action_id"),
        "workspace_id": record.get("workspace_id") or "",
        "status": record.get("status"),
        "started_at": record.get("started_at"),
        "finished_at": record.get("finished_at"),
        "error": record.get("error"),
    }
    summary = record.get("summary")
    if isinstance(summary, Mapping):
        payload["result"] = {
            "ok": summary.get("ok"),
            "returncode": summary.get("returncode"),
            "timed_out": summary.get("timed_out"),
            "duration_seconds": summary.get("duration_seconds"),
            "outputs": summary.get("outputs"),
            "output_root": summary.get("output_root"),
            "stdout_tail": str(summary.get("stdout_tail") or "")[-4000:],
            "stderr_tail": str(summary.get("stderr_tail") or "")[-4000:],
            "error": summary.get("error"),
        }
    return payload


def _resource_action_output_root(
    state: UiState,
    *,
    workspace_id: str,
    request_id: str,
) -> tuple[Path, str]:
    """Where one action's results go, and which Workspace that is (if any).

    Without a Workspace the results land in Studio's own runtime folder, which
    is right for a person clicking Run on the Catalog page and reading the
    output there. It is wrong for generating something: a simulator bundle
    produced into Studio's private folder has to be copied out by hand before
    it can be registered, and the copy is exactly the step that loses the
    connection between what was generated and what was registered.

    So an action may name an attached Workspace instead, and its results are
    written inside that folder -- already somewhere the person can see, edit,
    and register from.
    """

    stamp = _safe_artifact_identifier(request_id, "resource action request id")
    workspace_id = str(workspace_id or "").strip()
    if not workspace_id:
        return state.runtime_dir / "resource-action-runs" / stamp, ""
    workspace = _workspace_by_id(state, workspace_id)
    if not workspace:
        raise ValueError(f"Unknown workspace {workspace_id!r}.")
    root = _safe_workspace_root(state, Path(str(workspace.get("root") or "")))
    if not root.is_dir():
        raise ValueError(
            f"Workspace {workspace_id!r} has no folder on this machine yet."
        )
    return root / "resource-action-output" / stamp, str(workspace.get("id") or "")


def _notify_agent_session_resource_action_done(
    state: UiState, record: JsonDict
) -> None:
    """Wake the conversation that started a background action, with its result.

    Runs on the action's own worker thread, after the terminal status is
    recorded. Failures here must never damage the run record, so everything is
    defensive: a conversation that has since vanished, or an unreachable
    agent server, degrades to the transcript note alone -- which the person
    still sees.
    """

    session_id = str(record.get("agent_session_id") or "")
    if not session_id:
        return
    status = str(record.get("status") or "")
    public = _public_resource_action_run(record)
    result_block = json.dumps(
        {k: public.get(k) for k in ("status", "result", "error")},
        indent=2,
        sort_keys=True,
        default=str,
    )
    if len(result_block) > 12000:
        result_block = result_block[:12000] + "\n... truncated ..."
    try:
        _append_agent_message(
            state,
            session_id,
            {
                "role": "assistant",
                "title": "Background action finished",
                "source": "studio_ui",
                "content": (
                    f"The {record.get('action_id')} action finished: {status}."
                    + (
                        " Waking the Assistant to continue."
                        if record.get("agent_conversation_id")
                        else ""
                    )
                ),
            },
        )
    except Exception:
        return
    conversation_id = str(record.get("agent_conversation_id") or "")
    if not conversation_id:
        return
    posted = state.agent_adapter.post_background_result(
        conversation_id,
        (
            f"OptPilot background action result for "
            f"{record.get('action_id')} (request {record.get('request_id')}). "
            "The action has finished; nothing further is coming for it. Use "
            "this result to continue the task -- report the outcome to the "
            "person and take the next step.\n"
            f"```json\n{result_block}\n```"
        ),
    )
    if not posted.get("sent"):
        return
    try:
        # Under the operation lock: a tick finishing at this instant would
        # otherwise write its stale captured record back over the flip and
        # re-create the stall this whole mechanism exists to end.
        with _agent_session_operation_lock(state, session_id):
            session = _require_agent_session(state, session_id)
            session["status"] = "waiting_for_agent"
            _upsert_agent_session(state, session)
    except Exception:
        pass


def _copy_resource_tree_writable(source: Path, destination: Path) -> None:
    """Per-run writable copy of a sealed resource tree.

    Directories 0o700, files 0o600 (0o700 when executable) -- the same modes
    the realm's editable-workspace copy uses. Projections are verified to
    contain only regular files and directories; anything else is refused
    rather than copied.
    """

    destination.mkdir(mode=0o700)
    for root, dirs, files in os.walk(source):
        relative = Path(root).relative_to(source)
        for name in dirs:
            child = Path(root, name)
            if child.is_symlink():
                raise RuntimeError("Resource tree must not contain symlinks.")
            (destination / relative / name).mkdir(mode=0o700)
        for name in files:
            child = Path(root, name)
            if child.is_symlink() or not child.is_file():
                raise RuntimeError(
                    "Resource tree must contain only regular files."
                )
            target = destination / relative / name
            shutil.copyfile(child, target)
            os.chmod(target, 0o700 if child.stat().st_mode & 0o111 else 0o600)


def _delete_resource_action_runtime(state: UiState, runtime_id: str) -> bool:
    """Delete a per-run action runtime that never submitted a container.

    The stored record is converted to a terminal proof first (basis: no
    container start was ever submitted on this path), so deletion needs no
    container engine. Failures are swallowed: leftover directories are
    durable cleanup debt for the orphan sweep, never a reason to fail the
    action's own settlement.
    """

    try:
        manager = state.workspace_runtime
        record: JsonDict = {}
        if manager._record_path(runtime_id).is_file():
            record = manager._read_record(runtime_id)
        elif not manager._workspace_runtime_dir(runtime_id).exists():
            return False
        # A claimed directory whose record write was interrupted is still
        # ours to delete: _write_record revalidates the claim, so a foreign
        # or unclaimed directory raises here and is left for the operator.
        if not _workspace_runtime_record_proves_terminal(record):
            record.update(
                {
                    "status": "stopped",
                    "updated_at": _now_iso(),
                    "terminal_proof": {
                        "container_name": "",
                        "terminal_confirmed": True,
                        "state": "absent",
                        "basis": "container_start_not_submitted",
                    },
                }
            )
            manager._write_record(runtime_id, record)
        return manager.delete(runtime_id)
    except Exception:
        return False


def _prepare_resource_action_execution(
    state: UiState, resource_uid: str, request_id: str
) -> tuple[Path, Callable[[], None], Callable[[str], str]]:
    """A runnable manifest, the cleanup for what backs it, a text sanitizer.

    A configured filesystem import is the author's own writable folder and
    runs in place. Anything else resolves inside a sealed read-only realm
    projection (0o500 throughout, by contract), where core's setup step --
    "runs in the editable copy" -- cannot hold: the venv build's first mkdir
    is refused. So the exact revision is borrowed just long enough to copy
    the resource into a per-run writable runtime directory, the action runs
    against the copy, and the copy is deleted when the run settles. Output
    already goes to output_root; nothing from the copy needs to survive.
    """

    # Readable ids are allowed here: the assistant's tool schema tells the
    # model to pass a qualified_id or plain id, and a readable name that
    # resolved to None would silently misroute a realm-published resource
    # into the sealed projection -- the very failure this function exists to
    # prevent. The resolved ref (not the raw string) then feeds the borrow,
    # so it pins the same revision instead of re-resolving the name to None.
    entry_ref = _catalog_entry_ref_from_value(
        state, "resource", resource_uid, allow_readable_id=True
    )
    if entry_ref is None or entry_ref.source_kind == "configured-filesystem-import":
        return (
            _resolve_resource_action_source(state, resource_uid),
            (lambda: None),
            (lambda text: text),
        )
    source_projection = _borrow_catalog_entry_ref_projection(
        state,
        "resource",
        entry_ref,
        consumer_kind="resource-action-run",
        consumer_metadata={"request_id": request_id},
    )
    if source_projection is None:
        return (
            _resolve_resource_action_source(state, resource_uid),
            (lambda: None),
            (lambda text: text),
        )
    # "copy" in the prefix keeps these distinct from the sibling
    # resource-action-runs outputs directory under the same runtime root.
    # The nonce makes the directory per-ATTEMPT: two concurrent requests
    # carrying the same request_id must never share a directory, or the
    # loser's failure cleanup would delete the live winner's copy.
    runtime_id = (
        f"resource-action-copy-{request_id.replace('-', '')[:16]}"
        f"-{uuid.uuid4().hex[:8]}"
    )
    runtime_created = False
    try:
        source_dir = source_projection.source_path
        manifest_path, raw = _resource_manifest(source_dir)
        if manifest_path is None or raw.get("config") != "resource":
            raise FileNotFoundError(
                "This Resource has no runnable optpilot.resource.yaml manifest."
            )
        runtime_dir = state.workspace_runtime._ensure_workspace_runtime_dir(
            runtime_id
        )
        # Deletable from this moment: _delete_resource_action_runtime writes
        # the terminal record itself if the one below never lands.
        runtime_created = True
        state.workspace_runtime._write_record(
            runtime_id,
            {
                "status": "preparing",
                "updated_at": _now_iso(),
                "source_type": "resource-action-run",
                "transient": True,
                "container_may_exist": False,
                "request_id": request_id,
            },
        )
        working_copy = runtime_dir / "resource"
        _copy_resource_tree_writable(source_dir, working_copy)
        runnable_manifest = working_copy / manifest_path.relative_to(source_dir)
    except Exception:
        source_projection.close()
        if runtime_created:
            _delete_resource_action_runtime(state, runtime_id)
        raise
    # The copy is self-contained; the borrowed revision is no longer needed.
    # A close failure (ledger I/O, lease bookkeeping) must not leak the
    # finished copy with no cleanup handle attached to anything.
    try:
        source_projection.close()
    except Exception:
        _delete_resource_action_runtime(state, runtime_id)
        raise

    def cleanup() -> None:
        _delete_resource_action_runtime(state, runtime_id)

    copy_root = str(working_copy)
    origin_root = str(source_dir)

    def sanitize(text: str) -> str:
        # Error and log text otherwise cites the per-run copy, which is
        # deleted before anyone reads it; the projection origin is the
        # inspectable tree the bytes actually came from.
        return text.replace(copy_root, origin_root)

    return runnable_manifest, cleanup, sanitize


def _start_resource_action_run(
    state: UiState, payload: Any
) -> tuple[JsonDict, HTTPStatus]:
    if not isinstance(payload, Mapping):
        raise ValueError("Resource action request must be a JSON object.")
    request_id = _canonical_request_uuid(payload.get("request_id"))
    resource_uid = str(payload.get("resource_uid") or "").strip()
    action_id = str(payload.get("action_id") or "").strip()
    inputs = payload.get("inputs")
    if not resource_uid or not action_id:
        raise ValueError("resource_uid and action_id are required.")
    if inputs is not None and not isinstance(inputs, Mapping):
        raise ValueError("Resource action inputs must be a JSON object.")

    with state._lock:
        existing = state._resource_action_runs.get(request_id)
        if existing is not None:
            return _public_resource_action_run(existing), HTTPStatus.OK
        if (
            len(state._resource_action_runs) >= _MAX_RESOURCE_ACTION_RUNS
            and not any(
                record.get("status") in {"succeeded", "failed"}
                for record in state._resource_action_runs.values()
            )
        ):
            raise ValueError("Too many concurrent resource action runs.")

    manifest_path, cleanup_execution, sanitize_run_text = (
        _prepare_resource_action_execution(state, resource_uid, request_id)
    )
    try:
        with manifest_path.open("r", encoding="utf-8") as handle:
            resource_raw = yaml.safe_load(handle) or {}
        actions = compile_resource_actions(
            resource_raw, location=str(manifest_path)
        )
        action = find_resource_action(actions, action_id)
        # Resolve declared env/secret grants through Studio Settings (falling
        # back to the process environment) so actions work when values like
        # API keys are configured in Settings rather than exported to the
        # Studio process.
        granted_env = _require_declared_env_from_host(
            state,
            (*action.env_from_host, *action.secrets_from_host),
            action=f"resource action {action.action_id!r}",
        )
        action_host_env = {**os.environ, **granted_env}
        output_root, workspace_id = _resource_action_output_root(
            state,
            workspace_id=str(payload.get("workspace_id") or ""),
            request_id=request_id,
        )
    except Exception:
        cleanup_execution()
        raise
    record: JsonDict = {
        "request_id": request_id,
        "resource_uid": resource_uid,
        "resource_id": str(resource_raw.get("id") or ""),
        "action_id": action.action_id,
        "workspace_id": workspace_id,
        "status": "running",
        "started_at": time.time(),
        "finished_at": None,
        "summary": None,
        "error": None,
    }

    def execute() -> None:
        try:
            summary = run_resource_action(
                manifest_path,
                action.action_id,
                input_values=dict(inputs or {}),
                output_root=output_root,
                host_env=action_host_env,
            )
            for key in ("error", "stdout_tail", "stderr_tail"):
                if isinstance(summary.get(key), str):
                    summary[key] = sanitize_run_text(summary[key])
            record["summary"] = summary
            record["status"] = "succeeded" if summary.get("ok") else "failed"
            if not summary.get("ok") and summary.get("error"):
                record["error"] = str(summary["error"])
        except Exception as error:  # surfaced verbatim: local authored action
            record["status"] = "failed"
            record["error"] = sanitize_run_text(str(error))
        finally:
            record["finished_at"] = time.time()
            cleanup_execution()
            with state._lock:
                if (
                    state._resource_action_threads.get(request_id)
                    is threading.current_thread()
                ):
                    state._resource_action_threads.pop(request_id, None)
            # Success or failure alike: a conversation waiting on this must
            # hear the outcome either way, or a failed generation looks like
            # the stall it was built to prevent.
            _notify_agent_session_resource_action_done(state, record)

    start_failed = False
    with state._lock:
        existing_record = state._resource_action_runs.get(request_id)
        if existing_record is None:
            if len(state._resource_action_runs) >= _MAX_RESOURCE_ACTION_RUNS:
                for stale_id in [
                    key
                    for key, value in state._resource_action_runs.items()
                    if value.get("status") in {"succeeded", "failed"}
                ][: max(1, len(state._resource_action_runs) - _MAX_RESOURCE_ACTION_RUNS + 1)]:
                    state._resource_action_runs.pop(stale_id, None)
            state._resource_action_runs[request_id] = record
            thread = threading.Thread(
                target=execute,
                name=f"optpilot-resource-action-{request_id[:18]}",
                daemon=True,
            )
            state._resource_action_threads[request_id] = thread
            try:
                thread.start()
            except Exception:
                # A thread that never started would hold its registrations
                # forever: the record stuck "running", the copy exempt from
                # the sweep. Unwind both, release the copy, surface the
                # failure.
                state._resource_action_threads.pop(request_id, None)
                state._resource_action_runs.pop(request_id, None)
                start_failed = True
    if start_failed:
        cleanup_execution()
        raise RuntimeError("Could not start the resource action worker thread.")
    if existing_record is not None:
        # A concurrent duplicate won the insert while this call was busy
        # preparing its own (nonce-distinct) copy; release that copy and
        # return the winner's record. Deleting a directory tree stays off
        # the lock.
        cleanup_execution()
        return _public_resource_action_run(existing_record), HTTPStatus.OK
    return _public_resource_action_run(record), HTTPStatus.ACCEPTED


def _resource_action_run_status(state: UiState, request_id: str) -> JsonDict:
    request_id = _canonical_request_uuid(request_id)
    with state._lock:
        record = state._resource_action_runs.get(request_id)
    if record is None:
        raise KeyError(request_id)
    return _public_resource_action_run(record)


def _catalog_index_entry_for_source(
    state: UiState, expected_config: str, path: Path
) -> JsonDict:
    catalog = _catalog_index_payload(state)
    key = (
        "resources"
        if expected_config == "resource"
        else {
            "environment": "environments",
            "method": "methods",
            "study": "studies",
        }.get(expected_config, "")
    )
    resolved = path.resolve()
    for entry in catalog.get(key, []) if key else []:
        source = str(entry.get("_source_path") or "")
        if source and Path(source).resolve() == resolved:
            return entry
    raise FileNotFoundError(
        f"{expected_config} is not part of the current catalog index."
    )


def _public_catalog_validation(validation: JsonDict, logical_path: str) -> JsonDict:
    result = deepcopy(validation)
    if "path" in result:
        result["path"] = logical_path
    return result


def _resolve_catalog_identifier(
    state: UiState, expected_config: str, value: Any
) -> Path:
    """Resolve one public logical catalog identity inside an allowed source."""

    entry_ref = _catalog_entry_ref_from_value(state, expected_config, value)
    if entry_ref is not None:
        if entry_ref.source_kind == "configured-filesystem-import":
            return _configured_catalog_entry_ref_path(state, entry_ref)
        entry = _catalog_index_entry_by_ref(state, entry_ref)
        return Path(str(entry["_source_path"])).resolve()
    identifier = str(value or "").strip()
    if not identifier:
        raise FileNotFoundError(f"{expected_config} config not found: {value}")
    catalog = _catalog_index_payload(state)
    if expected_config == "resource":
        entries = catalog.get("resources", [])
    else:
        key = {
            "environment": "environments",
            "method": "methods",
            "study": "studies",
        }.get(expected_config, "")
        entries = catalog.get(key, []) if key else []
    matches = []
    for entry in entries:
        candidates = {
            str(entry.get("id") or ""),
            str(entry.get("qualified_id") or ""),
            str(entry.get("catalog_key") or ""),
            str(entry.get("label") or ""),
            str(entry.get("path") or ""),
        }
        if identifier in candidates:
            matches.append(entry)
    if len(matches) > 1:
        raise ValueError(
            f"Catalog identity {identifier!r} is ambiguous; use its exact ref."
        )
    if matches:
        raw_path = matches[0].get("_source_path")
        if raw_path:
            return Path(str(raw_path)).resolve()
    raise _catalog_identifier_not_found(catalog, expected_config, identifier)


def _catalog_identifier_not_found(
    catalog: JsonDict, expected_config: str, identifier: str
) -> BaseException:
    """The error for an identifier that names no entry of this kind.

    A package id lands here constantly -- a person says "republish
    devs_gallery" and the model reaches for catalog detail, whose lookup is
    per ENTRY. The old text ("resource config not found: devs_gallery") named
    the failure and taught nothing, and a live turn burned itself repeating
    the same call. The index is already in hand, so say which thing the name
    actually is.
    """

    packages = {
        str(source.get("package_id") or "")
        for source in (catalog.get("sources") or [])
        if isinstance(source, Mapping)
    }
    for key in ("environments", "methods", "resources", "studies"):
        for entry in catalog.get(key) or []:
            if isinstance(entry, Mapping) and entry.get("package_id"):
                packages.add(str(entry["package_id"]))
    packages.discard("")
    if identifier in packages:

        def package_entry_ids(keys: Iterable[str]) -> List[str]:
            return [
                str(entry.get("qualified_id") or entry.get("id") or "")
                for key in keys
                for entry in (catalog.get(key) or [])
                if isinstance(entry, Mapping)
                and str(entry.get("package_id") or "") == identifier
            ]

        # The worked example has to be valid for THIS lookup, which only ever
        # searches its own kind. Offering an environment to a resource lookup
        # buys a second refusal, and that one has no remedy to escape by.
        kind_key = _CATALOG_KIND_KEYS.get(expected_config, "")
        same_kind = package_entry_ids([kind_key]) if kind_key else []
        other_kinds = [
            uid
            for uid in package_entry_ids(
                ("environments", "methods", "resources", "studies")
            )
            if uid not in set(same_kind)
        ]
        entry_ids = [*same_kind, *other_kinds]
        if same_kind:
            takes = (
                "This lookup takes a single entry's identifier, such as "
                f"{same_kind[0]!r}."
            )
        else:
            takes = (
                f"It holds no {expected_config} entry at all, so no "
                "identifier of that kind exists to inspect."
            )
        return _with_remedy(
            FileNotFoundError(
                f"{identifier!r} is a catalog package, not one "
                f"{expected_config} entry. {takes}"
            ),
            _remedy(
                (
                    f"List what {identifier} contains and pick one entry. A "
                    "whole package is not inspected or registered through "
                    "this lookup."
                ),
                tool="optpilot_catalog_list",
                arguments={"query": identifier},
                details={
                    "package_id": identifier,
                    "entries": entry_ids[:12],
                    "reason": "package_id_is_not_an_entry_uid",
                },
            ),
        )
    return FileNotFoundError(
        f"No {expected_config} in the catalog is named {identifier!r}. "
        "Search the catalog and use an identifier from its results."
    )


#: The catalog keys each kind of entry lives under, for short-name lookups.
_CATALOG_KIND_KEYS = {
    "environment": "environments",
    "method": "methods",
    "study": "studies",
    "resource": "resources",
}


def _catalog_entry_ref_from_readable_id(
    state: UiState, expected_config: str, value: Any
) -> Optional[CatalogEntryRef]:
    """Resolve a name a person could type, rather than a ref token.

    The ref token encodes which source revision an entry came from, so it is
    long -- around 490 characters of base64. Every tool that touches a catalog
    entry required one echoed back exactly, and a language model will not
    reliably do that: one decoded a token, re-encoded it, dropped a field, and
    sent 485 characters that were not even a prefix of the original. The tool
    then failed with "Catalog entry ref is invalid", and the conversation
    stalled with no way for anyone to see why.

    So the readable identifiers already carried by every listing are accepted
    too: "or_solving/method/coopa-solver", or just "coopa-solver" when only one
    entry of that kind has the name. These name the entry as it stands now,
    which is what someone browsing the Catalog and clicking it also gets.
    """

    text = str(value or "").strip()
    if not text or text.startswith(CATALOG_ENTRY_REF_TOKEN_PREFIX):
        return None
    key = _CATALOG_KIND_KEYS.get(str(expected_config or ""))
    if not key:
        return None
    entries = _catalog_index_payload(state).get(key) or []

    exact = [
        entry
        for entry in entries
        if isinstance(entry, dict)
        and text in {entry.get("qualified_id"), entry.get("catalog_key")}
    ]
    if len(exact) == 1:
        return _catalog_entry_ref_from_value(state, expected_config, exact[0].get("uid"))

    by_id = [
        entry
        for entry in entries
        if isinstance(entry, dict) and entry.get("id") == text
    ]
    if len(by_id) == 1:
        return _catalog_entry_ref_from_value(state, expected_config, by_id[0].get("uid"))
    if len(by_id) > 1:
        # Say which ones, so the next attempt can succeed instead of guessing.
        choices = ", ".join(
            sorted(str(entry.get("qualified_id") or entry.get("id")) for entry in by_id)
        )
        raise ValueError(
            f"{text!r} is ambiguous: it matches more than one "
            f"{expected_config} ({choices}). Use the fuller name."
        )
    return None


def _catalog_entry_ref_from_value(
    state: UiState,
    expected_config: str,
    value: Any,
    *,
    allow_readable_id: bool = False,
) -> Optional[CatalogEntryRef]:
    """Resolve "which catalog entry", from a ref, a token, or (opt-in) a name.

    ``allow_readable_id`` is off by default because two callers use a None
    return as their test for "this is an exact reference": opening an entry's
    source read-only, and launching its interface. Both pin one exact revision,
    and a name that resolves to whatever is current would quietly weaken that.
    Reading, comparing and drafting accept names; pinning does not.
    """

    entry_ref: Optional[CatalogEntryRef] = None
    if isinstance(value, CatalogEntryRef):
        entry_ref = value
    elif isinstance(value, Mapping):
        entry_ref = CatalogEntryRef.from_dict(value)
    else:
        token = str(value or "").strip()
        if token.startswith(CATALOG_ENTRY_REF_TOKEN_PREFIX):
            encoded = token.removeprefix(CATALOG_ENTRY_REF_TOKEN_PREFIX)
            if not encoded or len(encoded) > 16_384:
                raise ValueError("Catalog entry ref token is invalid.")
            try:
                padding = "=" * (-len(encoded) % 4)
                payload = json.loads(
                    base64.urlsafe_b64decode(encoded + padding).decode("utf-8")
                )
            except Exception as error:
                raise ValueError("Catalog entry ref token is invalid.") from error
            if not isinstance(payload, dict):
                raise ValueError("Catalog entry ref token is invalid.")
            entry_ref = CatalogEntryRef.from_dict(payload)
        elif allow_readable_id:
            entry_ref = _catalog_entry_ref_from_readable_id(
                state, expected_config, token
            )
    if entry_ref is not None and entry_ref.kind != expected_config:
        raise ValueError(
            f"Catalog entry ref is for {entry_ref.kind}, not {expected_config}."
        )
    _ = state
    return entry_ref


def _catalog_index_entry_by_ref(state: UiState, entry_ref: CatalogEntryRef) -> JsonDict:
    catalog = _catalog_index_payload(state)
    key = (
        "resources"
        if entry_ref.kind == "resource"
        else {
            "environment": "environments",
            "method": "methods",
            "study": "studies",
        }.get(entry_ref.kind, "")
    )
    for entry in catalog.get(key, []) if key else []:
        raw_ref = entry.get("ref")
        if (
            isinstance(raw_ref, dict)
            and raw_ref.get("ref_digest") == entry_ref.ref_digest
        ):
            return entry
    raise RealmConflict(
        "Catalog entry is not in the current index; use an exact action to open "
        "its retained revision."
    )


def _configured_catalog_entry_ref_path(
    state: UiState, entry_ref: CatalogEntryRef
) -> Path:
    _refresh_catalog_package_roots(state)
    roots = [
        root.resolve()
        for root in state.catalog_roots
        if _configured_catalog_source_id(root) == entry_ref.source_id
    ]
    if len(roots) != 1:
        raise RealmNotFound("Configured catalog import is unavailable.")
    root = roots[0]
    path = (root / Path(*PurePosixPath(entry_ref.focus_path).parts)).resolve()
    if not _is_relative_to(path, root):
        raise RealmIntegrityError("Configured catalog entry escaped its root.")
    if entry_ref.kind == "resource":
        if not path.is_dir():
            raise RealmNotFound("Configured catalog resource is unavailable.")
        actual_id = str(_resource_catalog_entry(path).get("id") or "")
    else:
        if not path.is_file():
            raise RealmNotFound("Configured catalog config is unavailable.")
        raw = _read_yaml(path)
        if raw.get("config") != entry_ref.kind:
            raise RealmIntegrityError("Configured catalog entry kind changed.")
        actual_id = str(raw.get("id") or raw.get("name") or path.stem)
    if actual_id != entry_ref.entry_id:
        raise RealmConflict("Configured catalog entry identity changed.")
    return path


def _is_authorized_catalog_realization_path(state: UiState, path: Path) -> bool:
    """Fence provider paths to configured roots or a live exact consumer."""

    resolved = path.resolve()
    with state._catalog_projection_lock:
        roots = [
            *state._realm_catalog_package_ids,
            *(
                projection.root_path
                for projection in state._catalog_workspace_projections.values()
            ),
        ]
    with state._lock:
        roots.extend(
            job.source_projection.root_path
            for job in state.interface_launches.values()
            if job.source_projection is not None
        )
    roots.extend(root.resolve() for root in state.catalog_roots)
    return any(_is_relative_to(resolved, root) for root in roots)


def _compatibility_payload(state: UiState) -> JsonDict:
    catalog = _catalog_index_payload(state)
    # Derived entirely from that index, and costing about a second to build,
    # yet rebuilt on every request -- the Catalog page asks for both at once,
    # so this was paid on every visit. Key the reuse on the identity of the
    # index it came from, so a refreshed catalog rebuilds it and nothing else
    # does.
    ttl_seconds = state.catalog_refresh_ttl_seconds
    if ttl_seconds > 0:
        with state._catalog_projection_lock:
            cached = state._compatibility_cache
        if (
            cached is not None
            and cached[0] is catalog
            and time.monotonic() - cached[1] < ttl_seconds
        ):
            return cached[2]
    pairs = []
    # Each method's settings file was read once per environment: with the
    # shipped packages that is 182 parses where 13 will do, and parsing is the
    # dominant cost of this whole response. Read each file once.
    method_raws = {
        str(method["_source_path"]): _read_yaml(Path(str(method["_source_path"])))
        for method in catalog["methods"]
    }
    for environment in catalog["environments"]:
        env_raw = _read_yaml(Path(str(environment["_source_path"])))
        for method in catalog["methods"]:
            method_raw = method_raws[str(method["_source_path"])]
            result = _compatibility_result(environment, env_raw, method, method_raw)
            pairs.append(result)
    payload = {
        "environments": [
            _public_catalog_entry(item) for item in catalog["environments"]
        ],
        "methods": [_public_catalog_entry(item) for item in catalog["methods"]],
        "pairs": pairs,
    }
    if ttl_seconds > 0:
        with state._catalog_projection_lock:
            state._compatibility_cache = (catalog, time.monotonic(), payload)
    return payload


def _compatibility_for_catalog_refs(
    state: UiState, environment_value: Any, method_value: Any
) -> JsonDict:
    """Compare two exact catalog entries without accepting provider paths."""

    environment_source = _borrow_catalog_entry_ref_projection(
        state,
        "environment",
        environment_value,
        consumer_kind="catalog-compatibility",
        consumer_metadata={"component_kind": "environment"},
    )
    method_source: Optional[CatalogSourceProjection] = None
    try:
        method_source = _borrow_catalog_entry_ref_projection(
            state,
            "method",
            method_value,
            consumer_kind="catalog-compatibility",
            consumer_metadata={"component_kind": "method"},
        )
    except Exception:
        if environment_source is not None:
            environment_source.close()
        raise
    if environment_source is None or method_source is None:
        if environment_source is not None:
            environment_source.close()
        if method_source is not None:
            method_source.close()
        raise ValueError(
            "Selected-pair compatibility requires immutable Realm catalog refs."
        )
    try:
        environment_ref = _catalog_entry_ref_from_value(
            state, "environment", environment_value, allow_readable_id=True
        )
        method_ref = _catalog_entry_ref_from_value(
            state, "method", method_value, allow_readable_id=True
        )
        assert environment_ref is not None and method_ref is not None
        environment = _read_yaml(environment_source.source_path)
        method = _read_yaml(method_source.source_path)
        environment_entry = _catalog_entry(
            environment_source.source_path,
            environment,
            package_id=environment_source.package_id,
            package_root=environment_source.root_path,
            source_record={
                "source_kind": environment_ref.source_kind,
                "source_id": environment_ref.source_id,
                "source_revision": environment_ref.source_revision,
                "source_digest": environment_ref.source_digest,
            },
        )
        method_entry = _catalog_entry(
            method_source.source_path,
            method,
            package_id=method_source.package_id,
            package_root=method_source.root_path,
            source_record={
                "source_kind": method_ref.source_kind,
                "source_id": method_ref.source_id,
                "source_revision": method_ref.source_revision,
                "source_digest": method_ref.source_digest,
            },
        )
        return _compatibility_result(
            environment_entry,
            environment,
            method_entry,
            method,
        )
    finally:
        method_source.close()
        environment_source.close()


def _compatibility_result(
    environment: JsonDict, env_raw: JsonDict, method: JsonDict, method_raw: JsonDict
) -> JsonDict:
    candidate = (
        env_raw.get("candidate", {})
        if isinstance(env_raw.get("candidate"), dict)
        else {}
    )
    accepts = (
        method_raw.get("accepts", {})
        if isinstance(method_raw.get("accepts"), dict)
        else {}
    )
    requires = (
        accepts.get("requires", {}) if isinstance(accepts.get("requires"), dict) else {}
    )
    env_candidate_format = candidate.get("format")
    method_candidate_formats = list(accepts.get("formats", []) or [])
    required_context = list(requires.get("context", []) or [])
    required_capabilities = list(requires.get("capabilities", []) or [])
    env_context = declared_context_paths(env_raw)
    env_capabilities = {
        str(item.get("id"))
        for item in env_raw.get("capabilities", []) or []
        if isinstance(item, dict) and item.get("id")
    }
    checks = []
    checks.append(
        _compat_check(
            not method_candidate_formats
            or env_candidate_format in method_candidate_formats,
            f"candidate format {env_candidate_format!r} is supported",
            f"method accepts.formats {method_candidate_formats!r}, environment uses {env_candidate_format!r}",
        )
    )
    for required in required_context:
        checks.append(
            _compat_check(
                required in env_context,
                f"required context {required!r} is available",
                f"required context {required!r} is missing",
            )
        )
    for required in required_capabilities:
        checks.append(
            _compat_check(
                required in env_capabilities,
                f"required capability {required!r} is available",
                f"required capability {required!r} is missing",
            )
        )
    produces = method_raw.get("produces")
    if isinstance(produces, dict):
        try:
            mismatch = candidate_contract_mismatch(candidate, produces)
        except Exception as exc:
            mismatch = f"produces contract cannot be compared: {exc}"
        checks.append(
            _compat_check(
                mismatch is None,
                "produced candidate contract matches environment candidate contract",
                mismatch
                or "produced candidate contract does not match environment candidate contract",
            )
        )
    compatible = all(check["ok"] for check in checks)
    return {
        "compatible": compatible,
        "environment": _compat_entity(environment),
        "method": _compat_entity(method),
        "checks": checks,
        "reasons": [check["message"] for check in checks if not check["ok"]]
        or [check["message"] for check in checks],
    }


def _compat_entity(entry: JsonDict) -> JsonDict:
    return {
        "uid": entry["uid"],
        "id": entry["id"],
        "label": entry["label"],
        "path": entry["path"],
        "package_id": entry.get("package_id"),
        "ref": deepcopy(entry.get("ref")),
        "summary": entry.get("summary", {}),
    }


def _compat_check(ok: bool, success: str, failure: str) -> JsonDict:
    return {"ok": ok, "message": success if ok else failure}


def _portable_relative_path(value: Any, label: str) -> str:
    text = str(value or "").strip()
    path = PurePosixPath(text)
    if (
        not text
        or len(text.encode("utf-8")) > 4096
        or "\\" in text
        or path.is_absolute()
        or str(path) != text
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise ValueError(f"{label} must be a canonical portable relative path.")
    return text


def _realm_catalog_ref_for_readable_id(
    state: UiState, expected_config: str, value: Any
) -> Optional[CatalogEntryRef]:
    """Resolve a human-readable name to a REGISTERED catalog entry.

    The Study Builder pins exact Realm catalog revisions, so the generic
    readable-name resolver is not enough here: the same id can appear both as
    a registered entry and as its configured-filesystem source, and only the
    registered one is a valid pinning target. Registered matches win; a
    filesystem-only match is returned as-is so the caller's established
    "import into Realm first" refusal names the actual situation.
    """

    text = str(value or "").strip()
    if not text or text.startswith(CATALOG_ENTRY_REF_TOKEN_PREFIX):
        return None
    key = _CATALOG_KIND_KEYS.get(str(expected_config or ""))
    if not key:
        return None
    entries = [
        entry
        for entry in (_catalog_index_payload(state).get(key) or [])
        if isinstance(entry, dict)
        and text in {entry.get("qualified_id"), entry.get("catalog_key"), entry.get("id")}
    ]
    resolved: List[CatalogEntryRef] = []
    for entry in entries:
        ref = _catalog_entry_ref_from_value(state, expected_config, entry.get("uid"))
        if ref is not None:
            resolved.append(ref)
    realm = [ref for ref in resolved if ref.source_kind == "realm-catalog"]
    if len(realm) == 1:
        return realm[0]
    if len(realm) > 1:
        names = ", ".join(sorted(ref.entry_id for ref in realm))
        raise ValueError(
            f"{text!r} is ambiguous: it matches more than one registered "
            f"{expected_config} ({names}). Use the fuller name."
        )
    return resolved[0] if resolved else None


def _study_builder_sources(state: UiState, payload: JsonDict) -> StudyBuilderSources:
    """Resolve each component through its own exact, action-owned projection."""

    if "environment_path" in payload or "method_path" in payload:
        raise ValueError(
            "Study Builder accepts exact environment_ref and method_ref values; "
            "catalog paths are not action identities."
        )
    environment_ref = _realm_catalog_ref_for_readable_id(
        state, "environment", payload.get("environment_ref")
    ) or _catalog_entry_ref_from_value(
        state, "environment", payload.get("environment_ref")
    )
    method_ref = _realm_catalog_ref_for_readable_id(
        state, "method", payload.get("method_ref")
    ) or _catalog_entry_ref_from_value(
        state, "method", payload.get("method_ref")
    )
    if environment_ref is None or method_ref is None:
        # Name the value when a readable name simply matched nothing, so a
        # typo reads as a typo rather than as a missing exact reference.
        for label, value in (
            ("environment_ref", payload.get("environment_ref")),
            ("method_ref", payload.get("method_ref")),
        ):
            text = str(value or "").strip()
            if text and not text.startswith(CATALOG_ENTRY_REF_TOKEN_PREFIX) and not isinstance(value, Mapping):
                raise ValueError(
                    f"{label} {text!r} does not name any catalog entry."
                )
        raise ValueError(
            "environment_ref and method_ref are required exact catalog entry refs."
        )
    if (
        environment_ref.source_kind != "realm-catalog"
        or method_ref.source_kind != "realm-catalog"
    ):
        raise ValueError(
            "Study Builder requires immutable Realm catalog entries. Import the "
            "configured filesystem package into Realm first."
        )
    environment_source = _borrow_catalog_entry_ref_projection(
        state,
        "environment",
        environment_ref,
        consumer_kind="catalog-study-builder",
        consumer_metadata={"method_ref": method_ref.to_dict()},
    )
    if environment_source is None:
        raise RealmConflict("The exact catalog environment cannot be projected.")
    try:
        method_source = _borrow_catalog_entry_ref_projection(
            state,
            "method",
            method_ref,
            consumer_kind="catalog-study-builder",
            consumer_metadata={"environment_ref": environment_ref.to_dict()},
        )
    except Exception:
        environment_source.close()
        raise
    if method_source is None:
        environment_source.close()
        raise RealmConflict("The exact catalog method cannot be projected.")
    try:
        environment_path = environment_source.source_path
        method_path = method_source.source_path
        environment = _read_yaml(environment_path)
        method = _read_yaml(method_path)
        environment_source_record = {
            "source_kind": environment_ref.source_kind,
            "source_id": environment_ref.source_id,
            "source_revision": environment_ref.source_revision,
            "source_digest": environment_ref.source_digest,
        }
        method_source_record = {
            "source_kind": method_ref.source_kind,
            "source_id": method_ref.source_id,
            "source_revision": method_ref.source_revision,
            "source_digest": method_ref.source_digest,
        }
        compatibility = _compatibility_result(
            _catalog_entry(
                environment_path,
                environment,
                package_id=environment_source.package_id,
                package_root=environment_source.root_path,
                source_record=environment_source_record,
            ),
            environment,
            _catalog_entry(
                method_path,
                method,
                package_id=method_source.package_id,
                package_root=method_source.root_path,
                source_record=method_source_record,
            ),
            method,
        )
        return StudyBuilderSources(
            environment_source=environment_source,
            method_source=method_source,
            environment_ref=environment_ref,
            method_ref=method_ref,
            environment=environment,
            method=method,
            compatibility=compatibility,
        )
    except Exception:
        try:
            environment_source.close()
        finally:
            method_source.close()
        raise


def _public_workspace_value(value: Any, *, workspace_id: str, root: Path) -> Any:
    """Replace a provider checkout prefix in a browser-visible result."""

    logical_root = f"workspace://{workspace_id}"
    if isinstance(value, dict):
        return {
            key: _public_workspace_value(child, workspace_id=workspace_id, root=root)
            for key, child in value.items()
        }
    if isinstance(value, list):
        return [
            _public_workspace_value(child, workspace_id=workspace_id, root=root)
            for child in value
        ]
    if isinstance(value, str):
        return value.replace(str(root), logical_root)
    return value


def _study_builder_component_origins(
    sources: StudyBuilderSources,
) -> list[JsonDict]:
    """Canonical exact refs and roots that define a Study Builder workspace."""

    return [
        {
            "kind": "environment",
            "ref": sources.environment_ref.to_dict(),
            "selection": sources.environment_source.selection.to_dict(),
        },
        {
            "kind": "method",
            "ref": sources.method_ref.to_dict(),
            "selection": sources.method_source.selection.to_dict(),
        },
    ]


def _study_builder_workspace_seed(
    sources: StudyBuilderSources,
) -> WorkspaceSelectionSeed:
    return WorkspaceSelectionSeed.build(
        (
            WorkspaceRequestSource.build(
                selection=sources.environment_source.selection,
                focuses=(
                    WorkspaceFocus(
                        kind="environment",
                        focus_id=sources.environment_ref.entry_id,
                        relative_path=sources.environment_ref.focus_path,
                    ),
                ),
            ),
            WorkspaceRequestSource.build(
                selection=sources.method_source.selection,
                focuses=(
                    WorkspaceFocus(
                        kind="method",
                        focus_id=sources.method_ref.entry_id,
                        relative_path=sources.method_ref.focus_path,
                    ),
                ),
            ),
        )
    )


def _create_study_builder_workspace(
    state: UiState,
    *,
    operation_id: str,
    title: str,
    sources: StudyBuilderSources,
    draft_id: str,
    persist_draft: bool,
) -> tuple[JsonDict, Any]:
    """Create and open one managed workspace from exact whole-tree selections."""

    runtime = _require_realm_runtime(state)
    receipt = runtime.editable_workspaces.create_workspace(
        operation_id=operation_id,
        title=title,
        seed=_study_builder_workspace_seed(sources),
        ttl_seconds=300,
    )
    workspace_id = str(receipt.workspace_id)
    summary = runtime.editable_workspaces.read_workspace(workspace_id=workspace_id)
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"{operation_id}/open-checkout",
        workspace_id=workspace_id,
        expected_workspace_revision=summary.workspace_revision,
    )
    existing = next(
        (
            item
            for item in _read_workspace_index(state)
            if item.get("id") == workspace_id
        ),
        None,
    )
    workspace_payload = _managed_workspace_ui_payload(
        summary,
        checkout,
        existing=existing,
    )
    workspace_payload["description"] = (
        "Realm-managed workspace created by Study Builder"
    )
    workspace_payload["purpose"] = (
        WorkspacePurpose.STUDY_DRAFT_BACKING.value
        if persist_draft
        else WorkspacePurpose.READ_ONLY_SUPPORT.value
    )
    workspace_payload["purpose_subject"] = EntityCoordinate(
        kind="study-draft" if persist_draft else "study-launch",
        entity_id=draft_id,
    ).to_dict()
    return _create_ui_workspace(state, workspace_payload), receipt


def _study_draft_mutation_key(
    state: UiState,
    *,
    payload: Optional[Mapping[str, Any]] = None,
    draft_id: str = "",
) -> str:
    """Return one process-local key shared by save and discard mutations."""

    coordinate_kind = "draft"
    coordinate_id = str(draft_id or "")
    if payload is not None:
        requested_workspace_id = str(payload.get("workspace_id") or "")
        if requested_workspace_id:
            coordinate_kind = "workspace"
            coordinate_id = requested_workspace_id
            stored = next(
                (
                    item
                    for item in _read_workspace_index(state)
                    if item.get("id") == requested_workspace_id
                ),
                None,
            )
            origin = (
                stored.get("catalog_origin")
                if isinstance(stored, Mapping)
                else None
            )
            stored_draft_id = (
                str(origin.get("draft_id") or "")
                if isinstance(origin, Mapping)
                and origin.get("kind") == "study-builder"
                else ""
            )
            if stored_draft_id:
                coordinate_kind = "draft"
                coordinate_id = stored_draft_id
        else:
            request_id = _canonical_request_uuid(payload.get("request_id"))
            coordinate_id = f"draft_{request_id.replace('-', '')}"
    if not coordinate_id:
        raise ValueError("Study draft mutation coordinate is required.")
    return request_digest(
        {
            "schema": "optpilot.studio-study-draft-mutation-lock.v1",
            "kind": coordinate_kind,
            "id": coordinate_id,
        }
    )


@contextmanager
def _serialized_study_draft_mutation(state: UiState, key: str) -> Iterator[None]:
    """Serialize one live Study draft mutation and retire its lock afterward."""

    with state._study_draft_mutation_locks_guard:
        entry = state._study_draft_mutation_locks.get(key)
        if entry is None:
            entry = _StudyDraftMutationLock()
            state._study_draft_mutation_locks[key] = entry
        entry.users += 1
    entry.lock.acquire()
    try:
        yield
    finally:
        entry.lock.release()
        with state._study_draft_mutation_locks_guard:
            current = state._study_draft_mutation_locks.get(key)
            if current is not entry or entry.users <= 0:
                raise RuntimeError("Study draft mutation lock registry changed.")
            entry.users -= 1
            if entry.users == 0:
                del state._study_draft_mutation_locks[key]


def _draft_study(state: UiState, payload: JsonDict) -> JsonDict:
    if not isinstance(payload, dict):
        raise ValueError("Study Builder request must be a JSON object.")
    key = _study_draft_mutation_key(state, payload=payload)
    with _serialized_study_draft_mutation(state, key):
        return _draft_study_serialized(state, payload)


def _draft_study_serialized(state: UiState, payload: JsonDict) -> JsonDict:
    if not isinstance(payload, dict):
        raise ValueError("Study Builder request must be a JSON object.")
    if "operation_id" in payload:
        raise ValueError("Study Builder operation authority is server-derived.")
    persist_draft = payload.get("save_as_draft", False)
    if not isinstance(persist_draft, bool):
        raise ValueError("save_as_draft must be boolean.")
    requested_workspace_id = str(payload.get("workspace_id") or "")
    request_id = (
        None
        if requested_workspace_id
        else _canonical_request_uuid(payload.get("request_id"))
    )
    legacy_placement_fields = sorted(
        key
        for key in (
            "evidenceOutputDir",
            "evidenceStorage",
            "evidence_output_dir",
            "evidence_storage",
        )
        if key in payload
    )
    if legacy_placement_fields:
        raise ValueError(
            "Study evidence storage placement fields were removed; declared "
            "artifacts use managed Realm retention."
        )
    sources = _study_builder_sources(state, payload)
    environment_ref = sources.environment_ref
    method_ref = sources.method_ref
    environment = sources.environment
    compatibility = sources.compatibility
    name = str(
        payload.get("name") or f"{environment_ref.entry_id}-{method_ref.entry_id}"
    )
    description = str(payload.get("description") or "").strip()
    tags = payload.get("tags", [])
    if isinstance(tags, str):
        tags = [item.strip() for item in tags.split(",") if item.strip()]
    if not isinstance(tags, list):
        tags = []
    metric = str(payload.get("metric") or _first_metric(environment) or "score")
    direction = str(payload.get("direction") or "maximize")
    aggregation = str(payload.get("aggregation") or "mean")
    secondary_metrics = payload.get(
        "secondaryMetrics", payload.get("secondary_metrics", [])
    )
    if not isinstance(secondary_metrics, list):
        secondary_metrics = []
    max_trials = int(payload.get("maxTrials", payload.get("max_trials", 12)) or 12)
    max_wall_clock_raw = payload.get(
        "maxWallClockSeconds", payload.get("max_wall_clock_seconds")
    )
    max_failures_raw = payload.get("maxFailures", payload.get("max_failures"))
    parallelism = int(payload.get("parallelism", 1) or 1)
    timeout = int(
        payload.get("timeoutSeconds", payload.get("timeout_seconds", 120)) or 120
    )
    max_retries_raw = payload.get("maxRetries", payload.get("max_retries"))
    evidence_level = str(
        payload.get("evidenceLevel", payload.get("evidence_level", "standard"))
        or "standard"
    )
    draft = {
        "apiVersion": AUTHORING_API_VERSION,
        "config": "study",
        "name": name,
    }
    if description:
        draft["description"] = description
    if tags:
        draft["tags"] = [str(item) for item in tags if str(item)]
    draft.update(
        {
            "objective": {
                "metric": metric,
                "direction": direction,
                "aggregation": aggregation,
                "secondaryMetrics": [str(item) for item in secondary_metrics if item],
            },
            "budget": {"maxTrials": max_trials},
            "execution": {"parallelism": parallelism, "timeoutSeconds": timeout},
            "evidence": {"level": evidence_level},
        }
    )
    if max_wall_clock_raw not in (None, ""):
        max_wall_clock = int(max_wall_clock_raw)
        if max_wall_clock <= 0:
            raise ValueError("maxWallClockSeconds must be >= 1 when provided.")
        draft["budget"]["maxWallClockSeconds"] = max_wall_clock
    if max_failures_raw not in (None, ""):
        max_failures = int(max_failures_raw)
        if max_failures < 0:
            raise ValueError(
                "maxFailures must be >= 1 when provided, or blank/0 for no limit."
            )
        if max_failures > 0:
            draft["budget"]["maxFailures"] = max_failures
    if max_retries_raw not in (None, ""):
        max_retries = int(max_retries_raw)
        if max_retries < 0:
            raise ValueError("maxRetries must be >= 0 when provided.")
        draft["execution"]["retry"] = {"maxRetries": max_retries}
    if payload.get("seed") not in (None, ""):
        draft["reproducibility"] = {"seed": int(payload.get("seed"))}
    workspace: Optional[JsonDict] = None
    component_origins = _study_builder_component_origins(sources)
    assembly_digest = ""
    assembly_outcome = ""
    try:
        if requested_workspace_id:
            expected_revision = payload.get("expected_workspace_revision")
            if (
                isinstance(expected_revision, bool)
                or not isinstance(expected_revision, int)
                or expected_revision <= 0
            ):
                raise ValueError(
                    "expected_workspace_revision is required when updating a draft."
                )
            workspace = _require_ui_workspace(state, requested_workspace_id)
            if workspace.get("ownership") != "realm-managed":
                raise ValueError(
                    "Study Builder drafts require a Realm-managed workspace."
                )
            if int(workspace.get("realm_workspace_revision") or 0) != expected_revision:
                raise RealmConflict("Workspace revision changed.")
            if workspace.get("reopen_required"):
                workspace = _reopen_managed_workspace(
                    state,
                    requested_workspace_id,
                    {"expected_workspace_revision": expected_revision},
                )
            origin = workspace.get("catalog_origin")
            if not isinstance(origin, dict) or origin.get("kind") != "study-builder":
                raise ValueError(
                    "The selected workspace was not created by Study Builder."
                )
            if origin.get("components") != component_origins:
                raise RealmConflict(
                    "Study Builder component refs differ from the workspace base assembly."
                )
            assembly_digest = str(origin.get("assembly_digest") or "")
            assembly_outcome = str(origin.get("assembly_outcome") or "")
            if not re.fullmatch(r"[0-9a-f]{64}", assembly_digest):
                raise RealmIntegrityError(
                    "Study Builder workspace assembly digest is invalid."
                )
            if assembly_outcome not in {"adopt", "union"}:
                raise RealmIntegrityError(
                    "Study Builder workspace assembly outcome is invalid."
                )
            draft_id = str(origin.get("draft_id") or "")
            study_relative_path = _portable_relative_path(
                origin.get("study_relative_path"), "stored study relative path"
            )
        else:
            assert request_id is not None
            request_hex = request_id.replace("-", "")
            draft_id = f"draft_{request_hex}"
            study_relative_path = f"studies/draft-{request_hex}.yaml"
            workspace, assembly_receipt = _create_study_builder_workspace(
                state,
                operation_id=_workspace_create_operation_id(
                    "study-builder", request_id
                ),
                title=f"Study plan: {name}",
                sources=sources,
                draft_id=draft_id,
                persist_draft=persist_draft,
            )
            assembly_digest = str(assembly_receipt.assembly_digest)
            raw_outcome = assembly_receipt.outcome
            assembly_outcome = str(getattr(raw_outcome, "value", raw_outcome))

        assert workspace is not None
        workspace_id = str(workspace["id"])
        draft_action_id: Optional[str] = None
        expected_draft_revision: Optional[int] = None
        if persist_draft:
            draft_action_id = _canonical_request_uuid(payload.get("draft_action_id"))
            expected_draft_revision = payload.get("expected_draft_revision")
            if expected_draft_revision is not None and (
                isinstance(expected_draft_revision, bool)
                or not isinstance(expected_draft_revision, int)
                or expected_draft_revision <= 0
            ):
                raise ValueError(
                    "expected_draft_revision must be a positive integer."
                )
            try:
                current_draft = state.coordination.get_study_draft(draft_id)
            except CoordinationNotFound:
                current_draft = None
            if current_draft is None and expected_draft_revision is not None:
                raise RealmConflict("Study draft no longer exists.")
            if current_draft is not None:
                if current_draft.actor_id != _studio_actor_id(state):
                    raise RealmConflict(
                        "Study draft belongs to another local author."
                    )
                if expected_draft_revision != current_draft.revision:
                    raise RealmConflict(
                        "Study draft changed; reload before saving."
                    )
        root = _safe_workspace_root(state, Path(str(workspace["root"])).resolve())
        study_path = (root / Path(*PurePosixPath(study_relative_path).parts)).resolve()
        if not _is_relative_to(study_path, root):
            raise RealmIntegrityError("Study Builder path escaped its workspace.")
        environment_path = (
            root / Path(*PurePosixPath(environment_ref.focus_path).parts)
        ).resolve()
        method_path = (
            root / Path(*PurePosixPath(method_ref.focus_path).parts)
        ).resolve()
        if not environment_path.is_file() or not method_path.is_file():
            raise RealmIntegrityError(
                "Study Builder workspace omitted an exact catalog component."
            )
        study_parent = PurePosixPath(study_relative_path).parent.as_posix()
        draft["environmentConfig"] = posixpath.relpath(
            environment_ref.focus_path, start=study_parent
        )
        draft["methodConfig"] = posixpath.relpath(
            method_ref.focus_path, start=study_parent
        )
        draft_yaml = yaml.safe_dump(draft, sort_keys=False)
        study_path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_write_text(study_path, draft_yaml)
        raw_validation = _validate_study(study_path, state=state)
        validation = _public_workspace_value(
            raw_validation, workspace_id=workspace_id, root=root
        )
        origin = {
            "kind": "study-builder",
            "assembly_digest": assembly_digest,
            "assembly_outcome": assembly_outcome,
            "components": component_origins,
            "draft_id": draft_id,
            "study_relative_path": study_relative_path,
        }
        workspace["catalog_origin"] = origin
        workspace["description"] = "Realm-managed workspace created by Study Builder"
        workspace["registered_entries"] = [
            {
                "kind": "study",
                "id": name,
                "authoring_relative_path": study_relative_path,
                "catalog_relative_path": study_relative_path,
            }
        ]
        workspace["focus_paths"] = [study_relative_path]
        workspace["validation"] = validation
        workspace["status"] = "ready" if validation.get("valid") else "review"
        workspace = _upsert_ui_workspace(state, workspace)
        committed = _commit_managed_workspace_file(
            state,
            workspace_id,
            expected_workspace_revision=int(workspace["realm_workspace_revision"]),
            relative_path=study_relative_path,
        )
        workspace = committed["workspace"]
        draft_record = None
        if persist_draft:
            assert draft_action_id is not None
            config_digest = hashlib.sha256(
                draft_yaml.encode("utf-8")
            ).hexdigest()
            draft_record = state.coordination.save_study_draft(
                operation_id=f"studio/study-draft/{draft_action_id}",
                draft_id=draft_id,
                actor_id=_studio_actor_id(state),
                title=name,
                workspace_id=workspace_id,
                workspace_revision=int(workspace["realm_workspace_revision"]),
                study_relative_path=study_relative_path,
                config_digest=config_digest,
                expected_revision=expected_draft_revision,
            )
        return {
            "draft_id": draft_id,
            "workspace_id": workspace_id,
            "workspace_revision": int(workspace["realm_workspace_revision"]),
            "study_relative_path": study_relative_path,
            "draft": draft,
            "yaml": draft_yaml,
            "compatibility": compatibility,
            "validation": validation,
            "saved_as_draft": draft_record is not None,
            "draft_revision": None if draft_record is None else draft_record.revision,
        }
    finally:
        sources.close()


def _saved_study_draft_payload(
    state: UiState,
    record: Any,
    stored_workspace: Optional[Mapping[str, Any]],
    *,
    availability: Optional[Mapping[str, Any]] = None,
) -> JsonDict:
    workspace = dict(stored_workspace or {})
    availability_payload: JsonDict = dict(
        availability
        or {
            "available": True,
            "code": "ready",
            "reason": None,
        }
    )
    config: JsonDict = {}
    yaml_text = ""
    root: Optional[Path] = None
    path: Optional[Path] = None
    origin = workspace.get("catalog_origin")
    components = (
        origin.get("components", [])
        if isinstance(origin, Mapping)
        else []
    )
    refs = {
        str(item.get("kind")): item.get("ref")
        for item in components
        if isinstance(item, Mapping) and item.get("kind") and item.get("ref")
    }
    if availability_payload.get("available"):
        expected_subject = EntityCoordinate(
            kind="study-draft", entity_id=record.draft_id
        ).to_dict()
        origin_valid = (
            isinstance(origin, Mapping)
            and origin.get("kind") == "study-builder"
            and origin.get("draft_id") == record.draft_id
            and origin.get("study_relative_path") == record.study_relative_path
            and set(refs) == {"environment", "method"}
            and workspace.get("purpose_subject") in ({}, expected_subject)
        )
        try:
            if origin_valid:
                refs = {
                    kind: CatalogEntryRef.from_dict(value).to_dict()
                    for kind, value in refs.items()
                }
        except (TypeError, ValueError):
            origin_valid = False
        if not origin_valid:
            availability_payload = {
                "available": False,
                "code": "draft-metadata-unavailable",
                "reason": (
                    "The saved draft is preserved, but its exact component "
                    "references are unavailable."
                ),
            }
    if availability_payload.get("available"):
        root_text = str(workspace.get("root") or "")
        try:
            if not root_text:
                raise FileNotFoundError
            root = _safe_workspace_root(
                state, Path(root_text).expanduser().resolve()
            )
            path = (
                root / Path(*PurePosixPath(record.study_relative_path).parts)
            ).resolve()
            if not _is_relative_to(path, root) or not path.is_file():
                raise FileNotFoundError
            yaml_text = path.read_text(encoding="utf-8")
        except (OSError, RealmConflict, RealmIntegrityError, ValueError):
            availability_payload = {
                "available": False,
                "code": "draft-file-unavailable",
                "reason": (
                    "The saved draft is preserved, but its files could not be "
                    "reopened."
                ),
            }
            yaml_text = ""
    if availability_payload.get("available"):
        if (
            hashlib.sha256(yaml_text.encode("utf-8")).hexdigest()
            != record.config_digest
        ):
            availability_payload = {
                "available": False,
                "code": "draft-content-changed",
                "reason": (
                    "The reopened files do not match the exact saved draft version."
                ),
            }
            yaml_text = ""
        else:
            try:
                raw = yaml.safe_load(yaml_text)
            except yaml.YAMLError:
                raw = None
            if isinstance(raw, dict):
                config = raw
            else:
                availability_payload = {
                    "available": False,
                    "code": "draft-content-invalid",
                    "reason": "The exact saved draft is not a valid Study document.",
                }
                yaml_text = ""
    validation: JsonDict = {}
    if (
        availability_payload.get("available")
        and root is not None
        and path is not None
    ):
        validation = _public_workspace_value(
            _validate_study(path, state=state),
            workspace_id=record.workspace_id,
            root=root,
        )
    return {
        "record": record.to_dict(),
        "draft_id": record.draft_id,
        "draft_revision": record.revision,
        "title": record.title,
        "workspace_id": record.workspace_id,
        "workspace_revision": record.workspace_revision,
        "study_relative_path": record.study_relative_path,
        "environment_ref": refs.get("environment"),
        "method_ref": refs.get("method"),
        "config": config,
        "yaml": yaml_text,
        # Launch support and local-value readiness can change after a draft is
        # saved (for example after Studio is upgraded or Settings are edited).
        # Re-evaluate the exact saved file instead of replaying a cached verdict.
        "validation": validation,
        "availability": availability_payload,
    }


def _recover_saved_study_draft_workspace(
    state: UiState,
    record: Any,
    stored_workspace: Optional[Mapping[str, Any]],
) -> tuple[Optional[JsonDict], JsonDict]:
    """Reopen one draft's exact managed revision without changing its identity."""

    def unavailable(code: str, reason: str) -> tuple[Optional[JsonDict], JsonDict]:
        return (
            None if stored_workspace is None else dict(stored_workspace),
            {"available": False, "code": code, "reason": reason},
        )
    if not _managed_workspace_provider_available(state):
        return unavailable(
            "workspace-provider-unavailable",
            "The saved draft is preserved, but editable Workspace storage is unavailable.",
        )
    runtime = state.realm_runtime
    assert runtime is not None
    try:
        summary = runtime.editable_workspaces.read_workspace(
            workspace_id=record.workspace_id
        )
    except (RealmConflict, RealmIntegrityError, RealmNotFound):
        return unavailable(
            "workspace-unavailable",
            "The saved draft is preserved, but its editable Workspace is unavailable.",
        )
    if summary.workspace_revision != record.workspace_revision:
        return unavailable(
            "workspace-revision-changed",
            "The saved draft no longer matches the current editable Workspace version.",
        )
    try:
        purpose = state.coordination.get_workspace_purpose(record.workspace_id)
    except CoordinationNotFound:
        return unavailable(
            "draft-metadata-unavailable",
            "The saved draft is preserved, but its Workspace purpose is unavailable.",
        )
    if (
        purpose.purpose is not WorkspacePurpose.STUDY_DRAFT_BACKING
        or purpose.subject
        != EntityCoordinate(kind="study-draft", entity_id=record.draft_id)
    ):
        return unavailable(
            "draft-metadata-conflict",
            "The saved draft is preserved, but its Workspace is assigned to another purpose.",
        )
    existing = dict(
        stored_workspace
        or _managed_workspace_placeholder(summary, attached_sessions=[])
    )
    coordinate = request_digest(
        {
            "schema": "optpilot.studio-study-draft-reopen.v1",
            "draft_id": record.draft_id,
            "workspace_id": record.workspace_id,
            "workspace_revision": record.workspace_revision,
        }
    )
    try:
        checkout = runtime.editable_workspaces.open_workspace(
            operation_id=f"studio/study-draft/reopen/{coordinate}",
            workspace_id=record.workspace_id,
            expected_workspace_revision=record.workspace_revision,
        )
        workspace = _create_ui_workspace(
            state,
            _managed_workspace_ui_payload(summary, checkout, existing=existing),
        )
    except (OSError, RealmConflict, RealmIntegrityError, RealmNotFound, ValueError):
        return unavailable(
            "workspace-recovery-failed",
            "The saved draft is preserved, but its files could not be reopened safely.",
        )
    return workspace, {"available": True, "code": "ready", "reason": None}


def _list_saved_study_drafts(state: UiState) -> JsonDict:
    records = state.coordination.list_study_drafts(actor_id=_studio_actor_id(state))
    workspaces = {
        str(item.get("id")): item for item in _read_workspace_index(state)
    }
    drafts = []
    for record in records:
        workspace, availability = _recover_saved_study_draft_workspace(
            state, record, workspaces.get(record.workspace_id)
        )
        drafts.append(
            _saved_study_draft_payload(
                state,
                record,
                workspace,
                availability=availability,
            )
        )
    return {
        "schema": "optpilot.studio-study-draft-list.v1",
        "drafts": drafts,
    }


def _discard_saved_study_draft(
    state: UiState, draft_id: str, payload: Any
) -> JsonDict:
    key = _study_draft_mutation_key(state, draft_id=draft_id)
    with _serialized_study_draft_mutation(state, key):
        return _discard_saved_study_draft_serialized(state, draft_id, payload)


def _discard_saved_study_draft_serialized(
    state: UiState, draft_id: str, payload: Any
) -> JsonDict:
    request = _exact_json_object(
        payload,
        expected={"request_id", "expected_revision"},
        label="Discard Study draft request",
    )
    request_id = _canonical_request_uuid(request["request_id"])
    expected_revision = request["expected_revision"]
    if (
        isinstance(expected_revision, bool)
        or not isinstance(expected_revision, int)
        or expected_revision <= 0
    ):
        raise ValueError("expected_revision must be a positive integer.")
    record = state.coordination.discard_study_draft(
        operation_id=f"studio/study-draft/{request_id}/discard",
        draft_id=draft_id,
        actor_id=_studio_actor_id(state),
        expected_revision=expected_revision,
    )
    stored = next(
        (
            item
            for item in _read_workspace_index(state)
            if item.get("id") == record.workspace_id
        ),
        None,
    )
    if stored is not None:
        stored = dict(stored)
        stored["purpose"] = WorkspacePurpose.READ_ONLY_SUPPORT.value
        stored["purpose_subject"] = EntityCoordinate(
            kind="discarded-study", entity_id=record.draft_id
        ).to_dict()
        _set_workspace_purpose(
            state,
            stored,
            purpose=WorkspacePurpose.READ_ONLY_SUPPORT,
            subject=EntityCoordinate(
                kind="discarded-study", entity_id=record.draft_id
            ),
        )
        _upsert_ui_workspace(state, stored)
    return {
        "schema": "optpilot.studio-study-draft-discard.v1",
        "draft": record.to_dict(),
    }


def _open_study_workspace(state: UiState, payload: JsonDict) -> JsonDict:
    source_path: Optional[Path] = None
    if payload.get("study_path"):
        source_path = _resolve_user_path(payload.get("study_path"), state.cwd)
        study_yaml = source_path.read_text(encoding="utf-8")
        validation = _validate_study(source_path, state=state)
        raw = _read_yaml(source_path)
        title = str(raw.get("name") or raw.get("id") or source_path.stem)
    else:
        draft = _draft_study(state, payload)
        return _require_ui_workspace(state, str(draft["workspace_id"]))

    workspace_id = f"ws_study_{uuid.uuid4().hex[:10]}"
    root = state.workspaces_dir / workspace_id / "workspace"
    root.mkdir(parents=True, exist_ok=False)
    (root / "study.yaml").write_text(study_yaml, encoding="utf-8")
    (root / "README.md").write_text(
        f"# {title}\n\nThis workspace contains an editable OptPilot study plan. Review `study.yaml`, then launch it from Studies.\n",
        encoding="utf-8",
    )
    return _create_ui_workspace(
        state,
        {
            "id": workspace_id,
            "title": f"Study plan: {title}",
            "root": str(root),
            "source_type": "study-plan",
            "mode": "editable",
            "status": "ready" if validation.get("valid") else "review",
            "description": "Editable study plan workspace",
            "source_path": str(source_path) if source_path else "",
            "focus_paths": ["study.yaml", "README.md"],
            "registration_enabled": False,
        },
    )


def _study_ref_matches(value: Any, study_path: Path, expected_path: Path) -> bool:
    if not value:
        return False
    return _resolve_config_path(value, study_path) == expected_path.resolve()


def _resolve_config_path(value: Any, config_path: Path) -> Path:
    path = Path(str(value)).expanduser()
    if not path.is_absolute():
        path = config_path.parent / path
    return path.resolve()


def _first_metric(environment: JsonDict) -> Optional[str]:
    metrics = (
        environment.get("metrics", {})
        if isinstance(environment.get("metrics"), dict)
        else {}
    )
    keys = metrics.get("keys", [])
    if isinstance(keys, list) and keys:
        return str(keys[0])
    return None


def _evaluator_mode(evaluator: JsonDict) -> Optional[str]:
    for key in ("python", "command", "adapter"):
        if evaluator.get(key):
            return key
    return None


def _entrypoint_mode(entrypoint: JsonDict) -> Optional[str]:
    for key in ("python", "command"):
        if entrypoint.get(key):
            return key
    return None


def _environment_runtime_summary(raw: JsonDict) -> JsonDict:
    evaluator = (
        raw.get("evaluator", {}) if isinstance(raw.get("evaluator"), dict) else {}
    )
    runtime = raw.get("runtime", {}) if isinstance(raw.get("runtime"), dict) else {}
    return {
        "evaluate_type": _evaluator_mode(evaluator),
        "timeoutSeconds": evaluator.get("timeoutSeconds"),
        "has_python_path": bool(evaluator.get("pythonPath")),
        "sandbox": runtime.get("sandbox", "process"),
    }


def _method_runtime_summary(raw: JsonDict) -> JsonDict:
    runtime = raw.get("runtime", {}) if isinstance(raw.get("runtime"), dict) else {}
    container = (
        runtime.get("container", {})
        if isinstance(runtime.get("container", {}), dict)
        else {}
    )
    return {
        "type": runtime.get("sandbox", "process"),
        "image": container.get("image"),
        "has_build": bool(container.get("build")),
        "networkPolicy": container.get("network", "disabled")
        if runtime.get("sandbox") == "container"
        else "disabled",
    }


def _require_realm_runtime(state: UiState) -> LocalRealmRuntime:
    runtime = state.realm_runtime
    if runtime is None:
        raise RuntimeError("Studio Realm runtime is not configured.")
    if getattr(runtime, "closed", False):
        raise RuntimeError("Studio Realm runtime is closed.")
    return runtime


def _configured_study_package_root(state: UiState, study_path: Path) -> Path:
    """Select the unique most-specific configured package containing a study."""

    _refresh_realm_catalog_projections(
        state, max_age_seconds=state.catalog_refresh_ttl_seconds
    )
    with state._catalog_projection_lock:
        realm_roots = list(state._realm_catalog_package_ids)
    return _most_specific_study_package_root(
        study_path,
        [*realm_roots, *state.catalog_roots],
        missing_message=(
            "Study must be inside one of Studio's configured catalog package roots."
        ),
    )


def _assistant_study_package_root(
    state: UiState,
    session_id: str,
    study_path: Path,
) -> Path:
    _refresh_realm_catalog_projections(
        state, max_age_seconds=state.catalog_refresh_ttl_seconds
    )
    with state._catalog_projection_lock:
        roots = [*state._realm_catalog_package_ids, *state.catalog_roots]
    session = _require_agent_session(state, session_id)
    for workspace_id in session.get("attached_workspace_ids", []) or []:
        workspace = _workspace_by_id(state, str(workspace_id))
        if not workspace:
            continue
        roots.append(
            _safe_workspace_root(
                state,
                Path(str(workspace.get("root") or "")),
            )
        )
    return _most_specific_study_package_root(
        study_path,
        roots,
        missing_message=(
            "Smoke study must be inside a configured catalog package or an "
            "attached server-known workspace root."
        ),
    )


def _most_specific_study_package_root(
    study_path: Path,
    roots: Iterable[Path],
    *,
    missing_message: str,
) -> Path:
    try:
        selected_study = study_path.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise ValueError(f"Study path does not exist: {study_path}.") from exc
    if not selected_study.is_file():
        raise ValueError(f"Study path is not a file: {selected_study}.")

    candidates: List[Path] = []
    for configured in roots:
        try:
            package_root = configured.resolve(strict=True)
        except (OSError, RuntimeError):
            continue
        if package_root.is_dir() and _is_relative_to(selected_study, package_root):
            candidates.append(package_root)
    if not candidates:
        raise ValueError(missing_message)

    greatest_depth = max(len(path.parts) for path in candidates)
    most_specific = _dedupe_paths(
        path for path in candidates if len(path.parts) == greatest_depth
    )
    if len(most_specific) != 1:
        raise ValueError(
            "Study package is ambiguous across equally specific configured catalog roots."
        )
    return most_specific[0]


def _job_for_run_id(state: UiState, run_id: str) -> Optional[StudyLaunchView]:
    """Resolve Studio's compatibility row from durable Core launch views."""

    launch, _diagnostic = _job_for_run_id_resolution(state, run_id)
    return launch


def _job_for_run_id_resolution(
    state: UiState,
    run_id: str,
) -> tuple[Optional[StudyLaunchView], Optional[JsonDict]]:
    """Resolve optional Study metadata without making a valid Run disappear."""

    if not _study_launch_provider_available(state):
        return None, None
    try:
        return (
            _study_launch_service_for_state(state).read_for_run(run_id=run_id),
            None,
        )
    except RealmNotFound:
        return None, None
    except RealmIntegrityError as error:
        # A Run is independently retained Core evidence.  An older or damaged
        # optional Study-launch record must not make that Run—or every Run in
        # the list—unreadable.  Do not interpret or migrate the incompatible
        # record; omit only its convenience metadata and return a bounded,
        # non-sensitive diagnostic to the list projection.
        unsupported = str(error) == (
            "Study launch retained input facts are unsupported."
        )
        return None, {
            "code": (
                "older_study_metadata_unsupported"
                if unsupported
                else "study_metadata_unavailable"
            ),
            "message": (
                "This Run was created with an older Study metadata format. "
                "Its retained Run results remain available, but some Study "
                "details are omitted."
                if unsupported
                else "This Run's optional Study metadata could not be verified. "
                "Its retained Run results remain available, but some Study "
                "details are omitted."
            ),
            "run_id": run_id,
        }


def _required_canonical_run_id(arguments: JsonDict) -> str:
    if arguments.get("path"):
        raise ValueError(
            "Run tools require a canonical Realm run_id; filesystem paths are unsupported."
        )
    run_id = str(arguments.get("run_id") or "").strip()
    if not run_id:
        raise ValueError("run_id is required.")
    # Construction applies the canonical public bound before any Realm read.
    return RunViewRef(run_id=run_id).run_id


def _operator_job_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and isinstance(getattr(runtime, "operator_jobs", None), RealmOperatorJobService)
    )


def _study_launch_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and isinstance(
            getattr(runtime, "study_launches", None), RealmStudyLaunchService
        )
    )


def _study_launch_service_for_state(state: UiState) -> RealmStudyLaunchService:
    if not _study_launch_provider_available(state):
        raise RealmConflict("Core study launch service is unavailable.")
    service = _require_realm_runtime(state).study_launches
    if not isinstance(service, RealmStudyLaunchService):  # pragma: no cover
        raise RealmIntegrityError("Core study launch service is invalid.")
    return service


def _editable_workspace_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    return (
        _managed_workspace_provider_available(state)
        and getattr(runtime, "selection_actions", None) is not None
    )


def _managed_workspace_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and getattr(runtime, "editable_workspaces", None) is not None
    )


def _environment_preview_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    service = getattr(runtime, "operator_jobs", None) if runtime is not None else None
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and isinstance(service, RealmOperatorJobService)
        and bool(getattr(service, "environment_preview_available", False))
        and getattr(runtime, "environment_preview_binder", None) is not None
        and getattr(runtime, "container_web_provider", None) is not None
    )


def _selection_content_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and getattr(runtime, "selection_content", None) is not None
    )


def _candidate_comparison_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    run_views = getattr(runtime, "run_views", None)
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and callable(getattr(run_views, "compare_candidates", None))
    )


def _child_run_provider_available(state: UiState) -> bool:
    runtime = state.realm_runtime
    service = getattr(runtime, "child_runs", None) if runtime is not None else None
    return (
        runtime is not None
        and not getattr(runtime, "closed", False)
        and isinstance(service, RealmChildRunService)
        and callable(getattr(service, "prepare_exact_plan_selection_batch", None))
        and callable(
            getattr(
                service,
                "prepare_exact_plan_selection_batch_from_snapshot",
                None,
            )
        )
        and callable(getattr(service, "create_prepared_exact_plan", None))
        and callable(getattr(getattr(runtime, "run_execution", None), "execute", None))
    )


def _child_run_service_for_state(state: UiState) -> RealmChildRunService:
    if not _child_run_provider_available(state):
        raise RealmConflict("Child Run provider is unavailable.")
    runtime = _require_realm_runtime(state)
    service = runtime.child_runs
    assert isinstance(service, RealmChildRunService)
    return service


def _global_workbench_action_capabilities(
    state: UiState, capabilities: Iterable[Mapping[str, Any]]
) -> List[JsonDict]:
    """Overlay server-composed provider support without minting authority."""

    result: List[JsonDict] = []
    for raw in capabilities:
        item = dict(raw)
        action = item.get("action")
        if action == "inspect":
            item.update(supported=True, eligible=True, reason=None)
        elif action == "debug_run":
            supported = _operator_job_provider_available(state)
            item.update(
                supported=supported,
                eligible=supported,
                reason=None if supported else "operator_job_provider_unavailable",
            )
        elif action == "environment_preview":
            supported = _environment_preview_provider_available(state)
            item.update(
                supported=supported,
                eligible=False,
                reason=(
                    "candidate_selection_required"
                    if supported
                    else "environment_preview_provider_unavailable"
                ),
            )
        elif action == "open_read_only":
            supported = _selection_content_provider_available(state)
            item.update(
                supported=supported,
                eligible=False,
                reason=(
                    "selection_required"
                    if supported
                    else "selection_content_provider_unavailable"
                ),
            )
        elif action == "keep_editable":
            supported = _editable_workspace_provider_available(state)
            item.update(
                supported=supported,
                eligible=False,
                reason=(
                    "retained_tree_selection_required"
                    if supported
                    else "editable_workspace_provider_unavailable"
                ),
            )
        elif action == "evaluate_child_run":
            supported = _child_run_provider_available(state)
            item.update(
                supported=supported,
                eligible=False,
                reason=(
                    "candidate_selection_required"
                    if supported
                    else "child_run_provider_unavailable"
                ),
            )
        elif action == "compare":
            supported = _candidate_comparison_provider_available(state)
            item.update(
                supported=supported,
                eligible=False,
                reason=(
                    "candidate_comparison_selection_required"
                    if supported
                    else "candidate_comparison_provider_unavailable"
                ),
            )
        elif action == "ask_assistant":
            # Studio can mint a session-bound opaque handle for the exact
            # path-free presentation selection. Sending remains a separate
            # explicit action and starts no run execution.
            item.update(supported=True, eligible=True, reason=None)
        result.append(item)
    return result


def _candidate_action_target(
    state: UiState,
    *,
    run_id: str,
    presentation_selection: Mapping[str, Any],
) -> tuple[Any, Optional[str]]:
    """Remint one candidate selection and resolve its current retained closure."""

    runtime = _require_realm_runtime(state)
    selection_result = runtime.run_views.mint_selection(
        ref=RunViewRef(run_id=run_id),
        presentation_selection=presentation_selection,
    )
    selection = selection_result.selection
    if selection is None or selection.kind != "candidate":
        return None, "candidate_selection_required"
    try:
        target = runtime.inspection_targets.resolve_candidate(selection=selection)
    except RealmNotFound:
        return None, "candidate_derivation_unavailable"
    if not target.candidate_available:
        return target, "candidate_content_unavailable"
    if target.evaluation.availability != "available":
        return target, "evaluation_content_unavailable"
    return target, None


def _child_run_preparation_batch(
    state: UiState,
    *,
    capability_facts: Iterable[Any],
    snapshot: Any = None,
) -> tuple[Mapping[str, ExactPlanChildRunSelectionPreparation], Optional[str]]:
    """Prepare singleton exact plans in one actor-bound batch.

    The first Workbench page supplies its already-authorized bundle snapshot,
    so this adds no Realm read. Independently paged results use the service's
    one-read batch API. No row performs its own snapshot read.
    """

    if not _child_run_provider_available(state):
        return {}, "child_run_provider_unavailable"
    selections = tuple(
        fact.selection
        for fact in capability_facts
        if fact is not None and fact.selection.kind == "candidate"
    )
    if not selections:
        return {}, "candidate_selection_required"
    runtime = _require_realm_runtime(state)
    service = runtime.child_runs
    try:
        if snapshot is not None:
            prepared = service.prepare_exact_plan_selection_batch_from_snapshot(
                snapshot=snapshot,
                selections=selections,
            )
        else:
            prepared = service.prepare_exact_plan_selection_batch(
                selections=selections,
            )
    except ValueError as error:
        message = str(error).casefold()
        if "sealed terminal parent" in message or "terminal parent" in message:
            reason = "sealed_terminal_parent_required"
        elif "coordinate" in message or "logical trial" in message:
            reason = "candidate_has_no_exact_parent_evaluations"
        else:
            reason = "exact_plan_preparation_unavailable"
        return {}, reason
    except (RealmConflict, RealmNotFound):
        return {}, "run_head_changed_refresh_required"
    return prepared, None


def _public_exact_plan_preset(
    *,
    prepared: ExactPlanChildRunReceipt,
    target: Any,
) -> JsonDict:
    """Project the exact internal request to the browser-safe confirmation set."""

    if not isinstance(prepared, ExactPlanChildRunReceipt):
        raise TypeError("prepared child-run plan must be an ExactPlanChildRunReceipt.")
    request = prepared.request
    if len(request.candidates) != 1:
        raise RealmIntegrityError(
            "Studio exact-plan preset must contain exactly one candidate."
        )
    candidate = request.candidates[0]
    if (
        target is None
        or target.candidate.candidate_id != candidate.candidate_id
        or target.selection.entity_ref != str(candidate.candidate_ref)
    ):
        raise RealmIntegrityError(
            "Studio exact-plan preset differs from its batched candidate facts."
        )
    template = target.evaluation.closure.evaluation_template
    environment = target.evaluation.closure.environment_revision
    primary = dict(template.objective).get("primaryMetric")
    if not isinstance(primary, Mapping):
        raise RealmIntegrityError("Retained objective primary metric is unavailable.")
    coordinates = [
        {
            "seed": coordinate.to_dict()["seed"],
            "repetition_index": coordinate.repetition_index,
        }
        for coordinate in request.evaluation_plan.coordinates
    ]
    return {
        "schema": RE_EVALUATE_EXACT_PLAN_PRESET_SCHEMA,
        "id": RE_EVALUATE_EXACT_PLAN_PRESET_ID,
        "parent_run_id": request.parent.run_id,
        "parent_seal_digest": request.parent.seal_digest,
        "plan_digest": prepared.plan_digest,
        "candidate": {
            "id": candidate.candidate_id,
            "format": target.candidate.admission.envelope.candidate_format,
        },
        "environment": {
            "id": environment.environment_id,
            "revision": environment.digest,
        },
        "objective": {
            "metric": primary.get("name"),
            "direction": primary.get("direction"),
        },
        "coordinates": coordinates,
        "logical_trials": len(coordinates),
        "max_trials": request.max_trials,
        "method_proposals": False,
    }


def _public_candidate_try_plan(
    *,
    target: Any,
    mode: str,
    interface_profile_id: Optional[str] = None,
) -> JsonDict:
    """Project the immutable, read-only settings for one Candidate try mode."""

    if mode not in {"try_once", "try_interactively"}:
        raise ValueError("Candidate try mode is unsupported.")
    environment = target.evaluation.closure.environment_revision
    settings: JsonDict = {
        "seed": None,
        "repetition_index": None,
        "interface_profile_id": None,
    }
    if mode == "try_once":
        # The action itself compiles the same retained default through
        # ``compile_evaluation_spec``.  Read the immutable template here so
        # capability projection does not compile the runtime a second time.
        template = target.evaluation.closure.evaluation_template
        settings.update(
            seed=template.to_dict()["default_seed"],
            repetition_index=0,
        )
    else:
        settings["interface_profile_id"] = interface_profile_id
    return {
        "schema": CANDIDATE_TRY_PLAN_SCHEMA,
        "mode": mode,
        "candidate_id": target.candidate.candidate_id,
        "environment": {
            "id": environment.environment_id,
            "revision": environment.digest,
        },
        "settings": settings,
    }


def _row_workbench_action_capabilities(
    state: UiState,
    *,
    run_id: str,
    row: Mapping[str, Any],
    capability_facts: Any = None,
    child_run_preparation: Any = None,
    child_run_preparation_reason: Optional[str] = None,
) -> List[JsonDict]:
    selection = row.get("selection")
    if not isinstance(selection, Mapping):
        raise ValueError("Workbench row is missing its presentation selection.")
    kind = selection.get("kind")
    target = None
    unavailable_reason = "candidate_selection_required"
    if kind == "candidate":
        if capability_facts is None:
            raise RealmIntegrityError(
                "Candidate Workbench row is missing exact-head capability facts."
            )
        target = capability_facts.candidate_target
        unavailable_reason = (
            "candidate_derivation_unavailable" if target is None else None
        )
        if target is not None and not target.candidate_available:
            unavailable_reason = "candidate_content_unavailable"
        elif target is not None and target.evaluation.availability != "available":
            unavailable_reason = "evaluation_content_unavailable"
    if kind in {"candidate", "artifact"}:
        if capability_facts is None:
            raise RealmIntegrityError(
                "Content-bearing Workbench row is missing exact-head capability facts."
            )
        content_resolution = capability_facts.content
        content_viewable = content_resolution.eligibility.eligible
        content_reason = (
            None if content_viewable else content_resolution.eligibility.code
        )
        if content_resolution.root is not None:
            content_kind = (
                "tree"
                if isinstance(content_resolution.root.content_ref, SnapshotRef)
                else "blob"
            )
        elif content_resolution.eligibility.code == "parameter_candidate_semantic_only":
            content_kind = "semantic"
        else:
            content_kind = None
        keep_supported = capability_facts.tree.eligibility.eligible
        keep_reason = None if keep_supported else capability_facts.tree.eligibility.code
    else:
        content_viewable = False
        content_reason = "selection_kind_not_content_bearing"
        content_kind = None
        keep_supported = False
        keep_reason = "workbench_selection_kind_not_mintable"
    runnable = target is not None and unavailable_reason is None and target.runnable
    debug_supported = False
    debug_reason = unavailable_reason
    if runnable:
        debug_supported, debug_reason = _candidate_debug_runtime_capability(
            state, target=target
        )
    (
        preview_supported,
        preview_reason,
        preview_profiles,
        preview_profile_diagnostics,
        preview_eligibility_detail,
    ) = (
        _candidate_preview_runtime_capability(state, target=target)
        if runnable
        else (
            _environment_preview_provider_available(state),
            unavailable_reason,
            [],
            [],
            None,
        )
    )
    result: List[JsonDict] = []
    for raw in row.get("eligibility", []):
        item = dict(raw)
        action = item.get("action")
        if action == "inspect":
            item.update(
                supported=kind == "candidate",
                eligible=kind == "candidate" and target is not None,
                reason=None if target is not None else unavailable_reason,
            )
        elif action == "debug_run":
            provider = _operator_job_provider_available(state)
            inspection_plan = (
                _public_candidate_try_plan(target=target, mode="try_once")
                if target is not None and runnable and debug_supported
                else None
            )
            item.update(
                supported=provider and kind == "candidate",
                eligible=(
                    provider and kind == "candidate" and runnable and debug_supported
                ),
                reason=(
                    None
                    if provider and runnable and debug_supported
                    else (
                        "operator_job_provider_unavailable"
                        if not provider
                        else debug_reason or unavailable_reason
                    )
                ),
                inspection_plan=inspection_plan,
            )
        elif action == "environment_preview":
            selected_profile_id = (
                _default_preview_profile_id(preview_profiles)
                if preview_profiles
                else None
            )
            item.update(
                supported=kind == "candidate" and preview_supported,
                eligible=(
                    kind == "candidate" and preview_supported and bool(preview_profiles)
                ),
                reason=(
                    None if preview_supported and preview_profiles else preview_reason
                ),
                profiles=preview_profiles,
                profile_diagnostics=preview_profile_diagnostics,
                eligibility_detail=preview_eligibility_detail,
                selected_profile_id=selected_profile_id,
                inspection_plan=(
                    _public_candidate_try_plan(
                        target=target,
                        mode="try_interactively",
                        interface_profile_id=selected_profile_id,
                    )
                    if target is not None
                    and runnable
                    and preview_supported
                    and selected_profile_id
                    else None
                ),
            )
        elif action == "open_read_only":
            provider = _selection_content_provider_available(state)
            item.update(
                supported=provider and content_viewable,
                eligible=provider and content_viewable,
                reason=(
                    None
                    if provider and content_viewable
                    else (
                        "selection_content_provider_unavailable"
                        if not provider
                        else content_reason
                    )
                ),
                content_kind=content_kind,
            )
        elif action == "keep_editable":
            provider = _editable_workspace_provider_available(state)
            workspace_link = (
                _run_selection_workspace_link(
                    state, capability_facts.selection
                )
                if provider
                and capability_facts is not None
                and isinstance(capability_facts.selection, SelectionRef)
                and kind in {"candidate", "artifact"}
                else {
                    "workspace_state": "not-created",
                    "workspace_id": None,
                    "workspace_title": None,
                }
            )
            linked = bool(workspace_link["workspace_id"])
            item.update(
                supported=provider and (keep_supported or linked),
                eligible=provider and (keep_supported or linked),
                reason=(
                    None
                    if provider and (keep_supported or linked)
                    else (
                        "editable_workspace_provider_unavailable"
                        if not provider
                        else keep_reason
                    )
                ),
                **workspace_link,
            )
        elif action == "evaluate_child_run":
            provider = _child_run_provider_available(state)
            preset = None
            child_runtime_supported = False
            child_runtime_reason: Optional[str] = None
            preparation_reason = child_run_preparation_reason
            prepared = None
            plan_exceeds_confirmation_limit = False
            if isinstance(
                child_run_preparation,
                ExactPlanChildRunSelectionPreparation,
            ):
                prepared = child_run_preparation.prepared
                if not child_run_preparation.eligibility.eligible:
                    preparation_reason = child_run_preparation.eligibility.code
            if prepared is not None:
                plan_exceeds_confirmation_limit = (
                    prepared.request.max_trials
                    > STUDIO_EXACT_PLAN_CONFIRMATION_MAX_TRIALS
                )
            if (
                provider
                and kind == "candidate"
                and target is not None
                and prepared is not None
                and not plan_exceeds_confirmation_limit
            ):
                preset = _public_exact_plan_preset(
                    prepared=prepared,
                    target=target,
                )
                if (
                    preset["logical_trials"]
                    <= STUDIO_EXACT_PLAN_CONFIRMATION_MAX_TRIALS
                ):
                    child_runtime_supported, child_runtime_reason = (
                        _candidate_child_run_runtime_capability(
                            state,
                            target=target,
                            prepared=prepared,
                        )
                    )
            if not provider:
                reason = "child_run_provider_unavailable"
            elif kind != "candidate":
                reason = "candidate_selection_required"
            elif unavailable_reason is not None:
                reason = unavailable_reason
            elif plan_exceeds_confirmation_limit:
                reason = "exact_plan_confirmation_supports_at_most_100_evaluations"
            elif preset is None:
                reason = preparation_reason or "exact_plan_preparation_unavailable"
            elif preset["logical_trials"] > STUDIO_EXACT_PLAN_CONFIRMATION_MAX_TRIALS:
                reason = "exact_plan_confirmation_supports_at_most_100_evaluations"
                preset = None
            elif not child_runtime_supported:
                reason = child_runtime_reason or "child_run_runtime_unavailable"
                preset = None
            else:
                reason = None
            item.update(
                supported=provider and kind == "candidate",
                eligible=reason is None,
                reason=reason,
                preset=preset,
            )
        elif action == "compare":
            provider = _candidate_comparison_provider_available(state)
            eligible = provider and kind == "candidate"
            if eligible:
                reason = None
            elif not provider:
                reason = "candidate_comparison_provider_unavailable"
            else:
                reason = "candidate_comparison_requires_candidate"
            item.update(
                supported=provider and kind == "candidate",
                eligible=eligible,
                reason=reason,
            )
        elif action == "ask_assistant":
            item.update(supported=True, eligible=True, reason=None)
        result.append(item)
    return result


def _candidate_debug_runtime_capability(
    state: UiState, *, target: Any
) -> tuple[bool, Optional[str]]:
    """Compile the portable plan without deriving an owner or realizing bytes."""

    if not _operator_job_provider_available(state):
        return False, "operator_job_provider_unavailable"
    runtime = _require_realm_runtime(state)
    try:
        evaluation_spec = target.compile_evaluation_spec(
            metadata={"mode": "candidate-debug-run"}
        )
        compile_retained_process_attempt_runtime(
            owner_id="operator-job-capability-probe",
            run_definition=target.run_definition,
            evaluation_spec=evaluation_spec,
            provider=runtime.process_provider,
            candidate_input=CandidateRuntimeInput.from_envelope(
                target.candidate.admission.envelope
            ),
        )
    except RuntimeBindingCompileError as error:
        return False, f"debug_run_{error.code}"
    except (TypeError, ValueError):
        return False, "debug_run_candidate_input_invalid"
    return True, None


def _candidate_child_run_runtime_capability(
    state: UiState,
    *,
    target: Any,
    prepared: ExactPlanChildRunReceipt,
) -> tuple[bool, Optional[str]]:
    """Preflight the normal evaluator binding for every exact coordinate."""

    runtime = _require_realm_runtime(state)
    try:
        candidate_input = CandidateRuntimeInput.from_envelope(
            target.candidate.admission.envelope
        )
        for coordinate in prepared.request.evaluation_plan.coordinates:
            values = coordinate.to_dict()
            evaluation_spec = target.compile_evaluation_spec(
                seed=values["seed"],
                repetition_index=coordinate.repetition_index,
                metadata={"mode": "exact-plan-child-run"},
            )
            compile_retained_process_attempt_runtime(
                owner_id="child-run-capability-probe",
                run_definition=target.run_definition,
                evaluation_spec=evaluation_spec,
                provider=runtime.process_provider,
                candidate_input=candidate_input,
            )
    except RuntimeBindingCompileError as error:
        return False, f"child_run_{error.code}"
    except (TypeError, ValueError):
        return False, "child_run_candidate_input_invalid"
    return True, None


def _candidate_preview_runtime_capability(
    state: UiState, *, target: Any
) -> tuple[
    bool,
    Optional[str],
    List[JsonDict],
    List[JsonDict],
    Optional[JsonDict],
]:
    """Compile each retained profile and apply the exact provider preflight."""

    if not _environment_preview_provider_available(state):
        return (
            False,
            "environment_preview_provider_unavailable",
            [],
            [],
            {
                "category": "provider_unavailable",
                "code": "environment_preview_provider_unavailable",
            },
        )
    runtime = _require_realm_runtime(state)
    binder = runtime.environment_preview_binder
    trust_context: JsonDict = {}
    trust_source = getattr(runtime, "container_gateway_trust_source", None)
    if trust_source in {"realm", "session"}:
        trust_context["trust_source"] = trust_source
    trust_generation = getattr(
        runtime, "container_gateway_trust_generation", None
    )
    if isinstance(trust_generation, str) and 0 < len(trust_generation) <= 256:
        trust_context["trust_generation"] = trust_generation
    diagnostics: List[JsonDict] = []
    retained_profiles = (
        target.evaluation.closure.environment_revision.interface_profiles
    )
    for profile in retained_profiles:
        presentation = {
            "kind": profile.presentation.kind,
            "port": profile.presentation.port,
            "extra_ports": list(profile.presentation.extra_ports),
        }
        if profile.runtime.sandbox == "process":
            diagnostics.append(
                {
                    "id": profile.profile_id,
                    "label": profile.label,
                    "applicable": False,
                    "eligible": False,
                    "reason": "environment_preview_profile_incompatible",
                    "eligibility_detail": {
                        "category": "not_applicable",
                        "code": "profile_process_runtime_not_applicable",
                        **trust_context,
                    },
                    "presentation": presentation,
                }
            )
            continue
        reason: Optional[str] = None
        detail: JsonDict = {
            "category": "ready",
            "code": "ready",
            **trust_context,
        }
        remediation: Optional[JsonDict] = None
        try:
            plan = compile_environment_preview_plan(
                target, profile_id=profile.profile_id
            )
        except EnvironmentPreviewCompileError as error:
            reason = "environment_preview_profile_incompatible"
            detail = {
                "category": "unsupported_contract",
                "code": error.code,
                **trust_context,
            }
        except RealmConflict:
            reason = "environment_preview_profile_incompatible"
            detail = {
                "category": "unsupported_contract",
                "code": "profile_compile_conflict",
                **trust_context,
            }
        except (TypeError, ValueError):
            reason = "environment_preview_profile_incompatible"
            detail = {
                "category": "unsupported_contract",
                "code": "profile_compile_invalid",
                **trust_context,
            }
        if reason is None:
            try:
                binder.validate_plan(plan)
            except EnvironmentPreviewProviderPlanError as error:
                if error.code == "container_gateway_image_untrusted":
                    reason = "environment_preview_image_untrusted"
                    detail = {
                        "category": "authorization_required",
                        "code": error.code,
                        **trust_context,
                    }
                    remediation = {
                        "kind": "approve_container_gateway_image",
                        "image_ref": plan.runtime.image_ref,
                    }
                elif error.code == "container_image_unavailable":
                    reason = "environment_preview_image_unavailable"
                    detail = {
                        "category": "installation_required",
                        "code": error.code,
                        **trust_context,
                    }
                    remediation = {
                        "kind": "pull_container_image",
                        "image_ref": plan.runtime.image_ref,
                    }
                else:
                    reason = "environment_preview_profile_incompatible"
                    detail = {
                        "category": "provider_incompatible",
                        "code": error.code,
                        **trust_context,
                    }
            except RealmConflict:
                reason = "environment_preview_profile_incompatible"
                detail = {
                    "category": "provider_incompatible",
                    "code": "provider_plan_conflict",
                    **trust_context,
                }
            except (TypeError, ValueError):
                reason = "environment_preview_profile_incompatible"
                detail = {
                    "category": "provider_incompatible",
                    "code": "provider_plan_invalid",
                    **trust_context,
                }
        diagnostic: JsonDict = {
            "id": profile.profile_id,
            "label": profile.label,
            "applicable": True,
            "eligible": reason is None,
            "reason": reason,
            "eligibility_detail": detail,
            "presentation": presentation,
        }
        if remediation is not None:
            diagnostic["remediation"] = remediation
        diagnostics.append(diagnostic)
    eligible = [profile for profile in diagnostics if profile["eligible"]]
    if eligible:
        selected_profile_id = _default_preview_profile_id(eligible)
        return (
            True,
            None,
            eligible,
            diagnostics,
            {
                "category": "ready",
                "code": "ready",
                "profile_id": selected_profile_id,
                **trust_context,
            },
        )
    if not diagnostics:
        return (
            True,
            "environment_preview_profile_unavailable",
            [],
            [],
            {
                "category": "unavailable",
                "code": "profile_unavailable",
                **trust_context,
            },
        )
    applicable_blockers = [item for item in diagnostics if item["applicable"]]
    chosen = next(
        (
            item
            for item in applicable_blockers
            if item["reason"]
            in {
                "environment_preview_image_untrusted",
                "environment_preview_image_unavailable",
            }
        ),
        applicable_blockers[0] if applicable_blockers else diagnostics[0],
    )
    aggregate_detail = {
        **dict(chosen["eligibility_detail"]),
        "profile_id": chosen["id"],
    }
    if chosen.get("remediation") is not None:
        aggregate_detail["remediation"] = deepcopy(chosen["remediation"])
    return True, str(chosen["reason"]), [], diagnostics, aggregate_detail


def _default_preview_profile_id(profiles: Iterable[Mapping[str, Any]]) -> str:
    values = [dict(item) for item in profiles]
    for item in values:
        if item.get("id") == "default":
            return "default"
    return str(values[0]["id"]) if values else ""


def _enrich_workbench_head(state: UiState, payload: JsonDict) -> JsonDict:
    result = deepcopy(payload)
    capabilities = result.get("capabilities")
    if isinstance(capabilities, dict):
        actions = capabilities.get("actions")
        if isinstance(actions, list):
            capabilities["actions"] = _global_workbench_action_capabilities(
                state, actions
            )
    return result


def _workbench_capability_selections(
    pages: Iterable[Mapping[str, Any]],
) -> List[Mapping[str, Any]]:
    """Collect the bounded content-bearing selections from exact-head pages."""

    selections: List[Mapping[str, Any]] = []
    for page in pages:
        items = page.get("items")
        if not isinstance(items, list):
            raise ValueError("Workbench page items are invalid.")
        for row in items:
            if not isinstance(row, Mapping):
                raise ValueError("Workbench page row is invalid.")
            selection = row.get("selection")
            if not isinstance(selection, Mapping):
                raise ValueError("Workbench row is missing its presentation selection.")
            if selection.get("kind") in {"candidate", "artifact"}:
                selections.append(selection)
    return selections


def _enrich_workbench_page(
    state: UiState,
    payload: JsonDict,
    *,
    capability_facts: Optional[Mapping[str, Any]] = None,
    child_run_preparations: Optional[
        Mapping[str, ExactPlanChildRunSelectionPreparation]
    ] = None,
    child_run_preparation_reason: Optional[str] = None,
) -> JsonDict:
    result = deepcopy(payload)
    capabilities = result.get("capabilities")
    if isinstance(capabilities, dict):
        actions = capabilities.get("actions")
        if isinstance(actions, list):
            capabilities["actions"] = _global_workbench_action_capabilities(
                state, actions
            )
    run_id = str(result.get("run_id") or "")
    items = result.get("items")
    if not isinstance(items, list):
        raise ValueError("Workbench page items are invalid.")
    if capability_facts is None:
        selections = _workbench_capability_selections((result,))
        capability_facts = (
            _require_realm_runtime(state).run_views.workbench_capability_batch(
                ref=RunViewRef(run_id=run_id),
                presentation_selections=selections,
            )
            if selections
            else {}
        )
    if child_run_preparations is None:
        child_run_preparations, child_run_preparation_reason = (
            _child_run_preparation_batch(
                state,
                capability_facts=capability_facts.values(),
            )
        )
    for row in items:
        if not isinstance(row, dict):
            raise ValueError("Workbench page row is invalid.")
        selection = row.get("selection")
        if not isinstance(selection, Mapping):
            raise ValueError("Workbench row is missing its presentation selection.")
        facts = capability_facts.get(selection.get("selection_id"))
        prepared = (
            child_run_preparations.get(facts.selection.selection_digest)
            if facts is not None
            else None
        )
        if (
            selection.get("kind") == "candidate"
            and facts is not None
            and facts.candidate_target is not None
        ):
            environment = (
                facts.candidate_target.evaluation.closure.environment_revision
            )
            row["context"] = {
                "environment": {
                    "id": environment.environment_id,
                    "revision": environment.digest,
                }
            }
        row["eligibility"] = _row_workbench_action_capabilities(
            state,
            run_id=run_id,
            row=row,
            capability_facts=facts,
            child_run_preparation=prepared,
            child_run_preparation_reason=child_run_preparation_reason,
        )
    return result


def _realm_workbench_page(
    state: UiState,
    *,
    ref: RunViewRef,
    kind: str,
    page_token: Optional[str] = None,
    limit: int = RUN_WORKBENCH_DEFAULT_PAGE_SIZE,
) -> JsonDict:
    runtime = _require_realm_runtime(state)
    return _enrich_workbench_page(
        state,
        runtime.run_views.workbench_page(
            ref=ref,
            kind=kind,
            page_token=page_token,
            limit=limit,
        ),
    )


def _exact_json_object(
    payload: Any, *, expected: set[str], label: str
) -> Mapping[str, Any]:
    if not isinstance(payload, Mapping):
        raise ValueError(f"{label} must be a JSON object.")
    actual = set(payload)
    if actual != expected:
        raise ValueError(
            f"{label} fields differ; missing={sorted(expected - actual)!r}, "
            f"extra={sorted(actual - expected)!r}."
        )
    return payload


def _canonical_request_uuid(value: Any, *, label: str = "request_id") -> str:
    if not isinstance(value, str) or len(value) != 36:
        raise ValueError(f"{label} must be a canonical UUID string.")
    try:
        parsed = uuid.UUID(value)
    except (AttributeError, ValueError) as error:
        raise ValueError(f"{label} must be a canonical UUID string.") from error
    if str(parsed) != value:
        raise ValueError(f"{label} must be a canonical UUID string.")
    return value


def _workspace_create_operation_id(scope: str, request_id: Any) -> str:
    """Derive one Core creation coordinate from a client-owned request id."""

    if scope not in {
        "catalog",
        "operator-job-output",
        "study-builder",
    }:
        raise ValueError("Workspace creation scope is unsupported.")
    canonical = _canonical_request_uuid(request_id)
    return f"studio/workspace-create/{scope}/{canonical}"


def _assistant_workspace_request_id(
    *, session_id: str, tool: str, tool_call_id: Any
) -> str:
    """Derive a canonical workspace request id from one Assistant invocation.

    OpenHands owns and replays ``tool_call_id``.  Hashing that stable client
    coordinate gives Assistant tools the same retry boundary as a browser-
    minted UUID without persisting an OpenHands/provider identifier in Core.
    """

    session_id = str(session_id).strip()
    tool = str(tool).strip()
    if not session_id or len(session_id.encode("utf-8")) > 512:
        raise ValueError("Assistant session id is invalid.")
    if not tool or len(tool.encode("utf-8")) > 128:
        raise ValueError("Assistant tool name is invalid.")
    if not isinstance(tool_call_id, str):
        raise ValueError(
            "Assistant workspace creation requires a stable tool-call id or "
            "an explicit request_id."
        )
    tool_call_id = tool_call_id.strip()
    if not tool_call_id or len(tool_call_id.encode("utf-8")) > 512:
        raise ValueError(
            "Assistant workspace creation requires a stable tool-call id or "
            "an explicit request_id."
        )
    coordinate = json.dumps(
        {
            "schema": "optpilot.assistant-workspace-request-coordinate.v1",
            "session_id": session_id,
            "tool": tool,
            "tool_call_id": tool_call_id,
        },
        sort_keys=True,
        separators=(",", ":"),
    )
    return str(uuid.uuid5(uuid.NAMESPACE_URL, coordinate))


_PRIVATE_PRESENTATION_KEYS = frozenset(
    {
        "absolute_path",
        "binding",
        "binding_id",
        "command",
        "content_ref",
        "credential",
        "cwd",
        "host_path",
        "launch_token",
        "lease",
        "owner",
        "owner_id",
        "path",
        "port",
        "principal",
        "provider",
        "secret",
        "token",
        "workspace_path",
    }
)


def _contains_private_presentation_material(value: Any, *, depth: int = 0) -> bool:
    if depth > 24:
        return True
    if isinstance(value, str):
        lowered = value.casefold()
        return (
            value.startswith(("/", "~/", "~\\"))
            or re.match(r"^[A-Za-z]:[\\/]", value) is not None
            or lowered.startswith("file://")
        )
    if isinstance(value, Mapping):
        for key, child in value.items():
            normalized = str(key).casefold().replace("-", "_")
            if normalized in _PRIVATE_PRESENTATION_KEYS or normalized.endswith(
                ("_path", "_port", "_secret", "_token")
            ):
                return True
            if _contains_private_presentation_material(child, depth=depth + 1):
                return True
        return False
    if isinstance(value, (list, tuple)):
        return any(
            _contains_private_presentation_material(child, depth=depth + 1)
            for child in value
        )
    return False


def _bounded_candidate_spec(target: Any) -> tuple[Any, bool]:
    envelope = target.candidate.admission.envelope
    if envelope.candidate_format != "parameters":
        return None, False
    spec = envelope.to_dict()["spec"]
    if _contains_private_presentation_material(spec):
        return None, False
    encoded = json.dumps(
        spec,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")
    if len(encoded) > 64 * 1024:
        return None, False
    return spec, True


def _candidate_inspection_payload(target: Any) -> JsonDict:
    envelope = target.candidate.admission.envelope
    closure = target.evaluation.closure
    environment = closure.environment_revision
    runtime = closure.prepared_runtime
    template = closure.evaluation_template
    objective = dict(template.objective)
    primary = objective.get("primaryMetric")
    if not isinstance(primary, Mapping):
        primary = {}
    spec, spec_included = _bounded_candidate_spec(target)
    return {
        "schema": CANDIDATE_INSPECTION_SCHEMA,
        "candidate": {
            "candidate_id": target.candidate.candidate_id,
            "format": envelope.candidate_format,
            "spec": spec,
            "spec_included": spec_included,
            "content_count": len(envelope.content_refs),
        },
        "environment": {
            "environment_id": environment.environment_id,
            "runtime_kind": runtime.runtime_kind,
            "portability": runtime.portability,
            "availability": target.evaluation.availability,
        },
        "evaluation": {
            "runnable": target.runnable,
            "objective_metric": primary.get("name"),
            "objective_direction": primary.get("direction"),
            "default_seed": template.default_seed,
        },
        "realization": {
            "workspace_created": False,
            "content_copied": False,
            "process_started": False,
        },
    }


def _compare_run_candidates(
    state: UiState,
    *,
    run_id: str,
    payload: Any,
) -> JsonDict:
    """Return Core's exact-head candidate comparison projection verbatim."""

    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "baseline_selection",
            "comparison_selection",
            "text_diff_path",
        },
        label="run candidate comparison request",
    )
    if request["schema"] != RUN_CANDIDATE_COMPARISON_REQUEST_SCHEMA:
        raise ValueError("Run candidate comparison request schema is unsupported.")
    baseline = request["baseline_selection"]
    comparison = request["comparison_selection"]
    if not isinstance(baseline, Mapping):
        raise ValueError("baseline_selection must be a JSON object.")
    if not isinstance(comparison, Mapping):
        raise ValueError("comparison_selection must be a JSON object.")
    text_diff_path = request["text_diff_path"]
    if text_diff_path is not None and (
        not isinstance(text_diff_path, str)
        or not text_diff_path
        or text_diff_path != text_diff_path.strip()
        or len(text_diff_path.encode("utf-8")) > 4096
        or text_diff_path.startswith(("/", "\\"))
        or "\\" in text_diff_path
        or any(part in {"", ".", ".."} for part in text_diff_path.split("/"))
    ):
        raise ValueError("text_diff_path must be a canonical relative path or null.")
    ref = RunViewRef(run_id=run_id)
    projection = _require_realm_runtime(state).run_views.compare_candidates(
        ref=ref,
        baseline_presentation_selection=baseline,
        comparison_presentation_selection=comparison,
        text_diff_path=text_diff_path,
    )
    return projection.to_dict()


def _shortlist_draft_from_request(value: Any) -> ShortlistDraft:
    draft = _exact_json_object(
        value,
        expected={"shortlist_id", "expected_revision", "title", "cards"},
        label="Shortlist draft",
    )
    cards = draft["cards"]
    if not isinstance(cards, list):
        raise ValueError("Shortlist cards must be a list.")
    return ShortlistDraft(
        shortlist_id=draft["shortlist_id"],
        expected_revision=draft["expected_revision"],
        title=draft["title"],
        cards=tuple(
            ShortlistCardDraft(
                **_exact_json_object(
                    item,
                    expected={
                        "selection_digest",
                        "note",
                        "inspection_outcomes",
                    },
                    label="Shortlist card draft",
                )
            )
            for item in cards
        ),
    )


def _public_shortlist_history(history: Any) -> Optional[JsonDict]:
    """Return only the bounded revision navigator needed by the UI."""

    if history is None:
        return None
    payload = history.to_dict()
    return {
        "schema": payload["schema"],
        "collection_id": payload["collection_id"],
        "current_revision": payload["current_revision"],
        "items": [
            {
                "revision": item["revision"],
                "revision_digest": item["revision_digest"],
                "title": item["title"],
                "item_count": item["item_count"],
                "created_at": item["created_at"],
            }
            for item in payload["items"]
        ],
        "page": payload["page"],
    }


def _execute_shortlist_command(
    state: UiState,
    *,
    run_id: str,
    payload: Any,
) -> tuple[JsonDict, HTTPStatus]:
    """Commit one complete Run-local Shortlist draft atomically."""

    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "request_id",
            "command",
            "presentation_selection",
            "draft",
            "parameters",
        },
        label="Shortlist command",
    )
    if request["schema"] != SHORTLIST_COMMAND_SCHEMA:
        raise ValueError("Shortlist command schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    command = request["command"]
    if command not in {"save_candidate", "save_changes", "attach_inspection"}:
        raise ValueError("Shortlist command is unsupported.")
    canonical_run_id = RunViewRef(run_id=run_id).run_id
    draft = _shortlist_draft_from_request(request["draft"])
    parameters = _exact_json_object(
        request["parameters"],
        expected={
            "candidate_id",
            "note",
            "operator_job_id",
            "update_saved_result",
        },
        label="Shortlist command parameters",
    )
    operation_id = f"studio/shortlist/{canonical_run_id}/{request_id}/{command}"
    service = _require_realm_runtime(state).shortlists
    if command == "save_candidate":
        selection = request["presentation_selection"]
        if not isinstance(selection, Mapping):
            raise ValueError("Save to Shortlist requires a presentation selection.")
        if parameters["candidate_id"] not in (None, ""):
            raise ValueError("Save to Shortlist derives the Candidate from its selection.")
        operator_job_id = parameters["operator_job_id"]
        if operator_job_id is not None:
            operator_job_id = _required_operator_job_id(operator_job_id)
        shortlist = service.save_candidate(
            operation_id=operation_id,
            run_id=canonical_run_id,
            presentation_selection=selection,
            draft=draft,
            note=parameters["note"],
            operator_job_id=operator_job_id,
            update_saved_result=parameters["update_saved_result"],
        )
    elif command == "save_changes":
        if request["presentation_selection"] is not None:
            raise ValueError("Saving Shortlist changes does not accept a selection.")
        if any(
            parameters[key] not in (None, "", False)
            for key in (
                "candidate_id",
                "note",
                "operator_job_id",
                "update_saved_result",
            )
        ):
            raise ValueError("Saving Shortlist changes does not accept action parameters.")
        shortlist = service.save_changes(
            operation_id=operation_id,
            run_id=canonical_run_id,
            draft=draft,
        )
    else:
        if request["presentation_selection"] is not None:
            raise ValueError("Attaching an inspection does not accept a selection.")
        if parameters["note"] not in (None, "") or parameters[
            "update_saved_result"
        ] is not False:
            raise ValueError("Attaching an inspection received unrelated parameters.")
        shortlist = service.attach_inspection(
            operation_id=operation_id,
            run_id=canonical_run_id,
            candidate_id=parameters["candidate_id"],
            operator_job_id=_required_operator_job_id(parameters["operator_job_id"]),
            draft=draft,
        )
    runtime = _require_realm_runtime(state)
    return (
        {
            "schema": SHORTLIST_RESPONSE_SCHEMA,
            "run_id": canonical_run_id,
            "shortlist": shortlist.to_dict(),
            "history": _public_shortlist_history(
                runtime.review_collections.history_for_run(
                    run_id=canonical_run_id
                )
            ),
        },
        HTTPStatus.CREATED,
    )


def _execute_review_collection_command(
    state: UiState,
    *,
    run_id: str,
    payload: Any,
) -> tuple[JsonDict, HTTPStatus]:
    """Commit one immutable Review Collection revision from a bounded command."""

    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "request_id",
            "command",
            "presentation_selection",
            "draft",
        },
        label="Review Collection command",
    )
    if request["schema"] != REVIEW_COLLECTION_COMMAND_SCHEMA:
        raise ValueError("Review Collection command schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    command = request["command"]
    if command not in {"add", "save", "attach_inspection", "delete"}:
        raise ValueError("Review Collection command is unsupported.")
    canonical_run_id = RunViewRef(run_id=run_id).run_id
    runtime = _require_realm_runtime(state)
    operation_id = (
        f"studio/review-collection/{canonical_run_id}/{request_id}/{command}"
    )
    if command == "add":
        selection = request["presentation_selection"]
        if not isinstance(selection, Mapping):
            raise ValueError("Add to Review requires a presentation selection.")
        draft = _exact_json_object(
            request["draft"],
            expected={"note", "inspection_outcomes", "operator_job_id"},
            label="Add to Review draft",
        )
        note = draft["note"]
        if not isinstance(note, str):
            raise ValueError("Review note must be text.")
        inspection_outcomes = draft["inspection_outcomes"]
        if not isinstance(inspection_outcomes, list) or any(
            not isinstance(item, Mapping) for item in inspection_outcomes
        ):
            raise ValueError("Review inspection outcomes must be a list of objects.")
        operator_job_id = draft["operator_job_id"]
        if operator_job_id is not None:
            operator_job_id = _required_operator_job_id(operator_job_id)
        collection = runtime.review_collections.add_candidate(
            operation_id=operation_id,
            run_id=canonical_run_id,
            presentation_selection=selection,
            note=note,
            inspection_outcomes=tuple(inspection_outcomes),
            operator_job_id=operator_job_id,
        )
    elif command == "save":
        if request["presentation_selection"] is not None:
            raise ValueError("Saving a Review Collection does not accept a selection.")
        draft = _exact_json_object(
            request["draft"],
            expected={
                "collection_id",
                "expected_revision",
                "title",
                "items",
            },
            label="Review Collection revision draft",
        )
        collection_id = draft["collection_id"]
        title = draft["title"]
        expected_revision = draft["expected_revision"]
        items = draft["items"]
        if not isinstance(collection_id, str) or not collection_id:
            raise ValueError("Review Collection id must be nonempty text.")
        if not isinstance(title, str):
            raise ValueError("Review Collection title must be text.")
        if (
            isinstance(expected_revision, bool)
            or not isinstance(expected_revision, int)
            or expected_revision <= 0
        ):
            raise ValueError("Expected Review Collection revision must be positive.")
        if not isinstance(items, list):
            raise ValueError("Review Collection items must be a list.")
        entries = tuple(
            ReviewCollectionEntryDraft.from_dict(
                _exact_json_object(
                    item,
                    expected={
                        "selection_digest",
                        "note",
                        "inspection_outcomes",
                    },
                    label="Review Collection item draft",
                )
            )
            for item in items
        )
        collection = runtime.review_collections.save_revision(
            operation_id=operation_id,
            run_id=canonical_run_id,
            collection_id=collection_id,
            expected_revision=expected_revision,
            title=title,
            entries=entries,
        )
    elif command == "attach_inspection":
        if request["presentation_selection"] is not None:
            raise ValueError(
                "Attaching Review evidence does not accept a presentation selection."
            )
        draft = _exact_json_object(
            request["draft"],
            expected={
                "collection_id",
                "expected_revision",
                "title",
                "items",
                "selection_digest",
                "operator_job_id",
            },
            label="Review inspection attachment draft",
        )
        collection_id = draft["collection_id"]
        title = draft["title"]
        expected_revision = draft["expected_revision"]
        selection_digest = draft["selection_digest"]
        items = draft["items"]
        if not isinstance(collection_id, str) or not collection_id:
            raise ValueError("Review Collection id must be nonempty text.")
        if not isinstance(title, str):
            raise ValueError("Review Collection title must be text.")
        if (
            isinstance(expected_revision, bool)
            or not isinstance(expected_revision, int)
            or expected_revision <= 0
        ):
            raise ValueError("Expected Review Collection revision must be positive.")
        if not isinstance(selection_digest, str):
            raise ValueError("Review selection digest must be text.")
        if not isinstance(items, list):
            raise ValueError("Review Collection items must be a list.")
        entries = tuple(
            ReviewCollectionEntryDraft.from_dict(
                _exact_json_object(
                    item,
                    expected={
                        "selection_digest",
                        "note",
                        "inspection_outcomes",
                    },
                    label="Review Collection item draft",
                )
            )
            for item in items
        )
        collection = runtime.review_collections.attach_operator_job(
            operation_id=operation_id,
            run_id=canonical_run_id,
            collection_id=collection_id,
            expected_revision=expected_revision,
            title=title,
            entries=entries,
            selection_digest=selection_digest,
            operator_job_id=_required_operator_job_id(draft["operator_job_id"]),
        )
    else:
        if request["presentation_selection"] is not None:
            raise ValueError(
                "Deleting a Review Collection does not accept a selection."
            )
        draft = _exact_json_object(
            request["draft"],
            expected={
                "collection_id",
                "expected_revision",
                "expected_revision_digest",
                "confirmation",
            },
            label="Review Collection deletion request",
        )
        collection_id = draft["collection_id"]
        expected_revision = draft["expected_revision"]
        expected_revision_digest = draft["expected_revision_digest"]
        if not isinstance(collection_id, str) or not collection_id:
            raise ValueError("Review Collection id must be nonempty text.")
        if (
            isinstance(expected_revision, bool)
            or not isinstance(expected_revision, int)
            or expected_revision <= 0
        ):
            raise ValueError("Expected Review Collection revision must be positive.")
        if not isinstance(expected_revision_digest, str):
            raise ValueError("Expected Review Collection digest must be text.")
        if draft["confirmation"] != "delete_review_collection":
            raise ValueError("Review Collection deletion requires confirmation.")
        deletion = runtime.review_collections.delete_for_run(
            operation_id=operation_id,
            run_id=canonical_run_id,
            collection_id=collection_id,
            expected_revision=expected_revision,
            expected_revision_digest=expected_revision_digest,
        )
        return (
            {
                "schema": REVIEW_COLLECTION_RESPONSE_SCHEMA,
                "run_id": canonical_run_id,
                "collection": None,
                "history": None,
                "deletion": deletion.to_dict(),
            },
            HTTPStatus.OK,
        )
    return (
        {
            "schema": REVIEW_COLLECTION_RESPONSE_SCHEMA,
            "run_id": canonical_run_id,
            # The legacy command remains during migration, but its HTTP
            # boundary now returns the same redacted decision projection as
            # Shortlist rather than the authority-bearing persistence row.
            "collection": collection.export_dict(),
            "history": _public_shortlist_history(
                runtime.review_collections.history_for_run(
                    run_id=canonical_run_id
                )
            ),
        },
        HTTPStatus.CREATED,
    )


def _run_selection_workspace_action_request(
    state: UiState, selection: SelectionRef
) -> tuple[str, EntityCoordinate, JsonDict]:
    """Return one stable Workspace intent for an immutable Run selection.

    Workbench presentation coordinates change when the Run head advances, and
    browser request UUIDs change across refreshes. Neither is the identity of
    the user's intent to edit one retained Candidate project. The immutable Run
    entity, accepted sequence, retained content reference, and evaluation
    context are.
    """

    if not isinstance(selection, SelectionRef):
        raise TypeError("Run Workspace selection must be a SelectionRef.")
    if selection.source_kind != "run" or selection.kind not in {
        "candidate",
        "artifact",
    }:
        raise RealmConflict(
            "Edit in Workspace requires a retained Run Candidate or project folder."
        )
    anchor = {
        "context_digest": selection.context_digest,
        "entity_id": selection.entity_id,
        "entity_ref": selection.entity_ref,
        "entity_sequence": selection.entity_sequence,
        "kind": selection.kind,
        "relative_path": selection.relative_path,
        "run_id": selection.source_id,
        "schema": "optpilot.run-selection-workspace-anchor.v1",
    }
    anchor_digest = request_digest(anchor)
    source = EntityCoordinate(
        kind=selection.kind,
        entity_id=selection.entity_id,
        revision=selection.entity_sequence,
        digest=anchor_digest,
    )
    stable_parameters: JsonDict = {
        "anchor_digest": anchor_digest,
        "entity_id": selection.entity_id,
        "kind": selection.kind,
        "run_id": selection.source_id,
    }
    parameters: JsonDict = {
        **stable_parameters,
        # Retain the first exact authority coordinate so recovery replays the
        # same Core request even if the Run presentation head later advances.
        "selection": selection.to_dict(),
    }
    intent_id = "run-selection-workspace-" + request_digest(
        {
            "actor_id": _studio_actor_id(state),
            "parameters": stable_parameters,
            "schema": "optpilot.run-selection-workspace-intent.v1",
            "source": source.to_dict(),
        }
    )
    return intent_id, source, parameters


def _run_selection_workspace_action(
    state: UiState, selection: SelectionRef
) -> Optional[ActionIntentRecord]:
    intent_id, source, parameters = _run_selection_workspace_action_request(
        state, selection
    )
    try:
        action = state.coordination.get_action(intent_id)
    except CoordinationNotFound:
        return None
    raw_stored_selection = action.parameters.get("selection")
    if not isinstance(raw_stored_selection, Mapping):
        raise RealmIntegrityError(
            "The Candidate Workspace action lost its retained selection."
        )
    try:
        stored_selection = SelectionRef.from_dict(raw_stored_selection)
    except (TypeError, ValueError) as error:
        raise RealmIntegrityError(
            "The Candidate Workspace action selection is invalid."
        ) from error
    stored_intent_id, stored_source, stored_parameters = (
        _run_selection_workspace_action_request(state, stored_selection)
    )
    if (
        stored_intent_id != intent_id
        or stored_source != source
        or action.source != source
        or dict(action.parameters) != stored_parameters
    ):
        raise RealmIntegrityError(
            "The Candidate Workspace action does not match its retained source."
        )
    expected_digest = ActionIntentRecord.compute_intent_digest(
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="workspace-creation",
        source=stored_source,
        parameters=stored_parameters,
    )
    if action.intent_digest != expected_digest:
        raise RealmIntegrityError(
            "The Candidate Workspace action does not match its retained source."
        )
    return action


def _begin_run_selection_workspace_action(
    state: UiState, selection: SelectionRef
) -> ActionIntentRecord:
    intent_id, source, parameters = _run_selection_workspace_action_request(
        state, selection
    )
    current = _run_selection_workspace_action(state, selection)
    if current is not None:
        if current.state in {ActionState.UNCERTAIN, ActionState.FAILED}:
            return state.coordination.retry_action(
                operation_id=f"studio/action/{intent_id}/retry/{current.revision}",
                intent_id=intent_id,
            )
        return current
    return state.coordination.begin_action(
        operation_id=f"studio/action/{intent_id}/begin",
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="workspace-creation",
        source=source,
        parameters=parameters,
    )


def _run_selection_workspace_link(
    state: UiState, selection: SelectionRef
) -> JsonDict:
    action = _run_selection_workspace_action(state, selection)
    if action is None:
        return {
            "workspace_state": "not-created",
            "workspace_id": None,
            "workspace_title": None,
        }
    if action.state is ActionState.SUCCEEDED:
        result = action.result
        receipt = action.core_receipt
        if (
            result is None
            or result.kind != "workspace"
            or not isinstance(receipt, Mapping)
            or not isinstance(receipt.get("keep"), Mapping)
        ):
            raise RealmIntegrityError(
                "The Candidate Workspace receipt is incomplete."
            )
        title = receipt.get("workspace_title")
        return {
            "workspace_state": "created",
            "workspace_id": result.entity_id,
            "workspace_title": title if isinstance(title, str) else None,
        }
    return {
        "workspace_state": (
            "creating" if action.state is ActionState.PENDING else "retryable"
        ),
        "workspace_id": None,
        "workspace_title": None,
    }


def _replay_run_selection_workspace_action(
    state: UiState, action: ActionIntentRecord
) -> Optional[JsonDict]:
    if action.state is not ActionState.SUCCEEDED:
        return None
    result = action.result
    receipt = action.core_receipt
    if (
        result is None
        or result.kind != "workspace"
        or not isinstance(receipt, Mapping)
        or not isinstance(receipt.get("keep"), Mapping)
    ):
        raise RealmIntegrityError("The Candidate Workspace receipt is incomplete.")
    workspace = _workspace_by_id(state, result.entity_id)
    if workspace is None or workspace.get("reopen_required"):
        workspace = _reopen_managed_workspace(state, result.entity_id, {})
    return {
        "workspace": workspace,
        "keep": dict(receipt["keep"]),
    }


def _complete_run_selection_workspace_action(
    state: UiState,
    *,
    action: ActionIntentRecord,
    created: Mapping[str, Any],
) -> ActionIntentRecord:
    workspace = created.get("workspace")
    keep = created.get("keep")
    if not isinstance(workspace, Mapping) or not isinstance(keep, Mapping):
        raise RealmIntegrityError(
            "Candidate Workspace creation did not return a durable receipt."
        )
    workspace_id = str(keep.get("workspace_id") or "")
    revision = keep.get("workspace_revision")
    digest = keep.get("source_digest")
    if (
        not workspace_id
        or workspace_id != str(workspace.get("id") or "")
        or isinstance(revision, bool)
        or not isinstance(revision, int)
        or revision <= 0
        or not isinstance(digest, str)
    ):
        raise RealmIntegrityError(
            "Candidate Workspace creation returned an invalid receipt."
        )
    return state.coordination.complete_action(
        operation_id=f"studio/action/{action.intent_id}/complete",
        intent_id=action.intent_id,
        result=EntityCoordinate(
            kind="workspace",
            entity_id=workspace_id,
            revision=revision,
            digest=digest,
        ),
        core_receipt={
            "keep": dict(keep),
            "workspace_title": str(workspace.get("title") or "Workspace"),
        },
    )


def _mark_run_selection_workspace_action_uncertain(
    state: UiState, action: ActionIntentRecord, error: BaseException
) -> None:
    try:
        current = state.coordination.get_action(action.intent_id)
        state.coordination.mark_action_uncertain(
            operation_id=(
                f"studio/action/{action.intent_id}/uncertain/{current.revision}"
            ),
            intent_id=action.intent_id,
            message=(
                "Candidate Workspace creation did not return a confirmed receipt; "
                "retry will reconcile the same Workspace."
            ),
        )
    except Exception:
        _ = error


def _durable_run_action_intent(
    state: UiState,
    *,
    request_id: str,
    run_id: str,
    action: str,
    presentation_selection: Mapping[str, Any],
    parameters: Mapping[str, Any],
) -> Any:
    if action != "evaluate_child_run":
        raise ValueError("Durable Run action intent is unsupported.")
    # Each explicitly confirmed re-evaluation is a new Run intent. The browser
    # UUID distinguishes those user confirmations while the exact presentation
    # coordinate keeps each retry fenced to the confirmed Run head.
    presented = validate_run_workbench_selection(presentation_selection)
    if presented["run_id"] != run_id:
        raise ValueError("Durable action selection belongs to another Run.")
    entity_id = presented["entity_id"]
    kind = presented["kind"]
    revision = presented["revision"]
    selection_id = presented["selection_id"]
    digest = selection_id.removeprefix("sha256:")
    source = EntityCoordinate(
        kind=kind,
        entity_id=entity_id,
        revision=revision,
        digest=digest,
    )
    action_kind = "exact-reevaluation"
    intent_parameters = {
        "action": action,
        "parameters": dict(parameters),
        "run_id": run_id,
        "selection_digest": digest,
        "head_sequence": presented["sequence"],
    }
    expected_digest = ActionIntentRecord.compute_intent_digest(
        intent_id=request_id,
        actor_id=_studio_actor_id(state),
        action_kind=action_kind,
        source=source,
        parameters=intent_parameters,
    )
    try:
        current = state.coordination.get_action(request_id)
    except CoordinationNotFound:
        current = None
    if current is not None:
        if current.intent_digest != expected_digest:
            raise CoordinationConflict(
                "Action intent id was already used for another request."
            )
        if current.state is ActionState.FAILED:
            raise RealmConflict(
                current.error_message or "The previous action attempt failed."
            )
        if current.state is ActionState.UNCERTAIN:
            return state.coordination.retry_action(
                operation_id=f"studio/action/{request_id}/retry/{current.revision}",
                intent_id=request_id,
            )
        return current
    core_operation_id = f"studio/run-action/{run_id}/{request_id}/{action}"
    return state.coordination.begin_action(
        operation_id=f"studio/action/{request_id}/begin",
        intent_id=request_id,
        actor_id=_studio_actor_id(state),
        action_kind=action_kind,
        source=source,
        parameters=intent_parameters,
        core_operation_id=core_operation_id,
    )


def _replay_durable_run_action(intent: Any) -> Optional[tuple[JsonDict, HTTPStatus]]:
    if intent.state is not ActionState.SUCCEEDED:
        return None
    receipt = intent.core_receipt
    if not isinstance(receipt, Mapping):
        raise RealmIntegrityError("Durable Studio action receipt is missing.")
    response = receipt.get("response")
    status = receipt.get("http_status")
    if not isinstance(response, Mapping) or isinstance(status, bool) or not isinstance(
        status, int
    ):
        raise RealmIntegrityError("Durable Studio action receipt is invalid.")
    return dict(response), HTTPStatus(status)


def _complete_durable_run_action(
    state: UiState,
    *,
    intent: Any,
    result: EntityCoordinate,
    response: JsonDict,
    status: HTTPStatus,
) -> None:
    state.coordination.complete_action(
        operation_id=f"studio/action/{intent.intent_id}/complete",
        intent_id=intent.intent_id,
        result=result,
        core_receipt={"http_status": int(status), "response": response},
    )


def _approve_candidate_environment_preview_image(
    state: UiState,
    *,
    run_id: str,
    payload: Mapping[str, Any],
) -> JsonDict:
    """Approve when needed and install the exact blocking Preview image.

    The browser cannot name an arbitrary provider image: the request must
    reproduce one remediation on the current retained Candidate capability.
    """

    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "request_id",
            "presentation_selection",
            "profile_id",
            "image_ref",
        },
        label="Environment Preview trust approval request",
    )
    if request["schema"] != ENVIRONMENT_PREVIEW_TRUST_APPROVE_REQUEST_SCHEMA:
        raise ValueError(
            "Environment Preview trust approval request schema is unsupported."
        )
    request_id = _canonical_request_uuid(request["request_id"])
    canonical_run_id = RunViewRef(run_id=run_id).run_id
    presentation_selection = request["presentation_selection"]
    if not isinstance(presentation_selection, Mapping):
        raise ValueError("presentation_selection must be a JSON object.")
    profile_id = request["profile_id"]
    if (
        not isinstance(profile_id, str)
        or not profile_id
        or profile_id.strip() != profile_id
        or len(profile_id.encode("utf-8")) > 256
    ):
        raise ValueError("Environment Preview profile_id must be bounded text.")
    image_ref = ContainerGatewayImageTrust(
        image_ref=request["image_ref"]
    ).image_ref
    target, unavailable_reason = _candidate_action_target(
        state,
        run_id=canonical_run_id,
        presentation_selection=presentation_selection,
    )
    if target is None or unavailable_reason is not None or not target.runnable:
        raise RealmConflict(
            "Environment Preview approval requires the current runnable Candidate."
        )
    (
        _supported,
        _reason,
        _profiles,
        profile_diagnostics,
        _eligibility_detail,
    ) = _candidate_preview_runtime_capability(state, target=target)
    diagnostic = next(
        (
            item
            for item in profile_diagnostics
            if str(item.get("id") or "") == profile_id
        ),
        None,
    )
    remediation = (
        diagnostic.get("remediation")
        if isinstance(diagnostic, Mapping)
        and isinstance(diagnostic.get("remediation"), Mapping)
        else None
    )
    trust_source = str(
        diagnostic
        and diagnostic.get("eligibility_detail", {}).get("trust_source")
        or ""
    )
    remediation_kind = str(remediation and remediation.get("kind") or "")
    already_ready = False
    if isinstance(diagnostic, Mapping) and diagnostic.get("eligible") is True:
        try:
            already_ready = (
                compile_environment_preview_plan(
                    target,
                    profile_id=profile_id,
                ).runtime.image_ref
                == image_ref
            )
        except (EnvironmentPreviewCompileError, RealmConflict, TypeError, ValueError):
            already_ready = False
    if (
        not already_ready
        and (
            remediation is None
            or remediation_kind
            not in {"approve_container_gateway_image", "pull_container_image"}
            or remediation.get("image_ref") != image_ref
            or (
                remediation_kind == "approve_container_gateway_image"
                and trust_source != "realm"
            )
        )
    ):
        raise RealmConflict(
            "The current Candidate no longer requires this Preview image preparation."
        )
    runtime = _require_realm_runtime(state)
    decision = None
    if remediation_kind == "approve_container_gateway_image":
        decision = runtime.approve_container_gateway_image(
            operation_id=(
                f"studio/environment-preview/trust/approve/{request_id}"
            ),
            image_ref=image_ref,
            reason=(
                "Approved from Studio for the exact Environment Preview profile "
                f"{profile_id}."
            ),
        )
    downloaded = runtime.prepare_container_gateway_image(image_ref=image_ref)
    return {
        "schema": ENVIRONMENT_PREVIEW_TRUST_APPROVE_RESPONSE_SCHEMA,
        "request_id": request_id,
        "run_id": canonical_run_id,
        "profile_id": profile_id,
        "image_ref": image_ref,
        "decision_id": str(getattr(decision, "decision_id", "")),
        "downloaded": downloaded,
        "image_ready": True,
        "trust_generation": runtime.container_gateway_trust_generation,
        "restart_required": False,
    }


def _execute_run_workbench_action(
    state: UiState,
    *,
    run_id: str,
    payload: Any,
) -> tuple[JsonDict, HTTPStatus]:
    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "request_id",
            "action",
            "presentation_selection",
            "parameters",
        },
        label="run Workbench action request",
    )
    if request["schema"] != RUN_WORKBENCH_ACTION_REQUEST_SCHEMA:
        raise ValueError("Run Workbench action request schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    action = request["action"]
    if action not in _RUN_WORKBENCH_ACTIONS:
        raise ValueError("Run Workbench action is unsupported.")
    parameters = request["parameters"]
    if not isinstance(parameters, Mapping):
        raise ValueError("Run Workbench action parameters must be a JSON object.")
    preview_profile_id: Optional[str] = None
    content_session_id: Optional[str] = None
    child_run_confirmation: Optional[Mapping[str, Any]] = None
    if action == "environment_preview":
        if set(parameters) != {"profile_id"}:
            raise ValueError(
                "Environment Preview parameters must contain exactly profile_id."
            )
        value = parameters["profile_id"]
        if (
            not isinstance(value, str)
            or not value
            or value.strip() != value
            or len(value.encode("utf-8")) > 256
        ):
            raise ValueError(
                "Environment Preview profile_id must be nonempty bounded text."
            )
        preview_profile_id = value
    elif action == "open_read_only":
        if set(parameters) != {"content_session_id"}:
            raise ValueError(
                "Open Read Only parameters must contain exactly content_session_id."
            )
        content_session_id = _optional_selection_content_session_id(
            parameters["content_session_id"]
        )
    elif action == "evaluate_child_run":
        child_run_confirmation = _exact_json_object(
            parameters,
            expected={
                "schema",
                "preset",
                "expected_parent_seal_digest",
                "expected_plan_digest",
            },
            label="Re-evaluate exact plan confirmation",
        )
        if (
            child_run_confirmation["schema"]
            != RE_EVALUATE_EXACT_PLAN_CONFIRMATION_SCHEMA
        ):
            raise ValueError(
                "Re-evaluate exact plan confirmation schema is unsupported."
            )
        if child_run_confirmation["preset"] != RE_EVALUATE_EXACT_PLAN_PRESET_ID:
            raise ValueError("Re-evaluate exact plan preset is unsupported.")
        for field in ("expected_parent_seal_digest", "expected_plan_digest"):
            value = child_run_confirmation[field]
            if (
                not isinstance(value, str)
                or re.fullmatch(r"[0-9a-f]{64}", value) is None
            ):
                raise ValueError(f"{field} must be a lowercase SHA-256 digest.")
    elif parameters:
        raise ValueError("Run Workbench action parameters must be an empty object.")
    canonical_run_id = RunViewRef(run_id=run_id).run_id
    presentation_selection = request["presentation_selection"]
    if not isinstance(presentation_selection, Mapping):
        raise ValueError("presentation_selection must be a JSON object.")
    response: JsonDict = {
        "schema": RUN_WORKBENCH_ACTION_RESPONSE_SCHEMA,
        "request_id": request_id,
        "run_id": run_id,
        "action": action,
    }
    durable_intent = None
    if action == "evaluate_child_run":
        durable_intent = _durable_run_action_intent(
            state,
            request_id=request_id,
            run_id=canonical_run_id,
            action=action,
            presentation_selection=presentation_selection,
            parameters=parameters,
        )
        replay = _replay_durable_run_action(durable_intent)
        if replay is not None:
            return replay
    if action == "open_read_only":
        response["content_view"] = _open_selection_content_view(
            state,
            run_id=canonical_run_id,
            presentation_selection=presentation_selection,
            requested_session_id=content_session_id,
        )
        return response, HTTPStatus.CREATED
    if action == "keep_editable":
        if not _editable_workspace_provider_available(state):
            raise RealmConflict("Editable workspace provider is unavailable.")
        runtime = _require_realm_runtime(state)
        selection_result = runtime.run_views.mint_selection(
            ref=RunViewRef(run_id=canonical_run_id),
            presentation_selection=presentation_selection,
        )
        if selection_result.selection is None:
            raise RealmConflict(
                "Keep as Workspace requires a saved project-folder selection."
            )
        selection = selection_result.selection
        existing_action = _run_selection_workspace_action(state, selection)
        replay = (
            _replay_run_selection_workspace_action(state, existing_action)
            if existing_action is not None
            else None
        )
        if replay is not None:
            response.update(replay)
            return response, HTTPStatus.OK
        presented_kind = str(presentation_selection.get("kind") or "selection")
        presented_id = str(
            presentation_selection.get("entity_id") or "saved files"
        )
        workspace_action = _begin_run_selection_workspace_action(state, selection)
        stored_selection = SelectionRef.from_dict(
            workspace_action.parameters["selection"]
        )
        try:
            kept = _keep_run_selection_as_ui_workspace(
                state,
                operation_id=workspace_action.core_operation_id,
                selection=stored_selection,
                title=f"{presented_kind.replace('_', ' ').title()} {presented_id}",
                description="Realm-managed workspace kept from a Run Candidate",
            )
            _complete_run_selection_workspace_action(
                state,
                action=workspace_action,
                created=kept,
            )
        except Exception as error:
            _mark_run_selection_workspace_action_uncertain(
                state, workspace_action, error
            )
            raise
        response.update(kept)
        return response, HTTPStatus.CREATED
    if action == "evaluate_child_run":
        assert child_run_confirmation is not None
        service = _child_run_service_for_state(state)
        runtime = _require_realm_runtime(state)
        selection_result = runtime.run_views.mint_selection(
            ref=RunViewRef(run_id=canonical_run_id),
            presentation_selection=presentation_selection,
        )
        selection = selection_result.selection
        if selection is None or selection.kind != "candidate":
            raise RealmConflict(
                "Re-evaluate exact plan requires a current candidate selection."
            )
        preparations = service.prepare_exact_plan_selection_batch(
            selections=(selection,),
        )
        preparation = preparations.get(selection.selection_digest)
        if preparation is None:
            raise RealmIntegrityError(
                "Re-evaluate exact plan preparation omitted its selection."
            )
        if not preparation.eligibility.eligible or preparation.prepared is None:
            raise RealmConflict(
                "Re-evaluate exact plan is unavailable for this candidate: "
                f"{preparation.eligibility.code}."
            )
        prepared = preparation.prepared
        if prepared.request.max_trials > STUDIO_EXACT_PLAN_CONFIRMATION_MAX_TRIALS:
            raise RealmConflict(
                "Re-evaluate exact plan confirmation supports at most "
                f"{STUDIO_EXACT_PLAN_CONFIRMATION_MAX_TRIALS} evaluations."
            )
        if (
            child_run_confirmation["expected_parent_seal_digest"]
            != prepared.request.parent.seal_digest
            or child_run_confirmation["expected_plan_digest"] != prepared.plan_digest
        ):
            raise RealmConflict(
                "The terminal parent seal or exact evaluation plan changed; "
                "refresh and confirm the current plan."
            )
        try:
            target = runtime.inspection_targets.resolve_candidate(selection=selection)
        except RealmNotFound as error:
            raise RealmConflict(
                "Re-evaluate exact plan candidate is no longer available."
            ) from error
        if not target.runnable:
            raise RealmConflict(
                "Re-evaluate exact plan retained candidate or evaluation content "
                "is unavailable."
            )
        runtime_supported, runtime_reason = _candidate_child_run_runtime_capability(
            state,
            target=target,
            prepared=prepared,
        )
        if not runtime_supported:
            raise RealmConflict(
                "Re-evaluate exact plan runtime is unavailable: "
                f"{runtime_reason or 'child_run_runtime_unavailable'}."
            )
        assert durable_intent is not None
        committed = service.create_prepared_exact_plan(
            operation_id=durable_intent.core_operation_id,
            prepared=prepared,
        )
        response["child_run"] = {
            "schema": CHILD_RUN_PUBLIC_SCHEMA,
            "run_id": committed.run_id,
            "parent_run_id": committed.parent.run_id,
            "status": committed.admission.run.state,
        }
        _complete_durable_run_action(
            state,
            intent=durable_intent,
            result=EntityCoordinate(kind="run", entity_id=committed.run_id),
            response=response,
            status=HTTPStatus.ACCEPTED,
        )
        return response, HTTPStatus.ACCEPTED
    target, unavailable_reason = _candidate_action_target(
        state,
        run_id=canonical_run_id,
        presentation_selection=presentation_selection,
    )
    if target is None:
        raise RealmConflict(
            "Run action is unavailable for this selection: "
            f"{unavailable_reason or 'candidate_selection_unavailable'}."
        )
    if action == "inspect":
        response["inspection"] = _candidate_inspection_payload(target)
        return response, HTTPStatus.OK
    if unavailable_reason is not None or not target.runnable:
        raise RealmConflict(
            "Run action is unavailable for this selection: "
            f"{unavailable_reason or 'candidate_runtime_unavailable'}."
        )
    runtime = _require_realm_runtime(state)
    service = getattr(runtime, "operator_jobs", None)
    if service is None:
        raise RealmConflict("Operator Job provider is unavailable.")
    selection_result = runtime.run_views.mint_selection(
        ref=RunViewRef(run_id=run_id),
        presentation_selection=request["presentation_selection"],
    )
    if selection_result.selection is None:
        raise RealmConflict("Run action requires a runnable candidate selection.")
    if action == "environment_preview":
        (
            preview_supported,
            preview_reason,
            preview_profiles,
            _preview_profile_diagnostics,
            _preview_eligibility_detail,
        ) = (
            _candidate_preview_runtime_capability(state, target=target)
        )
        eligible_profile_ids = {
            str(item["id"])
            for item in preview_profiles
            if item.get("eligible") and item.get("id")
        }
        if not preview_supported or preview_profile_id not in eligible_profile_ids:
            raise RealmConflict(
                "Environment Preview is unavailable for this retained profile: "
                f"{preview_reason or 'environment_preview_profile_unavailable'}."
            )
        record = service.plan_environment_preview(
            operation_id=(
                f"studio/run-action/{run_id}/{request_id}/environment-preview"
            ),
            selection=selection_result.selection,
            profile_id=preview_profile_id,
        )
        response["job"] = _public_operator_job(record, state=state)
        return response, HTTPStatus.ACCEPTED
    debug_supported, debug_reason = _candidate_debug_runtime_capability(
        state, target=target
    )
    if not debug_supported:
        raise RealmConflict(
            "Debug Run is unavailable for this retained runtime: "
            f"{debug_reason or 'runtime_unsupported'}."
        )
    record = service.plan_candidate_debug_run(
        operation_id=f"studio/run-action/{run_id}/{request_id}/debug-run",
        selection=selection_result.selection,
    )
    response["job"] = _public_operator_job(record, state=state)
    return response, HTTPStatus.ACCEPTED


def _operator_job_presentation_key(job_id: str) -> str:
    return f"operator-job:{job_id}"


def _operator_job_output_unavailable(
    code: str, reason: str, *, supported: bool = True
) -> JsonDict:
    return {
        "supported": supported,
        "eligible": False,
        "code": code,
        "reason": reason,
    }


def _interface_output_failure_reason(error_code: Any) -> str:
    """Return path-free, actionable copy for a durable output failure code.

    Capture exceptions can contain private host paths, so the public Studio
    projection intentionally derives copy from the small retained error-code
    vocabulary instead of exposing the original exception.
    """

    code = str(error_code or "").strip().lower()
    if code == "content_rejected":
        return (
            "Studio could not safely save this folder because it contains "
            "unsupported filesystem content or metadata. Finish or clean the "
            "generated folder, then try again."
        )
    if code in {"session_expired", "session_ended", "attempt_expired"}:
        return (
            "The temporary interface session ended before Studio finished "
            "saving this output. Launch the interface again and regenerate it."
        )
    if code == "realm_conflict":
        return (
            "The output changed while Studio was saving it. Wait until "
            "generation finishes, then try again."
        )
    return (
        "Studio could not read and save this output. Check that generation is "
        "complete and the files are readable, then try again."
    )


def _public_live_operator_job_output(
    status: Any,
    *,
    retry_live: bool,
) -> JsonDict:
    raw = status.to_dict()
    output_state = str(raw.get("status") or "sealing")
    return {
        "id": str(raw.get("id") or ""),
        "label": str(raw.get("label") or ""),
        "kind": str(raw.get("kind") or ""),
        "status": output_state,
        "attempt": raw.get("attempt"),
        "error_code": raw.get("error_code"),
        "failure_reason": (
            _interface_output_failure_reason(raw.get("error_code"))
            if output_state == "failed"
            else None
        ),
        "logical_bytes": raw.get("logical_bytes"),
        "created_at": raw.get("created_at"),
        "updated_at": raw.get("updated_at"),
        "selection": None,
        "actions": {
            "view_read_only": _operator_job_output_unavailable(
                "operator_job_not_terminal",
                "This result can be viewed after the Candidate try finishes.",
            ),
            "keep_as_workspace": _operator_job_output_unavailable(
                "operator_job_not_terminal",
                "This project folder can be saved as a Workspace after the Candidate try finishes.",
            ),
            "retry_capture": {
                "supported": True,
                "eligible": output_state == "failed" and retry_live,
                "code": (
                    "ready"
                    if output_state == "failed" and retry_live
                    else "output_not_retryable"
                ),
                "reason": (
                    None
                    if output_state == "failed" and retry_live
                    else "Capture can be retried only for a failed output while the Preview is live."
                ),
            },
        },
    }


def _public_operator_job_interface_outputs(
    record: OperatorJobRecord,
    *,
    state: Optional[UiState],
) -> JsonDict:
    if record.plan.job_kind == "environment-preview":
        raw_plan = record.plan.input_facts.get("preview_plan")
        if not isinstance(raw_plan, Mapping):
            raise RealmIntegrityError(
                "Interactive Candidate interface is missing its retained settings."
            )
        preview_plan = EnvironmentPreviewPlan.from_dict(thaw_json(raw_plan))
        if not preview_plan.outputs_enabled:
            return {
                "supported": False,
                "lifecycle": "disabled",
                "outputs": [],
                "diagnostics": [],
            }
    if not record.state.terminal:
        statuses: tuple[Any, ...] = ()
        if record.plan.job_kind == "environment-preview" and state is not None:
            try:
                statuses = _operator_job_service_for_state(
                    state
                ).list_environment_preview_output_statuses(job_id=record.job_id)
            except (RealmConflict, RealmNotFound):
                statuses = ()
        retry_live = record.plan.job_kind == "environment-preview" and record.state in {
            OperatorJobState.STARTING,
            OperatorJobState.RUNNING,
        }
        return {
            "lifecycle": ("live" if retry_live else "pending"),
            "outputs": [
                _public_live_operator_job_output(item, retry_live=retry_live)
                for item in statuses
            ],
            "diagnostics": [],
        }

    result = None if record.result is None else record.result.result
    diagnostics = []
    if result is not None:
        raw_diagnostics = result.details.get("interface_output_diagnostics", ())
        if isinstance(raw_diagnostics, (list, tuple)):
            diagnostics = [
                dict(item)
                for item in raw_diagnostics[:256]
                if isinstance(item, Mapping)
            ]
    outputs: List[JsonDict] = []
    ready_ids: set[str] = set()
    if result is not None:
        for item in result.declared_outputs:
            ready_ids.add(item.declaration_id)
            view = _operator_job_output_unavailable(
                "selection_content_provider_unavailable",
                "Read-only result viewing is unavailable.",
                supported=False,
            )
            keep = _operator_job_output_unavailable(
                "selection_content_unavailable",
                "This saved result is not currently available as a Workspace.",
            )
            if state is not None:
                runtime = _require_realm_runtime(state)
                if _selection_content_provider_available(state):
                    view = _operator_job_output_unavailable(
                        "selection_content_unavailable",
                        "This saved result is not currently available to view.",
                    )
                try:
                    selection = runtime.ledger.mint_operator_job_output_selection(
                        actor_principal_id=runtime.actor_principal_id,
                        job_id=record.job_id,
                        output_id=item.declaration_id,
                    )
                    if _selection_content_provider_available(state):
                        view = runtime.ledger.resolve_selection_for_content_read(
                            actor_principal_id=runtime.actor_principal_id,
                            selection=selection,
                        ).eligibility.to_dict()
                    keep = runtime.selection_actions.open_read_only(
                        selection=selection
                    ).eligibility.to_dict()
                except (RealmConflict, RealmIntegrityError, RealmNotFound):
                    pass
            outputs.append(
                {
                    "id": item.declaration_id,
                    "label": item.name,
                    "kind": item.kind,
                    "status": "ready",
                    "attempt": None,
                    "error_code": None,
                    "failure_reason": None,
                    "logical_bytes": item.size_bytes,
                    "created_at": record.updated_at,
                    "updated_at": record.updated_at,
                    "selection": None,
                    "actions": {
                        "view_read_only": view,
                        "keep_as_workspace": keep,
                        "retry_capture": _operator_job_output_unavailable(
                            "operator_job_terminal",
                            "The Preview runtime is closed; saved outputs do not need capture retry.",
                        ),
                    },
                }
            )
    for diagnostic in diagnostics:
        output_id = str(diagnostic.get("id") or "")
        if (
            diagnostic.get("source") != "generation"
            or not output_id
            or output_id in ready_ids
        ):
            continue
        outputs.append(
            {
                "id": output_id,
                "label": str(diagnostic.get("label") or output_id),
                "kind": str(diagnostic.get("kind") or "output"),
                "status": "failed",
                "attempt": diagnostic.get("attempt"),
                "error_code": str(diagnostic.get("code") or "capture_failed"),
                "failure_reason": _interface_output_failure_reason(
                    diagnostic.get("code") or "capture_failed"
                ),
                "logical_bytes": None,
                "created_at": record.updated_at,
                "updated_at": record.updated_at,
                "selection": None,
                "actions": {
                    "view_read_only": _operator_job_output_unavailable(
                        "output_not_ready",
                        "Only a successfully saved result can be viewed.",
                    ),
                    "keep_as_workspace": _operator_job_output_unavailable(
                        "output_not_ready",
                        "Only a successfully saved project folder can be saved as a Workspace.",
                    ),
                    "retry_capture": _operator_job_output_unavailable(
                        "operator_job_terminal",
                        "Capture cannot be retried after the Preview runtime closes.",
                    ),
                },
            }
        )
    return {
        "lifecycle": "retained",
        "outputs": outputs,
        "diagnostics": diagnostics,
    }


def _public_operator_job_try_plan(record: OperatorJobRecord) -> Optional[JsonDict]:
    """Return only the immutable inspection settings useful to the operator."""

    facts = record.plan.input_facts
    if record.plan.job_kind == "candidate-debug-run":
        raw_spec = facts.get("evaluation_spec")
        if not isinstance(raw_spec, Mapping):
            raise RealmIntegrityError(
                "Candidate try is missing its retained evaluation settings."
            )
        spec = EvaluationSpec.from_dict(thaw_json(raw_spec))
        return {
            "schema": CANDIDATE_TRY_PLAN_SCHEMA,
            "mode": "try_once",
            "candidate_id": spec.candidate_id,
            "environment": {
                "id": spec.environment_id,
                "revision": spec.environment_revision_digest,
            },
            "settings": {
                "seed": spec.to_dict()["seed"],
                "repetition_index": spec.repetition_index,
                "interface_profile_id": None,
            },
        }
    if record.plan.job_kind == "environment-preview":
        raw_plan = facts.get("preview_plan")
        if not isinstance(raw_plan, Mapping):
            raise RealmIntegrityError(
                "Interactive Candidate interface is missing its retained settings."
            )
        plan = EnvironmentPreviewPlan.from_dict(thaw_json(raw_plan))
        return {
            "schema": CANDIDATE_TRY_PLAN_SCHEMA,
            "mode": "try_interactively",
            "candidate_id": plan.selection.entity_id,
            "environment": {
                "id": None,
                "revision": plan.fingerprints.source,
            },
            "settings": {
                "seed": None,
                "repetition_index": None,
                "interface_profile_id": plan.profile_id,
            },
        }
    return None


def _public_operator_job(
    record: OperatorJobRecord,
    *,
    state: Optional[UiState] = None,
    materialize_presentation: bool = False,
) -> JsonDict:
    if not isinstance(record, OperatorJobRecord):
        raise TypeError("Operator Job projection requires an OperatorJobRecord.")
    selection = record.plan.target.selection
    outcome = None
    if record.outcome is not None:
        value = record.outcome.outcome
        outcome = {
            "status": value.status.value,
            "code": value.code,
            "started": value.started,
            "disposition": value.disposition.value,
        }
    result = None
    if record.result is not None:
        value = record.result.result
        result = {
            "result_kind": value.result_kind,
            "status": value.status,
            "metrics": dict(value.metrics),
            "declared_outputs": [
                {
                    "declaration_id": item.declaration_id,
                    "name": item.name,
                    "kind": item.kind,
                    "size_bytes": item.size_bytes,
                    "media_type": item.media_type,
                }
                for item in value.declared_outputs
            ],
            "logs": [
                {
                    "stream": item.stream,
                    "byte_count": item.byte_count,
                    "line_count": item.line_count,
                    "truncated": item.truncated,
                }
                for item in value.logs
            ],
        }
    target: JsonDict = {
        "kind": record.plan.target.kind,
        "run_id": selection.source_id,
        "candidate_id": selection.entity_id,
    }
    presentation: Optional[JsonDict] = None
    if record.plan.job_kind == "environment-preview":
        retained_plan = record.plan.input_facts.get("preview_plan")
        if isinstance(retained_plan, Mapping):
            profile_id = retained_plan.get("profileId")
            if isinstance(profile_id, str) and profile_id:
                target["interface_profile_id"] = profile_id
        if state is not None and record.state is not OperatorJobState.RUNNING:
            state.presentation_broker.close(
                _operator_job_presentation_key(record.job_id)
            )
        if record.state is OperatorJobState.RUNNING:
            presentation = {"status": "ready"}
            if state is not None and materialize_presentation:
                try:
                    binding = _operator_job_service_for_state(
                        state
                    ).acquire_environment_preview_broker_binding(job_id=record.job_id)
                    endpoint = OwnedWebEndpoint.from_provider_binding(binding)
                except (RealmConflict, RealmNotFound):
                    state.presentation_broker.close(
                        _operator_job_presentation_key(record.job_id)
                    )
                    presentation = {
                        "status": "reconciling",
                        "reason": "presentation_endpoint_unavailable",
                    }
                else:
                    try:
                        lease = state.presentation_broker.open(
                            key=_operator_job_presentation_key(record.job_id),
                            endpoint=endpoint,
                        )
                    except OSError:
                        # Exhausted or policy-denied loopback ports are a
                        # presentation-capacity condition, not an Operator Job
                        # failure and not an HTTP 500 for the durable job read.
                        state.presentation_broker.close(
                            _operator_job_presentation_key(record.job_id)
                        )
                        presentation = {
                            "status": "reconciling",
                            "reason": "presentation_origin_unavailable",
                        }
                    else:
                        presentation = {
                            "status": "available",
                            **lease.public_dict(),
                        }
        elif record.state in {
            OperatorJobState.PLANNED,
            OperatorJobState.AWAITING_APPROVAL,
            OperatorJobState.QUEUED,
            OperatorJobState.STARTING,
        }:
            presentation = {"status": "pending"}
        else:
            presentation = {"status": "closed"}
    public = {
        "schema": OPERATOR_JOB_PUBLIC_SCHEMA,
        "job_id": record.job_id,
        "job_kind": record.plan.job_kind,
        "target": target,
        "state": record.state.value,
        "reconciliation_state": record.reconciliation_state.value,
        "cleanup_state": record.cleanup_state.value,
        "revision": record.revision,
        "created_at": record.created_at,
        "updated_at": record.updated_at,
        "can_stop": (
            not record.state.terminal and record.state is not OperatorJobState.STOPPING
        ),
        "stop_requested": record.stop is not None,
        "execution_policy": {
            "network_policy": record.plan.network_policy,
            "network_enforcement": getattr(
                record.plan, "network_enforcement", "advisory"
            ),
        },
        "outcome": outcome,
        "result": result,
    }
    inspection_plan = _public_operator_job_try_plan(record)
    if inspection_plan is not None:
        public["inspection_plan"] = inspection_plan
    if presentation is not None:
        public["presentation"] = presentation
    public["interface_outputs"] = _public_operator_job_interface_outputs(
        record,
        state=state,
    )
    return public


def _operator_job_service_for_state(state: UiState) -> Any:
    runtime = _require_realm_runtime(state)
    service = getattr(runtime, "operator_jobs", None)
    if service is None:
        raise RealmConflict("Operator Job provider is unavailable.")
    return service


def _operator_job_records_for_run(
    state: UiState,
    *,
    run_id: str,
    limit: int,
    states: Optional[tuple[OperatorJobState, ...]] = None,
    cleanup_states: Optional[tuple[OperatorJobCleanupState, ...]] = None,
) -> tuple[OperatorJobRecord, ...]:
    runtime = _require_realm_runtime(state)
    snapshot = runtime.ledger.read_run_snapshot(
        actor_principal_id=runtime.actor_principal_id,
        run_id=RunViewRef(run_id=run_id).run_id,
    )
    service = _operator_job_service_for_state(state)
    return service.list_for_run(
        source_owner_id=snapshot.run.owner_id,
        run_id=run_id,
        states=states,
        cleanup_states=cleanup_states,
        limit=limit,
    )


def _bounded_operator_job_limit(query: Dict[str, List[str]]) -> int:
    unknown = set(query) - {"limit"}
    if unknown:
        raise ValueError(
            f"Unknown Operator Job query parameters: {', '.join(sorted(unknown))}."
        )
    limit = _bounded_query_int(
        query,
        "limit",
        default=OPERATOR_JOB_PUBLIC_DEFAULT_LIST_SIZE,
    )
    if limit > OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE:
        raise ValueError(
            "Operator Job list limit must be at most "
            f"{OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE}."
        )
    return limit


def _realm_operator_jobs_payload(
    state: UiState,
    *,
    run_id: str,
    limit: int,
) -> JsonDict:
    if limit < 1 or limit > OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE:
        raise ValueError(
            "Operator Job list limit must be between 1 and "
            f"{OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE}."
        )
    records = _operator_job_records_for_run(
        state,
        run_id=run_id,
        limit=limit + 1,
    )
    selected = records[:limit]
    return {
        "schema": OPERATOR_JOB_LIST_SCHEMA,
        "run_id": run_id,
        "query": {"limit": limit},
        "jobs": [_public_operator_job(item, state=state) for item in selected],
        "page": {
            "count": len(selected),
            "has_more": len(records) > limit,
        },
    }


def _required_operator_job_id(value: str) -> str:
    if (
        not isinstance(value, str)
        or re.fullmatch(r"operator-job-[0-9a-f]{32}", value) is None
    ):
        raise ValueError("Operator Job id is invalid.")
    return value


def _operator_job_by_public_id(state: UiState, *, job_id: str) -> OperatorJobRecord:
    """Resolve a public job id, then reauthorize its canonical source run."""

    record = _operator_job_service_for_state(state).read(
        job_id=_required_operator_job_id(job_id)
    )
    selection = record.plan.target.selection
    if selection.source_kind != "run":
        raise RealmNotFound("Operator Job does not have a public run context.")
    return _operator_job_for_run(
        state,
        run_id=selection.source_id,
        job_id=record.job_id,
    )


def _operator_job_for_run(
    state: UiState, *, run_id: str, job_id: str
) -> OperatorJobRecord:
    job_id = _required_operator_job_id(job_id)
    record = _operator_job_service_for_state(state).read(job_id=job_id)
    selection = record.plan.target.selection
    if selection.source_kind != "run" or selection.source_id != run_id:
        raise RealmNotFound("Operator Job is not attached to this run.")
    # Reauthorize the run context as well; a job grant is not a substitute for
    # access to the route's canonical source run.
    _operator_job_records_for_run(state, run_id=run_id, limit=1)
    return record


def _realm_operator_job_detail_payload(
    state: UiState, *, run_id: str, job_id: str
) -> JsonDict:
    return {
        "schema": OPERATOR_JOB_DETAIL_SCHEMA,
        "run_id": run_id,
        "job": _public_operator_job(
            _operator_job_for_run(state, run_id=run_id, job_id=job_id),
            state=state,
            materialize_presentation=True,
        ),
    }


def _stop_realm_operator_job(
    state: UiState,
    *,
    run_id: str,
    job_id: str,
    payload: Any,
) -> JsonDict:
    request = _exact_json_object(
        payload,
        expected={"schema", "request_id"},
        label="Operator Job stop request",
    )
    if request["schema"] != OPERATOR_JOB_STOP_REQUEST_SCHEMA:
        raise ValueError("Operator Job stop request schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    record = _operator_job_for_run(state, run_id=run_id, job_id=job_id)
    state.presentation_broker.close(_operator_job_presentation_key(record.job_id))
    stopped = _operator_job_service_for_state(state).request_stop(
        operation_id=(
            f"studio/operator-job-stop/{run_id}/{record.job_id}/{request_id}"
        ),
        job_id=record.job_id,
    )
    return {
        "schema": OPERATOR_JOB_DETAIL_SCHEMA,
        "run_id": run_id,
        "job": _public_operator_job(stopped, state=state),
    }


def _cancel_realm_run(
    state: UiState,
    *,
    run_id: str,
    payload: Any,
) -> JsonDict:
    """Route a public Run stop through Core's durable handoff authority."""

    run_id = RunViewRef(run_id=run_id).run_id
    request = _exact_json_object(
        payload,
        expected={"schema", "request_id"},
        label="Run cancellation request",
    )
    if request["schema"] != RUN_CANCEL_REQUEST_SCHEMA:
        raise ValueError("Run cancellation request schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    launch = _study_launch_service_for_state(state).request_run_cancel(
        operation_id=f"studio/run-cancel/{run_id}/{request_id}",
        run_id=run_id,
        reason_code="user_cancelled",
    )
    head = _require_realm_runtime(state).run_views.workbench_head(
        ref=RunViewRef(run_id=run_id)
    )
    summary = head.summary.to_dict()
    return {
        "schema": RUN_CANCEL_RESPONSE_SCHEMA,
        "run_id": run_id,
        "launch": launch.to_dict(),
        "run": _realm_compat_run_row(
            state,
            summary,
            overview=head.overview.to_dict(),
        ),
    }


def _operator_job_declared_output(record: OperatorJobRecord, *, output_id: str) -> Any:
    if record.result is None:
        raise RealmConflict("Candidate try has no saved output result.")
    output = next(
        (
            item
            for item in record.result.result.declared_outputs
            if item.declaration_id == output_id
        ),
        None,
    )
    if output is None:
        raise RealmNotFound("Operator Job output was not found.")
    return output


def _view_realm_operator_job_output(
    state: UiState,
    *,
    record: OperatorJobRecord,
    output_id: str,
    requested_session_id: Optional[str],
) -> JsonDict:
    """Open a retained Candidate-try result through Selection Content View."""

    if not record.state.terminal:
        raise RealmConflict(
            "View result requires a terminal Candidate try output."
        )
    output = _operator_job_declared_output(record, output_id=output_id)
    runtime = _require_realm_runtime(state)
    selection = runtime.ledger.mint_operator_job_output_selection(
        actor_principal_id=runtime.actor_principal_id,
        job_id=record.job_id,
        output_id=output_id,
    )
    media_type = output.media_type
    if not media_type:
        media_type = mimetypes.guess_type(output.name)[0] or "application/octet-stream"
    return {
        "content_view": _open_exact_selection_content_view(
            state,
            run_id=record.plan.target.selection.source_id,
            public_selection={
                "kind": selection.kind,
                "entity_id": selection.entity_id,
                "revision": selection.source_revision,
                "sequence": selection.source_sequence,
            },
            selection=selection,
            requested_session_id=requested_session_id,
            media_type=media_type,
        )
    }


def _keep_realm_operator_job_output(
    state: UiState,
    *,
    record: OperatorJobRecord,
    output_id: str,
    request_id: Any,
) -> JsonDict:
    if not record.state.terminal:
        raise RealmConflict(
            "Keep as Workspace requires a terminal Operator Job output."
        )
    output = _operator_job_declared_output(record, output_id=output_id)
    runtime = _require_realm_runtime(state)
    selection = runtime.ledger.mint_operator_job_output_selection(
        actor_principal_id=runtime.actor_principal_id,
        job_id=record.job_id,
        output_id=output_id,
    )
    opened = runtime.selection_actions.open_read_only(selection=selection)
    if not opened.eligibility.eligible:
        raise RealmConflict(
            "Keep as Workspace is unavailable for this output: "
            f"{opened.eligibility.code}."
        )
    result = _keep_selection_as_ui_workspace(
        state,
        operation_id=_workspace_create_operation_id(
            "operator-job-output", request_id
        ),
        selection=selection,
        title=output.name,
        description="Realm-managed workspace kept from an Operator Job output",
    )
    refreshed = _operator_job_service_for_state(state).read(job_id=record.job_id)
    projected = _public_operator_job(refreshed, state=state)
    result["job"] = projected
    result["output"] = next(
        (
            item
            for item in projected.get("interface_outputs", {}).get("outputs", [])
            if item.get("id") == output_id
        ),
        None,
    )
    return result


def _retry_realm_operator_job_output(
    state: UiState,
    *,
    record: OperatorJobRecord,
    output_id: str,
) -> JsonDict:
    if record.plan.job_kind != "environment-preview":
        raise RealmConflict("Operator Job is not an Environment Preview.")
    _operator_job_service_for_state(state).retry_environment_preview_output(
        job_id=record.job_id,
        output_id=output_id,
    )
    refreshed = _operator_job_service_for_state(state).read(job_id=record.job_id)
    projected = _public_operator_job(refreshed, state=state)
    return {
        "job": projected,
        "output": next(
            (
                item
                for item in projected.get("interface_outputs", {}).get("outputs", [])
                if item.get("id") == output_id
            ),
            None,
        ),
    }


def _study_launch_needs_reconciliation(launch: StudyLaunchView) -> bool:
    if not launch.job.state.terminal:
        return True
    if launch.job.cleanup_state is OperatorJobCleanupState.PENDING:
        return True
    return False


def _study_launch_method_environment_binding(
    launch: StudyLaunchView,
) -> JsonDict:
    facts = thaw_json(launch.job.plan.input_facts)
    binding = facts.get("method_environment_binding")
    if not isinstance(binding, dict):
        raise RealmIntegrityError(
            "Study launch is missing its Method environment binding."
        )
    return binding


def _run_method_environment_binding(descriptor: Any) -> JsonDict | None:
    # Exact-plan child Runs are deliberately methodless.  They have no Method
    # process to receive local values, so do not manufacture an empty binding
    # descriptor (which would also require a retained-batch binding revision).
    if descriptor.mode == RUN_EXECUTION_MODE_EXACT_PLAN:
        return None
    names = tuple(descriptor.method_environment_names)
    revision_ids = tuple(descriptor.method_environment_revision_ids)
    source = descriptor.method_environment_source
    return {
        "binding_revision": descriptor.method_environment_binding_revision,
        "recoverability": descriptor.method_environment_recoverability,
        "requirements": [
            {
                "name": name,
                "revision_id": revision_id,
                "source": source,
            }
            for name, revision_id in zip(names, revision_ids, strict=True)
        ],
        "schema": METHOD_ENVIRONMENT_BINDING_SCHEMA,
    }


def _studio_method_launch_environment(
    state: UiState,
    binding: Mapping[str, Any],
) -> tuple[
    MethodLaunchEnvironment | MethodLaunchEnvironmentDescriptor,
    ValueError | None,
]:
    """Build a one-use value handoff, or a safe descriptor for attachment."""

    requirements = binding.get("requirements")
    if not isinstance(requirements, list):
        raise RealmIntegrityError(
            "Method environment binding requirements are malformed."
        )
    names = tuple(_clean_env_var_name(item.get("name")) for item in requirements)
    binding_revision = str(binding.get("binding_revision") or "")
    descriptor = MethodLaunchEnvironmentDescriptor(
        names=names,
        binding_revision=binding_revision,
    )
    if not names:
        return descriptor, None
    try:
        selected = _studio_method_environment_values(state, binding)
    except ValueError as error:
        # A names-only descriptor can still attach to the exact worker that
        # already received this Run's bound revision before Studio restarted.
        return descriptor, error
    environment = MethodLaunchEnvironment(
        names,
        selected,
        binding_revision=binding_revision,
    )
    selected.clear()
    return environment, None


def _schedule_study_launch_execution(
    state: UiState,
    *,
    launch_id: str,
) -> bool:
    """Best-effort dispatch while Core retains all lifecycle authority."""

    if state._background_execution_closing.is_set():
        return False
    service = _study_launch_service_for_state(state)
    launch = service.read(launch_id=launch_id)
    launch_id = launch.launch_id
    environment_binding = _study_launch_method_environment_binding(launch)
    with state._lock:
        if state._background_execution_closing.is_set():
            return False
        existing = state._study_launch_threads.get(launch_id)
        if existing is not None and existing.is_alive():
            return False

        def execute() -> None:
            retry_delay = 0.25
            environment_wait_reported = False
            try:
                while True:
                    if state._background_execution_closing.is_set():
                        return
                    method_environment, binding_error = (
                        _studio_method_launch_environment(
                            state, environment_binding
                        )
                    )
                    try:
                        current = service.execute(
                            launch_id=launch_id,
                            method_environment=method_environment,
                        )
                    except MethodLaunchEnvironmentError:
                        if binding_error is None:
                            raise
                        if not environment_wait_reported:
                            print(
                                "OptPilot Study launch is waiting for its "
                                f"bound Method setting: {binding_error}",
                                file=sys.stderr,
                                flush=True,
                            )
                            environment_wait_reported = True
                        if state._background_execution_closing.wait(retry_delay):
                            return
                        retry_delay = min(5.0, max(0.25, retry_delay * 2.0))
                        continue
                    except StudyLaunchDispatchDeferred:
                        # Another live fence won the claim. Its durable lease
                        # may expire after a crash, so keep a bounded backoff
                        # reconciler rather than manufacturing local status.
                        current = service.read(launch_id=launch_id)
                    environment_wait_reported = False
                    if not _study_launch_needs_reconciliation(current):
                        return
                    if state._background_execution_closing.wait(retry_delay):
                        return
                    retry_delay = min(5.0, max(0.25, retry_delay * 2.0))
            except Exception:
                # A Study launch owns scheduling only through the durable
                # handoff.  If Core already created the canonical Run, move
                # reconciliation immediately to the shared run-id guard.  In
                # particular, a provider failure after controller confirmation
                # must not be lost merely because the launch job is now
                # terminal and therefore absent from launch reconciliation.
                if state._background_execution_closing.is_set():
                    return
                try:
                    handed_off = service.read(launch_id=launch_id)
                    run_id = handed_off.run_id
                except Exception:
                    run_id = None
                if run_id is not None:
                    try:
                        _schedule_run_execution(state, run_id=run_id)
                    except Exception:
                        # The exact Run remains discoverable by Core startup
                        # reconciliation.  Never manufacture a Studio-owned
                        # failure state or a second controller identity here.
                        pass
            finally:
                with state._lock:
                    if (
                        state._study_launch_threads.get(launch_id)
                        is threading.current_thread()
                    ):
                        state._study_launch_threads.pop(launch_id, None)

        thread = threading.Thread(
            target=execute,
            name=f"optpilot-study-launch-{launch_id[-12:]}",
            daemon=True,
        )
        state._study_launch_threads[launch_id] = thread
        thread.start()
        return True


def _reconcile_visible_study_launches(state: UiState) -> None:
    """Adopt every bounded Core launch that still needs local progress."""

    if not _study_launch_provider_available(state):
        return
    try:
        launches = _study_launch_service_for_state(state).list_reconcilable()
    except Exception:
        return
    for launch in launches:
        try:
            _schedule_study_launch_execution(state, launch_id=launch.launch_id)
        except Exception:
            # One stale or concurrently claimed launch must not hide another
            # independently retained launch from startup adoption.
            continue


def _schedule_run_execution(
    state: UiState,
    *,
    run_id: str,
) -> bool:
    """Dispatch any supported canonical run through one Core service."""

    run_id = RunViewRef(run_id=run_id).run_id
    if state._background_execution_closing.is_set():
        return False
    runtime = _require_realm_runtime(state)
    descriptor = runtime.run_execution.describe(run_id=run_id)
    environment_binding = _run_method_environment_binding(descriptor)
    with state._lock:
        if state._background_execution_closing.is_set():
            return False
        existing = state._run_execution_threads.get(run_id)
        if existing is not None and existing.is_alive():
            return False
        dispatch_operation_id = new_run_execution_dispatch_operation_id()

        def execute() -> None:
            retry_delay = 0.25
            last_error_signature: tuple[str, str] | None = None
            try:
                while True:
                    if runtime.closed or state._background_execution_closing.is_set():
                        return
                    if environment_binding is None:
                        method_environment = None
                        binding_error = None
                    else:
                        method_environment, binding_error = (
                            _studio_method_launch_environment(
                                state, environment_binding
                            )
                        )
                    try:
                        execute_arguments = {
                            "run_id": run_id,
                            "dispatch_operation_id": dispatch_operation_id,
                        }
                        if method_environment is not None:
                            execute_arguments["method_environment"] = (
                                method_environment
                            )
                        summary = runtime.run_execution.execute(**execute_arguments)
                        last_error_signature = None
                    except MethodLaunchEnvironmentError:
                        if binding_error is None:
                            raise
                        signature = (
                            type(binding_error).__name__,
                            str(binding_error),
                        )
                        if signature != last_error_signature:
                            print(
                                "OptPilot Run execution is waiting for its "
                                f"bound Method setting: {binding_error}",
                                file=sys.stderr,
                                flush=True,
                            )
                            last_error_signature = signature
                        if state._background_execution_closing.wait(retry_delay):
                            return
                        retry_delay = min(5.0, max(0.25, retry_delay * 2.0))
                        continue
                    except RunExecutionDeferred:
                        if state._background_execution_closing.is_set():
                            return
                        summary = runtime.run_reader.summary(run_id=run_id)
                    except Exception as error:
                        # A failed dispatch may already own the live controller
                        # term.  Keep the same process-local dispatch identity,
                        # re-read only canonical state, and wait for either
                        # same-term recovery or expiry-authorized takeover.
                        # This is reconciliation, not a second lifecycle.
                        signature = (type(error).__name__, str(error))
                        if signature != last_error_signature:
                            print(
                                "OptPilot Run execution is waiting to recover "
                                f"{run_id}: {signature[0]}: {signature[1]}",
                                file=sys.stderr,
                                flush=True,
                            )
                            last_error_signature = signature
                        if (
                            runtime.closed
                            or state._background_execution_closing.is_set()
                        ):
                            return
                        try:
                            summary = runtime.run_reader.summary(run_id=run_id)
                        except Exception:
                            return
                    if summary.run_status != "running":
                        return
                    if runtime.closed or state._background_execution_closing.is_set():
                        return
                    if state._background_execution_closing.wait(retry_delay):
                        return
                    # A persistent identical failure (an unrecoverable worker,
                    # for example) must not hammer the Realm every 5 seconds
                    # forever — that starves every other Studio request. Let
                    # the failure streak back off toward 5 minutes; a healthy
                    # dispatch resets the signature and returns to the fast
                    # cadence.
                    ceiling = 300.0 if last_error_signature is not None else 5.0
                    retry_delay = min(ceiling, max(0.25, retry_delay * 2.0))
            except Exception:
                # The canonical nonterminal run remains intact and will be
                # rediscovered through Core. Studio owns no lifecycle mirror.
                pass
            finally:
                with state._lock:
                    if (
                        state._run_execution_threads.get(run_id)
                        is threading.current_thread()
                    ):
                        state._run_execution_threads.pop(run_id, None)

        thread = threading.Thread(
            target=execute,
            name=f"optpilot-run-execution-{run_id[-12:]}",
            daemon=True,
        )
        state._run_execution_threads[run_id] = thread
        thread.start()
        return True


def _reconcile_visible_run_executions(state: UiState) -> None:
    """Adopt all supported canonical runs after Core's complete page scan."""

    if state.realm_runtime is None:
        return
    try:
        descriptors = tuple(state.realm_runtime.run_execution.list_reconcilable())
    except Exception:
        return

    for descriptor in descriptors:
        try:
            _schedule_run_execution(state, run_id=descriptor.run_id)
        except Exception:
            # Each run remains durable and independently recoverable. One
            # stale or concurrently claimed run must not hide its neighbors.
            continue


def _schedule_operator_job_execution(state: UiState, *, job_id: str) -> bool:
    if state._background_execution_closing.is_set():
        return False
    service = _operator_job_service_for_state(state)
    service.read(job_id=_required_operator_job_id(job_id))
    with state._lock:
        if state._background_execution_closing.is_set():
            return False
        existing = state._operator_job_threads.get(job_id)
        if existing is not None and existing.is_alive():
            return False

        def execute() -> None:
            retry_delay = 0.25
            try:
                while True:
                    if state._background_execution_closing.is_set():
                        return
                    try:
                        service.execute(job_id=job_id)
                        return
                    except (
                        EnvironmentPreviewFinalCapturePending,
                        RealmCapacityUnavailable,
                    ):
                        # Capacity shortage leaves an exact queued head; final
                        # Preview capture can likewise leave an exact running
                        # head while another adopter finishes a persisted seal.
                        # Keep one bounded scheduler thread so both conditions
                        # converge without a restart or another click.
                        if state._background_execution_closing.is_set():
                            return
                        current = service.read(job_id=job_id)
                        if current.state.terminal:
                            return
                        if retry_delay and state._background_execution_closing.wait(
                            retry_delay
                        ):
                            return
                        retry_delay = min(5.0, max(0.25, retry_delay * 2.0))
            except Exception:
                # The durable nonterminal head is deliberately retained for
                # the next reconciliation pass; the thread owns no authority
                # that could safely manufacture a terminal result here.
                pass
            finally:
                if state._background_execution_closing.is_set():
                    state.presentation_broker.close(
                        _operator_job_presentation_key(job_id)
                    )
                else:
                    try:
                        current = service.read(job_id=job_id)
                        if current.state is not OperatorJobState.RUNNING:
                            state.presentation_broker.close(
                                _operator_job_presentation_key(job_id)
                            )
                    except Exception:
                        # Presentation authority is process-local and revocable;
                        # durable provider/job reconciliation remains authoritative.
                        state.presentation_broker.close(
                            _operator_job_presentation_key(job_id)
                        )
                with state._lock:
                    if (
                        state._operator_job_threads.get(job_id)
                        is threading.current_thread()
                    ):
                        state._operator_job_threads.pop(job_id, None)

        thread = threading.Thread(
            target=execute,
            name=f"optpilot-operator-job-{job_id[-12:]}",
            daemon=True,
        )
        state._operator_job_threads[job_id] = thread
        thread.start()
        return True


def _reconcile_visible_operator_jobs(state: UiState) -> None:
    """Best-effort bounded startup adoption for locally visible run jobs."""

    if not _operator_job_provider_available(state):
        return
    runtime = _require_realm_runtime(state)
    try:
        run_items = []
        page_token = None
        seen_page_tokens: set[str] = set()
        while True:
            page = runtime.run_reader.list_runs(
                page_token=page_token,
                limit=100,
            )
            run_items.extend(page.items)
            next_page_token = page.next_page_token
            if next_page_token is None:
                break
            if next_page_token in seen_page_tokens:
                # A repeated opaque token indicates a broken read snapshot;
                # do not spin or silently claim full startup reconciliation.
                return
            seen_page_tokens.add(next_page_token)
            page_token = next_page_token
    except Exception:
        return
    reconcilable_states = tuple(
        state for state in OperatorJobState if not state.terminal
    )
    for item in run_items:
        try:
            active = _operator_job_records_for_run(
                state,
                run_id=item.run_id,
                states=reconcilable_states,
                limit=OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE,
            )
            cleanup_debt = _operator_job_records_for_run(
                state,
                run_id=item.run_id,
                cleanup_states=(OperatorJobCleanupState.PENDING,),
                limit=OPERATOR_JOB_PUBLIC_MAX_LIST_SIZE,
            )
            records = tuple(
                {record.job_id: record for record in (*active, *cleanup_debt)}.values()
            )
        except Exception:
            continue
        for record in records:
            try:
                _schedule_operator_job_execution(state, job_id=record.job_id)
            except Exception:
                continue


def _run_display_name(
    job_payload: Optional[Mapping[str, Any]],
    objective: Any,
    run_id: str,
) -> str:
    """What to call a Run in a list of them.

    A Run launched from Studio carries the Run setup's name. One started any
    other way -- the command line, or an older job record -- did not, and fell
    back to the Run's own identifier: a list of forty-character hashes with
    nothing saying what any of them had been. The pieces to describe it were
    already on the record and simply unused.
    """

    payload = job_payload if isinstance(job_payload, Mapping) else {}
    study_name = str(payload.get("study_name") or "").strip()
    if study_name:
        return study_name

    environment_id = str(payload.get("environment_id") or "").strip()
    goal = objective if isinstance(objective, Mapping) else {}
    direction = str(goal.get("direction") or "").strip()
    metric = str(goal.get("metric") or "").strip()
    aim = f"{direction} {metric}".strip() if metric else ""

    if environment_id and aim:
        return f"{environment_id} — {aim}"
    if environment_id:
        return environment_id
    if aim:
        return aim
    return run_id


def _realm_presentation_status(run_status: str) -> str:
    if run_status == "succeeded":
        return "completed"
    return run_status


def _realm_compat_run_row(
    state: UiState,
    summary: JsonDict,
    *,
    catalog_entry: Optional[JsonDict] = None,
    overview: Optional[JsonDict] = None,
    diagnostics: Optional[List[JsonDict]] = None,
) -> JsonDict:
    run_id = str(summary["run_id"])
    counts = (
        summary.get("counts", {}) if isinstance(summary.get("counts"), dict) else {}
    )
    logical = (
        counts.get("logical_trials", {})
        if isinstance(counts.get("logical_trials"), dict)
        else {}
    )
    attempts = (
        counts.get("attempts", {}) if isinstance(counts.get("attempts"), dict) else {}
    )
    observations = (
        counts.get("observations", {})
        if isinstance(counts.get("observations"), dict)
        else {}
    )
    best_comparable_candidate = (
        overview.get("best_candidate")
        if isinstance(overview, dict)
        and isinstance(overview.get("best_candidate"), dict)
        else None
    )
    if best_comparable_candidate is None:
        best_comparable_candidate = {
            "available": False,
            "reason": "overview_unavailable",
            "candidate_id": None,
            "value": None,
            "sample_count": None,
            "rank": None,
            "tie_count": 0,
            "evaluation_plan_group": None,
        }
    objective = (
        summary.get("objective", {})
        if isinstance(summary.get("objective"), dict)
        else {}
    )
    budget = (
        summary.get("budget", {})
        if isinstance(summary.get("budget"), dict)
        else {}
    )
    head = summary.get("cursor", {}) if isinstance(summary.get("cursor"), dict) else {}
    if overview is not None:
        if not isinstance(overview, dict):
            raise TypeError("Run row overview must be an object.")
        if overview.get("run_id") != run_id or overview.get("head") != head:
            raise ValueError(
                "Run row overview must describe the same Run and exact head as its "
                "summary."
            )
    catalog = catalog_entry or {}
    if not budget and isinstance(catalog.get("budget"), dict):
        budget = catalog["budget"]
    job, job_diagnostic = _job_for_run_id_resolution(state, run_id)
    if job_diagnostic is not None and diagnostics is not None:
        diagnostics.append(job_diagnostic)
    job_payload = job.to_dict() if job is not None else None
    run_status = str(summary.get("run_status") or catalog.get("state") or "running")
    created_at = catalog.get("created_at")
    updated_at = catalog.get("updated_at")
    if job_payload is not None:
        job_started_at = job_payload.get("started_at")
        job_finished_at = job_payload.get("finished_at")
        created_at = created_at if created_at is not None else job_started_at
        updated_at = (
            updated_at if updated_at is not None else job_finished_at or job_started_at
        )
    return {
        "id": run_id,
        "run_id": run_id,
        "name": _run_display_name(job_payload, objective, run_id),
        "status": (
            str(job_payload.get("status"))
            if job_payload is not None and job_payload.get("status")
            else _realm_presentation_status(run_status)
        ),
        "summary_schema_version": summary.get("schema"),
        "run_status": run_status,
        "submission_state": summary.get("submission_state"),
        "retention_state": summary.get("retention_state"),
        "stop_code": summary.get("stop_code"),
        "completed_trials": logical.get("terminal", 0),
        "accepted_trials": logical.get("total", 0),
        "terminal_trials": logical.get("terminal", 0),
        "attempt_count": attempts.get("total", 0),
        "observation_count": observations.get("total", 0),
        # A low-level best observation is intentionally absent here: it is not
        # necessarily a complete, comparable Candidate result and must not be
        # mistaken for Studio's Run-wide decision summary.
        "best_comparable_candidate": deepcopy(best_comparable_candidate),
        "failure_count": logical.get("final_failures", 0),
        "final_failure_count": logical.get("final_failures", 0),
        "objective": objective,
        "budget": budget,
        "environment_id": (
            job_payload.get("environment_id") if job_payload is not None else None
        ),
        "method": {},
        "started_at": created_at,
        "finished_at": updated_at
        if run_status in {"succeeded", "failed", "cancelled"}
        else None,
        "updated_at": updated_at,
        "status_counts": observations.get("by_outcome", {}),
        "head": head,
        "can_stop": bool(job_payload is not None and job_payload.get("can_stop")),
        "cancellation_requested": bool(
            job_payload is not None and job_payload.get("cancellation_requested")
        ),
        "job": job_payload,
    }


def _realm_runs_payload(
    state: UiState,
    *,
    page_token: Optional[str] = None,
    limit: int = 50,
) -> JsonDict:
    runtime = _require_realm_runtime(state)
    page = runtime.run_reader.list_runs(page_token=page_token, limit=limit)
    catalog = page.to_dict()
    entries = {item.run_id: item.to_dict() for item in page.items}
    rows = []
    diagnostics: List[JsonDict] = []
    for item in page.items:
        try:
            workbench = runtime.run_views.workbench_head(
                ref=RunViewRef(run_id=item.run_id)
            )
            summary = workbench.summary.to_dict()
            rows.append(
                _realm_compat_run_row(
                    state,
                    summary,
                    catalog_entry=entries[item.run_id],
                    overview=workbench.overview.to_dict(),
                    diagnostics=diagnostics,
                )
            )
        except RealmIntegrityError:
            # Isolate an unreadable retained row.  The canonical catalog still
            # reports it, while the user-facing list remains usable for every
            # independently valid Run on the same page.
            diagnostics.append(
                {
                    "code": "run_projection_unavailable",
                    "message": (
                        "This Run could not be shown because its retained data "
                        "could not be verified. It was not modified."
                    ),
                    "run_id": item.run_id,
                }
            )
    diagnostic_limit = 10
    limited_count = sum(
        1
        for item in diagnostics
        if item["code"]
        in {"older_study_metadata_unsupported", "study_metadata_unavailable"}
    )
    hidden_count = len(diagnostics) - limited_count
    return {
        "runs": rows,
        "catalog": catalog,
        "unavailable": {
            "count": len(diagnostics),
            "hidden_count": hidden_count,
            "items": diagnostics[:diagnostic_limit],
            "limited_count": limited_count,
            "schema": "optpilot.studio-run-list-unavailable.v1",
            "truncated": len(diagnostics) > diagnostic_limit,
        },
    }


# Independent fingerprint checks bound staleness for the one known write that
# neither touches a run head nor a job row (a run-cancellation request made by
# a non-Studio process); Studio's own mutations invalidate explicitly.
_RUNS_RESPONSE_CACHE_MAX_AGE_SECONDS = 30.0


def _invalidate_runs_response_cache(state: UiState) -> None:
    with state._runs_response_cache_lock:
        state._runs_mutation_generation += 1
        state._runs_response_cache = None


def _runs_neutral_mutation_path(path: str) -> bool:
    """True for chatty mutation endpoints that can never change a Run row.

    The Assistant transcript sync posts every few seconds while a session is
    busy; invalidating the Run-list cache on it would defeat the cache.
    """

    return path.startswith("/api/agent-sessions/") and path.endswith("/sync")


def _runs_payload_fingerprint(state: UiState, *, limit: int) -> str:
    """Digest every cheap input that can change a Run-list row.

    Reads one bounded catalog page and the raw study-launch job records; both
    are single authorized SQL scans without per-run snapshot reads.  The
    process-local mutation generation covers Studio-side writes (notably
    run-cancellation requests) that change row presentation without moving a
    run head or a job revision.
    """

    runtime = _require_realm_runtime(state)
    page = runtime.run_reader.list_runs(limit=limit)
    jobs = runtime.ledger.list_operator_jobs_for_actor(
        actor_principal_id=runtime.actor_principal_id,
        job_kind=STUDY_LAUNCH_JOB_KIND,
        limit=200,
    )
    material = {
        "generation": state._runs_mutation_generation,
        "jobs": [
            [job.job_id, job.revision, job.updated_at, job.cleanup_state.value]
            for job in jobs
        ],
        "limit": limit,
        "runs": [
            [
                item.run_id,
                item.state,
                item.retention_state,
                item.current_revision,
                item.head_sequence,
                item.accepted_logical_trials,
                item.updated_at,
            ]
            for item in page.items
        ],
        "truncated": page.has_more,
    }
    return hashlib.sha256(
        json.dumps(material, sort_keys=True).encode("utf-8")
    ).hexdigest()


def _runs_response_entry(state: UiState, *, limit: int) -> JsonDict:
    """Serve the serialized first Run-list page, rebuilding only on change."""

    with state._runs_response_cache_lock:
        fingerprint = _runs_payload_fingerprint(state, limit=limit)
        entry = state._runs_response_cache
        now = time.monotonic()
        if (
            entry is not None
            and entry["limit"] == limit
            and entry["fingerprint"] == fingerprint
            and now - entry["built_at"] < _RUNS_RESPONSE_CACHE_MAX_AGE_SECONDS
        ):
            return entry
        payload = _realm_runs_payload(state, limit=limit)
        body = json.dumps(
            _public_studio_payload(payload), indent=2, sort_keys=True
        ).encode("utf-8")
        entry = {
            "body": body,
            "built_at": now,
            "etag": '"' + hashlib.sha256(body).hexdigest()[:32] + '"',
            "fingerprint": fingerprint,
            "limit": limit,
        }
        state._runs_response_cache = entry
        return entry


def _list_runs(state: UiState) -> List[JsonDict]:
    """List Realm runs in production; retain isolated legacy-fixture support."""

    if state.realm_runtime is not None:
        return _realm_runs_payload(state)["runs"]
    # Authoring-only test states deliberately do not open a Realm.  Keeping
    # their old fixture helper here avoids turning every unrelated Studio unit
    # test into a global-authority test.  The production HTTP route never
    # calls this branch: it invokes ``_realm_runs_payload`` directly.
    run_dirs = _find_run_dirs(state.run_roots)
    return [
        _run_summary(path, state)
        for path in sorted(run_dirs, key=_path_mtime, reverse=True)
    ]


def _candidate_resolution_payload(
    *,
    run_id: str,
    candidate_id: str,
    head: Mapping[str, Any],
    retention_state: str,
    candidate: Optional[JsonDict],
    shortlist: Any,
) -> JsonDict:
    """Describe a Run-local Candidate lookup without minting new authority."""

    shortlist_card = next(
        (
            card.to_dict()
            for card in (() if shortlist is None else shortlist.cards)
            if card.candidate_id == candidate_id
        ),
        None,
    )
    if candidate is not None and retention_state == "retired":
        status = "retired"
        source = "run_head"
        message = (
            "This Run's stored data was retired. Candidate result metadata "
            "remains available, but inputs needed to run it may have been released."
        )
        if shortlist_card is not None:
            message += " Its saved Shortlist snapshot remains available."
    elif candidate is not None:
        status = "available"
        source = "run_head"
        message = "Opened from this Run's saved results."
    elif shortlist_card is not None:
        status = "saved_only"
        source = "shortlist"
        message = (
            "This Candidate is no longer present at the current Run head. "
            "Its saved Shortlist snapshot remains available."
        )
    else:
        status = "not_found"
        source = "none"
        message = (
            "This Candidate was not found in this Run or its Shortlist. "
            "The copied address may be outdated or incorrect."
        )
    return {
        "schema": RUN_CANDIDATE_RESOLUTION_SCHEMA,
        "run_id": run_id,
        "candidate_id": candidate_id,
        "head": dict(head),
        "status": status,
        "source": source,
        "message": message,
        "candidate": candidate,
        "shortlist_card": shortlist_card,
    }


def _public_run_lineage(
    state: UiState, *, run_id: str, snapshot: Any
) -> JsonDict:
    """Project ordinary Study origin and durable Studio re-evaluation links."""

    metadata = (
        snapshot.definition.metadata
        if isinstance(snapshot.definition.metadata, Mapping)
        else {}
    )
    child_metadata = (
        metadata.get("child_run")
        if isinstance(metadata.get("child_run"), Mapping)
        else None
    )
    actions = state.coordination.list_actions(
        actor_id=_studio_actor_id(state),
        action_kind="exact-reevaluation",
        state=ActionState.SUCCEEDED,
        limit=200,
    )
    originating_action = next(
        (
            action
            for action in actions
            if action.result is not None
            and action.result.kind == "run"
            and action.result.entity_id == run_id
        ),
        None,
    )
    parent_run_id = ""
    candidate_id = ""
    if child_metadata is not None:
        parent_run_id = str(child_metadata.get("parent_run_id") or "")
    if originating_action is not None:
        parent_run_id = str(
            originating_action.parameters.get("run_id") or parent_run_id
        )
        if originating_action.source.kind == "candidate":
            candidate_id = originating_action.source.entity_id

    children = []
    for action in actions:
        if (
            action.result is None
            or action.result.kind != "run"
            or str(action.parameters.get("run_id") or "") != run_id
        ):
            continue
        children.append(
            {
                "run_id": action.result.entity_id,
                "candidate_id": (
                    action.source.entity_id
                    if action.source.kind == "candidate"
                    else ""
                ),
            }
        )
    children.sort(
        key=lambda item: (
            str(item["candidate_id"]).encode("utf-8"),
            str(item["run_id"]).encode("utf-8"),
        )
    )
    study_name = str(
        metadata.get("name")
        or metadata.get("study_name")
        or metadata.get("title")
        or ""
    )
    return {
        "schema": "optpilot.run-lineage-summary.v1",
        "run_id": run_id,
        "origin": (
            {
                "kind": "exact-reevaluation",
                "parent_run_id": parent_run_id,
                "candidate_id": candidate_id,
            }
            if parent_run_id
            else {"kind": "study", "study_name": study_name}
        ),
        "re_evaluation_runs": children,
        "truncated": len(actions) >= 200,
    }


def _realm_run_detail(
    state: UiState,
    *,
    ref: RunViewRef,
    focused_candidate_id: Optional[str] = None,
) -> JsonDict:
    runtime = _require_realm_runtime(state)
    bundle = runtime.run_views.workbench_bundle(
        ref=ref,
        limit=RUN_WORKBENCH_DEFAULT_PAGE_SIZE,
    )
    head = bundle.head
    selected_head = head.head
    focused_candidate = None
    if focused_candidate_id is not None:
        focused_candidate = bundle.entity_row(
            kind="candidate",
            entity_id=focused_candidate_id,
        )
    presentation_selections = _workbench_capability_selections(
        bundle.pages.values()
    )
    if focused_candidate is not None:
        focus_selection = focused_candidate.get("selection")
        if not isinstance(focus_selection, Mapping):
            raise ValueError("Focused Candidate is missing its presentation selection.")
        known_selection_ids = {
            str(selection.get("selection_id") or "")
            for selection in presentation_selections
        }
        if focus_selection.get("selection_id") not in known_selection_ids:
            presentation_selections.append(focus_selection)
    capability_facts = runtime.run_views.workbench_capability_batch(
        ref=ref,
        presentation_selections=presentation_selections,
        bundle=bundle,
    )
    child_run_preparations, child_run_preparation_reason = _child_run_preparation_batch(
        state,
        capability_facts=capability_facts.values(),
        snapshot=bundle.snapshot,
    )
    pages = {
        kind: _enrich_workbench_page(
            state,
            dict(bundle.pages[kind]),
            capability_facts=capability_facts,
            child_run_preparations=child_run_preparations,
            child_run_preparation_reason=child_run_preparation_reason,
        )
        for kind in RUN_WORKBENCH_KINDS
    }
    if focused_candidate is not None:
        focused_candidate = _enrich_workbench_page(
            state,
            {
                "run_id": ref.run_id,
                "capabilities": deepcopy(bundle.pages["candidate"]["capabilities"]),
                "items": [focused_candidate],
            },
            capability_facts=capability_facts,
            child_run_preparations=child_run_preparations,
            child_run_preparation_reason=child_run_preparation_reason,
        )["items"][0]
    timeline = runtime.run_views.timeline_page(
        ref=ref,
        expected_run_revision=selected_head["revision"],
        expected_head_sequence=selected_head["sequence"],
        limit=50,
    ).to_dict()
    summary = head.summary.to_dict()
    shortlist_service = getattr(runtime, "shortlists", None)
    review_service = getattr(runtime, "review_collections", None)
    shortlist = (
        None
        if shortlist_service is None
        else shortlist_service.read_for_run(run_id=ref.run_id)
    )
    review_collection_history = (
        None
        if review_service is None
        else review_service.history_for_run(run_id=ref.run_id)
    )
    candidate_resolution = (
        None
        if focused_candidate_id is None
        else _candidate_resolution_payload(
            run_id=ref.run_id,
            candidate_id=focused_candidate_id,
            head=selected_head,
            retention_state=str(summary.get("retention_state") or "active"),
            candidate=focused_candidate,
            shortlist=shortlist,
        )
    )
    return {
        "run": _realm_compat_run_row(
            state,
            summary,
            overview=head.overview.to_dict(),
        ),
        "workbench": _enrich_workbench_head(state, head.to_dict()),
        "pages": pages,
        "timeline": timeline,
        "shortlist": None if shortlist is None else shortlist.to_dict(),
        "review_collection_history": (
            _public_shortlist_history(review_collection_history)
        ),
        "candidate_resolution": candidate_resolution,
        "lineage": _public_run_lineage(
            state, run_id=ref.run_id, snapshot=bundle.snapshot
        ),
        "operator_jobs": _realm_operator_jobs_payload(
            state,
            run_id=ref.run_id,
            limit=OPERATOR_JOB_PUBLIC_DEFAULT_LIST_SIZE,
        ),
    }


def _realm_run_comparison_record(state: UiState, *, run_id: str) -> JsonDict:
    runtime = _require_realm_runtime(state)
    head = runtime.run_views.workbench_head(ref=RunViewRef(run_id=run_id))
    summary = head.summary.to_dict()
    return {
        "run": _realm_compat_run_row(
            state,
            summary,
            overview=head.overview.to_dict(),
        ),
        "workbench": _enrich_workbench_head(state, head.to_dict()),
    }


def _run_summary(run_dir: Path, state: Optional[UiState] = None) -> JsonDict:
    summary = _read_json(run_dir / "summary.json")
    study_spec = _read_json(run_dir / "study_spec.json")
    observations = _read_jsonl(run_dir / "observations.jsonl")
    status_counts = _status_counts(observations)
    _ = state
    status = _run_status(summary, None)
    objective = study_spec.get("objective", {}).get("primaryMetric", {})
    return {
        "id": _encode_id(run_dir),
        "path": str(run_dir),
        "name": study_spec.get("metadata", {}).get("name") or run_dir.name,
        "status": status,
        "summary_schema_version": summary.get("schema_version", "legacy"),
        "run_status": summary.get(
            "run_status", "legacy_completed" if summary else "incomplete"
        ),
        "stop_code": summary.get("stop_code"),
        "completed_trials": summary.get("completed_trials", len(observations)),
        "accepted_trials": summary.get(
            "accepted_trials", summary.get("completed_trials", len(observations))
        ),
        "terminal_trials": summary.get(
            "terminal_trials", summary.get("completed_trials", len(observations))
        ),
        "attempt_count": summary.get("attempt_count", len(observations)),
        "observation_count": summary.get("observation_count", len(observations)),
        "best_metric": summary.get("best_metric"),
        "best_trial_id": summary.get("best_trial_id"),
        "best_candidate_id": summary.get("best_candidate_id"),
        "failure_count": summary.get("failure_count", _failure_count(status_counts)),
        "final_failure_count": summary.get(
            "final_failure_count",
            summary.get("failure_count", _failure_count(status_counts)),
        ),
        "objective": objective,
        "environment_id": study_spec.get("environment", {}).get("environmentId"),
        "method": _method_summary(study_spec),
        "started_at": summary.get("started_at"),
        "finished_at": summary.get("finished_at"),
        "updated_at": _path_mtime(run_dir),
        "status_counts": status_counts,
        "job": None,
    }


def _run_detail(run_dir: Path, state: Optional[UiState] = None) -> JsonDict:
    observations = _read_jsonl(run_dir / "observations.jsonl")
    trials = _read_jsonl(run_dir / "trials.jsonl")
    candidates = _read_jsonl(run_dir / "candidates.jsonl")
    return {
        "run": _run_summary(run_dir, state),
        "summary": _read_json(run_dir / "summary.json"),
        "study_spec": _read_json(run_dir / "study_spec.json"),
        "run_policy": _read_json(run_dir / "run_policy.json"),
        "run_lineage": _read_json(run_dir / "run_lineage.json"),
        "environment_snapshot": _read_json(run_dir / "environment_snapshot.json"),
        "observations": observations,
        "trials": trials,
        "candidates": candidates,
        "method_calls": _read_jsonl(run_dir / "method_calls.jsonl"),
        "method_events": _read_jsonl(run_dir / "method_events.jsonl"),
        "controller_events": _read_jsonl(run_dir / "controller_events.jsonl"),
        "scheduler_events": _read_jsonl(run_dir / "scheduler_events.jsonl"),
        "files": _list_run_files(run_dir),
    }


def _assistant_run_detail(run_dir: Path, state: Optional[UiState] = None) -> JsonDict:
    summary = _read_json(run_dir / "summary.json")
    study_spec = _read_json(run_dir / "study_spec.json")
    observations = _read_jsonl(run_dir / "observations.jsonl")
    trials = _read_jsonl(run_dir / "trials.jsonl")
    candidates = _read_jsonl(run_dir / "candidates.jsonl")
    controller_events = _read_jsonl(run_dir / "controller_events.jsonl")
    run = _run_summary(run_dir, state)
    evidence_files = _run_evidence_files(run_dir, observations)
    best_candidate_id = run.get("best_candidate_id") or summary.get("best_candidate_id")
    best_trial_id = run.get("best_trial_id") or summary.get("best_trial_id")
    best_observation = next(
        (
            observation
            for observation in reversed(observations)
            if (best_trial_id and observation.get("trial_id") == best_trial_id)
            or (
                best_candidate_id
                and observation.get("candidate_id") == best_candidate_id
            )
        ),
        {},
    )
    best_candidate = next(
        (
            candidate
            for candidate in reversed(candidates)
            if best_candidate_id and candidate.get("candidate_id") == best_candidate_id
        ),
        {},
    )
    return {
        "run": run,
        "summary": {
            "status": run.get("status"),
            "run_status": run.get("run_status"),
            "stop_code": run.get("stop_code"),
            "completed_trials": run.get("completed_trials"),
            "accepted_trials": run.get("accepted_trials"),
            "terminal_trials": run.get("terminal_trials"),
            "attempt_count": run.get("attempt_count"),
            "observation_count": run.get("observation_count"),
            "failure_count": run.get("failure_count"),
            "final_failure_count": run.get("final_failure_count"),
            "best_metric": run.get("best_metric"),
            "best_trial_id": best_trial_id,
            "best_candidate_id": best_candidate_id,
            "started_at": summary.get("started_at") or run.get("started_at"),
            "finished_at": summary.get("finished_at") or run.get("finished_at"),
        },
        "study": {
            "name": study_spec.get("metadata", {}).get("name") or run.get("name"),
            "environment_id": run.get("environment_id"),
            "method": run.get("method"),
            "objective": run.get("objective"),
        },
        "observations": {
            "total": len(observations),
            "status_counts": _status_counts(observations),
            "metric_keys": _observation_metric_keys(observations),
            "preview": [
                _compact_observation(observation, run_dir)
                for observation in observations[:10]
            ],
        },
        "trials": {
            "total": len(trials),
            "preview": [_compact_trial(trial) for trial in trials[:10]],
        },
        "controller": {
            "event_count": len(controller_events),
            "recent_events": controller_events[-10:],
        },
        "best": {
            "metric": run.get("best_metric"),
            "trial_id": best_trial_id,
            "candidate_id": best_candidate_id,
            "observation": _compact_observation(best_observation, run_dir)
            if best_observation
            else {},
            "candidate": _compact_candidate(best_candidate, run_dir)
            if best_candidate
            else {},
        },
        "evidence_files": evidence_files,
        "tool_guidance": [
            "Canonical Realm runs are inspected through bounded Workbench pages and immutable selections.",
            "Runs open directly as recorded evidence; they are not filesystem workspaces.",
        ],
    }


def _observation_metric_keys(observations: List[JsonDict]) -> List[str]:
    keys: set[str] = set()
    for observation in observations:
        metrics = (
            observation.get("metric_values", {})
            if isinstance(observation.get("metric_values"), dict)
            else {}
        )
        keys.update(str(key) for key in metrics.keys())
    return sorted(keys)


def _compact_observation(observation: JsonDict, run_dir: Path) -> JsonDict:
    if not observation:
        return {}
    output_files = (
        observation.get("output_files", [])
        if isinstance(observation.get("output_files"), list)
        else []
    )
    return {
        "trial_id": observation.get("trial_id"),
        "candidate_id": observation.get("candidate_id"),
        "status": observation.get("status"),
        "metric_values": observation.get("metric_values", {}),
        "constraint_results": observation.get("constraint_results", {}),
        "event_summary": observation.get("event_summary", {}),
        "resource_usage": observation.get("resource_usage", {}),
        "output_files": [
            _compact_run_output_file(item, run_dir)
            for item in output_files[:20]
            if isinstance(item, dict)
        ],
        "error": observation.get("error") or observation.get("failure_reason"),
    }


def _compact_trial(trial: JsonDict) -> JsonDict:
    if not trial:
        return {}
    return {
        "trial_id": trial.get("trial_id"),
        "candidate_id": trial.get("candidate_id"),
        "status": trial.get("status"),
        "method_id": trial.get("method_id"),
        "created_at": trial.get("created_at"),
        "error": trial.get("error") or trial.get("failure_reason"),
    }


def _compact_candidate(candidate: JsonDict, run_dir: Path) -> JsonDict:
    if not candidate:
        return {}
    output_files = []
    generator = (
        candidate.get("generator", {})
        if isinstance(candidate.get("generator"), dict)
        else {}
    )
    materialization = (
        candidate.get("materialization", {})
        if isinstance(candidate.get("materialization"), dict)
        else {}
    )
    if isinstance(materialization.get("output_files"), list):
        output_files = [
            _compact_run_output_file(item, run_dir)
            for item in materialization["output_files"][:20]
            if isinstance(item, dict)
        ]
    return {
        "candidate_id": candidate.get("candidate_id"),
        "method_id": candidate.get("method_id") or generator.get("method_id"),
        "format": candidate.get("format"),
        "created_at": candidate.get("created_at"),
        "status": candidate.get("status"),
        "output_files": output_files,
    }


def _compact_run_output_file(item: JsonDict, run_dir: Path) -> JsonDict:
    path = str(item.get("path") or item.get("relative_path") or "")
    relative = _run_relative_path(path, run_dir) if path else ""
    return {
        "name": item.get("name") or Path(relative or path).name,
        "type": item.get("type") or Path(relative or path).suffix.lstrip("."),
        "relative_path": relative,
    }


def _run_evidence_files(
    run_dir: Path, observations: Optional[List[JsonDict]] = None
) -> List[JsonDict]:
    observations = (
        observations
        if observations is not None
        else _read_jsonl(run_dir / "observations.jsonl")
    )
    files_by_path = {item["relative_path"]: item for item in _list_run_files(run_dir)}
    evidence: Dict[str, JsonDict] = {}
    canonical = [
        (
            "summary.json",
            "run summary: status, trial counts, and best successful observation",
        ),
        (
            "observations.jsonl",
            "per-trial evaluation results, metric values, output files, and failures",
        ),
        ("trials.jsonl", "trial scheduler records and candidate assignments"),
        ("candidates.jsonl", "candidate metadata and materialization details"),
        ("method_calls.jsonl", "method invocation trace"),
        ("method_events.jsonl", "method-side events and logs"),
        (
            "controller_events.jsonl",
            "proposal, logical-trial, stop, and terminal transitions",
        ),
        ("scheduler_events.jsonl", "scheduler and execution events"),
        ("run_policy.json", "execution, evidence, sandbox, and reproducibility policy"),
        ("study_spec.json", "compiled study configuration used for this run"),
        ("environment_snapshot.json", "environment configuration snapshot"),
        ("run_lineage.json", "run lineage and reproducibility metadata"),
    ]
    for relative_path, purpose in canonical:
        file_info = files_by_path.get(relative_path)
        if file_info:
            evidence[relative_path] = {
                **file_info,
                "purpose": purpose,
                "recommended": True,
            }
    for observation in observations:
        output_files = (
            observation.get("output_files", [])
            if isinstance(observation.get("output_files"), list)
            else []
        )
        for output in output_files:
            if not isinstance(output, dict):
                continue
            relative_path = _run_relative_path(
                str(output.get("path") or output.get("relative_path") or ""), run_dir
            )
            if not relative_path or relative_path not in files_by_path:
                continue
            evidence.setdefault(
                relative_path,
                {
                    **files_by_path[relative_path],
                    "purpose": f"trial output: {output.get('name') or Path(relative_path).name}",
                    "recommended": False,
                },
            )
    return sorted(
        evidence.values(),
        key=lambda item: (not item.get("recommended"), item.get("relative_path", "")),
    )[:120]


def _run_relative_path(path_value: str, run_dir: Path) -> str:
    if not path_value:
        return ""
    path = Path(path_value).expanduser()
    if not path.is_absolute():
        path = run_dir / path
    try:
        resolved = path.resolve()
    except OSError:
        return path_value
    if not _is_relative_to(resolved, run_dir.resolve()):
        return path_value
    return str(resolved.relative_to(run_dir.resolve()))


def _study_launch_capability(validation: Mapping[str, Any]) -> JsonDict:
    launch = validation.get("launch")
    if isinstance(launch, Mapping):
        return dict(launch)
    capabilities = validation.get("capabilities")
    if isinstance(capabilities, Mapping):
        retained = capabilities.get("retained_execution")
        if isinstance(retained, Mapping):
            return {
                "eligible": retained.get("eligible") is True,
                "code": str(retained.get("code") or "retained_execution_unsupported"),
                "reason": retained.get("reason"),
            }
    return {
        "eligible": False,
        "code": "retained_preflight_missing",
        "reason": "The study has no retained execution preflight result.",
    }


def _declared_study_inputs(validation: Mapping[str, Any]) -> JsonDict:
    """The study's declared per-launch input map, or an empty map."""

    declared = validation.get("inputs")
    return dict(declared) if isinstance(declared, Mapping) else {}


def _unbound_required_study_inputs(
    validation: Mapping[str, Any],
    launch_inputs: Optional[Mapping[str, Any]],
) -> List[str]:
    """Declared inputs that have no default and no supplied launch value.

    Delegates to core's ``missing_required_parameters`` so this predictive
    check cannot drift from the rule the compiler actually enforces. This is
    a UX affordance only — it lets a caller collect the values before
    launching. Core re-checks unconditionally and remains authoritative.
    """

    return missing_required_parameters(
        launch_inputs if isinstance(launch_inputs, Mapping) else {},
        _declared_study_inputs(validation),
    )


def _study_launch_block_remedy(blocked: Mapping[str, Any]) -> JsonDict:
    """What would actually unblock this launch, by why it was blocked.

    The two common reasons need opposite responses, and telling them apart
    from the sentence alone is exactly what the Assistant used to get wrong:
    missing values are something only the person can supply, while a study
    that does not validate is something to go and fix.
    """

    code = str(blocked.get("code") or "")
    if code == "study_inputs_required":
        missing = [str(name) for name in blocked.get("missing_inputs", []) or []]
        return _remedy(
            "This run setup asks the person for "
            f"{', '.join(missing) or 'values'} before it can start. Ask them "
            "for the values -- never invent them -- then call this tool again "
            "with them in `inputs`.",
            tool="optpilot_study_launch",
            arguments={"inputs": {name: "<ask the person>" for name in missing}},
            details={
                "missing_inputs": missing,
                "input_declarations": deepcopy(
                    dict(blocked.get("input_declarations") or {})
                ),
            },
        )
    if code == "study_invalid":
        return _remedy(
            "The run setup does not validate, so fix what it reports before "
            "launching. Read the errors in `validation`, repair the config "
            "they name, then check it with optpilot_config_validate.",
            tool="optpilot_config_validate",
            details={"code": code},
        )
    return _remedy(
        str(blocked.get("reason") or "This launch cannot start as requested."),
        details={"code": code or "unknown"},
    )


def _study_launch_block(
    validation: Mapping[str, Any],
    *,
    launch_inputs: Optional[Mapping[str, Any]] = None,
) -> Optional[JsonDict]:
    if validation.get("valid") is not True:
        errors = [str(item) for item in validation.get("errors", []) or [] if str(item)]
        return {
            "eligible": False,
            "code": "study_invalid",
            "reason": errors[0] if errors else "Study validation failed.",
        }
    launch = _study_launch_capability(validation)
    if launch.get("eligible") is not True:
        return launch
    missing = _unbound_required_study_inputs(validation, launch_inputs)
    if missing:
        declared = _declared_study_inputs(validation)
        return {
            "eligible": False,
            "code": "study_inputs_required",
            "reason": (
                "This run setup needs a value for "
                f"{', '.join(missing)} before it can launch."
            ),
            "missing_inputs": missing,
            "input_declarations": {
                name: deepcopy(declared[name]) for name in missing
            },
        }
    return None


def _require_study_launchable(
    validation: Mapping[str, Any],
    *,
    launch_inputs: Optional[Mapping[str, Any]] = None,
) -> None:
    blocked = _study_launch_block(validation, launch_inputs=launch_inputs)
    if blocked is None:
        return
    code = str(blocked.get("code") or "retained_execution_unsupported")
    reason = str(blocked.get("reason") or "The study is not launchable.")
    # The message keeps its established format; the code rides along so the
    # launch response reports it in `code` instead of a generic rejection.
    raise CodedConfigError(code, f"Study launch blocked ({code}): {reason}")


def _canonical_method_request_timeout_seconds(value: Any) -> float:
    if (
        isinstance(value, bool)
        or not isinstance(value, (int, float))
        or not math.isfinite(float(value))
        or float(value) <= 0.0
        or float(value) > MAX_RUN_EXECUTION_CONTROL_SECONDS
    ):
        raise ValueError(
            "method_request_timeout_seconds must be a positive finite number "
            f"no greater than {MAX_RUN_EXECUTION_CONTROL_SECONDS:g}."
        )
    return float(value)


def _canonical_study_launch_request(payload: Any) -> Mapping[str, Any]:
    """Validate one exact browser-owned Study launch request."""

    if not isinstance(payload, Mapping):
        raise ValueError("Study launch request must be a JSON object.")
    schema = payload.get("schema")
    if schema != STUDY_LAUNCH_REQUEST_SCHEMA:
        raise ValueError("Study launch request schema is unsupported.")
    request_id = _canonical_request_uuid(payload.get("request_id"))
    has_method_timeout = "method_request_timeout_seconds" in payload
    method_timeout = (
        _canonical_method_request_timeout_seconds(
            payload["method_request_timeout_seconds"]
        )
        if has_method_timeout
        else None
    )
    has_inputs = "inputs" in payload
    launch_inputs = (
        _canonical_study_launch_inputs(payload["inputs"]) if has_inputs else None
    )
    common = (
        {"schema", "request_id"}
        | ({"method_request_timeout_seconds"} if has_method_timeout else set())
        | ({"inputs"} if has_inputs else set())
    )
    if "study_ref" in payload:
        _exact_json_object(
            payload,
            expected=common | {"study_ref"},
            label="Catalog Study launch request",
        )
        if not isinstance(payload["study_ref"], Mapping):
            raise ValueError("study_ref must be one exact Catalog reference.")
        result = {
            "schema": STUDY_LAUNCH_REQUEST_SCHEMA,
            "request_id": request_id,
            "study_ref": dict(payload["study_ref"]),
        }
        if method_timeout is not None:
            result["method_request_timeout_seconds"] = method_timeout
        if launch_inputs is not None:
            result["inputs"] = launch_inputs
        return result
    if "workspace_id" in payload:
        _exact_json_object(
            payload,
            expected=common
            | {
                "workspace_id",
                "study_relative_path",
                "expected_workspace_revision",
            },
            label="Workspace Study launch request",
        )
        workspace_id = str(payload["workspace_id"] or "").strip()
        if not workspace_id:
            raise ValueError("workspace_id must be nonempty text.")
        relative = _portable_relative_path(
            payload["study_relative_path"], "study_relative_path"
        )
        revision = payload["expected_workspace_revision"]
        if isinstance(revision, bool) or not isinstance(revision, int) or revision <= 0:
            raise ValueError("expected_workspace_revision must be a positive integer.")
        result = {
            "schema": STUDY_LAUNCH_REQUEST_SCHEMA,
            "request_id": request_id,
            "workspace_id": workspace_id,
            "study_relative_path": relative,
            "expected_workspace_revision": revision,
        }
        if method_timeout is not None:
            result["method_request_timeout_seconds"] = method_timeout
        if launch_inputs is not None:
            result["inputs"] = launch_inputs
        return result
    if "study_path" in payload:
        _exact_json_object(
            payload,
            expected=common | {"study_path"},
            label="Configured Study launch request",
        )
        study_path = str(payload["study_path"] or "").strip()
        if not study_path:
            raise ValueError("study_path must be nonempty text.")
        result = {
            "schema": STUDY_LAUNCH_REQUEST_SCHEMA,
            "request_id": request_id,
            "study_path": study_path,
        }
        if method_timeout is not None:
            result["method_request_timeout_seconds"] = method_timeout
        if launch_inputs is not None:
            result["inputs"] = launch_inputs
        return result
    raise ValueError(
        "Study launch request must name exactly one of study_ref, workspace_id, or study_path."
    )


_MAX_STUDY_LAUNCH_INPUT_KEYS = 64


def _canonical_study_launch_inputs(value: Any) -> Dict[str, Any]:
    """Bound one browser-supplied launch-input mapping.

    Typed validation against the study's declared inputs stays in core
    (``compile_authoring_config``); this only constrains the transport shape.
    """

    if not isinstance(value, Mapping):
        raise ValueError("Study launch inputs must be a JSON object.")
    if len(value) > _MAX_STUDY_LAUNCH_INPUT_KEYS:
        raise ValueError(
            "Study launch inputs exceed "
            f"{_MAX_STUDY_LAUNCH_INPUT_KEYS} keys."
        )
    result: Dict[str, Any] = {}
    for key, item in value.items():
        if not isinstance(key, str) or not key or len(key.encode("utf-8")) > 128:
            raise ValueError("Study launch input names must be short strings.")
        result[key] = item
    return result


_MAX_STUDY_LAUNCH_INPUT_DISPLAY_CHARS = 400


def _study_launch_input_display(launch_inputs: Mapping[str, Any]) -> List[str]:
    """Render bound launch-input values for one approval card.

    Launch inputs are the problem payload and are retained inside the run
    definition digest, so the approver must see the values that will actually
    run rather than only the input names. Long values are elided with an
    explicit marker; the untruncated mapping stays in the approval's recorded
    arguments.
    """

    rendered: List[str] = []
    for name in sorted(launch_inputs):
        value = launch_inputs[name]
        text = (
            value
            if isinstance(value, str)
            else json.dumps(value, sort_keys=True, default=str)
        )
        if len(text) > _MAX_STUDY_LAUNCH_INPUT_DISPLAY_CHARS:
            hidden = len(text) - _MAX_STUDY_LAUNCH_INPUT_DISPLAY_CHARS
            text = (
                f"{text[:_MAX_STUDY_LAUNCH_INPUT_DISPLAY_CHARS]}… "
                f"(+{hidden} more characters)"
            )
        rendered.append(f"{name}={text}")
    return rendered


def _study_launch_intent_source(request: Mapping[str, Any]) -> EntityCoordinate:
    source_digest = request_digest(
        {
            "request": dict(request),
            "schema": "optpilot.studio-study-launch-source.v1",
        }
    )
    if "workspace_id" in request:
        return EntityCoordinate(
            kind="workspace",
            entity_id=str(request["workspace_id"]),
            revision=int(request["expected_workspace_revision"]),
            digest=source_digest,
        )
    return EntityCoordinate(
        kind="study",
        entity_id=f"study-source-{source_digest[:32]}",
        digest=source_digest,
    )


def _begin_study_launch_intent(
    state: UiState, request: Mapping[str, Any]
) -> ActionIntentRecord:
    request_id = str(request["request_id"])
    source = _study_launch_intent_source(request)
    parameters = dict(request)
    core_operation_id = f"studio/study-launch/{request_id}"
    expected_digest = ActionIntentRecord.compute_intent_digest(
        intent_id=request_id,
        actor_id=_studio_actor_id(state),
        action_kind="study-launch",
        source=source,
        parameters=parameters,
    )
    try:
        current = state.coordination.get_action(request_id)
    except CoordinationNotFound:
        current = None
    if current is not None:
        if current.intent_digest != expected_digest:
            raise CoordinationConflict(
                "Study launch request_id was already used for another request."
            )
        if current.state is ActionState.UNCERTAIN:
            return state.coordination.retry_action(
                operation_id=(
                    f"studio/study-launch-intent/{request_id}/retry/{current.revision}"
                ),
                intent_id=request_id,
            )
        return current
    return state.coordination.begin_action(
        operation_id=f"studio/study-launch-intent/{request_id}/begin",
        intent_id=request_id,
        actor_id=_studio_actor_id(state),
        action_kind="study-launch",
        source=source,
        parameters=parameters,
        core_operation_id=core_operation_id,
    )


def _study_launch_failure_response(intent: ActionIntentRecord) -> JsonDict:
    return {
        "schema": STUDY_LAUNCH_RESPONSE_SCHEMA,
        "request_id": intent.intent_id,
        "code": intent.error_code or "study_launch_failed",
        "error": intent.error_message or "Study launch failed.",
        "launch": None,
    }


def _public_study_launch(view: StudyLaunchView) -> JsonDict:
    public = view.to_dict()
    job = view.job
    stage_by_state = {
        OperatorJobState.PLANNED: "Checking Study",
        OperatorJobState.AWAITING_APPROVAL: "Checking Study",
        OperatorJobState.QUEUED: "Queued",
        OperatorJobState.STARTING: "Preparing Run",
        OperatorJobState.RUNNING: "Run created",
        OperatorJobState.STOPPING: "Stopping",
        OperatorJobState.SUCCEEDED: "Run created" if view.run_id else "Prepared",
        OperatorJobState.FAILED: "Preparation failed",
        OperatorJobState.CANCELLED: "Stopped",
    }
    finished_at = None if job.outcome is None else job.outcome.created_at
    elapsed_until = finished_at if finished_at is not None else time.time()
    failure = None
    if job.state is OperatorJobState.FAILED:
        code = (
            None if job.outcome is None else str(job.outcome.outcome.code or "")
        ) or "study_launch_failed"
        message = "OptPilot could not prepare this Run. Review the Study and try again."
        if job.result is not None:
            details = job.result.result.details
            if isinstance(details, Mapping):
                detail_message = details.get("message") or details.get("error")
                if isinstance(detail_message, str) and detail_message.strip():
                    message = detail_message.strip()
        failure = {"code": code, "message": message}
    log_summary = []
    if job.result is not None:
        log_summary = [
            {
                "stream": item.stream,
                "byte_count": item.byte_count,
                "line_count": item.line_count,
                "truncated": item.truncated,
            }
            for item in job.result.result.logs
        ]
    return {
        **public,
        "schema": STUDY_LAUNCH_STATUS_SCHEMA,
        "stage": stage_by_state[job.state],
        "updated_at": job.updated_at,
        "elapsed_seconds": round(max(0.0, elapsed_until - job.created_at), 3),
        "failure": failure,
        "log_summary": log_summary,
    }


def _study_launch_response(
    view: StudyLaunchView, *, request_id: Optional[str] = None
) -> JsonDict:
    return {
        "schema": STUDY_LAUNCH_RESPONSE_SCHEMA,
        "request_id": request_id,
        "launch": _public_study_launch(view),
    }


def _complete_study_launch_intent(
    state: UiState, intent: ActionIntentRecord, view: StudyLaunchView
) -> ActionIntentRecord:
    return state.coordination.complete_action(
        operation_id=f"studio/study-launch-intent/{intent.intent_id}/complete",
        intent_id=intent.intent_id,
        result=EntityCoordinate(kind="study-launch", entity_id=view.launch_id),
        core_receipt={
            "schema": "optpilot.studio-study-launch-receipt.v1",
            "launch_id": view.launch_id,
        },
    )


def _read_study_launch_for_intent(
    state: UiState, intent: ActionIntentRecord
) -> Optional[StudyLaunchView]:
    launch_id = (
        intent.result.entity_id
        if intent.result is not None and intent.result.kind == "study-launch"
        else study_launch_id_for_operation(intent.core_operation_id)
    )
    try:
        return _study_launch_service_for_state(state).read(launch_id=launch_id)
    except RealmNotFound:
        return None


def _study_launch_preparation_stage(intent: ActionIntentRecord) -> tuple[str, str]:
    """Return honest pre-Operator-Job wording for one durable launch intent."""

    parameters = intent.parameters
    if "workspace_id" in parameters:
        return (
            "Saving current Workspace",
            "OptPilot is saving the current Workspace and preparing exact Run inputs.",
        )
    if "study_ref" in parameters:
        return (
            "Preparing Catalog Study",
            "OptPilot is preparing the exact registered Study version for this Run.",
        )
    return (
        "Preparing Study files",
        "OptPilot is saving exact Study inputs and checking them for this Run.",
    )


def _study_launch_preparation_response(
    state: UiState,
    intent: ActionIntentRecord,
    *,
    launch: Optional[StudyLaunchView] = None,
) -> JsonDict:
    """Project a durable action intent without inventing another Job type."""

    if intent.actor_id != _studio_actor_id(state) or intent.action_kind != "study-launch":
        raise CoordinationNotFound("Study launch preparation was not found.")
    if launch is None and intent.state is ActionState.SUCCEEDED:
        launch = _read_study_launch_for_intent(state, intent)
        if launch is None:
            raise RealmIntegrityError(
                "Completed Study launch preparation names no retained launch."
            )
    now = time.time()
    stage, message = _study_launch_preparation_stage(intent)
    state_name = "preparing"
    failure = None
    if intent.state is ActionState.SUCCEEDED:
        state_name = "ready"
        stage = "Run preparation started"
        message = "Exact Run inputs are retained and the launch is ready to follow."
    elif intent.state is ActionState.FAILED:
        state_name = "failed"
        stage = "Preparation failed"
        message = intent.error_message or "OptPilot could not prepare this Run."
        failure = {
            "code": intent.error_code or "study_launch_failed",
            "message": message,
        }
    elif intent.state is ActionState.UNCERTAIN:
        state_name = "uncertain"
        stage = "Reconnecting to preparation"
        message = (
            intent.error_message
            or "The preparation outcome is being reconciled from its durable request."
        )
    return {
        "schema": STUDY_LAUNCH_PREPARATION_SCHEMA,
        "request_id": intent.intent_id,
        "state": state_name,
        "stage": stage,
        "message": message,
        "started_at": intent.created_at,
        "updated_at": intent.updated_at,
        "elapsed_seconds": round(max(0.0, now - intent.created_at), 3),
        "launch": None if launch is None else _public_study_launch(launch),
        "failure": failure,
    }


def _schedule_study_launch_preparation(
    state: UiState, intent: ActionIntentRecord
) -> bool:
    """Best-effort local dispatch for one durable pre-job launch action."""

    if intent.state is not ActionState.PENDING:
        return False
    if state._background_execution_closing.is_set():
        return False
    intent_id = intent.intent_id
    with state._lock:
        if state._background_execution_closing.is_set():
            return False
        existing = state._study_preparation_threads.get(intent_id)
        if existing is not None and existing.is_alive():
            return False

        def execute() -> None:
            try:
                _execute_study_launch_request(state, dict(intent.parameters))
            except Exception:
                # _execute_study_launch_request records an uncertain durable
                # outcome before propagating unexpected provider failures.
                # The exact request can then be retried after refresh/restart.
                pass
            finally:
                with state._lock:
                    if (
                        state._study_preparation_threads.get(intent_id)
                        is threading.current_thread()
                    ):
                        state._study_preparation_threads.pop(intent_id, None)

        thread = threading.Thread(
            target=execute,
            name=f"optpilot-study-preparation-{intent_id[:24]}",
            daemon=True,
        )
        state._study_preparation_threads[intent_id] = thread
        thread.start()
        return True


def _reconcile_visible_study_launch_preparations(state: UiState) -> None:
    """Resume pending/uncertain Study preparations after Studio restarts."""

    actor_id = _studio_actor_id(state)
    intents: Dict[str, ActionIntentRecord] = {}
    for action_state in (ActionState.PENDING, ActionState.UNCERTAIN):
        for intent in state.coordination.list_actions(
            actor_id=actor_id,
            action_kind="study-launch",
            state=action_state,
            limit=200,
        ):
            intents[intent.intent_id] = intent
    for intent in intents.values():
        try:
            current = intent
            if current.state is ActionState.UNCERTAIN:
                current = state.coordination.retry_action(
                    operation_id=(
                        f"studio/study-launch-intent/{current.intent_id}/"
                        f"startup-retry/{current.revision}"
                    ),
                    intent_id=current.intent_id,
                )
            _schedule_study_launch_preparation(state, current)
        except (CoordinationConflict, CoordinationNotFound):
            continue


def _study_launch_preparation_status(
    state: UiState, request_id: str
) -> JsonDict:
    request_id = _canonical_request_uuid(request_id)
    intent = state.coordination.get_action(request_id)
    if (
        intent.actor_id != _studio_actor_id(state)
        or intent.action_kind != "study-launch"
    ):
        raise CoordinationNotFound("Study launch preparation was not found.")
    launch = (
        _read_study_launch_for_intent(state, intent)
        if _study_launch_provider_available(state)
        else None
    )
    if launch is not None and intent.state is not ActionState.SUCCEEDED:
        intent = _complete_study_launch_intent(state, intent, launch)
    return _study_launch_preparation_response(state, intent, launch=launch)


def _submit_study_launch_request(
    state: UiState, payload: Any
) -> tuple[JsonDict, HTTPStatus]:
    """Persist one launch click and return before package preparation blocks."""

    request = _canonical_study_launch_request(payload)
    intent = _begin_study_launch_intent(state, request)
    if intent.state is ActionState.FAILED:
        return (
            _study_launch_preparation_response(state, intent),
            HTTPStatus.BAD_REQUEST,
        )
    launch = (
        _read_study_launch_for_intent(state, intent)
        if _study_launch_provider_available(state)
        else None
    )
    if launch is not None:
        if intent.state is not ActionState.SUCCEEDED:
            intent = _complete_study_launch_intent(state, intent, launch)
        return (
            _study_launch_preparation_response(state, intent, launch=launch),
            HTTPStatus.OK,
        )
    if intent.state is ActionState.SUCCEEDED:
        raise RealmIntegrityError(
            "Completed Study launch preparation names no retained launch."
        )
    _schedule_study_launch_preparation(state, intent)
    return (
        _study_launch_preparation_response(state, intent),
        HTTPStatus.ACCEPTED,
    )


def _execute_study_launch_request(
    state: UiState, payload: Any
) -> tuple[JsonDict, HTTPStatus]:
    request = _canonical_study_launch_request(payload)
    intent = _begin_study_launch_intent(state, request)
    if intent.state is ActionState.FAILED:
        return _study_launch_failure_response(intent), HTTPStatus.BAD_REQUEST

    if _study_launch_provider_available(state):
        recovered = _read_study_launch_for_intent(state, intent)
        if recovered is not None:
            if intent.state is not ActionState.SUCCEEDED:
                intent = _complete_study_launch_intent(state, intent, recovered)
            return (
                _study_launch_response(recovered, request_id=intent.intent_id),
                HTTPStatus.OK,
            )

    requested_launch_inputs = request.get("inputs")
    configured_study_path: Optional[Path] = None
    configured_validation: Optional[JsonDict] = None
    if "study_path" in request:
        configured_study_path = _resolve_user_path(request["study_path"], state.cwd)
        _configured_study_package_root(state, configured_study_path)
        configured_validation = _validate_study(
            configured_study_path, state=state
        )
        blocked = _study_launch_block(
            configured_validation, launch_inputs=requested_launch_inputs
        )
        if blocked is not None:
            code = str(blocked.get("code") or "study_invalid")
            message = str(
                blocked.get("reason")
                or "Study validation or launch preflight failed."
            )
            failed = state.coordination.fail_action(
                operation_id=f"studio/study-launch-intent/{intent.intent_id}/fail",
                intent_id=intent.intent_id,
                error_code=code,
                error_message=message,
            )
            return _study_launch_failure_response(failed), HTTPStatus.BAD_REQUEST

    try:
        method_request_timeout_seconds = request.get(
            "method_request_timeout_seconds"
        )
        launch_inputs = requested_launch_inputs
        if "workspace_id" in request:
            launched = state.launch_study(
                workspace_id=str(request["workspace_id"]),
                study_relative_path=str(request["study_relative_path"]),
                expected_workspace_revision=int(
                    request["expected_workspace_revision"]
                ),
                operation_id=intent.core_operation_id,
                method_request_timeout_seconds=method_request_timeout_seconds,
                launch_inputs=launch_inputs,
            )
        elif "study_ref" in request:
            launched = state.launch_study(
                catalog_entry=request["study_ref"],
                operation_id=intent.core_operation_id,
                method_request_timeout_seconds=method_request_timeout_seconds,
                launch_inputs=launch_inputs,
            )
        else:
            assert configured_study_path is not None
            assert configured_validation is not None
            launched = state.launch_study(
                configured_study_path,
                study_name=configured_validation.get("name"),
                environment_id=configured_validation.get("environment_id"),
                operation_id=intent.core_operation_id,
                method_request_timeout_seconds=method_request_timeout_seconds,
                launch_inputs=launch_inputs,
            )
    except ValueError as error:
        error_code = str(
            getattr(error, "code", None) or "study_launch_rejected"
        )
        failed = state.coordination.fail_action(
            operation_id=f"studio/study-launch-intent/{intent.intent_id}/fail",
            intent_id=intent.intent_id,
            error_code=error_code,
            error_message=str(error),
        )
        return _study_launch_failure_response(failed), HTTPStatus.BAD_REQUEST
    except (CoordinationConflict, RealmConflict):
        state.coordination.mark_action_uncertain(
            operation_id=(
                f"studio/study-launch-intent/{intent.intent_id}/uncertain/{intent.revision}"
            ),
            intent_id=intent.intent_id,
            message="Study launch outcome requires reconciliation.",
        )
        raise
    except Exception:
        state.coordination.mark_action_uncertain(
            operation_id=(
                f"studio/study-launch-intent/{intent.intent_id}/uncertain/{intent.revision}"
            ),
            intent_id=intent.intent_id,
            message="Study launch response was interrupted; retry the same request.",
        )
        raise

    completed = _complete_study_launch_intent(state, intent, launched)
    return (
        _study_launch_response(launched, request_id=completed.intent_id),
        HTTPStatus.CREATED,
    )


def _validate_study(
    study_path: Path, *, state: Optional[UiState] = None
) -> JsonDict:
    path = Path(study_path).expanduser().resolve()
    try:
        validation = validate_authoring_config(path)
        if not validation["valid"]:
            errors = [str(item) for item in validation.get("errors", []) or []]
            launch = {
                "eligible": False,
                "code": "study_invalid",
                "reason": errors[0] if errors else "Study validation failed.",
            }
            return {
                **validation,
                "path": str(path),
                "capabilities": {
                    "retained_execution": {
                        "supported": False,
                        **launch,
                        "verification": "static",
                    }
                },
                "launch": launch,
            }
        # Static validation must not bind launch inputs: a study whose
        # declared inputs have no defaults is valid and launchable — the
        # launch form supplies the values at launch time.
        compiled = compile_authoring_config(path, bind_launch_inputs=False)
        with path.open("r", encoding="utf-8") as handle:
            raw_study = yaml.safe_load(handle) or {}
        declared_inputs = (
            raw_study.get("inputs") if isinstance(raw_study, Mapping) else None
        )
        method = compiled.get("method")
        method_runtime = (
            method.get("runtime") if isinstance(method, Mapping) else None
        )
        raw_method_environment_names = (
            method_runtime.get("envFromHost")
            if isinstance(method_runtime, Mapping)
            else None
        )
        method_environment_names_declared = _dedupe_strings(
            raw_method_environment_names
            if isinstance(raw_method_environment_names, list)
            else []
        )
        if state is None:
            runtime_environment_requirements = [
                {
                    "name": name,
                    "component": "Method",
                    "configured": None,
                    "source": "unknown",
                }
                for name in method_environment_names_declared
            ]
        else:
            runtime_environment_requirements = _retained_method_environment_status(
                state, method_environment_names_declared
            )
        missing_environment_names = [
            str(item["name"])
            for item in runtime_environment_requirements
            if item.get("configured") is False
        ]
        runtime_environment = {
            "requirements": runtime_environment_requirements,
            "ready": not missing_environment_names,
            "missing_names": missing_environment_names,
        }
        try:
            preflight_retained_process_study(study_spec_from_raw(path, compiled))
            retained = {
                "supported": True,
                "eligible": True,
                "code": "ready",
                "reason": None,
                "verification": "static",
            }
        except RetainedStudyCompileError as exc:
            retained = {
                "supported": False,
                "eligible": False,
                "code": exc.code,
                "reason": str(exc),
                "verification": "static",
            }
        except (OSError, TypeError, ValueError) as exc:
            retained = {
                "supported": False,
                "eligible": False,
                "code": "retained_preflight_failed",
                "reason": str(exc),
                "verification": "static",
            }
        if retained["eligible"] and missing_environment_names:
            joined = ", ".join(missing_environment_names)
            launch = {
                "eligible": False,
                "code": "runtime_environment_missing",
                "reason": (
                    f"Add {joined} in Studio Settings before launching this Run."
                ),
            }
        else:
            launch = {
                "eligible": retained["eligible"],
                "code": retained["code"],
                "reason": retained["reason"],
            }
        return {
            "valid": True,
            "errors": [],
            "path": str(path),
            "name": compiled.get("metadata", {}).get("name"),
            "environment_id": compiled.get("environment", {}).get("environmentId"),
            "objective": compiled.get("objective", {}).get("primaryMetric", {}),
            "max_trials": compiled.get("stopping", {}).get("maxTrials"),
            "capabilities": {"retained_execution": retained},
            "runtime_environment": runtime_environment,
            "launch": launch,
            "inputs": (
                dict(declared_inputs)
                if isinstance(declared_inputs, Mapping)
                else None
            ),
        }
    except Exception as exc:
        launch = {
            "eligible": False,
            "code": "study_invalid",
            "reason": str(exc),
        }
        return {
            "valid": False,
            "errors": [str(exc)],
            "path": str(path),
            "capabilities": {
                "retained_execution": {
                    "supported": False,
                    **launch,
                    "verification": "static",
                }
            },
            "launch": launch,
        }


def _workspace_index_path(state: UiState) -> Path:
    return state.workspace_index_path


def _workspace_index_storage_unavailable(
    error: BaseException,
) -> CoordinationStorageUnavailable:
    return CoordinationStorageUnavailable(
        COORDINATION_STORAGE_UNAVAILABLE_MESSAGE
    )


def _workspace_index_payload(path: Path) -> JsonDict:
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise _workspace_index_storage_unavailable(error) from error
    if not isinstance(raw, dict) or not isinstance(raw.get("workspaces"), list):
        error = ValueError("Workspace index has an invalid structure.")
        raise _workspace_index_storage_unavailable(error) from error
    return raw


def _atomic_write_workspace_index_payload(
    path: Path,
    payload: JsonDict,
    *,
    replace_existing: bool = True,
) -> bool:
    tmp_path: Optional[Path] = None
    directory_fd: Optional[int] = None
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        with tempfile.NamedTemporaryFile(
            mode="w",
            dir=path.parent,
            prefix=f".{path.name}.",
            suffix=".tmp",
            encoding="utf-8",
            delete=False,
        ) as handle:
            tmp_path = Path(handle.name)
            handle.write(json.dumps(payload, indent=2, sort_keys=True) + "\n")
            handle.flush()
            os.fsync(handle.fileno())
        if replace_existing:
            os.replace(tmp_path, path)
            tmp_path = None
        else:
            try:
                os.link(tmp_path, path)
            except FileExistsError:
                return False
            tmp_path.unlink()
            tmp_path = None
        if os.name != "nt":
            directory_fd = os.open(
                path.parent,
                os.O_RDONLY
                | getattr(os, "O_DIRECTORY", 0)
                | getattr(os, "O_CLOEXEC", 0),
            )
            os.fsync(directory_fd)
        return True
    except (OSError, UnicodeError) as error:
        raise _workspace_index_storage_unavailable(error) from error
    finally:
        if directory_fd is not None:
            try:
                os.close(directory_fd)
            except OSError:
                pass
        if tmp_path is not None:
            try:
                tmp_path.unlink(missing_ok=True)
            except OSError:
                pass


def _prepare_workspace_index_storage(
    state: UiState, *, legacy_path: Path
) -> None:
    """Migrate one valid legacy index without modifying its source file."""

    target = state.workspace_index_path
    if target == legacy_path:
        return
    with state._workspace_index_lock:
        try:
            target_exists = target.exists()
            legacy_exists = legacy_path.exists()
        except OSError as error:
            raise _workspace_index_storage_unavailable(error) from error
        if target_exists or not legacy_exists:
            return
        payload = _workspace_index_payload(legacy_path)
        _atomic_write_workspace_index_payload(
            target,
            payload,
            replace_existing=False,
        )


def _studio_actor_id(state: UiState) -> str:
    runtime = state.realm_runtime
    return (
        str(runtime.actor_principal_id)
        if runtime is not None
        else "studio-local-author"
    )


def _inferred_workspace_purpose(workspace: Mapping[str, Any]) -> WorkspacePurpose:
    explicit = workspace.get("purpose")
    if explicit:
        return WorkspacePurpose(str(explicit))
    source_type = str(workspace.get("source_type") or "")
    mode = str(workspace.get("mode") or "editable")
    origin = workspace.get("catalog_origin")
    if isinstance(origin, Mapping) and origin.get("kind") == "study-builder":
        return WorkspacePurpose.STUDY_DRAFT_BACKING
    if source_type in {"catalog", "run", "study-plan"} or mode in {
        "read-only",
        "analysis",
    }:
        return WorkspacePurpose.READ_ONLY_SUPPORT
    return WorkspacePurpose.USER_PROJECT


def _inferred_workspace_purpose_subject(
    workspace: Mapping[str, Any], purpose: WorkspacePurpose
) -> Optional[EntityCoordinate]:
    raw = workspace.get("purpose_subject")
    if isinstance(raw, Mapping):
        return EntityCoordinate.from_dict(raw)
    origin = workspace.get("catalog_origin")
    if (
        purpose is WorkspacePurpose.STUDY_DRAFT_BACKING
        and isinstance(origin, Mapping)
        and origin.get("draft_id")
    ):
        return EntityCoordinate(
            kind="study-draft", entity_id=str(origin["draft_id"])
        )
    return None


def _set_workspace_purpose(
    state: UiState,
    workspace: Mapping[str, Any],
    *,
    purpose: Optional[WorkspacePurpose] = None,
    subject: Optional[EntityCoordinate] = None,
) -> Any:
    workspace_id = str(workspace.get("id") or "")
    if not workspace_id:
        raise ValueError("Workspace purpose requires a Workspace id.")
    purpose = purpose or _inferred_workspace_purpose(workspace)
    if subject is None:
        subject = _inferred_workspace_purpose_subject(workspace, purpose)
    label = str(workspace.get("title") or "Workspace")
    try:
        current = state.coordination.get_workspace_purpose(workspace_id)
    except CoordinationNotFound:
        current = None
    semantic = {
        "workspace_id": workspace_id,
        "purpose": purpose.value,
        "subject": None if subject is None else subject.to_dict(),
        "label": label,
    }
    operation_id = (
        f"studio/workspace-purpose/{workspace_id}/"
        f"{request_digest(semantic)}"
    )
    if (
        current is not None
        and current.purpose is purpose
        and current.subject == subject
        and current.label == label
    ):
        return current
    return state.coordination.put_workspace_purpose(
        operation_id=operation_id,
        workspace_id=workspace_id,
        purpose=purpose,
        subject=subject,
        label=label,
        expected_revision=None if current is None else current.revision,
    )


def _workspace_purpose_record(state: UiState, workspace: Mapping[str, Any]) -> Any:
    workspace_id = str(workspace.get("id") or "")
    try:
        return state.coordination.get_workspace_purpose(workspace_id)
    except CoordinationNotFound:
        return _set_workspace_purpose(state, workspace)


def _agent_session_index_path(state: UiState) -> Path:
    return state.agent_sessions_dir / "index.json"


def _agent_session_dir(state: UiState, session_id: str) -> Path:
    return state.agent_sessions_dir / session_id


def _agent_messages_path(state: UiState, session_id: str) -> Path:
    return _agent_session_dir(state, session_id) / "messages.jsonl"


def _agent_events_path(state: UiState, session_id: str) -> Path:
    return _agent_session_dir(state, session_id) / "events.jsonl"


def _read_agent_session_index(state: UiState) -> List[JsonDict]:
    with state._agent_session_index_lock:
        path = _agent_session_index_path(state)
        if not path.exists():
            return []
        raw = _read_json(path)
        sessions = raw.get("sessions", []) if isinstance(raw, dict) else []
        if not isinstance(sessions, list):
            return []
        return [
            item for item in sessions if isinstance(item, dict) and item.get("id")
        ]


def _write_agent_session_index(state: UiState, sessions: List[JsonDict]) -> None:
    with state._agent_session_index_lock:
        path = _agent_session_index_path(state)
        path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "sessions": sorted(
                sessions, key=lambda item: item.get("updated_at", ""), reverse=True
            )
        }
        path.write_text(
            json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )


def _default_agent_message() -> JsonDict:
    return {
        "id": f"msg_{uuid.uuid4().hex[:10]}",
        "role": "assistant",
        "title": "Ready",
        "content": "I can use the current page, attached workspace roots, catalog, study plans, runs, and Code Server context.",
        "created_at": _now_iso(),
        "source": "studio_system",
        "memory_scope": "ui_history",
    }


def _read_agent_messages(state: UiState, session_id: str) -> List[JsonDict]:
    path = _agent_messages_path(state, session_id)
    if not path.exists():
        return []
    messages: List[JsonDict] = []
    seen: set[tuple[str, str]] = set()
    for message in _read_jsonl(path):
        if _is_legacy_openhands_placeholder(
            message
        ) or _is_malformed_openhands_context_echo(message):
            continue
        key = (
            str(message.get("role") or ""),
            _normalize_agent_text(str(message.get("content") or "")),
        )
        if key[1] and key in seen:
            continue
        seen.add(key)
        messages.append(message)
    return messages


def _is_legacy_openhands_placeholder(message: JsonDict) -> bool:
    return (
        str(message.get("content") or "").strip()
        == "Message sent to OpenHands. Refresh the assistant session to see later events."
    )


def _is_malformed_openhands_context_echo(message: JsonDict) -> bool:
    content = str(message.get("content") or "").strip()
    return (
        message.get("role") == "assistant"
        and content.startswith("User request:")
        and "Visible OptPilot Studio context packet:" in content
    )


def _recover_agent_assistant_messages_from_events(
    state: UiState, session_id: str
) -> None:
    path = _agent_messages_path(state, session_id)
    raw_messages = _read_jsonl(path) if path.exists() else []
    existing_ids = {str(message.get("id") or "") for message in raw_messages}
    existing_texts = {
        _normalize_agent_text(str(message.get("content") or ""))
        for message in raw_messages
        if str(message.get("content") or "").strip()
    }
    for event in _read_agent_events(state, session_id):
        text = _openhands_user_facing_message_from_event(event)
        normalized = _normalize_agent_text(text)
        if not text or not normalized or normalized in existing_texts:
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        event_id = str(
            event.get("id") or payload.get("event_id") or uuid.uuid4().hex[:10]
        )
        message_id = f"msg_{_slug_text(event_id)[:32]}"
        if message_id in existing_ids:
            continue
        _append_jsonl(
            path,
            {
                "id": message_id,
                "role": "assistant",
                "title": "OpenHands",
                "content": text,
                "created_at": event.get("created_at") or _now_iso(),
                "source": "openhands",
                "memory_scope": "openhands_conversation",
                "dispatch": {"status": "answered", "transport": "openhands_http"},
            },
        )
        existing_ids.add(message_id)
        existing_texts.add(normalized)


def _openhands_user_facing_message_from_event(event: JsonDict) -> str:
    if not isinstance(event, dict) or event.get("type") != "openhands_event":
        return ""
    payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
    if str(payload.get("tool") or "") == "finish":
        text = _openhands_finish_message_from_payload(payload)
        if text:
            return text
    return ""


def _openhands_finish_message_from_payload(payload: JsonDict) -> str:
    arguments_preview = str(payload.get("arguments_preview") or "").strip()
    if arguments_preview:
        try:
            arguments = json.loads(arguments_preview)
        except json.JSONDecodeError:
            arguments = {}
        if isinstance(arguments, dict):
            text = _user_facing_openhands_text(
                arguments.get("message")
                or arguments.get("content")
                or arguments.get("text")
            )
            if text:
                return text
    raw_preview = str(payload.get("raw_preview") or "").strip()
    if raw_preview:
        try:
            raw = json.loads(raw_preview)
        except json.JSONDecodeError:
            raw = {}
        if isinstance(raw, dict):
            action = raw.get("action") if isinstance(raw.get("action"), dict) else {}
            observation = (
                raw.get("observation")
                if isinstance(raw.get("observation"), dict)
                else {}
            )
            text = _user_facing_openhands_text(
                action.get("message")
                or action.get("content")
                or observation.get("message")
                or observation.get("content")
            )
            if text:
                return text
    return ""


def _user_facing_openhands_text(content: Any) -> str:
    text = _content_text(content)
    if "</think>" in text:
        text = text.rsplit("</think>", 1)[1].strip()
    text = text.strip()
    if not text:
        return ""
    normalized = _normalize_agent_text(text).lower()
    if not normalized:
        return ""
    return text


def _content_text(content: Any) -> str:
    if content is None:
        return ""
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, dict):
        if "text" in content:
            return _content_text(content.get("text"))
        if "content" in content:
            return _content_text(content.get("content"))
        if "message" in content:
            return _content_text(content.get("message"))
        return ""
    if isinstance(content, list):
        parts = [_content_text(item) for item in content]
        return "\n".join(part for part in parts if part).strip()
    return str(content).strip()


def _normalize_agent_text(text: str) -> str:
    return " ".join(str(text or "").strip().split())


def _read_agent_events(state: UiState, session_id: str) -> List[JsonDict]:
    path = _agent_events_path(state, session_id)
    if not path.exists():
        return []
    events: List[JsonDict] = []
    for event in _read_jsonl(path):
        sanitized = _sanitize_agent_event(event)
        if _hide_public_agent_event(sanitized):
            continue
        events.append(sanitized)
    return events


def _hide_public_agent_event(event: JsonDict) -> bool:
    if not isinstance(event, dict) or event.get("type") != "openhands_event":
        return False
    payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
    return str(payload.get("category") or "") == "assistant_message"


def _sanitize_agent_event(event: JsonDict) -> JsonDict:
    if not isinstance(event, dict):
        return event
    sanitized = json.loads(json.dumps(event, default=str))
    payload = sanitized.get("payload")
    if not isinstance(payload, dict):
        return sanitized
    if isinstance(payload.get("summary"), str):
        payload["summary"] = _redact_internal_agent_state_text(
            _sanitize_openhands_step_text(payload["summary"])
        )
    if isinstance(payload.get("assistant_preview"), str):
        payload["assistant_preview"] = _redact_internal_agent_state_text(
            _sanitize_openhands_step_text(payload["assistant_preview"])
        )
    if isinstance(payload.get("raw_preview"), str):
        payload["raw_preview"] = _sanitize_agent_result_preview(payload["raw_preview"])
    if isinstance(payload.get("result_preview"), str):
        payload["result_preview"] = _sanitize_agent_result_preview(
            payload["result_preview"]
        )
    if "ui_cards" in payload:
        payload["ui_cards"] = sanitize_studio_ui_cards(
            _strip_internal_agent_state(payload.get("ui_cards"))
        )
    result = payload.get("result")
    if isinstance(result, dict) and "ui_cards" in result:
        result["ui_cards"] = sanitize_studio_ui_cards(
            _strip_internal_agent_state(result.get("ui_cards"))
        )
    return sanitized


def _sanitize_agent_result_preview(text: str) -> str:
    sanitized_text = _redact_internal_agent_state_text(
        _sanitize_openhands_step_text(text)
    )
    try:
        payload = json.loads(sanitized_text)
    except (TypeError, ValueError):
        return sanitized_text
    cleaned = _strip_internal_agent_state(payload)
    try:
        return json.dumps(cleaned, indent=2, sort_keys=True)
    except (TypeError, ValueError):
        return sanitized_text


def _strip_internal_agent_state(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            key: _strip_internal_agent_state(item)
            for key, item in value.items()
            if key not in {"openhands_pending_sync"}
        }
    if isinstance(value, list):
        return [_strip_internal_agent_state(item) for item in value]
    if isinstance(value, str):
        return _redact_internal_agent_state_text(value)
    return value


def _redact_internal_agent_state_text(text: str) -> str:
    cleaned = str(text)
    for marker, replacement in (
        ('"openhands_pending_sync"', '"internal_openhands_sync_state": "[redacted]"'),
        (
            '\\"openhands_pending_sync\\"',
            '\\"internal_openhands_sync_state\\": \\"[redacted]\\"',
        ),
    ):
        while True:
            start = cleaned.find(marker)
            if start < 0:
                break
            colon = cleaned.find(":", start + len(marker))
            brace = cleaned.find("{", colon + 1) if colon >= 0 else -1
            if colon < 0 or brace < 0:
                cleaned = cleaned[:start] + replacement + cleaned[start + len(marker) :]
                break
            depth = 0
            end = len(cleaned)
            for index in range(brace, len(cleaned)):
                char = cleaned[index]
                if char == "{":
                    depth += 1
                elif char == "}":
                    depth -= 1
                    if depth == 0:
                        end = index + 1
                        break
            cursor = end
            while cursor < len(cleaned) and cleaned[cursor] in " \t\r\n":
                cursor += 1
            if cursor < len(cleaned) and cleaned[cursor] == ",":
                cursor += 1
            cleaned = cleaned[:start] + replacement + cleaned[cursor:]
    return cleaned


def _sanitize_openhands_step_text(text: str) -> str:
    marker = "Visible OptPilot Studio context packet:"
    if marker not in text:
        return text
    if "User request:" in text:
        request = text.split("User request:", 1)[1].split(marker, 1)[0].strip()
        request = " ".join(request.split())
        if request:
            return f"User request sent to OpenHands: {request[:220]}"
        return "User request and Studio context sent to OpenHands."
    return "[Studio context packet redacted from step preview]"


def _agent_approvals_path(state: UiState, session_id: str) -> Path:
    return _agent_session_dir(state, session_id) / "approvals.json"


def _read_agent_approvals(state: UiState, session_id: str) -> List[JsonDict]:
    path = _agent_approvals_path(state, session_id)
    if not path.exists():
        return []
    raw = _read_json(path)
    approvals = raw.get("approvals", []) if isinstance(raw, dict) else []
    return [item for item in approvals if isinstance(item, dict) and item.get("id")]


def _write_agent_approvals(
    state: UiState, session_id: str, approvals: List[JsonDict]
) -> None:
    path = _agent_approvals_path(state, session_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps({"approvals": approvals}, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )
    try:
        path.chmod(0o600)
    except OSError:
        pass


def _upsert_agent_approval(
    state: UiState, session_id: str, approval: JsonDict
) -> JsonDict:
    approvals = [
        item
        for item in _read_agent_approvals(state, session_id)
        if item.get("id") != approval.get("id")
    ]
    approvals.append(approval)
    _write_agent_approvals(state, session_id, approvals)
    return approval


def _assistant_ui_card_id(kind: str, coordinate: Mapping[str, Any]) -> str:
    digest = request_digest(
        {
            "schema": STUDIO_UI_CARD_SCHEMA,
            "kind": kind,
            "coordinate": dict(coordinate),
        }
    )[:24]
    return f"{kind.replace('-', '_')}_{digest}"


def _assistant_ui_card_action(
    card_id: str,
    operation: str,
    label: str,
    *,
    eligible: bool = True,
    reason: str = "",
    approval_required: bool = False,
) -> JsonDict:
    return {
        "id": f"{card_id}:{operation}",
        "label": label,
        "operation": operation,
        "eligible": bool(eligible),
        "reason": str(reason or ""),
        "approval_required": bool(approval_required),
    }


def _assistant_ui_card_facts(*facts: tuple[str, Any]) -> List[JsonDict]:
    return [
        {"label": label, "value": value}
        for label, value in facts
        if value not in (None, "", [], {})
        and isinstance(value, (str, int, float, bool))
    ]


def _assistant_study_launch_readiness(validation: Any) -> tuple[bool, str]:
    if not isinstance(validation, Mapping):
        return False, "Run setup validation is unavailable."
    if validation.get("valid") is not True:
        errors = [
            str(item)
            for item in validation.get("errors", []) or []
            if str(item)
        ]
        return False, errors[0] if errors else "Run setup validation failed."
    launch = validation.get("launch")
    if not isinstance(launch, Mapping):
        capabilities = validation.get("capabilities")
        launch = (
            capabilities.get("retained_execution")
            if isinstance(capabilities, Mapping)
            and isinstance(capabilities.get("retained_execution"), Mapping)
            else {}
        )
    if launch.get("eligible") is True:
        return True, ""
    return False, str(
        launch.get("reason")
        or "This Run setup is not currently eligible to start."
    )


def _assistant_catalog_ui_card(
    entry: Any, *, validation: Any = None
) -> Optional[JsonDict]:
    if not isinstance(entry, Mapping):
        return None
    config_kind = str(entry.get("config") or entry.get("kind") or "")
    uid = str(entry.get("uid") or "")
    title = str(entry.get("label") or entry.get("id") or "")
    if config_kind not in {"environment", "method", "resource", "study"}:
        return None
    if not uid or not title:
        return None
    coordinate = {
        "kind": "catalog-entry",
        "config_kind": config_kind,
        "uid": uid,
    }
    card_kind = "run-setup" if config_kind == "study" else "catalog-use"
    card_id = _assistant_ui_card_id(card_kind, coordinate)
    actions = [
        _assistant_ui_card_action(
            card_id,
            "open-catalog",
            "Open in Catalog",
        )
    ]
    interface = entry.get("interface")
    if isinstance(interface, Mapping) and interface.get("profiles"):
        launch = (
            interface.get("actions", {}).get("launch", {})
            if isinstance(interface.get("actions"), Mapping)
            else {}
        )
        launch_eligible = launch.get("eligible") is True
        actions.append(
            _assistant_ui_card_action(
                card_id,
                "open-interface",
                "Open interface",
                eligible=launch_eligible,
                reason=str(launch.get("reason") or "")
                if not launch_eligible
                else "",
            )
        )
    status = "available"
    validation_value = validation if isinstance(validation, Mapping) else entry.get(
        "validation"
    )
    if isinstance(validation_value, Mapping) and validation_value.get("valid") is False:
        status = "needs-review"
    if config_kind == "study":
        eligible, reason = _assistant_study_launch_readiness(validation_value)
        actions.extend(
            [
                _assistant_ui_card_action(
                    card_id,
                    "configure-run",
                    "Review Run setup",
                ),
                _assistant_ui_card_action(
                    card_id,
                    "start-run",
                    "Start run",
                    eligible=eligible,
                    reason=reason,
                    approval_required=True,
                ),
            ]
        )
        status = "ready" if eligible else "needs-review"
    package = str(entry.get("package_id") or entry.get("package") or "")
    profile_count = (
        interface.get("profileCount")
        if isinstance(interface, Mapping)
        else None
    )
    return {
        "schema": STUDIO_UI_CARD_SCHEMA,
        "id": card_id,
        "kind": card_kind,
        "coordinate": coordinate,
        "title": title,
        "description": str(entry.get("description") or ""),
        "status": status,
        "facts": _assistant_ui_card_facts(
            ("Type", "Run setup" if config_kind == "study" else config_kind.title()),
            ("Package", package),
            ("Interface profiles", profile_count),
        ),
        "actions": actions,
    }


def _assistant_run_setup_ui_card(
    data: Mapping[str, Any], *, saved_result: bool = False
) -> Optional[JsonDict]:
    workspace = data.get("workspace") if isinstance(data.get("workspace"), Mapping) else {}
    workspace_id = str(data.get("workspace_id") or workspace.get("id") or "")
    workspace_revision = data.get("workspace_revision") or workspace.get(
        "realm_workspace_revision"
    )
    study_relative_path = str(data.get("study_relative_path") or data.get("path") or "")
    exact_setup = (
        bool(workspace_id)
        and isinstance(workspace_revision, int)
        and not isinstance(workspace_revision, bool)
        and workspace_revision > 0
        and bool(study_relative_path)
    )
    compatibility = (
        data.get("compatibility")
        if isinstance(data.get("compatibility"), Mapping)
        else {}
    )
    environment = (
        compatibility.get("environment")
        if isinstance(compatibility.get("environment"), Mapping)
        else {}
    )
    method = (
        compatibility.get("method")
        if isinstance(compatibility.get("method"), Mapping)
        else {}
    )
    if exact_setup:
        coordinate: JsonDict = {
            "kind": "study-workspace",
            "workspace_id": workspace_id,
            "workspace_revision": workspace_revision,
            "study_relative_path": study_relative_path,
        }
        if environment.get("uid"):
            coordinate["environment_uid"] = str(environment["uid"])
        if method.get("uid"):
            coordinate["method_uid"] = str(method["uid"])
        if data.get("draft_id"):
            coordinate["draft_id"] = str(data["draft_id"])
        if data.get("draft_revision"):
            coordinate["draft_revision"] = data["draft_revision"]
    elif workspace_id:
        coordinate = {"kind": "workspace", "workspace_id": workspace_id}
    else:
        return None
    draft = data.get("draft") if isinstance(data.get("draft"), Mapping) else {}
    validation = data.get("validation")
    launch_eligible, launch_reason = _assistant_study_launch_readiness(validation)
    launch_eligible = bool(exact_setup and launch_eligible)
    if not exact_setup and not launch_reason:
        launch_reason = "Start from an exact Realm-managed Run setup revision."
    title = str(
        draft.get("name")
        or workspace.get("title")
        or Path(study_relative_path).stem
        or "Run setup"
    )
    objective = draft.get("objective") if isinstance(draft.get("objective"), Mapping) else {}
    budget = draft.get("budget") if isinstance(draft.get("budget"), Mapping) else {}
    compatibility_status = (
        "Compatible"
        if compatibility.get("compatible") is True
        else "Incompatible"
        if compatibility.get("compatible") is False
        else "Not checked"
    )
    validation_status = (
        "Valid"
        if isinstance(validation, Mapping) and validation.get("valid") is True
        else "Needs review"
    )
    card_id = _assistant_ui_card_id("run-setup", coordinate)
    actions = [
        _assistant_ui_card_action(
            card_id, "open-workspace", "Open Workspace", eligible=bool(workspace_id)
        )
    ]
    if exact_setup:
        actions.insert(
            0,
            _assistant_ui_card_action(
                card_id, "configure-run", "Review Run setup"
            ),
        )
    actions.append(
        _assistant_ui_card_action(
            card_id,
            "start-run",
            "Start run",
            eligible=launch_eligible,
            reason=launch_reason,
            approval_required=True,
        )
    )
    return {
        "schema": STUDIO_UI_CARD_SCHEMA,
        "id": card_id,
        "kind": "run-setup",
        "coordinate": coordinate,
        "title": title,
        "description": str(
            draft.get("description")
            or ("Saved Run setup." if saved_result else "Run setup prepared for review.")
        ),
        "status": "ready" if launch_eligible else "needs-review",
        "facts": _assistant_ui_card_facts(
            ("Environment", environment.get("label") or environment.get("id")),
            ("Method", method.get("label") or method.get("id")),
            ("Metric", objective.get("metric")),
            ("Direction", objective.get("direction")),
            ("Max trials", budget.get("maxTrials")),
            ("Compatibility", compatibility_status),
            ("Validation", validation_status),
            ("Workspace revision", workspace_revision),
        ),
        "actions": actions,
    }


def _assistant_study_launch_ui_card(data: Mapping[str, Any]) -> Optional[JsonDict]:
    job = data.get("job") if isinstance(data.get("job"), Mapping) else {}
    launch_id = str(job.get("launch_id") or job.get("job_id") or "")
    if not launch_id:
        return None
    coordinate: JsonDict = {"kind": "study-launch", "launch_id": launch_id}
    run_id = str(job.get("run_id") or "")
    if run_id:
        coordinate["run_id"] = run_id
    card_id = _assistant_ui_card_id("run", coordinate)
    actions = [
        _assistant_ui_card_action(card_id, "open-launch", "Open launch")
    ]
    if run_id:
        actions.append(
            _assistant_ui_card_action(card_id, "open-run", "Open run")
        )
    return {
        "schema": STUDIO_UI_CARD_SCHEMA,
        "id": card_id,
        "kind": "run",
        "coordinate": coordinate,
        "title": str(job.get("study_name") or "Run launch"),
        "description": "The Run setup was accepted and its current launch state is shown here.",
        "status": str(job.get("status") or "queued"),
        "facts": _assistant_ui_card_facts(
            ("Environment", job.get("environment_id")),
            ("Method", job.get("method_id")),
            ("Run", run_id),
        ),
        "actions": actions,
    }


def _assistant_run_ui_card(run: Any) -> Optional[JsonDict]:
    if not isinstance(run, Mapping):
        return None
    run_id = str(run.get("run_id") or run.get("id") or "")
    if not run_id:
        return None
    coordinate = {"kind": "run", "run_id": run_id}
    card_id = _assistant_ui_card_id("run", coordinate)
    objective = run.get("objective") if isinstance(run.get("objective"), Mapping) else {}
    primary_metric = (
        objective.get("metric")
        or objective.get("name")
        or (
            objective.get("primaryMetric", {}).get("name")
            if isinstance(objective.get("primaryMetric"), Mapping)
            else None
        )
    )
    best = run.get("best_comparable_candidate")
    best_value = None
    if isinstance(best, Mapping):
        best_value = best.get("primary_metric_value") or best.get("metric_value")
    return {
        "schema": STUDIO_UI_CARD_SCHEMA,
        "id": card_id,
        "kind": "run",
        "coordinate": coordinate,
        "title": str(run.get("name") or run_id),
        "description": "Open the recorded Run for current progress, results, and evidence.",
        "status": str(run.get("status") or run.get("run_status") or "unknown"),
        "facts": _assistant_ui_card_facts(
            ("Completed trials", run.get("completed_trials")),
            ("Accepted trials", run.get("accepted_trials")),
            ("Failures", run.get("failure_count")),
            ("Objective", primary_metric),
            ("Best", best_value),
        ),
        "actions": [
            _assistant_ui_card_action(card_id, "open-run", "Open run")
        ],
    }


def _assistant_interface_launch_ui_card(launch: Any) -> Optional[JsonDict]:
    if not isinstance(launch, Mapping):
        return None
    launch_id = str(launch.get("launch_id") or launch.get("id") or "")
    config_kind = str(launch.get("kind") or "")
    uid = str(launch.get("uid") or "")
    if (
        not launch_id
        or config_kind not in {"environment", "method", "resource"}
        or not uid
    ):
        return None
    coordinate = {
        "kind": "interface-launch",
        "launch_id": launch_id,
        "config_kind": config_kind,
        "uid": uid,
    }
    card_id = _assistant_ui_card_id("interface", coordinate)
    status = str(launch.get("status") or "queued")
    ready = status == "ready"
    active = status not in {"failed", "stopped"}
    return {
        "schema": STUDIO_UI_CARD_SCHEMA,
        "id": card_id,
        "kind": "interface",
        "coordinate": coordinate,
        "title": str(launch.get("label") or "Interface"),
        "description": (
            "The interface is ready in Studio Preview."
            if ready
            else "The interface launch is tracked by Studio."
        ),
        "status": status,
        "facts": _assistant_ui_card_facts(
            ("Launch", launch_id),
            ("Port", launch.get("port")),
            ("Profile", launch.get("profile_id")),
        ),
        "actions": [
            _assistant_ui_card_action(
                card_id,
                "open-interface",
                "Open interface" if ready else "View interface",
                eligible=active,
                reason=(
                    str(launch.get("error") or "This interface is no longer active.")
                    if not active
                    else ""
                ),
            )
        ],
    }


def _assistant_inactive_interface_launch_ui_card(card: Any) -> Optional[JsonDict]:
    """Project a retained interface card whose transient launch no longer exists."""

    cards = sanitize_studio_ui_cards([card])
    if not cards or cards[0].get("kind") != "interface":
        return None
    inactive = dict(cards[0])
    inactive["description"] = "This interface launch is no longer active."
    inactive["status"] = "stopped"
    inactive["actions"] = [
        {
            **action,
            "eligible": False,
            "reason": "This interface is no longer active.",
        }
        for action in inactive.get("actions", [])
    ]
    return inactive


def _assistant_tool_ui_cards(tool: str, data: Mapping[str, Any]) -> List[JsonDict]:
    cards: List[Optional[JsonDict]] = []
    if tool == "optpilot_catalog_detail":
        cards.append(
            _assistant_catalog_ui_card(
                data.get("entry"), validation=data.get("validation")
            )
        )
    elif tool == "optpilot_study_draft":
        cards.append(_assistant_run_setup_ui_card(data))
    elif tool == "optpilot_study_save":
        cards.append(_assistant_run_setup_ui_card(data, saved_result=True))
    elif tool == "optpilot_study_launch":
        cards.append(_assistant_study_launch_ui_card(data))
    elif tool == "optpilot_run_list":
        runs = data.get("runs")
        if isinstance(runs, list):
            cards.extend(_assistant_run_ui_card(item) for item in runs)
    elif tool == "optpilot_run_detail":
        cards.append(_assistant_run_ui_card(data.get("run")))
    elif tool in {"optpilot_interface_launch", "optpilot_interface_status"}:
        cards.append(_assistant_interface_launch_ui_card(data.get("launch")))
    return [card for card in cards if card is not None]


#: The shape every refusal uses to say what would fix it.
#:
#: A refusal has always carried a sentence for a person to read, and the
#: Assistant had to infer the fix from that English. Usually it guessed right;
#: sometimes it apologised and stopped, or proposed a fix for a different
#: problem. This carries the same answer a second time in a form that can be
#: acted on without interpretation.
#:
#: Exactly one of `command` or `tool` is the *thing to do*, and either may be
#: absent when the fix is neither -- editing a file, say. `details` carries the
#: specifics the fix needs, such as the declarations of the missing values.
REMEDY_SCHEMA = "optpilot.assistant-remedy.v1"


def _remedy(
    summary: str,
    *,
    command: str = "",
    tool: str = "",
    arguments: Optional[JsonDict] = None,
    details: Optional[JsonDict] = None,
) -> JsonDict:
    """One machine-readable answer to "what would fix this?"."""

    remedy: JsonDict = {"schema": REMEDY_SCHEMA, "summary": str(summary).strip()}
    if command:
        remedy["command"] = str(command).strip()
    if tool:
        remedy["tool"] = str(tool).strip()
        remedy["arguments"] = dict(arguments or {})
    if details:
        remedy["details"] = dict(details)
    return remedy


def _with_remedy(error: BaseException, remedy: JsonDict) -> BaseException:
    """Attach a remedy to the exception the code already raises.

    Most tools reject a bad request by raising, and those refusals reached the
    model as a bare sentence while returned ones could carry structure -- the
    same refusal answering differently depending on how it happened to be
    written.

    The remedy rides on the existing exception rather than a new type of its
    own, because the type carries meaning that must not change: thirty-five
    handlers branch on RealmConflict alone, and it decides an HTTP status.
    """

    setattr(error, "remedy", remedy)
    return error


def _tool_result(
    tool: str,
    ok: bool,
    summary: str,
    *,
    data: Optional[JsonDict] = None,
    artifacts: Optional[List[JsonDict]] = None,
    events: Optional[List[JsonDict]] = None,
    ui_cards: Optional[List[JsonDict]] = None,
    remedy: Optional[JsonDict] = None,
) -> JsonDict:
    result_data = data or {}
    projected_cards = (
        _assistant_tool_ui_cards(tool, result_data)
        if ui_cards is None
        else ui_cards
    )
    result = {
        "ok": ok,
        "tool": tool,
        "summary": summary,
        "data": result_data,
        "artifacts": artifacts or [],
        "events": events or [],
        "ui_cards": sanitize_studio_ui_cards(projected_cards),
    }
    # Only ever on a refusal: a remedy beside a success would read as "here is
    # something else you should have done".
    if remedy and not ok:
        result["remedy"] = remedy
    return result


def _approval_display_payload(approval: JsonDict) -> JsonDict:
    display = (
        approval.get("display_payload")
        if isinstance(approval.get("display_payload"), dict)
        else {}
    )
    arguments = (
        approval.get("arguments") if isinstance(approval.get("arguments"), dict) else {}
    )
    redacted_arguments = (
        display.get("redacted_arguments")
        if isinstance(display.get("redacted_arguments"), dict)
        else {}
    )
    if not redacted_arguments and arguments:
        redacted_arguments = {
            str(key): value
            for key, value in arguments.items()
            if str(key)
            not in {
                "content",
                "file_text",
                "yaml",
                "api_key",
                "token",
                "secret",
                "password",
                "_openhands_tool_call_id",
                "approved",
            }
        }
    return {
        "summary": str(display.get("summary") or approval.get("summary") or ""),
        "targets": display.get("targets")
        if isinstance(display.get("targets"), list)
        else list(approval.get("targets") or []),
        "redacted_arguments": redacted_arguments,
    }


def _public_agent_approval(approval: JsonDict) -> JsonDict:
    public_keys = {
        "id",
        "session_id",
        "tool",
        "kind",
        "title",
        "summary",
        "targets",
        "status",
        "created_at",
        "updated_at",
        "approved_at",
        "rejected_at",
        "executed_at",
        "request_key",
        "openhands_tool_call_id",
        "openhands_tool_call_ids",
        "rejection_reason",
    }
    public = {key: approval[key] for key in public_keys if key in approval}
    public["display_payload"] = _approval_display_payload(approval)
    if isinstance(approval.get("forwarding"), dict):
        public["forwarding"] = approval["forwarding"]
    if isinstance(approval.get("result"), dict):
        result = approval["result"]
        public["result"] = {
            "ok": bool(result.get("ok")),
            "tool": str(result.get("tool") or ""),
            "summary": str(result.get("summary") or ""),
            "ui_cards": sanitize_studio_ui_cards(result.get("ui_cards")),
        }
    if "openhands_feedback" in approval:
        public["openhands_feedback"] = approval.get("openhands_feedback")
    return public


def _public_agent_approvals(state: UiState, session_id: str) -> List[JsonDict]:
    approvals: List[JsonDict] = []
    for approval in _read_agent_approvals(state, session_id):
        public = _public_agent_approval(approval)
        result = (
            approval.get("result")
            if isinstance(approval.get("result"), dict)
            else {}
        )
        data = result.get("data") if isinstance(result.get("data"), dict) else {}
        launch_id = str(
            data.get("launch_id")
            or (
                data.get("launch", {}).get("launch_id")
                if isinstance(data.get("launch"), dict)
                else ""
            )
        )
        if result.get("tool") == "optpilot_interface_launch" and launch_id:
            try:
                launch = _interface_launch_by_id(state, launch_id)
            except KeyError:
                launch = None
            card = _assistant_interface_launch_ui_card(launch)
            if isinstance(public.get("result"), dict):
                if card:
                    public["result"]["ui_cards"] = sanitize_studio_ui_cards([card])
                else:
                    retained_cards = public["result"].get("ui_cards", [])
                    public["result"]["ui_cards"] = sanitize_studio_ui_cards(
                        [
                            inactive
                            for retained in retained_cards
                            if (inactive := _assistant_inactive_interface_launch_ui_card(retained))
                        ]
                    )
        approvals.append(public)
    return approvals


def _agent_pending_approval_ids(state: UiState, session_id: str) -> List[str]:
    return [
        str(item.get("id"))
        for item in _read_agent_approvals(state, session_id)
        if item.get("status") == "pending" and item.get("id")
    ]


def _agent_forwarding_failed_approval_ids(state: UiState, session_id: str) -> List[str]:
    failed_ids: List[str] = []
    for approval in _read_agent_approvals(state, session_id):
        forwarding = (
            approval.get("forwarding")
            if isinstance(approval.get("forwarding"), dict)
            else {}
        )
        if forwarding.get("status") in {"failed", "partial"} and approval.get("id"):
            failed_ids.append(str(approval["id"]))
    return failed_ids


def _agent_effective_status(state: UiState, session: JsonDict) -> str:
    session_id = str(session.get("id") or "")
    if session_id and _agent_pending_approval_ids(state, session_id):
        return "awaiting_user_approval"
    if session_id and _agent_forwarding_failed_approval_ids(state, session_id):
        return "approval_forwarding_failed"
    return str(session.get("status") or "idle")


def _session_background_action_runs(state: UiState, session_id: str) -> List[JsonDict]:
    """Slim live projections of this conversation's background action runs.

    Rides every session payload (full and summary) so the transcript can
    show a live running/succeeded/failed indicator and the Open Work shelf
    can list running jobs, without a per-request polling fan-out. Slim on
    purpose: the stdout/stderr tails stay on GET /api/resource-actions/<id>.
    Records live in memory only -- after a Studio restart the list is empty
    and the static transcript notes remain the history.
    """

    if not session_id:
        return []
    with state._lock:
        records = [
            dict(record)
            for record in state._resource_action_runs.values()
            if str(record.get("agent_session_id") or "") == session_id
        ]
    records.sort(key=lambda item: float(item.get("started_at") or 0.0), reverse=True)
    return [
        {
            "request_id": record.get("request_id"),
            "resource_uid": record.get("resource_uid"),
            "resource_id": record.get("resource_id"),
            "action_id": record.get("action_id"),
            "workspace_id": record.get("workspace_id") or "",
            "status": record.get("status"),
            "started_at": record.get("started_at"),
            "finished_at": record.get("finished_at"),
            "error": str(record.get("error") or "")[:300],
        }
        for record in records[:8]
    ]


def _decorate_agent_session_status(state: UiState, payload: JsonDict) -> JsonDict:
    session_id = str(payload.get("id") or "")
    active_ids = _agent_pending_approval_ids(state, session_id) if session_id else []
    forwarding_failed_ids = (
        _agent_forwarding_failed_approval_ids(state, session_id) if session_id else []
    )
    payload["effective_status"] = _agent_effective_status(state, payload)
    # These three fields describe one list, not three disjoint sets:
    # pending_approval_count is the whole pending set, active_approval_ids is
    # the single request currently offered to the user, and
    # queued_approval_count is the remaining tail. Clients that want a total
    # use pending_approval_count alone; adding the queued count double-counts.
    payload["pending_approval_count"] = len(active_ids)
    payload["active_approval_ids"] = active_ids[:1]
    payload["queued_approval_count"] = max(len(active_ids) - 1, 0)
    payload["forwarding_failed_approval_ids"] = forwarding_failed_ids
    payload["background_actions"] = _session_background_action_runs(state, session_id)
    return payload


def _validation_error_summary(validation: JsonDict, *, limit: int = 3) -> str:
    errors: List[str] = []
    for error in validation.get("errors", []) or []:
        if error:
            errors.append(str(error))
    for entry in validation.get("entries", []) or []:
        if not isinstance(entry, dict):
            continue
        label = str(
            entry.get("qualified_id") or entry.get("id") or entry.get("path") or "entry"
        )
        config = str(entry.get("config") or "").strip()
        if config and config not in label:
            label = f"{config} {label}"
        for error in entry.get("errors", []) or []:
            if error:
                errors.append(f"{label}: {error}")
    unique: List[str] = []
    seen: set[str] = set()
    for error in errors:
        normalized = " ".join(error.split())
        if normalized in seen:
            continue
        seen.add(normalized)
        unique.append(normalized)
        if len(unique) >= limit:
            break
    if not unique:
        return "no detailed error was reported"
    suffix = ""
    if len(errors) > len(unique):
        suffix = f"; and {len(errors) - len(unique)} more"
    return "; ".join(unique) + suffix


def _smoke_error_summary(smoke: JsonDict, *, limit: int = 3) -> str:
    errors = [
        str(error) for error in smoke.get("errors", []) or [] if str(error).strip()
    ]
    if not errors:
        for key in ("stderr", "stdout"):
            text = str(smoke.get(key) or "").strip()
            if text:
                errors.append(text)
                break
    unique: List[str] = []
    seen: set[str] = set()
    for error in errors:
        normalized = " ".join(error.split())
        if normalized in seen:
            continue
        seen.add(normalized)
        unique.append(_cap_text(normalized, 500))
        if len(unique) >= limit:
            break
    if not unique:
        return "no detailed smoke error was reported"
    suffix = ""
    if len(errors) > len(unique):
        suffix = f"; and {len(errors) - len(unique)} more"
    return "; ".join(unique) + suffix


def _approval_request_key(tool: str, kind: str, arguments: JsonDict) -> str:
    stable_arguments = {
        str(key): value
        for key, value in (arguments or {}).items()
        if key not in {"_openhands_tool_call_id", "approved", "description"}
    }
    payload = {"tool": tool, "kind": kind, "arguments": stable_arguments}
    return hashlib.sha1(
        json.dumps(payload, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()


def _approval_record_key(approval: JsonDict) -> str:
    arguments = (
        approval.get("arguments") if isinstance(approval.get("arguments"), dict) else {}
    )
    if arguments:
        return _approval_request_key(
            str(approval.get("tool") or ""), str(approval.get("kind") or ""), arguments
        )
    return str(approval.get("request_key") or "")


def _supersede_duplicate_pending_approvals(
    state: UiState, session_id: str, approval: JsonDict, *, action: str
) -> None:
    approval_id = str(approval.get("id") or "")
    request_key = _approval_record_key(approval)
    changed = False
    approvals = []
    for item in _read_agent_approvals(state, session_id):
        item = dict(item)
        if (
            item.get("status") == "pending"
            and str(item.get("id") or "") != approval_id
            and _approval_record_key(item) == request_key
        ):
            item["status"] = "superseded"
            item["superseded_by"] = approval_id
            item["superseded_action"] = action
            item["superseded_at"] = _now_iso()
            changed = True
        approvals.append(item)
    if changed:
        _write_agent_approvals(state, session_id, approvals)


def _merge_duplicate_pending_approval_tool_calls(
    state: UiState, session_id: str, approval: JsonDict
) -> JsonDict:
    approval = dict(approval)
    approval_id = str(approval.get("id") or "")
    request_key = _approval_record_key(approval)
    tool_call_ids = _approval_tool_call_ids(approval)
    for item in _read_agent_approvals(state, session_id):
        if item.get("status") != "pending" or str(item.get("id") or "") == approval_id:
            continue
        if _approval_record_key(item) != request_key:
            continue
        for tool_call_id in _approval_tool_call_ids(item):
            if tool_call_id not in tool_call_ids:
                tool_call_ids.append(tool_call_id)
    approval["openhands_tool_call_ids"] = tool_call_ids
    return approval


def _approval_execution_context_allows_bypass(
    state: UiState,
    session_id: str,
    *,
    tool: str,
    arguments: JsonDict,
    execution_context: Optional[ToolExecutionContext],
) -> bool:
    if not execution_context or not execution_context.bypass_approval:
        return False
    if (
        execution_context.source != "studio_approval_handler"
        or not execution_context.approval_id
    ):
        return False
    approval = next(
        (
            item
            for item in _read_agent_approvals(state, session_id)
            if item.get("id") == execution_context.approval_id
        ),
        None,
    )
    if not approval or approval.get("status") not in {"pending", "executing"}:
        return False
    if str(approval.get("tool") or "") != tool:
        return False
    approval_kind = str(approval.get("kind") or "")
    return _approval_request_key(
        tool, approval_kind, arguments
    ) == _approval_record_key(approval)


def _approval_bypass_field_result(tool: str) -> JsonDict:
    summary = (
        "Approval bypass fields are ignored; use Studio's approval buttons to continue."
    )
    return _tool_result(
        tool,
        False,
        summary,
        data={"policy_error": "approval_bypass_rejected"},
        events=[{"level": "error", "message": summary}],
    )


def _previous_tool_failure_summary(
    state: UiState, session_id: str, tool: str
) -> str:
    """The reason this tool last failed in this conversation, if it did.

    Asking again after a failure is reasonable -- the person may have fixed
    whatever was wrong. Asking again without saying what went wrong is not:
    one conversation raised the same approval six times over four minutes,
    each run failing for three missing settings, and the person saw only a
    prompt reappearing with no explanation. The reason was recorded and
    readable the whole time; nothing put it in front of them.
    """

    latest = ""
    for event in _read_agent_events(state, session_id):
        if event.get("type") != "optpilot_tool_result":
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        if str(payload.get("tool") or "") != tool:
            continue
        if payload.get("ok"):
            latest = ""  # a later success clears the warning
            continue
        latest = str(payload.get("summary") or "").strip()
    return latest


def _request_agent_approval(
    state: UiState,
    session_id: str,
    *,
    tool: str,
    arguments: JsonDict,
    kind: str,
    title: str,
    summary: str,
    targets: Optional[List[str]] = None,
) -> JsonDict:
    request_key = _approval_request_key(tool, kind, arguments)
    for existing in _read_agent_approvals(state, session_id):
        if (
            existing.get("status") == "pending"
            and _approval_record_key(existing) == request_key
        ):
            existing = dict(existing)
            tool_call_id = str(arguments.get("_openhands_tool_call_id") or "")
            if tool_call_id:
                tool_call_ids = _approval_tool_call_ids(existing)
                if tool_call_id not in tool_call_ids:
                    tool_call_ids.append(tool_call_id)
                    existing["openhands_tool_call_ids"] = tool_call_ids
                    existing["updated_at"] = _now_iso()
                    _upsert_agent_approval(state, session_id, existing)
            session = _require_agent_session(state, session_id)
            session["status"] = "awaiting_user_approval"
            _upsert_agent_session(state, session)
            return _tool_result(
                tool,
                False,
                f"Approval required: {summary}",
                data={"approval": existing, "approval_required": True},
                events=[{"level": "warning", "message": summary}],
            )
    tool_call_id = str(arguments.get("_openhands_tool_call_id") or "")
    previous_failure = _previous_tool_failure_summary(state, session_id, tool)
    if previous_failure:
        # Put the last failure on the card itself. Approving again without it
        # is a coin flip the person cannot reason about.
        summary = f"{summary}\n\nThis failed last time: {previous_failure}"
    approval = {
        "id": f"approval_{uuid.uuid4().hex[:10]}",
        "session_id": session_id,
        "tool": tool,
        "kind": kind,
        "title": title,
        "summary": summary,
        "previous_failure": previous_failure,
        "targets": targets or [],
        "arguments": arguments,
        "private_execution_payload": {
            "arguments": arguments,
            "normalized_arguments": {
                str(key): value
                for key, value in (arguments or {}).items()
                if str(key)
                not in {"_openhands_tool_call_id", "approved", "description"}
            },
        },
        "display_payload": {
            "summary": summary,
            "targets": targets or [],
            "redacted_arguments": _approval_display_payload(
                {"summary": summary, "targets": targets or [], "arguments": arguments}
            )["redacted_arguments"],
        },
        "status": "pending",
        "request_key": request_key,
        "openhands_tool_call_id": tool_call_id,
        "openhands_tool_call_ids": [tool_call_id] if tool_call_id else [],
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
        "forwarding": {"status": "not_started", "attempts": []},
    }
    _upsert_agent_approval(state, session_id, approval)
    session = _require_agent_session(state, session_id)
    session["status"] = "awaiting_user_approval"
    _upsert_agent_session(state, session)
    _append_jsonl(
        _agent_events_path(state, session_id),
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "approval_requested",
            "created_at": approval["created_at"],
            "payload": approval,
        },
    )
    return _tool_result(
        tool,
        False,
        f"Approval required: {summary}",
        data={"approval": approval, "approval_required": True},
        events=[{"level": "warning", "message": summary}],
    )


def _assistant_permission(state: UiState, key: str) -> str:
    permissions = _assistant_permissions_from_settings(_read_ui_settings(state))
    return str(permissions.get(key) or DEFAULT_ASSISTANT_PERMISSIONS[key])


#: How each permission reads on the Settings page, so a refusal can name the
#: control rather than the key it is stored under.
ASSISTANT_PERMISSION_LABELS = {
    "file_write": "File writes",
    "shell_run": "Shell commands",
    "catalog_registration": "Catalog publishing",
    "study_launch": "Study launch",
    "job_stop": "Stop Runs and Candidate tries",
    "smoke_test": "Smoke tests",
    "resource_action": "Resource actions",
}


def _agent_permission_blocked_result(tool: str, key: str) -> JsonDict:
    summary = f"Assistant permission '{key}' is disabled in Studio settings."
    label = ASSISTANT_PERMISSION_LABELS.get(key, key)
    return _tool_result(
        tool,
        False,
        summary,
        data={"permission": key, "permission_status": "disabled"},
        events=[{"level": "error", "message": summary}],
        remedy=_remedy(
            f"Only the person can lift this: ask them to open Settings and set "
            f"\"{label}\" to something other than Disabled. Do not retry until "
            "they say they have.",
            details={"permission": key, "settings_label": label},
        ),
    )


def _agent_permission_gate(
    state: UiState,
    session_id: str,
    *,
    tool: str,
    arguments: JsonDict,
    permission_key: str,
    approval_kind: str,
    title: str,
    summary: str,
    targets: Optional[List[str]] = None,
    require_approval: bool = True,
    execution_context: Optional[ToolExecutionContext] = None,
) -> Optional[JsonDict]:
    mode = _assistant_permission(state, permission_key)
    if mode == "disabled":
        return _agent_permission_blocked_result(tool, permission_key)
    bypass_allowed = _approval_execution_context_allows_bypass(
        state,
        session_id,
        tool=tool,
        arguments=arguments,
        execution_context=execution_context,
    )
    if (
        require_approval
        and mode in {"approval_required", "safe_without_approval"}
        and not bypass_allowed
    ):
        if any(
            key in arguments
            for key in {"approved", "bypass_approval", "approval_bypass"}
        ):
            return _approval_bypass_field_result(tool)
        return _request_agent_approval(
            state,
            session_id,
            tool=tool,
            arguments=arguments,
            kind=approval_kind,
            title=title,
            summary=summary,
            targets=targets,
        )
    return None


def _approve_agent_action(
    state: UiState, session_id: str, approval_id: str
) -> JsonDict:
    with _agent_session_operation_lock(state, session_id):
        approvals = _read_agent_approvals(state, session_id)
        approval = next(
            (item for item in approvals if item.get("id") == approval_id), None
        )
        if not approval:
            raise KeyError(approval_id)
        if approval.get("status") != "pending":
            return {
                "approval": _public_agent_approval(approval),
                "result": approval.get("result"),
                "session": _agent_session_by_id(state, session_id),
            }
        approval = _merge_duplicate_pending_approval_tool_calls(
            state, session_id, approval
        )
        private_payload = (
            approval.get("private_execution_payload")
            if isinstance(approval.get("private_execution_payload"), dict)
            else {}
        )
        arguments = dict(
            private_payload.get("arguments", {})
            if isinstance(private_payload.get("arguments"), dict)
            else approval.get("arguments", {})
            if isinstance(approval.get("arguments"), dict)
            else {}
        )
        approval["status"] = "executing"
        approval["updated_at"] = _now_iso()
        _upsert_agent_approval(state, session_id, approval)
        try:
            result = _execute_agent_tool(
                state,
                session_id,
                str(approval["tool"]),
                arguments,
                execution_context=ToolExecutionContext(
                    source="studio_approval_handler",
                    approval_id=approval_id,
                    bypass_approval=True,
                ),
            )
        except Exception as exc:
            result = _tool_result(
                str(approval.get("tool") or "approval"),
                False,
                f"{type(exc).__name__}: {exc}",
                data={"error": {"type": type(exc).__name__, "message": str(exc)}},
                events=[{"level": "error", "message": str(exc)}],
            )
        feedback = _forward_approved_tool_result_to_openhands(
            state, session_id, approval, result
        )
        _supersede_duplicate_pending_approvals(
            state, session_id, approval, action="approved"
        )
        approval["status"] = "approved"
        approval["approved_at"] = _now_iso()
        approval["executed_at"] = approval["approved_at"]
        approval["updated_at"] = approval["approved_at"]
        approval["result"] = result
        approval["openhands_feedback"] = feedback
        approval["forwarding"] = _approval_forwarding_record(feedback)
        _upsert_agent_approval(state, session_id, approval)
        _update_session_after_approval_resolution(state, session_id, approval)
        _append_jsonl(
            _agent_events_path(state, session_id),
            {
                "id": f"evt_{uuid.uuid4().hex[:10]}",
                "type": "approval_approved",
                "created_at": approval["approved_at"],
                "payload": {
                    "approval_id": approval_id,
                    "tool": approval.get("tool"),
                    "ok": result.get("ok"),
                    "openhands_feedback": feedback,
                },
            },
        )
        return {
            "approval": _public_agent_approval(approval),
            "result": result,
            "session": _agent_session_by_id(state, session_id),
        }


def _reject_agent_action(
    state: UiState, session_id: str, approval_id: str, reason: str = ""
) -> JsonDict:
    with _agent_session_operation_lock(state, session_id):
        approvals = _read_agent_approvals(state, session_id)
        approval = next(
            (item for item in approvals if item.get("id") == approval_id), None
        )
        if not approval:
            raise KeyError(approval_id)
        if approval.get("status") != "pending":
            return {
                "approval": _public_agent_approval(approval),
                "session": _agent_session_by_id(state, session_id),
            }
        approval = _merge_duplicate_pending_approval_tool_calls(
            state, session_id, approval
        )
        approval["status"] = "rejected"
        approval["rejected_at"] = _now_iso()
        approval["updated_at"] = approval["rejected_at"]
        approval["rejection_reason"] = reason or "Rejected by user."
        result = _tool_result(
            str(approval.get("tool") or "approval"),
            False,
            f"Approval rejected: {approval['rejection_reason']}",
        )
        feedback = _forward_approved_tool_result_to_openhands(
            state, session_id, approval, result
        )
        _supersede_duplicate_pending_approvals(
            state, session_id, approval, action="rejected"
        )
        approval["result"] = result
        approval["openhands_feedback"] = feedback
        approval["forwarding"] = _approval_forwarding_record(feedback)
        _upsert_agent_approval(state, session_id, approval)
        _update_session_after_approval_resolution(state, session_id, approval)
        _append_jsonl(
            _agent_events_path(state, session_id),
            {
                "id": f"evt_{uuid.uuid4().hex[:10]}",
                "type": "approval_rejected",
                "created_at": approval["rejected_at"],
                "payload": {
                    "approval_id": approval_id,
                    "tool": approval.get("tool"),
                    "reason": approval["rejection_reason"],
                    "openhands_feedback": feedback,
                },
            },
        )
        return {
            "approval": _public_agent_approval(approval),
            "session": _agent_session_by_id(state, session_id),
        }


def _approval_forwarding_record(feedback: JsonDict) -> JsonDict:
    results = (
        feedback.get("results") if isinstance(feedback.get("results"), list) else []
    )
    if (
        not results
        and not feedback.get("sent")
        and "No active OpenHands tool call" in str(feedback.get("reason") or "")
    ):
        return {"status": "not_applicable", "updated_at": _now_iso(), "attempts": []}
    if not results and feedback:
        results = [feedback]
    sent_count = sum(
        1 for item in results if isinstance(item, dict) and item.get("sent")
    )
    if not results:
        status = "not_applicable"
    elif sent_count == len(results):
        if any(
            str(item.get("delivery_status") or "") == "confirmed_after_timeout"
            for item in results
            if isinstance(item, dict)
        ):
            status = "confirmed_after_timeout"
        else:
            status = "sent"
    elif sent_count > 0:
        status = "partial"
    else:
        status = "failed"
    return {
        "status": status,
        "updated_at": _now_iso(),
        "attempts": [
            {
                "sent": bool(item.get("sent")) if isinstance(item, dict) else False,
                "reason": str(item.get("reason") or item.get("delivery_status") or "")
                if isinstance(item, dict)
                else "",
                "tool_call_id": str(item.get("tool_call_id") or "")
                if isinstance(item, dict)
                else "",
            }
            for item in results
            if isinstance(item, dict)
        ],
    }


def _update_session_after_approval_resolution(
    state: UiState, session_id: str, approval: JsonDict
) -> None:
    if _agent_pending_approval_ids(state, session_id):
        return
    session = _require_agent_session(state, session_id)
    forwarding = (
        approval.get("forwarding")
        if isinstance(approval.get("forwarding"), dict)
        else {}
    )
    status = str(forwarding.get("status") or "")
    if status in {"failed", "partial"}:
        session["status"] = "approval_forwarding_failed"
    elif status in {"sent", "confirmed_after_timeout"}:
        session["status"] = "waiting_for_agent"
    else:
        session["status"] = "idle"
        session.pop("active_turn_id", None)
        session.pop("active_turn_started_at", None)
        session.pop("openhands_pending_sync", None)
    _upsert_agent_session(state, session)


def _approval_tool_call_ids(approval: JsonDict) -> List[str]:
    arguments = (
        approval.get("arguments") if isinstance(approval.get("arguments"), dict) else {}
    )
    values = [
        *(
            approval.get("openhands_tool_call_ids") or []
            if isinstance(approval.get("openhands_tool_call_ids"), list)
            else []
        ),
        approval.get("openhands_tool_call_id"),
        arguments.get("_openhands_tool_call_id"),
    ]
    result: List[str] = []
    seen: set[str] = set()
    for value in values:
        text = str(value or "").strip()
        if not text or text in seen:
            continue
        seen.add(text)
        result.append(text)
    return result


def _successful_openhands_forwarded_tool_call_ids(
    state: UiState, session_id: str
) -> set[str]:
    handled: set[str] = set()
    for event in _read_agent_events(state, session_id):
        event_type = str(event.get("type") or "")
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        if event_type == "optpilot_tool_result" and str(
            payload.get("delivery_status") or ""
        ) in {
            "sent",
            "confirmed_after_timeout",
        }:
            call_id = str(payload.get("tool_call_id") or "")
            if call_id:
                handled.add(call_id)
            continue
        if event_type != "openhands_tool_result_forwarded" or not payload.get("sent"):
            continue
        values = [
            *(
                payload.get("tool_call_ids")
                if isinstance(payload.get("tool_call_ids"), list)
                else []
            ),
            payload.get("tool_call_id"),
        ]
        for value in values:
            call_id = str(value or "")
            if call_id:
                handled.add(call_id)
    return handled


def _supersede_forwarded_pending_approvals(
    state: UiState, session_id: str
) -> bool:
    """Recover approval cards left pending after their call already resumed."""

    forwarded_call_ids = _successful_openhands_forwarded_tool_call_ids(
        state, session_id
    )
    if not forwarded_call_ids:
        return False
    approvals = _read_agent_approvals(state, session_id)
    resolved_by_call_id: Dict[str, str] = {}
    for approval in approvals:
        if approval.get("status") not in {"approved", "rejected"}:
            continue
        approval_id = str(approval.get("id") or "")
        for call_id in _approval_tool_call_ids(approval):
            if call_id in forwarded_call_ids and approval_id:
                resolved_by_call_id[call_id] = approval_id

    changed = False
    recovered_at = _now_iso()
    recovered: List[JsonDict] = []
    for approval in approvals:
        approval = dict(approval)
        matching_call_ids = [
            call_id
            for call_id in _approval_tool_call_ids(approval)
            if call_id in forwarded_call_ids
        ]
        if approval.get("status") == "pending" and matching_call_ids:
            approval["status"] = "superseded"
            approval["superseded_action"] = "tool_result_already_forwarded"
            approval["superseded_at"] = recovered_at
            approval["updated_at"] = recovered_at
            superseded_by = next(
                (
                    resolved_by_call_id[call_id]
                    for call_id in matching_call_ids
                    if call_id in resolved_by_call_id
                ),
                "",
            )
            if superseded_by:
                approval["superseded_by"] = superseded_by
            changed = True
        recovered.append(approval)
    if changed:
        _write_agent_approvals(state, session_id, recovered)
    return changed


def _pending_tool_result_forward_records(
    state: UiState, session_id: str
) -> List[JsonDict]:
    successful = _successful_openhands_forwarded_tool_call_ids(state, session_id)
    records: List[JsonDict] = []
    seen: set[str] = set()
    for event in _read_agent_events(state, session_id):
        if event.get("type") != "optpilot_tool_result":
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        call_id = str(payload.get("tool_call_id") or "")
        delivery_status = str(payload.get("delivery_status") or "")
        result = (
            payload.get("result") if isinstance(payload.get("result"), dict) else {}
        )
        if (
            not call_id
            or call_id in successful
            or call_id in seen
            or delivery_status not in {"timeout", "failed"}
            or not result
        ):
            continue
        seen.add(call_id)
        records.append(
            {
                "tool": str(payload.get("tool") or ""),
                "tool_call_id": call_id,
                "result": result,
                "delivery_status": delivery_status,
                "delivery_error": str(payload.get("delivery_error") or ""),
            }
        )
    return records


def _retry_pending_tool_result_forwards(
    state: UiState, session_id: str, conversation_id: str
) -> List[JsonDict]:
    if not conversation_id:
        return []
    submit_tool_result = getattr(state.agent_adapter, "submit_tool_result", None)
    if not callable(submit_tool_result):
        return []
    attempts: List[JsonDict] = []
    for record in _pending_tool_result_forward_records(state, session_id):
        tool = str(record.get("tool") or "")
        call_id = str(record.get("tool_call_id") or "")
        result = record.get("result") if isinstance(record.get("result"), dict) else {}
        if not tool or not call_id or not result:
            continue
        try:
            feedback = submit_tool_result(conversation_id, tool, call_id, result)
        except Exception as exc:  # pragma: no cover - defensive adapter boundary
            feedback = {
                "sent": False,
                "reason": str(exc),
                "conversation_id": conversation_id,
                "tool_call_id": call_id,
            }
        event = {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "openhands_tool_result_forwarded"
            if feedback.get("sent")
            else "openhands_tool_result_forward_skipped",
            "created_at": _now_iso(),
            "payload": {
                "tool": tool,
                "tool_call_id": call_id,
                "tool_call_ids": [call_id],
                "conversation_id": conversation_id,
                "sent": bool(feedback.get("sent")),
                "reason": str(
                    feedback.get("reason") or feedback.get("delivery_status") or ""
                ),
                "retry": True,
                "previous_delivery_status": str(record.get("delivery_status") or ""),
                "previous_delivery_error": str(record.get("delivery_error") or ""),
                "feedback": feedback,
            },
        }
        _append_agent_event_record(state, session_id, event)
        attempts.append(event)
    return attempts


def _forward_approved_tool_result_to_openhands(
    state: UiState,
    session_id: str,
    approval: JsonDict,
    result: JsonDict,
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    conversation_id = str(session.get("openhands_conversation_id") or "")
    tool_call_ids = _approval_tool_call_ids(approval)
    tool_name = str(approval.get("tool") or result.get("tool") or "")
    feedback: JsonDict = {
        "sent": False,
        "reason": "No active OpenHands tool call to continue.",
        "results": [],
    }
    submit_tool_result = getattr(state.agent_adapter, "submit_tool_result", None)
    if conversation_id and tool_call_ids and callable(submit_tool_result):
        results = []
        for tool_call_id in tool_call_ids:
            try:
                item = submit_tool_result(
                    conversation_id, tool_name, tool_call_id, result
                )
            except Exception as exc:  # pragma: no cover - defensive adapter boundary
                item = {
                    "sent": False,
                    "reason": str(exc),
                    "conversation_id": conversation_id,
                    "tool_call_id": tool_call_id,
                }
            results.append(item)
        sent_count = sum(1 for item in results if item.get("sent"))
        feedback = {
            "sent": sent_count > 0,
            "sent_count": sent_count,
            "results": results,
            "conversation_id": conversation_id,
            "tool_call_ids": tool_call_ids,
            "reason": ""
            if sent_count
            else "; ".join(
                str(item.get("reason") or "") for item in results if item.get("reason")
            ),
        }
    _append_agent_event_record(
        state,
        session_id,
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "openhands_tool_result_forwarded"
            if feedback.get("sent")
            else "openhands_tool_result_forward_skipped",
            "created_at": _now_iso(),
            "payload": {
                "tool": tool_name,
                "tool_call_id": tool_call_ids[0] if tool_call_ids else "",
                "tool_call_ids": tool_call_ids,
                "conversation_id": conversation_id,
                "sent": bool(feedback.get("sent")),
                "reason": feedback.get("reason") or "",
            },
        },
    )
    if feedback.get("sent"):
        session["status"] = "waiting_for_agent"
        _upsert_agent_session(state, session)
    return feedback


def _execute_agent_tool(
    state: UiState,
    session_id: str,
    tool: str,
    arguments: Optional[JsonDict] = None,
    *,
    execution_context: Optional[ToolExecutionContext] = None,
) -> JsonDict:
    arguments = arguments or {}
    if tool == "optpilot_conversation_title":
        return _set_agent_conversation_title(
            state, session_id, arguments.get("title")
        )
    if tool == "optpilot_workspace_list":
        sessions = _read_agent_session_index(state)
        session = _require_agent_session(state, session_id)
        attached = set(session.get("attached_workspace_ids", []) or [])
        workspaces = []
        for workspace in _list_ui_workspaces(state, include_support=True):
            item = dict(workspace)
            item["attached_to_current_session"] = item.get("id") in attached
            workspaces.append(item)
        # Sessions ride along only for "what is attached where" context.
        # The raw index carried every internal field and, worse, stale
        # attachments to deleted workspaces -- a model copied one of those
        # ids into workspace_attach and the turn died on it. Serve only
        # live attachments and the fields a model can act on.
        live_ids = {str(item.get("id") or "") for item in workspaces}
        sessions_slim = [
            {
                "id": item.get("id"),
                "title": item.get("title"),
                "status": item.get("status"),
                "attached_workspace_ids": [
                    workspace_id
                    for workspace_id in (item.get("attached_workspace_ids") or [])
                    if workspace_id in live_ids
                ],
            }
            for item in sessions
            if isinstance(item, dict)
        ]
        return _tool_result(
            tool,
            True,
            f"Found {len(workspaces)} workspace(s).",
            data={"workspaces": workspaces, "sessions": sessions_slim},
        )
    if tool == "optpilot_workspace_create":
        workspace = _create_ui_workspace(state, arguments)
        _attach_agent_workspace(state, session_id, workspace["id"], select=True)
        return _tool_result(
            tool,
            True,
            f"Created workspace {workspace['id']}.",
            data={"workspace": workspace},
        )
    if tool == "optpilot_workspace_attach":
        session = _attach_agent_workspace(
            state, session_id, str(arguments.get("workspace_id") or ""), select=True
        )
        return _tool_result(
            tool, True, "Workspace attached.", data={"session": session}
        )
    if tool == "optpilot_workspace_detach":
        session = _detach_agent_workspace(
            state, session_id, str(arguments.get("workspace_id") or "")
        )
        return _tool_result(
            tool, True, "Workspace detached.", data={"session": session}
        )
    if tool == "optpilot_workspace_focus":
        session = _select_agent_workspace(
            state, session_id, str(arguments.get("workspace_id") or "")
        )
        return _tool_result(
            tool,
            True,
            "Workspace selected.",
            data={"session": session, "focus_path": str(arguments.get("path") or "")},
        )
    if tool == "optpilot_file_tree":
        workspace, root, target = _resolve_agent_workspace_path(
            state, session_id, arguments, default_path="."
        )
        max_files = min(max(int(arguments.get("max_files") or 200), 1), 500)
        files = _workspace_file_tree(root, target, max_files=max_files)
        return _tool_result(
            tool,
            True,
            f"Listed {len(files)} file(s).",
            data={
                "workspace": workspace,
                "root": str(root),
                "path": _relative_path(target, root),
                "files": files,
            },
        )
    if tool == "optpilot_file_read":
        workspace, root, path = _resolve_agent_workspace_path(
            state, session_id, arguments
        )
        _refuse_secret_file(path, root)
        if not path.is_file():
            raise FileNotFoundError(_relative_path(path, root))
        if path.stat().st_size > 1_000_000:
            raise ValueError("File is too large to read through the assistant tool.")
        return _tool_result(
            tool,
            True,
            f"Read {_relative_path(path, root)}.",
            data={
                "workspace": workspace,
                "path": _relative_path(path, root),
                "content": path.read_text(encoding="utf-8", errors="replace"),
            },
        )
    if tool == "optpilot_file_write":
        workspace, root, path = _resolve_agent_workspace_path(
            state, session_id, arguments
        )
        _refuse_secret_file(path, root)
        _require_editable_workspace(workspace)
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={
                **arguments,
                "workspace_id": workspace["id"],
                "path": _relative_path(path, root),
            },
            permission_key="file_write",
            approval_kind="file_write",
            title="Write workspace file",
            summary=f"Write {_relative_path(path, root)} in {workspace.get('title') or workspace.get('id')}.",
            targets=[str(root), _relative_path(path, root)],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        content = str(arguments.get("content") or "")
        if len(content.encode("utf-8")) > 2_000_000:
            raise ValueError(
                "Content is too large to write through the assistant tool."
            )
        existed = path.exists()
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8")
        return _tool_result(
            tool,
            True,
            f"Wrote {_relative_path(path, root)}.",
            data={
                "workspace": workspace,
                "path": _relative_path(path, root),
                "created": not existed,
                "bytes": len(content.encode("utf-8")),
            },
        )
    if tool == "optpilot_file_diff":
        workspace, root, path = _resolve_agent_workspace_path(
            state, session_id, arguments
        )
        # A diff shows the existing contents line by line, so it leaks exactly
        # what a read would.
        _refuse_secret_file(path, root)
        new_content = str(arguments.get("content") or "")
        old_content = (
            path.read_text(encoding="utf-8", errors="replace")
            if path.exists() and path.is_file()
            else ""
        )
        diff = "".join(
            difflib.unified_diff(
                old_content.splitlines(True),
                new_content.splitlines(True),
                fromfile=f"a/{_relative_path(path, root)}",
                tofile=f"b/{_relative_path(path, root)}",
            )
        )
        return _tool_result(
            tool,
            True,
            f"Prepared diff for {_relative_path(path, root)}.",
            data={
                "workspace": workspace,
                "path": _relative_path(path, root),
                "diff": diff,
            },
        )
    if tool == "optpilot_shell_run":
        return _agent_tool_shell_run(
            state, session_id, tool, arguments, execution_context=execution_context
        )
    if tool in {"optpilot_terminal", "terminal"}:
        return _agent_tool_openhands_terminal(
            state, session_id, tool, arguments, execution_context=execution_context
        )
    if tool in {"optpilot_file_editor", "file_editor"}:
        return _agent_tool_openhands_file_editor(
            state, session_id, tool, arguments, execution_context=execution_context
        )
    if tool == "optpilot_workspace_preview_open":
        return _agent_tool_workspace_preview_open(state, session_id, tool, arguments)
    if tool == "optpilot_catalog_list":
        catalog = _catalog_payload(state)
        kind = str(arguments.get("config_kind") or arguments.get("kind") or "")
        kind_keys = {
            "environment": "environments",
            "method": "methods",
            "study": "studies",
            "resource": "resources",
            "environments": "environments",
            "methods": "methods",
            "studies": "studies",
            "resources": "resources",
        }
        query = str(arguments.get("query") or "").strip()
        tags = _catalog_search_tags(arguments.get("tags"))
        selected = (
            {key: catalog.get(key, []) for key in ("environments", "methods", "studies", "resources")}
            if not kind
            else {kind_keys.get(kind, kind): catalog.get(kind_keys.get(kind, kind), [])}
        )
        total = sum(len(entries) for entries in selected.values())
        filtered = {
            key: _search_catalog_entries(entries, query=query, tags=tags)
            for key, entries in selected.items()
        }
        matched = sum(len(entries) for entries in filtered.values())
        slim = {
            key: _assistant_catalog_entries(entries)
            for key, entries in filtered.items()
        }
        data = (
            slim
            if kind
            # Without a kind the caller wants everything, which also carries
            # the small non-entry keys (where the catalog was read from, and
            # which sources they came from). Keep those, replace the entry
            # lists with the slim ones.
            else {key: value for key, value in catalog.items() if key not in slim}
            | slim
        )
        summary = "Catalog entries and saved study plans listed."
        if query or tags:
            summary = (
                f"Catalog search matched {matched} of {total} "
                "entries and saved study plans."
            )
        return _tool_result(tool, True, summary, data=data)
    if tool == "optpilot_catalog_detail":
        kind = str(arguments.get("config_kind") or arguments.get("kind") or "")
        uid = str(arguments.get("uid") or "")
        if not uid:
            raise ValueError("uid must be an exact catalog entry ref token.")
        detail = _catalog_detail(state, kind, uid)
        detail_label = (
            "saved study plan" if kind in {"study", "studies"} else "catalog entry"
        )
        return _tool_result(tool, True, f"Loaded {kind} {detail_label}.", data=detail)
    if tool == "optpilot_resource_action_list":
        resource_uid = str(arguments.get("resource_uid") or "").strip()
        if not resource_uid:
            raise ValueError("resource_uid must be an exact catalog entry ref token.")
        manifest_path = _resolve_resource_action_source(state, resource_uid)
        with manifest_path.open("r", encoding="utf-8") as handle:
            resource_raw = yaml.safe_load(handle) or {}
        actions = compile_resource_actions(resource_raw, location=str(manifest_path))
        listing = [
            {
                "action_id": action.action_id,
                "label": action.label,
                "description": action.description,
                "inputs": action.inputs,
                "timeout_seconds": action.timeout_seconds,
                "requires_env_from_host": list(action.env_from_host),
                "requires_secrets_from_host": list(action.secrets_from_host),
            }
            for action in actions
        ]
        return _tool_result(
            tool,
            True,
            f"{len(listing)} action(s) declared by {resource_raw.get('id') or 'this resource'}."
            if listing
            else "This resource declares no actions.",
            data={"resource_uid": resource_uid, "actions": listing},
        )
    if tool == "optpilot_resource_action_run":
        resource_uid = str(arguments.get("resource_uid") or "").strip()
        action_id = str(arguments.get("action_id") or "").strip()
        if not resource_uid or not action_id:
            raise ValueError("resource_uid and action_id are required.")
        blocked = _resource_action_blocked_reason(state, resource_uid, action_id)
        if blocked:
            return _tool_result(
                tool,
                False,
                blocked,
                data={"remedy": {"kind": "configure_environment", "reason": blocked}},
            )
        workspace_id = str(arguments.get("workspace_id") or "").strip()
        inputs = arguments.get("inputs")
        if inputs is not None and not isinstance(inputs, Mapping):
            raise ValueError("inputs must be a JSON object.")
        # Generated here rather than asked of the model, and then carried in
        # the approval's stored arguments -- so approving a request runs the
        # same one, and a repeated call after approval does not run it twice.
        request_id = _canonical_request_uuid(
            str(arguments.get("request_id") or "") or str(uuid.uuid4())
        )
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={
                **arguments,
                "resource_uid": resource_uid,
                "action_id": action_id,
                "workspace_id": workspace_id,
                "request_id": request_id,
            },
            permission_key="resource_action",
            approval_kind="resource_action_run",
            title=f"Run resource action {action_id}",
            summary=(
                f"Run the {action_id} action and write its output into the "
                f"attached Workspace."
                if workspace_id
                else f"Run the {action_id} action."
            ),
            targets=[resource_uid, action_id],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        payload, start_status = _start_resource_action_run(
            state,
            {
                "request_id": request_id,
                "resource_uid": resource_uid,
                "action_id": action_id,
                "workspace_id": workspace_id,
                "inputs": dict(inputs or {}),
            },
        )
        # HTTPStatus.OK means the request id matched an existing run: nothing
        # new started, so a second "running in the background" note would
        # fabricate a launch that never happened.
        already_running = start_status == HTTPStatus.OK
        # A long action outlives any model turn, so the turn will end while
        # the work runs. Remember which conversation started it: when the
        # background thread finishes, the outcome is posted back into that
        # conversation and the loop resumes. Without this, "I'll continue
        # when the result arrives" was a promise nothing could keep.
        session = _require_agent_session(state, session_id)
        with state._lock:
            record = state._resource_action_runs.get(
                str(payload.get("request_id") or "")
            )
            if record is not None and record.get("status") == "running":
                record["agent_session_id"] = session_id
                record["agent_conversation_id"] = str(
                    session.get("openhands_conversation_id") or ""
                )
        if not already_running:
            _append_agent_message(
                state,
                session_id,
                {
                    "role": "assistant",
                    "title": "Running in the background",
                    "source": "studio_ui",
                    "content": (
                        f"The {action_id} action is running in the background "
                        f"(request {payload.get('request_id')}). Its result will "
                        "be posted into this conversation when it finishes; "
                        "nothing needs to be done meanwhile."
                    ),
                },
            )
        return _tool_result(
            tool,
            True,
            (
                (
                    f"This exact request ({payload.get('request_id')}) is "
                    f"already tracked; current status: "
                    f"{payload.get('status')}. Nothing new was started. Its "
                    "result will be posted into this conversation "
                    "automatically -- do not poll for it in a loop. Tell the "
                    "person, then end your turn."
                )
                if already_running
                else (
                    f"Started {action_id} in the background (request_id "
                    f"{payload.get('request_id')}). Its result will be posted "
                    "into this conversation automatically when it finishes -- do "
                    "not poll for it in a loop. Tell the person it is running, "
                    "then end your turn."
                )
            ),
            data=payload,
        )
    if tool == "optpilot_resource_action_status":
        request_id = str(arguments.get("request_id") or "").strip()
        if not request_id:
            raise ValueError("request_id is required.")
        payload = _resource_action_run_status(state, request_id)
        status = str(payload.get("status") or "")
        summary = {
            "running": "Still running.",
            "succeeded": "The action finished successfully.",
            "failed": f"The action failed: {payload.get('error') or 'see stderr_tail'}.",
        }.get(status, f"Action status: {status or 'unknown'}.")
        return _tool_result(tool, status != "failed", summary, data=payload)
    if tool == "optpilot_compatibility_check":
        environment_ref = arguments.get("environment_ref")
        method_ref = arguments.get("method_ref")
        if (environment_ref is None) != (method_ref is None):
            raise ValueError(
                "environment_ref and method_ref must be provided together."
            )
        if environment_ref is not None:
            data = _compatibility_for_catalog_refs(state, environment_ref, method_ref)
        else:
            data = _compatibility_payload(state)
        return _tool_result(tool, True, "Compatibility checked.", data=data)
    if tool == "optpilot_config_discover":
        workspace_id = str(
            arguments.get("workspace_id")
            or _selected_agent_workspace_id(state, session_id)
        )
        data = _discover_workspace_configs(state, workspace_id)
        return _tool_result(
            tool,
            True,
            f"Discovered {len(data.get('configs', []))} config(s).",
            data=data,
        )
    if tool == "optpilot_config_validate":
        path = _resolve_agent_or_allowed_path(state, session_id, arguments)
        validation = validate_authoring_config(path)
        if validation.get("valid"):
            summary = "Config validation passed."
        else:
            summary = f"Config validation failed: {_validation_error_summary(validation)}. Repair the reported config/source issue and rerun validation."
        return _tool_result(
            tool,
            bool(validation.get("valid")),
            summary,
            data={"validation": validation, "path": str(path)},
        )
    if tool == "optpilot_catalog_setup":
        workspace_id = str(arguments.get("workspace_id") or "").strip()
        role = str(arguments.get("role") or "").strip().lower()
        if not workspace_id or not role:
            raise ValueError("workspace_id and role are required.")
        component_id = str(arguments.get("id") or "").strip()
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={**arguments, "workspace_id": workspace_id, "role": role},
            permission_key="catalog_registration",
            approval_kind="catalog_setup",
            title="Set up Workspace for the Catalog",
            summary=(
                f"Write the {role} starter configuration"
                + (f" '{component_id}'" if component_id else "")
                + " into the Workspace. For a generated simulator with a "
                "policy hook this includes the full policy-search "
                "environment. Files are written into the Workspace only; "
                "nothing is registered yet."
            ),
            targets=[workspace_id],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        configured = _configure_workspace_catalog_role(
            state,
            workspace_id,
            {
                "role": role,
                **({"id": component_id} if component_id else {}),
                **(
                    {"description": str(arguments.get("description"))}
                    if arguments.get("description")
                    else {}
                ),
            },
        )
        configuration = configured.get("configuration") or {}
        created = configuration.get("created_paths") or []
        detected = configuration.get("detected_simulation")
        next_action = str(configuration.get("next_action") or "check")
        summary = (
            f"Wrote {len(created)} file(s) for the {role} role. "
            + (
                "A generated simulation with a policy hook was detected and "
                "the policy-search environment was written. "
                if detected
                else ""
            )
            + (
                "Next: edit the template files it created, then validate."
                if next_action == "edit-template"
                else "Next: prepare and validate the package plan, then apply "
                "it to register."
            )
        )
        return _tool_result(tool, True, summary, data={"configuration": configuration})
    if tool == "optpilot_package_plan_prepare":
        workspace_id = str(
            arguments.get("workspace_id")
            or _selected_agent_workspace_id(state, session_id)
        )
        data = _prepare_package_plan(state, workspace_id, arguments)
        plan = data.get("package_plan", {})
        component_count = len(plan.get("components", []) or [])
        study_count = len(plan.get("studies", []) or [])
        return _tool_result(
            tool,
            True,
            f"Package plan prepared: {plan.get('classification', 'unknown')} with {component_count} component(s) and {study_count} study/studies. Next run package-plan validation.",
            data=data,
        )
    if tool == "optpilot_package_plan_update":
        data = _update_package_plan(
            state,
            str(arguments.get("workspace_id") or ""),
            str(arguments.get("plan_id") or ""),
            arguments,
        )
        return _tool_result(tool, True, "Package plan updated.", data=data)
    if tool == "optpilot_package_plan_validate":
        data = _validate_package_plan(
            state,
            str(arguments.get("workspace_id") or ""),
            str(arguments.get("plan_id") or ""),
        )
        plan = data.get("package_plan", {})
        ok = bool(plan.get("validation", {}).get("valid"))
        if ok:
            warnings = [
                str(item) for item in plan.get("warnings", []) or [] if str(item)
            ]
            summary = f"Package plan validated; readiness is {plan.get('readiness', 'unknown')}."
            if warnings:
                summary += f" Warning: {warnings[0]}"
            if _is_configured_whole_package_plan(plan):
                # A configured whole-package plan is checked statically and
                # apply exempts it from smoke; steering it to the smoke tool
                # sent callers into a step that always refuses.
                summary += " Next run optpilot_package_plan_apply."
            elif plan.get("classification") == "environment-plus-method" and not plan.get(
                "studies"
            ):
                summary += " Next draft a minimal smoke study for the validated environment/method pair, save it under optpilot_configs/studies/, then prepare and validate the package plan again."
            elif plan.get(
                "classification"
            ) == "environment-plus-method" and not plan.get("smoke", {}).get("valid"):
                summary += " Next run optpilot_package_plan_smoke."
        else:
            summary = f"Package plan validation failed: {_validation_error_summary(plan.get('validation', {}) or {})}. Repair missing adapters/source paths/setup files and rerun package-plan validation."
        return _tool_result(tool, ok, summary, data=data)
    if tool == "optpilot_package_plan_smoke":
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments=arguments,
            permission_key="smoke_test",
            approval_kind="package_plan_smoke",
            title="Run package plan smoke study",
            summary="Materialize the package plan in a temporary folder and run the selected smoke study.",
            targets=[str(arguments.get("plan_id") or "")],
            require_approval=_assistant_permission(state, "smoke_test")
            == "approval_required",
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        data = _smoke_package_plan(
            state,
            str(arguments.get("workspace_id") or ""),
            str(arguments.get("plan_id") or ""),
            arguments,
        )
        ok = bool(data.get("smoke", {}).get("valid"))
        if ok:
            summary = "Package plan smoke passed."
        else:
            summary = f"Package plan smoke failed: {_smoke_error_summary(data.get('smoke', {}) or {})}. Repair the failing config, adapter, dependency setup, or study path, then validate and smoke-run the package plan again."
        return _tool_result(tool, ok, summary, data=data)
    if tool == "optpilot_package_plan_apply":
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments=arguments,
            permission_key="catalog_registration",
            approval_kind="package_plan_apply",
            title="Apply package plan",
            summary=(
                "Publish the exact validated artifact as the next canonical "
                "Realm catalog package revision."
            ),
            targets=[str(arguments.get("plan_id") or "")],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        data = _apply_package_plan(
            state,
            str(arguments.get("workspace_id") or ""),
            str(arguments.get("plan_id") or ""),
        )
        return _tool_result(
            tool,
            bool(data.get("applied")),
            "Package plan applied."
            if data.get("applied")
            else "Package plan was not applied.",
            data=data,
        )
    if tool == "optpilot_study_draft":
        draft_arguments = dict(arguments)
        tool_call_id = draft_arguments.pop("_openhands_tool_call_id", None)
        if not draft_arguments.get("workspace_id") and not draft_arguments.get(
            "request_id"
        ):
            draft_arguments["request_id"] = _assistant_workspace_request_id(
                session_id=session_id,
                tool=tool,
                tool_call_id=tool_call_id,
            )
        data = _draft_study(state, draft_arguments)
        return _tool_result(
            tool,
            bool(data.get("validation", {}).get("valid")),
            "Study draft prepared.",
            data=data,
        )
    if tool == "optpilot_study_save":
        workspace, root, path = _resolve_agent_workspace_path(
            state, session_id, arguments
        )
        _require_editable_workspace(workspace)
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={
                **arguments,
                "workspace_id": workspace["id"],
                "path": _relative_path(path, root),
            },
            permission_key="file_write",
            approval_kind="study_save",
            title="Save study YAML",
            summary=f"Save study YAML to {_relative_path(path, root)} in {workspace.get('title') or workspace.get('id')}.",
            targets=[str(root), _relative_path(path, root)],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(str(arguments.get("yaml") or ""), encoding="utf-8")
        return _tool_result(
            tool,
            True,
            f"Saved study YAML to {_relative_path(path, root)}.",
            data={
                "workspace": workspace,
                "path": _relative_path(path, root),
                "validation": _validate_study(path, state=state),
            },
        )
    if tool == "optpilot_study_launch":
        unsupported = sorted(
            key
            for key in ("output_root", "package_root", "realm_root", "operation_id")
            if key in arguments
        )
        if unsupported:
            raise ValueError(
                "Study launch authority is server-derived; unsupported "
                f"assistant fields: {', '.join(unsupported)}."
            )
        study_ref = arguments.get("study_ref")
        workspace_id = str(arguments.get("workspace_id") or "")
        if bool(study_ref) == bool(workspace_id):
            raise ValueError(
                "Pass exactly one of study_ref or workspace_id for study launch."
            )
        # An empty mapping is normalized away: core rejects launch inputs
        # supplied to a study that declares none, and an assistant that
        # habitually sends `inputs: {}` must not trip that error.
        launch_inputs = (
            _canonical_study_launch_inputs(arguments["inputs"])
            if arguments.get("inputs") is not None
            else None
        ) or None
        study_relative_path = ""
        expected_workspace_revision: Optional[int] = None
        if study_ref:
            detail = _catalog_detail(state, "study", study_ref)
            validation = detail["validation"]
            approval_summary = "Launch the exact saved catalog study revision."
            approval_targets = [
                str(
                    (study_ref if isinstance(study_ref, Mapping) else {}).get(
                        "ref_digest"
                    )
                    or "catalog-study-ref"
                )
            ]
        else:
            study_relative_path = _portable_relative_path(
                arguments.get("study_relative_path"), "study_relative_path"
            )
            expected_workspace_revision = arguments.get("expected_workspace_revision")
            if (
                isinstance(expected_workspace_revision, bool)
                or not isinstance(expected_workspace_revision, int)
                or expected_workspace_revision <= 0
            ):
                raise ValueError(
                    "expected_workspace_revision is required for a managed "
                    "workspace study launch."
                )
            workspace = _require_ui_workspace(state, workspace_id)
            if workspace.get("ownership") != "realm-managed":
                raise ValueError(
                    "Assistant study launch requires a Realm-managed workspace."
                )
            if int(workspace.get("realm_workspace_revision") or 0) != (
                expected_workspace_revision
            ):
                raise RealmConflict("Workspace revision changed.")
            if workspace.get("reopen_required"):
                workspace = _reopen_managed_workspace(
                    state,
                    workspace_id,
                    {
                        "expected_workspace_revision": expected_workspace_revision,
                    },
                )
            root = _safe_workspace_root(state, Path(str(workspace["root"])).resolve())
            study_path = (
                root / Path(*PurePosixPath(study_relative_path).parts)
            ).resolve()
            if not _is_relative_to(study_path, root) or not study_path.is_file():
                raise FileNotFoundError(
                    "The managed workspace study config is unavailable."
                )
            validation = _public_workspace_value(
                _validate_study(study_path, state=state),
                workspace_id=workspace_id,
                root=root,
            )
            approval_summary = (
                f"Launch {study_relative_path} from managed workspace {workspace_id}."
            )
            approval_targets = [
                f"workspace:{workspace_id}@{expected_workspace_revision}",
                study_relative_path,
            ]
        blocked = _study_launch_block(validation, launch_inputs=launch_inputs)
        if blocked is not None:
            reason = str(blocked.get("reason") or "Study launch preflight failed.")
            return _tool_result(
                tool,
                False,
                f"Study launch blocked: {reason}",
                data={"validation": validation, "capability": blocked},
                remedy=_study_launch_block_remedy(blocked),
            )
        if launch_inputs:
            # The approver decides on the problem payload, not just the study
            # identity, so the bound values belong on the card itself.
            rendered_inputs = _study_launch_input_display(launch_inputs)
            approval_summary = (
                f"{approval_summary} Inputs: {'; '.join(rendered_inputs)}."
            )
            approval_targets = approval_targets + [
                f"input:{item}" for item in rendered_inputs
            ]
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments=arguments,
            permission_key="study_launch",
            approval_kind="study_launch",
            title="Launch OptPilot study",
            summary=approval_summary,
            targets=approval_targets,
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        job = (
            state.launch_study(catalog_entry=study_ref, launch_inputs=launch_inputs)
            if study_ref
            else state.launch_study(
                workspace_id=workspace_id,
                study_relative_path=study_relative_path,
                expected_workspace_revision=expected_workspace_revision,
                launch_inputs=launch_inputs,
            )
        )
        return _tool_result(
            tool,
            True,
            "Study launched.",
            data={"job": job.to_dict(), "validation": validation},
        )
    if tool == "optpilot_job_stop":
        launch_id = str(arguments.get("job_id") or "").strip()
        if not launch_id:
            raise ValueError("job_id is required.")
        if _assistant_permission(state, "job_stop") == "disabled":
            return _agent_permission_blocked_result(tool, "job_stop")
        try:
            launch = _study_launch_service_for_state(state).read(launch_id=launch_id)
        except RealmNotFound:
            return _tool_result(
                tool,
                False,
                "Study launch was not found.",
                data={
                    "reason": "study_launch_not_found",
                    "can_stop": False,
                },
            )
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={"job_id": launch.launch_id},
            permission_key="job_stop",
            approval_kind="study_launch_stop",
            title="Stop OptPilot study launch",
            summary=(
                "Cancel the durable study launch or its handed-off canonical run."
            ),
            targets=[launch.launch_id],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        job = state.stop_job(launch.launch_id)
        return _tool_result(
            tool,
            True,
            "Study cancellation requested.",
            data={"job": job, "can_stop": bool(job.get("can_stop"))},
        )
    if tool == "optpilot_run_list":
        data = _realm_runs_payload(state)
        return _tool_result(tool, True, f"Found {len(data['runs'])} run(s).", data=data)
    if tool == "optpilot_run_detail":
        run_id = _required_canonical_run_id(arguments)
        return _tool_result(
            tool,
            True,
            "Bounded Realm Workbench detail loaded.",
            data=_realm_run_detail(state, ref=RunViewRef(run_id=run_id)),
        )
    if tool == "optpilot_run_file_read":
        return _tool_result(
            tool,
            False,
            "Raw run-file reads are unavailable for canonical Realm runs.",
            data={
                "supported": False,
                "reason": "raw_run_file_access_removed",
                "guidance": "Use optpilot_run_detail and bounded Workbench selections.",
            },
            remedy=_remedy(
                "Read the Run through its own tool instead. Nothing is broken "
                "and retrying this will not start working.",
                tool="optpilot_run_detail",
                arguments={"run_id": str(arguments.get("run_id") or "")},
            ),
        )
    if tool == "optpilot_run_compare":
        requested = arguments.get("runs", [])
        if not isinstance(requested, list) or not requested:
            raise ValueError("runs must contain at least one canonical run id.")
        if len(requested) > 20:
            raise ValueError("At most 20 runs can be compared at once.")
        runs = [
            _realm_run_comparison_record(state, run_id=str(run_id))
            for run_id in requested
        ]
        return _tool_result(
            tool,
            True,
            f"Compared {len(runs)} run(s).",
            data={
                "runs": [_run_compare_summary(run) for run in runs],
                "comparable": _runs_comparable(runs),
            },
        )
    if tool == "optpilot_smoke_test_study":
        return _agent_tool_smoke_test_study(
            state, session_id, tool, arguments, execution_context=execution_context
        )
    if tool == "optpilot_interface_launch":
        kind = str(arguments.get("config_kind") or arguments.get("kind") or "")
        uid = str(arguments.get("uid") or "")
        if not kind or not uid:
            raise ValueError("config_kind and uid are required.")
        entry_label = uid
        # Ask whether this CAN launch before asking the person to approve it.
        # Studio already computes that answer, with a reason, and the Catalog
        # page shows it -- but this tool went straight to the approval card, so
        # a person was asked to approve a launch that was known to fail, it
        # failed, the model asked again, and the loop ran until someone gave
        # up. Approving something is a decision; being asked to decide the same
        # doomed thing repeatedly is not.
        blocked = _interface_launch_blocked_reason(state, kind, uid)
        if blocked:
            return _tool_result(
                tool,
                False,
                blocked,
                data={"remedy": {"kind": "configure_environment", "reason": blocked}},
            )
        gate = _agent_permission_gate(
            state,
            session_id,
            tool=tool,
            arguments={**arguments, "config_kind": kind, "uid": uid},
            permission_key="interface_launch",
            approval_kind="interface_launch",
            title="Open a component's interface",
            summary=(
                f"Start the web interface declared by {entry_label} in a "
                "container, with the credentials it declares."
            ),
            targets=[entry_label],
            execution_context=execution_context,
        )
        if gate is not None:
            return gate
        launched = _start_catalog_interface_launch(
            state,
            kind,
            uid,
            profile_id=str(arguments.get("profile_id") or "") or None,
        )
        launch = launched.get("launch") if isinstance(launched, dict) else {}
        launch_id = str((launch or {}).get("id") or (launch or {}).get("launch_id") or "")
        return _tool_result(
            tool,
            True,
            (
                f"Opening the interface for {entry_label}. It takes a few "
                "seconds to become reachable; check optpilot_interface_status "
                f"with launch_id {launch_id}."
            ),
            data={"launch": launch, "launch_id": launch_id},
        )
    if tool == "optpilot_interface_status":
        launch_id = str(arguments.get("launch_id") or "")
        if not launch_id:
            raise ValueError("launch_id is required.")
        launch = _interface_launch_by_id(state, launch_id)
        status = str((launch or {}).get("status") or "unknown")
        url = str((launch or {}).get("url") or (launch or {}).get("preview_url") or "")
        ready = status in {"ready", "running"}
        summary = (
            f"The interface is ready at {url}." if ready and url
            else f"The interface is {status}."
        )
        return _tool_result(tool, True, summary, data={"launch": launch})
    if tool == "optpilot_docs_search":
        results = _docs_search(
            state,
            str(arguments.get("query") or ""),
            limit=int(arguments.get("limit") or 5),
        )
        return _tool_result(
            tool,
            True,
            f"Found {len(results)} doc result(s).",
            data={"results": results},
        )
    if tool == "optpilot_capability_list":
        data = _assistant_capability_list(
            state, str(arguments.get("capability_kind") or arguments.get("kind") or "")
        )
        total = sum(len(records) for records in data.get("capabilities", {}).values())
        return _tool_result(
            tool,
            True,
            f"Found {total} configured assistant capability record(s).",
            data=data,
        )
    if tool == "optpilot_capability_detail":
        data = _assistant_capability_detail(
            state,
            str(arguments.get("capability_kind") or arguments.get("kind") or ""),
            str(arguments.get("id") or ""),
        )
        return _tool_result(tool, True, "Assistant capability loaded.", data=data)
    return _tool_result(
        tool,
        False,
        f"Unknown OptPilot assistant tool: {tool}",
        data={"known_tools": state.agent_adapter.status().get("available_tools", [])},
    )


def _selected_agent_workspace_id(state: UiState, session_id: str) -> str:
    session = _require_agent_session(state, session_id)
    selected = str(session.get("selected_workspace_id") or "")
    attached = [str(item) for item in session.get("attached_workspace_ids", []) or []]
    if selected and selected in attached:
        return selected
    if attached:
        raise ValueError(
            "No workspace is selected for this assistant session. Pass workspace_id explicitly or focus a workspace first."
        )
    raise ValueError("No workspace is attached to this assistant session.")


#: Files whose whole purpose is to hold a credential. Reading one through an
#: Assistant tool puts its contents into the conversation, and from there into
#: whichever model provider the person configured -- which is how this project
#: published eleven live API keys once already.
#:
#: Matched on the file name alone, case-insensitively, so it holds wherever the
#: file sits. Deliberately a denylist of well-known names rather than content
#: sniffing: a name test cannot be argued with, and a file that merely mentions
#: a key is a different problem from a file that exists to store one.
SECRET_FILE_NAMES = frozenset(
    {
        ".env",
        ".envrc",
        ".netrc",
        "_netrc",
        ".npmrc",
        ".pypirc",
        ".git-credentials",
        ".htpasswd",
        "credentials",
        "id_rsa",
        "id_dsa",
        "id_ecdsa",
        "id_ed25519",
        "secrets.json",
        "secrets.yaml",
        "secrets.yml",
    }
)

#: Suffixes that name a key or certificate store regardless of the stem.
SECRET_FILE_SUFFIXES = (".pem", ".key", ".p12", ".pfx", ".jks", ".keystore")

#: Stems whose every variant is a credential file: `.env.local`,
#: `.env.production`, `id_rsa.bak`, and so on.
SECRET_FILE_PREFIXES = (".env.", "id_rsa.", "id_ed25519.")


def _is_secret_file(path: Path) -> bool:
    name = path.name.lower()
    if name in SECRET_FILE_NAMES:
        return True
    if name.endswith(SECRET_FILE_SUFFIXES):
        return True
    if name.startswith(SECRET_FILE_PREFIXES):
        return True
    # An SSH private key is the file inside .ssh that has no .pub twin; the
    # common names are listed above, but the directory itself is never a place
    # an Assistant needs to read from.
    return ".ssh" in {part.lower() for part in path.parts}


def _refuse_secret_file(path: Path, root: Path) -> None:
    """Stop before a credential file's contents enter the conversation."""

    if not _is_secret_file(path):
        return
    relative = _relative_path(path, root)
    raise _with_remedy(
        PermissionError(
            f"{relative} holds credentials, so OptPilot will not read or "
            "change it through the Assistant. Anything the Assistant reads is "
            "sent to the configured model provider. Open it yourself if you "
            "need to see it, and set values OptPilot should use in Studio "
            "Settings instead."
        ),
        _remedy(
            "There is no way to read this file through the Assistant, and no "
            "point retrying. If a config needs one of these values, declare "
            "the name it should be read from and ask the person to set it "
            "under Local environment variables in Settings.",
            details={"path": relative, "reason": "holds_credentials"},
        ),
    )


def _resolve_agent_workspace_path(
    state: UiState,
    session_id: str,
    arguments: JsonDict,
    *,
    default_path: Optional[str] = None,
) -> tuple[JsonDict, Path, Path]:
    workspace_id = str(
        arguments.get("workspace_id") or _selected_agent_workspace_id(state, session_id)
    )
    session = _require_agent_session(state, session_id)
    if workspace_id not in (session.get("attached_workspace_ids", []) or []):
        raise PermissionError("Workspace is not attached to this assistant session.")
    workspace = _require_ui_workspace(state, workspace_id)
    root = _safe_workspace_root(state, Path(str(workspace["root"]))).resolve()
    raw_path = arguments.get("path")
    if raw_path in (None, "") and default_path is not None:
        raw_path = default_path
    if raw_path in (None, ""):
        raise ValueError("path is required.")
    requested = Path(str(raw_path)).expanduser()
    target = requested if requested.is_absolute() else root / requested
    target = target.resolve()
    if not _is_relative_to(target, root):
        raise PermissionError("Path is outside the attached workspace root.")
    return workspace, root, target


def _require_editable_workspace(workspace: JsonDict) -> None:
    if str(workspace.get("mode") or "editable") != "editable":
        raise PermissionError(
            "This workspace is read-only; attach an editable copy before writing."
        )


def _workspace_file_tree(root: Path, target: Path, *, max_files: int) -> List[JsonDict]:
    if target.is_file():
        stat = target.stat()
        return [
            {"path": _relative_path(target, root), "type": "file", "size": stat.st_size}
        ]
    if not target.exists() or not target.is_dir():
        raise FileNotFoundError(_relative_path(target, root))
    files: List[JsonDict] = []
    stack = [target]
    while stack and len(files) < max_files:
        current = stack.pop()
        try:
            entries = sorted(
                current.iterdir(),
                key=lambda item: (not item.is_dir(), item.name.lower()),
            )
        except OSError:
            continue
        for child in entries:
            if child.name in EXCLUDED_SCAN_DIRS:
                continue
            resolved = child.resolve()
            if not _is_relative_to(resolved, root):
                continue
            if child.is_dir():
                files.append(
                    {"path": _relative_path(resolved, root), "type": "directory"}
                )
                stack.append(resolved)
            elif child.is_file():
                stat = child.stat()
                files.append(
                    {
                        "path": _relative_path(resolved, root),
                        "type": "file",
                        "size": stat.st_size,
                    }
                )
            if len(files) >= max_files:
                break
    return files


def _resolve_agent_or_allowed_path(
    state: UiState, session_id: str, arguments: JsonDict
) -> Path:
    raw_path = arguments.get("path") or arguments.get("study_path")
    if not raw_path:
        raise ValueError("path is required.")
    workspace_id = str(arguments.get("workspace_id") or "")
    if workspace_id:
        return _resolve_agent_workspace_path(
            state, session_id, {**arguments, "path": raw_path}
        )[2]
    requested = Path(str(raw_path)).expanduser()
    if not requested.is_absolute():
        try:
            selected_workspace_id = _selected_agent_workspace_id(state, session_id)
            workspace = _require_ui_workspace(state, selected_workspace_id)
            root = _safe_workspace_root(state, Path(str(workspace["root"]))).resolve()
            workspace_candidate = (root / requested).resolve()
            if (
                _is_relative_to(workspace_candidate, root)
                and workspace_candidate.exists()
            ):
                return workspace_candidate
        except Exception:
            pass
    candidate = _resolve_user_path(raw_path, state.cwd)
    allowed_roots = [
        state.cwd,
        *state.catalog_roots,
        *state.run_roots,
        state.sessions_dir,
        state.workspaces_dir,
    ]
    if any(_is_relative_to(candidate, root.resolve()) for root in allowed_roots):
        return candidate
    raise PermissionError(f"Path is outside OptPilot-controlled roots: {candidate}")


def _agent_tool_workspace_preview_open(
    state: UiState, session_id: str, tool: str, arguments: JsonDict
) -> JsonDict:
    workspace, root, _ = _resolve_agent_workspace_path(
        state,
        session_id,
        {**arguments, "path": "."},
        default_path=".",
    )
    port = int(arguments.get("port") or 0)
    extra_ports = (
        arguments.get("extra_ports")
        if isinstance(arguments.get("extra_ports"), list)
        else []
    )
    result = state.workspace_preview_open(root, port, extra_ports=extra_ports)
    return _tool_result(
        tool,
        True,
        f"Workspace preview opened on port {port}.",
        data={
            **result,
            "workspace": workspace,
        },
    )


def _agent_tool_openhands_terminal(
    state: UiState,
    session_id: str,
    tool: str,
    arguments: JsonDict,
    *,
    execution_context: Optional[ToolExecutionContext] = None,
) -> JsonDict:
    if arguments.get("is_input"):
        raise ValueError(
            "Studio-backed terminal does not support interactive stdin. Run a complete command instead."
        )
    if arguments.get("reset"):
        return _tool_result(
            tool,
            True,
            "Studio-backed terminal is stateless; reset is a no-op.",
            data={"reset": True},
        )
    command = str(arguments.get("command") or "").strip()
    if not command:
        raise ValueError("command is required.")
    timeout_seconds = arguments.get("timeout_seconds")
    if timeout_seconds in (None, ""):
        timeout_seconds = arguments.get("timeout")
    if timeout_seconds in (None, ""):
        timeout_seconds = 30
    return _agent_tool_shell_run(
        state,
        session_id,
        tool,
        {
            **arguments,
            "command": ["sh", "-lc", command],
            "timeout_seconds": int(timeout_seconds),
            "description": str(
                arguments.get("description")
                or f"Run terminal command: {_cap_text(command, 120)}"
            ),
        },
        execution_context=execution_context,
    )


def _agent_tool_openhands_file_editor(
    state: UiState,
    session_id: str,
    tool: str,
    arguments: JsonDict,
    *,
    execution_context: Optional[ToolExecutionContext] = None,
) -> JsonDict:
    command = str(arguments.get("command") or "").strip()
    if command not in {"view", "create", "str_replace", "insert"}:
        raise ValueError(
            "file_editor command must be one of: view, create, str_replace, insert."
        )
    workspace, root, path = _resolve_agent_workspace_path(state, session_id, arguments)
    # Covers every command: viewing a credential file leaks it, and creating
    # or editing one is not the Assistant's to do either.
    _refuse_secret_file(path, root)
    if command == "view":
        return _agent_file_editor_view(tool, workspace, root, path, arguments)
    _require_editable_workspace(workspace)
    gate = _agent_permission_gate(
        state,
        session_id,
        tool=tool,
        arguments={
            **arguments,
            "workspace_id": workspace["id"],
            "path": _relative_path(path, root),
        },
        permission_key="file_write",
        approval_kind="file_write",
        title="Edit workspace file",
        summary=f"Edit {_relative_path(path, root)} in {workspace.get('title') or workspace.get('id')}.",
        targets=[str(root), _relative_path(path, root)],
        execution_context=execution_context,
    )
    if gate is not None:
        return gate
    if command == "create":
        return _agent_file_editor_create(tool, workspace, root, path, arguments)
    if command == "str_replace":
        return _agent_file_editor_str_replace(tool, workspace, root, path, arguments)
    return _agent_file_editor_insert(tool, workspace, root, path, arguments)


def _agent_file_editor_view(
    tool: str, workspace: JsonDict, root: Path, path: Path, arguments: JsonDict
) -> JsonDict:
    if path.is_dir():
        files = _workspace_file_tree(
            root,
            path,
            max_files=min(max(int(arguments.get("max_files") or 200), 1), 500),
        )
        return _tool_result(
            tool,
            True,
            f"Listed directory {_relative_path(path, root)}.",
            data={
                "workspace": workspace,
                "path": _relative_path(path, root),
                "type": "directory",
                "files": files,
            },
        )
    if not path.is_file():
        raise FileNotFoundError(_relative_path(path, root))
    if path.stat().st_size > 1_000_000:
        raise ValueError("File is too large to view through file_editor.")
    content = path.read_text(encoding="utf-8", errors="replace")
    start_line, end_line, view_content = _file_editor_view_slice(
        content, arguments.get("view_range")
    )
    return _tool_result(
        tool,
        True,
        f"Viewed {_relative_path(path, root)}.",
        data={
            "workspace": workspace,
            "path": _relative_path(path, root),
            "type": "file",
            "content": view_content,
            "numbered_content": _numbered_file_content(view_content, start_line),
            "view_range": [start_line, end_line],
            "total_lines": len(content.splitlines()),
        },
    )


def _agent_file_editor_create(
    tool: str, workspace: JsonDict, root: Path, path: Path, arguments: JsonDict
) -> JsonDict:
    if path.exists():
        raise FileExistsError(f"File already exists: {_relative_path(path, root)}")
    file_text = str(arguments.get("file_text") or "")
    if len(file_text.encode("utf-8")) > 2_000_000:
        raise ValueError("file_text is too large to write through file_editor.")
    path.parent.mkdir(parents=True, exist_ok=True)
    _atomic_write_text(path, file_text)
    return _tool_result(
        tool,
        True,
        f"Created {_relative_path(path, root)}.",
        data={
            "workspace": workspace,
            "path": _relative_path(path, root),
            "bytes": len(file_text.encode("utf-8")),
        },
    )


def _agent_file_editor_str_replace(
    tool: str, workspace: JsonDict, root: Path, path: Path, arguments: JsonDict
) -> JsonDict:
    if not path.is_file():
        raise FileNotFoundError(_relative_path(path, root))
    old_str = arguments.get("old_str")
    if old_str in (None, ""):
        raise ValueError("old_str is required for str_replace.")
    if "new_str" not in arguments:
        raise ValueError("new_str is required for str_replace.")
    old_str = str(old_str)
    new_str = str(arguments.get("new_str") or "")
    if new_str == old_str:
        raise ValueError("new_str and old_str must be different.")
    content = path.read_text(encoding="utf-8", errors="replace")
    count = content.count(old_str)
    if count == 0:
        raise ValueError("old_str was not found in the file.")
    if count > 1:
        raise ValueError(f"old_str must match exactly once; found {count} matches.")
    updated = content.replace(old_str, new_str, 1)
    _atomic_write_text(path, updated)
    diff = "".join(
        difflib.unified_diff(
            content.splitlines(True),
            updated.splitlines(True),
            fromfile=f"a/{_relative_path(path, root)}",
            tofile=f"b/{_relative_path(path, root)}",
        )
    )
    return _tool_result(
        tool,
        True,
        f"Replaced text in {_relative_path(path, root)}.",
        data={"workspace": workspace, "path": _relative_path(path, root), "diff": diff},
    )


def _agent_file_editor_insert(
    tool: str, workspace: JsonDict, root: Path, path: Path, arguments: JsonDict
) -> JsonDict:
    if not path.is_file():
        raise FileNotFoundError(_relative_path(path, root))
    if "insert_line" not in arguments:
        raise ValueError("insert_line is required for insert.")
    if "new_str" not in arguments:
        raise ValueError("new_str is required for insert.")
    insert_line = int(arguments.get("insert_line"))
    content = path.read_text(encoding="utf-8", errors="replace")
    lines = content.splitlines(keepends=True)
    if insert_line < 0 or insert_line > len(lines):
        raise ValueError(f"insert_line must be between 0 and {len(lines)}.")
    insert_lines = [
        line + "\n" for line in str(arguments.get("new_str") or "").split("\n")
    ]
    updated = (
        "".join(lines[:insert_line])
        + "".join(insert_lines)
        + "".join(lines[insert_line:])
    )
    _atomic_write_text(path, updated)
    diff = "".join(
        difflib.unified_diff(
            content.splitlines(True),
            updated.splitlines(True),
            fromfile=f"a/{_relative_path(path, root)}",
            tofile=f"b/{_relative_path(path, root)}",
        )
    )
    return _tool_result(
        tool,
        True,
        f"Inserted text in {_relative_path(path, root)}.",
        data={"workspace": workspace, "path": _relative_path(path, root), "diff": diff},
    )


def _file_editor_view_slice(content: str, raw_range: Any) -> tuple[int, int, str]:
    lines = content.splitlines()
    total = len(lines)
    if not isinstance(raw_range, list) or not raw_range:
        start, end = 1, total
    else:
        if len(raw_range) != 2:
            raise ValueError("view_range must be a list of two integers.")
        start = int(raw_range[0]) if len(raw_range) >= 1 else 1
        end = int(raw_range[1]) if len(raw_range) >= 2 else start
        if end == -1:
            end = total
    if total == 0:
        return 1, 0, ""
    if start < 1 or start > total:
        raise ValueError(f"view_range start must be between 1 and {total}.")
    if end < start:
        raise ValueError("view_range end must be greater than or equal to start.")
    end = min(end, total)
    return start, end, "\n".join(lines[start - 1 : end])


def _numbered_file_content(content: str, start_line: int) -> str:
    if not content:
        return ""
    return "\n".join(
        f"{index:6}\t{line}"
        for index, line in enumerate(content.splitlines(), start=start_line)
    )


def _atomic_write_text(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        mode="w",
        dir=path.parent,
        prefix=f".{path.name}.",
        suffix=".tmp",
        encoding="utf-8",
        delete=False,
    ) as handle:
        handle.write(content)
        tmp_path = Path(handle.name)
    try:
        if path.exists():
            os.chmod(tmp_path, path.stat().st_mode & 0o7777)
        tmp_path.replace(path)
    except BaseException:
        tmp_path.unlink(missing_ok=True)
        raise


def _agent_tool_shell_run(
    state: UiState,
    session_id: str,
    tool: str,
    arguments: JsonDict,
    *,
    execution_context: Optional[ToolExecutionContext] = None,
) -> JsonDict:
    workspace, root, cwd = _resolve_agent_workspace_path(
        state,
        session_id,
        {**arguments, "path": arguments.get("cwd") or arguments.get("path") or "."},
        default_path=".",
    )
    _require_editable_workspace(workspace)
    if cwd.is_file():
        cwd = cwd.parent
    if not cwd.exists() or not cwd.is_dir():
        raise FileNotFoundError(_relative_path(cwd, root))
    command = _normalize_shell_command(arguments.get("command"))
    if not command:
        raise ValueError("command is required.")
    timeout_seconds = min(max(int(arguments.get("timeout_seconds") or 30), 1), 120)
    permission = _assistant_permission(state, "shell_run")
    gate = _agent_permission_gate(
        state,
        session_id,
        tool=tool,
        arguments={
            **arguments,
            "workspace_id": workspace["id"],
            "command": command,
            "cwd": _relative_path(cwd, root),
            "timeout_seconds": timeout_seconds,
        },
        permission_key="shell_run",
        approval_kind="shell_run",
        title="Run workspace command",
        summary=f"Run {' '.join(shlex.quote(part) for part in command)} in {workspace.get('title') or workspace.get('id')}.",
        targets=[str(root), _relative_path(cwd, root)],
        require_approval=permission == "approval_required"
        or (permission == "safe_without_approval" and _shell_needs_approval(command)),
        execution_context=execution_context,
    )
    if gate is not None:
        return gate
    env = {
        key: value
        for key, value in os.environ.items()
        if key in {"LANG", "LC_ALL", "UV_CACHE_DIR"}
    }
    env["OPTPILOT_WORKSPACE_ROOT"] = str(root)
    env["OPTPILOT_STUDIO_ROOT"] = str(state.cwd)
    completed, runtime_status = state.workspace_runtime.exec(
        workspace,
        command,
        cwd=cwd,
        env=env,
        timeout=timeout_seconds,
    )
    return _tool_result(
        tool,
        completed.returncode == 0,
        f"Command exited with {completed.returncode}.",
        data={
            "workspace": workspace,
            "runtime": runtime_status,
            "cwd": _relative_path(cwd, root),
            "command": command,
            "returncode": completed.returncode,
            "stdout": _cap_text(completed.stdout, 12000),
            "stderr": _cap_text(completed.stderr, 12000),
        },
    )


def _normalize_shell_command(raw: Any) -> List[str]:
    if isinstance(raw, str):
        return shlex.split(raw)
    if isinstance(raw, list):
        return [str(item) for item in raw if str(item)]
    raise ValueError("command must be a string or list of strings.")


def _shell_needs_approval(command: List[str]) -> bool:
    return _shell_needs_approval_inner(command, depth=0)


def _shell_needs_approval_inner(command: List[str], *, depth: int) -> bool:
    if not command:
        return False
    first = Path(command[0]).name
    tokens = {item.lower() for item in command[1:]}
    # The file tools refuse credential files outright. A shell command can
    # read one in too many ways to block them all, so this does the one thing
    # that is actually reliable: it makes sure a person sees the command
    # first, even for someone who allowed unattended shell commands.
    if any(_is_secret_file(Path(item)) for item in command[1:]):
        return True
    shell_payload = _shell_wrapper_payload(command)
    if shell_payload and depth < 2:
        if _shell_payload_text_needs_approval(shell_payload):
            return True
        try:
            nested_command = shlex.split(shell_payload)
        except ValueError:
            nested_command = []
        if nested_command and _shell_needs_approval_inner(
            nested_command, depth=depth + 1
        ):
            return True
    if first in {
        "curl",
        "wget",
        "brew",
        "docker",
        "podman",
        "pip",
        "pip3",
        "rm",
        "mv",
        "cp",
        "chmod",
        "chown",
    }:
        return True
    if first in {"python", "python3", Path(sys.executable).name} and len(command) >= 4:
        if command[1] == "-m" and command[2] in {"pip", "pip3"}:
            return True
    if first in {"npm", "pnpm", "yarn"}:
        return True
    if first == "git":
        return len(command) > 1 and command[1] in {
            "clone",
            "push",
            "pull",
            "fetch",
            "reset",
            "checkout",
            "clean",
            "merge",
            "rebase",
        }
    if first == "uv":
        risky = {"add", "remove", "sync", "lock", "tool", "pip", "build", "publish"}
        return bool(
            tokens.intersection(risky) or "install" in tokens or "--with" in tokens
        )
    return False


def _shell_wrapper_payload(command: List[str]) -> str:
    if not command:
        return ""
    first = Path(command[0]).name
    if first not in {"sh", "bash", "zsh"}:
        return ""
    for index, token in enumerate(command[1:], start=1):
        if token == "-c" or (token.startswith("-") and "c" in token):
            if index + 1 < len(command):
                return str(command[index + 1])
            return ""
    return ""


def _shell_payload_text_needs_approval(payload: str) -> bool:
    text = payload.strip().lower()
    if not text:
        return False
    risky_patterns = [
        r"(^|[;&|()])\s*(?:\.?/[\w./-]+/)?pip3?\s+",
        r"(^|[;&|()])\s*(?:python3?|python[\w.-]*)\s+-m\s+pip3?\s+",
        r"(^|[;&|()])\s*uv\s+(?:add|remove|sync|lock|tool|pip|build|publish)\b",
        r"(^|[;&|()])\s*(?:npm|pnpm|yarn)\s+",
        r"(^|[;&|()])\s*(?:curl|wget|brew|docker|podman|rm|mv|cp|chmod|chown)\s+",
        r"(^|[;&|()])\s*git\s+(?:clone|push|pull|fetch|reset|checkout|clean|merge|rebase)\b",
    ]
    return any(re.search(pattern, text) for pattern in risky_patterns)


def _agent_tool_smoke_test_study(
    state: UiState,
    session_id: str,
    tool: str,
    arguments: JsonDict,
    *,
    execution_context: Optional[ToolExecutionContext] = None,
) -> JsonDict:
    study_path = _resolve_agent_or_allowed_path(
        state,
        session_id,
        {
            "path": arguments.get("study_path"),
            "workspace_id": arguments.get("workspace_id"),
        },
    )
    package_root = _assistant_study_package_root(
        state,
        session_id,
        study_path,
    )
    validation = _validate_study(study_path, state=state)
    if not validation.get("valid"):
        return _tool_result(
            tool,
            False,
            "Study validation failed; smoke test blocked.",
            data={"validation": validation},
            remedy=_remedy(
                "Fix what the run setup reports before smoke testing it. The "
                f"errors are in `validation`, for {study_path.name}.",
                tool="optpilot_config_validate",
                arguments={"path": str(study_path)},
                details={
                    "path": str(study_path),
                    "errors": [
                        str(item)
                        for item in (validation.get("errors") or [])
                        if str(item)
                    ][:5],
                },
            ),
        )
    gate = _agent_permission_gate(
        state,
        session_id,
        tool=tool,
        arguments={**arguments, "study_path": str(study_path)},
        permission_key="smoke_test",
        approval_kind="smoke_test_study",
        title="Run study smoke test",
        summary=f"Execute {study_path.name} in a temporary private Realm.",
        targets=[str(study_path)],
        require_approval=_assistant_permission(state, "smoke_test")
        == "approval_required",
        execution_context=execution_context,
    )
    if gate is not None:
        return gate
    with tempfile.TemporaryDirectory(prefix="optpilot-assistant-smoke-") as tmp_dir:
        tmp = Path(tmp_dir)
        smoke_package, smoke_study = _prepare_assistant_smoke_package(
            package_root=package_root,
            study_path=study_path,
            temporary_root=tmp,
            max_trials=_assistant_smoke_trial_limit(arguments.get("max_trials")),
        )
        smoke = _run_temporary_realm_smoke(
            state,
            package_root=smoke_package,
            study_path=smoke_study,
            temporary_root=tmp,
            timeout_seconds=min(
                max(int(arguments.get("timeout_seconds") or 120), 10),
                300,
            ),
        )
    return _tool_result(
        tool,
        bool(smoke.get("valid")),
        "Smoke test passed." if smoke.get("valid") else "Smoke test failed.",
        data={"validation": validation, **smoke},
    )


def _apply_smoke_trial_limit(study_path: Path, max_trials: int) -> None:
    if max_trials <= 0:
        return
    raw = _read_yaml(study_path)
    raw.setdefault("budget", {})["maxTrials"] = max_trials
    study_path.write_text(yaml.safe_dump(raw, sort_keys=False), encoding="utf-8")


def _prepare_assistant_smoke_package(
    *,
    package_root: Path,
    study_path: Path,
    temporary_root: Path,
    max_trials: int,
) -> tuple[Path, Path]:
    """Copy the package aside and cap its trials, so the smoke touches neither.

    The limit is normalised here rather than trusted from the caller: a smoke
    test runs without asking the person, so losing its bound must not be one
    mistaken argument away. Passing nothing meaningful gets the default limit,
    not an unlimited run against the person's own folder -- which is what this
    did before.

    The study is guaranteed to sit inside ``package_root`` because callers
    resolve it with ``_most_specific_study_package_root``.
    """

    max_trials = _assistant_smoke_trial_limit(max_trials)
    relative_study = study_path.resolve().relative_to(package_root.resolve())
    copied_package = temporary_root / "package"
    shutil.copytree(
        package_root,
        copied_package,
        symlinks=True,
        ignore=shutil.ignore_patterns(
            ".git",
            ".optpilot",
            ".optpilot-ui",
            ".venv",
            "__pycache__",
            "node_modules",
            "runs",
        ),
    )
    copied_study = copied_package / relative_study
    _apply_smoke_trial_limit(copied_study, max_trials)
    return copied_package, copied_study


def _redact_temporary_path(value: Any, temporary_root: Path) -> str:
    return str(value or "").replace(str(temporary_root), "<temporary>")


def _process_error_summary(
    *,
    stderr: Any,
    stdout: Any,
    returncode: Any,
) -> str:
    text = str(stderr or stdout or "").strip()
    if text:
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        if lines:
            return lines[-1]
    return f"exit code {returncode}"


def _run_temporary_realm_smoke(
    state: UiState,
    *,
    package_root: Path,
    study_path: Path,
    temporary_root: Path,
    timeout_seconds: int,
) -> JsonDict:
    operation_id = new_local_study_operation_id()
    run_id = local_study_run_id_for_operation(operation_id)
    realm_root = temporary_root / "realm"
    command = [
        sys.executable,
        "-m",
        "optpilot",
        "run",
        str(study_path),
        "--package-root",
        str(package_root),
        "--realm-root",
        str(realm_root),
        "--operation-id",
        operation_id,
    ]
    try:
        completed = subprocess.run(
            command,
            cwd=str(state.cwd),
            env=_study_subprocess_env(state, study_path),
            text=True,
            capture_output=True,
            timeout=timeout_seconds,
            check=False,
        )
    except subprocess.TimeoutExpired as exc:
        return {
            "valid": False,
            "run_id": run_id,
            "returncode": None,
            "summary": {},
            "stdout": _cap_text(
                _redact_temporary_path(exc.stdout, temporary_root),
                8000,
            ),
            "stderr": _cap_text(
                _redact_temporary_path(
                    _process_error_summary(
                        stderr=exc.stderr,
                        stdout="",
                        returncode="timeout",
                    )
                    if exc.stderr
                    else "",
                    temporary_root,
                ),
                2000,
            ),
            "errors": [f"Smoke study timed out after {timeout_seconds} seconds."],
        }
    except Exception as exc:
        return {
            "valid": False,
            "run_id": run_id,
            "returncode": None,
            "summary": {},
            "stdout": "",
            "stderr": "",
            "errors": [
                _redact_temporary_path(
                    str(exc) or type(exc).__name__,
                    temporary_root,
                )
            ],
        }

    summary = _stdout_run_summary_projection(
        _parse_smoke_summary(completed.stdout),
        expected_run_id=run_id,
    )
    errors = _smoke_summary_errors(completed, summary, study_path)
    return {
        "valid": not errors,
        "run_id": run_id,
        "returncode": completed.returncode,
        "summary": summary,
        "stdout": _cap_text(
            _redact_temporary_path(completed.stdout, temporary_root),
            8000,
        ),
        "stderr": _redact_temporary_path(
            _process_error_summary(
                stderr=completed.stderr,
                stdout="",
                returncode=completed.returncode,
            )
            if completed.stderr
            else "",
            temporary_root,
        ),
        "errors": [_redact_temporary_path(error, temporary_root) for error in errors],
    }


def _run_compare_summary(run: JsonDict) -> JsonDict:
    summary = run.get("summary", {}) if isinstance(run.get("summary"), dict) else {}
    info = run.get("run", {}) if isinstance(run.get("run"), dict) else {}
    return {
        "id": info.get("id"),
        "run_id": info.get("run_id") or info.get("id"),
        "name": info.get("name"),
        "status": info.get("status"),
        "environment_id": info.get("environment_id"),
        "method": info.get("method"),
        "objective": info.get("objective"),
        "run_status": info.get("run_status"),
        "stop_code": info.get("stop_code"),
        "completed_trials": info.get("completed_trials"),
        "accepted_trials": info.get("accepted_trials"),
        "terminal_trials": info.get("terminal_trials"),
        "attempt_count": info.get("attempt_count"),
        "observation_count": info.get("observation_count"),
        "best_comparable_candidate": deepcopy(
            info.get("best_comparable_candidate")
            if isinstance(info.get("best_comparable_candidate"), dict)
            else {
                "available": False,
                "reason": "overview_unavailable",
                "candidate_id": None,
                "value": None,
                "sample_count": None,
                "rank": None,
                "tie_count": 0,
                "evaluation_plan_group": None,
            }
        ),
        "failure_count": summary.get("failure_count", info.get("failure_count")),
        "final_failure_count": summary.get(
            "final_failure_count", info.get("final_failure_count")
        ),
    }


def _runs_comparable(runs: List[JsonDict]) -> JsonDict:
    if len(runs) < 2:
        return {"compatible": True, "caveats": ["Only one run was provided."]}
    summaries = [_run_compare_summary(run) for run in runs]
    envs = {str(item.get("environment_id") or "") for item in summaries}
    objectives = {
        json.dumps(item.get("objective") or {}, sort_keys=True) for item in summaries
    }
    caveats = []
    if len(envs) > 1:
        caveats.append("Runs use different environment ids.")
    if len(objectives) > 1:
        caveats.append("Runs use different objective settings.")
    return {"compatible": not caveats, "caveats": caveats}


def _docs_search(state: UiState, query: str, *, limit: int = 5) -> List[JsonDict]:
    terms = [term.lower() for term in query.split() if term.strip()]
    if not terms:
        return []
    studio_package_root = _package_dir("optpilot_studio")
    core_package_root = _package_dir("optpilot")
    roots = [
        state.cwd / "docs",
        state.cwd / ".agents" / "optpilot-assistant",
        state.cwd / "src" / "optpilot" / "schemas",
    ]
    if studio_package_root is not None:
        roots.extend(
            [
                studio_package_root / "docs_assets",
                studio_package_root / "assistant_assets",
            ]
        )
    if core_package_root is not None:
        roots.append(core_package_root / "schemas")
    matches: List[JsonDict] = []
    suffixes = {".md", ".yaml", ".yml", ".json", ".py"}
    for root in roots:
        if not root.exists():
            continue
        for path in sorted(root.rglob("*")):
            if not path.is_file() or path.suffix.lower() not in suffixes:
                continue
            if any(part in EXCLUDED_SCAN_DIRS for part in path.parts):
                continue
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            lower = text.lower()
            score = sum(lower.count(term) for term in terms)
            if score <= 0:
                continue
            line_number, snippet = _snippet_for_terms(text, terms)
            matches.append(
                {
                    "path": str(
                        path.relative_to(state.cwd)
                        if _is_relative_to(path, state.cwd)
                        else path
                    ),
                    "line": line_number,
                    "score": score,
                    "snippet": snippet,
                }
            )
    return sorted(matches, key=lambda item: (-int(item["score"]), str(item["path"])))[
        : max(1, min(limit, 20))
    ]


def _snippet_for_terms(text: str, terms: List[str]) -> tuple[int, str]:
    lines = text.splitlines()
    for index, line in enumerate(lines, start=1):
        lower = line.lower()
        if any(term in lower for term in terms):
            start = max(index - 2, 1)
            end = min(index + 2, len(lines))
            snippet = "\n".join(lines[start - 1 : end])
            return index, _cap_text(snippet, 1200)
    return 1, _cap_text(text, 1200)


def _cap_text(value: Any, limit: int) -> str:
    text = str(value or "")
    if len(text) <= limit:
        return text
    return text[:limit] + "\n... truncated ..."


def _append_jsonl(path: Path, record: JsonDict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(record, sort_keys=True) + "\n")


def _agent_session_operation_lock(state: UiState, session_id: str) -> threading.Lock:
    with state._agent_session_locks_lock:
        lock = state.agent_session_locks.get(session_id)
        if lock is None:
            lock = threading.RLock()
            state.agent_session_locks[session_id] = lock
        return lock


def _append_agent_event_record(
    state: UiState, session_id: str, event: JsonDict
) -> None:
    event_id = str(event.get("id") or "")
    path = _agent_events_path(state, session_id)
    if event_id and any(
        str(existing.get("id") or "") == event_id
        for existing in _read_agent_events(state, session_id)
    ):
        return
    _append_jsonl(
        path,
        {
            "id": event_id or f"evt_{uuid.uuid4().hex[:10]}",
            "type": str(event.get("type") or "openhands_event"),
            "created_at": event.get("created_at") or _now_iso(),
            "payload": event.get("payload", {}),
        },
    )


def _agent_session_payload(state: UiState, session: JsonDict) -> JsonDict:
    payload = dict(session)
    payload.pop("openhands_pending_sync", None)
    session_id = str(session["id"])
    lock = _agent_session_operation_lock(state, session_id)
    lock_acquired = lock.acquire(blocking=False)
    try:
        if lock_acquired:
            _recover_agent_assistant_messages_from_events(state, session_id)
        messages = _read_agent_messages(state, session_id)
    finally:
        if lock_acquired:
            lock.release()
    if not messages:
        messages = [_default_agent_message()]
        _append_jsonl(_agent_messages_path(state, session_id), messages[0])
    events = _read_agent_events(state, session_id)
    payload["messages"] = _refresh_runtime_error_messages(messages, events)
    payload["events"] = events
    payload["approvals"] = _public_agent_approvals(state, session_id)
    return _decorate_agent_session_status(state, payload)


def _refresh_runtime_error_messages(
    messages: List[JsonDict], events: List[JsonDict]
) -> List[JsonDict]:
    """Repair old generic provider notices when retained events are more specific."""

    runtime_errors: List[tuple[float, str]] = []
    for event in events:
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        error = ""
        if event.get("type") == "openhands_dispatch_failed":
            error = str(payload.get("error") or "")
        elif event.get("type") == "openhands_event" and payload.get("category") == "error":
            error = str(payload.get("summary") or payload.get("raw_preview") or "")
        timestamp = _parse_iso_timestamp(str(event.get("created_at") or ""))
        if error and timestamp is not None:
            runtime_errors.append((timestamp, error))

    refreshed: List[JsonDict] = []
    for message in messages:
        copy = dict(message)
        content = str(copy.get("content") or "")
        message_time = _parse_iso_timestamp(str(copy.get("created_at") or ""))
        if (
            copy.get("title") == "The Assistant could not finish"
            and content.startswith("The model you chose")
            and message_time is not None
        ):
            nearby = [
                error
                for timestamp, error in runtime_errors
                if 0 <= message_time - timestamp <= 60
            ]
            if nearby:
                copy["content"] = explain_runtime_error(nearby[-1])[0]
        refreshed.append(copy)
    return refreshed


_AGENT_TITLE_ORIGINS = frozenset({"default", "fallback", "assistant", "user"})
_AGENT_GENERIC_TITLES = frozenset(
    {
        "",
        "conversation",
        "main conversation",
        "main session",
        "new conversation",
        "new session",
        "session",
        "untitled",
        "untitled conversation",
    }
)
_AGENT_TRIVIAL_REQUESTS = frozenset(
    {
        "continue",
        "go ahead",
        "hello",
        "hello there",
        "hi",
        "hey",
        "no",
        "ok",
        "okay",
        "please continue",
        "sounds good",
        "thank you",
        "thanks",
        "yes",
    }
)


def _agent_title_is_generic(value: Any) -> bool:
    title = " ".join(str(value or "").split()).casefold()
    return title in _AGENT_GENERIC_TITLES or bool(
        re.fullmatch(r"(?:conversation|session)\s+\d+", title)
    )


def _agent_title_origin(session: Mapping[str, Any]) -> str:
    stored = str(session.get("title_origin") or "")
    if stored in _AGENT_TITLE_ORIGINS:
        return stored
    return "default" if _agent_title_is_generic(session.get("title")) else "user"


def _agent_request_is_substantive(value: Any) -> bool:
    text = " ".join(str(value or "").split()).strip(" .,!?:;-_").casefold()
    if not text or text in _AGENT_TRIVIAL_REQUESTS:
        return False
    return bool(re.search(r"[a-z0-9]", text))


def _sanitize_agent_conversation_title(value: Any) -> str:
    if not isinstance(value, str):
        return ""
    text = re.sub(r"<[^>\n]{0,256}>", " ", value)
    text = "".join(char if ord(char) >= 32 else " " for char in text)
    text = re.sub(r"\s+", " ", text).strip()
    text = re.sub(r"(?i)^title\s*[:\-]\s*", "", text)
    text = text.strip(" \t\"'`#*_~|:;,.!?-–—")
    words = text.split()
    if len(words) > 8:
        text = " ".join(words[:8]).rstrip(" \t\"'`#*_~|:;,.!?-–—")
    if len(text) > 64:
        text = text[:64].rsplit(" ", 1)[0].rstrip(" \t\"'`#*_~|:;,.!?-–—")
    if not text or _agent_title_is_generic(text) or not re.search(r"[A-Za-z0-9]", text):
        return ""
    return text


def _agent_title_from_request(value: Any) -> str:
    if not _agent_request_is_substantive(value):
        return ""
    text = str(value or "")
    text = re.sub(r"```.*?```", " ", text, flags=re.DOTALL)
    text = next(
        (line.strip() for line in text.splitlines() if line.strip()),
        text.strip(),
    )
    text = re.sub(r"^(?:[-*+]\s+|#{1,6}\s*)", "", text)
    prefixes = (
        r"please\s+",
        r"(?:can|could|would)\s+you\s+",
        r"help\s+me\s+(?:to\s+)?",
        r"i(?:'d|\s+would)?\s+like\s+(?:you\s+)?to\s+",
        r"i\s+(?:want|need)\s+(?:you\s+)?to\s+",
        r"i\s+asked\s+(?:another|an)\s+agent\s+to\s+(?:help\s+me\s+)?",
        r"go\s+ahead\s+(?:and\s+)?",
    )
    changed = True
    while changed:
        changed = False
        for prefix in prefixes:
            updated = re.sub(rf"(?i)^{prefix}", "", text, count=1).strip()
            if updated != text:
                text = updated
                changed = True
                break
    sentence = re.split(r"(?<=[.!?])\s+", text, maxsplit=1)[0]
    title = _sanitize_agent_conversation_title(sentence)
    if title:
        title = title[0].upper() + title[1:]
    return title


def _agent_user_turn_count(state: UiState, session_id: str) -> int:
    return sum(
        1
        for message in _read_agent_messages(state, session_id)
        if message.get("role") == "user"
    )


def _maybe_apply_agent_title_fallback(
    state: UiState,
    session: JsonDict,
    content: Any,
    *,
    pending_user_message: bool = False,
) -> bool:
    if _agent_title_origin(session) != "default":
        return False
    title = _agent_title_from_request(content)
    if not title:
        return False
    session["title"] = title
    session["title_origin"] = "fallback"
    session["title_updated_turn"] = _agent_user_turn_count(
        state, str(session.get("id") or "")
    ) + (1 if pending_user_message else 0)
    return True


def _set_agent_conversation_title(
    state: UiState, session_id: str, value: Any
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    if _agent_title_origin(session) == "user":
        return _tool_result(
            "optpilot_conversation_title",
            True,
            "Kept the user-defined Conversation title.",
            data={"title": str(session.get("title") or "")},
        )
    title = _sanitize_agent_conversation_title(value)
    if not title:
        return _tool_result(
            "optpilot_conversation_title",
            False,
            "Use a specific, single-line Conversation title of at most 64 characters.",
        )
    turn = _agent_user_turn_count(state, session_id)
    if turn <= 0:
        return _tool_result(
            "optpilot_conversation_title",
            False,
            "A substantive user request is required before automatic naming.",
        )
    try:
        assistant_title_updated_turn = int(
            session.get("assistant_title_updated_turn") or -1
        )
    except (TypeError, ValueError):
        assistant_title_updated_turn = -1
    if assistant_title_updated_turn == turn:
        return _tool_result(
            "optpilot_conversation_title",
            True,
            "The Conversation title was already updated for this turn.",
            data={"title": str(session.get("title") or "")},
        )
    session["title"] = title
    session["title_origin"] = "assistant"
    session["title_updated_turn"] = turn
    session["assistant_title_updated_turn"] = turn
    _upsert_agent_session(state, session)
    return _tool_result(
        "optpilot_conversation_title",
        True,
        "Conversation title updated.",
        data={"title": title},
    )


def _normalized_agent_sessions(state: UiState) -> List[JsonDict]:
    with state._agent_session_index_lock:
        sessions = _read_agent_session_index(state)
        if not sessions:
            _create_agent_session(
                state,
                {"title": "Main Session", "description": "General OptPilot work"},
            )
            sessions = _read_agent_session_index(state)
        known_workspaces = {
            str(workspace["id"]) for workspace in _read_workspace_index(state)
        }
        changed = False
        normalized = []
        for session in sessions:
            session = dict(session)
            session_id = str(session.get("id") or "")
            if session_id and _supersede_forwarded_pending_approvals(
                state, session_id
            ):
                if session.get("openhands_conversation_id") and session.get(
                    "active_turn_id"
                ):
                    session["status"] = "waiting_for_agent"
                else:
                    session["status"] = "idle"
                pending_sync = (
                    dict(session.get("openhands_pending_sync"))
                    if isinstance(session.get("openhands_pending_sync"), dict)
                    else {}
                )
                pending_sync.pop("paused_approval_id", None)
                if pending_sync:
                    session["openhands_pending_sync"] = pending_sync
                else:
                    session.pop("openhands_pending_sync", None)
                session["updated_at"] = _now_iso()
                changed = True
            attached = [
                item
                for item in session.get("attached_workspace_ids", [])
                if item in known_workspaces
            ]
            if attached != session.get("attached_workspace_ids", []):
                session["attached_workspace_ids"] = attached
                if session.get("selected_workspace_id") not in attached:
                    session["selected_workspace_id"] = ""
                session["updated_at"] = _now_iso()
                changed = True
            if str(session.get("title_origin") or "") not in _AGENT_TITLE_ORIGINS:
                session["title_origin"] = _agent_title_origin(session)
                changed = True
            if _agent_title_origin(session) in {"assistant", "fallback"}:
                cleaned_title = _sanitize_agent_conversation_title(
                    session.get("title")
                )
                if cleaned_title and cleaned_title != session.get("title"):
                    session["title"] = cleaned_title
                    changed = True
            if "has_user_message" not in session:
                session["has_user_message"] = any(
                    message.get("role") == "user"
                    for message in _read_agent_messages(
                        state, str(session.get("id") or "")
                    )
                )
                changed = True
            if _agent_title_origin(session) == "default":
                for message in _read_agent_messages(
                    state, str(session.get("id") or "")
                ):
                    if message.get("role") != "user":
                        continue
                    if _maybe_apply_agent_title_fallback(
                        state, session, message.get("content")
                    ):
                        changed = True
                        break
            normalized.append(session)
        if changed:
            _write_agent_session_index(state, normalized)
        return normalized


def _agent_session_is_untouched(session: JsonDict) -> bool:
    """A conversation the user never wrote to, named, or attached work to.

    Untouched conversations are kept out of the sidebar list (they only
    clutter it as "Untitled conversation" entries) and are eventually
    reaped; the one the user currently has open still works — it simply
    joins the list with its first message. A conversation the user gave a
    title is deliberate work in progress, never clutter.
    """

    return (
        not session.get("has_user_message")
        and not session.get("attached_workspace_ids")
        and not session.get("archived")
        and _agent_title_origin(session) != "user"
    )


_UNTOUCHED_AGENT_SESSION_REAP_AGE_SECONDS = 24 * 3600


def _parse_iso_timestamp(value: str) -> Optional[float]:
    try:
        return calendar.timegm(time.strptime(value, "%Y-%m-%dT%H:%M:%SZ"))
    except (TypeError, ValueError):
        return None


def _reap_untouched_agent_sessions_once(state: UiState) -> None:
    if getattr(state, "_untouched_agent_sessions_reaped", False):
        return
    state._untouched_agent_sessions_reaped = True
    cutoff = time.time() - _UNTOUCHED_AGENT_SESSION_REAP_AGE_SECONDS
    with state._agent_session_index_lock:
        sessions = _read_agent_session_index(state)
        kept: List[JsonDict] = []
        reaped: List[str] = []
        for session in sessions:
            created = _parse_iso_timestamp(str(session.get("created_at") or ""))
            if (
                _agent_session_is_untouched(session)
                and created is not None
                and created < cutoff
            ):
                reaped.append(str(session.get("id") or ""))
            else:
                kept.append(session)
        if reaped:
            _write_agent_session_index(state, kept)
    for session_id in reaped:
        if not session_id:
            continue
        try:
            shutil.rmtree(_agent_session_dir(state, session_id))
        except OSError:
            pass


def _list_agent_session_summaries(state: UiState) -> List[JsonDict]:
    _reap_untouched_agent_sessions_once(state)
    return [
        _decorate_agent_session_status(state, dict(session))
        for session in _normalized_agent_sessions(state)
        if not session.get("archived") and not _agent_session_is_untouched(session)
    ]


def _list_archived_agent_session_summaries(state: UiState) -> List[JsonDict]:
    archived = [
        _decorate_agent_session_status(state, dict(session))
        for session in _normalized_agent_sessions(state)
        if session.get("archived")
    ]
    return sorted(
        archived,
        key=lambda session: str(session.get("archived_at") or ""),
        reverse=True,
    )


def _list_agent_sessions(state: UiState) -> List[JsonDict]:
    normalized = _normalized_agent_sessions(state)
    return [
        _agent_session_payload(state, session)
        for session in normalized
        if not session.get("archived")
    ]


def _agent_session_by_id(state: UiState, session_id: str) -> Optional[JsonDict]:
    for session in _normalized_agent_sessions(state):
        if session.get("id") == session_id:
            return _agent_session_payload(state, session)
    return None


def _require_agent_session(state: UiState, session_id: str) -> JsonDict:
    for session in _read_agent_session_index(state):
        if session.get("id") == session_id:
            return dict(session)
    raise KeyError(session_id)


def _upsert_agent_session(state: UiState, session: JsonDict) -> JsonDict:
    with state._agent_session_index_lock:
        sessions = [
            item
            for item in _read_agent_session_index(state)
            if item.get("id") != session.get("id")
        ]
        session = dict(session)
        session["updated_at"] = _now_iso()
        sessions.append(session)
        _write_agent_session_index(state, sessions)
    return _agent_session_payload(state, session)


def _set_agent_session_archived(
    state: UiState, session_id: str, archived: bool
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    session = dict(session)
    session["archived"] = bool(archived)
    session["archived_at"] = _now_iso() if archived else ""
    return _upsert_agent_session(state, session)


def _create_agent_session(state: UiState, payload: JsonDict) -> JsonDict:
    session_id = _safe_artifact_identifier(
        str(payload.get("id") or f"as_{uuid.uuid4().hex[:10]}"),
        "agent session id",
    )
    now = _now_iso()
    attached = [str(item) for item in payload.get("attached_workspace_ids", []) or []]
    title = str(payload.get("title") or "Untitled conversation")
    session = {
        "id": session_id,
        "title": title,
        "title_origin": "default" if _agent_title_is_generic(title) else "user",
        "description": str(payload.get("description") or "New conversation"),
        "status": "idle",
        "created_at": now,
        "updated_at": now,
        "attached_workspace_ids": attached,
        "selected_workspace_id": str(payload.get("selected_workspace_id") or ""),
        "openhands_conversation_id": str(
            payload.get("openhands_conversation_id") or ""
        ),
    }
    _agent_session_dir(state, session_id).mkdir(parents=True, exist_ok=True)
    _append_jsonl(_agent_messages_path(state, session_id), _default_agent_message())
    event = {
        "id": f"evt_{uuid.uuid4().hex[:10]}",
        "type": "session_created",
        "created_at": now,
        "payload": {"title": session["title"]},
    }
    _append_jsonl(_agent_events_path(state, session_id), event)
    for workspace_id in attached:
        if _workspace_by_id(state, workspace_id):
            _attach_workspace_to_session_record(state, workspace_id, session_id)
    return _upsert_agent_session(state, session)


def _attach_workspace_to_session_record(
    state: UiState, workspace_id: str, session_id: str
) -> None:
    workspace = _require_ui_workspace(state, workspace_id)
    attached = list(workspace.get("attached_sessions", []) or [])
    if session_id not in attached:
        attached.append(session_id)
        workspace["attached_sessions"] = attached
        _upsert_ui_workspace(state, workspace)


def _detach_workspace_from_session_record(
    state: UiState, workspace_id: str, session_id: str
) -> None:
    if not _workspace_by_id(state, workspace_id):
        return
    workspace = _require_ui_workspace(state, workspace_id)
    workspace["attached_sessions"] = [
        item for item in workspace.get("attached_sessions", []) if item != session_id
    ]
    if _workspace_should_remove_after_last_detach(state, workspace):
        _remove_ui_workspace_reference(state, workspace_id)
        return
    _upsert_ui_workspace(state, workspace)


def _attach_agent_workspace(
    state: UiState, session_id: str, workspace_id: str, *, select: bool = False
) -> JsonDict:
    if not workspace_id:
        raise ValueError("workspace_id is required.")
    _require_ui_workspace(state, workspace_id)
    session = _require_agent_session(state, session_id)
    attached = list(session.get("attached_workspace_ids", []) or [])
    if workspace_id not in attached:
        attached.append(workspace_id)
    session["attached_workspace_ids"] = attached
    if select or not session.get("selected_workspace_id"):
        session["selected_workspace_id"] = workspace_id
    _attach_workspace_to_session_record(state, workspace_id, session_id)
    _append_jsonl(
        _agent_events_path(state, session_id),
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "workspace_attached",
            "created_at": _now_iso(),
            "payload": {"workspace_id": workspace_id},
        },
    )
    return _upsert_agent_session(state, session)


def _detach_agent_workspace(
    state: UiState, session_id: str, workspace_id: str
) -> JsonDict:
    if not workspace_id:
        raise ValueError("workspace_id is required.")
    session = _require_agent_session(state, session_id)
    attached = [
        item
        for item in session.get("attached_workspace_ids", [])
        if item != workspace_id
    ]
    session["attached_workspace_ids"] = attached
    if session.get("selected_workspace_id") == workspace_id:
        session["selected_workspace_id"] = ""
    _detach_workspace_from_session_record(state, workspace_id, session_id)
    _append_jsonl(
        _agent_events_path(state, session_id),
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "workspace_detached",
            "created_at": _now_iso(),
            "payload": {"workspace_id": workspace_id},
        },
    )
    return _upsert_agent_session(state, session)


def _select_agent_workspace(
    state: UiState, session_id: str, workspace_id: str
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    if workspace_id and workspace_id not in session.get("attached_workspace_ids", []):
        _require_ui_workspace(state, workspace_id)
        session = _attach_agent_workspace(state, session_id, workspace_id, select=True)
        return session
    session["selected_workspace_id"] = workspace_id
    return _upsert_agent_session(state, session)


def _mark_agent_session_idle(state: UiState, session_id: str) -> JsonDict:
    session = _require_agent_session(state, session_id)
    session["status"] = "idle"
    session.pop("active_turn_id", None)
    session.pop("active_turn_started_at", None)
    return _upsert_agent_session(state, session)


def _cancel_agent_session(state: UiState, session_id: str) -> JsonDict:
    remote_cancel_scheduled = False
    with _agent_session_operation_lock(state, session_id):
        session = _require_agent_session(state, session_id)
        conversation_id = str(session.get("openhands_conversation_id") or "")
        turn_id = str(session.get("active_turn_id") or "")
        cancelled_at = _now_iso()
        cancel_conversation = getattr(state.agent_adapter, "cancel_conversation", None)
        remote_cancel_scheduled = bool(
            conversation_id and callable(cancel_conversation)
        )
        session["status"] = "idle"
        session["cancelled_at"] = cancelled_at
        if turn_id:
            session["cancelled_turn_id"] = turn_id
        if conversation_id:
            session["cancelled_openhands_conversation_id"] = conversation_id
        session.pop("active_turn_id", None)
        session.pop("active_turn_started_at", None)
        session.pop("openhands_pending_sync", None)
        _append_agent_event_record(
            state,
            session_id,
            {
                "id": f"evt_{uuid.uuid4().hex[:10]}",
                "type": "openhands_dispatch_cancelled",
                "created_at": cancelled_at,
                "payload": {
                    "conversation_id": conversation_id,
                    "turn_id": turn_id,
                    "remote_cancel_scheduled": remote_cancel_scheduled,
                    "remote_cancelled": False,
                    "remote_action": "",
                    "remote_error": ""
                    if remote_cancel_scheduled
                    else "No active OpenHands conversation.",
                },
            },
        )
        updated = _upsert_agent_session(state, session)
    if remote_cancel_scheduled:
        _schedule_openhands_cancel(state, session_id, conversation_id, turn_id)
    return updated


def _schedule_openhands_cancel(
    state: UiState, session_id: str, conversation_id: str, turn_id: str
) -> None:
    def worker() -> None:
        cancel_conversation = getattr(state.agent_adapter, "cancel_conversation", None)
        if not callable(cancel_conversation):
            return
        event_type = "openhands_cancel_acknowledged"
        try:
            cancel_result = cancel_conversation(conversation_id)
            if not cancel_result.get("cancelled"):
                event_type = "openhands_cancel_failed"
        except Exception as exc:  # pragma: no cover - defensive adapter boundary
            cancel_result = {
                "cancelled": False,
                "conversation_id": conversation_id,
                "error": str(exc),
            }
            event_type = "openhands_cancel_failed"
        with _agent_session_operation_lock(state, session_id):
            _append_agent_event_record(
                state,
                session_id,
                {
                    "id": f"evt_{uuid.uuid4().hex[:10]}",
                    "type": event_type,
                    "created_at": _now_iso(),
                    "payload": {
                        "conversation_id": conversation_id,
                        "turn_id": turn_id,
                        "remote_cancelled": bool(cancel_result.get("cancelled")),
                        "remote_action": cancel_result.get("action") or "",
                        "remote_error": cancel_result.get("error")
                        or cancel_result.get("reason")
                        or "",
                    },
                },
            )

    threading.Thread(
        target=worker,
        name=f"optpilot-openhands-cancel-{session_id}",
        daemon=True,
    ).start()


def _cancelled_agent_turn_session(
    state: UiState,
    session_id: str,
    *,
    turn_id: str,
    conversation_id: str,
    turn_started_at: str,
) -> Optional[JsonDict]:
    latest = _require_agent_session(state, session_id)
    cancelled_turn_id = str(latest.get("cancelled_turn_id") or "")
    if turn_id and cancelled_turn_id == turn_id:
        return latest
    cancelled_conversation_id = str(
        latest.get("cancelled_openhands_conversation_id") or ""
    )
    cancelled_at = str(latest.get("cancelled_at") or "")
    if (
        conversation_id
        and cancelled_conversation_id == conversation_id
        and cancelled_at
        and turn_started_at
        and cancelled_at >= turn_started_at
    ):
        return latest
    return None


def _append_agent_assistant_message_if_new(
    state: UiState,
    session_id: str,
    *,
    content: Any,
    title: str = "Assistant",
    context: Optional[JsonDict] = None,
    dispatch: Optional[JsonDict] = None,
) -> bool:
    assistant_content = _user_facing_openhands_text(content)
    normalized = _normalize_agent_text(assistant_content)
    if not assistant_content or not normalized:
        return False
    existing_texts = {
        _normalize_agent_text(str(message.get("content") or ""))
        for message in _read_agent_messages(state, session_id)
        if message.get("role") == "assistant"
        and str(message.get("content") or "").strip()
    }
    if normalized in existing_texts:
        return False
    source, memory_scope = _agent_assistant_message_origin(dispatch)
    message: JsonDict = {
        "id": f"msg_{uuid.uuid4().hex[:10]}",
        "role": "assistant",
        "title": title or "Assistant",
        "content": assistant_content,
        "created_at": _now_iso(),
        "source": source,
        "memory_scope": memory_scope,
    }
    if context is not None:
        message["context"] = context
    if dispatch is not None:
        message["dispatch"] = dispatch
    _append_jsonl(_agent_messages_path(state, session_id), message)
    return True


def _agent_assistant_message_origin(dispatch: Optional[JsonDict]) -> tuple[str, str]:
    dispatch = dispatch if isinstance(dispatch, dict) else {}
    status = str(dispatch.get("status") or "")
    transport = str(dispatch.get("transport") or dispatch.get("dispatch") or "")
    conversation_id = str(dispatch.get("conversation_id") or "")
    if status in {"queued", "failed"}:
        return "studio_system", "ui_history"
    if conversation_id and "openhands" in transport:
        return "openhands", "openhands_conversation"
    if transport:
        return "model_chat", "stateless_model"
    return "assistant", "ui_history"


def _agent_recent_message_context(
    state: UiState,
    session_id: str,
    *,
    limit: int = 8,
    character_limit: int = 6000,
    exclude_message_id: str = "",
) -> List[JsonDict]:
    """Return bounded user-visible history when a runtime must be recreated."""

    history: List[JsonDict] = []
    used = 0
    for message in reversed(_read_agent_messages(state, session_id)):
        if exclude_message_id and str(message.get("id") or "") == exclude_message_id:
            continue
        role = str(message.get("role") or "")
        source = str(message.get("source") or "")
        if role not in {"user", "assistant", "agent"}:
            continue
        if source == "studio_system":
            continue
        content = _cap_text(message.get("content"), 1200).strip()
        if not content:
            continue
        remaining = character_limit - used
        if remaining <= 0:
            break
        content = content[:remaining]
        history.append(
            {
                "role": "assistant" if role in {"assistant", "agent"} else "user",
                "content": content,
            }
        )
        used += len(content)
        if len(history) >= max(1, limit):
            break
    history.reverse()
    return history


def _record_missing_openhands_conversation(
    state: UiState,
    session_id: str,
    conversation_id: str,
    *,
    notify_user: bool,
) -> None:
    """Record one missing runtime binding without changing Studio history."""

    _append_agent_event_record(
        state,
        session_id,
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "openhands_conversation_missing",
            "created_at": _now_iso(),
            "payload": {
                "conversation_id": conversation_id,
                "recovery": "create_on_next_message",
            },
        },
    )
    if notify_user:
        _append_agent_assistant_message_if_new(
            state,
            session_id,
            title="Assistant restarted",
            content=(
                "The Assistant service restarted before it could finish this request. "
                "Your Conversation history is still here; send the request again to continue."
            ),
            dispatch={"status": "failed", "transport": "openhands_http"},
        )


def _clear_openhands_runtime_binding(session: JsonDict) -> None:
    """Clear only ephemeral OpenHands state; retained Studio messages stay intact."""

    session["openhands_conversation_id"] = ""
    session.pop("openhands_workspace_id", None)
    session.pop("openhands_pending_sync", None)
    session.pop("cancelled_openhands_conversation_id", None)


def _append_agent_message(
    state: UiState, session_id: str, payload: JsonDict
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    role = str(payload.get("role") or "user")
    content = str(payload.get("content") or payload.get("message") or "")
    title = str(payload.get("title") or ("User" if role == "user" else "Assistant"))
    source = str(payload.get("source") or ("user" if role == "user" else "studio_ui"))
    memory_scope = str(
        payload.get("memory_scope")
        or (
            "openhands_conversation"
            if role == "user" or source == "openhands"
            else "ui_history"
        )
    )
    ui_context = (
        payload.get("ui_context") if isinstance(payload.get("ui_context"), dict) else {}
    )
    if not content:
        raise ValueError("Message content is required.")
    if role == "user":
        _maybe_apply_agent_title_fallback(
            state, session, content, pending_user_message=True
        )
    context = _agent_context_packet(state, session, ui_context)
    message = {
        "id": f"msg_{uuid.uuid4().hex[:10]}",
        "role": role,
        "title": title,
        "content": content,
        "created_at": _now_iso(),
        "source": source,
        "memory_scope": memory_scope,
        "context": context,
    }
    _append_jsonl(_agent_messages_path(state, session_id), message)
    _append_jsonl(
        _agent_events_path(state, session_id),
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "message",
            "created_at": message["created_at"],
            "payload": {"message_id": message["id"], "role": role},
        },
    )
    if role == "user":
        turn_id = f"turn_{uuid.uuid4().hex[:10]}"
        turn_started_at = str(message["created_at"])
        selected_workspace = (
            context.get("selected_workspace")
            if isinstance(context.get("selected_workspace"), dict)
            else {}
        )
        target_workspace_id = str(selected_workspace.get("id") or "")
        target_workspace_title = str(
            selected_workspace.get("title") or "No default Workspace"
        )
        existing_conversation_id = str(
            session.get("openhands_conversation_id") or ""
        )
        runtime_workspace_id = str(session.get("openhands_workspace_id") or "")
        workspace_changed = bool(
            existing_conversation_id and runtime_workspace_id != target_workspace_id
        )
        dispatch_conversation_id = existing_conversation_id
        if workspace_changed:
            dispatch_conversation_id = ""
            session["openhands_conversation_id"] = ""
            session.pop("openhands_pending_sync", None)
            context.setdefault("conversation", {})["recent_messages"] = (
                _agent_recent_message_context(
                    state,
                    session_id,
                    exclude_message_id=str(message.get("id") or ""),
                )
            )
            _append_agent_event_record(
                state,
                session_id,
                {
                    "id": f"evt_{uuid.uuid4().hex[:10]}",
                    "type": "assistant_workspace_changed",
                    "created_at": _now_iso(),
                    "payload": {
                        "workspace_id": target_workspace_id,
                        "workspace_title": target_workspace_title,
                    },
                },
            )
        elif not existing_conversation_id:
            context.setdefault("conversation", {})["recent_messages"] = (
                _agent_recent_message_context(
                    state,
                    session_id,
                    exclude_message_id=str(message.get("id") or ""),
                )
            )
        session["status"] = "running"
        session["active_turn_id"] = turn_id
        session["active_turn_started_at"] = turn_started_at
        session["has_user_message"] = True
        session.pop("openhands_pending_sync", None)
        _upsert_agent_session(state, session)
        _append_agent_event_record(
            state,
            session_id,
            {
                "id": f"evt_{uuid.uuid4().hex[:10]}",
                "type": "openhands_dispatch_started",
                "created_at": _now_iso(),
                "payload": {
                    "dispatch": state.agent_adapter.status().get("dispatch"),
                    "conversation_id": dispatch_conversation_id,
                    "turn_id": turn_id,
                },
            },
        )
        dispatch = state.agent_adapter.dispatch_message(
            message=content,
            context=context,
            conversation_id=dispatch_conversation_id or None,
            tool_executor=lambda tool_name, arguments: _execute_agent_tool(
                state, session_id, tool_name, arguments
            ),
            ignored_response_texts=_assistant_response_texts(state, session_id),
        )
        recovered_conversation_id = ""
        if (
            dispatch_conversation_id
            and str(dispatch.get("status") or "") == "conversation_missing"
        ):
            missing_conversation_id = str(
                dispatch.get("conversation_id") or dispatch_conversation_id
            )
            _clear_openhands_runtime_binding(session)
            context.setdefault("conversation", {})["recent_messages"] = (
                _agent_recent_message_context(
                    state,
                    session_id,
                    exclude_message_id=str(message.get("id") or ""),
                )
            )
            _record_missing_openhands_conversation(
                state,
                session_id,
                missing_conversation_id,
                notify_user=False,
            )
            dispatch = state.agent_adapter.dispatch_message(
                message=content,
                context=context,
                conversation_id=None,
                tool_executor=lambda tool_name, arguments: _execute_agent_tool(
                    state, session_id, tool_name, arguments
                ),
                ignored_response_texts=_assistant_response_texts(state, session_id),
            )
            recovered_conversation_id = str(dispatch.get("conversation_id") or "")
            if recovered_conversation_id:
                _append_agent_event_record(
                    state,
                    session_id,
                    {
                        "id": f"evt_{uuid.uuid4().hex[:10]}",
                        "type": "openhands_conversation_recreated",
                        "created_at": _now_iso(),
                        "payload": {
                            "previous_conversation_id": missing_conversation_id,
                            "conversation_id": recovered_conversation_id,
                        },
                    },
                )
        conversation_id = str(dispatch.get("conversation_id") or "")
        if conversation_id:
            session["openhands_conversation_id"] = conversation_id
            session["openhands_workspace_id"] = target_workspace_id
        cancelled_session = _cancelled_agent_turn_session(
            state,
            session_id,
            turn_id=turn_id,
            conversation_id=conversation_id,
            turn_started_at=turn_started_at,
        )
        if cancelled_session:
            return {
                "session": _agent_session_payload(state, cancelled_session),
                "message": message,
            }
        sync_state = (
            dispatch.get("sync_state")
            if isinstance(dispatch.get("sync_state"), dict)
            else {}
        )
        if sync_state:
            session["openhands_pending_sync"] = sync_state
        for event in dispatch.get("events", []) or []:
            if not isinstance(event, dict):
                continue
            _append_agent_event_record(state, session_id, event)
        raw_assistant = (
            dispatch.get("assistant_message")
            if isinstance(dispatch.get("assistant_message"), dict)
            else {}
        )
        _append_agent_assistant_message_if_new(
            state,
            session_id,
            content=raw_assistant.get("content"),
            title=str(raw_assistant.get("title") or "Assistant"),
            context=context,
            dispatch={
                "status": dispatch.get("status"),
                "mode": dispatch.get("mode"),
                "transport": dispatch.get("dispatch"),
                "conversation_id": conversation_id,
            },
        )
        dispatch_status = str(dispatch.get("status") or "")
        # "queued" means nothing was sent and nothing will ever arrive: the
        # Assistant is switched off or has no model configured. The notice
        # written into the transcript IS the whole answer, so the turn is
        # finished. Treating it as still-waiting is what left conversations
        # showing "Working" indefinitely, surviving restarts, with no hint
        # that no one was on the other end.
        if dispatch_status in {"answered", "dispatched", "queued"}:
            session["status"] = "idle"
            session.pop("active_turn_id", None)
            session.pop("active_turn_started_at", None)
            session.pop("openhands_pending_sync", None)
        elif dispatch_status == "awaiting_user_approval":
            session["status"] = "awaiting_user_approval"
        elif dispatch_status == "failed":
            session["status"] = "error"
            session.pop("active_turn_id", None)
            session.pop("active_turn_started_at", None)
            session.pop("openhands_pending_sync", None)
        else:
            session["status"] = "waiting_for_agent"
    else:
        session["status"] = session.get("status", "idle")
    if role == "user":
        latest = _require_agent_session(state, session_id)
        for key in (
            "status",
            "openhands_conversation_id",
            "openhands_workspace_id",
            "active_turn_id",
            "active_turn_started_at",
            "openhands_pending_sync",
        ):
            if key in session:
                latest[key] = session[key]
            else:
                latest.pop(key, None)
        session = latest
    updated = _upsert_agent_session(state, session)
    return {"session": updated, "message": message}


def _sync_agent_session(
    state: UiState, session_id: str, *, poll_seconds: float = 3.0
) -> JsonDict:
    sync_started_at = _now_iso()
    with _agent_session_operation_lock(state, session_id):
        session = _require_agent_session(state, session_id)
        conversation_id = str(session.get("openhands_conversation_id") or "")
        turn_id = str(session.get("active_turn_id") or "")
        turn_started_at = str(session.get("active_turn_started_at") or sync_started_at)
        if not conversation_id or _agent_effective_status(state, session) not in {
            "waiting_for_agent",
            "running",
        }:
            return _agent_session_payload(state, session)
        _retry_pending_tool_result_forwards(state, session_id, conversation_id)
        handled_tool_calls = _handled_optpilot_tool_call_ids(state, session_id)
        pending_sync = (
            session.get("openhands_pending_sync")
            if isinstance(session.get("openhands_pending_sync"), dict)
            else {}
        )
        ignored_event_ids = {
            str(event_id)
            for event_id in pending_sync.get("ignored_event_ids", [])
            if event_id
        }
        ignored_response_texts = {
            str(text) for text in pending_sync.get("ignored_response_texts", []) if text
        }
        ignored_response_texts.update(_assistant_response_texts(state, session_id))
        try:
            dispatch = state.agent_adapter.sync_conversation(
                conversation_id,
                tool_executor=lambda tool_name, arguments: _execute_agent_tool(
                    state, session_id, tool_name, arguments
                ),
                ignored_tool_calls=handled_tool_calls,
                ignored_event_ids=ignored_event_ids,
                ignored_response_texts=ignored_response_texts,
                poll_seconds=poll_seconds,
            )
        except OpenHandsConversationNotFound:
            _clear_openhands_runtime_binding(session)
            session["status"] = "idle"
            session.pop("active_turn_id", None)
            session.pop("active_turn_started_at", None)
            _record_missing_openhands_conversation(
                state,
                session_id,
                conversation_id,
                notify_user=True,
            )
            return _upsert_agent_session(state, session)
        except Exception as exc:
            if not _is_timeout_like(exc):
                raise
            session["status"] = "waiting_for_agent"
            _append_agent_event_record(
                state,
                session_id,
                {
                    "id": f"evt_{uuid.uuid4().hex[:10]}",
                    "type": "openhands_sync_timeout",
                    "created_at": _now_iso(),
                    "payload": {
                        "conversation_id": conversation_id,
                        "reason": str(exc) or "Timed out while polling OpenHands.",
                    },
                },
            )
            return _agent_session_payload(state, _upsert_agent_session(state, session))
        cancelled_session = _cancelled_agent_turn_session(
            state,
            session_id,
            turn_id=turn_id,
            conversation_id=conversation_id,
            turn_started_at=turn_started_at,
        )
        if cancelled_session:
            return _agent_session_payload(state, cancelled_session)
        latest_session = _require_agent_session(state, session_id)
        latest_turn_id = str(latest_session.get("active_turn_id") or "")
        latest_conversation_id = str(
            latest_session.get("openhands_conversation_id") or ""
        )
        if (
            _agent_effective_status(state, latest_session)
            not in {"waiting_for_agent", "running"}
            or latest_turn_id != turn_id
            or latest_conversation_id != conversation_id
        ):
            return _agent_session_payload(state, latest_session)
        session = latest_session
        for event in dispatch.get("events", []) or []:
            if not isinstance(event, dict):
                continue
            _append_agent_event_record(state, session_id, event)
        raw_assistant = (
            dispatch.get("assistant_message")
            if isinstance(dispatch.get("assistant_message"), dict)
            else {}
        )
        appended_assistant_message = _append_agent_assistant_message_if_new(
            state,
            session_id,
            content=raw_assistant.get("content"),
            title=str(raw_assistant.get("title") or "Assistant"),
            dispatch={
                "status": dispatch.get("status"),
                "transport": "openhands_http",
                "conversation_id": conversation_id,
            },
        )
        if dispatch.get("status") == "failed":
            session["status"] = "error"
            session.pop("active_turn_id", None)
            session.pop("active_turn_started_at", None)
            session.pop("openhands_pending_sync", None)
        elif dispatch.get("status") == "awaiting_user_approval":
            session["status"] = "awaiting_user_approval"
            sync_state = (
                dispatch.get("sync_state")
                if isinstance(dispatch.get("sync_state"), dict)
                else {}
            )
            if sync_state:
                session["openhands_pending_sync"] = sync_state
        elif appended_assistant_message:
            session["status"] = "idle"
            session.pop("active_turn_id", None)
            session.pop("active_turn_started_at", None)
            session.pop("openhands_pending_sync", None)
        else:
            session["status"] = "waiting_for_agent"
            sync_state = (
                dispatch.get("sync_state")
                if isinstance(dispatch.get("sync_state"), dict)
                else {}
            )
            if sync_state:
                session["openhands_pending_sync"] = sync_state
        return _upsert_agent_session(state, session)


def _agent_tick_candidate_session_ids(state: UiState, *, now: float) -> List[str]:
    """Busy sessions due for an unattended sync, oldest stall first.

    Reads the session index only -- never a session payload, which recovers
    messages and writes as a side effect. A session is a candidate when it
    holds a conversation and its stored status says work may still be
    outstanding; anything awaiting a person, idle, errored or archived is
    left alone.
    """

    candidates: List[tuple[str, str]] = []
    backoff = getattr(state, "_agent_tick_backoff", {})
    for session in _read_agent_session_index(state):
        if not isinstance(session, dict) or session.get("archived"):
            continue
        session_id = str(session.get("id") or "")
        if not session_id or not str(session.get("openhands_conversation_id") or ""):
            continue
        if str(session.get("status") or "") not in {"waiting_for_agent", "running"}:
            continue
        due_at, _delay = backoff.get(session_id, (0.0, 0.0))
        if due_at > now:
            continue
        candidates.append((str(session.get("updated_at") or ""), session_id))
    candidates.sort()
    return [session_id for _updated_at, session_id in candidates][
        :_AGENT_TICK_MAX_SESSIONS_PER_CYCLE
    ]


def _agent_tick_note_progress(state: UiState, session_id: str) -> None:
    state._agent_tick_backoff.pop(session_id, None)


def _agent_tick_note_no_progress(
    state: UiState, session_id: str, *, now: float, interval: float
) -> None:
    _due_at, delay = state._agent_tick_backoff.get(session_id, (0.0, 0.0))
    delay = min(
        max(interval, delay * 2 if delay else interval),
        _AGENT_TICK_BACKOFF_CEILING_SECONDS,
    )
    state._agent_tick_backoff[session_id] = (now + delay, delay)


def _run_agent_session_tick_cycle(
    state: UiState, *, now: Optional[float] = None
) -> List[str]:
    """Advance up to a few busy sessions; return the ids actually synced.

    One reachability probe gates the whole cycle: a down agent-server makes
    every sync burn its poll window for nothing, and reports no error to
    distinguish itself from a slow model.
    """

    now = time.monotonic() if now is None else now
    interval = max(getattr(state, "agent_tick_interval_seconds", 0.0), 1.0)
    claim = getattr(state, "_runtime_supervisor_claim", None)
    if claim is not None:
        claim.assert_active_for(state.cwd)
    adapter = state.agent_adapter
    status = adapter.status() if adapter is not None else {}
    if not isinstance(status, dict):
        return []
    if status.get("dispatch") != "openhands_http" or not status.get("connected"):
        return []
    synced: List[str] = []
    for session_id in _agent_tick_candidate_session_ids(state, now=now):
        if state._background_execution_closing.is_set():
            break
        lock = _agent_session_operation_lock(state, session_id)
        # A client sync, a message post, or an approval already owns this
        # session; skipping is the whole point of not queueing behind them.
        if not lock.acquire(blocking=False):
            continue
        try:
            payload = _sync_agent_session(
                state, session_id, poll_seconds=_AGENT_TICK_POLL_SECONDS
            )
        except Exception:
            # A session archived mid-cycle raises KeyError, a 502 escapes as a
            # plain RuntimeError, and this tree can raise OSError on any write.
            # None of them may end the thread.
            _agent_tick_note_no_progress(
                state, session_id, now=now, interval=interval
            )
        else:
            synced.append(session_id)
            if str(payload.get("status") or "") in {"waiting_for_agent", "running"}:
                _agent_tick_note_no_progress(
                    state, session_id, now=now, interval=interval
                )
            else:
                _agent_tick_note_progress(state, session_id)
        finally:
            lock.release()
    return synced


def _start_agent_session_tick(state: UiState) -> bool:
    """Start the one thread that advances conversations with nobody watching."""

    interval = getattr(state, "agent_tick_interval_seconds", 0.0)
    if interval <= 0:
        return False
    if getattr(state, "_runtime_supervisor_claim", None) is None:
        return False
    if state._background_execution_closing.is_set():
        return False

    def loop() -> None:
        try:
            while not state._background_execution_closing.is_set():
                try:
                    _run_agent_session_tick_cycle(state)
                except Exception:
                    # Whole-cycle net: enumeration itself can fail on this
                    # storage. The next cycle re-reads from scratch.
                    pass
                if state._background_execution_closing.wait(interval):
                    return
        finally:
            with state._lock:
                if (
                    state._agent_tick_threads.get("agent-tick")
                    is threading.current_thread()
                ):
                    state._agent_tick_threads.pop("agent-tick", None)

    with state._lock:
        existing = state._agent_tick_threads.get("agent-tick")
        if existing is not None and existing.is_alive():
            return False
        thread = threading.Thread(
            target=loop, name="optpilot-agent-session-tick", daemon=True
        )
        state._agent_tick_threads["agent-tick"] = thread
    thread.start()
    return True


def _is_timeout_like(exc: Exception) -> bool:
    return (
        type(exc).__name__ in {"TimeoutError", "TimeoutExpired"}
        or "timed out" in str(exc).lower()
    )


def _mark_agent_session_waiting_after_sync_timeout(
    state: UiState, session_id: str, exc: Exception
) -> JsonDict:
    session = _require_agent_session(state, session_id)
    conversation_id = str(session.get("openhands_conversation_id") or "")
    session["status"] = "waiting_for_agent"
    _append_agent_event_record(
        state,
        session_id,
        {
            "id": f"evt_{uuid.uuid4().hex[:10]}",
            "type": "openhands_sync_timeout",
            "created_at": _now_iso(),
            "payload": {
                "conversation_id": conversation_id,
                "reason": str(exc) or "Timed out while polling OpenHands.",
            },
        },
    )
    return _agent_session_payload(state, _upsert_agent_session(state, session))


def _assistant_response_texts(state: UiState, session_id: str) -> set[str]:
    return {
        str(message.get("content") or "").strip()
        for message in _read_agent_messages(state, session_id)
        if (
            message.get("role") == "assistant"
            and _agent_message_source(message) == "openhands"
            and str(message.get("content") or "").strip()
        )
    }


def _agent_message_source(message: JsonDict) -> str:
    source = str(message.get("source") or "")
    if source:
        return source
    role = str(message.get("role") or "user")
    if role == "user":
        return "user"
    title = str(message.get("title") or "")
    dispatch = (
        message.get("dispatch") if isinstance(message.get("dispatch"), dict) else {}
    )
    if role == "assistant" and (
        title == "OpenHands" or dispatch.get("conversation_id")
    ):
        return "openhands"
    if role == "assistant" and title == "Assistant" and dispatch.get("transport"):
        return "model_chat"
    return "studio_ui"


def _handled_optpilot_tool_call_ids(state: UiState, session_id: str) -> set[str]:
    # Approval-gated tools do not emit ``optpilot_tool_result`` when the
    # adapter first sees them: polling pauses while Studio waits for the
    # person to approve or reject the action.  Once that decision is sent
    # back to OpenHands, the forwarding event is the durable proof that the
    # call was handled.  Include it here so a replayed ActionEvent cannot
    # create another approval (or execute the approved action again).
    handled = _successful_openhands_forwarded_tool_call_ids(state, session_id)
    for event in _read_agent_events(state, session_id):
        if event.get("type") not in {"optpilot_tool_result", "optpilot_approval_pause"}:
            continue
        payload = event.get("payload") if isinstance(event.get("payload"), dict) else {}
        call_id = str(payload.get("tool_call_id") or "")
        if call_id:
            handled.add(call_id)
    return handled


def _prune_assistant_run_selections_locked(state: UiState, *, now: float) -> None:
    expired = [
        handle
        for handle, record in state.assistant_run_selections.items()
        if now - record.created_at > ASSISTANT_RUN_SELECTION_TTL_SECONDS
    ]
    for handle in expired:
        state.assistant_run_selections.pop(handle, None)
    overflow = len(state.assistant_run_selections) - (
        ASSISTANT_RUN_SELECTION_MAX_RECORDS - 1
    )
    if overflow <= 0:
        return
    oldest = sorted(
        state.assistant_run_selections.values(),
        key=lambda record: record.created_at,
    )[:overflow]
    for record in oldest:
        state.assistant_run_selections.pop(record.handle, None)


def _canonical_selection_content_session_id(value: Any) -> str:
    if not isinstance(value, str) or not re.fullmatch(r"scs_[0-9a-f]{32}", value):
        raise ValueError("Content session id is invalid or expired.")
    return value


def _optional_selection_content_session_id(value: Any) -> Optional[str]:
    if value is None:
        return None
    return _canonical_selection_content_session_id(value)


def _canonical_selection_content_view_handle(value: Any) -> str:
    if not isinstance(value, str) or not re.fullmatch(r"scv_[0-9a-f]{32}", value):
        raise RealmNotFound("Content view not found.")
    return value


def _prune_selection_content_views_locked(state: UiState, *, now: float) -> None:
    expired_sessions = {
        session_id
        for session_id, record in state.selection_content_sessions.items()
        if now - record.created_at > SELECTION_CONTENT_VIEW_TTL_SECONDS
    }
    for session_id in expired_sessions:
        state.selection_content_sessions.pop(session_id, None)
    expired_views = [
        handle
        for handle, record in state.selection_content_views.items()
        if (
            record.session_id in expired_sessions
            or now - record.created_at > SELECTION_CONTENT_VIEW_TTL_SECONDS
        )
    ]
    for handle in expired_views:
        state.selection_content_views.pop(handle, None)


def _evict_selection_content_session_locked(state: UiState, *, session_id: str) -> None:
    state.selection_content_sessions.pop(session_id, None)
    for handle in tuple(state.selection_content_views):
        if state.selection_content_views[handle].session_id == session_id:
            state.selection_content_views.pop(handle, None)


def _selection_content_session(
    state: UiState, *, requested_session_id: Optional[str]
) -> SelectionContentSessionRecord:
    runtime = _require_realm_runtime(state)
    actor_principal_id = runtime.actor_principal_id
    now = time.monotonic()
    with state._lock:
        _prune_selection_content_views_locked(state, now=now)
        if requested_session_id is not None:
            record = state.selection_content_sessions.get(requested_session_id)
            if record is not None and (record.actor_principal_id != actor_principal_id):
                raise ValueError("Content session id is invalid or expired.")
            if record is not None:
                return record
            # A well-formed id can outlive this process or its short TTL in the
            # browser's tab memory.  It carries no selection authority, so
            # transparently replace it instead of trapping the tab in a
            # reload-only failure loop.
        if len(state.selection_content_sessions) >= (
            SELECTION_CONTENT_SESSION_MAX_RECORDS
        ):
            oldest = min(
                state.selection_content_sessions.values(),
                key=lambda record: record.created_at,
            )
            _evict_selection_content_session_locked(state, session_id=oldest.session_id)
        session_id = f"scs_{uuid.uuid4().hex}"
        while session_id in state.selection_content_sessions:
            session_id = f"scs_{uuid.uuid4().hex}"
        record = SelectionContentSessionRecord(
            session_id=session_id,
            actor_principal_id=actor_principal_id,
            created_at=now,
        )
        state.selection_content_sessions[session_id] = record
        return record


def _store_selection_content_view(
    state: UiState,
    *,
    session: SelectionContentSessionRecord,
    run_id: str,
    public_selection: Mapping[str, Any],
    selection: SelectionRef,
    content_kind: str,
    media_type: str,
    entry_count: Optional[int],
    total_size_bytes: int,
) -> SelectionContentViewRecord:
    now = time.monotonic()
    with state._lock:
        _prune_selection_content_views_locked(state, now=now)
        current_session = state.selection_content_sessions.get(session.session_id)
        if current_session != session:
            raise ValueError("Content session id is invalid or expired.")
        session_views = sorted(
            (
                record
                for record in state.selection_content_views.values()
                if record.session_id == session.session_id
            ),
            key=lambda record: record.created_at,
        )
        if len(session_views) >= SELECTION_CONTENT_VIEW_MAX_PER_SESSION:
            state.selection_content_views.pop(session_views[0].handle, None)
        if len(state.selection_content_views) >= SELECTION_CONTENT_VIEW_MAX_RECORDS:
            oldest = min(
                state.selection_content_views.values(),
                key=lambda record: record.created_at,
            )
            state.selection_content_views.pop(oldest.handle, None)
        handle = f"scv_{uuid.uuid4().hex}"
        while handle in state.selection_content_views:
            handle = f"scv_{uuid.uuid4().hex}"
        record = SelectionContentViewRecord(
            handle=handle,
            session_id=session.session_id,
            actor_principal_id=session.actor_principal_id,
            run_id=run_id,
            public_selection=deepcopy(dict(public_selection)),
            selection=selection,
            content_kind=content_kind,
            media_type=media_type,
            entry_count=entry_count,
            total_size_bytes=total_size_bytes,
            created_at=now,
        )
        state.selection_content_views[handle] = record
        return record


def _public_selection_content_view(record: SelectionContentViewRecord) -> JsonDict:
    selection = record.public_selection
    sequence = selection.get("sequence")
    return {
        "schema": SELECTION_CONTENT_VIEW_SCHEMA,
        "handle": record.handle,
        "content_session_id": record.session_id,
        "content_kind": record.content_kind,
        "media_type": record.media_type,
        "entry_count": record.entry_count,
        "total_size_bytes": record.total_size_bytes,
        "selection": {
            "kind": str(selection["kind"]),
            "entity_id": str(selection["entity_id"]),
        },
        "head": {
            "revision": int(selection["revision"]),
            "sequence": None if sequence is None else int(sequence),
        },
        "expires_in_seconds": SELECTION_CONTENT_VIEW_TTL_SECONDS,
    }


def _selection_content_view_record(
    state: UiState, *, handle: Any, session_id: str
) -> SelectionContentViewRecord:
    canonical_handle = _canonical_selection_content_view_handle(handle)
    runtime = _require_realm_runtime(state)
    now = time.monotonic()
    with state._lock:
        _prune_selection_content_views_locked(state, now=now)
        session = state.selection_content_sessions.get(session_id)
        record = state.selection_content_views.get(canonical_handle)
    if (
        session is None
        or record is None
        or session.actor_principal_id != runtime.actor_principal_id
        or record.actor_principal_id != runtime.actor_principal_id
        or record.session_id != session_id
    ):
        raise RealmNotFound("Content view not found.")
    return record


def _discard_selection_content_view(
    state: UiState, *, record: SelectionContentViewRecord
) -> None:
    with state._lock:
        current = state.selection_content_views.get(record.handle)
        if current == record:
            state.selection_content_views.pop(record.handle, None)


def _open_selection_content_view(
    state: UiState,
    *,
    run_id: str,
    presentation_selection: Mapping[str, Any],
    requested_session_id: Optional[str],
) -> JsonDict:
    """Exchange exact-head presentation coordinates for one opaque view."""

    if not _selection_content_provider_available(state):
        raise RealmConflict("Selection content provider is unavailable.")
    runtime = _require_realm_runtime(state)
    ref = RunViewRef(run_id=run_id)
    selection_result = runtime.run_views.mint_selection(
        ref=ref,
        presentation_selection=presentation_selection,
    )
    selection = selection_result.selection
    if selection is None:
        raise RealmConflict(
            "Open Read Only is unavailable for this selection: "
            f"{selection_result.eligibility.code}."
        )
    # Resolve the bounded row only to derive logical display metadata.  No
    # content/store reference from that row is retained or returned.
    _summary, row = runtime.run_views.resolve_workbench_selection(
        ref=ref,
        presentation_selection=presentation_selection,
    )
    media_type = (
        "application/vnd.optpilot.tree"
        if selection.entity_ref.startswith("tree:sha256:")
        else "application/octet-stream"
    )
    row_data = row.get("data")
    if isinstance(row_data, Mapping):
        presented_media_type = row_data.get("media_type")
        if (
            isinstance(presented_media_type, str)
            and presented_media_type
            and len(presented_media_type.encode("utf-8")) <= 512
        ):
            media_type = presented_media_type
    return _open_exact_selection_content_view(
        state,
        run_id=ref.run_id,
        public_selection={
            "kind": presentation_selection.get("kind"),
            "entity_id": presentation_selection.get("entity_id"),
            "revision": presentation_selection.get("revision"),
            "sequence": presentation_selection.get("sequence"),
        },
        selection=selection,
        requested_session_id=requested_session_id,
        media_type=media_type,
    )


def _open_exact_selection_content_view(
    state: UiState,
    *,
    run_id: str,
    public_selection: Mapping[str, Any],
    selection: SelectionRef,
    requested_session_id: Optional[str],
    media_type: str,
) -> JsonDict:
    """Open one exact Realm selection through the shared bounded viewer.

    ``public_selection`` carries only the small display coordinate echoed to
    the browser.  The immutable ``SelectionRef`` and all store authority stay
    in the process-local view record and are reauthorized for every read.
    """

    if not _selection_content_provider_available(state):
        raise RealmConflict("Selection content provider is unavailable.")
    if not isinstance(selection, SelectionRef):
        raise TypeError("Selection content view requires a SelectionRef.")
    public = dict(public_selection)
    if set(public) != {"kind", "entity_id", "revision", "sequence"}:
        raise RealmIntegrityError("Selection content display coordinate is invalid.")
    if (
        public["kind"] != selection.kind
        or public["entity_id"] != selection.entity_id
        or public["revision"] != selection.source_revision
        or public["sequence"] != selection.source_sequence
    ):
        raise RealmIntegrityError(
            "Selection content display coordinate differs from its exact selection."
        )
    if (
        not isinstance(media_type, str)
        or not media_type
        or len(media_type.encode("utf-8")) > 512
    ):
        media_type = "application/octet-stream"
    runtime = _require_realm_runtime(state)
    try:
        described = runtime.selection_content.describe(selection=selection)
    except (RealmIntegrityError, RealmNotFound):
        raise RealmConflict(
            "Open Read Only is unavailable because saved files could not "
            "be verified."
        ) from None
    if not described.eligibility.eligible:
        raise RealmConflict(
            "Open Read Only is unavailable for this selection: "
            f"{described.eligibility.code}."
        )
    content_kind = str(described.content_kind)
    if content_kind not in {"tree", "blob"}:
        raise RealmConflict("Open Read Only requires a saved file or folder.")
    if content_kind == "tree":
        media_type = "application/vnd.optpilot.tree"
    session = _selection_content_session(
        state, requested_session_id=requested_session_id
    )
    record = _store_selection_content_view(
        state,
        session=session,
        run_id=RunViewRef(run_id=run_id).run_id,
        public_selection=public,
        selection=selection,
        content_kind=content_kind,
        media_type=media_type,
        entry_count=described.entry_count,
        total_size_bytes=int(described.total_bytes),
    )
    return _public_selection_content_view(record)


def _revalidate_selection_content_view(
    state: UiState, *, handle: Any, session_id: str
) -> tuple[SelectionContentViewRecord, SelectionRef]:
    """Recheck session, actor, immutable authority, and content identity.

    The presentation head is fenced once when Open mints ``record.selection``.
    Later run events must not move that immutable anchor or invalidate viewing;
    each operation instead reauthorizes the server-held SelectionRef directly.
    """

    record = _selection_content_view_record(state, handle=handle, session_id=session_id)
    runtime = _require_realm_runtime(state)
    try:
        described = runtime.selection_content.describe(selection=record.selection)
        if (
            not described.eligibility.eligible
            or described.content_kind != record.content_kind
            or described.entry_count != record.entry_count
            or described.total_bytes != record.total_size_bytes
        ):
            raise RealmConflict("Content view selection changed.")
    except (RealmConflict, RealmIntegrityError, RealmNotFound, ValueError):
        _discard_selection_content_view(state, record=record)
        raise RealmConflict(
            "Content view selection is stale or unavailable. Open it again."
        ) from None
    return record, record.selection


def _selection_content_tree_page(
    state: UiState,
    *,
    handle: str,
    session_id: str,
    page_token: Optional[str],
    limit: int,
) -> JsonDict:
    record, selection = _revalidate_selection_content_view(
        state, handle=handle, session_id=session_id
    )
    if record.content_kind != "tree":
        raise RealmConflict("This content view is a file, not a folder.")
    runtime = _require_realm_runtime(state)
    try:
        page = runtime.selection_content.list_tree(
            selection=selection,
            cursor=page_token,
            limit=limit,
        )
    except (RealmIntegrityError, RealmNotFound):
        _discard_selection_content_view(state, record=record)
        raise RealmConflict(
            "Content view selection is stale or unavailable. Open it again."
        ) from None
    if not page.eligibility.eligible:
        _discard_selection_content_view(state, record=record)
        raise RealmConflict(
            f"Folder files are no longer viewable: {page.eligibility.code}."
        )
    entries = [
        {
            "relative_path": entry.relative_path,
            "kind": entry.kind,
            "size_bytes": entry.size,
            "executable": entry.executable,
        }
        for entry in page.entries
    ]
    return {
        "schema": SELECTION_CONTENT_TREE_PAGE_SCHEMA,
        "content_view": _public_selection_content_view(record),
        "entries": entries,
        "page": {
            "count": len(entries),
            "has_more": page.next_cursor is not None,
            "next_page_token": page.next_cursor,
        },
    }


def _selection_content_media_type(
    record: SelectionContentViewRecord, *, relative_path: Optional[str]
) -> str:
    if relative_path is None:
        return record.media_type
    guessed, _encoding = mimetypes.guess_type(relative_path)
    return guessed or "application/octet-stream"


def _selection_content_is_text(media_type: str) -> bool:
    normalized = media_type.split(";", 1)[0].strip().casefold()
    return (
        normalized.startswith("text/")
        or normalized.endswith(("+json", "+xml"))
        or normalized
        in {
            "application/json",
            "application/javascript",
            "application/toml",
            "application/xml",
            "application/x-httpd-php",
            "application/x-sh",
            "application/x-yaml",
        }
    )


def _selection_content_byte_range(
    state: UiState,
    *,
    handle: str,
    session_id: str,
    relative_path: Optional[str],
    offset: int,
    limit: int,
) -> JsonDict:
    record, selection = _revalidate_selection_content_view(
        state, handle=handle, session_id=session_id
    )
    runtime = _require_realm_runtime(state)
    try:
        selected = runtime.selection_content.read_range(
            selection=selection,
            relative_path=relative_path,
            offset=offset,
            length=limit,
        )
    except (RealmIntegrityError, RealmNotFound):
        _discard_selection_content_view(state, record=record)
        raise RealmConflict(
            "Content view selection is stale or unavailable. Open it again."
        ) from None
    if not selected.eligibility.eligible or selected.data is None:
        _discard_selection_content_view(state, record=record)
        raise RealmConflict(
            f"Selected content is no longer viewable: {selected.eligibility.code}."
        )
    media_type = _selection_content_media_type(
        record, relative_path=selected.relative_path
    )
    encoding = "base64"
    returned_length = len(selected.data)
    encoded: JsonDict = {"data": base64.b64encode(selected.data).decode("ascii")}
    if _selection_content_is_text(media_type):
        try:
            text_content = selected.data.decode("utf-8", errors="strict")
        except UnicodeDecodeError as error:
            # A bounded range can end in the middle of one otherwise valid
            # UTF-8 code point.  Return the maximal complete prefix and leave
            # the suffix for the next offset instead of misclassifying the
            # entire text file as binary.  An empty prefix would make no
            # progress, so that rare tiny-range case remains base64.
            incomplete_suffix = (
                not selected.eof
                and error.reason == "unexpected end of data"
                and error.end == len(selected.data)
                and error.start > 0
            )
            if incomplete_suffix:
                prefix = selected.data[: error.start]
                try:
                    text_content = prefix.decode("utf-8", errors="strict")
                except UnicodeDecodeError:
                    pass
                else:
                    encoding = "utf-8"
                    encoded = {"text": text_content}
                    returned_length = len(prefix)
        else:
            encoding = "utf-8"
            encoded = {"text": text_content}
    assert selected.offset is not None
    assert selected.total_size is not None
    assert selected.eof is not None
    next_offset = selected.offset + returned_length
    return {
        "schema": SELECTION_CONTENT_BYTE_RANGE_SCHEMA,
        "content_view": _public_selection_content_view(record),
        "relative_path": selected.relative_path,
        "media_type": media_type,
        "encoding": encoding,
        **encoded,
        "offset": selected.offset,
        "next_offset": next_offset,
        "has_more": next_offset < selected.total_size,
        "total_size_bytes": selected.total_size,
    }


def _close_selection_content_view(
    state: UiState, *, handle: str, session_id: str
) -> JsonDict:
    record = _selection_content_view_record(state, handle=handle, session_id=session_id)
    # Closing must remain possible after authority/content loss, but still
    # attempt the same immutable-selection reauthorization before discarding
    # the local handle.
    try:
        _revalidate_selection_content_view(state, handle=handle, session_id=session_id)
    except RealmConflict:
        pass
    finally:
        _discard_selection_content_view(state, record=record)
    return {
        "schema": SELECTION_CONTENT_VIEW_CLOSE_RESPONSE_SCHEMA,
        "handle": record.handle,
        "closed": True,
    }


def _mint_assistant_run_selection(
    state: UiState,
    *,
    session_id: str,
    payload: JsonDict,
) -> JsonDict:
    """Validate exact coordinates and mint a session-bound opaque handle."""

    try:
        _require_agent_session(state, session_id)
    except KeyError as error:
        raise ValueError("Assistant session does not exist.") from error
    if not isinstance(payload, Mapping) or set(payload) != {
        "schema",
        "presentation_selection",
    }:
        raise ValueError(
            "Assistant run selection requests accept exactly schema and "
            "presentation_selection."
        )
    if payload["schema"] != ASSISTANT_RUN_SELECTION_REQUEST_SCHEMA:
        raise ValueError("Assistant run selection request schema is unsupported.")
    presentation_selection = payload["presentation_selection"]
    if not isinstance(presentation_selection, Mapping):
        raise ValueError("presentation_selection must be a JSON object.")
    run_id = presentation_selection.get("run_id")
    if not isinstance(run_id, str):
        raise ValueError("Workbench selection run_id must be bounded text.")
    ref = RunViewRef(run_id=run_id)
    runtime = _require_realm_runtime(state)
    summary, row = runtime.run_views.resolve_workbench_selection(
        ref=ref,
        presentation_selection=presentation_selection,
    )
    now = time.monotonic()
    with state._lock:
        _prune_assistant_run_selections_locked(state, now=now)
        handle = f"ars_{uuid.uuid4().hex}"
        while handle in state.assistant_run_selections:  # Defensive collision.
            handle = f"ars_{uuid.uuid4().hex}"
        state.assistant_run_selections[handle] = AssistantRunSelectionRecord(
            handle=handle,
            session_id=session_id,
            run_id=ref.run_id,
            presentation_selection=deepcopy(dict(presentation_selection)),
            created_at=now,
        )
    return {
        "schema": ASSISTANT_RUN_SELECTION_HANDLE_SCHEMA,
        "handle": handle,
        "run_id": ref.run_id,
        "head": summary.cursor.to_dict(),
        "selection": {
            "kind": str(row["kind"]),
            "entity_id": str(row["id"]),
        },
        "expires_in_seconds": ASSISTANT_RUN_SELECTION_TTL_SECONDS,
    }


def _assistant_run_selection_record(
    state: UiState, *, session_id: str, handle: Any
) -> AssistantRunSelectionRecord:
    invalid = (
        "Assistant run selection handle is invalid or expired. Choose Ask "
        "Assistant on the run item again."
    )
    if not isinstance(handle, str) or not re.fullmatch(r"ars_[0-9a-f]{32}", handle):
        raise ValueError(invalid)
    now = time.monotonic()
    with state._lock:
        _prune_assistant_run_selections_locked(state, now=now)
        record = state.assistant_run_selections.get(handle)
    if record is None or record.session_id != session_id:
        raise ValueError(invalid)
    return record


def _discard_assistant_run_selection(
    state: UiState, *, record: AssistantRunSelectionRecord
) -> None:
    with state._lock:
        if state.assistant_run_selections.get(record.handle) == record:
            state.assistant_run_selections.pop(record.handle, None)


def _bounded_assistant_run_selection(row: Mapping[str, Any]) -> JsonDict:
    selection = row.get("selection")
    if not isinstance(selection, Mapping):
        raise ValueError("Resolved Workbench row is missing its selection.")
    data = row.get("data")
    correlations = row.get("correlations")
    projected_correlations: List[JsonDict] = []
    if isinstance(correlations, list):
        for correlation in correlations:
            if not isinstance(correlation, Mapping):
                continue
            related = correlation.get("selection")
            if not isinstance(related, Mapping):
                continue
            projected_correlations.append(
                {
                    "relation": str(correlation.get("relation") or "related"),
                    "kind": str(related.get("kind") or ""),
                    "entity_id": str(related.get("entity_id") or ""),
                }
            )
    return {
        "selection_id": str(selection.get("selection_id") or ""),
        "kind": str(row.get("kind") or selection.get("kind") or ""),
        "entity_id": str(row.get("id") or selection.get("entity_id") or ""),
        "head": {
            "revision": selection.get("revision"),
            "sequence": selection.get("sequence"),
        },
        "data": deepcopy(dict(data)) if isinstance(data, Mapping) else {},
        "correlations": projected_correlations,
    }


def _resolve_assistant_selected_run(
    state: UiState,
    *,
    session_id: str,
    value: Mapping[str, Any],
) -> JsonDict:
    """Derive selected-run context from Realm, never client row contents."""

    allowed = {"run_id", "selection_handle"}
    if (
        not isinstance(value, Mapping)
        or "run_id" not in value
        or not set(value).issubset(allowed)
    ):
        raise ValueError(
            "Assistant selected_run accepts only run_id and selection_handle."
        )
    run_id = value["run_id"]
    if not isinstance(run_id, str):
        raise ValueError("Assistant selected_run run_id must be bounded text.")
    ref = RunViewRef(run_id=run_id)
    runtime = _require_realm_runtime(state)
    selected: Optional[JsonDict] = None
    handle = value.get("selection_handle")
    if handle not in (None, ""):
        record = _assistant_run_selection_record(
            state,
            session_id=session_id,
            handle=handle,
        )
        if record.run_id != ref.run_id:
            raise ValueError(
                "Assistant run selection handle belongs to a different run. "
                "Choose Discuss in Conversation on the Run again."
            )
        try:
            summary, row = runtime.run_views.resolve_workbench_selection(
                ref=ref,
                presentation_selection=record.presentation_selection,
            )
        except (RealmConflict, RealmNotFound, ValueError) as error:
            _discard_assistant_run_selection(state, record=record)
            raise RealmConflict(
                "The Conversation's Run selection is stale or unavailable. "
                "Choose Discuss in Conversation on the Run again."
            ) from error
        selected = _bounded_assistant_run_selection(row)
    else:
        summary = runtime.run_views.workbench_head(ref=ref).summary
    run = _realm_compat_run_row(state, summary.to_dict())
    return {
        "run_id": ref.run_id,
        "name": run.get("name") or ref.run_id,
        "status": run.get("status"),
        "objective": deepcopy(run.get("objective") or {}),
        "head": summary.cursor.to_dict(),
        "selection": selected,
    }


def _agent_context_packet(
    state: UiState, session: JsonDict, ui_context: Optional[JsonDict] = None
) -> JsonDict:
    ui_context = ui_context or {}
    attached = []
    for workspace_id in session.get("attached_workspace_ids", []) or []:
        workspace = _workspace_by_id(state, workspace_id)
        if workspace:
            attached.append(
                {
                    "id": workspace["id"],
                    "title": workspace.get("title"),
                    "root": workspace.get("root"),
                    "mode": workspace.get("mode"),
                    "source_type": workspace.get("source_type"),
                    "registered_entries": workspace.get("registered_entries", []),
                    "focus_paths": workspace.get("focus_paths", []),
                }
            )
    catalog = _catalog_payload(state)
    current_page = _assistant_page_name(ui_context.get("current_page"))
    assistant_mode = str(ui_context.get("assistant_mode") or "chat")
    selected_workspace = None
    ui_selected_workspace = (
        ui_context.get("selected_workspace")
        if isinstance(ui_context.get("selected_workspace"), dict)
        else None
    )
    ui_selected_workspace_id = str((ui_selected_workspace or {}).get("id") or "")
    if current_page == "editor" and ui_selected_workspace_id:
        selected_workspace = next(
            (item for item in attached if item["id"] == ui_selected_workspace_id), None
        )
    if selected_workspace is None:
        default_workspace_id = str(session.get("selected_workspace_id") or "")
        if default_workspace_id:
            selected_workspace = next(
                (item for item in attached if item["id"] == default_workspace_id), None
            )
    selected_catalog_entry = (
        ui_context.get("selected_catalog_entry")
        if current_page == "catalog"
        and isinstance(ui_context.get("selected_catalog_entry"), dict)
        else None
    )
    selected_study_plan = (
        ui_context.get("selected_study_plan")
        if current_page == "studies"
        and isinstance(ui_context.get("selected_study_plan"), dict)
        else None
    )
    ui_selected_run = (
        ui_context.get("selected_run")
        if current_page == "runs" and isinstance(ui_context.get("selected_run"), dict)
        else None
    )
    selected_run = (
        _resolve_assistant_selected_run(
            state,
            session_id=str(session.get("id") or ""),
            value=ui_selected_run,
        )
        if ui_selected_run is not None
        else None
    )
    selected_interface = _assistant_selected_interface(
        ui_context.get("selected_interface"), current_page=current_page
    )
    registration_menu = (
        ui_context.get("registration_menu")
        if assistant_mode == "registration"
        and isinstance(ui_context.get("registration_menu"), dict)
        else None
    )
    code_editor = (
        ui_context.get("code_editor")
        if current_page == "editor" and isinstance(ui_context.get("code_editor"), dict)
        else None
    )
    workspace_preview = (
        ui_context.get("workspace_preview")
        if current_page == "editor"
        and isinstance(ui_context.get("workspace_preview"), dict)
        else None
    )
    return state.agent_adapter.context_packet(
        session_id=str(session.get("id") or ""),
        conversation={
            "title": str(session.get("title") or ""),
            "title_origin": _agent_title_origin(session),
            "automatic_title_allowed": _agent_title_origin(session) != "user",
        },
        selected_workspace=selected_workspace,
        attached_workspaces=attached,
        catalog_counts={
            "environments": len(catalog["environments"]),
            "methods": len(catalog["methods"]),
            "resources": len(catalog.get("resources", [])),
        },
        study_plan_count=len(catalog["studies"]),
        run_count=len(_list_runs(state)),
        current_page=current_page,
        registration_menu=registration_menu,
        selected_catalog_entry=selected_catalog_entry,
        selected_study_plan=selected_study_plan,
        selected_run=selected_run,
        selected_interface=selected_interface,
        code_editor=code_editor,
        workspace_preview=workspace_preview,
        visible_state={
            key: value
            for key, value in ui_context.items()
            if key
            not in {
                "current_page",
                "registration_menu",
                "selected_workspace",
                "selected_catalog_entry",
                "selected_study_plan",
                "selected_run",
                "selected_interface",
                "code_editor",
                "workspace_preview",
            }
        },
        assistant_capabilities=_assistant_capability_summary(state),
    )


def _assistant_page_name(value: Any) -> str:
    page = str(value or "editor")
    return {
        "workspace": "editor",
        "experiments": "studies",
    }.get(page, page)


def _assistant_selected_interface(
    value: Any, *, current_page: str
) -> Optional[JsonDict]:
    """Bound a full-stage interface selection to exact launch coordinates.

    The packet carries identity only — launch id, lifecycle status, and the
    Catalog or Workspace source that launched it — never preview URLs, host
    paths, or presentation tokens (U5).
    """

    if current_page not in {"interface", "editor"} or not isinstance(
        value, Mapping
    ):
        return None
    result: JsonDict = {}
    for key in ("launch_id", "status", "launch_scope", "profile_id", "label"):
        item = value.get(key)
        if isinstance(item, str) and item:
            result[key] = item[:256]
    if not result.get("launch_id"):
        return None
    source = value.get("source")
    if isinstance(source, Mapping):
        bounded_source: JsonDict = {}
        for key in ("kind", "uid", "key", "workspace_id", "workspace_title"):
            item = source.get(key)
            if isinstance(item, str) and item:
                bounded_source[key] = item[:256]
        if bounded_source:
            result["source"] = bounded_source
    return result


def _read_workspace_index(state: UiState) -> List[JsonDict]:
    with state._workspace_index_lock:
        path = _workspace_index_path(state)
        try:
            exists = path.exists()
        except OSError as error:
            raise _workspace_index_storage_unavailable(error) from error
        if not exists:
            return []
        items = _workspace_index_payload(path)["workspaces"]
        return [
            item
            for item in items
            if isinstance(item, dict)
            and item.get("id")
            and (
                item.get("root")
                or item.get("ownership") == "realm-managed"
                or item.get("source_type") == "realm-workspace"
                or (
                    item.get("source_type") == "catalog"
                    and isinstance(item.get("catalog_origin"), dict)
                    and item.get("catalog_origin")
                )
            )
        ]


def _write_workspace_index(state: UiState, workspaces: List[JsonDict]) -> None:
    with state._workspace_index_lock:
        cleaned = [_stored_workspace_record(item) for item in workspaces]
        payload = {
            "workspaces": sorted(
                cleaned, key=lambda item: item.get("updated_at", ""), reverse=True
            )
        }
        _atomic_write_workspace_index_payload(
            _workspace_index_path(state), payload
        )


def _stored_workspace_record(workspace: JsonDict) -> JsonDict:
    stored = {
        key: value
        for key, value in dict(workspace).items()
        if key not in DERIVED_WORKSPACE_FIELDS
    }
    if (
        stored.get("source_type") == "catalog"
        and isinstance(stored.get("catalog_origin"), dict)
        and stored.get("catalog_origin")
    ):
        # A catalog View persists only its exact logical selection.  Its leased
        # provider path is reconstructed on demand after every Studio restart.
        stored["root"] = ""
        stored["source_root"] = ""
        stored["realization_state"] = "closed"
    return stored


def _workspace_attachment_map(state: UiState) -> Dict[str, List[str]]:
    attachments: Dict[str, List[str]] = {}
    for session in _read_agent_session_index(state):
        session_id = str(session.get("id") or "")
        if not session_id:
            continue
        for workspace_id in session.get("attached_workspace_ids", []) or []:
            workspace_key = str(workspace_id)
            if workspace_key:
                attachments.setdefault(workspace_key, []).append(session_id)
    return {key: sorted(set(value)) for key, value in attachments.items()}


def _decorate_ui_workspace(state: UiState, workspace: JsonDict) -> JsonDict:
    item = dict(workspace)
    purpose = _workspace_purpose_record(state, item)
    item["purpose"] = purpose.purpose.value
    item["purpose_revision"] = purpose.revision
    item["visible_in_workspaces"] = (
        purpose.purpose is WorkspacePurpose.USER_PROJECT
    )
    item["ownership"] = str(item.get("ownership") or _workspace_ownership(state, item))
    item["managed_by_studio"] = item["ownership"] == "studio-owned"
    item["delete_action"] = _workspace_delete_action(state, item)
    item["delete_label"] = _workspace_delete_label(item, item["delete_action"])
    if item.get("reopen_required"):
        item["runtime"] = {
            "target": "per-workspace-container",
            "status": "closed",
            "containerized": False,
            "message": "Reopen the managed workspace before using its runtime.",
        }
        item["interface"] = {}
    else:
        item["runtime"] = _workspace_runtime_status(state, item)
        item["interface"] = _workspace_interface_summary(state, item)
    return item


def _workspace_ownership(state: UiState, workspace: JsonDict) -> str:
    root = Path(str(workspace.get("root") or "")).resolve()
    workspace_id = str(workspace.get("id") or "")
    source_type = str(workspace.get("source_type") or "")
    mode = str(workspace.get("mode") or "editable")
    if workspace_id and _is_managed_draft_root(state, workspace_id, root):
        return "studio-owned"
    if source_type == "run" or mode == "analysis":
        return "run-artifact"
    if source_type == "catalog" or mode == "read-only":
        return "catalog-asset"
    return "external-reference"


def _workspace_delete_action(state: UiState, workspace: JsonDict) -> str:
    ownership = str(
        workspace.get("ownership") or _workspace_ownership(state, workspace)
    )
    if ownership == "realm-managed":
        return "retire_workspace"
    if ownership == "studio-owned":
        return "delete_draft"
    return "remove_reference"


def _workspace_delete_label(workspace: JsonDict, action: str) -> str:
    del workspace
    return "Remove from Workspaces" if action == "remove_reference" else "Delete Workspace"


def _workspace_runtime_status(state: UiState, workspace: JsonDict) -> JsonDict:
    return state.workspace_runtime.status(workspace)


def _managed_workspace_summaries(state: UiState):
    if not _managed_workspace_provider_available(state):
        return None
    runtime = state.realm_runtime
    assert runtime is not None
    return {
        summary.workspace_id: summary
        for summary in runtime.editable_workspaces.list_workspaces()
    }


def _workspace_time_iso(value: float) -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(float(value)))


def _managed_workspace_placeholder(
    summary: Any,
    *,
    existing: Optional[Mapping[str, Any]] = None,
    attached_sessions: Optional[List[str]] = None,
) -> JsonDict:
    """Return a durable identity without manufacturing a filesystem root."""

    existing = dict(existing or {})
    result = {
        "id": summary.workspace_id,
        "title": summary.title,
        "root": "",
        "source_type": str(existing.get("source_type") or "realm-workspace"),
        "mode": str(existing.get("mode") or "editable"),
        "status": "closed",
        "description": str(
            existing.get("description") or "Realm-managed editable workspace"
        ),
        "attached_sessions": list(attached_sessions or []),
        "registered_entries": list(existing.get("registered_entries", []) or []),
        "catalog_publications": list(
            existing.get("catalog_publications", []) or []
        ),
        "catalog_origin": deepcopy(existing.get("catalog_origin", {}) or {}),
        "focus_paths": list(existing.get("focus_paths", []) or []),
        "registration_enabled": bool(
            existing.get("registration_enabled", True)
        ),
        "setup": dict(existing.get("setup", {}) or {}),
        "validation": dict(existing.get("validation", {}) or {}),
        "source_path": "",
        "source_root": "",
        "created_at": str(
            existing.get("created_at") or _workspace_time_iso(summary.created_at)
        ),
        "updated_at": _workspace_time_iso(summary.updated_at),
        "ownership": "realm-managed",
        "realm_workspace_id": summary.workspace_id,
        "realm_workspace_revision": summary.workspace_revision,
        "realm_workspace_metadata_revision": summary.metadata_revision,
        "realm_checkout_id": "",
        "realization_state": "closed",
        "reopen_required": True,
        "last_commit_status": str(existing.get("last_commit_status") or ""),
    }
    if existing.get("purpose"):
        result["purpose"] = str(existing["purpose"])
    if isinstance(existing.get("purpose_subject"), Mapping) and existing.get(
        "purpose_subject"
    ):
        result["purpose_subject"] = deepcopy(existing["purpose_subject"])
    return result


def _list_ui_workspaces(
    state: UiState,
    *,
    include_support: bool = False,
    preserve_workspace_ids: Iterable[str] = (),
) -> List[JsonDict]:
    # Conversations normalize their Workspace attachments while holding the
    # agent-session index lock and then reading the Workspace index.  Take the
    # same agent -> Workspace lock order here.  Acquiring the Workspace lock
    # first would deadlock the parallel Conversation and Workspace requests
    # issued during initial page hydration.
    attachment_map = _workspace_attachment_map(state)
    with state._workspace_index_lock:
        return _list_ui_workspaces_unlocked(
            state,
            include_support=include_support,
            preserve_workspace_ids=preserve_workspace_ids,
            attachment_map=attachment_map,
        )


def _list_ui_workspaces_unlocked(
    state: UiState,
    *,
    include_support: bool = False,
    preserve_workspace_ids: Iterable[str] = (),
    attachment_map: Optional[Mapping[str, List[str]]] = None,
) -> List[JsonDict]:
    workspaces = []
    returned = []
    changed = False
    preserved = {str(item) for item in preserve_workspace_ids if str(item)}
    attachment_map = dict(attachment_map or {})
    managed = _managed_workspace_summaries(state)
    visible_managed: set[str] = set()
    for workspace in _read_workspace_index(state):
        workspace = dict(workspace)
        if (
            workspace.get("source_type") == "catalog"
            and isinstance(workspace.get("catalog_origin"), dict)
            and workspace.get("catalog_origin")
        ):
            workspace = _realize_catalog_workspace_reference(state, workspace)
        root_text = str(workspace.get("root") or "")
        root = Path(root_text) if root_text else None
        ownership = str(
            workspace.get("ownership") or _workspace_ownership(state, workspace)
        )
        if ownership == "realm-managed" and managed is not None:
            realm_workspace_id = str(
                workspace.get("realm_workspace_id") or workspace.get("id") or ""
            )
            summary = managed.get(realm_workspace_id)
            if summary is None:
                state.workspace_runtime.delete(str(workspace.get("id") or ""))
                changed = True
                continue
            visible_managed.add(realm_workspace_id)
            if root is None or not root.exists():
                state.workspace_runtime.delete(str(workspace.get("id") or ""))
                closed = _managed_workspace_placeholder(
                    summary,
                    existing=workspace,
                    attached_sessions=attachment_map.get(
                        str(workspace.get("id") or ""), []
                    ),
                )
                if closed != workspace:
                    changed = True
                workspace = closed
                workspaces.append(workspace)
                decorated = _decorate_ui_workspace(state, workspace)
                if include_support or decorated["visible_in_workspaces"]:
                    returned.append(decorated)
                continue
            runtime = state.realm_runtime
            assert runtime is not None
            checkout = runtime.editable_workspaces.open_workspace(
                operation_id=f"studio/workspace/{realm_workspace_id}/validate-visible",
                workspace_id=realm_workspace_id,
                expected_workspace_revision=summary.workspace_revision,
            )
            canonical_root = str(checkout.root_path)
            canonical = {
                "title": summary.title,
                "root": canonical_root,
                "source_root": canonical_root,
                "realm_workspace_id": summary.workspace_id,
                "realm_workspace_revision": summary.workspace_revision,
                "realm_workspace_metadata_revision": summary.metadata_revision,
                "realm_checkout_id": checkout.checkout_id,
                "ownership": "realm-managed",
                "realization_state": "open",
                "reopen_required": False,
            }
            if any(workspace.get(key) != value for key, value in canonical.items()):
                workspace.update(canonical)
                changed = True
        if root is None or not root.exists():
            workspace["status"] = "missing"
            changed = True
        attached_sessions = attachment_map.get(str(workspace.get("id") or ""), [])
        if workspace.get("attached_sessions", []) != attached_sessions:
            workspace["attached_sessions"] = attached_sessions
            changed = True
        if (
            str(workspace.get("id") or "") not in preserved
            and not state._code_workspace_start_in_progress(
                str(workspace.get("id") or "")
            )
            and _workspace_should_remove_after_last_detach(
                state, workspace, keep_recent=True
            )
        ):
            workspace_id = str(workspace.get("id") or "")
            try:
                _require_no_live_workspace_interface_launches(
                    state, workspace_id, action="reclaiming"
                )
            except RealmConflict:
                # A live interface still borrows this source. Keep both its
                # logical reference and runtime until terminal proof exists.
                pass
            else:
                runtime_path = state.workspace_runtime._workspace_runtime_dir(
                    workspace_id
                )
                runtime_present = runtime_path.exists() or runtime_path.is_symlink()
                runtime_deleted = state.workspace_runtime.delete(workspace_id)
                if not runtime_present or runtime_deleted:
                    _release_catalog_workspace_projection(state, workspace_id)
                    changed = True
                    continue
        workspaces.append(workspace)
        decorated = _decorate_ui_workspace(state, workspace)
        if include_support or decorated["visible_in_workspaces"]:
            returned.append(decorated)
    if changed:
        _write_workspace_index(state, workspaces)
    if managed is not None:
        for workspace_id, summary in managed.items():
            if workspace_id in visible_managed:
                continue
            decorated = _decorate_ui_workspace(
                state,
                _managed_workspace_placeholder(
                    summary,
                    attached_sessions=attachment_map.get(workspace_id, []),
                ),
            )
            if include_support or decorated["visible_in_workspaces"]:
                returned.append(decorated)
    return returned


def _workspace_by_id(state: UiState, workspace_id: str) -> Optional[JsonDict]:
    # An exact action is evidence that this support reference is still in use.
    # Do not let opportunistic list pruning delete the requested read-only view
    # while resolving that same request.
    for workspace in _list_ui_workspaces(
        state,
        include_support=True,
        preserve_workspace_ids=(workspace_id,),
    ):
        if workspace.get("id") == workspace_id:
            return workspace
    return None


def _require_ui_workspace(state: UiState, workspace_id: str) -> JsonDict:
    workspace = _workspace_by_id(state, workspace_id)
    if not workspace:
        # The bare id as the error ("KeyError: 'ws_x'") reached the model as
        # the whole explanation and derailed a live turn. Old conversations
        # keep references to deleted workspaces, so a stale id is an
        # expected input here, not programmer error.
        raise KeyError(
            f"Workspace '{workspace_id}' was not found -- it may have been "
            "deleted. Call optpilot_workspace_list and use an id from its "
            "workspaces list, or optpilot_workspace_create for a new one."
        )
    return workspace


def _upsert_ui_workspace(state: UiState, workspace: JsonDict) -> JsonDict:
    workspace = dict(workspace)
    workspace["updated_at"] = _now_iso()
    with state._workspace_index_lock:
        workspaces = [
            item
            for item in _read_workspace_index(state)
            if item.get("id") != workspace.get("id")
        ]
        workspaces.append(_stored_workspace_record(workspace))
        _write_workspace_index(state, workspaces)
    return _decorate_ui_workspace(state, workspace)


def _create_ui_workspace(state: UiState, payload: JsonDict) -> JsonDict:
    workspace_id = _safe_artifact_identifier(
        str(payload.get("id") or f"ws_{uuid.uuid4().hex[:10]}"),
        "workspace id",
    )
    if len(workspace_id.encode("utf-8")) > 180:
        raise ValueError("workspace id is too long.")
    root_value = payload.get("root")
    if root_value:
        root = _resolve_user_path(root_value, state.cwd)
        _safe_workspace_root(state, root)
    else:
        root = state.workspaces_dir / workspace_id / "workspace"
    root.mkdir(parents=True, exist_ok=True)
    title = str(payload.get("title") or "Untitled workspace")
    if bool(payload.get("initialize_if_empty", True)) and not any(root.iterdir()):
        readme = root / "README.md"
        readme.write_text(
            f"# {title}\n\nThis is a generic OptPilot workspace. Add code, configs, data, or notes here, then use Register to Catalog when it is ready.\n",
            encoding="utf-8",
        )
    workspace = {
        "id": workspace_id,
        "title": title,
        "root": str(root.resolve()),
        "source_type": str(payload.get("source_type") or "blank"),
        "mode": str(payload.get("mode") or "editable"),
        "status": str(payload.get("status") or "ready"),
        "description": str(payload.get("description") or "Generic project workspace"),
        "attached_sessions": list(payload.get("attached_sessions", []) or []),
        "registered_entries": list(payload.get("registered_entries", []) or []),
        "catalog_publications": list(payload.get("catalog_publications", []) or []),
        "catalog_origin": deepcopy(payload.get("catalog_origin", {}) or {}),
        "focus_paths": list(payload.get("focus_paths", []) or []),
        "registration_enabled": bool(payload.get("registration_enabled", True)),
        "setup": dict(payload.get("setup", {}) or {}),
        "validation": dict(payload.get("validation", {}) or {}),
        "source_path": str(payload.get("source_path") or ""),
        "source_root": str(payload.get("source_root") or payload.get("root") or ""),
        "created_at": str(payload.get("created_at") or _now_iso()),
        "realm_workspace_id": str(payload.get("realm_workspace_id") or ""),
        "realm_workspace_revision": payload.get("realm_workspace_revision"),
        "realm_workspace_metadata_revision": payload.get(
            "realm_workspace_metadata_revision"
        ),
        "realm_checkout_id": str(payload.get("realm_checkout_id") or ""),
        "realization_state": str(payload.get("realization_state") or "open"),
        "reopen_required": bool(payload.get("reopen_required", False)),
        "last_commit_status": str(payload.get("last_commit_status") or ""),
    }
    if payload.get("purpose"):
        workspace["purpose"] = WorkspacePurpose(
            str(payload["purpose"])
        ).value
    if payload.get("purpose_subject") and isinstance(
        payload.get("purpose_subject"), Mapping
    ):
        workspace["purpose_subject"] = EntityCoordinate.from_dict(
            payload["purpose_subject"]
        ).to_dict()
    workspace["ownership"] = str(
        payload.get("ownership") or _workspace_ownership(state, workspace)
    )
    return _upsert_ui_workspace(state, workspace)


def _connect_local_folder(state: UiState, payload: JsonDict) -> JsonDict:
    """Add one existing, server-visible folder as editable work without copying it."""

    if not isinstance(payload, dict):
        raise ValueError("Open local folder request must be a JSON object.")
    unexpected = sorted(set(payload) - {"path", "title"})
    if unexpected:
        raise ValueError(
            "Unsupported Open local folder fields: " + ", ".join(unexpected) + "."
        )
    value = str(payload.get("path") or "").strip()
    if not value:
        raise ValueError("Choose an existing folder path.")
    requested = _resolve_user_path(value, state.cwd)
    if not requested.exists() or not requested.is_dir():
        raise ValueError("The selected local folder does not exist or is not a directory.")
    root = _safe_workspace_root(state, requested)
    workspace_id = "folder_" + request_digest(
        {
            "actor_id": _studio_actor_id(state),
            "root": str(root),
            "schema": "optpilot.connected-local-folder.v1",
        }
    )[:24]
    title = str(payload.get("title") or root.name or "Local folder").strip()
    if not title:
        raise ValueError("Local folder title cannot be empty.")
    return _create_ui_workspace(
        state,
        {
            "id": workspace_id,
            "title": title,
            "root": str(root),
            "source_root": str(root),
            "source_path": str(root),
            "source_type": "local-folder",
            "mode": "editable",
            "description": (
                "Connected local folder. Removing this Workspace from Studio "
                "does not delete the source folder."
            ),
            "initialize_if_empty": False,
            "ownership": "external-reference",
            "registration_enabled": True,
            "purpose": WorkspacePurpose.USER_PROJECT.value,
        },
    )


def _managed_workspace_request_revision(
    payload: JsonDict, *, required: bool
) -> Optional[int]:
    if not isinstance(payload, dict):
        raise ValueError("Managed workspace request must be a JSON object.")
    unexpected = sorted(set(payload) - {"expected_workspace_revision"})
    if unexpected:
        raise ValueError(
            "Unsupported managed workspace request fields: "
            + ", ".join(unexpected)
            + "."
        )
    value = payload.get("expected_workspace_revision")
    if value is None and not required:
        return None
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ValueError("expected_workspace_revision must be a positive integer.")
    return value


def _managed_workspace_ui_payload(
    summary: Any,
    checkout: Any,
    *,
    existing: Optional[JsonDict] = None,
    last_commit_status: str = "",
) -> JsonDict:
    existing = dict(existing or {})
    root = checkout.root_path
    return {
        "id": summary.workspace_id,
        "title": summary.title,
        "root": str(root),
        "source_root": str(root),
        "source_type": "realm-workspace",
        "mode": "editable",
        "status": "ready",
        "description": str(
            existing.get("description") or "Realm-managed editable workspace"
        ),
        "source_path": "",
        "registration_enabled": True,
        "ownership": "realm-managed",
        "initialize_if_empty": False,
        "realm_workspace_id": summary.workspace_id,
        "realm_workspace_revision": summary.workspace_revision,
        "realm_workspace_metadata_revision": summary.metadata_revision,
        "realm_checkout_id": checkout.checkout_id,
        "realization_state": "open",
        "reopen_required": False,
        "last_commit_status": last_commit_status,
        "registered_entries": list(existing.get("registered_entries", []) or []),
        "catalog_publications": list(existing.get("catalog_publications", []) or []),
        "catalog_origin": deepcopy(existing.get("catalog_origin", {}) or {}),
        "focus_paths": list(existing.get("focus_paths", []) or []),
        "setup": dict(existing.get("setup", {}) or {}),
        "validation": dict(existing.get("validation", {}) or {}),
        "purpose": str(existing.get("purpose") or ""),
        "purpose_subject": deepcopy(existing.get("purpose_subject", {}) or {}),
        "created_at": str(
            existing.get("created_at") or _workspace_time_iso(summary.created_at)
        ),
    }


def _reopen_managed_workspace(
    state: UiState, workspace_id: str, payload: JsonDict
) -> JsonDict:
    if not _managed_workspace_provider_available(state):
        raise RealmConflict("Managed editable workspace provider is unavailable.")
    expected = _managed_workspace_request_revision(payload, required=False)
    runtime = state.realm_runtime
    assert runtime is not None
    summary = runtime.editable_workspaces.read_workspace(workspace_id=workspace_id)
    if expected is not None and summary.workspace_revision != expected:
        raise RealmConflict("Workspace revision changed.")
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"studio/workspace/{workspace_id}/reopen/{uuid.uuid4().hex}",
        workspace_id=workspace_id,
        expected_workspace_revision=summary.workspace_revision,
    )
    existing = next(
        (
            item
            for item in _read_workspace_index(state)
            if item.get("id") == workspace_id
        ),
        None,
    )
    return _create_ui_workspace(
        state,
        _managed_workspace_ui_payload(summary, checkout, existing=existing),
    )


def _commit_managed_workspace(
    state: UiState,
    workspace_id: str,
    payload: JsonDict,
    *,
    operation_id: Optional[str] = None,
) -> JsonDict:
    if not _managed_workspace_provider_available(state):
        raise RealmConflict("Managed editable workspace provider is unavailable.")
    expected = _managed_workspace_request_revision(payload, required=True)
    assert expected is not None
    existing = _require_ui_workspace(state, workspace_id)
    if existing.get("ownership") != "realm-managed":
        raise ValueError("Only Realm-managed workspaces have durable revisions.")
    if existing.get("reopen_required"):
        raise RealmConflict("Reopen the managed workspace before committing it.")
    runtime = state.realm_runtime
    assert runtime is not None
    committed = runtime.editable_workspaces.commit_workspace(
        operation_id=(
            operation_id
            or f"studio/workspace/{workspace_id}/commit/{uuid.uuid4().hex}"
        ),
        workspace_id=workspace_id,
        expected_workspace_revision=expected,
    )
    summary = runtime.editable_workspaces.read_workspace(workspace_id=workspace_id)
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"studio/workspace/{workspace_id}/open-after-commit/{uuid.uuid4().hex}",
        workspace_id=workspace_id,
        expected_workspace_revision=committed.current_revision,
    )
    workspace = _create_ui_workspace(
        state,
        _managed_workspace_ui_payload(
            summary,
            checkout,
            existing=existing,
            last_commit_status=committed.status.value,
        ),
    )
    return {"workspace": workspace, "commit": committed.to_dict()}


def _commit_managed_workspace_file(
    state: UiState,
    workspace_id: str,
    *,
    expected_workspace_revision: int,
    relative_path: str,
    operation_id: Optional[str] = None,
) -> JsonDict:
    """Commit one generated file while retaining unrelated checkout edits."""

    if not _managed_workspace_provider_available(state):
        raise RealmConflict("Managed editable workspace provider is unavailable.")
    existing = _require_ui_workspace(state, workspace_id)
    if existing.get("ownership") != "realm-managed":
        raise ValueError("Only Realm-managed workspaces have durable revisions.")
    if existing.get("reopen_required"):
        raise RealmConflict("Reopen the managed workspace before committing it.")
    runtime = state.realm_runtime
    assert runtime is not None
    committed = runtime.editable_workspaces.commit_workspace_file(
        operation_id=(
            operation_id
            or f"studio/workspace/{workspace_id}/commit-file/{uuid.uuid4().hex}"
        ),
        workspace_id=workspace_id,
        expected_workspace_revision=expected_workspace_revision,
        relative_path=relative_path,
        executable=False,
    )
    summary = runtime.editable_workspaces.read_workspace(workspace_id=workspace_id)
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"studio/workspace/{workspace_id}/open-after-file-commit/{uuid.uuid4().hex}",
        workspace_id=workspace_id,
        expected_workspace_revision=committed.current_revision,
    )
    workspace = _create_ui_workspace(
        state,
        _managed_workspace_ui_payload(
            summary,
            checkout,
            existing=existing,
            last_commit_status=committed.status.value,
        ),
    )
    return {"workspace": workspace, "commit": committed.to_dict()}


def _detach_workspace(state: UiState, workspace_id: str, session_id: str) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    if session_id:
        sessions = []
        for session in _read_agent_session_index(state):
            if session.get("id") == session_id:
                session = dict(session)
                attached = [
                    item
                    for item in session.get("attached_workspace_ids", [])
                    if item != workspace_id
                ]
                session["attached_workspace_ids"] = attached
                if session.get("selected_workspace_id") == workspace_id:
                    session["selected_workspace_id"] = ""
                session["updated_at"] = _now_iso()
            sessions.append(session)
        _write_agent_session_index(state, sessions)
    workspace["attached_sessions"] = _workspace_attachment_map(state).get(
        workspace_id, []
    )
    if _workspace_should_remove_after_last_detach(state, workspace):
        return _remove_ui_workspace_reference(state, workspace_id)
    return _upsert_ui_workspace(state, workspace)


def _workspace_should_remove_after_last_detach(
    state: UiState, workspace: JsonDict, *, keep_recent: bool = False
) -> bool:
    if workspace.get("attached_sessions"):
        return False
    if str(workspace.get("mode") or "") not in {"read-only", "analysis"}:
        return False
    if keep_recent and _workspace_created_within(
        workspace, READ_ONLY_WORKSPACE_PRUNE_GRACE_SECONDS
    ):
        return False
    return _workspace_ownership(state, workspace) in {"catalog-asset", "run-artifact"}


def _workspace_created_within(workspace: JsonDict, seconds: int) -> bool:
    created_at = str(workspace.get("created_at") or "")
    if not created_at:
        return False
    try:
        created_epoch = calendar.timegm(time.strptime(created_at, "%Y-%m-%dT%H:%M:%SZ"))
    except ValueError:
        return False
    return time.time() - created_epoch < seconds


def _require_no_live_workspace_interface_launches(
    state: UiState,
    workspace_id: str,
    *,
    action: str,
) -> None:
    live_statuses = {"queued", "running", "ready", "stopping", "cleanup_pending"}
    with state._lock:
        blockers = {
            job.launch_id
            for job in state.interface_launches.values()
            if job.launch_scope == "workspace-transient"
            and job.source_workspace_id == workspace_id
            and job.status in live_statuses
        }
    # Jobs are process-local, but an unconfirmed launch runtime survives a
    # Studio restart.  Its ownership record is the durable fence that prevents
    # deleting a source root which may still be mounted by that runtime.
    runtime_directories = getattr(state.workspace_runtime, "_runtime_directories", None)
    persisted_runtime_items = (
        runtime_directories(workspace_prefix="interface-launch-")
        if callable(runtime_directories)
        else [
            (path.name, path)
            for path in state.runtime_dir.glob("interface-launch-*")
        ]
    )
    for runtime_id, runtime_path in persisted_runtime_items:
        if runtime_path.parent != state.runtime_dir or runtime_path.is_symlink():
            continue
        try:
            record = state.workspace_runtime._read_record(runtime_id)
        except (OSError, RuntimeError, ValueError):
            continue
        if str(record.get("source_workspace_id") or "") != workspace_id:
            continue
        proof = record.get("terminal_proof")
        terminal_confirmed = bool(
            record.get("status") == "stopped"
            and isinstance(proof, dict)
            and proof.get("terminal_confirmed")
        )
        if not terminal_confirmed:
            blockers.add(runtime_id)
    if blockers:
        raise RealmConflict(
            "Stop the workspace interface launch before "
            f"{action} this workspace ({', '.join(sorted(blockers))})."
        )


def _remove_ui_workspace_reference(state: UiState, workspace_id: str) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    _require_no_live_workspace_interface_launches(
        state, workspace_id, action="removing"
    )
    sessions = _read_agent_session_index(state)
    changed_sessions = []
    for session in sessions:
        attached = [
            item
            for item in session.get("attached_workspace_ids", [])
            if item != workspace_id
        ]
        if attached != session.get("attached_workspace_ids", []):
            session = dict(session)
            session["attached_workspace_ids"] = attached
            if session.get("selected_workspace_id") == workspace_id:
                session["selected_workspace_id"] = ""
            session["updated_at"] = _now_iso()
        changed_sessions.append(session)
    _write_agent_session_index(state, changed_sessions)
    with state._workspace_index_lock:
        _write_workspace_index(
            state,
            [
                item
                for item in _read_workspace_index(state)
                if item.get("id") != workspace_id
            ],
        )
    runtime_deleted = state.workspace_runtime.delete(workspace_id)
    _release_catalog_workspace_projection(state, workspace_id)
    workspace = dict(workspace)
    workspace["deleted"] = True
    workspace["files_deleted"] = False
    workspace["runtime_deleted"] = runtime_deleted
    workspace["delete_action"] = "remove_reference"
    workspace["delete_label"] = _workspace_delete_label(
        workspace, workspace["delete_action"]
    )
    return workspace


def _rename_ui_workspace(
    state: UiState, workspace_id: str, payload: JsonDict
) -> JsonDict:
    request = _exact_json_object(
        payload,
        expected={
            "schema",
            "request_id",
            "title",
            "expected_title",
            "expected_metadata_revision",
        },
        label="Workspace rename request",
    )
    if request["schema"] != "optpilot.studio-workspace-rename-request.v1":
        raise ValueError("Workspace rename request schema is unsupported.")
    request_id = _canonical_request_uuid(request["request_id"])
    cleaned = " ".join(str(request["title"] or "").strip().split())
    if not cleaned:
        raise ValueError("Workspace name cannot be empty.")
    if len(cleaned) > 120:
        raise ValueError("Workspace name must be 120 characters or fewer.")
    workspace = _require_ui_workspace(state, workspace_id)
    expected_title = str(request["expected_title"] or "")
    if str(workspace.get("ownership") or "") == "realm-managed":
        expected_metadata_revision = request["expected_metadata_revision"]
        if (
            isinstance(expected_metadata_revision, bool)
            or not isinstance(expected_metadata_revision, int)
            or expected_metadata_revision <= 0
        ):
            raise ValueError(
                "expected_metadata_revision must be a positive integer."
            )
        if not _managed_workspace_provider_available(state):
            raise RealmConflict("Managed editable workspace provider is unavailable.")
        runtime = state.realm_runtime
        assert runtime is not None
        summary = runtime.editable_workspaces.rename_workspace(
            operation_id=(
                f"studio/workspace/{workspace_id}/rename/{request_id}"
            ),
            workspace_id=str(
                workspace.get("realm_workspace_id") or workspace.get("id") or ""
            ),
            expected_metadata_revision=expected_metadata_revision,
            title=cleaned,
        )
        current = dict(_require_ui_workspace(state, workspace_id))
        current["title"] = summary.title
        current["realm_workspace_metadata_revision"] = summary.metadata_revision
        current["updated_at"] = _workspace_time_iso(summary.updated_at)
        return _upsert_ui_workspace(state, current)
    if expected_title != str(workspace.get("title") or ""):
        raise RealmConflict("Workspace name changed.")
    workspace["title"] = cleaned
    return _upsert_ui_workspace(state, workspace)


def _retire_managed_ui_workspace(state: UiState, workspace: JsonDict) -> JsonDict:
    source_workspace_id = str(workspace.get("id") or "")
    _require_no_live_workspace_interface_launches(
        state, source_workspace_id, action="retiring"
    )
    if not _managed_workspace_provider_available(state):
        raise RealmConflict("Managed editable workspace provider is unavailable.")
    workspace_id = str(workspace.get("realm_workspace_id") or workspace.get("id") or "")
    revision = workspace.get("realm_workspace_revision")
    if isinstance(revision, bool) or not isinstance(revision, int) or revision <= 0:
        raise RealmConflict("Managed workspace revision is unavailable.")
    attached_sessions = list(workspace.get("attached_sessions", []) or [])
    if attached_sessions:
        raise RealmConflict(
            "Detach the managed workspace from every assistant session before retiring it."
        )

    # Stop the Studio-owned runtime before the provider removes its checkout.
    # External/source roots never participate in this branch.
    runtime_deleted = state.workspace_runtime.delete(str(workspace.get("id") or ""))
    runtime = state.realm_runtime
    assert runtime is not None
    retirement = runtime.editable_workspaces.retire_workspace(
        operation_id=f"studio/workspace/{workspace_id}/retire/revision-{revision}",
        workspace_id=workspace_id,
        expected_workspace_revision=revision,
    )

    sessions = []
    for session in _read_agent_session_index(state):
        attached = [
            item
            for item in session.get("attached_workspace_ids", [])
            if item != workspace.get("id")
        ]
        if attached != session.get("attached_workspace_ids", []):
            session = dict(session)
            session["attached_workspace_ids"] = attached
            if session.get("selected_workspace_id") == workspace.get("id"):
                session["selected_workspace_id"] = ""
            session["updated_at"] = _now_iso()
        sessions.append(session)
    _write_agent_session_index(state, sessions)
    with state._workspace_index_lock:
        _write_workspace_index(
            state,
            [
                item
                for item in _read_workspace_index(state)
                if item.get("id") != workspace.get("id")
            ],
        )
    result = dict(workspace)
    result.update(
        {
            "deleted": True,
            "files_deleted": True,
            "runtime_deleted": runtime_deleted,
            "workspace_retired": True,
            "checkout_absent": True,
            "source_content_unchanged": True,
            "retirement": retirement.to_dict(),
            "delete_action": "retire_workspace",
            "delete_label": "Retire Workspace",
        }
    )
    return result


def _delete_ui_workspace(state: UiState, workspace_id: str) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    _require_no_live_workspace_interface_launches(
        state, workspace_id, action="deleting"
    )
    if str(workspace.get("ownership") or "") == "realm-managed":
        return _retire_managed_ui_workspace(state, workspace)
    if str(workspace.get("mode") or "editable") not in {"editable"}:
        raise ValueError("Only editable workspaces can be removed from Studio.")
    sessions = _read_agent_session_index(state)
    changed_sessions = []
    for session in sessions:
        attached = [
            item
            for item in session.get("attached_workspace_ids", [])
            if item != workspace_id
        ]
        if attached != session.get("attached_workspace_ids", []):
            session = dict(session)
            session["attached_workspace_ids"] = attached
            if session.get("selected_workspace_id") == workspace_id:
                session["selected_workspace_id"] = ""
            session["updated_at"] = _now_iso()
        changed_sessions.append(session)
    _write_agent_session_index(state, changed_sessions)
    with state._workspace_index_lock:
        workspaces = [
            item
            for item in _read_workspace_index(state)
            if item.get("id") != workspace_id
        ]
        _write_workspace_index(state, workspaces)
    root = Path(str(workspace["root"])).resolve()
    files_deleted = False
    delete_error = ""
    if _is_managed_draft_root(state, workspace_id, root):
        try:
            shutil.rmtree(root.parent)
        except Exception as exc:
            delete_error = str(exc)
        files_deleted = not root.parent.exists()
    runtime_deleted = state.workspace_runtime.delete(workspace_id)
    workspace = dict(workspace)
    workspace["deleted"] = True
    workspace["files_deleted"] = files_deleted
    workspace["runtime_deleted"] = runtime_deleted
    if delete_error:
        workspace["delete_error"] = delete_error
    workspace["delete_action"] = "delete_draft" if files_deleted else "remove_reference"
    workspace["delete_label"] = _workspace_delete_label(
        workspace, workspace["delete_action"]
    )
    return workspace


def _is_managed_draft_root(state: UiState, workspace_id: str, root: Path) -> bool:
    expected = (state.workspaces_dir / workspace_id / "workspace").resolve()
    return root == expected and _is_relative_to(root, state.workspaces_dir.resolve())


def _component_setup_specs(
    raw: JsonDict,
    *,
    profile: Optional[InterfaceLaunchProfile] = None,
) -> List[tuple[str, JsonDict]]:
    specs: List[tuple[str, JsonDict]] = []
    if profile is not None:
        interface_setup = profile.runtime.setup
        if interface_setup is not None:
            specs.append(("Interface setup", interface_setup.to_dict()))
        return specs
    runtime = raw.get("runtime", {}) if isinstance(raw.get("runtime"), dict) else {}
    runtime_setup = (
        runtime.get("setup") if isinstance(runtime.get("setup"), dict) else None
    )
    if runtime_setup:
        specs.append(("Runtime setup", runtime_setup))
    return specs


_PROTECTED_INTERFACE_RUNTIME_ENV = frozenset(
    {
        "HOST",
        "OPTPILOT_INTERFACE_EPHEMERAL_ROOT",
        "OPTPILOT_INTERFACE_FRONTEND_RUNTIME_ROOT",
        "OPTPILOT_INTERFACE_OUTPUT_ROOT",
        "OPTPILOT_INTERFACE_OUTPUTS_FILE",
        "OPTPILOT_INTERFACE_PORT",
        "OPTPILOT_INTERFACE_RUNTIME_ROOT",
        "OPTPILOT_INTERFACE_VENV",
        "OPTPILOT_INTERFACE_VITE_CACHE_DIR",
        "OPTPILOT_WORKSPACE_ROOT",
        "OPTPILOT_PREPARED_RUNTIME_ACCESS",
        "OPTPILOT_PREPARED_RUNTIME_ROOT",
        "PORT",
    }
)


def _reject_interface_runtime_env_overrides(
    authored_env: Mapping[str, Any],
) -> None:
    """Keep package-authored values from replacing Studio-owned handles."""

    conflicts = sorted(
        str(key)
        for key in authored_env
        if str(key) in _PROTECTED_INTERFACE_RUNTIME_ENV
    )
    if conflicts:
        raise ValueError(
            "Interface configuration cannot override Studio-owned runtime environment "
            f"variable(s): {', '.join(conflicts)}."
        )


def _require_unreserved_interface_environment(
    profile: InterfaceLaunchProfile,
) -> None:
    """Reject reserved handles at compilation, with runtime checks as defense."""

    authored: Dict[str, str] = {
        str(name): "process environment" for name in profile.env
    }
    authored.update(
        {
            str(name): "host environment grant"
            for name in (
                *profile.grants.env_from_host,
                *profile.grants.secrets_from_host,
            )
        }
    )
    setup = profile.runtime.setup
    if setup is not None:
        authored.update({str(name): "setup environment" for name in setup.env})
        for step in setup.steps:
            authored.update(
                {
                    str(name): "setup-step environment"
                    for name in (step.get("env") or {})
                }
            )
    _reject_interface_runtime_env_overrides(authored)


def _run_component_setup_in_workspace_runtime(
    state: UiState,
    workspace: JsonDict,
    raw: JsonDict,
    root: Path,
    report: Any,
    *,
    profile: Optional[InterfaceLaunchProfile] = None,
    launch_env: Optional[Dict[str, str]] = None,
    should_stop: Optional[Callable[[], bool]] = None,
) -> JsonDict:
    _check_interface_launch_cancelled(should_stop)
    specs = _component_setup_specs(raw, profile=profile)
    if (
        len(specs) == 1
        and specs[0][1].get("cache") == "prepared"
        and profile is not None
    ):
        cached = _run_cached_component_setup_in_workspace_runtime(
            state,
            workspace,
            raw,
            root,
            report,
            profile=profile,
            setup_label=specs[0][0],
            setup=specs[0][1],
            launch_env=launch_env,
            should_stop=should_stop,
        )
        if cached is not None:
            return cached
    return _execute_component_setup_specs(
        state,
        workspace,
        specs,
        root,
        report,
        launch_env=launch_env,
        should_stop=should_stop,
    )


def _execute_component_setup_specs(
    state: UiState,
    workspace: JsonDict,
    specs: List[tuple[str, JsonDict]],
    root: Path,
    report: Any,
    *,
    launch_env: Optional[Dict[str, str]] = None,
    durable_log_workspace: Optional[JsonDict] = None,
    should_stop: Optional[Callable[[], bool]] = None,
) -> JsonDict:
    results = []
    for label, setup in specs:
        _check_interface_launch_cancelled(should_stop)
        timeout = int(setup.get("timeoutSeconds", 600) or 600)
        setup_env = setup.get("env") or {}
        _reject_interface_runtime_env_overrides(setup_env)
        base_env = _workspace_runtime_setup_env(
            state,
            setup,
            secret_names=(),
        )
        base_env.update(launch_env or {})
        step_results = []
        for index, step in enumerate(setup.get("steps") or []):
            for command in setup_commands_for_step(step, root):
                _check_interface_launch_cancelled(should_stop)
                cwd = setup_cwd(step, root)
                env = dict(base_env)
                step_env = {
                    str(key): str(value)
                    for key, value in (step.get("env") or {}).items()
                }
                _reject_interface_runtime_env_overrides(step_env)
                env.update(step_env)
                process_name = (
                    f"setup-{len(results) + 1}-{index + 1}-"
                    f"{len(step_results) + 1}"
                )
                log_paths = state.workspace_runtime.process_log_paths(
                    str(workspace["id"]), process_name
                )
                report(
                    f"{label} {index + 1}",
                    " ".join(command),
                    data=log_paths,
                )
                completed, _runtime, _logs = state.workspace_runtime.exec_logged(
                    workspace,
                    command,
                    cwd=cwd,
                    env=env,
                    timeout=timeout,
                    name=process_name,
                    should_stop=should_stop,
                )
                _check_interface_launch_cancelled(should_stop)
                if durable_log_workspace is not None:
                    retained_logs = state.workspace_runtime.process_log_paths(
                        str(durable_log_workspace["id"]), process_name
                    )
                    Path(str(retained_logs["stdout_log"])).write_text(
                        completed.stdout or "", encoding="utf-8"
                    )
                    Path(str(retained_logs["stderr_log"])).write_text(
                        completed.stderr or "", encoding="utf-8"
                    )
                    report(
                        f"{label} {index + 1}",
                        "Setup command finished; retaining its bounded logs.",
                        data=retained_logs,
                    )
                step_result = {
                    "command": command,
                    "cwd": str(cwd),
                    "returncode": completed.returncode,
                    "stdout": completed.stdout[-4000:] if completed.stdout else "",
                    "stderr": completed.stderr[-4000:] if completed.stderr else "",
                }
                step_results.append(step_result)
                if completed.returncode != 0:
                    raise RuntimeError(
                        f"{label} step {index + 1} failed with exit code {completed.returncode}: "
                        f"{completed.stderr.strip() or completed.stdout.strip()}"
                    )
        results.append({"label": label, "ran": True, "steps": step_results})
    return {"ran": bool(results), "results": results}


def _run_cached_component_setup_in_workspace_runtime(
    state: UiState,
    workspace: JsonDict,
    raw: JsonDict,
    root: Path,
    report: Any,
    *,
    profile: InterfaceLaunchProfile,
    setup_label: str,
    setup: JsonDict,
    launch_env: Optional[Dict[str, str]],
    should_stop: Optional[Callable[[], bool]],
) -> Optional[JsonDict]:
    _check_interface_launch_cancelled(should_stop)
    launch_id = str(workspace.get("launch_id") or "")
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if (
        not launch_id
        or job is None
        or job.launch_scope != "catalog-transient"
        or job.source_projection is None
    ):
        report(
            "Prepared runtime unavailable",
            "This source is not an exact sealed catalog projection; running setup privately.",
        )
        return None

    projection = job.source_projection
    source_identity = {
        "selectionDigest": projection.selection.selection_digest,
        "packageId": projection.package_id,
        "revision": projection.revision,
        "publisherId": projection.publisher_id,
        "relativePath": projection.relative_path,
    }
    component_identity = {
        "kind": job.kind,
        "profileId": profile.profile_id,
        "configDigest": request_digest(raw),
    }
    report(
        "Checking prepared runtime cache",
        "Resolving the exact source, setup, builder image, platform, and stable cache path.",
    )
    provider_identity = state.workspace_runtime.prepared_runtime_provider_identity()
    _check_interface_launch_cancelled(should_stop)
    key_payload = state.prepared_runtime_cache.key_payload(
        source_identity=source_identity,
        setup=setup,
        provider_identity=provider_identity,
        component_identity=component_identity,
    )
    build_result: JsonDict = {}

    def build(entry_root: Path, payload_root: Path) -> None:
        nonlocal build_result
        _check_interface_launch_cancelled(should_stop)
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is job:
                current.public_path_redactions.update(
                    {str(entry_root), str(payload_root)}
                )
        builder_id = (
            f"prepared-build-{state.prepared_runtime_cache.cache_key(key_payload)[:24]}-"
            f"{uuid.uuid4().hex[:8]}"
        )
        builder_workspace: JsonDict = {
            "id": builder_id,
            "title": f"Prepare {job.label}",
            "root": str(root),
            "source_root": str(root),
            "source_type": "prepared-runtime-build",
            "mode": "read-only",
            "transient": True,
            "_prepared_runtime_entry": str(entry_root),
            "_prepared_runtime_mount_mode": "rw",
        }
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not job:
                raise RuntimeError("Interface launch ownership disappeared.")
            current.prepared_runtime_builders[builder_id] = dict(builder_workspace)
        setup_error: Optional[BaseException] = None
        try:
            state.workspace_runtime._ensure_workspace_runtime_dir(builder_id)
            state.workspace_runtime._write_record(
                builder_id,
                {
                    "status": "preparing",
                    "updated_at": _now_iso(),
                    "workspace_root": str(root),
                    "source_type": "prepared-runtime-build",
                    "mode": "read-only",
                    "transient": True,
                    "prepared_runtime_entry": str(entry_root),
                    # Restart recovery can now reconcile this builder before
                    # allowing a later launch to reuse its cache namespace.
                    "owner_launch_id": launch_id,
                },
            )
            build_env = {
                "OPTPILOT_PREPARED_RUNTIME_ROOT": str(payload_root),
                "OPTPILOT_PREPARED_RUNTIME_ACCESS": "build",
                "OPTPILOT_INTERFACE_EPHEMERAL_ROOT": (
                    f"/tmp/optpilot-prepared-runtime/{builder_id}"
                ),
                "PYTHONDONTWRITEBYTECODE": "1",
            }
            report(
                "Building prepared runtime",
                "Cache miss: setup is running once at its provider-stable path.",
            )
            build_result = _execute_component_setup_specs(
                state,
                builder_workspace,
                [(setup_label, setup)],
                root,
                report,
                launch_env=build_env,
                durable_log_workspace=workspace,
                should_stop=should_stop,
            )
            # A cancelled builder must not return successfully to the cache,
            # because a successful callback is what authorizes sealing.
            _check_interface_launch_cancelled(should_stop)
        except BaseException as error:
            setup_error = error
            raise
        finally:
            deleted = False
            try:
                _mark_prestart_interface_runtime_terminal(
                    state, builder_workspace
                )
                deleted = state.workspace_runtime.delete(builder_id)
                if not deleted:
                    deleted = not state.workspace_runtime._workspace_runtime_dir(
                        builder_id
                    ).exists()
            except Exception:
                deleted = False
            if deleted:
                with state._lock:
                    current = state.interface_launches.get(launch_id)
                    if current is job:
                        current.prepared_runtime_builders.pop(builder_id, None)
            if not deleted and setup_error is None:
                raise RuntimeError(
                    "Prepared-runtime builder cleanup could not be confirmed."
                )

    _check_interface_launch_cancelled(should_stop)
    lease = state.prepared_runtime_cache.acquire(
        key_payload=key_payload,
        launch_id=launch_id,
        build=build,
    )
    adopted = False
    stopped = False
    with state._lock:
        current = state.interface_launches.get(launch_id)
        if current is job:
            # Adopt before observing cancellation.  From this point the single
            # launch finalizer owns release and can truthfully report debt.
            current.prepared_runtime_lease = lease
            current.public_path_redactions.update(
                {str(lease.entry_root), str(lease.payload_root)}
            )
            current.runtime_workspace.update(
                {
                    "_prepared_runtime_entry": str(lease.entry_root),
                    "_prepared_runtime_mount_mode": "ro",
                    "_prepared_runtime_cache_key": lease.cache_key,
                }
            )
            adopted = True
            stopped = current.stop_requested
    if not adopted:
        # This branch is defensive: launch jobs are not normally removed.
        # Provider I/O remains outside the global state lock.
        state.prepared_runtime_cache.release(lease)
        raise RuntimeError("Interface launch ownership disappeared.")
    if stopped or (should_stop is not None and should_stop()):
        raise RuntimeError("Interface launch was stopped.")
    workspace.update(
        {
            "_prepared_runtime_entry": str(lease.entry_root),
            "_prepared_runtime_mount_mode": "ro",
            "_prepared_runtime_cache_key": lease.cache_key,
        }
    )
    if launch_env is not None:
        launch_env["OPTPILOT_PREPARED_RUNTIME_ROOT"] = str(lease.payload_root)
        launch_env["OPTPILOT_PREPARED_RUNTIME_ACCESS"] = "read-only"
    cache = lease.public_summary()
    if lease.cache_status == "hit":
        report(
            "Prepared runtime cache hit",
            "Reusing the sealed dependency layer; no setup commands were run.",
            status="ready",
        )
        return {
            "ran": False,
            "skipped": True,
            "reason": "Prepared runtime cache hit.",
            "cache": cache,
        }
    report(
        "Prepared runtime cached",
        "Setup completed and the dependency layer was sealed for later launches.",
        status="ready",
    )
    return {**build_result, "cache": cache}


def _resource_config_target(
    entry: JsonDict, original_root: Path, copied_root: Path
) -> Path:
    source_value = entry.get("config_path")
    if source_value:
        source_path = Path(str(source_value)).resolve()
        try:
            return copied_root / source_path.relative_to(original_root.resolve())
        except ValueError:
            return copied_root / source_path.name
    return copied_root / "optpilot.resource.yaml"


def _workspace_runtime_setup_env(
    state: UiState,
    setup: JsonDict,
    *,
    secret_names: Iterable[str] = (),
) -> Dict[str, str]:
    declared_names = list(setup.get("envFromHost", []) or [])
    declared_names.extend(secret_names)
    resolved = _require_declared_env_from_host(
        state,
        declared_names,
        action="component setup",
    )
    env = {str(key): str(value) for key, value in (setup.get("env") or {}).items()}
    env.update(resolved)
    return env


def _workspace_source_root(workspace: JsonDict) -> Path:
    return Path(
        str(workspace.get("source_root") or workspace.get("root") or ".")
    ).resolve()


def _workspace_registered_config_candidates(
    workspace: JsonDict,
) -> List[tuple[str, Path]]:
    root = Path(str(workspace.get("root") or ".")).resolve()
    candidates: List[tuple[str, Path]] = []
    for entry in workspace.get("registered_entries", []) or []:
        if not isinstance(entry, dict):
            continue
        kind = str(entry.get("kind") or "")
        if kind not in {"environment", "method", "resource"}:
            continue
        config_value = str(
            entry.get("authoring_relative_path") or entry.get("config_path") or ""
        ).strip()
        if not config_value:
            continue
        config_path = Path(config_value)
        if not config_path.is_absolute():
            config_path = root / config_path
        candidates.append((kind, config_path.resolve()))
    return candidates


def _workspace_interface_config(
    state: UiState,
    workspace: JsonDict,
) -> tuple[str, Path, JsonDict, List[InterfaceLaunchProfile]]:
    root = _safe_workspace_root(state, Path(str(workspace.get("root") or "")))
    for kind, config_path in _workspace_registered_config_candidates(workspace):
        if (
            not config_path.exists()
            or not config_path.is_file()
            or not _is_relative_to(config_path, root)
        ):
            continue
        raw = _read_yaml(config_path)
        if raw.get("apiVersion") != AUTHORING_API_VERSION or raw.get("config") != kind:
            continue
        profiles = _compile_component_interface_profiles(
            raw.get("interface"),
            component_kind=kind,
        )
        if profiles:
            return kind, config_path, raw, profiles
    raise ValueError(
        "This workspace does not have a registered environment, method, or resource config with a launchable interface."
    )


def _workspace_interface_summary(state: UiState, workspace: JsonDict) -> JsonDict:
    try:
        kind, config_path, _raw, profiles = _workspace_interface_config(
            state, workspace
        )
    except Exception:
        return {}
    summary = _interface_summary_with_launch_capabilities(
        state,
        _interface_summary(profiles),
        profiles,
    )
    summary["kind"] = kind
    summary["config_path"] = _relative_path(
        config_path, Path(str(workspace.get("root") or ".")).resolve()
    )
    return summary


def _catalog_component_source_root(kind: str, config_path: Path, raw: JsonDict) -> Path:
    if kind == "study":
        return config_path.parent.resolve()
    refs: List[str] = []
    hints: List[Path] = []
    if kind == "environment":
        evaluator = (
            raw.get("evaluator", {}) if isinstance(raw.get("evaluator"), dict) else {}
        )
        for key in ("python", "adapter"):
            if evaluator.get(key):
                refs.append(str(evaluator[key]))
        hints.extend(
            _resolve_public_hint_path(path, config_path)
            for path in evaluator.get("pythonPath", []) or []
        )
    elif kind == "method":
        entrypoint = (
            raw.get("entrypoint", {}) if isinstance(raw.get("entrypoint"), dict) else {}
        )
        if entrypoint.get("python"):
            refs.append(str(entrypoint["python"]))
        hints.extend(
            _resolve_public_hint_path(path, config_path)
            for path in entrypoint.get("pythonPath", []) or []
        )
    return _choose_source_root(config_path, refs, hints)


def _catalog_edit_workspace_operation_id(
    state: UiState, kind: str, source: CatalogSourceProjection
) -> str:
    """Identify the one editable derivation of an exact Catalog entry."""

    return "studio/workspace-create/catalog/" + request_digest(
        {
            "actor_id": _studio_actor_id(state),
            "component_kind": kind,
            "relative_path": source.relative_path,
            "schema": "optpilot.catalog-edit-workspace-intent.v1",
            "selection": source.selection.to_dict(),
        }
    )


def _resolve_public_hint_path(value: Any, config_path: Path) -> Path:
    path = Path(str(value)).expanduser()
    if path.is_absolute():
        return path.resolve()
    return (config_path.parent / path).resolve()


def _open_realm_catalog_workspace(
    state: UiState,
    kind: str,
    source: CatalogSourceProjection,
    *,
    editable: bool,
    title_prefix: str,
    install: bool,
    create_operation_id: Optional[str],
) -> JsonDict:
    """Open one exact catalog selection without a source-specific copier."""

    selected_path = source.source_path
    package_root = source.root_path
    if kind == "resource":
        entry = _resource_catalog_entry(
            selected_path,
            package_id=source.package_id,
        )
        base_raw = deepcopy(entry.get("raw_config") or {})
        label = str(entry.get("label") or selected_path.name)
        selected_source_root = selected_path
        config_value = str(entry.get("config_path") or "").strip()
        selected_config_path = (
            Path(config_value).resolve()
            if config_value
            else selected_path / "optpilot.resource.yaml"
        )
        readme_value = str(entry.get("summary", {}).get("readme") or "")
    else:
        selected_config_path = selected_path
        base_raw = _read_yaml(selected_config_path)
        if (
            base_raw.get("config") != kind
            or base_raw.get("apiVersion") != AUTHORING_API_VERSION
        ):
            raise FileNotFoundError(
                f"{kind} config not found in the selected catalog revision."
            )
        label = str(base_raw.get("name") or base_raw.get("id") or selected_path.stem)
        selected_source_root = _catalog_component_source_root(
            kind, selected_config_path, base_raw
        )
        readme_value = ""
    if not _is_relative_to(selected_source_root, package_root):
        raise RealmIntegrityError(
            "Catalog component source escaped its exact package selection."
        )
    raw_for_workspace = base_raw
    config_relative = selected_config_path.relative_to(package_root).as_posix()
    source_root_relative = selected_source_root.relative_to(package_root).as_posix()
    catalog_origin = {
        "selection": source.selection.to_dict(),
        "package_id": source.package_id,
        "revision": source.revision,
        "publisher_id": source.publisher_id,
        "component_kind": kind,
        "config_relative_path": config_relative,
        "source_root_relative_path": source_root_relative,
    }

    if editable:
        if create_operation_id is None:
            source.close()
            raise ValueError(
                "Editable catalog workspace creation requires a request_id."
            )
        try:
            kept = _keep_selection_as_ui_workspace(
                state,
                operation_id=create_operation_id,
                selection=source.selection,
                title=f"{title_prefix} {label}",
                description=f"Editable workspace kept from {kind} catalog selection",
            )
            workspace = dict(kept["workspace"])
            root = Path(str(workspace["root"])).resolve()
            workspace_config_path = root / config_relative
            workspace_source_root = root / source_root_relative
            validation: JsonDict = {}
            workspace["registered_entries"] = [
                {
                    "kind": kind,
                    "id": str(
                        raw_for_workspace.get("id")
                        or raw_for_workspace.get("name")
                        or selected_config_path.stem
                    ),
                    "authoring_relative_path": config_relative,
                    "catalog_relative_path": config_relative,
                }
            ]
            workspace["catalog_origin"] = catalog_origin
            workspace["focus_paths"] = (
                [f"{source_root_relative}/{readme_value}".strip("/")]
                if readme_value
                else _focus_paths_for_config(
                    root,
                    workspace_config_path,
                    raw_for_workspace,
                )
            )
            workspace["validation"] = validation
            workspace = _upsert_ui_workspace(state, workspace)
            if install:
                if validation and not validation.get("valid"):
                    setup_result = {
                        "ran": False,
                        "skipped": True,
                        "reason": "Config validation failed.",
                        "validation": validation,
                    }
                else:
                    setup_result = _run_component_setup_in_workspace_runtime(
                        state,
                        workspace,
                        raw_for_workspace,
                        workspace_source_root,
                        lambda *_args, **_kwargs: None,
                    )
                workspace = dict(_require_ui_workspace(state, str(workspace["id"])))
                workspace["setup"] = setup_result
                workspace = _upsert_ui_workspace(state, workspace)
            return workspace
        finally:
            source.close()

    workspace_id = (
        "ws_catalog_"
        + request_digest(
            {
                "selection": source.selection.to_dict(),
                "component_kind": kind,
                "config_relative_path": config_relative,
            }
        )[:24]
    )
    with state._catalog_projection_lock:
        previous = state._catalog_workspace_projections.get(workspace_id)
        state._catalog_workspace_projections[workspace_id] = source
    try:
        workspace = _create_ui_workspace(
            state,
            {
                "id": workspace_id,
                "title": f"Inspect {label}",
                "root": str(selected_source_root),
                "source_root": str(selected_source_root),
                "source_type": "catalog",
                "mode": "read-only",
                "description": f"read-only {kind} catalog selection",
                "source_path": _package_plan_catalog_destination(
                    source.package_id, config_relative
                ),
                "registered_entries": [
                    {
                        "kind": kind,
                        "id": str(
                            raw_for_workspace.get("id")
                            or raw_for_workspace.get("name")
                            or selected_config_path.stem
                        ),
                        "authoring_relative_path": selected_config_path.relative_to(
                            selected_source_root
                        ).as_posix(),
                        "catalog_relative_path": config_relative,
                    }
                ],
                "catalog_origin": catalog_origin,
                "focus_paths": (
                    [readme_value]
                    if readme_value
                    else _focus_paths_for_config(
                        selected_source_root,
                        selected_config_path,
                        raw_for_workspace,
                    )
                ),
                "registration_enabled": False,
                "initialize_if_empty": False,
            },
        )
        if previous is not None and previous is not source:
            previous.close()
        return workspace
    except Exception:
        with state._catalog_projection_lock:
            current = state._catalog_workspace_projections.get(workspace_id)
            if current is source:
                if previous is None:
                    state._catalog_workspace_projections.pop(workspace_id, None)
                else:
                    state._catalog_workspace_projections[workspace_id] = previous
        source.close()
        raise


def _open_catalog_workspace(
    state: UiState,
    kind: str,
    uid: str,
    *,
    editable: bool,
    title_prefix: str = "Edit",
    install: bool = False,
    request_id: Optional[str] = None,
) -> JsonDict:
    if editable:
        # Keep a strict client request token at the HTTP boundary, but derive
        # the durable creation identity from the exact Catalog source.  A
        # refreshed browser or lost response must reopen the same Workspace.
        _canonical_request_uuid(request_id)
    realm_source = _borrow_catalog_entry_ref_projection(
        state,
        kind,
        uid,
        consumer_kind="catalog-workspace",
        consumer_metadata={"component_kind": kind, "editable": editable},
    )
    if realm_source is not None:
        create_operation_id = (
            _catalog_edit_workspace_operation_id(state, kind, realm_source)
            if editable
            else None
        )
        return _open_realm_catalog_workspace(
            state,
            kind,
            realm_source,
            editable=editable,
            title_prefix=title_prefix,
            install=install,
            create_operation_id=create_operation_id,
        )
    resolved_source = _resolve_catalog_identifier(state, kind, uid)
    realm_source = _borrow_realm_catalog_source_projection(
        state,
        resolved_source,
        consumer_kind="catalog-workspace",
        consumer_metadata={"component_kind": kind, "editable": editable},
    )
    if realm_source is not None:
        create_operation_id = (
            _catalog_edit_workspace_operation_id(state, kind, realm_source)
            if editable
            else None
        )
        return _open_realm_catalog_workspace(
            state,
            kind,
            realm_source,
            editable=editable,
            title_prefix=title_prefix,
            install=install,
            create_operation_id=create_operation_id,
        )
    if editable:
        raise CatalogWorkspaceCreationUnsupported(
            "Open this local source folder as a Workspace, then check and register "
            "the version you want to reuse."
        )
    uid = _encode_id(resolved_source)
    if kind == "resource":
        resource_root = _decode_id(uid).resolve()
        if not resource_root.exists() or not resource_root.is_dir():
            raise FileNotFoundError(f"resource not found: {resource_root}")
        entry = _resource_catalog_entry(resource_root)
        label = str(entry.get("label") or resource_root.name)
        workspace_id = f"ws_{slug_path(resource_root)}_resource"
        root = resource_root
        source_root = resource_root
        mode = "read-only"
        source_type = "catalog"
        title = f"Inspect {label}"
        readme = entry.get("summary", {}).get("readme") or "README.md"
        workspace = _create_ui_workspace(
            state,
            {
                "id": workspace_id,
                "title": title,
                "root": str(root),
                "source_root": str(source_root),
                "source_type": source_type,
                "mode": mode,
                "description": "resource catalog entry",
                "source_path": str(resource_root),
                "registered_entries": [
                    {
                        "kind": "resource",
                        "id": str(entry.get("id") or resource_root.name),
                        "config_path": "",
                        "source_config_path": str(resource_root),
                    }
                ],
                "focus_paths": [readme] if (root / readme).exists() else ["README.md"],
                "registration_enabled": False,
                "validation": {},
            },
        )
        return workspace
    config_path = _decode_id(uid)
    raw = _read_yaml(config_path)
    if raw.get("config") != kind or raw.get("apiVersion") != AUTHORING_API_VERSION:
        raise FileNotFoundError(f"{kind} config not found: {config_path}")
    raw_for_workspace = deepcopy(raw)
    label = str(raw.get("name") or raw.get("id") or config_path.stem)
    original_source_root = _catalog_component_source_root(kind, config_path, raw)
    root = original_source_root
    source_root = original_source_root
    mode = "read-only"
    source_type = "catalog"
    title = f"Inspect {label}"
    focus_paths = _focus_paths_for_config(root, config_path, raw)
    registered_entry = {
        "kind": kind,
        "id": str(
            raw_for_workspace.get("id")
            or raw_for_workspace.get("name")
            or config_path.stem
        ),
        "config_path": _relative_path(config_path, root),
        "source_config_path": str(config_path),
    }
    workspace = _create_ui_workspace(
        state,
        {
            "id": f"ws_{slug_path(original_source_root)}_{kind}_{slug_path(config_path)}",
            "title": title,
            "root": str(root),
            "source_root": str(source_root),
            "source_type": source_type,
            "mode": mode,
            "description": f"{kind} catalog entry",
            "source_path": str(config_path),
            "registered_entries": [registered_entry],
            "focus_paths": focus_paths,
            "registration_enabled": False,
            "validation": {},
        },
    )
    return workspace


def _open_catalog_code_server(
    state: UiState,
    kind: str,
    uid: str,
) -> JsonDict:
    """Open exact Catalog source in a read-only Code Server atomically."""

    if _catalog_entry_ref_from_value(state, kind, uid) is None:
        raise ValueError("Catalog Open Code requires an exact Catalog entry ref.")
    workspace = _open_catalog_workspace(
        state,
        kind,
        uid,
        editable=False,
        install=False,
    )
    return {
        "workspace": workspace,
        "code_server": state.start_workspace_code_server(workspace),
    }


def _catalog_interface_runtime_descriptor(
    state: UiState,
    kind: str,
    uid: str,
    launch_id: str,
    *,
    catalog_root: Optional[Path] = None,
    resolved_source_path: Optional[Path] = None,
) -> tuple[JsonDict, JsonDict, str]:
    """Describe a catalog source without registering or copying a workspace."""

    source_path = (
        resolved_source_path.resolve(strict=True)
        if resolved_source_path is not None
        else _resolve_catalog_identifier(state, kind, uid).resolve()
    )
    allowed_roots = (
        [catalog_root.resolve()]
        if catalog_root is not None
        else [root.resolve() for root in state.catalog_roots]
    )
    if not any(_is_relative_to(source_path, root) for root in allowed_roots):
        raise PermissionError(
            f"Catalog interface source is outside configured catalog roots: {source_path}"
        )
    if kind == "resource":
        if not source_path.is_dir():
            raise FileNotFoundError(f"resource not found: {source_path}")
        entry = _resource_catalog_entry(source_path)
        base_raw = deepcopy(entry.get("raw_config") or {})
        source_root = source_path
        config_path = Path(
            str(entry.get("config_path") or source_path / "optpilot.resource.yaml")
        ).resolve()
        label = str(entry.get("label") or source_path.name)
    else:
        if not source_path.is_file():
            raise FileNotFoundError(f"{kind} config not found: {source_path}")
        base_raw = _read_yaml(source_path)
        if (
            base_raw.get("config") != kind
            or base_raw.get("apiVersion") != AUTHORING_API_VERSION
        ):
            raise FileNotFoundError(f"{kind} config not found: {source_path}")
        source_root = _catalog_component_source_root(kind, source_path, base_raw)
        config_path = source_path
        label = str(base_raw.get("name") or base_raw.get("id") or source_path.stem)
    source_root = source_root.resolve()
    if not source_root.is_dir() or not any(
        _is_relative_to(source_root, root) for root in allowed_roots
    ):
        raise PermissionError(
            "Catalog interface source root must remain inside a configured catalog root."
        )
    raw = deepcopy(base_raw)
    schema_result = validate_public_config_schema(raw, config_path=config_path)
    if not schema_result.valid:
        errors = "; ".join(
            f"{issue.path}: {issue.message}" for issue in schema_result.errors[:8]
        )
        raise ValueError(f"Interface config validation failed: {errors}")
    runtime_id = f"interface-{launch_id}"
    workspace = {
        "id": runtime_id,
        "title": f"Launch {label}",
        "root": str(source_root),
        "source_root": str(source_root),
        "source_type": "catalog",
        "mode": "read-only",
        "description": f"transient {kind} catalog interface runtime",
        "source_path": str(source_path),
        "registration_enabled": False,
        "transient": True,
        "launch_id": launch_id,
    }
    return workspace, raw, label


def _workspace_interface_runtime_descriptor(
    state: UiState,
    workspace: JsonDict,
    launch_id: str,
) -> JsonDict:
    """Describe a launch-scoped runtime over one editable workspace tree."""

    workspace_id = str(workspace.get("id") or "")
    if not workspace_id:
        raise ValueError("Workspace interface source is missing its identity.")
    if str(workspace.get("mode") or "editable") != "editable":
        raise ValueError(
            "Workspace interfaces require an editable workspace; launch read-only "
            "catalog interfaces from the catalog instead."
        )
    root = _safe_workspace_root(state, Path(str(workspace.get("root") or ""))).resolve()
    source_root = _workspace_source_root(workspace)
    if not _is_relative_to(source_root, root):
        source_root = root
    return {
        "id": f"interface-{launch_id}",
        "title": f"Launch {workspace.get('title') or workspace_id}",
        # The launch gets a different runtime identity, not a copied tree.  The
        # same editable root is mounted rw so interface changes remain visible
        # in the user's existing authoring workspace.
        "root": str(root),
        "source_root": str(source_root),
        "source_type": "workspace-interface",
        "mode": "editable",
        "description": "transient editable-workspace interface runtime",
        "registration_enabled": False,
        "transient": True,
        "launch_id": launch_id,
        "source_workspace_id": workspace_id,
    }


def _prepare_transient_interface_runtime_handles(
    state: UiState,
    workspace: JsonDict,
    *,
    outputs_enabled: bool = False,
    output_actions_enabled: bool = False,
) -> Dict[str, str]:
    workspace_id = str(workspace["id"])
    runtime_dir = state.workspace_runtime._workspace_runtime_dir(workspace_id)
    if runtime_dir.exists():
        raise FileExistsError(
            f"Interface launch runtime already exists: {workspace_id}"
        )
    runtime_dir = state.workspace_runtime._ensure_workspace_runtime_dir(workspace_id)
    state.workspace_runtime._write_record(
        workspace_id,
        {
            "status": "preparing",
            "updated_at": _now_iso(),
            "workspace_root": str(workspace.get("root") or ""),
            "source_type": str(workspace.get("source_type") or "interface-launch"),
            "mode": str(workspace.get("mode") or "editable"),
            "source_workspace_id": str(workspace.get("source_workspace_id") or ""),
            "transient": True,
            # The launch worker must durably flip this before submitting any
            # container start. It may be converted to a terminal proof only
            # after that worker has unwound (or during restart recovery).
            "container_may_exist": False,
        },
    )
    interface_runtime_root = runtime_dir / "interface-runtime"
    for path in (interface_runtime_root,):
        path.mkdir(parents=True, exist_ok=True, mode=0o700)
        try:
            path.chmod(0o700)
        except OSError:
            pass
    safe_workspace_id = _safe_artifact_identifier(workspace_id, "interface runtime id")
    ephemeral_root = f"/tmp/optpilot-interface/{safe_workspace_id}"
    handles = {
        "OPTPILOT_INTERFACE_RUNTIME_ROOT": str(interface_runtime_root),
        # Executable dependency trees are disposable container state. Keeping
        # them off host-backed/synchronized mounts avoids broken venv symlinks
        # and npm shims while output/control/runtime evidence remains durable.
        "OPTPILOT_INTERFACE_EPHEMERAL_ROOT": ephemeral_root,
    }
    if outputs_enabled:
        output_root = runtime_dir / "interface-outputs"
        control_dir = runtime_dir / "control"
        for path in (output_root, control_dir):
            path.mkdir(parents=True, exist_ok=True, mode=0o700)
            try:
                path.chmod(0o700)
            except OSError:
                pass
        outputs_file = control_dir / "outputs.jsonl"
        descriptor = os.open(
            outputs_file,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0),
            0o600,
        )
        os.close(descriptor)
        handles.update(
            {
                "OPTPILOT_INTERFACE_OUTPUT_ROOT": str(output_root),
                "OPTPILOT_INTERFACE_OUTPUTS_FILE": str(outputs_file),
            }
        )
    action_root: Optional[Path] = None
    execution_root: Optional[Path] = None
    if output_actions_enabled:
        if not outputs_enabled:
            raise ValueError("Interface output actions require interface outputs.")
        action_root = runtime_dir / "interface-output-actions"
        action_root.mkdir(mode=0o700)
        for name in ("inputs", "responses", "results", "cancellations"):
            (action_root / name).mkdir(mode=0o700)
        requests_file = action_root / "requests.jsonl"
        descriptor = os.open(
            requests_file,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0),
            0o600,
        )
        os.close(descriptor)
        action_paths = {
            "root": action_root,
            "requests": requests_file,
            "inputs": action_root / "inputs",
            "responses": action_root / "responses",
            "results": action_root / "results",
            "cancellations": action_root / "cancellations",
        }
        action_path_identities = {
            name: (
                int(info.st_dev),
                int(info.st_ino),
                int(stat.S_IFMT(info.st_mode)),
            )
            for name, path in action_paths.items()
            for info in (path.lstat(),)
        }
        # Snapshots and executor scratch space stay outside the directory
        # mounted into the live interface container.  The interface sees only
        # its narrow request/response broker.
        execution_root = (
            state.runtime_dir
            / ".interface-output-executions"
            / safe_workspace_id
        )
        execution_root.mkdir(parents=True, mode=0o700)
        handles["OPTPILOT_INTERFACE_OUTPUT_ACTION_ROOT"] = str(action_root)
    launch_id = str(workspace.get("launch_id") or "")
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is not None:
            job.public_path_redactions.update(
                str(value) for value in handles.values()
            )
            job.public_path_redactions.add(str(runtime_dir))
            if action_root is not None and execution_root is not None:
                job.output_action_root = action_root
                job.output_action_path_identities = action_path_identities
                job.output_execution_root = execution_root
                job.public_path_redactions.add(str(execution_root))
    return handles


def _interface_output_service(state: UiState) -> Optional[Any]:
    runtime = state.realm_runtime
    if runtime is None or getattr(runtime, "closed", False):
        return None
    service = getattr(runtime, "interface_outputs", None)
    return service if isinstance(service, RealmInterfaceOutputSessionService) else None


def _interface_output_workspace_action_request(
    state: UiState, generation: Any
) -> tuple[str, EntityCoordinate, JsonDict]:
    """Return the stable Studio action identity for saving one exact output.

    The browser request UUID is deliberately not part of this identity.  It is
    a transport retry token, whereas an interface-output generation is already
    one immutable, authority-revision-anchored source.  A refreshed browser may
    therefore mint another request UUID and still reconcile the same save.
    Creating another Workspace would need a separate explicit product action.
    """

    selection = generation.selection
    if selection is None:
        raise RealmConflict("The interface output has no keepable selection.")
    source = EntityCoordinate(
        kind="interface-output",
        entity_id="output-" + request_digest(
            {
                "output_id": generation.output_id,
                "schema": "optpilot.interface-output-coordinate.v1",
                "session_id": generation.session_id,
            }
        ),
        revision=generation.session_revision,
        digest=selection.selection_digest,
    )
    parameters: JsonDict = {
        "label": generation.label,
        "output_id": generation.output_id,
        "selection_digest": selection.selection_digest,
        "session_id": generation.session_id,
    }
    intent_id = "interface-output-workspace-" + request_digest(
        {
            "actor_id": _studio_actor_id(state),
            "parameters": parameters,
            "schema": "optpilot.interface-output-workspace-intent.v1",
            "source": source.to_dict(),
        }
    )
    return intent_id, source, parameters


def _interface_output_workspace_action(
    state: UiState, generation: Any
) -> Optional[ActionIntentRecord]:
    intent_id, source, parameters = _interface_output_workspace_action_request(
        state, generation
    )
    try:
        action = state.coordination.get_action(intent_id)
    except CoordinationNotFound:
        return None
    expected_digest = ActionIntentRecord.compute_intent_digest(
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="workspace-creation",
        source=source,
        parameters=parameters,
    )
    if action.intent_digest != expected_digest:
        raise RealmIntegrityError(
            "The saved interface-output action does not match its source."
        )
    return action


def _begin_interface_output_workspace_action(
    state: UiState, generation: Any
) -> ActionIntentRecord:
    intent_id, source, parameters = _interface_output_workspace_action_request(
        state, generation
    )
    current = _interface_output_workspace_action(state, generation)
    if current is not None:
        if current.state in {ActionState.UNCERTAIN, ActionState.FAILED}:
            return state.coordination.retry_action(
                operation_id=(
                    f"studio/action/{intent_id}/retry/{current.revision}"
                ),
                intent_id=intent_id,
            )
        return current
    return state.coordination.begin_action(
        operation_id=f"studio/action/{intent_id}/begin",
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="workspace-creation",
        source=source,
        parameters=parameters,
    )


def _interface_output_workspace_link(
    state: UiState, generation: Any
) -> JsonDict:
    action = _interface_output_workspace_action(state, generation)
    if action is None:
        return {
            "keep_state": "not-started",
            "kept_workspace_id": None,
            "kept_workspace_title": None,
        }
    if action.state is ActionState.SUCCEEDED:
        result = action.result
        receipt = action.core_receipt
        if (
            result is None
            or result.kind != "workspace"
            or not isinstance(receipt, Mapping)
            or not isinstance(receipt.get("keep"), Mapping)
        ):
            raise RealmIntegrityError(
                "The saved interface-output Workspace receipt is incomplete."
            )
        title = receipt.get("workspace_title")
        return {
            "keep_state": "saved",
            "kept_workspace_id": result.entity_id,
            "kept_workspace_title": title if isinstance(title, str) else None,
        }
    return {
        "keep_state": (
            "saving" if action.state is ActionState.PENDING else "retryable"
        ),
        "kept_workspace_id": None,
        "kept_workspace_title": None,
    }


def _public_interface_output_execution(
    value: Mapping[str, Any],
    *,
    job: Optional[UiLaunchJob] = None,
) -> JsonDict:
    """Return one bounded, path-free action execution for an output card."""

    result = value.get("result")
    public_result: Optional[JsonDict] = None
    if isinstance(result, Mapping):
        request_id = str(result.get("request_id") or "")
        stdout = str(result.get("stdout") or "")[-4000:]
        stderr = str(result.get("stderr") or "")[-4000:]
        if job is not None:
            stdout = _redact_interface_public_text(
                stdout,
                path_redactions=job.public_path_redactions,
                secret_redactions=job.public_secret_redactions,
            )
            stderr = _redact_interface_public_text(
                stderr,
                path_redactions=job.public_path_redactions,
                secret_redactions=job.public_secret_redactions,
            )
        result_files, result_file_count = (
            _public_interface_output_action_result_files(
                job,
                request_id=request_id,
                value=result.get("result_files"),
            )
        )
        public_result = {
            "schema_version": str(result.get("schema_version") or ""),
            "request_id": request_id,
            "action_id": str(result.get("action_id") or ""),
            "snapshot_ref": result.get("snapshot_ref"),
            "status": str(result.get("status") or ""),
            "exit_code": result.get("exit_code"),
            "duration_seconds": result.get("duration_seconds"),
            "stdout": stdout,
            "stderr": stderr,
            "stdout_truncated": bool(result.get("stdout_truncated")),
            "stderr_truncated": bool(result.get("stderr_truncated")),
            "result_files": result_files,
            "result_file_count": result_file_count,
            "result_files_truncated": result_file_count > len(result_files),
            "failure_code": result.get("failure_code"),
        }
    return {
        "request_id": str(value.get("request_id") or ""),
        "action_id": str(value.get("action_id") or ""),
        "label": str(value.get("label") or ""),
        "status": str(value.get("status") or "queued"),
        "started_at": value.get("started_at"),
        "updated_at": value.get("updated_at"),
        "result": public_result,
    }


def _interface_output_action_result_path(value: Any) -> str:
    if (
        not isinstance(value, str)
        or not value
        or "\x00" in value
        or "\\" in value
        or len(value.encode("utf-8")) > 4096
    ):
        raise ValueError("Action result path must be a canonical relative path.")
    relative = PurePosixPath(value)
    if (
        relative.is_absolute()
        or relative.as_posix() != value
        or any(part in {"", ".", ".."} for part in relative.parts)
    ):
        raise ValueError("Action result path must be a canonical relative path.")
    return value


def _public_interface_output_action_result_files(
    job: Optional[UiLaunchJob],
    *,
    request_id: str,
    value: Any,
) -> tuple[List[JsonDict], int]:
    """Return a bounded inventory with server-minted, temporary file links."""

    raw_files = value if isinstance(value, list) else []
    checked: List[JsonDict] = []
    for raw in raw_files:
        if not isinstance(raw, Mapping):
            continue
        try:
            relative_path = _interface_output_action_result_path(raw.get("path"))
            size = raw.get("size")
            digest = raw.get("sha256")
            if (
                isinstance(size, bool)
                or not isinstance(size, int)
                or size < 0
                or not isinstance(digest, str)
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None
            ):
                continue
        except (TypeError, ValueError):
            continue
        checked.append(
            {
                "path": relative_path,
                "size": size,
                "sha256": digest,
            }
        )
    active = bool(
        job is not None
        and job.output_action_root is not None
        and job.status in {"running", "ready", "stopping", "cleanup_pending"}
    )
    public: List[JsonDict] = []
    for item in checked[:_MAX_PUBLIC_INTERFACE_OUTPUT_ACTION_RESULT_FILES]:
        size = int(item["size"])
        eligible = active and size <= (
            _MAX_BROWSER_INTERFACE_OUTPUT_ACTION_RESULT_FILE_BYTES
        )
        media_type = mimetypes.guess_type(str(item["path"]))[0] or (
            "application/octet-stream"
        )
        access: JsonDict = {
            "eligible": eligible,
            "preview_eligible": eligible
            and _selection_content_is_text(media_type),
            "reason": None,
        }
        if eligible and job is not None:
            base = (
                f"/api/interface-launches/{quote(job.launch_id, safe='')}/"
                "output-action-executions/"
                f"{quote(request_id, safe='')}/files/content"
                f"?path={quote(str(item['path']), safe='')}"
            )
            access["open_url"] = base
            access["download_url"] = f"{base}&download=1"
        elif not active:
            access["reason"] = (
                "Result files are available only while the originating "
                "interface launch is active."
            )
        else:
            access["reason"] = (
                "This result file is too large for the bounded browser "
                "download endpoint."
            )
        public.append({**item, "access": access})
    return public, len(checked)


def _interface_output_execution_capability(
    job: Optional[UiLaunchJob],
    *,
    output_id: str,
    kind: str,
    output_state: str,
) -> tuple[JsonDict, List[JsonDict]]:
    """Describe only authored output actions; commands stay private."""

    profile = job.interface_profile if job is not None else None
    authored = tuple(profile.output_actions) if profile is not None else ()
    presented = tuple(action for action in authored if action.show_in_output_card)
    if not presented:
        return (
            {
                "supported": False,
                "eligible": False,
                "code": "output_card_actions_not_declared",
                "reason": (
                    "This interface does not present an action on its output cards."
                ),
                "items": [],
            },
            [],
        )
    eligible = bool(
        job is not None
        and output_state == "ready"
        and kind == "tree"
        and job.status in {"running", "ready"}
        and not job.stop_requested
        and not job.terminal_target
        and job.prepared_runtime_lease is not None
    )
    if kind != "tree":
        code = "output_action_requires_tree"
        reason = "Only folder outputs can be run."
    elif output_state != "ready":
        code = "output_not_ready"
        reason = "Wait until this output is ready."
    elif (
        job is None
        or job.status not in {"running", "ready"}
        or job.stop_requested
        or job.terminal_target
    ):
        code = "launch_not_active"
        reason = "The originating interface launch is no longer active."
    elif job.prepared_runtime_lease is None:
        code = "prepared_runtime_unavailable"
        reason = (
            "This interface did not prepare an isolated runtime that can be "
            "reused to run its output."
        )
    else:
        code = "ready"
        reason = None
    items = [
        {
            "id": action.action_id,
            "label": action.label,
            "accepts_arguments": action.accepts_arguments,
            "eligible": eligible,
            "code": code,
            "reason": reason,
        }
        for action in presented
    ]
    executions = (
        sorted(
            (
                _public_interface_output_execution(value, job=job)
                for value in job.output_action_executions.values()
                if str(value.get("output_id") or "") == output_id
                and any(
                    action.action_id == str(value.get("action_id") or "")
                    for action in presented
                )
            ),
            key=lambda value: float(value.get("started_at") or 0.0),
            reverse=True,
        )[:8]
        if job is not None
        else []
    )
    return (
        {
            "supported": True,
            "eligible": eligible,
            "code": code,
            "reason": reason,
            "items": items,
        },
        executions,
    )


def _public_interface_output_status(
    state: UiState,
    status: Any,
    *,
    job: Optional[UiLaunchJob] = None,
) -> JsonDict:
    raw = status.to_dict()
    selection = raw.get("selection")
    kind = str(raw.get("kind") or "")
    output_state = str(raw.get("status") or "")
    generation = status.ready_generation
    output_id = str(raw.get("id") or "")
    workspace_link = (
        _interface_output_workspace_link(state, generation)
        if generation is not None and generation.selection is not None
        else {
            "keep_state": "not-started",
            "kept_workspace_id": None,
            "kept_workspace_title": None,
        }
    )
    view_capability: JsonDict
    keep_capability: JsonDict
    if workspace_link["keep_state"] == "saved":
        keep_capability = {
            "supported": True,
            "eligible": True,
            "code": "workspace_saved",
            "reason": "This output is already linked to its saved Workspace.",
        }
    else:
        keep_capability = {
            "supported": True,
            "eligible": False,
            "code": "output_not_ready",
            "reason": "The output must finish preparing before it can be saved.",
        }
    if not _selection_content_provider_available(state):
        view_capability = {
            "supported": False,
            "eligible": False,
            "code": "selection_content_provider_unavailable",
            "reason": "Read-only result viewing is unavailable.",
        }
    else:
        view_capability = {
            "supported": True,
            "eligible": False,
            "code": "output_not_ready",
            "reason": "The output must finish preparing before it can be viewed.",
        }
    if isinstance(selection, dict):
        runtime = _require_realm_runtime(state)
        try:
            selection_ref = SelectionRef.from_dict(selection)
            if workspace_link["keep_state"] != "saved":
                opened = runtime.selection_actions.open_read_only(
                    selection=selection_ref
                )
                keep_capability = opened.eligibility.to_dict()
            if _selection_content_provider_available(state):
                viewed = runtime.ledger.resolve_selection_for_content_read(
                    actor_principal_id=runtime.actor_principal_id,
                    selection=selection_ref,
                )
                view_capability = viewed.eligibility.to_dict()
        except (RealmConflict, RealmNotFound):
            if workspace_link["keep_state"] != "saved":
                keep_capability = {
                    "supported": True,
                    "eligible": False,
                    "code": "output_session_closed",
                    "reason": "This temporary output can no longer be saved.",
                }
            view_capability = {
                "supported": True,
                "eligible": False,
                "code": "output_session_closed",
                "reason": "This temporary output can no longer be viewed.",
            }
    execute_capability, executions = _interface_output_execution_capability(
        job,
        output_id=output_id,
        kind=kind,
        output_state=output_state,
    )
    return {
        "id": output_id,
        "label": str(raw.get("label") or ""),
        "kind": kind,
        "status": output_state,
        "attempt": raw.get("attempt"),
        "error_code": raw.get("error_code"),
        "failure_reason": (
            _interface_output_failure_reason(raw.get("error_code"))
            if output_state == "failed"
            else None
        ),
        "logical_bytes": raw.get("logical_bytes"),
        "created_at": raw.get("created_at"),
        "updated_at": raw.get("updated_at"),
        "selection": selection if isinstance(selection, dict) else None,
        "executions": executions,
        **workspace_link,
        "actions": {
            "view_read_only": view_capability,
            "keep_as_workspace": keep_capability,
            "retry_capture": {
                "supported": True,
                "eligible": output_state == "failed",
                "reason": None if output_state == "failed" else "output_not_failed",
            },
            "execute": execute_capability,
        },
    }


def _refresh_interface_output_statuses(
    state: UiState, launch_id: str
) -> List[JsonDict]:
    service = _interface_output_service(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
        handle = job.output_session if job is not None else None
    if service is None or handle is None:
        statuses: List[JsonDict] = []
    else:
        records = service.list_statuses(handle=handle)
        statuses = [
            _public_interface_output_status(state, item, job=job)
            for item in records
        ]
    with state._lock:
        current = state.interface_launches.get(launch_id)
        if current is not None:
            previous = current.result.get("outputs")
            current.result["outputs"] = statuses
            # Polling is not user-visible activity.  Advance the timestamp only
            # when the bounded output status actually changes so a quiet launch
            # is not presented as continuously doing work.
            if previous != statuses:
                current.updated_at = time.time()
    return statuses


def _interface_output_paths(job: UiLaunchJob) -> tuple[Path, Dict[str, Path]]:
    control_value = str(
        job.runtime_handles.get("OPTPILOT_INTERFACE_OUTPUTS_FILE") or ""
    )
    output_value = str(job.runtime_handles.get("OPTPILOT_INTERFACE_OUTPUT_ROOT") or "")
    if not control_value or not output_value:
        raise RealmConflict("Interface output runtime handles are unavailable.")
    runtime_dir = Path(
        str(job.runtime_handles.get("OPTPILOT_INTERFACE_RUNTIME_ROOT") or "")
    ).parent
    control_file = Path(control_value)
    output_root = Path(output_value)
    if (
        not runtime_dir.is_absolute()
        or not control_file.is_absolute()
        or not output_root.is_absolute()
        or not _is_relative_to(control_file, runtime_dir)
        or not _is_relative_to(output_root, runtime_dir)
    ):
        raise RealmConflict("Interface output runtime handles are invalid.")
    return control_file, {"output": output_root}


def _interface_output_action_paths(job: UiLaunchJob) -> Dict[str, Path]:
    root = job.output_action_root
    if root is None:
        raise RealmConflict("Interface output action broker is unavailable.")
    runtime_value = str(
        job.runtime_handles.get("OPTPILOT_INTERFACE_RUNTIME_ROOT") or ""
    )
    if not runtime_value:
        raise RealmConflict("Interface output action broker is unavailable.")
    runtime_dir = Path(runtime_value).parent
    expected = runtime_dir / "interface-output-actions"
    paths = {
        "root": root,
        "requests": root / "requests.jsonl",
        "inputs": root / "inputs",
        "responses": root / "responses",
        "results": root / "results",
        "cancellations": root / "cancellations",
    }
    identities = job.output_action_path_identities
    if (
        root != expected
        or not _is_relative_to(root, runtime_dir)
        or set(identities) != set(paths)
    ):
        raise RealmConflict("Interface output action broker identity changed.")
    for name, path in paths.items():
        try:
            linked = path.lstat()
        except OSError as error:
            raise RealmConflict(
                "Interface output action broker is unavailable."
            ) from error
        actual = (
            int(linked.st_dev),
            int(linked.st_ino),
            int(stat.S_IFMT(linked.st_mode)),
        )
        expected_identity = identities.get(name)
        expected_type = stat.S_IFREG if name == "requests" else stat.S_IFDIR
        if (
            stat.S_IFMT(linked.st_mode) != expected_type
            or actual != expected_identity
        ):
            raise RealmConflict("Interface output action broker identity changed.")
    return paths


def _interface_output_action_identity(
    job: UiLaunchJob,
    name: str,
) -> tuple[int, int, int]:
    value = job.output_action_path_identities.get(name)
    if value is None:
        raise RealmConflict("Interface output action broker identity changed.")
    return value


def _open_interface_output_action_directory(
    job: UiLaunchJob,
    name: str,
) -> int:
    """Open one launch-created broker directory without following replacements."""

    if name not in {"root", "inputs", "responses", "results", "cancellations"}:
        raise ValueError("Unknown interface output action directory.")
    paths = _interface_output_action_paths(job)
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_NOFOLLOW", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    if not getattr(os, "O_DIRECTORY", 0) or not getattr(os, "O_NOFOLLOW", 0):
        raise RealmConflict("Secure broker directory access is unavailable.")
    root_fd = os.open(paths["root"], flags)
    try:
        root_info = os.fstat(root_fd)
        actual_root = (
            int(root_info.st_dev),
            int(root_info.st_ino),
            int(stat.S_IFMT(root_info.st_mode)),
        )
        if actual_root != _interface_output_action_identity(job, "root"):
            raise RealmConflict("Interface output action broker identity changed.")
        if name == "root":
            retained_fd = root_fd
            root_fd = -1
            return retained_fd
        child_fd = os.open(paths[name].name, flags, dir_fd=root_fd)
        try:
            child_info = os.fstat(child_fd)
            actual_child = (
                int(child_info.st_dev),
                int(child_info.st_ino),
                int(stat.S_IFMT(child_info.st_mode)),
            )
            if actual_child != _interface_output_action_identity(job, name):
                raise RealmConflict(
                    "Interface output action broker identity changed."
                )
            retained_fd = child_fd
            child_fd = -1
            return retained_fd
        finally:
            if child_fd >= 0:
                os.close(child_fd)
    finally:
        if root_fd >= 0:
            os.close(root_fd)


def _interface_output_action_for_job(job: UiLaunchJob, action_id: str) -> Any:
    profile = job.interface_profile
    if profile is None:
        raise InterfaceOutputExecutionRejected(
            "The originating interface profile is unavailable."
        )
    for action in profile.output_actions:
        if action.action_id == action_id:
            return action
    raise InterfaceOutputExecutionRejected(
        "The requested output action is not authorized by this interface."
    )


def _interface_output_action_cancelled(
    state: UiState,
    job: UiLaunchJob,
    request_id: str,
) -> bool:
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        stopped = bool(
            current is not job
            or job.stop_requested
            or job.output_watcher_stop.is_set()
        )
    if stopped:
        return True
    try:
        cancellation_fd = _open_interface_output_action_directory(
            job, "cancellations"
        )
        try:
            os.stat(request_id, dir_fd=cancellation_fd, follow_symlinks=False)
            return True
        finally:
            os.close(cancellation_fd)
    except FileNotFoundError:
        return False
    except (OSError, RealmConflict):
        return True


def _interface_output_action_rejected_result(
    request: InterfaceOutputExecutionRequest,
    *,
    failure_code: str,
    detail: str,
    status: str = "rejected",
) -> InterfaceOutputExecutionResult:
    return InterfaceOutputExecutionResult(
        request_id=request.request_id,
        action_id=request.action_id,
        snapshot_ref=None,
        status=status,
        exit_code=None,
        duration_seconds=0.0,
        stdout="",
        stderr=str(detail)[-4000:],
        stdout_truncated=False,
        stderr_truncated=len(str(detail)) > 4000,
        result_files=(),
        failure_code=failure_code,
    )


def _publish_interface_output_action_result(
    job: UiLaunchJob,
    result: InterfaceOutputExecutionResult,
) -> None:
    """Export result bytes before publishing the atomic terminal response."""

    paths = _interface_output_action_paths(job)
    if result.local_results is not None:
        results_fd = _open_interface_output_action_directory(job, "results")
        try:
            result_identity = _interface_output_action_identity(job, "results")
            export_execution_result_tree_at(
                result,
                results_fd,
                paths["results"],
                result.request_id,
                expected_parent_identity=result_identity[:2],
            )
        finally:
            os.close(results_fd)
    responses_fd = _open_interface_output_action_directory(job, "responses")
    try:
        response_identity = _interface_output_action_identity(job, "responses")
        write_execution_result_at(
            responses_fd,
            f"{result.request_id}.json",
            result,
            expected_parent_identity=response_identity[:2],
        )
    finally:
        os.close(responses_fd)


def _interface_output_action_result_file_bytes(
    state: UiState,
    *,
    launch_id: str,
    request_id: str,
    relative_path: str,
) -> tuple[bytes, str, str]:
    """Read one evidenced result file through the launch-owned broker root."""

    selected_path = _interface_output_action_result_path(relative_path)
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            raise RealmNotFound("Interface launch not found.")
        if (
            job.output_action_root is None
            or job.status
            not in {"running", "ready", "stopping", "cleanup_pending"}
        ):
            raise RealmConflict(
                "Action result files are no longer available because the "
                "originating interface launch has ended."
            )
        execution = job.output_action_executions.get(request_id)
        result = execution.get("result") if isinstance(execution, Mapping) else None
        raw_files = (
            result.get("result_files") if isinstance(result, Mapping) else None
        )
        expected = next(
            (
                dict(item)
                for item in raw_files
                if isinstance(item, Mapping)
                and item.get("path") == selected_path
            ),
            None,
        ) if isinstance(raw_files, list) else None
    if expected is None:
        raise RealmNotFound("Action result file not found.")
    size = expected.get("size")
    digest = expected.get("sha256")
    if (
        isinstance(size, bool)
        or not isinstance(size, int)
        or size < 0
        or not isinstance(digest, str)
        or re.fullmatch(r"[0-9a-f]{64}", digest) is None
    ):
        raise RealmConflict("Action result evidence is invalid.")
    if size > _MAX_BROWSER_INTERFACE_OUTPUT_ACTION_RESULT_FILE_BYTES:
        raise RealmConflict(
            "This action result file is too large for the bounded browser "
            "download endpoint."
        )

    results_fd = -1
    request_fd = -1
    directory_fd = -1
    file_fd = -1
    try:
        results_fd = _open_interface_output_action_directory(job, "results")
        request_fd = os.open(
            request_id,
            os.O_RDONLY
            | os.O_DIRECTORY
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=results_fd,
        )
        directory_fd = os.dup(request_fd)
        parts = selected_path.split("/")
        for component in parts[:-1]:
            next_fd = os.open(
                component,
                os.O_RDONLY
                | os.O_DIRECTORY
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=directory_fd,
            )
            os.close(directory_fd)
            directory_fd = next_fd
        file_fd = os.open(
            parts[-1],
            os.O_RDONLY
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NONBLOCK", 0),
            dir_fd=directory_fd,
        )
        before = os.fstat(file_fd)
        identity = (
            int(before.st_dev),
            int(before.st_ino),
            int(before.st_mode),
            int(before.st_size),
            int(before.st_mtime_ns),
            int(before.st_ctime_ns),
        )
        if not stat.S_ISREG(before.st_mode) or before.st_size != size:
            raise RealmConflict("Action result file no longer matches its evidence.")
        data = bytearray()
        remaining = size + 1
        while remaining > 0:
            chunk = os.read(file_fd, min(64 * 1024, remaining))
            if not chunk:
                break
            data.extend(chunk)
            remaining -= len(chunk)
        after = os.fstat(file_fd)
        after_identity = (
            int(after.st_dev),
            int(after.st_ino),
            int(after.st_mode),
            int(after.st_size),
            int(after.st_mtime_ns),
            int(after.st_ctime_ns),
        )
        if (
            len(data) != size
            or identity != after_identity
            or hashlib.sha256(data).hexdigest() != digest
        ):
            raise RealmConflict("Action result file no longer matches its evidence.")
    except (FileNotFoundError, NotADirectoryError):
        raise RealmNotFound("Action result file not found.") from None
    except RealmConflict:
        raise
    except OSError:
        raise RealmConflict("Action result file could not be read safely.") from None
    finally:
        for descriptor in (file_fd, directory_fd, request_fd, results_fd):
            if descriptor >= 0:
                try:
                    os.close(descriptor)
                except OSError:
                    pass
    media_type = mimetypes.guess_type(selected_path)[0] or (
        "application/octet-stream"
    )
    return bytes(data), media_type, PurePosixPath(selected_path).name


def _set_interface_output_action_execution(
    state: UiState,
    job: UiLaunchJob,
    request_id: str,
    *,
    status: str,
    result: Optional[InterfaceOutputExecutionResult] = None,
) -> None:
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        if current is not job:
            return
        record = job.output_action_executions.get(request_id)
        if record is None:
            return
        record["status"] = status
        record["updated_at"] = time.time()
        if result is not None:
            record["result"] = result.to_dict()
        job.updated_at = time.time()
    try:
        _refresh_interface_output_statuses(state, job.launch_id)
    except Exception:
        pass


def _record_terminal_interface_output_action_request(
    state: UiState,
    job: UiLaunchJob,
    request: InterfaceOutputExecutionRequest,
    *,
    output_id: str,
    result: InterfaceOutputExecutionResult,
) -> bool:
    """Fence a canonical rejected request so it can never execute later."""

    digest = request_digest({**request.to_dict(), "output_id": output_id})
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        if current is not job:
            return False
        previous = job.output_action_request_digests.get(request.request_id)
        if previous is not None:
            if previous != digest:
                raise InterfaceOutputExecutionRejected(
                    "A request id cannot be reused with another payload."
                )
            return False
        # The broker file itself is bounded to this count.  HTTP requests can
        # fill the in-memory registry first; in that case the limit cannot
        # become available later because request identities are never evicted,
        # so publishing the rejection without growing the map remains final.
        if len(job.output_action_request_digests) >= (
            _MAX_INTERFACE_OUTPUT_ACTION_REQUESTS
        ):
            return True
        try:
            label = _interface_output_action_for_job(
                job, request.action_id
            ).label
        except InterfaceOutputExecutionRejected:
            label = request.action_id
        now = time.time()
        job.output_action_request_digests[request.request_id] = digest
        job.output_action_executions[request.request_id] = {
            "request_id": request.request_id,
            "action_id": request.action_id,
            "label": label,
            "output_id": output_id,
            "status": result.status,
            "started_at": now,
            "updated_at": now,
            "result": result.to_dict(),
        }
        job.updated_at = now
    return True


def _complete_interface_output_action_thread(
    state: UiState,
    job: UiLaunchJob,
    request_id: str,
) -> None:
    should_settle = False
    terminal_target = ""
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        if current is job:
            job.output_action_threads.pop(request_id, None)
            if not job.output_action_threads:
                job.output_actions_quiesced.set()
                terminal_target = (
                    "stopped" if job.stop_requested else job.terminal_target
                )
                should_settle = bool(
                    terminal_target and job.execution_quiesced.is_set()
                )
    if should_settle:
        try:
            _settle_interface_launch(
                state,
                job.launch_id,
                terminal_target=terminal_target,
            )
        except Exception:
            pass


def _run_interface_output_action_worker(
    state: UiState,
    job: UiLaunchJob,
    request: InterfaceOutputExecutionRequest,
    *,
    source_factory: Callable[[], tuple[ImmutableInterfaceOutputTree, Callable[[], None]]],
) -> None:
    result: Optional[InterfaceOutputExecutionResult] = None
    executed_result: Optional[InterfaceOutputExecutionResult] = None
    source: Optional[ImmutableInterfaceOutputTree] = None
    release_source: Callable[[], None] = lambda: None
    _set_interface_output_action_execution(
        state,
        job,
        request.request_id,
        status="running",
    )
    try:
        if _interface_output_action_cancelled(state, job, request.request_id):
            result = _interface_output_action_rejected_result(
                request,
                failure_code="cancelled",
                detail="Execution was cancelled before it started.",
                status="cancelled",
            )
        else:
            action = _interface_output_action_for_job(job, request.action_id)
            with state._lock:
                lease = (
                    job.prepared_runtime_lease
                    if state.interface_launches.get(job.launch_id) is job
                    and not job.stop_requested
                    else None
                )
                execution_root = job.output_execution_root
            if lease is None or execution_root is None:
                raise InterfaceOutputExecutionUnavailable(
                    "The originating prepared runtime is unavailable."
                )
            source, release_source = source_factory()
            runtime = OriginatingPreparedRuntime.from_lease(lease)
            executable = state.workspace_runtime._require_container_executable()
            executor = LocalContainerInterfaceOutputExecutor(
                executable=executable,
                runtime_root=execution_root / "containers",
            )
            result = executor.execute(
                source=source,
                runtime=runtime,
                action=action,
                request=request,
                should_cancel=lambda: _interface_output_action_cancelled(
                    state, job, request.request_id
                ),
            )
            executed_result = result
        _publish_interface_output_action_result(job, result)
    except InterfaceOutputExecutionRejected as error:
        result = _interface_output_action_rejected_result(
            request,
            failure_code="request_rejected",
            detail=str(error),
        )
        try:
            _publish_interface_output_action_result(job, result)
        except Exception:
            pass
    except Exception as error:
        if executed_result is not None:
            try:
                executed_result.cleanup()
            except Exception:
                pass
            executed_result = None
        result = _interface_output_action_rejected_result(
            request,
            failure_code="execution_unavailable",
            detail=str(error),
            status="infrastructure_failed",
        )
        try:
            _publish_interface_output_action_result(job, result)
        except Exception:
            pass
    finally:
        try:
            release_source()
        except Exception:
            pass
        if source is not None:
            try:
                source.cleanup()
            except Exception:
                pass
        if result is not None:
            try:
                result.cleanup()
            except Exception:
                pass
            _set_interface_output_action_execution(
                state,
                job,
                request.request_id,
                status=result.status,
                result=result,
            )
        _complete_interface_output_action_thread(
            state,
            job,
            request.request_id,
        )


def _schedule_interface_output_action(
    state: UiState,
    job: UiLaunchJob,
    request: InterfaceOutputExecutionRequest,
    *,
    output_id: str,
    source_factory: Callable[[], tuple[ImmutableInterfaceOutputTree, Callable[[], None]]],
) -> bool:
    request_payload = {
        **request.to_dict(),
        "output_id": output_id,
    }
    digest = request_digest(request_payload)
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        if current is not job or job.stop_requested or job.terminal_target:
            raise RealmConflict("The originating interface launch is stopping.")
        previous = job.output_action_request_digests.get(request.request_id)
        if previous is not None:
            if previous != digest:
                raise InterfaceOutputExecutionRejected(
                    "A request id cannot be reused with another payload."
                )
            return False
        if len(job.output_action_request_digests) >= (
            _MAX_INTERFACE_OUTPUT_ACTION_REQUESTS
        ):
            raise InterfaceOutputExecutionRejected(
                "This interface launch reached its output action request limit."
            )
        # Registered workers count as active even during the small interval
        # before Thread.start() makes is_alive() true.
        active = len(job.output_action_threads)
        if active >= _MAX_CONCURRENT_INTERFACE_OUTPUT_ACTIONS:
            raise InterfaceOutputExecutionRejected(
                "Too many output actions are already running."
            )
        action = _interface_output_action_for_job(job, request.action_id)
        if (
            request.timeout_seconds is not None
            and request.timeout_seconds > action.timeout_seconds
        ):
            raise InterfaceOutputExecutionRejected(
                "Execution timeout may not exceed the authored action maximum."
            )
        now = time.time()
        job.output_action_request_digests[request.request_id] = digest
        job.output_action_executions[request.request_id] = {
            "request_id": request.request_id,
            "action_id": request.action_id,
            "label": action.label,
            "output_id": output_id,
            "status": "queued",
            "started_at": now,
            "updated_at": now,
            "result": None,
        }
        worker = threading.Thread(
            target=_run_interface_output_action_worker,
            args=(state, job, request),
            kwargs={"source_factory": source_factory},
            daemon=True,
            name=(
                f"interface-output-action-{job.launch_id}-"
                f"{request.request_id[-20:]}"
            ),
        )
        job.output_action_threads[request.request_id] = worker
        job.output_actions_quiesced.clear()
    try:
        worker.start()
    except Exception:
        with state._lock:
            job.output_action_threads.pop(request.request_id, None)
            job.output_action_executions.pop(request.request_id, None)
            job.output_action_request_digests.pop(request.request_id, None)
            if not job.output_action_threads:
                job.output_actions_quiesced.set()
        raise
    return True


def _read_interface_output_action_requests(job: UiLaunchJob) -> List[bytes]:
    paths = _interface_output_action_paths(job)
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | getattr(os, "O_NOFOLLOW", 0)
    )
    root_fd = _open_interface_output_action_directory(job, "root")
    try:
        descriptor = os.open(paths["requests"].name, flags, dir_fd=root_fd)
    finally:
        os.close(root_fd)
    try:
        info = os.fstat(descriptor)
        actual = (
            int(info.st_dev),
            int(info.st_ino),
            int(stat.S_IFMT(info.st_mode)),
        )
        if (
            not stat.S_ISREG(info.st_mode)
            or actual != _interface_output_action_identity(job, "requests")
            or info.st_size > _MAX_INTERFACE_OUTPUT_ACTION_REQUEST_FILE_BYTES
        ):
            raise InterfaceOutputExecutionRejected(
                "Output action request file is invalid or too large."
            )
        remaining = _MAX_INTERFACE_OUTPUT_ACTION_REQUEST_FILE_BYTES + 1
        chunks: List[bytes] = []
        while remaining > 0:
            chunk = os.read(descriptor, min(64 * 1024, remaining))
            if not chunk:
                break
            chunks.append(chunk)
            remaining -= len(chunk)
        payload = b"".join(chunks)
        if len(payload) > _MAX_INTERFACE_OUTPUT_ACTION_REQUEST_FILE_BYTES:
            raise InterfaceOutputExecutionRejected(
                "Output action request file is too large."
            )
    finally:
        os.close(descriptor)
    if not payload:
        return []
    # A writer may still be appending its last record.  Consume only complete
    # newline-terminated records; the watcher retries after the next metadata
    # change.
    lines = payload.splitlines(keepends=True)
    if lines and not lines[-1].endswith((b"\n", b"\r")):
        lines.pop()
    if len(lines) > _MAX_INTERFACE_OUTPUT_ACTION_REQUESTS:
        raise InterfaceOutputExecutionRejected(
            "Output action request file contains too many records."
        )
    for line in lines:
        if len(line) > _MAX_INTERFACE_OUTPUT_ACTION_REQUEST_LINE_BYTES:
            raise InterfaceOutputExecutionRejected(
                "An output action request record is too large."
            )
    return lines


def _record_interface_output_action_broker_error(
    state: UiState,
    job: UiLaunchJob,
    code: str,
) -> None:
    with state._lock:
        current = state.interface_launches.get(job.launch_id)
        if current is job:
            job.result["output_action_broker_error"] = code
            job.updated_at = time.time()


def _process_interface_output_action_requests(
    state: UiState,
    launch_id: str,
) -> None:
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None or job.output_action_root is None:
        return
    try:
        lines = _read_interface_output_action_requests(job)
    except (OSError, RealmConflict, InterfaceOutputExecutionRejected):
        _record_interface_output_action_broker_error(
            state,
            job,
            "request_file_rejected",
        )
        return
    encountered_error = False
    for line in lines:
        try:
            decoded = json.loads(line)
            request = InterfaceOutputExecutionRequest.from_dict(decoded)
        except (json.JSONDecodeError, TypeError, InterfaceOutputExecutionRejected):
            encountered_error = True
            _record_interface_output_action_broker_error(
                state,
                job,
                "request_record_rejected",
            )
            continue
        with state._lock:
            execution_root = job.output_execution_root
        if execution_root is None:
            result = _interface_output_action_rejected_result(
                request,
                failure_code="execution_unavailable",
                detail="Output execution storage is unavailable.",
                status="infrastructure_failed",
            )
            if _record_terminal_interface_output_action_request(
                state,
                job,
                request,
                output_id="",
                result=result,
            ):
                try:
                    _publish_interface_output_action_result(job, result)
                except Exception:
                    pass
            continue

        def source_factory(
            *,
            selected_job: UiLaunchJob = job,
            selected_request: InterfaceOutputExecutionRequest = request,
            selected_execution_root: Path = execution_root,
        ) -> tuple[ImmutableInterfaceOutputTree, Callable[[], None]]:
            action_paths = _interface_output_action_paths(selected_job)
            inputs_identity = _interface_output_action_identity(
                selected_job, "inputs"
            )
            source = snapshot_interface_output_tree(
                allowed_root=action_paths["inputs"],
                snapshot_parent=selected_execution_root / "snapshots",
                request_id=selected_request.request_id,
                relative_path=selected_request.output_path,
                expected_allowed_root_identity=inputs_identity[:2],
            )
            return source, lambda: None

        try:
            _schedule_interface_output_action(
                state,
                job,
                request,
                output_id="",
                source_factory=source_factory,
            )
        except InterfaceOutputExecutionRejected as error:
            # Never replace the response for an existing id whose payload was
            # changed.  The original request remains authoritative.
            with state._lock:
                previous = job.output_action_request_digests.get(
                    request.request_id
                )
            candidate_digest = request_digest(
                {**request.to_dict(), "output_id": ""}
            )
            if previous is not None and previous != candidate_digest:
                encountered_error = True
                _record_interface_output_action_broker_error(
                    state,
                    job,
                    "duplicate_request_changed",
                )
                continue
            result = _interface_output_action_rejected_result(
                request,
                failure_code="request_rejected",
                detail=str(error),
            )
            if _record_terminal_interface_output_action_request(
                state,
                job,
                request,
                output_id="",
                result=result,
            ):
                try:
                    _publish_interface_output_action_result(job, result)
                except Exception:
                    pass
        except RealmConflict:
            result = _interface_output_action_rejected_result(
                request,
                failure_code="launch_stopping",
                detail="The originating interface launch is stopping.",
                status="cancelled",
            )
            try:
                _publish_interface_output_action_result(job, result)
            except Exception:
                pass
    if not encountered_error:
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is job:
                current.result.pop("output_action_broker_error", None)


def _interface_output_tree_capability(state: UiState, job: UiLaunchJob) -> JsonDict:
    def unavailable(code: str, reason: str, *, supported: bool = True) -> JsonDict:
        return {
            "supported": supported,
            "eligible": False,
            "code": code,
            "reason": reason,
        }

    if not job.outputs_enabled:
        return unavailable(
            "interface_outputs_not_declared",
            "This interface does not declare reusable outputs.",
            supported=False,
        )
    if job.launch_scope not in {"catalog-transient", "workspace-transient"}:
        return unavailable(
            "launch_scope_unsupported",
            "This launch does not own an output root that Studio can inspect.",
            supported=False,
        )
    if _interface_output_service(state) is None:
        return unavailable(
            "output_service_unavailable",
            "Interface output capture is unavailable in this Studio process.",
            supported=False,
        )
    if job.status == "stopped":
        return unavailable(
            "launch_stopped",
            "The launch has stopped and its output root has been retired.",
        )
    if job.status in {"stopping", "cleanup_pending"} or job.stop_requested:
        return unavailable(
            "launch_closing",
            "The launch is stopping, so no new output selection can be captured.",
        )
    if job.status == "failed":
        return unavailable(
            "launch_failed",
            "The launch failed and its output runtime is unavailable.",
        )
    if job.status not in {"running", "ready"}:
        return unavailable(
            "launch_not_active",
            "Wait until the interface output runtime is active.",
        )
    handle = job.output_session
    if handle is None:
        return unavailable(
            "output_session_unavailable",
            "The launch does not have an active output session.",
        )
    if handle.lease.state.value != "active":
        return unavailable(
            "output_session_closed",
            "The launch output session is closed.",
        )
    if handle.lease.expires_at <= time.time():
        return unavailable(
            "output_session_expired",
            "The launch output session expired.",
        )
    try:
        _control_file, roots = _interface_output_paths(job)
        output_root = roots["output"]
        root_status = output_root.lstat()
    except (KeyError, OSError, RealmConflict):
        return unavailable(
            "output_root_unavailable",
            "The launch-owned output root is unavailable.",
        )
    if not stat.S_ISDIR(root_status.st_mode):
        return unavailable(
            "output_root_invalid",
            "The launch-owned output root is not a directory.",
        )
    return {
        "supported": True,
        "eligible": True,
        "code": "ready",
        "reason": None,
        "kind": "tree",
    }


def _interface_output_tree_choices(state: UiState, launch_id: str) -> JsonDict:
    service = _interface_output_service(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    capability = _interface_output_tree_capability(state, job)
    if service is None or not capability["eligible"]:
        return {"action": capability, "paths": []}
    with job.output_capture_lock:
        capability = _interface_output_tree_capability(state, job)
        if not capability["eligible"]:
            return {"action": capability, "paths": []}
        handle = job.output_session
        assert handle is not None
        _control_file, roots = _interface_output_paths(job)
        try:
            paths = service.list_tree_selections(
                handle=handle,
                root_path=roots["output"],
            )
        except RealmExpired:
            capability = {
                "supported": True,
                "eligible": False,
                "code": "output_session_expired",
                "reason": "The launch output session expired.",
            }
            paths = ()
        except RealmConflict as error:
            capability = {
                "supported": True,
                "eligible": False,
                "code": "output_session_changed",
                "reason": str(error),
            }
            paths = ()
        except ContentRejected:
            capability = {
                "supported": True,
                "eligible": False,
                "code": "output_tree_unavailable",
                "reason": (
                    "The output folder changed or is too large to list; "
                    "retry after generation finishes."
                ),
            }
            paths = ()
    return {"action": capability, "paths": list(paths)}


def _capture_interface_output_tree(
    state: UiState,
    launch_id: str,
    payload: JsonDict,
) -> JsonDict:
    if not isinstance(payload, dict) or set(payload) != {"label", "path"}:
        raise ValueError(
            "Output folder capture accepts exactly a label and a relative path."
        )
    service = _interface_output_service(state)
    if service is None:
        raise RealmConflict("Interface output capture is unavailable.")
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    with job.output_capture_lock:
        capability = _interface_output_tree_capability(state, job)
        if not capability["eligible"]:
            raise RealmConflict(str(capability["reason"]))
        handle = job.output_session
        assert handle is not None
        _control_file, roots = _interface_output_paths(job)
        try:
            status = service.capture_tree_selection(
                handle=handle,
                label=payload["label"],
                relative_path=payload["path"],
                root_handle="output",
                root_path=roots["output"],
            )
        except ContentRejected as error:
            raise ValueError(
                "Output label and path must be non-empty, bounded, and the path "
                "must be canonical and relative to the launch output root."
            ) from error
    statuses = _refresh_interface_output_statuses(state, launch_id)
    output = next(
        (item for item in statuses if item.get("id") == status.output_id),
        None,
    )
    if output is None:
        raise RealmConflict("Captured interface output status is unavailable.")
    return {"launch": _interface_launch_by_id(state, launch_id), "output": output}


def _record_interface_output_capture_error(
    state: UiState,
    launch_id: str,
    error: BaseException,
    *,
    error_code: Optional[str] = None,
) -> None:
    resolved_code = error_code or "capture_failed"
    if error_code is None:
        if isinstance(error, RealmConflict):
            resolved_code = "realm_conflict"
        elif isinstance(error, FileNotFoundError):
            resolved_code = "output_runtime_missing"
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is not None:
            job.result["output_capture_error"] = resolved_code
            job.updated_at = time.time()


def _capture_interface_outputs_once(state: UiState, launch_id: str) -> List[JsonDict]:
    service = _interface_output_service(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if service is None or job is None or job.output_session is None:
        return []
    with job.output_capture_lock:
        try:
            control_file, root_handles = _interface_output_paths(job)
            rejected_records: List[Any] = []
            service.capture_control_file(
                handle=job.output_session,
                control_file=control_file,
                root_handles=root_handles,
                retry_failed=False,
                rejected_records=rejected_records,
            )
            with state._lock:
                current = state.interface_launches.get(launch_id)
                if current is not None:
                    current.result.pop("output_capture_error", None)
                    if rejected_records:
                        current.result["output_record_errors"] = [
                            item.to_dict() for item in rejected_records
                        ]
                    else:
                        current.result.pop("output_record_errors", None)
            return _refresh_interface_output_statuses(state, launch_id)
        except BaseException as error:
            _record_interface_output_capture_error(state, launch_id, error)
            try:
                return _refresh_interface_output_statuses(state, launch_id)
            except Exception:
                return []


def _same_interface_output_fence(
    left: InterfaceOutputSessionHandle,
    right: InterfaceOutputSessionHandle,
) -> bool:
    return bool(
        left.session.session_id == right.session.session_id
        and left.session.owner_id == right.session.owner_id
        and left.lease.lease_id == right.lease.lease_id
        and left.lease.holder_id == right.lease.holder_id
        and left.lease.fencing_token == right.lease.fencing_token
    )


def _prove_interface_output_resume_runtime(
    state: UiState,
    job: UiLaunchJob,
) -> None:
    """Prove this process still owns live work before replacing an expired fence."""

    claim = state._runtime_supervisor_claim
    if claim is None:
        raise RuntimeError(
            "Interface output recovery requires the Studio runtime-supervisor claim."
        )
    claim.assert_active_for(state.cwd)
    workspace = dict(job.runtime_workspace)
    workspace_id = str(workspace.get("id") or "")
    if not workspace_id or workspace_id != f"interface-{job.launch_id}":
        raise RuntimeError("Interface output recovery runtime identity changed.")
    record_path = state.workspace_runtime._record_path(workspace_id)
    if not record_path.is_file():
        raise RuntimeError("Interface output recovery runtime record is unavailable.")
    record = state.workspace_runtime._read_record(workspace_id)
    if not record or _workspace_runtime_record_proves_terminal(record):
        raise RuntimeError("Interface output recovery runtime is terminal.")

    worker = job.worker_thread
    if (
        worker is not None
        and worker.is_alive()
        and not job.execution_quiesced.is_set()
    ):
        # Setup/startup is still executing under this process-lifetime claim.
        # The runtime may legitimately still be in its pre-container record.
        return
    status = state.workspace_runtime.status(workspace)
    if str(status.get("status") or "").lower() != "running":
        raise RuntimeError("Interface output recovery runtime is not running.")


def _resume_interface_outputs_after_expiry(
    state: UiState,
    launch_id: str,
    stale_handle: InterfaceOutputSessionHandle,
) -> Optional[InterfaceOutputSessionHandle]:
    """Replace one expired output lease while retaining Stop-race ownership."""

    service = _interface_output_service(state)
    if service is None:
        raise RuntimeError("Interface output recovery service is unavailable.")
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        return None
    with job.cleanup_lock:
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not job:
                return None
            current_handle = job.output_session
            if current_handle is None:
                return None
            if (
                job.launch_id != launch_id
                or stale_handle.session.launch_id != launch_id
                or current_handle.session.launch_id != launch_id
            ):
                raise RuntimeError(
                    "Interface output recovery launch identity changed."
                )
            if not _same_interface_output_fence(current_handle, stale_handle):
                return current_handle
            if job.output_watcher_stop.is_set() or job.stop_requested:
                return None

        # Provider/runtime inspection and Realm I/O never run under the
        # process-wide state lock. cleanup_lock linearizes this proof and the
        # replacement against terminal settlement.
        _prove_interface_output_resume_runtime(state, job)
        resumed = service.resume_expired_session(
            operation_id=(
                f"studio/interface-launch/{launch_id}/outputs/resume/"
                f"{stale_handle.lease.fencing_token}"
            ),
            handle=stale_handle,
            ttl_seconds=90,
        )
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not job:
                # Jobs are not normally removed before settlement. Keep the
                # durable handle reachable if an administrative caller did so.
                job.output_session = resumed
                return None
            current_handle = job.output_session
            if current_handle is not None and not _same_interface_output_fence(
                current_handle, stale_handle
            ):
                return current_handle
            job.output_session = resumed
            if job.result.get("output_capture_error") in {
                "output_session_heartbeat_failed",
                "output_session_recovery_pending",
            }:
                job.result.pop("output_capture_error", None)
            if job.output_watcher_stop.is_set() or job.stop_requested:
                return None
        return resumed


def _watch_interface_outputs(state: UiState, launch_id: str) -> None:
    last_signature: Optional[tuple[int, int, int, int, int]] = None
    last_action_signature: Optional[tuple[int, int, int, int, int]] = None
    heartbeat_at = 0.0
    heartbeat_failures = 0
    while True:
        with state._lock:
            job = state.interface_launches.get(launch_id)
            if job is None:
                return
            stop = job.output_watcher_stop
            handle = job.output_session
        if stop.is_set() or handle is None:
            return
        try:
            control_file, _root_handles = _interface_output_paths(job)
            control_stat = control_file.stat()
            signature = (
                int(control_stat.st_dev),
                int(control_stat.st_ino),
                int(control_stat.st_size),
                int(control_stat.st_mtime_ns),
                int(control_stat.st_ctime_ns),
            )
            if signature != last_signature:
                _capture_interface_outputs_once(state, launch_id)
                last_signature = signature
        except FileNotFoundError:
            pass
        except OSError as error:
            # A synchronized or temporarily unavailable host filesystem can
            # fail one metadata read. Do not let that stop lease heartbeats;
            # the next successful poll will retry capture from the durable
            # append-only control file.
            _record_interface_output_capture_error(
                state,
                launch_id,
                error,
                error_code="output_control_poll_failed",
            )
        else:
            with state._lock:
                current = state.interface_launches.get(launch_id)
                if (
                    current is not None
                    and current.result.get("output_capture_error")
                    == "output_control_poll_failed"
                ):
                    current.result.pop("output_capture_error", None)
        if job.output_action_root is not None:
            try:
                requests_file = _interface_output_action_paths(job)["requests"]
                request_stat = requests_file.lstat()
                if requests_file.is_symlink() or not stat.S_ISREG(
                    request_stat.st_mode
                ):
                    raise OSError("Output action request file identity changed.")
                action_signature = (
                    int(request_stat.st_dev),
                    int(request_stat.st_ino),
                    int(request_stat.st_size),
                    int(request_stat.st_mtime_ns),
                    int(request_stat.st_ctime_ns),
                )
                if action_signature != last_action_signature:
                    _process_interface_output_action_requests(state, launch_id)
                    last_action_signature = action_signature
            except (OSError, RealmConflict):
                _record_interface_output_action_broker_error(
                    state,
                    job,
                    "request_file_rejected",
                )
        now = time.monotonic()
        if now >= heartbeat_at:
            service = _interface_output_service(state)
            if service is None:
                return
            try:
                renewed = service.heartbeat_session(
                    operation_id=(
                        f"studio/interface-launch/{launch_id}/outputs/heartbeat/"
                        f"{uuid.uuid4().hex}"
                    ),
                    handle=handle,
                    ttl_seconds=90,
                )
                with state._lock:
                    current = state.interface_launches.get(launch_id)
                    if current is not None and current.output_session is handle:
                        current.output_session = renewed
                handle = renewed
                heartbeat_failures = 0
                with state._lock:
                    current = state.interface_launches.get(launch_id)
                    if (
                        current is not None
                        and current.result.get("output_capture_error")
                        == "output_session_heartbeat_failed"
                    ):
                        current.result.pop("output_capture_error", None)
            except RealmExpired as error:
                _record_interface_output_capture_error(
                    state,
                    launch_id,
                    error,
                    error_code="output_session_recovery_pending",
                )
                try:
                    resumed = _resume_interface_outputs_after_expiry(
                        state, launch_id, handle
                    )
                except (RealmConflict, RealmNotFound) as recovery_error:
                    _record_interface_output_capture_error(
                        state, launch_id, recovery_error
                    )
                    return
                except Exception as recovery_error:
                    heartbeat_failures += 1
                    _record_interface_output_capture_error(
                        state,
                        launch_id,
                        recovery_error,
                        error_code="output_session_recovery_pending",
                    )
                    heartbeat_at = now + min(
                        20.0, float(2 ** min(heartbeat_failures - 1, 4))
                    )
                    continue
                if resumed is None:
                    return
                handle = resumed
                # The poll immediately before this heartbeat may have seen a
                # changed control file but failed capture under the expired
                # fence. Force the same immutable file state through capture
                # again under the replacement lease.
                last_signature = None
                heartbeat_failures = 0
                heartbeat_at = now + 20
                continue
            except (RealmConflict, RealmNotFound) as error:
                _record_interface_output_capture_error(state, launch_id, error)
                return
            except Exception as error:
                heartbeat_failures += 1
                _record_interface_output_capture_error(
                    state,
                    launch_id,
                    error,
                    error_code="output_session_heartbeat_failed",
                )
                heartbeat_at = now + min(
                    20.0, float(2 ** min(heartbeat_failures - 1, 4))
                )
                continue
            heartbeat_at = now + 20
        stop.wait(0.25)


def _begin_interface_output_session(state: UiState, launch_id: str) -> None:
    service = _interface_output_service(state)
    if service is None:
        return
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        return
    if not job.outputs_enabled:
        return
    with job.cleanup_lock:
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if (
                current is not job
                or job.output_session is not None
                or job.stop_requested
            ):
                return
        handle = service.create_session(
            operation_id=f"studio/interface-launch/{launch_id}/outputs/create",
            launch_id=launch_id,
            ttl_seconds=90,
        )
        watcher = threading.Thread(
            target=_watch_interface_outputs,
            args=(state, launch_id),
            daemon=True,
            name=f"interface-outputs-{launch_id}",
        )
        retire_unowned = False
        start_watcher = False
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not job:
                retire_unowned = True
            else:
                # Once create_session succeeds, the job owns that durable
                # handle even if Stop raced the provider call.  Finalization
                # can now retry retirement instead of falsely declaring that
                # no session existed.
                job.output_session = handle
                job.result.setdefault("outputs", [])
                if not job.stop_requested:
                    job.output_watcher = watcher
                    start_watcher = True
        if retire_unowned:
            # Provider I/O never runs under the process-wide state lock.
            service.retire_session(
                operation_id=f"studio/interface-launch/{launch_id}/outputs/abandon",
                handle=handle,
            )
            return
        if start_watcher:
            watcher.start()


def _mark_prestart_interface_runtime_terminal(
    state: UiState,
    workspace: JsonDict,
) -> bool:
    """Seal a quiesced pre-start runtime without consulting the engine.

    Callers must know that the launch worker has unwound, or that Studio is
    recovering after a process restart. The durable ``starting`` transition is
    written before ``docker run``, so an exact ``preparing`` record with no
    start evidence proves that this launch never submitted container execution.
    """

    workspace_id = str(workspace.get("id") or "")
    if not workspace_id:
        return False
    record_path = state.workspace_runtime._record_path(workspace_id)
    if not record_path.is_file():
        return False
    record = state.workspace_runtime._read_record(workspace_id)
    if not _workspace_runtime_record_is_prestart(record):
        return _workspace_runtime_record_proves_terminal(record)
    record.update(
        {
            "status": "stopped",
            "updated_at": _now_iso(),
            "terminal_proof": {
                "container_name": "",
                "terminal_confirmed": True,
                "state": "absent",
                "basis": "container_start_not_submitted",
            },
        }
    )
    state.workspace_runtime._write_record(workspace_id, record)
    return True


def _cleanup_transient_interface_runtime(
    state: UiState,
    workspace: JsonDict,
    port: int,
) -> JsonDict:
    """Best-effort cleanup for direct launches that have no output session."""

    workspace_id = str(workspace.get("id") or "")
    if not workspace_id:
        return {
            "cleaned": True,
            "runtime_terminal_confirmed": True,
            "runtime_deleted": True,
            "presentation_closed": True,
        }
    runtime_dir = state.workspace_runtime._workspace_runtime_dir(workspace_id)
    has_runtime_record = state.workspace_runtime._record_path(workspace_id).is_file()
    terminal_confirmed = not has_runtime_record
    if has_runtime_record:
        # This helper is used only when no tracked launch worker owns cleanup.
        _mark_prestart_interface_runtime_terminal(state, workspace)
        record = state.workspace_runtime._read_record(workspace_id)
        terminal_confirmed = _workspace_runtime_record_proves_terminal(record)
        if not terminal_confirmed:
            try:
                state.workspace_runtime.stop(workspace)
                stopped_record = state.workspace_runtime._read_record(workspace_id)
                terminal_confirmed = _workspace_runtime_record_proves_terminal(
                    stopped_record
                )
            except Exception:
                terminal_confirmed = False
    presentation_closed = True
    try:
        presentation_closed = bool(
            state._stop_workspace_preview_proxy(
                f"{workspace_id}:{int(port)}"
            )
        )
    except Exception:  # pragma: no cover - defensive broker boundary
        presentation_closed = False
    runtime_deleted = False
    if terminal_confirmed and presentation_closed:
        try:
            state.workspace_runtime.delete(workspace_id)
        except Exception:  # pragma: no cover - defensive container boundary
            pass
    runtime_deleted = not runtime_dir.exists()
    result = {
        "cleaned": presentation_closed and terminal_confirmed and runtime_deleted,
        "runtime_terminal_confirmed": terminal_confirmed,
        "runtime_deleted": runtime_deleted,
        "presentation_closed": presentation_closed,
    }
    if not terminal_confirmed:
        result["error"] = "runtime_stop_unconfirmed"
    elif not presentation_closed:
        result["error"] = "presentation_close_failed"
    elif not runtime_deleted:
        result["error"] = "runtime_delete_failed"
    return result


def _finish_transient_interface_cleanup(
    state: UiState,
    launch_id: str,
    job: UiLaunchJob,
    workspace_id: str,
    runtime_dir: Path,
    port: int,
) -> JsonDict:
    """Finish cleanup while the output generation/Keep boundary is locked."""

    _capture_interface_outputs_once(state, launch_id)
    _retain_interface_launch_logs(job)

    presentation_closed = True
    try:
        presentation_closed = bool(
            state._stop_workspace_preview_proxy(
                f"{workspace_id}:{int(port)}"
            )
        )
    except Exception:  # pragma: no cover - defensive broker boundary
        presentation_closed = False

    runtime_deleted = False
    if presentation_closed:
        try:
            state.workspace_runtime.delete(workspace_id)
            runtime_deleted = not runtime_dir.exists()
        except Exception:  # pragma: no cover - defensive container boundary
            runtime_deleted = False

    session_retired = job.output_session is None
    if runtime_deleted and job.output_session is not None:
        service = _interface_output_service(state)
        if service is not None:
            try:
                service.retire_session(
                    operation_id=(
                        f"studio/interface-launch/{launch_id}/outputs/finalize"
                    ),
                    handle=job.output_session,
                )
                job.output_session = None
                session_retired = True
            except Exception:
                session_retired = False

    source_projection_released = job.source_projection is None
    if runtime_deleted and job.source_projection is not None:
        try:
            job.source_projection.close()
            job.source_projection = None
            source_projection_released = True
        except Exception:
            source_projection_released = False

    prepared_runtime_released = job.prepared_runtime_lease is None
    if runtime_deleted and job.prepared_runtime_lease is not None:
        try:
            state.prepared_runtime_cache.release(job.prepared_runtime_lease)
            job.prepared_runtime_lease = None
            prepared_runtime_released = True
        except Exception:
            prepared_runtime_released = False

    output_execution_root_deleted = job.output_execution_root is None
    if (
        runtime_deleted
        and job.output_actions_quiesced.is_set()
        and job.output_execution_root is not None
    ):
        execution_root = job.output_execution_root
        expected_parent = state.runtime_dir / ".interface-output-executions"
        try:
            linked = execution_root.lstat()
            if (
                execution_root.parent != expected_parent
                or execution_root.is_symlink()
                or not stat.S_ISDIR(linked.st_mode)
            ):
                raise RuntimeError("Output execution root identity changed.")
            shutil.rmtree(execution_root)
            output_execution_root_deleted = not execution_root.exists()
            if output_execution_root_deleted:
                job.output_execution_root = None
        except FileNotFoundError:
            output_execution_root_deleted = True
            job.output_execution_root = None
        except Exception:
            output_execution_root_deleted = False

    cleaned = (
        runtime_deleted
        and presentation_closed
        and session_retired
        and source_projection_released
        and prepared_runtime_released
        and output_execution_root_deleted
    )
    result = {
        "cleaned": cleaned,
        "runtime_terminal_confirmed": True,
        "runtime_deleted": runtime_deleted,
        "presentation_closed": presentation_closed,
        "session_retired": session_retired,
        "source_projection_released": source_projection_released,
        "prepared_runtime_released": prepared_runtime_released,
        "output_execution_root_deleted": output_execution_root_deleted,
    }
    if not presentation_closed:
        result["error"] = "presentation_close_failed"
    elif not runtime_deleted:
        result["error"] = "runtime_delete_failed"
    elif not session_retired:
        result["error"] = "output_session_retire_failed"
    elif not source_projection_released:
        result["error"] = "source_projection_release_failed"
    elif not prepared_runtime_released:
        result["error"] = "prepared_runtime_release_failed"
    elif not output_execution_root_deleted:
        result["error"] = "output_execution_cleanup_failed"
    return result


def _cleanup_interface_prepared_runtime_builders(
    state: UiState,
    launch_id: str,
    job: UiLaunchJob,
) -> JsonDict:
    """Stop and remove every cache-builder runtime owned by one launch."""

    with state._lock:
        builders = {
            builder_id: dict(workspace)
            for builder_id, workspace in job.prepared_runtime_builders.items()
        }
    results: List[JsonDict] = []
    all_cleaned = True
    for builder_id, workspace in builders.items():
        runtime_dir = state.workspace_runtime._workspace_runtime_dir(builder_id)
        cleaned = not runtime_dir.exists()
        if not cleaned:
            try:
                _mark_prestart_interface_runtime_terminal(state, workspace)
                deleted = state.workspace_runtime.delete(builder_id)
                cleaned = bool(deleted) or not runtime_dir.exists()
            except Exception:
                cleaned = False
        if cleaned:
            with state._lock:
                current = state.interface_launches.get(launch_id)
                if current is job:
                    current.prepared_runtime_builders.pop(builder_id, None)
        else:
            all_cleaned = False
        results.append({"runtime_id": builder_id, "cleaned": cleaned})
    return {"cleaned": all_cleaned, "builders": results}


def _finalize_transient_interface_launch(
    state: UiState,
    launch_id: str,
    workspace: JsonDict,
    port: int,
) -> JsonDict:
    """Quiesce, capture, delete, then retire one transient launch."""

    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        return _cleanup_transient_interface_runtime(state, workspace, port)
    if not job.execution_quiesced.is_set():
        return {
            "cleaned": False,
            "runtime_terminal_confirmed": False,
            "runtime_deleted": False,
            "presentation_closed": False,
            "session_retired": False,
            "error": "launch_worker_active",
        }
    if not job.output_actions_quiesced.is_set():
        return {
            "cleaned": False,
            "runtime_terminal_confirmed": False,
            "runtime_deleted": False,
            "presentation_closed": False,
            "session_retired": False,
            "error": "output_action_execution_active",
        }
    with job.cleanup_lock:
        workspace_id = str(workspace.get("id") or "")
        runtime_dir = state.workspace_runtime._workspace_runtime_dir(workspace_id)
        job.output_watcher_stop.set()

        has_runtime_record = state.workspace_runtime._record_path(
            workspace_id
        ).is_file()
        terminal_confirmed = not has_runtime_record
        if has_runtime_record:
            record = state.workspace_runtime._read_record(workspace_id)
            terminal_confirmed = _workspace_runtime_record_proves_terminal(record)
            if not terminal_confirmed:
                try:
                    state.workspace_runtime.stop(workspace)
                    stopped_record = state.workspace_runtime._read_record(workspace_id)
                    terminal_confirmed = _workspace_runtime_record_proves_terminal(
                        stopped_record
                    )
                except Exception:
                    terminal_confirmed = False
        if not terminal_confirmed:
            return {
                "cleaned": False,
                "runtime_terminal_confirmed": False,
                "runtime_deleted": False,
                "presentation_closed": False,
                "session_retired": False,
                "error": "runtime_stop_unconfirmed",
            }

        watcher = job.output_watcher
        if watcher is not None and watcher is not threading.current_thread():
            watcher.join(timeout=10)
            if watcher.is_alive():
                return {
                    "cleaned": False,
                    "runtime_terminal_confirmed": True,
                    "runtime_deleted": False,
                    "presentation_closed": False,
                    "session_retired": False,
                    "error": "output_capture_in_progress",
                }

        builder_cleanup = _cleanup_interface_prepared_runtime_builders(
            state, launch_id, job
        )
        if not builder_cleanup["cleaned"]:
            # The main interface is terminal, but a builder can still hold the
            # source projection or prepared entry mounted.  Preserve all
            # borrowed resources until that runtime is proven absent.
            with job.output_capture_lock:
                _capture_interface_outputs_once(state, launch_id)
                _retain_interface_launch_logs(job)
            presentation_closed = True
            try:
                presentation_closed = bool(
                    state._stop_workspace_preview_proxy(
                        f"{workspace_id}:{int(port)}"
                    )
                )
            except Exception:
                presentation_closed = False
            return {
                "cleaned": False,
                "runtime_terminal_confirmed": True,
                "runtime_deleted": False,
                "presentation_closed": presentation_closed,
                "session_retired": job.output_session is None,
                "source_projection_released": job.source_projection is None,
                "prepared_runtime_released": job.prepared_runtime_lease is None,
                "prepared_runtime_builders": builder_cleanup,
                "error": "prepared_runtime_builder_cleanup_failed",
            }

        with job.output_capture_lock:
            result = _finish_transient_interface_cleanup(
                state,
                launch_id,
                job,
                workspace_id,
                runtime_dir,
                port,
            )
        result["prepared_runtime_builders"] = builder_cleanup
        return result


def _interface_launch_by_id(state: UiState, launch_id: str) -> JsonDict:
    with state._lock:
        job = state.interface_launches.get(launch_id)
        snapshot = job.public_snapshot() if job is not None else None
    if job is None:
        service = _interface_output_service(state)
        if service is None:
            raise KeyError(launch_id)
        try:
            handle = service.recover_session(launch_id=launch_id)
            statuses = service.list_statuses(handle=handle)
        except (RealmConflict, RealmNotFound):
            raise KeyError(launch_id) from None
        for status in statuses:
            generation = status.ready_generation
            if generation is None or generation.selection is None:
                continue
            action = _interface_output_workspace_action(state, generation)
            if action is not None and action.state in {
                ActionState.PENDING,
                ActionState.UNCERTAIN,
            }:
                _reconcile_interface_output_workspace_action(
                    state, generation, action
                )
        # Transient process/presentation data is intentionally not recreated.
        # This bounded recovery view exists so a browser refresh or Studio
        # restart can reconcile durable output save receipts before forgetting
        # the obsolete launch coordinate.
        return {
            "launch_id": launch_id,
            "kind": "interface",
            "uid": "",
            "label": "Previous interface",
            "port": 0,
            "profile_id": "",
            "status": "stopped",
            "started_at": handle.session.created_at,
            "updated_at": handle.session.updated_at,
            "finished_at": handle.session.updated_at,
            "steps": [],
            "result": {
                "outputs": [
                    _public_interface_output_status(state, item) for item in statuses
                ]
            },
            "error": "",
            "launch_scope": "retired",
            "can_stop": False,
            "recovered": True,
            "actions": {
                "capture_output_tree": {
                    "supported": True,
                    "eligible": False,
                    "code": "launch_stopped",
                    "reason": "The interface has stopped.",
                    "kind": "tree",
                }
            },
        }
    assert snapshot is not None
    payload = _render_interface_launch_public_snapshot(snapshot)
    payload["actions"] = {
        "capture_output_tree": _interface_output_tree_capability(state, job)
    }
    return payload


def _keep_run_selection_as_ui_workspace(
    state: UiState,
    *,
    operation_id: str,
    selection: SelectionRef,
    title: str,
    description: str,
) -> JsonDict:
    """Keep one Candidate tree through Core's source-aware selection action."""

    runtime = _require_realm_runtime(state)
    kept = runtime.selection_actions.keep_as_editable_workspace(
        operation_id=operation_id,
        selection=selection,
        title=title,
    )
    if not kept.eligibility.eligible or kept.workspace is None:
        raise RealmConflict(
            "Edit in Workspace is unavailable for this Candidate: "
            f"{kept.eligibility.code}."
        )
    receipt = kept.workspace
    workspace_id = receipt.workspace.workspace_id
    summary = runtime.editable_workspaces.read_workspace(
        workspace_id=workspace_id
    )
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"{operation_id}/open-checkout",
        workspace_id=workspace_id,
        expected_workspace_revision=summary.workspace_revision,
    )
    existing = next(
        (
            item
            for item in _read_workspace_index(state)
            if item.get("id") == workspace_id
        ),
        None,
    )
    workspace_payload = _managed_workspace_ui_payload(
        summary,
        checkout,
        existing=existing,
    )
    workspace_payload["description"] = description
    workspace = _create_ui_workspace(state, workspace_payload)
    return {
        "workspace": workspace,
        "keep": {
            "ownership": "realm-managed",
            "persistence": "reopenable",
            "workspace_id": workspace_id,
            "workspace_revision": summary.workspace_revision,
            "source_digest": request_digest(
                {
                    "schema": "optpilot.selection-workspace-derivation.v1",
                    "selection": selection.to_dict(),
                    "workspace_id": workspace_id,
                }
            ),
        },
    }


def _keep_selection_as_ui_workspace(
    state: UiState,
    *,
    operation_id: str,
    selection: SelectionRef,
    title: str,
    description: str,
) -> JsonDict:
    """Keep any eligible tree selection through the one managed-workspace path."""

    runtime = _require_realm_runtime(state)
    created = runtime.editable_workspaces.create_workspace(
        operation_id=operation_id,
        title=title,
        seed=WorkspaceSelectionSeed.build(
            (WorkspaceRequestSource.build(selection=selection),)
        ),
    )
    summary = runtime.editable_workspaces.read_workspace(
        workspace_id=created.workspace_id
    )
    checkout = runtime.editable_workspaces.open_workspace(
        operation_id=f"{operation_id}/open-checkout",
        workspace_id=created.workspace_id,
        expected_workspace_revision=summary.workspace_revision,
    )
    existing = next(
        (
            item
            for item in _read_workspace_index(state)
            if item.get("id") == created.workspace_id
        ),
        None,
    )
    workspace_payload = _managed_workspace_ui_payload(
        summary,
        checkout,
        existing=existing,
    )
    workspace_payload["description"] = description
    workspace = _create_ui_workspace(state, workspace_payload)
    return {
        "workspace": workspace,
        "keep": {
            "ownership": "realm-managed",
            "persistence": "reopenable",
            "workspace_id": created.workspace_id,
            "workspace_revision": summary.workspace_revision,
            "assembly_digest": created.assembly_digest,
            "assembly_outcome": created.outcome,
        },
    }


def _replay_interface_output_workspace_action(
    state: UiState, action: ActionIntentRecord
) -> Optional[JsonDict]:
    if action.state is not ActionState.SUCCEEDED:
        return None
    result = action.result
    receipt = action.core_receipt
    if (
        result is None
        or result.kind != "workspace"
        or not isinstance(receipt, Mapping)
        or not isinstance(receipt.get("keep"), Mapping)
    ):
        raise RealmIntegrityError(
            "The saved interface-output Workspace receipt is incomplete."
        )
    workspace = _workspace_by_id(state, result.entity_id)
    if workspace is None or workspace.get("reopen_required"):
        # The durable Workspace is authoritative; a checkout is only a local
        # realization and may legitimately disappear across Studio restarts.
        workspace = _reopen_managed_workspace(state, result.entity_id, {})
    return {
        "workspace": workspace,
        "keep": dict(receipt["keep"]),
    }


def _complete_interface_output_workspace_action(
    state: UiState,
    *,
    action: ActionIntentRecord,
    created: Mapping[str, Any],
) -> ActionIntentRecord:
    workspace = created.get("workspace")
    keep = created.get("keep")
    if not isinstance(workspace, Mapping) or not isinstance(keep, Mapping):
        raise RealmIntegrityError(
            "Workspace creation did not return a durable Keep receipt."
        )
    workspace_id = str(keep.get("workspace_id") or "")
    revision = keep.get("workspace_revision")
    digest = keep.get("assembly_digest")
    if (
        not workspace_id
        or workspace_id != str(workspace.get("id") or "")
        or isinstance(revision, bool)
        or not isinstance(revision, int)
        or revision <= 0
        or not isinstance(digest, str)
    ):
        raise RealmIntegrityError("Workspace creation returned an invalid receipt.")
    return state.coordination.complete_action(
        operation_id=f"studio/action/{action.intent_id}/complete",
        intent_id=action.intent_id,
        result=EntityCoordinate(
            kind="workspace",
            entity_id=workspace_id,
            revision=revision,
            digest=digest,
        ),
        core_receipt={
            "keep": dict(keep),
            "workspace_title": str(workspace.get("title") or "Workspace"),
        },
    )


def _mark_interface_output_workspace_action_uncertain(
    state: UiState, action: ActionIntentRecord, error: BaseException
) -> None:
    try:
        current = state.coordination.get_action(action.intent_id)
        state.coordination.mark_action_uncertain(
            operation_id=(
                f"studio/action/{action.intent_id}/uncertain/{current.revision}"
            ),
            intent_id=action.intent_id,
            message=(
                "Workspace save did not return a confirmed receipt; retry will "
                "reconcile the same operation."
            ),
        )
    except Exception:
        # Preserve the original failure at the HTTP boundary.  A later Retry
        # can still re-read a pending/succeeded action and the idempotent Core
        # operation; this best-effort transition is not the creation authority.
        _ = error


def _reconcile_interface_output_workspace_action(
    state: UiState, generation: Any, action: ActionIntentRecord
) -> ActionIntentRecord:
    """Finish an already-authorized save after an interrupted Studio request."""

    if action.state is ActionState.SUCCEEDED:
        return action
    if action.state not in {ActionState.PENDING, ActionState.UNCERTAIN}:
        return action
    selection = generation.selection
    if selection is None:
        return action
    action = _begin_interface_output_workspace_action(state, generation)
    try:
        created = _keep_selection_as_ui_workspace(
            state,
            operation_id=action.core_operation_id,
            selection=selection,
            title=generation.label,
            description="Realm-managed workspace kept from an interface output",
        )
        return _complete_interface_output_workspace_action(
            state,
            action=action,
            created=created,
        )
    except Exception as error:
        _mark_interface_output_workspace_action_uncertain(state, action, error)
        return state.coordination.get_action(action.intent_id)


def _keep_interface_output_as_workspace(
    state: UiState,
    launch_id: str,
    output_id: str,
    *,
    request_id: Any,
) -> JsonDict:
    # This remains part of the strict HTTP request contract, but the immutable
    # output coordinate below is the durable save identity.
    _canonical_request_uuid(request_id)
    runtime = _require_realm_runtime(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    with job.output_capture_lock:
        handle = job.output_session
        if handle is None:
            raise RealmConflict(
                "The interface output session is closed; keep an output before stopping the interface."
            )
        status = runtime.ledger.read_interface_output_status(
            actor_principal_id=runtime.actor_principal_id,
            session_id=handle.session.session_id,
            output_id=output_id,
        )
        if status.state is not InterfaceOutputGenerationState.READY:
            raise RealmConflict("The interface output is not ready to keep.")
        generation = status.ready_generation
        assert generation is not None
        selection = generation.selection
        if selection is None:
            raise RealmConflict("The interface output has no keepable selection.")
        existing_action = _interface_output_workspace_action(state, generation)
        replay = (
            _replay_interface_output_workspace_action(state, existing_action)
            if existing_action is not None
            else None
        )
        if replay is not None:
            result = replay
        else:
            opened = runtime.selection_actions.open_read_only(selection=selection)
            if not opened.eligibility.eligible:
                raise RealmConflict(
                    "Keep as Workspace is unavailable for this output: "
                    f"{opened.eligibility.code}."
                )
            action = _begin_interface_output_workspace_action(state, generation)
            try:
                result = _keep_selection_as_ui_workspace(
                    state,
                    operation_id=action.core_operation_id,
                    selection=selection,
                    title=generation.label,
                    description="Realm-managed workspace kept from an interface output",
                )
                action = _complete_interface_output_workspace_action(
                    state,
                    action=action,
                    created=result,
                )
            except Exception as error:
                _mark_interface_output_workspace_action_uncertain(
                    state, action, error
                )
                raise
    result["output"] = _public_interface_output_status(state, status, job=job)
    return result


def _view_interface_output(
    state: UiState,
    launch_id: str,
    output_id: str,
    *,
    requested_session_id: Optional[str],
) -> JsonDict:
    """Open one live interface result through the shared bounded viewer."""

    if not _selection_content_provider_available(state):
        raise RealmConflict("Selection content provider is unavailable.")
    runtime = _require_realm_runtime(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    with job.output_capture_lock:
        handle = job.output_session
        if handle is None:
            raise RealmConflict(
                "The interface output session is closed; view an output before "
                "stopping the interface."
            )
        status = runtime.ledger.read_interface_output_status(
            actor_principal_id=runtime.actor_principal_id,
            session_id=handle.session.session_id,
            output_id=output_id,
        )
        if status.state is not InterfaceOutputGenerationState.READY:
            raise RealmConflict("The interface output is not ready to view.")
        generation = status.ready_generation
        assert generation is not None
        selection = generation.selection
        if selection is None:
            raise RealmConflict("The interface output has no viewable selection.")
        media_type = (
            "application/vnd.optpilot.tree"
            if generation.kind is InterfaceOutputKind.TREE
            else mimetypes.guess_type(status.relative_path)[0]
            or "application/octet-stream"
        )
        return {
            "content_view": _open_exact_selection_content_view(
                state,
                run_id=f"interface:{launch_id}",
                public_selection={
                    "kind": selection.kind,
                    "entity_id": selection.entity_id,
                    "revision": selection.source_revision,
                    "sequence": selection.source_sequence,
                },
                selection=selection,
                requested_session_id=requested_session_id,
                media_type=media_type,
            )
        }


def _retry_interface_output_capture(
    state: UiState, launch_id: str, output_id: str
) -> JsonDict:
    runtime = _require_realm_runtime(state)
    service = _interface_output_service(state)
    if service is None:
        raise RealmConflict("Interface output capture is unavailable.")
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    with job.output_capture_lock:
        handle = job.output_session
        if handle is None:
            raise RealmConflict("The interface output session is closed.")
        status = runtime.ledger.read_interface_output_status(
            actor_principal_id=runtime.actor_principal_id,
            session_id=handle.session.session_id,
            output_id=output_id,
        )
        if status.state is not InterfaceOutputGenerationState.FAILED:
            raise RealmConflict("Only a failed interface output can be retried.")
        _control_file, root_handles = _interface_output_paths(job)
        service.capture_generation(
            handle=handle,
            record=status.record,
            root_handles=root_handles,
        )
    statuses = _refresh_interface_output_statuses(state, launch_id)
    output = next((item for item in statuses if item.get("id") == output_id), None)
    return {"launch": _interface_launch_by_id(state, launch_id), "output": output}


def _run_ready_interface_output_action(
    state: UiState,
    launch_id: str,
    output_id: str,
    action_id: str,
    payload: JsonDict,
) -> JsonDict:
    """Queue one authored action for an exact ready tree output."""

    optional_timeout = (
        {"timeout_seconds"}
        if isinstance(payload, Mapping) and "timeout_seconds" in payload
        else set()
    )
    request_payload = _exact_json_object(
        payload,
        expected={
            "schema_version",
            "request_id",
            "arguments",
            *optional_timeout,
        },
        label="Interface output action request",
    )
    if request_payload["schema_version"] != _INTERFACE_OUTPUT_ACTION_HTTP_SCHEMA:
        raise ValueError("Interface output action request schema is unsupported.")
    if not isinstance(request_payload["arguments"], list):
        raise ValueError("Interface output action arguments must be a list.")
    request = InterfaceOutputExecutionRequest(
        request_id=request_payload["request_id"],
        action_id=action_id,
        output_path=".",
        arguments=tuple(request_payload["arguments"]),
        timeout_seconds=request_payload.get("timeout_seconds"),
    )
    runtime = _require_realm_runtime(state)
    with state._lock:
        job = state.interface_launches.get(launch_id)
    if job is None:
        raise KeyError(launch_id)
    with job.output_capture_lock:
        handle = job.output_session
        if handle is None:
            raise RealmConflict("The interface output session is closed.")
        status = runtime.ledger.read_interface_output_status(
            actor_principal_id=runtime.actor_principal_id,
            session_id=handle.session.session_id,
            output_id=output_id,
        )
        if status.state is not InterfaceOutputGenerationState.READY:
            raise RealmConflict("The interface output is not ready to run.")
        generation = status.ready_generation
        assert generation is not None
        if (
            generation.kind is not InterfaceOutputKind.TREE
            or not isinstance(generation.content_ref, SnapshotRef)
            or generation.selection is None
        ):
            raise RealmConflict("Only a ready folder output can be run.")
        action = _interface_output_action_for_job(job, action_id)
        capability, _executions = _interface_output_execution_capability(
            job,
            output_id=output_id,
            kind="tree",
            output_state="ready",
        )
        selected_capability = next(
            (
                item
                for item in capability.get("items", [])
                if item.get("id") == action_id
            ),
            None,
        )
        if (
            not capability.get("eligible")
            or not isinstance(selected_capability, Mapping)
            or not selected_capability.get("eligible")
        ):
            raise RealmConflict(
                str(
                    capability.get("reason")
                    or "This output action is not currently available."
                )
            )
        selection = generation.selection
        snapshot_ref = generation.content_ref

    def source_factory() -> tuple[ImmutableInterfaceOutputTree, Callable[[], None]]:
        coordinate = uuid.uuid4().hex
        projection = runtime.projection_service.project_selection_read_only(
            operation_id=(
                f"studio/interface-output-action/{launch_id}/"
                f"{request.request_id}/{coordinate}"
            ),
            actor_principal_id=runtime.actor_principal_id,
            selection=selection,
            holder_id=f"studio-output-action-{coordinate}",
            ttl_seconds=float(action.timeout_seconds + 90),
            consumer_kind="interface-output-execution",
            consumer_metadata={
                "launch_id": launch_id,
                "output_id": output_id,
                "action_id": action_id,
                "request_id": request.request_id,
            },
        )
        try:
            source = ImmutableInterfaceOutputTree(
                snapshot_ref=snapshot_ref,
                root_path=projection.root_path,
            )
        except Exception:
            projection.close()
            raise
        return source, projection.close

    _schedule_interface_output_action(
        state,
        job,
        request,
        output_id=output_id,
        source_factory=source_factory,
    )
    outputs = _refresh_interface_output_statuses(state, launch_id)
    output = next(
        (item for item in outputs if item.get("id") == output_id),
        None,
    )
    with state._lock:
        execution = deepcopy(
            job.output_action_executions.get(request.request_id) or {}
        )
    return {
        "launch": _interface_launch_by_id(state, launch_id),
        "output": output,
        "execution": _public_interface_output_execution(execution, job=job),
    }


def _settle_interface_launch(
    state: UiState,
    launch_id: str,
    *,
    terminal_target: str,
) -> JsonDict:
    """Settle one quiesced launch through the single destructive boundary."""

    return_current = False
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            raise KeyError(launch_id)
        if (
            not job.execution_quiesced.is_set()
            or not job.output_actions_quiesced.is_set()
        ):
            return_current = True
    if return_current:
        return _interface_launch_by_id(state, launch_id)

    with job.cleanup_lock:
        return_current = False
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is None:
                raise KeyError(launch_id)
            existing_cleanup = current.result.get("cleanup")
            if current.status in {"stopped", "failed"} and isinstance(
                existing_cleanup, dict
            ) and existing_cleanup.get("cleaned"):
                return_current = True
                workspace = {}
                port = int(current.port)
            else:
                workspace = dict(current.runtime_workspace)
                port = int(current.port)
                if current.stop_requested:
                    terminal_target = "stopped"
                current.terminal_target = terminal_target
        if return_current:
            return _interface_launch_by_id(state, launch_id)
        try:
            # A pre-start record can be sealed only after the execution frame
            # that could submit container work has completely unwound.
            _mark_prestart_interface_runtime_terminal(state, workspace)
            cleanup = _finalize_transient_interface_launch(
                state, launch_id, workspace, port
            )
        except Exception as error:
            try:
                diagnostic = repr(error)
            except Exception:
                diagnostic = type(error).__name__
            cleanup = {
                "cleaned": False,
                "runtime_terminal_confirmed": False,
                "runtime_deleted": False,
                "presentation_closed": False,
                "session_retired": False,
                "source_projection_released": False,
                "prepared_runtime_released": False,
                "error": "cleanup_failed",
            }
            with state._lock:
                current = state.interface_launches.get(launch_id)
                if current is not None:
                    suffix = f"cleanup: {diagnostic}"
                    current.private_error = (
                        f"{current.private_error}\n{suffix}".strip()
                    )
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is None:
                raise KeyError(launch_id)
            target = "stopped" if current.stop_requested else current.terminal_target
            cleaned = bool(cleanup.get("cleaned"))
            current.status = target if cleaned else "cleanup_pending"
            current.updated_at = time.time()
            current.finished_at = time.time()
            current.result = {**current.result, "cleanup": cleanup}
            if not cleaned:
                current.error_code = "interface_cleanup_pending"
                current.error = (
                    "Execution has ended, but cleanup could not yet be proven "
                    "complete. Retry Stop."
                )
            elif target == "stopped":
                current.error = ""
                current.error_code = ""
            else:
                current.error_code = (
                    current.terminal_error_code or "interface_launch_failed"
                )
                current.error = current.terminal_error or (
                    "The interface could not be started. "
                    "Review the bounded launch log for details."
                )
            title = (
                "Interface stopped"
                if cleaned and target == "stopped"
                else "Launch failed"
                if cleaned
                else "Interface cleanup pending"
            )
            detail = (
                "Closed Preview and removed the launch-scoped runtime."
                if cleaned and target == "stopped"
                else current.error
                if cleaned
                else current.error
            )
            current.steps.append(
                {
                    "time": _now_iso(),
                    "status": current.status,
                    "title": title,
                    "detail": detail,
                }
            )
            current.steps = current.steps[-80:]
    return _interface_launch_by_id(state, launch_id)


def _mark_interface_output_action_cancellations(job: UiLaunchJob) -> None:
    """Publish launch-owned cancellation markers without following links."""

    root = job.output_action_root
    if root is None:
        return
    try:
        cancellation_fd = _open_interface_output_action_directory(
            job, "cancellations"
        )
    except (OSError, RealmConflict):
        return
    for request_id in tuple(job.output_action_threads):
        try:
            descriptor = os.open(
                request_id,
                os.O_WRONLY
                | os.O_CREAT
                | os.O_EXCL
                | getattr(os, "O_CLOEXEC", 0)
                | getattr(os, "O_NOFOLLOW", 0),
                0o600,
                dir_fd=cancellation_fd,
            )
            os.close(descriptor)
        except FileExistsError:
            # The interface may already have requested cancellation.
            continue
        except OSError:
            # The in-memory stop fence remains authoritative even when the
            # untrusted broker directory was changed.
            continue
    try:
        os.fsync(cancellation_fd)
    except OSError:
        pass
    finally:
        os.close(cancellation_fd)


def _request_interface_launch_stop(
    state: UiState, launch_id: str
) -> tuple[threading.Event, bool]:
    """Publish a stop request without waiting for provider cleanup."""

    already_stopped = False
    cancellation_job: Optional[UiLaunchJob] = None
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            raise KeyError(launch_id)
        if job.launch_scope not in {"catalog-transient", "workspace-transient"}:
            raise ValueError("This interface does not own a launch-scoped runtime.")
        job.output_watcher_stop.set()
        cancellation_job = job
        if job.status == "stopped":
            already_stopped = True
            quiesced = job.execution_quiesced
        else:
            job.stop_requested = True
            job.status = "stopping"
            job.finished_at = None
            job.updated_at = time.time()
            job.terminal_target = "stopped"
            if not any(
                step.get("title") == "Stop requested" for step in job.steps[-4:]
            ):
                job.steps.append(
                    {
                        "time": _now_iso(),
                        "status": "stopping",
                        "title": "Stop requested",
                        "detail": (
                            "Waiting for active setup or runtime startup work to "
                            "reach a safe cleanup boundary."
                        ),
                    }
                )
                job.steps = job.steps[-80:]
            quiesced = job.execution_quiesced
    if cancellation_job is not None:
        _mark_interface_output_action_cancellations(cancellation_job)
    return quiesced, already_stopped


def _stop_interface_launch(state: UiState, launch_id: str) -> JsonDict:
    quiesced, already_stopped = _request_interface_launch_stop(state, launch_id)
    if already_stopped:
        return _interface_launch_by_id(state, launch_id)
    # Keep HTTP Stop responsive. The worker will settle itself when a slow
    # image build or setup command returns; until then no owned resource is
    # deleted and the truthful public state remains ``stopping``.
    if not quiesced.wait(timeout=0.25):
        return _interface_launch_by_id(state, launch_id)
    with state._lock:
        job = state.interface_launches.get(launch_id)
        actions_quiesced = (
            job.output_actions_quiesced if job is not None else None
        )
    if actions_quiesced is not None and not actions_quiesced.wait(timeout=0.25):
        return _interface_launch_by_id(state, launch_id)
    return _settle_interface_launch(
        state,
        launch_id,
        terminal_target="stopped",
    )


def _resource_action_blocked_reason(
    state: UiState, resource_uid: str, action_id: str
) -> str:
    """Why this action cannot run right now, or empty if it can.

    Same purpose as the interface check beside it: a person should not be asked
    to approve something already known to fail. One conversation approved the
    same generation action six times in four minutes, every run failing for
    three values that were never set.
    """

    try:
        manifest_path = _resolve_resource_action_source(state, resource_uid)
        with manifest_path.open("r", encoding="utf-8") as handle:
            raw = yaml.safe_load(handle) or {}
        actions = compile_resource_actions(raw, location=str(manifest_path))
        action = find_resource_action(actions, action_id)
    except Exception:
        # A genuine lookup problem is reported by the run itself, in its own
        # words; this check only answers "would the environment stop it?".
        return ""
    _resolved, missing = _resolve_declared_env_from_host(
        state, (*action.env_from_host, *action.secrets_from_host)
    )
    if not missing:
        return ""
    joined = ", ".join(missing)
    return (
        f"Add {joined} in Studio Settings or export "
        f"{'them' if len(missing) != 1 else 'it'} before running this action."
    )


def _interface_launch_blocked_reason(state: UiState, kind: str, uid: str) -> str:
    """Why this interface cannot launch right now, or empty if it can.

    Reads the same answer the Catalog page shows, so the two cannot disagree
    about the same component.
    """

    try:
        detail = _catalog_detail(state, kind, uid)
    except Exception:
        return ""
    entry = detail.get("entry") if isinstance(detail.get("entry"), dict) else {}
    summary = entry.get("summary") if isinstance(entry.get("summary"), dict) else {}
    interface = summary.get("interface") if isinstance(summary.get("interface"), dict) else {}
    actions = interface.get("actions") if isinstance(interface.get("actions"), dict) else {}
    launch = actions.get("launch") if isinstance(actions.get("launch"), dict) else {}
    if not launch or launch.get("eligible"):
        return ""
    return str(launch.get("reason") or "This interface cannot be launched yet.")


def _start_catalog_interface_launch(
    state: UiState,
    kind: str,
    uid: str,
    *,
    profile_id: Optional[str] = None,
) -> JsonDict:
    if kind == "study":
        raise ValueError("Study configs do not declare launchable interfaces.")
    # Preserve catalog-coordinate authorization even when the runtime is down.
    # Exact Realm refs are validated by their signed logical fields below;
    # legacy/local identifiers must first resolve inside a configured root.
    if _catalog_entry_ref_from_value(state, kind, uid) is None:
        _resolve_catalog_identifier(state, kind, uid)
    # Every currently supported interface uses the shared isolated Workspace
    # runtime. Reject before borrowing an exact Catalog projection or creating
    # any transient launch state.
    _require_interface_launch_runtime(state)
    source_projection = _borrow_catalog_entry_ref_projection(
        state,
        kind,
        uid,
        consumer_kind="catalog-interface",
        consumer_metadata={"component_kind": kind},
    )
    source_path = (
        source_projection.source_path
        if source_projection is not None
        else _resolve_catalog_identifier(state, kind, uid)
    )
    if source_projection is None:
        source_projection = _borrow_realm_catalog_source_projection(
            state,
            source_path,
            consumer_kind="catalog-interface",
            consumer_metadata={"component_kind": kind},
        )
    action_uid = (
        _encode_id(source_projection.source_path)
        if source_projection is not None
        else _encode_id(source_path)
    )
    try:
        profiles = _component_interface_profiles_for_uid(kind, action_uid)
        profile = _select_launchable_interface_profile(state, profiles, profile_id)
        profile_capability = _interface_profile_launch_capability(state, profile)
        if not profile_capability.get("eligible"):
            raise ValueError(str(profile_capability["reason"]))
        declared_host_env = _require_declared_env_from_host(
            state,
            _interface_launch_env_requirements(profile),
            action="interface launch",
        )
        launch_id = f"launch-{uuid.uuid4().hex[:12]}"
        runtime_workspace, _raw, _label = _catalog_interface_runtime_descriptor(
            state,
            kind,
            action_uid,
            launch_id,
            catalog_root=(
                source_projection.root_path if source_projection is not None else None
            ),
            resolved_source_path=source_path,
        )
    except Exception:
        if source_projection is not None:
            source_projection.close()
        raise
    job = UiLaunchJob(
        launch_id=launch_id,
        kind=kind,
        uid=uid,
        label=profile.label,
        port=profile.presentation.port,
        profile_id=profile.profile_id,
        outputs_enabled=profile.outputs,
        interface_profile=profile,
        launch_scope="catalog-transient",
        runtime_workspace=runtime_workspace,
        source_projection=source_projection,
        public_path_redactions=_interface_launch_public_path_redactions(
            state, runtime_workspace
        ),
        public_secret_redactions={
            declared_host_env[name]
            for name in profile.grants.secrets_from_host
            if declared_host_env.get(name)
        },
    )
    job.steps.append(
        {
            "time": _now_iso(),
            "status": "queued",
            "title": "Queued launch",
            "detail": "Preparing a read-only catalog source with an isolated writable runtime.",
        }
    )
    worker = threading.Thread(
        target=_run_catalog_interface_launch,
        args=(
            state,
            launch_id,
            kind,
            action_uid,
            profile.profile_id,
            runtime_workspace,
        ),
        daemon=True,
    )
    job.worker_thread = worker
    with state._lock:
        state.interface_launches[launch_id] = job
    worker.start()
    return {"launch": _interface_launch_by_id(state, launch_id)}


def _start_workspace_interface_launch(
    state: UiState,
    workspace_id: str,
    *,
    setup_policy: str = "auto",
    profile_id: Optional[str] = None,
) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    kind, config_path, _raw, profiles = _workspace_interface_config(state, workspace)
    profile = _select_launchable_interface_profile(state, profiles, profile_id)
    profile_capability = _interface_profile_launch_capability(state, profile)
    if not profile_capability.get("eligible"):
        if profile_capability.get("code") == "interface_runtime_unavailable":
            raise InterfaceLaunchRuntimeUnavailable(
                str(profile_capability["reason"])
            )
        raise ValueError(str(profile_capability["reason"]))
    declared_host_env = _require_declared_env_from_host(
        state,
        _interface_launch_env_requirements(profile),
        action="interface launch",
    )
    launch_id = f"launch-{uuid.uuid4().hex[:12]}"
    runtime_workspace = _workspace_interface_runtime_descriptor(
        state, workspace, launch_id
    )
    label = profile.label or f"{kind} interface"
    workspace_root = Path(str(workspace["root"])).resolve()
    config_relative = config_path.resolve().relative_to(workspace_root).as_posix()
    job = UiLaunchJob(
        launch_id=launch_id,
        kind=kind,
        uid=f"workspace://{workspace_id}/{config_relative}",
        label=label,
        port=profile.presentation.port,
        profile_id=profile.profile_id,
        outputs_enabled=profile.outputs,
        interface_profile=profile,
        launch_scope="workspace-transient",
        source_workspace_id=workspace_id,
        runtime_workspace=runtime_workspace,
        public_path_redactions=_interface_launch_public_path_redactions(
            state, runtime_workspace
        ),
        public_secret_redactions={
            declared_host_env[name]
            for name in profile.grants.secrets_from_host
            if declared_host_env.get(name)
        },
    )
    job.steps.append(
        {
            "time": _now_iso(),
            "status": "queued",
            "title": "Queued launch",
            "detail": (
                "Preparing a launch-scoped runtime over the existing editable "
                "workspace tree."
            ),
        }
    )
    worker = threading.Thread(
        target=_run_workspace_interface_launch,
        args=(
            state,
            launch_id,
            workspace_id,
            setup_policy,
            profile.profile_id,
            runtime_workspace,
        ),
        daemon=True,
    )
    job.worker_thread = worker
    with state._lock:
        state.interface_launches[launch_id] = job
    worker.start()
    return {"launch": _interface_launch_by_id(state, launch_id)}


def _run_catalog_interface_launch(
    state: UiState,
    launch_id: str,
    kind: str,
    uid: str,
    profile_id: Optional[str] = None,
    runtime_workspace: Optional[JsonDict] = None,
) -> None:
    with state._lock:
        launch_job = state.interface_launches.get(launch_id)
        runtime_handles = launch_job.runtime_handles if launch_job is not None else {}
    result: JsonDict = {}
    failure: Optional[BaseException] = None
    try:
        result = _launch_catalog_interface(
            state,
            kind,
            uid,
            profile_id=profile_id,
            launch_id=launch_id,
            runtime_workspace=runtime_workspace,
            resolved_source_path=(
                Path(str(runtime_workspace.get("source_path") or ""))
                if isinstance(runtime_workspace, dict)
                and runtime_workspace.get("source_path")
                else None
            ),
            runtime_handles=runtime_handles,
            should_stop=lambda: _interface_launch_stop_requested(state, launch_id),
            progress=lambda title, detail="", status="running", data=None: (
                _record_interface_launch_step(
                    state,
                    launch_id,
                    title,
                    detail,
                    status=status,
                    data=data,
                )
            ),
        )
    except Exception as exc:  # pragma: no cover - defensive background boundary
        failure = exc
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            return
        if failure is not None:
            job.private_error = repr(failure)
            code, message = _public_interface_launch_failure(failure)
            job.error_code = code
            job.error = message
            job.failure_detail = _interface_launch_failure_detail(failure)
            job.terminal_error_code = code
            job.terminal_error = message
            job.terminal_target = "failed"
            # Publish the terminal fence before the first cleanup attempt. If
            # an output action is still active, settlement will wait for it,
            # but no later request may enter the closing launch.
            job.status = "stopping"
            job.output_watcher_stop.set()
        job.execution_quiesced.set()
        should_settle = job.stop_requested or failure is not None
        if not should_settle:
            job.status = "ready"
            output_state = {
                key: value
                for key, value in job.result.items()
                if key in {"outputs", "output_capture_error", "output_record_errors"}
            }
            job.result = {**result, **output_state}
            job.updated_at = time.time()
            job.finished_at = time.time()
            job.steps.append(
                {
                    "time": _now_iso(),
                    "status": "ready",
                    "title": "Preview ready",
                    "detail": f"Interface is reachable on port {job.port}.",
                }
            )
            job.steps = job.steps[-80:]
            job.worker_done.set()
            return
    try:
        _settle_interface_launch(
            state,
            launch_id,
            terminal_target="failed" if failure is not None else "stopped",
        )
    finally:
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not None:
                current.worker_done.set()


def _interface_launch_stop_requested(state: UiState, launch_id: str) -> bool:
    with state._lock:
        job = state.interface_launches.get(launch_id)
        return bool(job and job.stop_requested)


def _run_workspace_interface_launch(
    state: UiState,
    launch_id: str,
    workspace_id: str,
    setup_policy: str,
    profile_id: Optional[str] = None,
    runtime_workspace: Optional[JsonDict] = None,
) -> None:
    with state._lock:
        launch_job = state.interface_launches.get(launch_id)
        runtime_handles = launch_job.runtime_handles if launch_job is not None else {}
    result: JsonDict = {}
    failure: Optional[BaseException] = None
    try:
        result = _launch_workspace_interface(
            state,
            workspace_id,
            setup_policy=setup_policy,
            profile_id=profile_id,
            launch_id=launch_id,
            runtime_workspace=runtime_workspace,
            runtime_handles=runtime_handles,
            should_stop=lambda: _interface_launch_stop_requested(state, launch_id),
            progress=lambda title, detail="", status="running", data=None: (
                _record_interface_launch_step(
                    state,
                    launch_id,
                    title,
                    detail,
                    status=status,
                    data=data,
                )
            ),
        )
    except Exception as exc:  # pragma: no cover - defensive background boundary
        failure = exc
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            return
        if failure is not None:
            job.private_error = repr(failure)
            code, message = _public_interface_launch_failure(failure)
            job.error_code = code
            job.error = message
            job.failure_detail = _interface_launch_failure_detail(failure)
            job.terminal_error_code = code
            job.terminal_error = message
            job.terminal_target = "failed"
            # Publish the terminal fence before the first cleanup attempt. If
            # an output action is still active, settlement will wait for it,
            # but no later request may enter the closing launch.
            job.status = "stopping"
            job.output_watcher_stop.set()
        job.execution_quiesced.set()
        should_settle = job.stop_requested or failure is not None
        if not should_settle:
            job.status = "ready"
            output_state = {
                key: value
                for key, value in job.result.items()
                if key in {"outputs", "output_capture_error", "output_record_errors"}
            }
            job.result = {**result, **output_state}
            job.updated_at = time.time()
            job.finished_at = time.time()
            port = result.get("interface", {}).get("port") or job.port
            job.steps.append(
                {
                    "time": _now_iso(),
                    "status": "ready",
                    "title": "Preview ready",
                    "detail": f"Interface is reachable on port {port}.",
                }
            )
            job.steps = job.steps[-80:]
            job.worker_done.set()
            return
    try:
        _settle_interface_launch(
            state,
            launch_id,
            terminal_target="failed" if failure is not None else "stopped",
        )
    finally:
        with state._lock:
            current = state.interface_launches.get(launch_id)
            if current is not None:
                current.worker_done.set()


def _record_interface_launch_step(
    state: UiState,
    launch_id: str,
    title: str,
    detail: str = "",
    *,
    status: str = "running",
    data: Optional[JsonDict] = None,
) -> None:
    with state._lock:
        job = state.interface_launches.get(launch_id)
        if job is None:
            return
        if job.status in {"queued", "running"}:
            job.status = "running" if status != "failed" else "failed"
        if data:
            stdout_log = str(data.get("stdout_log") or "")
            stderr_log = str(data.get("stderr_log") or "")
            if stdout_log:
                job.log_paths["stdout"] = stdout_log
                job.public_path_redactions.add(str(Path(stdout_log).parent))
            if stderr_log:
                job.log_paths["stderr"] = stderr_log
                job.public_path_redactions.add(str(Path(stderr_log).parent))
        job.updated_at = time.time()
        step: JsonDict = {
            "time": _now_iso(),
            "status": status,
            "title": title,
        }
        if detail:
            step["detail"] = detail
        job.steps.append(step)
        job.steps = job.steps[-80:]


def _launch_log_tail(log_paths: JsonDict, *, max_chars: int = 4000) -> JsonDict:
    logs: JsonDict = {}
    for name in ("stdout", "stderr"):
        path = str(log_paths.get(name) or "")
        if not path:
            continue
        log_path = Path(path)
        # The container may write this directory, so neither an existence
        # check nor Path.open() is a sufficient authority boundary.  Open the
        # exact manager-provided basename relative to its no-follow parent.
        text = _read_log_file_tail(
            log_path,
            max_chars=max_chars,
            owned_root=log_path.parent,
        )
        if text:
            logs[name] = text
    return logs


def _redact_interface_public_text(
    text: str,
    *,
    path_redactions: Iterable[str],
    secret_redactions: Iterable[str],
) -> str:
    """Remove private coordinates and granted secrets from browser text."""

    result = str(text)
    private_paths = {
        str(value)
        for value in path_redactions
        if value is not None
        and str(value)
        and str(value) not in {"/", ".", ".."}
    }
    for value in sorted(private_paths, key=len, reverse=True):
        result = result.replace(value, "[private]")
    secrets = {
        str(value)
        for value in secret_redactions
        if value is not None and str(value)
    }
    for value in sorted(secrets, key=len, reverse=True):
        if value not in result:
            continue
        # Replacing a one-character token throughout a diagnostic can expand
        # it catastrophically and still disclose the token through a careless
        # placeholder.  Withhold that whole string instead.  Longer secrets
        # are removed without a marker whose own text might equal the secret.
        if len(value) < 4 or value in {"/", ".", ".."}:
            return ""
        result = result.replace(value, "")
    return result


def _redact_interface_public_value(
    value: Any,
    *,
    path_redactions: Iterable[str],
    secret_redactions: Iterable[str],
) -> Any:
    """Recursively redact browser-facing launch diagnostics."""

    if isinstance(value, Mapping):
        return {
            str(key): _redact_interface_public_value(
                child,
                path_redactions=path_redactions,
                secret_redactions=secret_redactions,
            )
            for key, child in value.items()
        }
    if isinstance(value, list):
        return [
            _redact_interface_public_value(
                child,
                path_redactions=path_redactions,
                secret_redactions=secret_redactions,
            )
            for child in value
        ]
    if isinstance(value, tuple):
        return [
            _redact_interface_public_value(
                child,
                path_redactions=path_redactions,
                secret_redactions=secret_redactions,
            )
            for child in value
        ]
    if isinstance(value, str):
        return _redact_interface_public_text(
            value,
            path_redactions=path_redactions,
            secret_redactions=secret_redactions,
        )
    return value


def _render_interface_launch_public_snapshot(snapshot: JsonDict) -> JsonDict:
    """Render one immutable job snapshot without holding the Studio lock."""

    raw = dict(snapshot)
    log_paths = dict(raw.pop("_log_paths", {}) or {})
    retained_logs = dict(raw.pop("_retained_logs", {}) or {})
    path_redactions = tuple(raw.pop("_path_redactions", ()) or ())
    secret_redactions = tuple(raw.pop("_secret_redactions", ()) or ())
    failure_detail = str(raw.pop("_failure_detail", "") or "")
    payload = _redact_interface_public_value(
        raw,
        path_redactions=path_redactions,
        secret_redactions=secret_redactions,
    )
    if failure_detail:
        public_detail = _redact_interface_public_text(
            failure_detail,
            path_redactions=path_redactions,
            secret_redactions=secret_redactions,
        ).strip()
        if public_detail:
            payload["error_detail"] = public_detail[-1000:]
    logs = _launch_log_tail(log_paths) or retained_logs
    if logs:
        payload["logs"] = _redact_interface_public_value(
            logs,
            path_redactions=path_redactions,
            secret_redactions=secret_redactions,
        )
    return payload


def _interface_launch_public_path_redactions(
    state: UiState,
    workspace: Mapping[str, Any],
) -> set[str]:
    """Collect private provider coordinates separately from secret values."""

    values = {
        str(state.cwd),
        str(state.runtime_dir),
        str(state.prepared_runtime_cache_dir),
    }
    for key in (
        "root",
        "source_root",
        "source_path",
        "_prepared_runtime_entry",
    ):
        value = str(workspace.get(key) or "")
        if value:
            values.add(value)
    return values


def _public_interface_launch_failure(
    error: BaseException,
) -> tuple[str, str]:
    """Return a stable browser error without provider diagnostics."""

    message = str(error).lower()
    if "stopped" in message or "cancel" in message:
        return "launch_stopped", ""
    if isinstance(error, InterfaceLaunchProcessExited):
        return (
            "interface_process_exited",
            "The interface process exited with code "
            f"{error.exit_code} before it became ready.",
        )
    if isinstance(error, InterfaceLaunchReadinessTimeout):
        return (
            "interface_not_reachable",
            "The interface process kept running but did not become reachable "
            f"within {error.timeout_seconds}s.",
        )
    if "readiness" in message or "reachable" in message or "preview port" in message:
        return (
            "interface_not_reachable",
            "The interface started but did not become reachable before the timeout.",
        )
    if "setup" in message or "prepared runtime" in message:
        return (
            "interface_setup_failed",
            "Interface setup failed. Review the bounded launch log for details.",
        )
    if "container" in message or "runtime image" in message or "docker" in message:
        return (
            "interface_runtime_failed",
            "The isolated interface runtime could not be prepared.",
        )
    return (
        "interface_launch_failed",
        "The interface could not be started. Review the bounded launch log for details.",
    )


def _interface_launch_failure_detail(error: BaseException) -> str:
    """Return one bounded process diagnostic for redaction at render time."""

    if not isinstance(error, InterfaceLaunchProcessExited):
        return ""
    lines = [line.strip() for line in error.diagnostic.splitlines() if line.strip()]
    if not lines:
        return ""
    # The final stderr line normally carries the actionable exception while
    # the complete, separately bounded log remains available under Show log.
    return lines[-1][-1000:]


def _read_log_file_tail(
    path: Path,
    *,
    max_chars: int,
    owned_root: Optional[Path] = None,
) -> str:
    """Read a bounded regular-file tail through a no-follow directory handle."""

    if max_chars <= 0 or not hasattr(os, "O_NOFOLLOW"):
        return ""
    absolute = Path(os.path.abspath(path.expanduser()))
    root = Path(os.path.abspath((owned_root or absolute.parent).expanduser()))
    try:
        relative = absolute.relative_to(root)
    except ValueError:
        return ""
    if not relative.parts or any(part in {"", ".", ".."} for part in relative.parts):
        return ""
    directory_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
        | os.O_NOFOLLOW
    )
    file_flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | os.O_NOFOLLOW
    descriptors: List[int] = []
    try:
        directory_fd = os.open(root, directory_flags)
        descriptors.append(directory_fd)
        if not stat.S_ISDIR(os.fstat(directory_fd).st_mode):
            return ""
        for component in relative.parts[:-1]:
            next_fd = os.open(component, directory_flags, dir_fd=directory_fd)
            descriptors.append(next_fd)
            directory_fd = next_fd
            if not stat.S_ISDIR(os.fstat(directory_fd).st_mode):
                return ""
        file_fd = os.open(relative.parts[-1], file_flags, dir_fd=directory_fd)
        descriptors.append(file_fd)
        opened = os.fstat(file_fd)
        if not stat.S_ISREG(opened.st_mode):
            return ""
        byte_count = os.lseek(file_fd, 0, os.SEEK_END)
        os.lseek(file_fd, max(0, byte_count - (max_chars * 4)), os.SEEK_SET)
        data = os.read(file_fd, max_chars * 4)
    except (OSError, ValueError):
        return ""
    finally:
        for descriptor in reversed(descriptors):
            try:
                os.close(descriptor)
            except OSError:
                pass
    return data.decode("utf-8", errors="replace")[-max_chars:]


def _retain_interface_launch_logs(job: UiLaunchJob) -> None:
    """Keep bounded diagnostics before launch-scoped files are removed."""

    logs = _launch_log_tail(job.log_paths, max_chars=12_000)
    if logs:
        job.retained_logs = logs


def _require_workspace_interface_runtime(
    profile: InterfaceLaunchProfile,
) -> None:
    if profile.runtime.sandbox == "container":
        raise ValueError(
            f"Interface profile {profile.profile_id!r} requires its declared "
            "container runtime. Studio's editable-workspace launcher cannot "
            "substitute its generic launch-scoped sibling runtime; use a process "
            "profile or launch it through a contextual Operator Preview provider."
        )


def _public_catalog_interface_setup(setup: JsonDict) -> JsonDict:
    public_results: List[JsonDict] = []
    for raw_result in setup.get("results", []) or []:
        if not isinstance(raw_result, dict):
            continue
        public_results.append(
            {
                "label": str(raw_result.get("label") or ""),
                "ran": bool(raw_result.get("ran")),
                "steps": [
                    {"returncode": int(step.get("returncode") or 0)}
                    for step in raw_result.get("steps", []) or []
                    if isinstance(step, dict)
                ],
            }
        )
    result: JsonDict = {"ran": bool(setup.get("ran"))}
    if public_results:
        result["results"] = public_results
    if setup.get("skipped"):
        result["skipped"] = True
    if setup.get("reason"):
        result["reason"] = str(setup["reason"])
    cache = setup.get("cache")
    if isinstance(cache, dict):
        result["cache"] = {
            key: cache.get(key)
            for key in (
                "enabled",
                "status",
                "key",
                "scope",
                "readOnlyAtRuntime",
            )
            if cache.get(key) not in (None, "")
        }
    return result


def _public_catalog_interface_launch(launch: JsonDict) -> JsonDict:
    runtime = launch.get("runtime") if isinstance(launch.get("runtime"), dict) else {}
    return {
        "name": str(launch.get("name") or "interface"),
        "started_at": launch.get("started_at"),
        "returncode": launch.get("returncode"),
        "runtime": {
            key: runtime.get(key)
            for key in (
                "status",
                "containerized",
                "executor",
                "engine",
                "image",
                "container_name",
                "mount_mode",
                "host",
                "port",
                "url",
            )
            if runtime.get(key) not in (None, "")
        },
    }


def _public_catalog_interface_preview(preview: JsonDict) -> JsonDict:
    return {
        key: preview.get(key)
        for key in (
            "workspace_id",
            "port",
            "preview_url",
            "proxy",
            "allowed_ports",
            "readiness",
        )
        if preview.get(key) not in (None, "")
    }


def _launch_catalog_interface(
    state: UiState,
    kind: str,
    uid: str,
    progress: Optional[Any] = None,
    profile_id: Optional[str] = None,
    launch_id: Optional[str] = None,
    runtime_workspace: Optional[JsonDict] = None,
    runtime_handles: Optional[JsonDict] = None,
    should_stop: Optional[Any] = None,
    resolved_source_path: Optional[Path] = None,
) -> JsonDict:
    def report(
        title: str,
        detail: str = "",
        status: str = "running",
        data: Optional[JsonDict] = None,
    ) -> None:
        if progress:
            progress(title, detail, status, data)

    if kind == "study":
        raise ValueError("Study configs do not declare launchable interfaces.")
    source_path = (
        resolved_source_path.resolve(strict=True)
        if resolved_source_path is not None
        else _resolve_catalog_identifier(state, kind, uid)
    )
    if resolved_source_path is not None and not _is_authorized_catalog_realization_path(
        state, source_path
    ):
        raise PermissionError("Catalog interface source is not authorized.")
    resolved_uid = _encode_id(source_path)
    report("Reading interface config", f"Loading {kind} interface declaration.")
    profiles = _component_interface_profiles_for_uid(kind, resolved_uid)
    profile = _select_interface_profile(profiles, profile_id)
    _require_workspace_interface_runtime(profile)
    selected_launch_id = str(launch_id or f"launch-{uuid.uuid4().hex[:12]}")
    with state._lock:
        launch_job = state.interface_launches.get(selected_launch_id)
    catalog_root = (
        launch_job.source_projection.root_path
        if launch_job is not None and launch_job.source_projection is not None
        else None
    )
    expected_workspace, raw, label = _catalog_interface_runtime_descriptor(
        state,
        kind,
        resolved_uid,
        selected_launch_id,
        catalog_root=catalog_root,
        resolved_source_path=source_path,
    )
    workspace = dict(runtime_workspace or expected_workspace)
    for key in ("id", "root", "source_root", "mode", "source_type"):
        if workspace.get(key) != expected_workspace.get(key):
            raise ValueError(
                f"Catalog interface runtime descriptor has an invalid {key}."
            )
    root = Path(str(workspace["root"])).resolve()
    source_root = _workspace_source_root(workspace)
    cwd = (source_root / profile.cwd).resolve()
    if not _is_relative_to(cwd, source_root):
        raise ValueError("Interface cwd must stay inside the read-only catalog source.")
    port = profile.presentation.port
    command = list(profile.command)
    env = {str(key): str(value) for key, value in profile.env.items() if str(key)}
    env["HOST"] = "0.0.0.0"
    env["PORT"] = str(port)
    env["OPTPILOT_INTERFACE_PORT"] = str(port)
    env["OPTPILOT_WORKSPACE_ROOT"] = str(root)
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    env.update(
        _require_declared_env_from_host(
            state,
            _interface_launch_env_requirements(profile),
            action="interface launch",
        )
    )
    report(
        "Preparing transient runtime",
        "Mounting the catalog source read-only and creating launch-scoped writable handles.",
    )

    def check_stopped() -> None:
        if should_stop and should_stop():
            raise RuntimeError("Interface launch was stopped.")

    lifecycle = launch_job.cleanup_lock if launch_job is not None else nullcontext()

    try:
        with lifecycle:
            check_stopped()
            launch_env = _prepare_transient_interface_runtime_handles(
                state,
                workspace,
                outputs_enabled=profile.outputs,
                output_actions_enabled=bool(profile.output_actions),
            )
            if runtime_handles is not None:
                runtime_handles.clear()
                runtime_handles.update(launch_env)
            if launch_job is not None:
                _begin_interface_output_session(state, selected_launch_id)
        env.update(launch_env)
        report(
            "Starting isolated runtime",
            "Starting a container whose only writable storage belongs to this interface launch.",
        )
        setup_result = _run_component_setup_in_workspace_runtime(
            state,
            workspace,
            raw,
            source_root,
            report,
            profile=profile,
            launch_env=launch_env,
            should_stop=should_stop,
        )
        # Cached setup may add the stable prepared-runtime handle after the
        # launch-scoped environment was first assembled.
        env.update(launch_env)
        with lifecycle:
            check_stopped()
            launch = state.workspace_runtime.exec_detached(
                workspace,
                command,
                cwd=cwd,
                env=env,
                name="interface",
                should_stop=should_stop,
            )
        report(
            "Launch command started",
            "Interface stdout and stderr are being captured.",
            data=launch,
        )
        with lifecycle:
            check_stopped()
            preview = (
                state.transient_workspace_preview_open(
                    workspace,
                    port,
                    extra_ports=profile.presentation.extra_ports,
                )
                if should_stop is None
                else state.transient_workspace_preview_open(
                    workspace,
                    port,
                    extra_ports=profile.presentation.extra_ports,
                    should_stop=should_stop,
                )
            )
        report(
            "Opening preview proxy",
            f"Routing interface port {port} through Studio Preview.",
        )
        report(
            "Waiting for preview port",
            f"Checking {profile.presentation.readiness.path} until the interface becomes reachable.",
        )
        readiness = _wait_for_preview_ready(
            str(preview.get("proxy_target") or ""),
            profile.presentation.readiness.path,
            profile.presentation.readiness.timeout_seconds,
            should_stop=should_stop,
            launch=launch,
        )
        preview["readiness"] = readiness
        check_stopped()
        if not readiness.get("ready") and not readiness.get("skipped"):
            raise _preview_readiness_failure(port, readiness)
        runtime_result: JsonDict = {
            "scope": "launch",
            "runtime_id": str(workspace["id"]),
            "source_mount": "read-only",
            "writable_scope": "launch-only",
        }
        if profile.outputs:
            runtime_result["output_protocol"] = "optpilot.interface.output.v1"
        return {
            "source": {
                "kind": kind,
                "id": str(raw.get("id") or raw.get("name") or label),
                "label": label,
                "mode": "read-only",
            },
            "runtime": runtime_result,
            "interface": _safe_interface_profile_summary(profile),
            "setup": _public_catalog_interface_setup(setup_result),
            "launch": _public_catalog_interface_launch(launch),
            "preview": _public_catalog_interface_preview(preview),
        }
    except Exception:
        # The tracked worker owns settlement after this call has completely
        # unwound. It is unsafe to release projections or runtime files here
        # while Stop may be racing this frame.
        if launch_job is None:
            _mark_prestart_interface_runtime_terminal(state, workspace)
            _cleanup_transient_interface_runtime(state, workspace, port)
        raise


def _workspace_interface_setup_result(
    state: UiState,
    source_workspace: JsonDict,
    raw: JsonDict,
    source_root: Path,
    profile: InterfaceLaunchProfile,
    setup_policy: str,
    report: Any,
    *,
    runtime_workspace: Optional[JsonDict] = None,
    launch_env: Optional[Dict[str, str]] = None,
    should_stop: Optional[Callable[[], bool]] = None,
) -> JsonDict:
    _check_interface_launch_cancelled(should_stop)
    policy = str(setup_policy or "auto").strip().lower()
    if policy not in {"auto", "always", "skip"}:
        raise ValueError("setup must be one of: auto, always, skip")
    if not _component_setup_specs(raw, profile=profile):
        return {"ran": False, "skipped": True, "reason": "No setup declared."}
    if policy == "skip":
        return {
            "ran": False,
            "skipped": True,
            "reason": "Setup skipped for workspace relaunch.",
        }
    # A sibling launch has a fresh runtime namespace and private ephemeral
    # dependency root.  A successful setup recorded on the source workspace is
    # diagnostic history, not proof that this runtime contains those outputs.
    # Until a prepared-runtime identity exists, auto must prepare every launch.
    setup_result = _run_component_setup_in_workspace_runtime(
        state,
        runtime_workspace or source_workspace,
        raw,
        source_root,
        report,
        profile=profile,
        launch_env=launch_env,
        should_stop=should_stop,
    )
    refreshed = dict(_require_ui_workspace(state, str(source_workspace["id"])))
    refreshed["setup"] = setup_result
    _upsert_ui_workspace(state, refreshed)
    return setup_result


def _launch_workspace_interface(
    state: UiState,
    workspace_id: str,
    *,
    setup_policy: str = "auto",
    progress: Optional[Any] = None,
    profile_id: Optional[str] = None,
    launch_id: Optional[str] = None,
    runtime_workspace: Optional[JsonDict] = None,
    runtime_handles: Optional[JsonDict] = None,
    should_stop: Optional[Any] = None,
) -> JsonDict:
    def report(
        title: str,
        detail: str = "",
        status: str = "running",
        data: Optional[JsonDict] = None,
    ) -> None:
        if progress:
            progress(title, detail, status, data)

    source_workspace = _require_ui_workspace(state, workspace_id)
    selected_launch_id = str(launch_id or "")
    if not selected_launch_id:
        raise ValueError(
            "Workspace interfaces must be started as a tracked interface launch."
        )
    expected_runtime_workspace = _workspace_interface_runtime_descriptor(
        state, source_workspace, selected_launch_id
    )
    workspace = dict(runtime_workspace or expected_runtime_workspace)
    for key in (
        "id",
        "root",
        "source_root",
        "mode",
        "source_type",
        "source_workspace_id",
    ):
        if workspace.get(key) != expected_runtime_workspace.get(key):
            raise ValueError(
                f"Workspace interface runtime descriptor has an invalid {key}."
            )
    root = Path(str(workspace["root"])).resolve()
    report(
        "Reading interface config",
        "Loading the launchable interface from the workspace config.",
    )
    kind, config_path, raw, profiles = _workspace_interface_config(
        state, source_workspace
    )
    profile = _select_interface_profile(profiles, profile_id)
    _require_workspace_interface_runtime(profile)
    validation = validate_authoring_config(config_path)
    if validation and not validation.get("valid"):
        raise ValueError(
            "Workspace config validation failed: "
            + "; ".join(
                str(error)
                for error in validation.get("errors", []) or ["invalid config"]
            )
        )
    # A Workspace may contain a whole package while the selected interface
    # belongs to one nested Environment, Method, or Resource.  Keep mounting
    # the complete editable Workspace, but resolve setup and the launch cwd
    # from that component's source root just as a Catalog launch does.
    source_root = _catalog_component_source_root(kind, config_path, raw).resolve()
    if not _is_relative_to(source_root, root):
        raise ValueError(
            "Interface component source must stay inside the editable workspace."
        )
    cwd = (source_root / profile.cwd).resolve()
    if not _is_relative_to(cwd, source_root):
        raise ValueError("Interface cwd must stay inside its component source.")
    port = profile.presentation.port
    command = list(profile.command)
    env = {str(key): str(value) for key, value in profile.env.items() if str(key)}
    env["HOST"] = "0.0.0.0"
    env["PORT"] = str(port)
    env["OPTPILOT_INTERFACE_PORT"] = str(port)
    env["OPTPILOT_WORKSPACE_ROOT"] = str(root)
    env.update(
        _require_declared_env_from_host(
            state,
            _interface_launch_env_requirements(profile),
            action="interface launch",
        )
    )
    report(
        "Preparing transient runtime",
        "Mounting the existing editable workspace read-write in a separate launch runtime.",
    )

    def check_stopped() -> None:
        if should_stop and should_stop():
            raise RuntimeError("Interface launch was stopped.")

    with state._lock:
        launch_job = state.interface_launches.get(selected_launch_id)
    if launch_job is None or launch_job.launch_scope != "workspace-transient":
        raise ValueError("Workspace interface launch ownership is unavailable.")
    lifecycle = launch_job.cleanup_lock

    try:
        with lifecycle:
            check_stopped()
            launch_env = _prepare_transient_interface_runtime_handles(
                state,
                workspace,
                outputs_enabled=profile.outputs,
                output_actions_enabled=bool(profile.output_actions),
            )
            if runtime_handles is not None:
                runtime_handles.clear()
                runtime_handles.update(launch_env)
            _begin_interface_output_session(state, selected_launch_id)
        env.update(launch_env)
        report(
            "Starting isolated runtime",
            "Starting the interface in its launch-scoped sibling runtime.",
        )
        setup_result = _workspace_interface_setup_result(
            state,
            source_workspace,
            raw,
            source_root,
            profile,
            setup_policy,
            report,
            runtime_workspace=workspace,
            launch_env=launch_env,
            should_stop=should_stop,
        )
        with lifecycle:
            check_stopped()
            launch = state.workspace_runtime.exec_detached(
                workspace,
                command,
                cwd=cwd,
                env=env,
                name="interface",
                should_stop=should_stop,
            )
        report(
            "Launch command started",
            "Interface stdout and stderr are being captured.",
            data=launch,
        )
        with lifecycle:
            check_stopped()
            preview = (
                state.transient_workspace_preview_open(
                    workspace,
                    port,
                    extra_ports=profile.presentation.extra_ports,
                )
                if should_stop is None
                else state.transient_workspace_preview_open(
                    workspace,
                    port,
                    extra_ports=profile.presentation.extra_ports,
                    should_stop=should_stop,
                )
            )
        report(
            "Opening preview proxy",
            f"Routing interface port {port} through Studio Preview.",
        )
        report(
            "Waiting for preview port",
            f"Checking {profile.presentation.readiness.path} until the interface becomes reachable.",
        )
        readiness = _wait_for_preview_ready(
            str(preview.get("proxy_target") or ""),
            profile.presentation.readiness.path,
            profile.presentation.readiness.timeout_seconds,
            should_stop=should_stop,
            launch=launch,
        )
        preview["readiness"] = readiness
        check_stopped()
        if not readiness.get("ready") and not readiness.get("skipped"):
            raise _preview_readiness_failure(port, readiness)
        refreshed_workspace = _require_ui_workspace(state, str(source_workspace["id"]))
        runtime_result: JsonDict = {
            "scope": "launch",
            "runtime_id": str(workspace["id"]),
            "source_workspace_id": str(source_workspace["id"]),
            "source_mount": "read-write",
            "writable_scope": (
                "workspace-and-launch-output" if profile.outputs else "workspace"
            ),
        }
        if profile.outputs:
            runtime_result["output_protocol"] = "optpilot.interface.output.v1"
        return {
            "workspace": refreshed_workspace,
            "runtime": runtime_result,
            "interface": _safe_interface_profile_summary(profile),
            "setup": setup_result,
            "launch": launch,
            "preview": preview,
        }
    except Exception:
        # Settlement belongs to the tracked worker after this frame unwinds.
        raise


def _catalog_interface_for_uid(kind: str, uid: str) -> JsonDict:
    return _interface_summary(_component_interface_profiles_for_uid(kind, uid))


def _component_interface_profiles_for_uid(
    kind: str,
    uid: str,
) -> List[InterfaceLaunchProfile]:
    if kind == "resource":
        resource_root = _decode_id(uid).resolve()
        if not resource_root.exists() or not resource_root.is_dir():
            raise FileNotFoundError(f"resource not found: {resource_root}")
        raw = _resource_catalog_entry(resource_root).get("raw_config", {})
        return _compile_component_interface_profiles(
            raw.get("interface"),
            component_kind="resource",
        )
    config_path = _decode_id(uid)
    raw = _read_yaml(config_path)
    if raw.get("config") != kind or raw.get("apiVersion") != AUTHORING_API_VERSION:
        raise FileNotFoundError(f"{kind} config not found: {config_path}")
    return _compile_component_interface_profiles(
        raw.get("interface"),
        component_kind=kind,
    )


def _discover_workspace_configs(state: UiState, workspace_id: str) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    root = Path(str(workspace["root"])).resolve()
    _safe_workspace_root(state, root)
    return {
        "workspace": workspace,
        "configs": _discover_workspace_package_configs(root),
    }


#: Where a headless resource action writes its results inside a Workspace.
#: A generated simulator lands in resource-action-output/<request>/<name>/,
#: not at the Workspace root, so a bundle is looked for there too.
_RESOURCE_ACTION_OUTPUT_DIRNAME = "resource-action-output"


def _generated_simulation_bundle_root(root: Path) -> Optional[Path]:
    """Where this Workspace's generated simulator lives, if it holds one.

    The Workspace root wins, so a hand-placed bundle behaves as before.
    Otherwise the one bundle a generate action wrote is used: without this,
    setup silently fell back to generic starter files and the declared
    policy hook never became an optimizable environment -- the exact seam
    between generating a simulator and optimizing it.

    Ambiguity is never guessed at: several bundles means the person says
    which, because picking one would quietly register the wrong simulator.
    """

    if (root / "simulation.json").is_file():
        return root
    outputs = root / _RESOURCE_ACTION_OUTPUT_DIRNAME
    if not outputs.is_dir():
        return None
    candidates: List[Path] = []
    try:
        for request_dir in sorted(outputs.iterdir()):
            if not request_dir.is_dir():
                continue
            for child in sorted(request_dir.iterdir()):
                if child.is_dir() and (child / "simulation.json").is_file():
                    candidates.append(child)
    except OSError:
        return None
    if len(candidates) == 1:
        return candidates[0]
    if len(candidates) > 1:
        named = ", ".join(
            str(item.relative_to(root)) for item in candidates[:6]
        )
        raise ValueError(
            "This Workspace holds more than one generated simulator "
            f"({named}). Keep the one to register and remove the rest, or "
            "register them from separate Workspaces."
        )
    return None


def _workspace_simulation_handoff(root: Path) -> Optional[JsonDict]:
    """Read the portable generated-simulation manifest without importing code."""

    manifest_path = root / "simulation.json"
    try:
        metadata = manifest_path.lstat()
    except FileNotFoundError:
        return None
    if (
        stat.S_ISLNK(metadata.st_mode)
        or not stat.S_ISREG(metadata.st_mode)
        or metadata.st_size > 64 * 1024
    ):
        raise ValueError(
            "simulation.json must be a regular JSON file no larger than 64 KiB."
        )
    try:
        def unique_object(pairs: List[tuple[str, Any]]) -> JsonDict:
            result: JsonDict = {}
            for key, value in pairs:
                if key in result:
                    raise ValueError(f"simulation.json repeats the key {key!r}.")
                result[key] = value
            return result

        def reject_constant(value: str) -> None:
            raise ValueError(
                f"simulation.json contains a non-finite number: {value}."
            )

        document = json.loads(
            manifest_path.read_text(encoding="utf-8"),
            object_pairs_hook=unique_object,
            parse_constant=reject_constant,
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ValueError(f"Cannot read simulation.json: {exc}") from exc
    if (
        not isinstance(document, dict)
        or document.get("schema_version")
        not in GENERATED_SIMULATION_SCHEMA_VERSIONS
        or document.get("entrypoint") != "run.py"
    ):
        raise ValueError(
            "simulation.json must use "
            + " or ".join(sorted(GENERATED_SIMULATION_SCHEMA_VERSIONS))
            + " with entrypoint run.py."
        )
    unexpected_top = sorted(
        set(document)
        - {
            "schema_version",
            "entrypoint",
            "timeout_seconds",
            "arguments",
            "result_files",
            "metrics",
            "policy",
            "python_runtime",
        }
    )
    if unexpected_top:
        raise ValueError(
            "simulation.json has unsupported fields: "
            + ", ".join(unexpected_top)
            + "."
        )
    declared_metrics = _validated_simulation_metrics(document)
    declared_policy = _validated_simulation_policy(document, root)
    runner_path = root / "run.py"
    try:
        runner_metadata = runner_path.lstat()
    except FileNotFoundError as exc:
        raise ValueError("The generated simulation is missing run.py.") from exc
    if stat.S_ISLNK(runner_metadata.st_mode) or not stat.S_ISREG(
        runner_metadata.st_mode
    ):
        raise ValueError("run.py must be a regular file, not a symbolic link.")
    simulator_source = root / "devs_project"
    try:
        simulator_metadata = simulator_source.lstat()
    except FileNotFoundError as exc:
        raise ValueError(
            "The generated simulation is missing its devs_project source directory."
        ) from exc
    if stat.S_ISLNK(simulator_metadata.st_mode) or not stat.S_ISDIR(
        simulator_metadata.st_mode
    ):
        raise ValueError(
            "devs_project must be a regular directory, not a symbolic link."
        )
    python_runtime = document.get("python_runtime")
    if (
        not isinstance(python_runtime, dict)
        or set(python_runtime) != {"requirements_lock"}
    ):
        raise ValueError(
            "simulation.json python_runtime must contain only requirements_lock."
        )
    requirements_lock = python_runtime.get("requirements_lock")
    if (
        not isinstance(requirements_lock, str)
        or not requirements_lock
        or "\\" in requirements_lock
        or "\x00" in requirements_lock
    ):
        raise ValueError(
            "simulation.json python_runtime.requirements_lock is invalid."
        )
    lock_relative = PurePosixPath(requirements_lock)
    if (
        lock_relative.is_absolute()
        or lock_relative.as_posix() != requirements_lock
        or any(part in {"", ".", ".."} for part in lock_relative.parts)
        or len(requirements_lock.encode("utf-8")) > 1024
    ):
        raise ValueError(
            "simulation.json python_runtime.requirements_lock must be a canonical relative path."
        )
    lock_parent = root
    for part in lock_relative.parts[:-1]:
        lock_parent = lock_parent / part
        try:
            parent_metadata = lock_parent.lstat()
        except FileNotFoundError as exc:
            raise ValueError(
                "The generated simulation's Python requirements directory is missing."
            ) from exc
        if stat.S_ISLNK(parent_metadata.st_mode) or not stat.S_ISDIR(
            parent_metadata.st_mode
        ):
            raise ValueError(
                "The generated simulation's Python requirements path may not contain links."
            )
    lock_path = root.joinpath(*lock_relative.parts)
    try:
        lock_metadata = lock_path.lstat()
    except FileNotFoundError as exc:
        raise ValueError(
            "The generated simulation's declared Python requirements lock is missing."
        ) from exc
    if (
        stat.S_ISLNK(lock_metadata.st_mode)
        or not stat.S_ISREG(lock_metadata.st_mode)
        or lock_metadata.st_size > 1024 * 1024
    ):
        raise ValueError(
            "The generated simulation's Python requirements lock must be a regular file no larger than 1 MiB."
        )
    try:
        with lock_path.open("rb") as lock_stream:
            lock_payload = lock_stream.read(1024 * 1024 + 1)
        if len(lock_payload) > 1024 * 1024:
            raise ValueError(
                "The generated simulation's Python requirements lock grew beyond 1 MiB while it was read."
            )
        locked_wheels = parse_locked_python_wheel_lock(lock_payload)
    except (OSError, LockedPythonRuntimeError) as exc:
        raise ValueError(
            f"The generated simulation's Python requirements lock is invalid: {exc}"
        ) from exc
    if len(locked_wheels) > GENERATED_SIMULATION_MAX_RUNTIME_WHEELS:
        raise ValueError(
            "The generated simulation declares too many vendored Python wheels "
            f"(maximum {GENERATED_SIMULATION_MAX_RUNTIME_WHEELS})."
        )
    seen_wheels: set[str] = set()
    checked_wheels: List[tuple[str, str, Path, int]] = []
    total_wheel_bytes = 0
    for wheel_text, expected_digest in locked_wheels:
        if (
            not isinstance(wheel_text, str)
            or not wheel_text
            or "\\" in wheel_text
            or "\x00" in wheel_text
        ):
            raise ValueError("The generated simulation's locked wheel path is invalid.")
        wheel_relative = PurePosixPath(wheel_text)
        if (
            wheel_relative.is_absolute()
            or wheel_relative.as_posix() != wheel_text
            or any(part in {"", ".", ".."} for part in wheel_relative.parts)
            or not re.fullmatch(
                r"[A-Za-z0-9_.]+-[A-Za-z0-9_.!+-]+-(?:py3|py2\.py3)-none-any\.whl",
                wheel_relative.name,
            )
        ):
            raise ValueError(
                "The generated simulation must use canonical vendored pure-Python wheel paths."
            )
        wheel_path = lock_path.parent.joinpath(*wheel_relative.parts)
        wheel_parent = lock_path.parent
        for part in wheel_relative.parts[:-1]:
            wheel_parent = wheel_parent / part
            try:
                parent_metadata = wheel_parent.lstat()
            except FileNotFoundError as exc:
                raise ValueError(
                    f"The generated simulation is missing locked wheel {wheel_text}."
                ) from exc
            if stat.S_ISLNK(parent_metadata.st_mode) or not stat.S_ISDIR(
                parent_metadata.st_mode
            ):
                raise ValueError(
                    "The generated simulation's locked wheel path may not contain links."
                )
        try:
            wheel_metadata = wheel_path.lstat()
        except FileNotFoundError as exc:
            raise ValueError(
                f"The generated simulation is missing locked wheel {wheel_text}."
            ) from exc
        if stat.S_ISLNK(wheel_metadata.st_mode) or not stat.S_ISREG(
            wheel_metadata.st_mode
        ):
            raise ValueError(
                f"The generated simulation's locked wheel is not a regular file: {wheel_text}."
            )
        wheel_size = wheel_metadata.st_size
        if (
            wheel_size < 1
            or wheel_size > GENERATED_SIMULATION_MAX_RUNTIME_WHEEL_BYTES
        ):
            raise ValueError(
                "The generated simulation's locked wheel exceeds the per-file "
                f"limit ({GENERATED_SIMULATION_MAX_RUNTIME_WHEEL_BYTES} bytes): "
                f"{wheel_text}."
            )
        total_wheel_bytes += wheel_size
        if total_wheel_bytes > GENERATED_SIMULATION_MAX_RUNTIME_TOTAL_BYTES:
            raise ValueError(
                "The generated simulation's vendored Python wheels exceed the "
                f"total limit ({GENERATED_SIMULATION_MAX_RUNTIME_TOTAL_BYTES} bytes)."
            )
        wheel_key = wheel_path.relative_to(root).as_posix()
        if wheel_key in seen_wheels:
            raise ValueError(
                "The generated simulation's Python requirements lock repeats a wheel."
            )
        seen_wheels.add(wheel_key)
        checked_wheels.append(
            (wheel_text, expected_digest, wheel_path, wheel_size)
        )

    # Do not hash any dependency bytes until every declaration has passed the
    # count, per-file, and aggregate size checks above.  Hash incrementally so
    # a file that grows after lstat cannot force an unbounded allocation.
    for wheel_text, expected_digest, wheel_path, expected_size in checked_wheels:
        try:
            digest = hashlib.sha256()
            hashed_size = 0
            with wheel_path.open("rb") as wheel_stream:
                while True:
                    chunk = wheel_stream.read(1024 * 1024)
                    if not chunk:
                        break
                    hashed_size += len(chunk)
                    if hashed_size > GENERATED_SIMULATION_MAX_RUNTIME_WHEEL_BYTES:
                        raise ValueError(
                            "The generated simulation's locked wheel grew beyond "
                            f"the per-file limit while it was read: {wheel_text}."
                        )
                    digest.update(chunk)
            if hashed_size != expected_size:
                raise ValueError(
                    "The generated simulation's locked wheel changed while it "
                    f"was inspected: {wheel_text}."
                )
            actual_digest = digest.hexdigest()
        except OSError as exc:
            raise ValueError(
                f"Cannot read the generated simulation's locked wheel {wheel_text}: {exc}"
            ) from exc
        if actual_digest != expected_digest:
            raise ValueError(
                f"The generated simulation's locked wheel hash does not match: {wheel_text}."
            )
    timeout_seconds = document.get("timeout_seconds", 30)
    if (
        type(timeout_seconds) is not int
        or not 1 <= timeout_seconds <= 300
    ):
        raise ValueError(
            "simulation.json timeout_seconds must be an integer from 1 to 300."
        )
    arguments = document.get("arguments", [])
    if not isinstance(arguments, list) or len(arguments) > 64:
        raise ValueError("simulation.json arguments must be an array of at most 64 items.")
    candidate_schema: JsonDict = {}
    for index, argument in enumerate(arguments):
        if not isinstance(argument, dict):
            raise ValueError(f"simulation.json arguments[{index}] must be an object.")
        unexpected_argument = sorted(
            set(argument)
            - {
                "name",
                "flag",
                "type",
                "required",
                "default",
                "minimum",
                "maximum",
                "choices",
                "action",
                "description",
                "label",
            }
        )
        if unexpected_argument:
            raise ValueError(
                f"simulation.json arguments[{index}] has unsupported fields: "
                + ", ".join(unexpected_argument)
                + "."
            )
        name = argument.get("name")
        value_type = argument.get("type")
        if (
            not isinstance(name, str)
            or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", name)
            or name in candidate_schema
        ):
            raise ValueError(
                f"simulation.json arguments[{index}].name is invalid or duplicated."
            )
        if value_type not in {"integer", "number", "boolean", "string"}:
            raise ValueError(
                f"simulation.json arguments[{index}].type is unsupported."
            )
        flag = argument.get("flag", f"--{name}")
        if not isinstance(flag, str) or not re.fullmatch(
            r"--[A-Za-z][A-Za-z0-9_-]{0,63}", flag
        ):
            raise ValueError(
                f"simulation.json arguments[{index}].flag is invalid."
            )
        required = argument.get("required", False)
        if type(required) is not bool:
            raise ValueError(
                f"simulation.json arguments[{index}].required must be boolean."
            )
        action = argument.get("action", "value")
        if action not in {"value", "store_true", "store_false"}:
            raise ValueError(
                f"simulation.json arguments[{index}].action is unsupported."
            )
        if action != "value" and value_type != "boolean":
            raise ValueError(
                f"simulation.json arguments[{index}] flag action requires boolean type."
            )
        choices = argument.get("choices", [])
        if not isinstance(choices, list) or len(choices) > 128:
            raise ValueError(
                f"simulation.json arguments[{index}].choices must be an array."
            )
        minimum = argument.get("minimum")
        maximum = argument.get("maximum")
        for bound_name, bound in (("minimum", minimum), ("maximum", maximum)):
            if bound is not None and (
                type(bound) not in (int, float)
                or not math.isfinite(float(bound))
            ):
                raise ValueError(
                    f"simulation.json arguments[{index}].{bound_name} must be finite."
                )
        if value_type not in {"integer", "number"} and (
            minimum is not None or maximum is not None
        ):
            raise ValueError(
                f"simulation.json arguments[{index}] bounds require a numeric type."
            )
        if (
            minimum is not None
            and maximum is not None
            and minimum > maximum
        ):
            raise ValueError(
                f"simulation.json arguments[{index}] minimum exceeds maximum."
            )

        def validated_scalar(value: Any, field_name: str) -> Any:
            valid = (
                (value_type == "string" and type(value) is str)
                or (value_type == "integer" and type(value) is int)
                or (
                    value_type == "number"
                    and type(value) in (int, float)
                    and math.isfinite(float(value))
                )
                or (value_type == "boolean" and type(value) is bool)
            )
            if not valid:
                raise ValueError(
                    f"simulation.json arguments[{index}].{field_name} "
                    f"does not match type {value_type}."
                )
            if minimum is not None and value < minimum:
                raise ValueError(
                    f"simulation.json arguments[{index}].{field_name} is below minimum."
                )
            if maximum is not None and value > maximum:
                raise ValueError(
                    f"simulation.json arguments[{index}].{field_name} is above maximum."
                )
            return value

        validated_choices = [
            validated_scalar(choice, "choices") for choice in choices
        ]
        if len({json.dumps(item, sort_keys=True) for item in validated_choices}) != len(
            validated_choices
        ):
            raise ValueError(
                f"simulation.json arguments[{index}].choices contains duplicates."
            )
        if "default" in argument:
            default = validated_scalar(argument["default"], "default")
            if validated_choices and default not in validated_choices:
                raise ValueError(
                    f"simulation.json arguments[{index}].default is not an allowed choice."
                )
        if required and "default" in argument:
            raise ValueError(
                f"simulation.json arguments[{index}] cannot be required and have a default."
            )
        for text_field in ("description", "label"):
            text_value = argument.get(text_field)
            if text_value is not None and (
                not isinstance(text_value, str)
                or len(text_value.encode("utf-8")) > 4096
            ):
                raise ValueError(
                    f"simulation.json arguments[{index}].{text_field} is invalid."
                )
        if choices:
            parameter: JsonDict = {
                "valueType": "categorical",
                "values": deepcopy(validated_choices),
            }
        else:
            mapped_type = {
                "integer": "int",
                "number": "float",
                "boolean": "bool",
                "string": "string",
            }.get(value_type)
            if mapped_type is None:
                raise ValueError(
                    f"simulation.json arguments[{index}].type is unsupported."
                )
            parameter = {"valueType": mapped_type}
        if minimum is not None:
            parameter["min"] = minimum
        if maximum is not None:
            parameter["max"] = maximum
        if "default" in argument:
            parameter["default"] = deepcopy(default)
        description = argument.get("description")
        if isinstance(description, str) and description.strip():
            parameter["description"] = description.strip()
        candidate_schema[name] = parameter
    result_files = document.get("result_files", [])
    if not isinstance(result_files, list) or len(result_files) > 128:
        raise ValueError(
            "simulation.json result_files must be an array of at most 128 paths."
        )
    checked_result_files: List[str] = []
    for index, item in enumerate(result_files):
        if not isinstance(item, str) or not item or "\\" in item or "\x00" in item:
            raise ValueError(
                f"simulation.json result_files[{index}] is invalid."
            )
        relative = PurePosixPath(item)
        if (
            relative.is_absolute()
            or relative.as_posix() != item
            or any(part in {"", ".", ".."} for part in relative.parts)
            or len(item.encode("utf-8")) > 1024
        ):
            raise ValueError(
                f"simulation.json result_files[{index}] must be a canonical relative path."
            )
        checked_result_files.append(item)
    if len(set(checked_result_files)) != len(checked_result_files):
        raise ValueError("simulation.json result_files contains duplicate paths.")
    handoff = {
        "schema_version": str(document.get("schema_version")),
        "entrypoint": "run.py",
        "candidate_schema": candidate_schema,
        "parameter_count": len(candidate_schema),
        "result_files": checked_result_files,
        "python_runtime": {
            "requirements_lock": requirements_lock,
            "wheel_count": len(seen_wheels),
        },
    }
    if declared_metrics is not None:
        handoff["metrics"] = declared_metrics
    if declared_policy is not None:
        handoff["policy"] = declared_policy
    return handoff


GENERATED_SIMULATION_SCHEMA_VERSIONS = frozenset(
    {"devs.simulation.v1", "devs.simulation.v2"}
)
_GENERATED_SIMULATION_METRIC_NAME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9_]{0,63}$")
_GENERATED_SIMULATION_MAX_METRICS = 64
_GENERATED_SIMULATION_MAX_METRIC_DESCRIPTION_CHARS = 512


def _validated_simulation_policy(
    document: JsonDict, bundle_root: Path
) -> Optional[JsonDict]:
    """Validate the optional devs.simulation.v2 policy-hook declaration."""

    raw = document.get("policy")
    if raw is None:
        return None
    if document.get("schema_version") == "devs.simulation.v1":
        raise ValueError(
            "simulation.json policy requires schema_version devs.simulation.v2."
        )
    if not isinstance(raw, dict) or not {"file", "entrypoint"} <= set(raw) or not (
        set(raw) <= {"file", "entrypoint", "description"}
    ):
        raise ValueError(
            "simulation.json policy must declare file and entrypoint "
            "(description optional)."
        )
    file_name = raw.get("file")
    entrypoint = raw.get("entrypoint")
    if (
        not isinstance(file_name, str)
        or not file_name.endswith(".py")
        or file_name.startswith("/")
        or ".." in file_name
        or "\\" in file_name
        or "\x00" in file_name
        or not isinstance(entrypoint, str)
        or not entrypoint.isidentifier()
    ):
        raise ValueError("simulation.json policy file or entrypoint is invalid.")
    description = raw.get("description")
    if description is not None and (
        not isinstance(description, str)
        or not description
        or len(description) > 512
    ):
        raise ValueError("simulation.json policy description is invalid.")
    policy_path = bundle_root / file_name
    try:
        resolved = policy_path.resolve(strict=True)
        resolved.relative_to(bundle_root.resolve(strict=True))
        metadata = resolved.lstat()
    except (OSError, ValueError) as exc:
        raise ValueError(
            f"simulation.json declares policy file {file_name!r}, which is "
            "missing from the bundle."
        ) from exc
    if policy_path.is_symlink() or not stat.S_ISREG(metadata.st_mode):
        raise ValueError(
            f"simulation.json policy file {file_name!r} must be a regular file."
        )
    entrypoint_kind = _policy_entrypoint_kind(resolved, entrypoint)
    if entrypoint_kind is None:
        raise ValueError(
            f"simulation.json policy file {file_name!r} does not define the "
            f"declared entrypoint {entrypoint!r} at top level."
        )
    validated = dict(raw)
    validated["entrypoint_kind"] = entrypoint_kind
    return validated


def _policy_entrypoint_kind(policy_path: Path, entrypoint: str) -> Optional[str]:
    """Classify the declared policy entrypoint definition, if it exists.

    ``"function"`` selects the delegated policy-factory contract (a
    zero-argument factory the components call), ``"class"`` the
    deciding-component contract (the DEVS component that owns the decision
    is itself the editable candidate). ``None`` means the declaration
    points at nothing and must be rejected.
    """

    try:
        source = policy_path.read_text(encoding="utf-8")
        tree = ast.parse(source)
    except (OSError, UnicodeError, SyntaxError, ValueError):
        return None
    for node in tree.body:
        if (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name == entrypoint
        ):
            return "function"
        if isinstance(node, ast.ClassDef) and node.name == entrypoint:
            return "class"
    return None


def _validated_simulation_metrics(document: JsonDict) -> Optional[JsonDict]:
    """Validate the optional devs.simulation.v2 metrics declaration."""

    raw = document.get("metrics")
    if raw is None:
        return None
    if document.get("schema_version") == "devs.simulation.v1":
        raise ValueError(
            "simulation.json metrics requires schema_version devs.simulation.v2."
        )
    if not isinstance(raw, dict) or not set(raw) <= {
        "keys",
        "objective",
        "descriptions",
    }:
        raise ValueError(
            "simulation.json metrics must contain only keys, objective, and "
            "descriptions."
        )
    keys = raw.get("keys")
    if (
        not isinstance(keys, list)
        or not keys
        or len(keys) > _GENERATED_SIMULATION_MAX_METRICS
        or any(
            not isinstance(key, str)
            or not _GENERATED_SIMULATION_METRIC_NAME_RE.fullmatch(key)
            for key in keys
        )
        or len(set(keys)) != len(keys)
    ):
        raise ValueError(
            "simulation.json metrics.keys must be a non-empty array of unique "
            f"metric names (at most {_GENERATED_SIMULATION_MAX_METRICS})."
        )
    validated: JsonDict = {"keys": list(keys)}
    objective = raw.get("objective")
    if objective is not None:
        if (
            not isinstance(objective, dict)
            or set(objective) != {"metric", "direction"}
            or objective.get("metric") not in keys
            or objective.get("direction") not in {"maximize", "minimize"}
        ):
            raise ValueError(
                "simulation.json metrics.objective must name a declared metric "
                "with direction maximize or minimize."
            )
        validated["objective"] = dict(objective)
    descriptions = raw.get("descriptions")
    if descriptions is not None:
        if (
            not isinstance(descriptions, dict)
            or not set(descriptions) <= set(keys)
            or any(
                not isinstance(text, str)
                or not text
                or len(text)
                > _GENERATED_SIMULATION_MAX_METRIC_DESCRIPTION_CHARS
                for text in descriptions.values()
            )
        ):
            raise ValueError(
                "simulation.json metrics.descriptions must map declared metric "
                "names to non-empty strings of at most "
                f"{_GENERATED_SIMULATION_MAX_METRIC_DESCRIPTION_CHARS} "
                "characters."
            )
        validated["descriptions"] = dict(descriptions)
    return validated


def _simulation_policy_variant_starter_files(
    component_id: str,
    description: str,
    simulation_handoff: JsonDict,
    bundle_prefix: str = "",
) -> List[tuple[Path, str]]:
    """Starter files for the file-candidate (editable policy) variant.

    Emitted alongside the parameters variant when a v2 bundle declares a
    policy hook. Deliberately a reviewed template (never launch-ready):
    replication seeds and scoring need a human decision, so the config is
    written disabled with the declared contract prefilled.
    """

    policy = simulation_handoff["policy"]
    # Where the bundle sits relative to this config's own folder. A generate
    # action writes it under resource-action-output/<request>/<name>/, so
    # "../" alone would point at an empty Workspace root.
    bundle_root_ref = f"../{bundle_prefix}" if bundle_prefix else ".."
    policy_file = str(policy["file"])
    policy_basename = PurePosixPath(policy_file).name
    entrypoint = str(policy["entrypoint"])
    # "function": the delegated policy-factory contract. "class": the
    # deciding DEVS component itself is the editable candidate
    # (declare-don't-extract; the generator names the component that owns
    # the decision instead of restructuring the model).
    entrypoint_kind = str(policy.get("entrypoint_kind") or "function")
    metrics = simulation_handoff.get("metrics") or {}
    metric_keys = list(metrics.get("keys") or [])
    objective = metrics.get("objective") or {}
    score_metric = str(objective.get("metric") or (metric_keys[0] if metric_keys else "score"))
    score_direction = str(objective.get("direction") or "maximize")
    seed_argument = ""
    for name, declaration in (simulation_handoff.get("candidate_schema") or {}).items():
        if (
            isinstance(declaration, dict)
            and declaration.get("valueType") == "int"
            and name.lower() in {"seed", "random_seed", "rng_seed", "noise_seed"}
        ):
            seed_argument = name
            break

    environment_body = yaml.safe_dump(
        {
            "apiVersion": AUTHORING_API_VERSION,
            "config": "environment",
            "id": f"{component_id}-policy",
            "description": (
                (description or "Generated simulation")
                + (
                    " File-candidate variant: the deciding component "
                    f"({policy_file}) is the editable candidate."
                    if entrypoint_kind == "class"
                    else " File-candidate variant: the decision policy "
                    f"({policy_file}) is the editable candidate."
                )
            ),
            "evaluator": {
                "python": "optpilot_adapter_policy:evaluate",
                "pythonPath": ["."],
                "settings": {
                    "seeds": [101, 102, 103],
                    "seedArgument": seed_argument,
                    "scoreMetric": score_metric,
                    "scoreDirection": score_direction,
                },
            },
            "trialWorkspace": [
                {"from": f"{bundle_root_ref}/run.py", "to": "simulator/run.py"},
                {
                    "from": f"{bundle_root_ref}/simulation.json",
                    "to": "simulator/simulation.json",
                },
                {
                    "from": f"{bundle_root_ref}/devs_project",
                    "to": "simulator/devs_project",
                },
            ],
            "candidate": {
                "format": "files",
                "materialize": {"root": "candidate"},
                "files": {
                    "editable": [{"path": policy_basename}],
                    "required": [policy_basename],
                    "allow": [policy_basename, "provenance/**"],
                    "deny": ["**/__pycache__/**", "**/*.pyc"],
                },
            },
            "methodContext": {
                "instructions": ["policy_instructions.md"],
                "references": [
                    {
                        "name": policy_basename,
                        "type": "candidate_template",
                        "path": f"{bundle_root_ref}/{policy_file}",
                    },
                    {
                        "name": "replay_settings",
                        "type": "json",
                        "path": "policy_replay_settings.json",
                    },
                ],
            },
            "capabilities": [
                {
                    "id": "exact_seed_replay",
                    "description": (
                        "Replays the candidate policy on an exact evaluation "
                        "seed and produces a bounded SQLite trace."
                    ),
                    "callable": "optpilot_adapter_policy:replay_candidate",
                }
            ],
            # The core entrypoint check pins top-level functions only, so
            # the class-style contract relies on the editing instructions
            # plus natural evaluation failure (a candidate that renames the
            # component class crashes its own replications).
            "policyValidation": {
                **(
                    {
                        "entrypoint": {
                            "file": policy_basename,
                            "callable": entrypoint,
                            "maxArguments": 0,
                        }
                    }
                    if entrypoint_kind == "function"
                    else {}
                ),
                "forbiddenImports": [
                    "builtins", "importlib", "os", "pathlib", "random",
                    "socket", "subprocess", "sys",
                ],
                "forbiddenNames": [],
            },
            "metrics": {
                "source": "return",
                "keys": [
                    "mean_total_score", "min_total_score", "max_total_score",
                    "worst_seed", "worst_total_score",
                ],
            },
        },
        sort_keys=False,
    )
    environment_body = (
        "# Starter only: review the replication seeds, the seed argument, and\n"
        "# the scoring below, then rename this file to environment_policy.yaml\n"
        "# so Setup can Check it. The policy contract was declared by the\n"
        "# generated simulator itself (simulation.json policy block).\n"
        + environment_body
    )
    declared_purpose = (
        f"Declared purpose: {policy['description']}\n\n"
        if policy.get("description")
        else ""
    )
    metrics_note = (
        "Declared simulator metrics: "
        + ", ".join(metric_keys)
        + f". The optimization score is `{score_metric}` ({score_direction}d "
        "per replication; the evaluator aggregates mean/min/max and "
        "worst-seed values).\n"
        if metric_keys
        else ""
    )
    if entrypoint_kind == "class":
        instructions = (
            "# Editing contract\n\n"
            f"The editable candidate file is `{policy_basename}` — the DEVS "
            f"component class `{entrypoint}` that owns the optimizable "
            "decision. Each candidate is a complete replacement of this "
            "file, so everything except the selection logic must be "
            "preserved exactly.\n\n"
            + declared_purpose
            + "Preserve verbatim:\n"
            f"- the top-level class name `{entrypoint}` and its `__init__` "
            "signature;\n"
            "- every port registration (names, types, direction) and the "
            "message protocol with peer components documented in the "
            "class docstring (paired outputs, request/response handshakes, "
            "idle/empty edge cases);\n"
            "- the DEVS lifecycle structure (`deltext`/`deltint`/`lambdaf` "
            "roles and the sigma/passivate discipline);\n"
            "- all existing imports and any trace/logging calls.\n\n"
            "Change only the selection logic — the part of the class that "
            "chooses among the waiting candidates. Its inputs and the "
            "decision method are documented in the class docstring. The "
            "logic must stay deterministic: never import or use random, "
            "and never add imports of os, sys, subprocess, socket, "
            "pathlib, importlib, or builtins.\n\n"
            "A candidate that breaks the class name, ports, or protocol "
            "will crash or corrupt its own replications and score as a "
            "failed trial.\n\n"
            + metrics_note
        )
    else:
        instructions = (
            "# Policy contract\n\n"
            f"The editable candidate file is `{policy_basename}`. It must define a "
            f"top-level, zero-argument `{entrypoint}()` returning the policy "
            "object the simulator's decision components delegate to.\n\n"
            + declared_purpose
            + "Snapshot fields and decision semantics are documented in the "
            "policy file's docstring inside the generated bundle. The policy "
            "must stay deterministic and dependency-free (no simulator "
            "internals, os, sys, subprocess, socket, pathlib, importlib, or "
            "random).\n\n"
            + metrics_note
        )
    replay_settings = json.dumps(
        {
            "seeds": [101, 102, 103],
            "seedArgument": seed_argument,
            "scoreMetric": score_metric,
            "scoreDirection": score_direction,
        },
        indent=2,
        sort_keys=True,
    ) + "\n"
    return [
        (
            Path("optpilot_configs/environment_policy.template.yaml.disabled"),
            environment_body,
        ),
        (
            Path("optpilot_configs/optpilot_adapter_policy.py"),
            _simulation_policy_adapter_starter(policy_file, entrypoint),
        ),
        (Path("optpilot_configs/policy_instructions.md"), instructions),
        (Path("optpilot_configs/policy_replay_settings.json"), replay_settings),
    ]


def _simulation_policy_adapter_starter(policy_file: str, entrypoint: str) -> str:
    """Adapter template for policy-candidate evaluation of a generated bundle."""

    return f'''"""Starter adapter: evaluate an editable policy against the generated simulator.

Per candidate: overlay the candidate policy over the bundle's declared
policy file, run one replication per configured seed, score each from the
summary metrics, keep the worst replication's converted SQLite trace, and
report aggregate metric values. Review the seed handling before enabling.
"""

from __future__ import annotations

import json
import shutil
import sqlite3
import subprocess
import sys
from pathlib import Path

_POLICY_FILE = {policy_file!r}
_ENTRYPOINT = {entrypoint!r}
_MAX_TRACE_ROWS = 200000


def _run_replication(simulator, results_dir, settings, seed):
    results_dir.mkdir(parents=True, exist_ok=True)
    for stale in results_dir.iterdir():
        stale.unlink()
    argv = [sys.executable, "-u", "run.py"]
    seed_argument = str(settings.get("seedArgument") or "")
    if seed_argument:
        argv += [f"--{{seed_argument}}", str(seed)]
    completed = subprocess.run(
        argv,
        cwd=simulator,
        env={{
            "PATH": str(Path(sys.executable).parent),
            "HOME": str(results_dir),
            "PYTHONNOUSERSITE": "1",
            "PYTHONUNBUFFERED": "1",
            "PYTHONHASHSEED": str(seed),
            "OPTPILOT_SIMULATION_RESULTS_DIR": str(results_dir),
            "DEVS_SIMULATION_RESULTS_DIR": str(results_dir),
            **(
                {{"PYTHONPATH": __import__("os").environ["PYTHONPATH"]}}
                if __import__("os").environ.get("PYTHONPATH")
                else {{}}
            ),
        }},
        capture_output=True,
        text=True,
        timeout=float(settings.get("timeoutSeconds", 300.0)),
    )
    if completed.returncode:
        raise RuntimeError(
            f"Simulation exited with {{completed.returncode}}: "
            + completed.stderr[-2000:]
        )
    summary = json.loads((results_dir / "summary.json").read_text(encoding="utf-8"))
    metrics = summary.get("metrics") or {{}}
    score_metric = str(settings.get("scoreMetric") or "score")
    if score_metric not in metrics:
        raise RuntimeError(
            f"summary.json does not report the score metric {{score_metric!r}}."
        )
    value = float(metrics[score_metric])
    score = value if settings.get("scoreDirection") != "minimize" else -value
    return score, metrics


def _convert_trace(jsonl_path, database_path, kpis):
    rows = [
        json.loads(line)
        for line in jsonl_path.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    connection = sqlite3.connect(database_path)
    try:
        connection.execute(
            "CREATE TABLE events (sequence INTEGER, record_sequence INTEGER, "
            "simulation_time REAL, component TEXT, port TEXT, value TEXT)"
        )
        connection.execute(
            "CREATE TABLE states (sequence INTEGER, record_sequence INTEGER, "
            "simulation_time REAL, component TEXT, phase TEXT, sigma REAL)"
        )
        connection.execute("CREATE TABLE kpi (name TEXT, value REAL)")
        for row in rows[1:-1][:_MAX_TRACE_ROWS]:
            if row.get("record_type") == "event":
                connection.execute(
                    "INSERT INTO events VALUES (?, ?, ?, ?, ?, ?)",
                    (
                        row.get("sequence"), row.get("record_sequence"),
                        row.get("simulation_time"), row.get("component"),
                        row.get("port"), json.dumps(row.get("value"), default=str)[:2000],
                    ),
                )
            elif row.get("record_type") == "state":
                connection.execute(
                    "INSERT INTO states VALUES (?, ?, ?, ?, ?, ?)",
                    (
                        row.get("sequence"), row.get("record_sequence"),
                        row.get("simulation_time"), row.get("component"),
                        row.get("phase"), row.get("sigma"),
                    ),
                )
        for name, value in sorted((kpis or {{}}).items()):
            if isinstance(value, (int, float)):
                connection.execute(
                    "INSERT INTO kpi VALUES (?, ?)", (str(name), float(value))
                )
        connection.commit()
    finally:
        connection.close()


def _prepared_simulator(workspace, candidate_dir):
    simulator = workspace / "simulator"
    if not simulator.is_dir():
        # Replay contexts run in a bare workspace without the trial
        # materialization; copy the environment-source simulator tree.
        source = Path(__file__).resolve().parent / "simulator"
        shutil.copytree(
            source,
            simulator,
            ignore=shutil.ignore_patterns("__pycache__", "runtime_dependencies"),
        )
        # The environment source projection is read-only; the copy must be
        # writable so the candidate policy can overlay its declared file.
        import os as _os

        for directory, _subdirs, files in _os.walk(simulator):
            _os.chmod(directory, 0o755)
            for name in files:
                _os.chmod(Path(directory) / name, 0o644)
    policy_target = simulator / _POLICY_FILE
    candidate_policy = candidate_dir / Path(_POLICY_FILE).name
    if not candidate_policy.is_file():
        raise FileNotFoundError(
            f"Candidate must provide {{Path(_POLICY_FILE).name}}."
        )
    policy_target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(candidate_policy, policy_target)
    return simulator


def evaluate(candidate_runtime, context):
    workspace = Path(context["workspace"]).resolve()
    candidate_dir = Path(
        candidate_runtime.get("candidateRoot") or workspace / "candidate"
    ).resolve()
    settings = dict(context.get("settings") or {{}})
    seeds = settings.get("seeds") or [101, 102, 103]
    simulator = _prepared_simulator(workspace, candidate_dir)

    records = []
    for seed in seeds:
        score, metrics = _run_replication(
            simulator, workspace / f"results-{{seed}}", settings, int(seed)
        )
        records.append((int(seed), score, metrics))
    worst_seed, worst_score, worst_metrics = min(
        records, key=lambda record: (record[1], record[0])
    )
    database_path = workspace / "worst_run.db"
    if database_path.exists():
        database_path.unlink()
    trace = workspace / f"results-{{worst_seed}}" / "event_trace.jsonl"
    if trace.is_file():
        _convert_trace(trace, database_path, worst_metrics)
    scores = [record[1] for record in records]
    metric_values = {{
        "mean_total_score": sum(scores) / len(scores),
        "min_total_score": min(scores),
        "max_total_score": max(scores),
        "worst_seed": float(worst_seed),
        "worst_total_score": worst_score,
    }}
    output_files = []
    if database_path.is_file():
        output_files.append(
            {{
                "declaration_id": "worst_run",
                "name": "worst_run",
                "path": database_path.relative_to(workspace).as_posix(),
                "kind": "file",
                "media_type": "application/vnd.sqlite3",
                "metadata": {{"seed": worst_seed}},
            }}
        )
    return {{
        "status": "success",
        "metric_values": metric_values,
        "output_files": output_files,
        "event_summary": {{"replications": len(records), "worst_seed": worst_seed}},
    }}


def replay_candidate(*, candidate_dir, settings, seed, database_path):
    workspace = Path(database_path).resolve().parent
    simulator = _prepared_simulator(workspace, Path(candidate_dir))
    results_dir = workspace / f"replay-{{int(seed)}}"
    score, metrics = _run_replication(
        simulator, results_dir, dict(settings), int(seed)
    )
    trace = results_dir / "event_trace.jsonl"
    database = Path(database_path)
    if database.exists():
        database.unlink()
    if trace.is_file():
        _convert_trace(trace, database, metrics)
    else:
        _convert_trace_empty = sqlite3.connect(database)
        _convert_trace_empty.execute("CREATE TABLE kpi (name TEXT, value REAL)")
        _convert_trace_empty.commit()
        _convert_trace_empty.close()
    return {{"total_score": score, "metrics": metrics}}
'''


def _simulation_environment_adapter_starter(
    expected_requirements_lock: str,
) -> str:
    """Return an adapter bound to the dependency lock validated by Setup.

    ``simulation.json`` is copied into each trial Workspace so that the runner
    can use its argument and result declarations.  The dependency lock is not
    copied: it was consumed while preparing the retained Environment runtime.
    Embedding its canonical relative path here prevents a later manifest edit
    from making the trial claim a different runtime than Setup actually
    prepared.
    """

    if (
        not isinstance(expected_requirements_lock, str)
        or not expected_requirements_lock
        or "\\" in expected_requirements_lock
        or "\x00" in expected_requirements_lock
    ):
        raise ValueError("Expected Python requirements lock is invalid.")
    expected_relative = PurePosixPath(expected_requirements_lock)
    if (
        expected_relative.is_absolute()
        or expected_relative.as_posix() != expected_requirements_lock
        or any(part in {"", ".", ".."} for part in expected_relative.parts)
        or len(expected_requirements_lock.encode("utf-8")) > 1024
    ):
        raise ValueError(
            "Expected Python requirements lock must be a canonical relative path."
        )

    source = '''"""Starter adapter for a generated simulation.

The runner and Candidate inputs were detected from simulation.json. Review the
metric extraction below, then enable the Environment config.
"""

from __future__ import annotations

import json
import math
import os
import re
import signal
import stat
import subprocess
import sys
import threading
import time
from pathlib import Path, PurePosixPath


_MAX_MANIFEST_BYTES = 64 * 1024
_MAX_ARGUMENTS = 64
_MAX_CHOICES = 128
_MAX_RESULT_FILES = 128
_MAX_RESULT_ENTRIES = 256
_MAX_RESULT_FILE_BYTES = 16 * 1024 * 1024
_MAX_RESULT_TOTAL_BYTES = 64 * 1024 * 1024
_MAX_JSON_RESULT_BYTES = 1024 * 1024
_MAX_STREAM_BYTES = 1024 * 1024
_PROCESS_POLL_SECONDS = 0.02
_PROCESS_STOP_GRACE_SECONDS = 0.5
_READ_CHUNK_BYTES = 64 * 1024
_EXPECTED_REQUIREMENTS_LOCK = __OPTPILOT_EXPECTED_REQUIREMENTS_LOCK__


def _read_bounded_regular_file(path, *, maximum, label):
    try:
        before = path.lstat()
    except FileNotFoundError as error:
        raise FileNotFoundError(f"{label} is missing.") from error
    if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
        raise ValueError(f"{label} must be a regular file, not a symbolic link.")
    if before.st_size > maximum:
        raise ValueError(f"{label} exceeds the {maximum}-byte limit.")
    chunks = []
    size = 0
    try:
        with path.open("rb") as stream:
            opened = os.fstat(stream.fileno())
            if not stat.S_ISREG(opened.st_mode) or (
                (opened.st_dev, opened.st_ino) != (before.st_dev, before.st_ino)
            ):
                raise ValueError(f"{label} changed while it was opened.")
            while True:
                chunk = stream.read(min(_READ_CHUNK_BYTES, maximum - size + 1))
                if not chunk:
                    break
                size += len(chunk)
                if size > maximum:
                    raise ValueError(f"{label} exceeds the {maximum}-byte limit.")
                chunks.append(chunk)
            after = os.fstat(stream.fileno())
    except OSError as error:
        raise ValueError(f"{label} could not be read: {error}") from error
    if size != before.st_size or after.st_size != size:
        raise ValueError(f"{label} changed while it was read.")
    return b"".join(chunks)


def _load_bounded_json(path, *, maximum, label):
    payload = _read_bounded_regular_file(path, maximum=maximum, label=label)

    def unique_object(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"{label} repeats the key {key!r}.")
            result[key] = value
        return result

    def finite_float(value):
        number = float(value)
        if not math.isfinite(number):
            raise ValueError(f"{label} contains a non-finite number.")
        return number

    def reject_constant(value):
        raise ValueError(f"{label} contains a non-finite number: {value}.")

    try:
        return json.loads(
            payload.decode("utf-8", errors="strict"),
            object_pairs_hook=unique_object,
            parse_float=finite_float,
            parse_constant=reject_constant,
        )
    except (UnicodeError, json.JSONDecodeError, RecursionError) as error:
        raise ValueError(f"{label} is not bounded valid UTF-8 JSON: {error}") from error


def _canonical_relative_path(value, label):
    if (
        not isinstance(value, str)
        or not value
        or "\\\\" in value
        or "\\x00" in value
        or len(value.encode("utf-8")) > 1024
    ):
        raise ValueError(f"{label} must be a canonical relative path.")
    relative = PurePosixPath(value)
    if (
        relative.is_absolute()
        or relative.as_posix() != value
        or any(part in {"", ".", ".."} for part in relative.parts)
    ):
        raise ValueError(f"{label} must be a canonical relative path.")
    return relative


def _value_matches(value, value_type):
    if value_type == "string":
        return type(value) is str and len(value.encode("utf-8")) <= 4096
    if value_type == "integer":
        return type(value) is int
    if value_type == "number":
        return type(value) in (int, float) and math.isfinite(float(value))
    return value_type == "boolean" and type(value) is bool


def _validate_argument_value(value, item, label):
    value_type = item["type"]
    if not _value_matches(value, value_type):
        raise ValueError(f"{label} does not match simulator input type {value_type}.")
    minimum = item.get("minimum")
    maximum = item.get("maximum")
    if minimum is not None and value < minimum:
        raise ValueError(f"{label} is below the declared minimum.")
    if maximum is not None and value > maximum:
        raise ValueError(f"{label} is above the declared maximum.")
    choices = item.get("choices", [])
    if choices and value not in choices:
        raise ValueError(f"{label} is not one of the declared choices.")
    return value


def _load_manifest(simulator_root):
    manifest = _load_bounded_json(
        simulator_root / "simulation.json",
        maximum=_MAX_MANIFEST_BYTES,
        label="simulation.json",
    )
    if not isinstance(manifest, dict):
        raise ValueError("simulation.json must contain one JSON object.")
    allowed_top = {
        "schema_version",
        "entrypoint",
        "timeout_seconds",
        "arguments",
        "result_files",
        "python_runtime",
    }
    unexpected = sorted(set(manifest) - allowed_top)
    if unexpected:
        raise ValueError(
            "simulation.json has unsupported fields: " + ", ".join(unexpected) + "."
        )
    if (
        manifest.get("schema_version") != "devs.simulation.v1"
        or manifest.get("entrypoint") != "run.py"
    ):
        raise ValueError(
            "simulation.json must use devs.simulation.v1 with entrypoint run.py."
        )
    runner = simulator_root / "run.py"
    try:
        runner_metadata = runner.lstat()
    except FileNotFoundError as error:
        raise FileNotFoundError("The simulator is missing run.py.") from error
    if stat.S_ISLNK(runner_metadata.st_mode) or not stat.S_ISREG(runner_metadata.st_mode):
        raise ValueError("run.py must be a regular file, not a symbolic link.")

    raw_runtime = manifest.get("python_runtime")
    if not isinstance(raw_runtime, dict) or set(raw_runtime) != {"requirements_lock"}:
        raise ValueError(
            "simulation.json python_runtime must contain only requirements_lock."
        )
    requirements_lock = _canonical_relative_path(
        raw_runtime.get("requirements_lock"),
        "simulation.json python_runtime.requirements_lock",
    ).as_posix()
    if requirements_lock != _EXPECTED_REQUIREMENTS_LOCK:
        raise ValueError(
            "simulation.json python_runtime.requirements_lock changed after "
            "Workspace Setup. Run Setup again so the retained runtime and "
            "simulator manifest describe the same dependencies."
        )

    timeout_seconds = manifest.get("timeout_seconds", 30)
    if type(timeout_seconds) is not int or not 1 <= timeout_seconds <= 300:
        raise ValueError(
            "simulation.json timeout_seconds must be an integer from 1 to 300."
        )

    raw_arguments = manifest.get("arguments", [])
    if not isinstance(raw_arguments, list) or len(raw_arguments) > _MAX_ARGUMENTS:
        raise ValueError(
            f"simulation.json arguments must contain at most {_MAX_ARGUMENTS} items."
        )
    arguments = []
    names = set()
    for index, raw_item in enumerate(raw_arguments):
        label = f"simulation.json arguments[{index}]"
        if not isinstance(raw_item, dict):
            raise ValueError(f"{label} must be an object.")
        allowed = {
            "name", "flag", "type", "required", "default", "minimum",
            "maximum", "choices", "action", "description", "label",
        }
        unexpected = sorted(set(raw_item) - allowed)
        if unexpected:
            raise ValueError(
                f"{label} has unsupported fields: " + ", ".join(unexpected) + "."
            )
        item = dict(raw_item)
        name = item.get("name")
        if (
            not isinstance(name, str)
            or not re.fullmatch(r"[A-Za-z][A-Za-z0-9_-]{0,63}", name)
            or name in names
        ):
            raise ValueError(f"{label}.name is invalid or duplicated.")
        names.add(name)
        value_type = item.get("type")
        if value_type not in {"integer", "number", "boolean", "string"}:
            raise ValueError(f"{label}.type is unsupported.")
        flag = item.get("flag", f"--{name}")
        if not isinstance(flag, str) or not re.fullmatch(
            r"--[A-Za-z][A-Za-z0-9_-]{0,63}", flag
        ):
            raise ValueError(f"{label}.flag is invalid.")
        item["flag"] = flag
        required = item.get("required", False)
        if type(required) is not bool:
            raise ValueError(f"{label}.required must be boolean.")
        action = item.get("action", "value")
        if action not in {"value", "store_true", "store_false"}:
            raise ValueError(f"{label}.action is unsupported.")
        if action != "value" and value_type != "boolean":
            raise ValueError(f"{label} flag actions require boolean type.")
        item["action"] = action
        choices = item.get("choices", [])
        if not isinstance(choices, list) or len(choices) > _MAX_CHOICES:
            raise ValueError(f"{label}.choices is too large or is not an array.")
        minimum = item.get("minimum")
        maximum = item.get("maximum")
        for bound_name, bound in (("minimum", minimum), ("maximum", maximum)):
            if bound is not None and (
                type(bound) not in (int, float) or not math.isfinite(float(bound))
            ):
                raise ValueError(f"{label}.{bound_name} must be finite numeric data.")
        if value_type not in {"integer", "number"} and (
            minimum is not None or maximum is not None
        ):
            raise ValueError(f"{label} bounds require a numeric input type.")
        if minimum is not None and maximum is not None and minimum > maximum:
            raise ValueError(f"{label}.minimum exceeds maximum.")
        checked_choices = [
            _validate_argument_value(value, {**item, "choices": []}, f"{label}.choices")
            for value in choices
        ]
        if len({json.dumps(value, sort_keys=True) for value in checked_choices}) != len(
            checked_choices
        ):
            raise ValueError(f"{label}.choices contains duplicates.")
        item["choices"] = checked_choices
        if "default" in item:
            _validate_argument_value(item["default"], item, f"{label}.default")
        if required and "default" in item:
            raise ValueError(f"{label} cannot be required and have a default.")
        for text_name in ("description", "label"):
            text_value = item.get(text_name)
            if text_value is not None and (
                not isinstance(text_value, str)
                or len(text_value.encode("utf-8")) > 4096
            ):
                raise ValueError(f"{label}.{text_name} is invalid.")
        arguments.append(item)

    raw_results = manifest.get("result_files", [])
    if not isinstance(raw_results, list) or len(raw_results) > _MAX_RESULT_FILES:
        raise ValueError(
            f"simulation.json result_files must contain at most {_MAX_RESULT_FILES} paths."
        )
    result_files = [
        _canonical_relative_path(value, f"simulation.json result_files[{index}]").as_posix()
        for index, value in enumerate(raw_results)
    ]
    if len(set(result_files)) != len(result_files):
        raise ValueError("simulation.json result_files contains duplicate paths.")
    return {
        "timeout_seconds": timeout_seconds,
        "arguments": arguments,
        "result_files": result_files,
    }


def _inspect_result_tree(result_root):
    stack = [result_root]
    entry_count = 0
    file_count = 0
    total_bytes = 0
    while stack:
        directory = stack.pop()
        try:
            with os.scandir(directory) as entries:
                for entry in entries:
                    entry_count += 1
                    if entry_count > _MAX_RESULT_ENTRIES:
                        raise RuntimeError(
                            "Simulation results contain too many filesystem entries "
                            f"(maximum {_MAX_RESULT_ENTRIES})."
                        )
                    try:
                        metadata = entry.stat(follow_symlinks=False)
                    except FileNotFoundError:
                        continue
                    path = Path(entry.path)
                    if stat.S_ISLNK(metadata.st_mode):
                        raise RuntimeError(
                            f"Simulation results may not contain symbolic links: {entry.name}."
                        )
                    if stat.S_ISDIR(metadata.st_mode):
                        stack.append(path)
                        continue
                    if not stat.S_ISREG(metadata.st_mode):
                        raise RuntimeError(
                            f"Simulation results contain an unsupported file type: {entry.name}."
                        )
                    file_count += 1
                    if file_count > _MAX_RESULT_FILES:
                        raise RuntimeError(
                            "Simulation results contain too many files "
                            f"(maximum {_MAX_RESULT_FILES})."
                        )
                    if metadata.st_size > _MAX_RESULT_FILE_BYTES:
                        raise RuntimeError(
                            f"Simulation result {entry.name} exceeds the "
                            f"{_MAX_RESULT_FILE_BYTES}-byte per-file limit."
                        )
                    total_bytes += metadata.st_size
                    if total_bytes > _MAX_RESULT_TOTAL_BYTES:
                        raise RuntimeError(
                            "Simulation results exceed the total output limit "
                            f"({_MAX_RESULT_TOTAL_BYTES} bytes)."
                        )
        except OSError as error:
            raise RuntimeError(
                f"Simulation results could not be inspected safely: {error}"
            ) from error
    return file_count, total_bytes, entry_count


def _declared_result_path(result_root, relative):
    canonical = _canonical_relative_path(relative, "Declared simulation result")
    path = result_root
    for index, part in enumerate(canonical.parts):
        path = path / part
        try:
            metadata = path.lstat()
        except FileNotFoundError as error:
            raise FileNotFoundError(
                f"Declared simulation result is missing: {relative}"
            ) from error
        if stat.S_ISLNK(metadata.st_mode):
            raise RuntimeError(
                f"Declared simulation result may not traverse a symbolic link: {relative}"
            )
        if index < len(canonical.parts) - 1:
            if not stat.S_ISDIR(metadata.st_mode):
                raise RuntimeError(
                    f"Declared simulation result has a non-directory parent: {relative}"
                )
        elif not stat.S_ISREG(metadata.st_mode):
            raise RuntimeError(
                f"Declared simulation result is not a regular file: {relative}"
            )
    return path


class _BoundedCapture:
    def __init__(self, limit):
        self.limit = limit
        self.chunks = []
        self.size = 0
        self.truncated = False

    def add(self, chunk):
        remaining = self.limit - self.size
        if remaining > 0:
            kept = chunk[:remaining]
            self.chunks.append(kept)
            self.size += len(kept)
        if len(chunk) > max(remaining, 0):
            self.truncated = True

    def text(self):
        return b"".join(self.chunks).decode("utf-8", errors="replace")


def _drain_stream(stream, capture, overflow):
    if stream is None:
        return
    try:
        while True:
            try:
                chunk = stream.read(64 * 1024)
            except (OSError, ValueError):
                return
            if not chunk:
                return
            capture.add(chunk)
            if capture.truncated:
                overflow.set()
    finally:
        try:
            stream.close()
        except OSError:
            pass


def _signal_process_group(process, signal_number, *, force=False):
    if os.name == "posix":
        try:
            os.killpg(process.pid, signal_number)
            return
        except ProcessLookupError:
            return
        except (PermissionError, OSError):
            pass
    if process.poll() is not None:
        return
    try:
        if force:
            process.kill()
        else:
            process.terminate()
    except ProcessLookupError:
        pass


def _process_group_exists(process):
    if os.name != "posix":
        return process.poll() is None
    try:
        os.killpg(process.pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _terminate_process_group(process):
    # The direct program may exit after spawning a background child. Always
    # close its whole isolated process group, including after a normal exit.
    _signal_process_group(process, signal.SIGTERM)
    deadline = time.monotonic() + _PROCESS_STOP_GRACE_SECONDS
    while _process_group_exists(process) and time.monotonic() < deadline:
        time.sleep(_PROCESS_POLL_SECONDS)
    kill_signal = getattr(signal, "SIGKILL", signal.SIGTERM)
    _signal_process_group(process, kill_signal, force=True)
    try:
        process.wait(timeout=2.0)
    except (subprocess.TimeoutExpired, ProcessLookupError):
        _signal_process_group(process, kill_signal, force=True)
        try:
            process.wait(timeout=2.0)
        except (subprocess.TimeoutExpired, ProcessLookupError):
            pass


def _run_bounded(command, *, cwd, environment, timeout_seconds, result_root):
    stdout_capture = _BoundedCapture(_MAX_STREAM_BYTES)
    stderr_capture = _BoundedCapture(_MAX_STREAM_BYTES)
    overflow = threading.Event()
    process = None
    readers = []
    failure = None
    cleaned = False
    started = time.monotonic()
    try:
        process = subprocess.Popen(
            command,
            cwd=cwd,
            env=environment,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            start_new_session=(os.name == "posix"),
            bufsize=0,
        )
        for stream, capture in (
            (process.stdout, stdout_capture),
            (process.stderr, stderr_capture),
        ):
            reader = threading.Thread(
                target=_drain_stream,
                args=(stream, capture, overflow),
                daemon=True,
            )
            reader.start()
            readers.append(reader)

        while process.poll() is None:
            if overflow.is_set():
                failure = (
                    "Simulation exceeded the stdout or stderr output limit "
                    f"({_MAX_STREAM_BYTES} bytes per stream)."
                )
                break
            if time.monotonic() - started >= timeout_seconds:
                failure = (
                    f"Simulation timed out after {timeout_seconds} seconds."
                )
                break
            try:
                _inspect_result_tree(result_root)
            except RuntimeError as error:
                failure = str(error)
                break
            time.sleep(_PROCESS_POLL_SECONDS)

        _terminate_process_group(process)
        cleaned = True
        for reader in readers:
            reader.join(timeout=1.0)
        if stdout_capture.truncated or stderr_capture.truncated:
            failure = (
                "Simulation exceeded the stdout or stderr output limit "
                f"({_MAX_STREAM_BYTES} bytes per stream)."
            )
        if process.returncode is None and failure is None:
            failure = "Simulation process could not be stopped safely."
        if failure is None:
            try:
                _inspect_result_tree(result_root)
            except RuntimeError as error:
                failure = str(error)
        return (
            process.returncode,
            stdout_capture.text(),
            stderr_capture.text(),
            failure,
        )
    finally:
        if process is not None and not cleaned:
            _terminate_process_group(process)
        for reader in readers:
            reader.join(timeout=1.0)


def _argument_vector(manifest, candidate):
    if not isinstance(candidate, dict):
        raise ValueError("Candidate simulator inputs must be an object.")
    declared_names = {item["name"] for item in manifest["arguments"]}
    unexpected = sorted(set(candidate) - declared_names)
    if unexpected:
        raise ValueError(
            "Candidate contains undeclared simulator inputs: "
            + ", ".join(str(value) for value in unexpected)
            + "."
        )
    result = []
    for item in manifest["arguments"]:
        name = item["name"]
        if name in candidate:
            value = candidate[name]
        elif "default" in item:
            value = item["default"]
        elif item.get("required"):
            raise ValueError(f"Missing required simulator input: {name}")
        else:
            continue
        value = _validate_argument_value(value, item, f"Candidate input {name!r}")
        flag = item.get("flag", f"--{name}")
        action = item.get("action", "value")
        if action == "store_true":
            if value:
                result.append(flag)
        elif action == "store_false":
            if not value:
                result.append(flag)
        else:
            result.extend((flag, str(value).lower() if isinstance(value, bool) else str(value)))
    return result


def _check_event_trace_structure(path):
    """Bounded operational-conformance check of a declared event trace.

    Rejects a trace whose header, observation rows, or summary footer are
    structurally broken (the generated writer produces exactly this shape),
    so a truncated or corrupt trace fails the trial instead of silently
    weakening downstream evidence.
    """

    payload = _read_bounded_regular_file(
        path, maximum=_MAX_RESULT_FILE_BYTES, label="Event trace"
    )
    rows = []
    for index, raw in enumerate(payload.decode("utf-8", errors="strict").splitlines()):
        text = raw.strip()
        if not text:
            continue
        try:
            row = json.loads(text)
        except ValueError:
            raise RuntimeError(f"Event trace line {index + 1} is not valid JSON.")
        if not isinstance(row, dict):
            raise RuntimeError(f"Event trace line {index + 1} is not an object.")
        rows.append(row)
    if len(rows) < 2:
        raise RuntimeError("Event trace must contain a header and a summary footer.")
    if rows[0].get("record_type") != "header":
        raise RuntimeError("Event trace must start with its header row.")
    if rows[-1].get("record_type") != "summary":
        raise RuntimeError("Event trace must end with its summary footer.")
    observed = 0
    previous_sequence = 0
    for row in rows[1:-1]:
        if row.get("record_type") not in ("event", "state"):
            raise RuntimeError("Event trace rows must be event or state records.")
        observed += 1
        sequence = row.get("record_sequence")
        if type(sequence) is int:
            if sequence <= previous_sequence:
                raise RuntimeError("Event trace record_sequence went backwards.")
            previous_sequence = sequence
    recorded = rows[-1].get("recorded_records")
    if type(recorded) is int and recorded != observed:
        raise RuntimeError(
            f"Event trace footer declares {recorded} records but {observed} are present."
        )


def evaluate(candidate_runtime, context):
    if not isinstance(context, dict) or not isinstance(context.get("workspace"), str):
        raise ValueError("Evaluation context is missing its trial Workspace.")
    workspace = Path(context["workspace"]).resolve(strict=True)
    if not workspace.is_dir():
        raise ValueError("Evaluation context Workspace is not a directory.")
    simulator_root = workspace / "simulator"
    try:
        simulator_metadata = simulator_root.lstat()
    except FileNotFoundError as error:
        raise FileNotFoundError("Trial Workspace is missing the simulator folder.") from error
    if stat.S_ISLNK(simulator_metadata.st_mode) or not stat.S_ISDIR(
        simulator_metadata.st_mode
    ):
        raise ValueError("The trial simulator folder must not be a symbolic link.")
    manifest = _load_manifest(simulator_root)
    result_root = workspace / "simulation_results"
    result_root.mkdir(parents=True, exist_ok=True)
    result_metadata = result_root.lstat()
    if stat.S_ISLNK(result_metadata.st_mode) or not stat.S_ISDIR(result_metadata.st_mode):
        raise ValueError("The simulation result location must be a regular directory.")
    _files, _bytes, existing_entries = _inspect_result_tree(result_root)
    if existing_entries:
        raise RuntimeError(
            "The simulation result directory must be empty at the start of each trial."
        )
    python = Path(sys.executable).resolve()
    environment = {
        "PATH": str(python.parent),
        "HOME": str(workspace),
        "TMPDIR": str(workspace),
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
        "PYTHONUNBUFFERED": "1",
        "PYTHONNOUSERSITE": "1",
        "OPTPILOT_SIMULATION_RESULTS_DIR": str(result_root),
        "DEVS_SIMULATION_RESULTS_DIR": str(result_root),
    }
    # Retained workers expose the exact prepared wheel layer through
    # PYTHONPATH. Forward that one runtime binding to run.py without inheriting
    # host credentials, proxy settings, or unrelated environment variables.
    retained_pythonpath = os.environ.get("PYTHONPATH")
    if retained_pythonpath:
        environment["PYTHONPATH"] = retained_pythonpath
    timeout_seconds = manifest["timeout_seconds"]
    return_code, stdout, stderr, execution_failure = _run_bounded(
        [str(python), "-u", "run.py", *_argument_vector(manifest, candidate_runtime)],
        cwd=simulator_root,
        environment=environment,
        timeout_seconds=timeout_seconds,
        result_root=result_root,
    )
    if execution_failure:
        detail = stderr[-4000:] or stdout[-4000:]
        raise RuntimeError(
            execution_failure + (f" {detail}" if detail else "")
        )
    if return_code:
        raise RuntimeError(
            f"Simulation exited with {return_code}: {stderr[-4000:]}"
        )

    metric_values = {}
    output_files = []
    _inspect_result_tree(result_root)
    declared_total_bytes = 0
    for relative in manifest["result_files"]:
        path = _declared_result_path(result_root, relative)
        metadata = path.lstat()
        if metadata.st_size > _MAX_RESULT_FILE_BYTES:
            raise RuntimeError(
                f"Declared simulation result exceeds the per-file limit: {relative}"
            )
        declared_total_bytes += metadata.st_size
        if declared_total_bytes > _MAX_RESULT_TOTAL_BYTES:
            raise RuntimeError("Declared simulation results exceed the total output limit.")
        suffix = path.suffix.lower()
        output_files.append(
            {
                "declaration_id": f"simulation-result-{len(output_files) + 1}",
                "name": Path(relative).stem,
                "path": path.relative_to(workspace).as_posix(),
                "kind": "file",
                "media_type": (
                    "application/json"
                    if suffix == ".json"
                    else "application/octet-stream"
                ),
                "metadata": {"simulation_result": True},
            }
        )
        if path.suffix.lower() == ".json":
            payload = _load_bounded_json(
                path,
                maximum=min(_MAX_JSON_RESULT_BYTES, _MAX_RESULT_FILE_BYTES),
                label=f"Simulation JSON result {relative}",
            )
            values = payload.get("metrics", payload) if isinstance(payload, dict) else {}
            for name, value in values.items():
                if (
                    not isinstance(name, str)
                    or not name
                    or len(name.encode("utf-8")) > 512
                    or not (
                        type(value) in (bool, int)
                        or (type(value) is float and math.isfinite(value))
                    )
                ):
                    continue
                if name in metric_values:
                    raise ValueError(
                        f"Simulation results declare metric {name!r} more than once."
                    )
                metric_values[name] = value
        if path.name == "event_trace.jsonl":
            _check_event_trace_structure(path)
    if not metric_values:
        raise NotImplementedError(
            "The simulator runs, but no optimization metric is declared yet. "
            "Write a JSON result containing a metrics object and list it in "
            "simulation.json, then set the Environment metric keys."
        )
    return {
        "status": "success",
        "metric_values": metric_values,
        "output_files": output_files,
        "event_summary": {"stdout": stdout[-4000:]},
    }
'''
    marker = "__OPTPILOT_EXPECTED_REQUIREMENTS_LOCK__"
    if source.count(marker) != 1:
        raise RuntimeError("Generated simulation adapter template marker is invalid.")
    return source.replace(marker, repr(expected_requirements_lock))


def _configure_workspace_catalog_role(
    state: UiState, workspace_id: str, payload: JsonDict
) -> JsonDict:
    """Write one bounded starter config without guessing domain semantics."""

    if not isinstance(payload, dict):
        raise ValueError("Workspace Configure request must be a JSON object.")
    unexpected = sorted(set(payload) - {"role", "id", "description"})
    if unexpected:
        raise ValueError(
            "Unsupported Workspace Configure fields: " + ", ".join(unexpected) + "."
        )
    workspace = _require_ui_workspace(state, workspace_id)
    if str(workspace.get("mode") or "editable") != "editable":
        raise RealmConflict("Only an editable Workspace can be configured.")
    if workspace.get("reopen_required"):
        raise RealmConflict("Reopen this Workspace before configuring it.")
    root = Path(str(workspace.get("root") or "")).resolve()
    _safe_workspace_root(state, root)
    role = str(payload.get("role") or "").strip().lower()
    allowed = {"environment", "method", *RESOURCE_PURPOSES}
    if role not in allowed:
        raise ValueError(
            "Choose Environment, Method, Generator, Viewer, Template, or Reference."
        )
    component_id = _slug_text(
        str(payload.get("id") or workspace.get("title") or workspace_id)
    )
    if not component_id:
        raise ValueError("Catalog id cannot be empty.")
    description = str(payload.get("description") or "").strip()
    bundle_root = (
        _generated_simulation_bundle_root(root) if role == "environment" else None
    )
    simulation_handoff = (
        _workspace_simulation_handoff(bundle_root) if bundle_root is not None else None
    )
    bundle_prefix = (
        PurePosixPath(bundle_root.relative_to(root)).as_posix()
        if bundle_root is not None and bundle_root != root
        else ""
    )
    bundle_root_ref = f"../{bundle_prefix}" if bundle_prefix else ".."

    if role in RESOURCE_PURPOSES:
        relative = Path("optpilot.resource.yaml")
        content: JsonDict = {
            "apiVersion": AUTHORING_API_VERSION,
            "config": "resource",
            "id": component_id,
            "name": str(workspace.get("title") or component_id),
            "description": description or f"Reusable {role} files.",
            "purpose": role,
        }
        body = yaml.safe_dump(content, sort_keys=False)
        needs_editing = False
        support_files: List[tuple[Path, str]] = []
    elif role == "environment":
        detected_schema = (
            deepcopy(simulation_handoff["candidate_schema"])
            if simulation_handoff
            and simulation_handoff.get("candidate_schema")
            else {
                "decision": {
                    "valueType": "float",
                    "min": 0,
                    "max": 1,
                    "description": "Replace with the real decision variable.",
                }
            }
        )
        declared_simulation_metrics = (
            simulation_handoff.get("metrics") if simulation_handoff else None
        )
        metric_keys = (
            list(declared_simulation_metrics["keys"])
            if declared_simulation_metrics
            else ["score"]
        )
        # A v2 bundle that declares its metric names produces a launch-ready
        # Environment: the config is written enabled and Setup can Check it
        # immediately. Without declared metrics the config stays a disabled
        # template whose metric keys need human review.
        launch_ready = bool(declared_simulation_metrics)
        relative = (
            Path("optpilot_configs/environment.yaml")
            if launch_ready
            else Path("optpilot_configs/environment.template.yaml.disabled")
        )
        body = yaml.safe_dump(
            {
                "apiVersion": AUTHORING_API_VERSION,
                "config": "environment",
                "id": component_id,
                "description": description or "Describe what this Environment evaluates.",
                "evaluator": {
                    "python": "optpilot_adapter:evaluate",
                    "pythonPath": ["."],
                },
                **(
                    {
                        "runtime": {
                            "sandbox": "process",
                            "setup": {
                                "cache": "prepared",
                                "timeoutSeconds": 300,
                                "steps": [
                                    {
                                        "uses": "python-venv",
                                        "cwd": "..",
                                        "requirements": [
                                            simulation_handoff["python_runtime"][
                                                "requirements_lock"
                                            ]
                                        ],
                                    }
                                ],
                            },
                        }
                    }
                    if simulation_handoff
                    else {}
                ),
                **(
                    {
                        "trialWorkspace": [
                            {
                                "from": f"{bundle_root_ref}/run.py",
                                "to": "simulator/run.py",
                            },
                            {
                                "from": f"{bundle_root_ref}/simulation.json",
                                "to": "simulator/simulation.json",
                            },
                            {
                                "from": f"{bundle_root_ref}/devs_project",
                                "to": "simulator/devs_project",
                            },
                        ]
                    }
                    if simulation_handoff
                    else {}
                ),
                "candidate": {
                    "format": "parameters",
                    "parameters": {
                        "schema": detected_schema
                    },
                },
                "metrics": {"source": "return", "keys": metric_keys},
            },
            sort_keys=False,
        )
        if launch_ready:
            body = (
                "# Generated from simulation.json (devs.simulation.v2): the\n"
                "# metric keys below were declared by the simulator itself.\n"
                + body
            )
        else:
            body = (
                "# Starter only: review the Candidate contract, evaluator, and metrics,\n"
                "# then rename this file to environment.yaml so Setup can Check it.\n"
                + body
            )
        support_files = [
            (
                Path("optpilot_configs/optpilot_adapter.py"),
                (
                    _simulation_environment_adapter_starter(
                        simulation_handoff["python_runtime"]["requirements_lock"]
                    )
                    if simulation_handoff
                    else
                    '"""Replace this starter with the project\'s real evaluation adapter."""\n\n'
                    "def evaluate(candidate_runtime, context):\n"
                    "    raise NotImplementedError(\n"
                    '        "Implement the Environment evaluator before registering this project."\n'
                    "    )\n"
                ),
            )
        ]
        if simulation_handoff and simulation_handoff.get("policy"):
            # The bundle declares an optimizable decision policy: emit the
            # file-candidate variant alongside the parameters one, as a
            # reviewed template (seeds and scoring need a human decision).
            support_files.extend(
                _simulation_policy_variant_starter_files(
                    component_id, description, simulation_handoff, bundle_prefix
                )
            )
        needs_editing = not launch_ready
    else:
        relative = Path("optpilot_configs/method.template.yaml.disabled")
        body = yaml.safe_dump(
            {
                "apiVersion": AUTHORING_API_VERSION,
                "config": "method",
                "id": component_id,
                "description": description or "Describe how this Method proposes Candidates.",
                "entrypoint": {
                    "python": "optpilot_method:Method",
                    "pythonPath": ["."],
                    "protocol": "batch",
                },
                "accepts": {"formats": ["parameters"]},
            },
            sort_keys=False,
        )
        body = (
            "# Starter only: implement the proposal logic and accepted Candidate format,\n"
            "# then rename this file to method.yaml so Setup can Check it.\n"
            + body
        )
        support_files = [
            (
                Path("optpilot_configs/optpilot_method.py"),
                '"""Replace this starter with the project\'s real proposal Method."""\n\n'
                "class Method:\n"
                "    def __init__(self, definition, study_spec, rng):\n"
                "        self.rng = rng\n\n"
                "    def propose(self, n_candidates, study_state):\n"
                "        raise NotImplementedError(\n"
                '            "Implement Candidate proposal before registering this project."\n'
                "        )\n",
            )
        ]
        needs_editing = True

    target = _contained_output_path(root, relative)
    targets = [(target, body)] + [
        (_contained_output_path(root, path), content)
        for path, content in support_files
    ]
    with _PACKAGE_PLAN_APPLY_LOCK:
        existing = [path for path, _content in targets if path.exists()]
        if existing:
            raise RealmConflict(
                "Setup did not overwrite existing project files. Edit or remove the "
                f"existing file first: {_relative_path(existing[0], root)}"
            )
        created: List[Path] = []
        try:
            for path, content in targets:
                path.parent.mkdir(parents=True, exist_ok=True)
                _atomic_write_text(path, content)
                created.append(path)
        except BaseException:
            for path in reversed(created):
                path.unlink(missing_ok=True)
            raise
    return {
        "workspace": _require_ui_workspace(state, workspace_id),
        "configuration": {
            "role": role,
            "id": component_id,
            "created_paths": [
                _relative_path(path, root) for path, _content in targets
            ],
            "needs_editing": needs_editing,
            "next_action": "edit-template" if needs_editing else "check",
            "detected_simulation": (
                {
                    "schema_version": simulation_handoff["schema_version"],
                    "entrypoint": simulation_handoff["entrypoint"],
                    "parameter_count": simulation_handoff["parameter_count"],
                    "result_file_count": len(
                        simulation_handoff["result_files"]
                    ),
                    "python_runtime": deepcopy(
                        simulation_handoff["python_runtime"]
                    ),
                    **(
                        {"metrics": deepcopy(simulation_handoff["metrics"])}
                        if simulation_handoff.get("metrics")
                        else {}
                    ),
                }
                if simulation_handoff
                else None
            ),
        },
    }


def _default_resource_registration_include(root: Path) -> List[str]:
    include: List[str] = []
    for item in sorted(root.iterdir(), key=lambda path: path.name.lower()):
        if item.name in EXCLUDED_SCAN_DIRS or item.name in {".DS_Store"}:
            continue
        include.append(f"{item.name}/**" if item.is_dir() else item.name)
    return include or ["README.md"]


def _registration_workspace_revision(workspace: Mapping[str, Any]) -> Optional[int]:
    revision = workspace.get("realm_workspace_revision")
    if not isinstance(revision, bool) and isinstance(revision, int) and revision > 0:
        return revision
    # Connected/local Workspaces do not have a Realm checkout revision.  Their
    # Check still seals exact immutable bytes; the durable product-purpose
    # revision supplies a stable positive Workspace coordinate while the
    # artifact ref/digest supplies the changing content identity.
    purpose_revision = workspace.get("purpose_revision")
    if (
        not isinstance(purpose_revision, bool)
        and isinstance(purpose_revision, int)
        and purpose_revision > 0
    ):
        return purpose_revision
    return None


def _registration_catalog_roles(plan: Mapping[str, Any]) -> tuple[str, ...]:
    roles = {
        str(item.get("kind") or "")
        for group in ("components", "resources", "studies")
        for item in plan.get(group, []) or []
        if isinstance(item, Mapping)
    }
    return tuple(sorted((role for role in roles if role), key=lambda item: item.encode("utf-8")))


def _registration_setup_source(
    workspace_id: str, workspace_revision: int
) -> EntityCoordinate:
    return EntityCoordinate(
        kind="workspace",
        entity_id=workspace_id,
        revision=workspace_revision,
    )


def _current_registration_setup(state: UiState, workspace_id: str) -> Any:
    try:
        return state.coordination.get_registration_setup(
            actor_id=_studio_actor_id(state), workspace_id=workspace_id
        )
    except CoordinationNotFound:
        return None


def _save_registration_setup_data(
    state: UiState,
    *,
    workspace_id: str,
    data: RegistrationSetupData,
) -> Any:
    current = _current_registration_setup(state, workspace_id)
    expected_revision = None if current is None else current.revision
    operation_id = (
        f"studio/registration-setup/{workspace_id}/"
        + request_digest(
            {
                "data": data.to_dict(),
                "expected_revision": expected_revision,
                "schema": "optpilot.registration-setup-save.v1",
            }
        )
    )
    return state.coordination.save_registration_setup(
        operation_id=operation_id,
        actor_id=_studio_actor_id(state),
        workspace_id=workspace_id,
        data=data,
        expected_revision=expected_revision,
    )


def _public_registration_setup(record: Any) -> Optional[JsonDict]:
    if record is None:
        return None
    data = record.data
    return {
        "schema": "optpilot.workspace-setup.v1",
        "setup_id": record.setup_id,
        "workspace_id": record.workspace_id,
        "revision": record.revision,
        "state": data.state.value,
        "package_id": data.package_id,
        "catalog_roles": list(data.catalog_roles),
        "check": None if data.check is None else {
            "accepted": data.check.accepted,
            "checked_at": data.check.checked_at,
            "workspace_revision": data.check.workspace_revision,
            "summary": deepcopy(dict(data.check.summary)),
        },
        "test": None if data.test is None else {
            "accepted": data.test.accepted,
            "tested_at": data.test.tested_at,
            "summary": deepcopy(dict(data.test.summary)),
        },
        "registered": None if data.publication_result is None else {
            "kind": data.publication_result.kind,
            "id": data.publication_result.entity_id,
            "revision": data.publication_result.revision,
        },
        "updated_at": record.updated_at,
    }


def _record_registration_configuring(
    state: UiState, *, workspace: Mapping[str, Any], plan: Mapping[str, Any]
) -> Any:
    workspace_revision = _registration_workspace_revision(workspace)
    if workspace_revision is None:
        return None
    data = RegistrationSetupData(
        state=RegistrationSetupState.CONFIGURING,
        package_id=_package_plan_package_id(plan.get("package_id")),
        catalog_roles=_registration_catalog_roles(plan),
        publisher_id=_package_plan_publisher_id(dict(plan)),
        source_lineage=_registration_setup_source(
            str(workspace["id"]), workspace_revision
        ),
    )
    return _save_registration_setup_data(
        state, workspace_id=str(workspace["id"]), data=data
    )


def _registration_validation_digest(plan: Mapping[str, Any]) -> str:
    artifact = plan.get("artifact") or {}
    return request_digest(
        {
            "schema": "optpilot.package-plan-validation-evidence.v1",
            "artifact_ref": artifact.get("content_ref"),
            "validation": plan.get("validation", {}),
        }
    )


def _record_registration_check(
    state: UiState, *, workspace: Mapping[str, Any], plan: Mapping[str, Any]
) -> Any:
    workspace_revision = _registration_workspace_revision(workspace)
    artifact = plan.get("artifact") if isinstance(plan.get("artifact"), Mapping) else None
    if workspace_revision is None or not artifact:
        return None
    validation = plan.get("validation") if isinstance(plan.get("validation"), Mapping) else {}
    accepted = bool(validation.get("valid"))
    check = RegistrationCheck(
        workspace_revision=workspace_revision,
        store_id=str(artifact["store_id"]),
        artifact_ref=SnapshotRef.parse(str(artifact["content_ref"])),
        owned_paths=tuple(_package_plan_owned_paths(dict(plan))),
        accepted=accepted,
        validation_digest=_registration_validation_digest(plan),
        summary={
            "error_count": len(validation.get("errors", []) or []),
            "file_count": int(artifact.get("file_count") or 0),
            "logical_bytes": int(artifact.get("logical_bytes") or 0),
            "warning_count": len(validation.get("warnings", []) or []),
        },
        checked_at=time.time(),
    )
    expected_head = _package_plan_catalog_base_head(dict(plan))
    data = RegistrationSetupData(
        state=(
            RegistrationSetupState.CHECKED
            if accepted
            else RegistrationSetupState.CHECK_FAILED
        ),
        package_id=_package_plan_package_id(plan.get("package_id")),
        catalog_roles=_registration_catalog_roles(plan),
        publisher_id=_package_plan_publisher_id(dict(plan)),
        source_lineage=_registration_setup_source(
            str(workspace["id"]), workspace_revision
        ),
        check=check,
        expected_catalog_head=expected_head,
    )
    return _save_registration_setup_data(
        state, workspace_id=str(workspace["id"]), data=data
    )


def _record_registration_test(
    state: UiState,
    *,
    workspace_id: str,
    result: Mapping[str, Any],
) -> Any:
    current = _current_registration_setup(state, workspace_id)
    if current is None or current.data.check is None or not current.data.check.accepted:
        return None
    tested = RegistrationTestResult(
        accepted=bool(result.get("valid")),
        result_digest=request_digest(
            {
                "result": dict(result),
                "schema": "optpilot.registration-test-result.v1",
            }
        ),
        summary={
            "code": str(result.get("code") or ""),
            "error_count": len(result.get("errors", []) or []),
            "study_selected": bool(result.get("study")),
        },
        tested_at=time.time(),
    )
    data = replace(
        current.data,
        state=RegistrationSetupState.CHECKED,
        test=tested,
        publication_intent_id=None,
        publication_result=None,
    )
    return _save_registration_setup_data(
        state, workspace_id=workspace_id, data=data
    )


def _package_plan_package_id(value: Any) -> str:
    package_id = _safe_artifact_identifier(
        str(value or LOCAL_PACKAGE_NAME).strip(),
        "package plan package id",
    )
    if package_id.startswith((".", "~")):
        raise ValueError("Package plan package id cannot be hidden or home-relative.")
    return package_id


def _package_plan_catalog_destination(package_id: str, relative: str = "") -> str:
    package_id = _package_plan_package_id(package_id)
    if not relative:
        return f"catalog://{package_id}"
    path = _safe_relative_plan_path(relative, "package catalog destination")
    return f"catalog://{package_id}/{path.as_posix()}"


def _prepare_package_plan(
    state: UiState, workspace_id: str, payload: JsonDict
) -> JsonDict:
    workspace = _require_ui_workspace(state, workspace_id)
    if not workspace.get("registration_enabled", True):
        raise ValueError("This workspace cannot be registered to the catalog.")
    configured_authority = (
        _configured_source_workspace_authority(state, workspace)
        if workspace.get("source_type") == "configured-catalog-source"
        else None
    )
    root = Path(str(workspace["root"])).resolve()
    configs = _discover_workspace_package_configs(root)
    requested_paths = {str(item) for item in payload.get("config_paths", []) or []}
    selected = [
        item
        for item in configs
        if not requested_paths
        or item["relative_path"] in requested_paths
        or item["path"] in requested_paths
    ]
    requested_plan_id = payload.get("id")
    plan_id = str(
        requested_plan_id
        or "pkg_plan_"
        + request_digest(
            {
                "actor_id": _studio_actor_id(state),
                "schema": "optpilot.workspace-registration-plan.v1",
                "workspace_id": workspace_id,
            }
        )[:20]
    )
    # Opening Setup is a read/reopen operation.  It must not mint a new plan,
    # publisher identity, or Catalog lineage merely because the page was
    # refreshed.  An explicit refresh or changed configuration starts a fresh
    # deterministic preparation of the same Workspace setup identity.
    preparation_requested = bool(
        payload.get("refresh")
        or payload.get("config_paths")
        or payload.get("package_id")
        or payload.get("resource_id")
        or payload.get("kind")
    )
    if requested_plan_id is None and not preparation_requested:
        try:
            return {
                "package_plan": _decorate_plan_software_state(
                    state,
                    workspace_id,
                    _read_package_plan(state, workspace_id, plan_id),
                ),
                "setup": _public_registration_setup(
                    _current_registration_setup(state, workspace_id)
                ),
            }
        except FileNotFoundError:
            pass
    requested_package_id = payload.get("package_id")
    if configured_authority is not None:
        package_id = str(configured_authority["package_id"])
        if requested_package_id not in (None, "", package_id):
            raise ValueError(
                "A configured source Workspace keeps its authorized Catalog identity."
            )
    else:
        package_id = _package_plan_package_id(
            requested_package_id or LOCAL_PACKAGE_NAME
        )
    components = []
    resources = []
    studies = []
    for item in selected:
        config_path = Path(item["path"])
        raw = _read_yaml(config_path)
        kind = str(item["kind"])
        if kind in {"environment", "method"}:
            component_root = (
                f"{'environments' if kind == 'environment' else 'methods'}/"
                f"{_slug_text(item['id'])}"
            )
            components.append(
                {
                    "target_id": f"target_{uuid.uuid4().hex[:8]}",
                    "kind": kind,
                    "id": item["id"],
                    "label": item["label"],
                    "config_path": item["relative_path"],
                    "registered_config_path": _registered_config_filename(
                        kind, config_path.name
                    ),
                    "component_root": component_root,
                    "destination": _package_plan_catalog_destination(
                        package_id, component_root
                    ),
                    "include": _default_registration_include(root, config_path, raw),
                    "exclude": [
                        ".git/**",
                        ".venv/**",
                        "runs/**",
                        "__pycache__/**",
                        "node_modules/**",
                    ],
                    "path_rewrites": [],
                    "source_hints": [],
                    "validation": item["validation"],
                    "raw_config": raw,
                }
            )
        elif kind == "resource":
            resources.append(_package_plan_resource_target(package_id, root, item, raw))
        elif kind == "study":
            studies.append(_package_plan_study_target(root, item, raw))
    if not selected and (
        payload.get("resource_id") or str(payload.get("kind") or "") == "resource"
    ):
        resource_id = _slug_text(
            str(payload.get("resource_id") or workspace.get("title") or workspace["id"])
        )
        resources.append(
            {
                "target_id": f"target_{uuid.uuid4().hex[:8]}",
                "kind": "resource",
                "id": resource_id,
                "label": str(
                    payload.get("description") or workspace.get("title") or resource_id
                ),
                "config_path": "",
                "component_root": f"resources/{resource_id}",
                "destination": _package_plan_catalog_destination(
                    package_id,
                    f"resources/{resource_id}",
                ),
                "include": _default_resource_registration_include(root),
                "exclude": [
                    ".git/**",
                    ".venv/**",
                    "runs/**",
                    "__pycache__/**",
                    "node_modules/**",
                ],
                "validation": {"valid": True, "errors": [], "warnings": []},
                "synthesized": True,
            }
        )
    classification = _package_plan_classification(components, resources)
    readiness = "draft" if selected or resources else "not-yet-classifiable"
    package_identity_value = _package_identity_for(state, package_id)
    plan = {
        "id": plan_id,
        "workspace_id": workspace_id,
        "package_id": package_id,
        "package_identity": package_identity_value,
        # What the package looked like when this work started. Registering
        # compares against it: if the folder moved on since, this work was built
        # on an older version and is refused rather than replacing what moved it.
        "catalog_selection_fingerprint": None,  # set once the selection is known
        "publisher_id": (
            str(configured_authority["publisher_id"])
            if configured_authority is not None
            else _package_folder_publisher_id(package_id, package_identity_value)
        ),
        "publication_scope": (
            CONFIGURED_SOURCE_PLAN_SCOPE
            if configured_authority is not None
            else "curated-items"
        ),
        "source_authority": (
            {
                "kind": "configured-catalog-source",
                "source_id": str(configured_authority["source_id"]),
            }
            if configured_authority is not None
            else None
        ),
        "classification": classification,
        "readiness": readiness,
        "status": "draft",
        "destination": _package_plan_catalog_destination(package_id),
        "source_root": str(root),
        "components": components,
        "resources": resources,
        "studies": studies,
        "artifact": {},
        "catalog_base": {},
        "publication": {},
        "validation": {},
        "smoke": {},
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    placement = payload.get("image_placement")
    if placement is not None:
        if placement not in ("component", "package"):
            raise ValueError(
                "image_placement must be 'component' or 'package'."
            )
        # Where captured software goes when the package already has an image.
        # Carried on the plan because the capture records it at Check; a client
        # that never sets it gets the default, which is the component.
        plan["image_placement"] = placement
    # What the parts of the package this work covers looked like when it began.
    # Registering compares against it and refuses if they moved, so a stale
    # workspace can never quietly replace a newer version of its own component.
    plan["catalog_selection_fingerprint"] = _package_selection_fingerprint(
        state.cwd / CATALOG_DIR_NAME / package_id,
        _package_plan_selection_paths(plan),
    )
    _decorate_plan_software_state(state, workspace_id, plan)
    _write_package_plan(state, workspace_id, plan)
    setup = _record_registration_configuring(
        state, workspace=workspace, plan=plan
    )
    return {
        "package_plan": plan,
        "setup": _public_registration_setup(setup),
    }


def _package_plan_resource_target(
    package_id: str, root: Path, item: JsonDict, raw: JsonDict
) -> JsonDict:
    resource_id = _slug_text(str(item["id"]))
    config_path = Path(item["path"])
    return {
        "target_id": f"target_{uuid.uuid4().hex[:8]}",
        "kind": "resource",
        "id": resource_id,
        "label": item["label"],
        "config_path": item["relative_path"],
        "registered_config_path": _registered_config_filename(
            "resource", config_path.name
        ),
        "component_root": f"resources/{resource_id}",
        "destination": _package_plan_catalog_destination(
            package_id,
            f"resources/{resource_id}",
        ),
        "include": _default_resource_config_include(root, config_path, raw),
        "exclude": [
            ".git/**",
            ".venv/**",
            "runs/**",
            "__pycache__/**",
            "node_modules/**",
        ],
        "validation": item["validation"],
        "raw_config": raw,
    }


def _package_plan_study_target(root: Path, item: JsonDict, raw: JsonDict) -> JsonDict:
    study_name = _slug_text(str(raw.get("name") or item["id"]))
    return {
        "target_id": f"target_{uuid.uuid4().hex[:8]}",
        "kind": "study",
        "id": study_name,
        "label": str(raw.get("name") or item["label"]),
        "config_path": item["relative_path"],
        "registered_config_path": f"studies/{study_name}.yaml",
        "include": [item["relative_path"]],
        "environmentConfig": str(raw.get("environmentConfig") or ""),
        "methodConfig": str(raw.get("methodConfig") or ""),
        "smoke": "smoke" in study_name,
        "validation": item["validation"],
    }


def _update_package_plan(
    state: UiState, workspace_id: str, plan_id: str, payload: JsonDict
) -> JsonDict:
    plan = _read_package_plan(state, workspace_id, plan_id)
    previous_semantic_digest = _package_plan_digest(plan)
    placement = payload.get("image_placement")
    if placement is not None:
        if placement not in ("component", "package"):
            raise ValueError(
                "image_placement must be 'component' or 'package'."
            )
        # The browser's answer to the placement question, recorded on the
        # stored plan without rebuilding it; Check reads it when capturing.
        plan["image_placement"] = placement
    if payload.get("package_id"):
        if _is_configured_whole_package_plan(plan):
            authority = _assert_configured_package_plan_authority(state, plan)
            assert authority is not None
            if str(payload["package_id"]) != authority["package_id"]:
                raise ValueError(
                    "A configured source Workspace keeps its authorized Catalog identity."
                )
        plan["package_id"] = _package_plan_package_id(payload["package_id"])
        plan["destination"] = _package_plan_catalog_destination(plan["package_id"])
        for target in [
            *(plan.get("components", []) or []),
            *(plan.get("resources", []) or []),
        ]:
            if isinstance(target, dict) and target.get("component_root"):
                target["destination"] = _package_plan_catalog_destination(
                    plan["package_id"], str(target["component_root"])
                )
    for collection_name in ("components", "resources", "studies"):
        updates = payload.get(collection_name)
        if not isinstance(updates, list):
            continue
        records = (
            plan.get(collection_name, [])
            if isinstance(plan.get(collection_name), list)
            else []
        )
        by_id = {
            str(item.get("target_id") or item.get("id")): item
            for item in records
            if isinstance(item, dict)
        }
        for update in updates:
            if not isinstance(update, dict):
                continue
            key = str(update.get("target_id") or update.get("id") or "")
            target = by_id.get(key)
            if not target:
                continue
            for field_name in (
                "include",
                "exclude",
                "source_hints",
                "path_rewrites",
                "smoke",
            ):
                if field_name in update:
                    target[field_name] = _validated_package_plan_field(
                        field_name, update[field_name]
                    )
    # The browser synchronizes the visible Setup fields before Check, Test, and
    # Register.  An unchanged synchronization is a read/replay, not an edit: it
    # must preserve the exact checked artifact and Test evidence.  Only a real
    # semantic change invalidates those results.
    if _package_plan_digest(plan) != previous_semantic_digest:
        plan["artifact"] = {}
        plan["catalog_base"] = {}
        plan["publication"] = {}
        plan["validation"] = {}
        plan["smoke"] = {}
        plan["status"] = "draft"
    plan["updated_at"] = _now_iso()
    _write_package_plan(state, workspace_id, plan)
    return {"package_plan": plan}


def _validated_package_plan_field(field: str, value: Any) -> Any:
    if field == "smoke":
        return bool(value)
    if field in {"include", "exclude"}:
        if not isinstance(value, list):
            raise ValueError(f"Package plan {field} must be a list.")
        normalized = []
        for item in value:
            text = str(item)
            _validate_workspace_pattern(text)
            normalized.append(text)
        return normalized
    if field == "source_hints":
        if not isinstance(value, list):
            raise ValueError("Package plan source_hints must be a list.")
        normalized_hints = []
        for hint in value:
            path = hint.get("path") if isinstance(hint, dict) else hint
            text = str(path or "")
            _validate_workspace_pattern(text)
            normalized_hints.append(
                {**hint, "path": text} if isinstance(hint, dict) else text
            )
        return normalized_hints
    if field == "path_rewrites":
        if not isinstance(value, list):
            raise ValueError("Package plan path_rewrites must be a list.")
        normalized = []
        for rewrite in value:
            if not isinstance(rewrite, dict):
                raise ValueError("Package plan path_rewrites entries must be objects.")
            source = str(rewrite.get("from") or "")
            destination = str(rewrite.get("to") or "")
            _safe_relative_plan_path(source, "path rewrite source")
            _safe_relative_plan_path(destination, "path rewrite destination")
            normalized.append({"from": source, "to": destination})
        return normalized
    raise ValueError(f"Unsupported package plan field: {field}.")


def _package_plan_semantic_payload(plan: JsonDict) -> JsonDict:
    """Return the path-free plan fields that determine package bytes."""

    component_fields = (
        "kind",
        "id",
        "config_path",
        "registered_config_path",
        "component_root",
        "include",
        "exclude",
        "source_hints",
        "path_rewrites",
        "synthesized",
    )
    study_fields = (
        "kind",
        "id",
        "config_path",
        "registered_config_path",
        "environmentConfig",
        "methodConfig",
        "smoke",
    )

    def selected(items: Any, fields: tuple[str, ...]) -> List[JsonDict]:
        selected_items: List[JsonDict] = []
        for item in items or []:
            if not isinstance(item, dict):
                continue
            normalized: JsonDict = {}
            for field in fields:
                if field in {"include", "exclude", "source_hints", "path_rewrites"}:
                    normalized[field] = deepcopy(item.get(field, []) or [])
                elif field == "smoke":
                    normalized[field] = bool(item.get(field, False))
                elif field in item:
                    normalized[field] = deepcopy(item[field])
            selected_items.append(normalized)
        return selected_items

    return {
        "schema": "optpilot.package-plan-input.v2",
        "package_id": str(plan.get("package_id") or LOCAL_PACKAGE_NAME),
        "publication_scope": str(plan.get("publication_scope") or "curated-items"),
        "capture_excluded_directory_names": (
            list(CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS)
            if _is_configured_whole_package_plan(plan)
            else []
        ),
        "source_authority": deepcopy(plan.get("source_authority")),
        # Where captured software is recorded changes what Check composes, so
        # a changed answer invalidates checked artifacts like any other edit.
        "image_placement": str(plan.get("image_placement") or "component"),
        "classification": str(plan.get("classification") or ""),
        "components": selected(plan.get("components"), component_fields),
        "resources": selected(plan.get("resources"), component_fields),
        "studies": selected(plan.get("studies"), study_fields),
    }


def _package_plan_digest(plan: JsonDict) -> str:
    return request_digest(_package_plan_semantic_payload(plan))


def _package_plan_realm_runtime(state: UiState) -> LocalRealmRuntime:
    """Use Studio's one Realm, opening it lazily only in isolated UI tests."""

    runtime = state.realm_runtime
    if runtime is not None and not getattr(runtime, "closed", False):
        return runtime
    actor = (
        "studio-authoring-"
        + request_digest(
            {"schema": "optpilot.studio-authoring-principal.v1", "root": str(state.cwd)}
        )[:32]
    )
    runtime = LocalRealmRuntime.open(
        realm_root=state.cwd / ".optpilot-ui" / "realm",
        actor_principal_id=actor,
    )
    state.realm_runtime = runtime
    return runtime


def _current_package_plan_catalog_base(state: UiState, plan: JsonDict) -> JsonDict:
    package_id = _package_plan_package_id(plan.get("package_id"))
    runtime = _package_plan_realm_runtime(state)
    head = runtime.catalog.read_head(package_id=package_id)
    return {
        "schema": PACKAGE_PLAN_CATALOG_BASE_SCHEMA,
        "package_id": package_id,
        "head": None if head is None else head.to_dict(),
    }


def _package_plan_catalog_base_head(plan: JsonDict) -> CatalogPackageHead | None:
    base = plan.get("catalog_base")
    if not isinstance(base, dict) or base.get("schema") != (
        PACKAGE_PLAN_CATALOG_BASE_SCHEMA
    ):
        raise RealmConflict("Package plan has no validated catalog base.")
    package_id = _package_plan_package_id(plan.get("package_id"))
    if base.get("package_id") != package_id:
        raise RealmConflict("Package plan catalog base belongs to another package.")
    raw_head = base.get("head")
    if raw_head is None:
        return None
    if not isinstance(raw_head, dict):
        raise RealmConflict("Package plan catalog base head is invalid.")
    return CatalogPackageHead.from_dict(raw_head)


def _is_configured_whole_package_plan(plan: Mapping[str, Any]) -> bool:
    authority = plan.get("source_authority")
    return bool(
        plan.get("publication_scope") == CONFIGURED_SOURCE_PLAN_SCOPE
        and isinstance(authority, Mapping)
        and authority.get("kind") == "configured-catalog-source"
    )


def _package_plan_publisher_id(plan: JsonDict) -> str:
    if _is_configured_whole_package_plan(plan):
        authority = plan.get("source_authority")
        assert isinstance(authority, Mapping)
        expected = _configured_source_publisher_id(
            _package_plan_package_id(plan.get("package_id")),
            str(authority.get("source_id") or ""),
        )
    else:
        identity = plan.get("package_identity")
        if not isinstance(identity, str) or not identity:
            raise RealmConflict("Package plan has no package identity.")
        expected = _package_folder_publisher_id(
            _package_plan_package_id(plan.get("package_id")), identity
        )
    if plan.get("publisher_id") != expected:
        raise RealmConflict("Package plan publisher identity changed.")
    return expected


def _assert_configured_package_plan_authority(
    state: UiState, plan: Mapping[str, Any]
) -> Optional[JsonDict]:
    if not _is_configured_whole_package_plan(plan):
        return None
    workspace = _require_ui_workspace(state, str(plan.get("workspace_id") or ""))
    authority = _configured_source_workspace_authority(state, workspace)
    recorded = plan.get("source_authority")
    if (
        not isinstance(recorded, Mapping)
        or recorded.get("source_id") != authority["source_id"]
        or plan.get("package_id") != authority["package_id"]
        or plan.get("publisher_id") != authority["publisher_id"]
    ):
        raise RealmConflict("Configured source package-plan authority changed.")
    return authority


def _package_plan_artifact_owner_id(plan: JsonDict) -> str:
    return (
        "package-plan-owner-"
        + request_digest(
            {
                "schema": "optpilot.package-plan-owner.v1",
                "workspace_id": str(plan.get("workspace_id") or ""),
                "plan_id": str(plan.get("id") or ""),
            }
        )[:40]
    )


def _package_plan_workspace_anchor(state: UiState, plan: JsonDict) -> JsonDict:
    workspace = _require_ui_workspace(state, str(plan.get("workspace_id") or ""))
    realm_workspace_id = str(workspace.get("realm_workspace_id") or "")
    revision = workspace.get("realm_workspace_revision")
    if realm_workspace_id and isinstance(revision, int) and revision > 0:
        return {
            "kind": "managed-workspace",
            "workspace_id": realm_workspace_id,
            "workspace_revision": revision,
        }
    return {"kind": "sealed-package-source"}


def _package_plan_tree_source(plan: JsonDict, root: Path) -> AllowedTreeSource:
    """Bind the exact tree selection used by Check and stale-source probing."""

    return AllowedTreeSource(
        root,
        excluded_directory_names=(
            CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS
            if _is_configured_whole_package_plan(plan)
            else ()
        ),
    )


def _seal_package_plan_artifact(
    state: UiState,
    plan: JsonDict,
    package_root: Path,
) -> JsonDict:
    """Seal and retain the one package tree consumed by later phases."""

    runtime = _package_plan_realm_runtime(state)
    ledger = runtime.ledger
    actor = runtime.actor_principal_id
    owner_id = _package_plan_artifact_owner_id(plan)
    ledger.create_owner(
        operation_id=(
            "studio/package-plan/owner/"
            + request_digest(
                {
                    "workspace_id": str(plan.get("workspace_id") or ""),
                    "plan_id": str(plan.get("id") or ""),
                    "owner_id": owner_id,
                }
            )
        ),
        owner_id=owner_id,
        owner_kind="package-plan-artifact",
        principal_id=actor,
    )
    owner = ledger.read_owner(
        actor_principal_id=actor,
        owner_id=owner_id,
        permission=OwnerPermission.DERIVE,
    )
    if owner.state is not OwnerState.ACTIVE:
        raise RealmConflict("Package-plan artifact owner is not active.")
    current = tuple(
        item
        for item in ledger.list_owner_memberships(
            actor_principal_id=actor,
            owner_id=owner_id,
            permission=OwnerPermission.DERIVE,
        )
        if item.role == PACKAGE_PLAN_ARTIFACT_ROLE
    )
    if len(current) > 1:
        raise RealmConflict("Package-plan owner retains multiple artifact roots.")
    attempt = uuid.uuid4().hex
    change = ledger.begin_owner_change(
        operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/begin",
        actor_principal_id=actor,
        owner_id=owner_id,
        expected_owner_revision=owner.revision,
        ttl_seconds=300,
    )
    committed = False
    try:
        capture = runtime.content_service.capture(
            actor_principal_id=actor,
            change_id=change.change_id,
            store_id=runtime.content_store.store_id,
        )
        seal = capture.seal_tree(
            source=_package_plan_tree_source(plan, package_root),
            limits=SealLimits(
                max_entries=100_000,
                max_depth=64,
                max_total_bytes=20 * 1024**3,
                max_file_bytes=4 * 1024**3,
            ),
            operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/seal",
        )
        membership = OwnerMembership(
            runtime.content_store.store_id,
            seal.snapshot_ref,
            PACKAGE_PLAN_ARTIFACT_ROLE,
        )
        if current == (membership,):
            ledger.abort_owner_change(
                operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/unchanged",
                actor_principal_id=actor,
                change_id=change.change_id,
            )
            committed = True
            owner_revision = owner.revision
        else:
            ledger.hold_owner_content(
                operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/hold",
                actor_principal_id=actor,
                change_id=change.change_id,
                memberships=(membership,),
            )
            commit = ledger.commit_owner_change(
                operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/commit",
                actor_principal_id=actor,
                change_id=change.change_id,
                expected_owner_revision=owner.revision,
                additions=(membership,),
                removals=current,
            )
            committed = True
            owner_revision = commit.owner_revision
        result = {
            "schema": PACKAGE_PLAN_ARTIFACT_SCHEMA,
            "plan_digest": _package_plan_digest(plan),
            "owner_id": owner_id,
            "owner_revision": owner_revision,
            "store_id": runtime.content_store.store_id,
            "content_ref": str(seal.snapshot_ref),
            "logical_bytes": seal.manifest.logical_bytes,
            "file_count": sum(
                1 for item in seal.manifest.entries if item.kind == "file"
            ),
            "source": _package_plan_workspace_anchor(state, plan),
            "sealed_at": _now_iso(),
        }
        # Curated and whole-package registrations both seal a complete package
        # now -- one composed from the folder plus this work -- so both claim the
        # whole tree. One publisher owns the package, and each registration
        # replaces what the last one claimed.
        from optpilot.realm.configured_package_ingress import (
            whole_tree_catalog_paths,
        )

        result["owned_paths"] = list(whole_tree_catalog_paths(seal.manifest))
        return result
    finally:
        if not committed:
            try:
                ledger.abort_owner_change(
                    operation_id=f"studio/package-plan/{plan['id']}/artifact/{attempt}/abort",
                    actor_principal_id=actor,
                    change_id=change.change_id,
                )
            except (RealmConflict, RealmNotFound):
                pass


def _require_package_plan_artifact(state: UiState, plan: JsonDict) -> JsonDict:
    artifact = plan.get("artifact")
    if (
        not isinstance(artifact, dict)
        or artifact.get("schema") != PACKAGE_PLAN_ARTIFACT_SCHEMA
    ):
        raise RealmConflict("Package plan has no validated immutable artifact.")
    if artifact.get("plan_digest") != _package_plan_digest(plan):
        raise RealmConflict("Package plan changed; validate it again.")
    try:
        snapshot = SnapshotRef.parse(str(artifact.get("content_ref") or ""))
        owner_revision = int(artifact.get("owner_revision"))
    except (TypeError, ValueError) as error:
        raise RealmConflict("Package-plan artifact identity is invalid.") from error
    runtime = _package_plan_realm_runtime(state)
    if str(artifact.get("store_id") or "") != runtime.content_store.store_id:
        raise RealmConflict("Package-plan artifact store is unavailable.")
    owner = runtime.ledger.read_owner(
        actor_principal_id=runtime.actor_principal_id,
        owner_id=str(artifact.get("owner_id") or ""),
        permission=OwnerPermission.DERIVE,
    )
    if owner.state is not OwnerState.ACTIVE or owner.revision != owner_revision:
        raise RealmConflict("Package-plan artifact owner revision changed.")
    membership = OwnerMembership(
        runtime.content_store.store_id,
        snapshot,
        PACKAGE_PLAN_ARTIFACT_ROLE,
    )
    if membership not in runtime.ledger.list_owner_memberships(
        actor_principal_id=runtime.actor_principal_id,
        owner_id=owner.owner_id,
        permission=OwnerPermission.DERIVE,
    ):
        raise RealmConflict("Package-plan artifact is no longer retained.")
    if _is_configured_whole_package_plan(plan):
        from optpilot.realm.configured_package_ingress import (
            whole_tree_catalog_paths,
        )

        actual_paths = whole_tree_catalog_paths(
            runtime.content_store.verify_tree(snapshot, verify_children=False)
        )
        if tuple(artifact.get("owned_paths") or ()) != actual_paths:
            raise RealmConflict("Configured package artifact path ownership changed.")
    return artifact


def _assert_package_plan_source_unchanged(state: UiState, plan: JsonDict) -> None:
    """Re-seal the live plan input provisionally and compare immutable identity."""

    artifact = _require_package_plan_artifact(state, plan)
    runtime = _package_plan_realm_runtime(state)
    owner = runtime.ledger.read_owner(
        actor_principal_id=runtime.actor_principal_id,
        owner_id=str(artifact["owner_id"]),
        permission=OwnerPermission.DERIVE,
    )
    with tempfile.TemporaryDirectory(prefix="optpilot-package-plan-stale-") as tmp_dir:
        if _is_configured_whole_package_plan(plan):
            authority = _assert_configured_package_plan_authority(state, plan)
            if authority is None:
                raise RealmConflict("Configured source package authority is unavailable.")
            candidate_root = Path(authority["root"])
        else:
            candidate_root = _contained_output_path(
                Path(tmp_dir), Path(str(plan.get("package_id") or LOCAL_PACKAGE_NAME))
            )
            _compose_package_candidate(state, plan, candidate_root)
        attempt = uuid.uuid4().hex
        change = runtime.ledger.begin_owner_change(
            operation_id=f"studio/package-plan/{plan['id']}/probe/{attempt}/begin",
            actor_principal_id=runtime.actor_principal_id,
            owner_id=owner.owner_id,
            expected_owner_revision=owner.revision,
            ttl_seconds=300,
        )
        try:
            capture = runtime.content_service.capture(
                actor_principal_id=runtime.actor_principal_id,
                change_id=change.change_id,
                store_id=runtime.content_store.store_id,
            )
            seal = capture.seal_tree(
                source=_package_plan_tree_source(plan, candidate_root),
                limits=SealLimits(
                    max_entries=100_000,
                    max_depth=64,
                    max_total_bytes=20 * 1024**3,
                    max_file_bytes=4 * 1024**3,
                ),
                operation_id=f"studio/package-plan/{plan['id']}/probe/{attempt}/seal",
            )
            if str(seal.snapshot_ref) != str(artifact["content_ref"]):
                raise RealmConflict(
                    "Package plan source changed after validation; validate it again."
                )
        finally:
            try:
                runtime.ledger.abort_owner_change(
                    operation_id=f"studio/package-plan/{plan['id']}/probe/{attempt}/abort",
                    actor_principal_id=runtime.actor_principal_id,
                    change_id=change.change_id,
                )
            except (RealmConflict, RealmNotFound):
                pass


@contextmanager
def _open_package_plan_artifact(state: UiState, plan: JsonDict):
    artifact = _require_package_plan_artifact(state, plan)
    runtime = _package_plan_realm_runtime(state)
    snapshot = SnapshotRef.parse(str(artifact["content_ref"]))
    operation_key = uuid.uuid4().hex
    projection = runtime.projection_service.project_read_only(
        operation_id=f"studio/package-plan/{plan['id']}/projection/{operation_key}",
        actor_principal_id=runtime.actor_principal_id,
        store_id=str(artifact["store_id"]),
        spec=ProjectionSpec(
            owner_id=str(artifact["owner_id"]),
            mappings=(TreeMapping(snapshot),),
        ),
        holder_id=f"package-plan-{operation_key}",
        ttl_seconds=300,
        consumer_kind="package-plan",
        consumer_metadata={
            "plan_id": str(plan.get("id") or ""),
            "artifact_ref": str(snapshot),
        },
    )
    try:
        yield projection.root_path
    finally:
        projection.close()


def _configured_package_plan_validation(immutable_root: Path) -> JsonDict:
    """Adapt the established configured-source validator to Setup's Check UI."""

    result = _configured_package_static_validator(immutable_root)
    facts = _configured_package_validation_payload(result) or {
        "accepted": False,
        "digest": "",
        "facts": [],
    }
    errors = [
        f"{item['code']}: {item['count']}"
        for item in facts["facts"]
        if item["severity"] == "error" and int(item["count"]) > 0
    ]
    warnings = [
        f"{item['code']}: {item['count']}"
        for item in facts["facts"]
        if item["severity"] == "warning" and int(item["count"]) > 0
    ]
    return {
        "valid": bool(facts["accepted"]),
        "errors": errors,
        "warnings": warnings,
        "entries": [],
        "configured_source_validation": facts,
        "test_policy": "static-only",
    }


def _validate_package_plan(state: UiState, workspace_id: str, plan_id: str) -> JsonDict:
    plan = _read_package_plan(state, workspace_id, plan_id)
    if (
        str(plan.get("classification") or "") == "not-yet-classifiable"
        and not plan.get("source_authority")
    ):
        # Checking a folder that holds nothing OptPilot recognises used to run
        # on into the registration state machine and surface its internal
        # consistency assertion -- "checked registration setup lacks its exact
        # identity" -- which names nothing a person can act on. Say what is
        # missing instead, at the point they asked.
        #
        # Only for a folder with no source authority -- the case the state
        # machine cannot represent. A folder that IS a registered catalog
        # source and has since lost its entries keeps the real check: that path
        # produces facts a person can use, naming both the missing entries and
        # any stray yaml that was ignored, and refusing early would throw those
        # away. Measured, not assumed: the two cases are identical on
        # classification, package id, publisher and lineage, and differ only
        # here.
        raise ValueError(
            "This folder does not contain anything OptPilot recognises as a "
            "package yet, so there is nothing to check. Add at least one "
            "environment, method, or resource settings file to it, then try "
            "again."
        )
    workspace = _require_ui_workspace(state, workspace_id)
    if workspace.get("ownership") == "realm-managed":
        revision = _registration_workspace_revision(workspace)
        if revision is None:
            raise RealmConflict("Workspace revision is unavailable for Check.")
        committed = _commit_managed_workspace(
            state,
            workspace_id,
            {"expected_workspace_revision": revision},
        )
        workspace = committed["workspace"]
        plan["source_root"] = str(Path(str(workspace["root"])).resolve())
    _capture_installed_software(state, plan, workspace_id)
    previous_artifact = (
        plan.get("artifact") if isinstance(plan.get("artifact"), dict) else {}
    )
    previous_catalog_base = (
        plan.get("catalog_base") if isinstance(plan.get("catalog_base"), dict) else {}
    )
    previous_publication = (
        plan.get("publication") if isinstance(plan.get("publication"), dict) else {}
    )
    current_catalog_base = _current_package_plan_catalog_base(state, plan)
    with tempfile.TemporaryDirectory(prefix="optpilot-package-plan-") as tmp_dir:
        package_root = _contained_output_path(
            Path(tmp_dir),
            Path(str(plan.get("package_id") or LOCAL_PACKAGE_NAME)),
        )
        if _is_configured_whole_package_plan(plan):
            authority = _assert_configured_package_plan_authority(state, plan)
            if authority is None:
                raise RealmConflict("Configured source package authority is unavailable.")
            capture_root = Path(authority["root"])
        else:
            _compose_package_candidate(state, plan, package_root)
            capture_root = package_root
        artifact = _seal_package_plan_artifact(state, plan, capture_root)
        if _is_configured_whole_package_plan(plan):
            # Validate the retained immutable bytes, not the mutable folder
            # that happened to be present when Check began.
            plan["artifact"] = artifact
            with _open_package_plan_artifact(state, plan) as immutable_root:
                validation = _configured_package_plan_validation(immutable_root)
            curation = {"errors": [], "warnings": []}
        else:
            # Authoring validation is intentionally non-executing.  Importing or
            # constructing workspace Python belongs to the explicit Smoke action,
            # which consumes this exact immutable artifact.
            validation = validate_package(
                package_root,
                check_source=True,
                check_setup_files=True,
                check_imports=False,
            )
            hint_errors = _package_plan_source_hint_errors(plan, package_root)
            if hint_errors:
                validation["errors"] = [*validation.get("errors", []), *hint_errors]
                validation["valid"] = False
            curation = _package_plan_curation_checks(plan, package_root)
            if curation.get("errors"):
                validation["errors"] = [
                    *validation.get("errors", []),
                    *curation.get("errors", []),
                ]
                validation["valid"] = False
    validation["artifact_ref"] = artifact["content_ref"]
    validation["artifact_plan_digest"] = artifact["plan_digest"]
    warnings = (
        list(validation.get("warnings", []) or [])
        if _is_configured_whole_package_plan(plan)
        else _package_plan_warnings(plan, validation)
    )
    warnings.extend(
        str(item) for item in curation.get("warnings", []) or [] if str(item)
    )
    plan["validation"] = validation
    plan["artifact"] = artifact
    artifact_unchanged = previous_artifact.get("content_ref") == artifact.get(
        "content_ref"
    ) and previous_artifact.get("plan_digest") == artifact.get("plan_digest")
    if not artifact_unchanged:
        plan["smoke"] = {}
        plan["publication"] = {}
        plan["catalog_base"] = current_catalog_base
    elif (
        previous_publication.get("schema") == PACKAGE_PLAN_PUBLICATION_SCHEMA
        and previous_catalog_base.get("schema") == PACKAGE_PLAN_CATALOG_BASE_SCHEMA
    ):
        plan["publication"] = previous_publication
        plan["catalog_base"] = previous_catalog_base
    else:
        plan["publication"] = {}
        plan["catalog_base"] = current_catalog_base
    plan["curation"] = curation
    plan["warnings"] = warnings
    plan["readiness"] = (
        "component-ready"
        if _is_configured_whole_package_plan(plan) and validation.get("valid")
        else _package_plan_readiness(plan, validation)
    )
    plan["status"] = "validated" if validation.get("valid") else "invalid"
    plan["updated_at"] = _now_iso()
    _write_package_plan(state, workspace_id, plan)
    setup = _record_registration_check(
        state, workspace=workspace, plan=plan
    )
    return {
        "package_plan": plan,
        "workspace": workspace,
        "setup": _public_registration_setup(setup),
    }


def _smoke_package_plan(
    state: UiState, workspace_id: str, plan_id: str, payload: JsonDict
) -> JsonDict:
    plan = _read_package_plan(state, workspace_id, plan_id)
    if _is_configured_whole_package_plan(plan):
        raise ValueError(
            "Configured source registration uses static Check only and does not "
            "execute authored package code."
        )
    artifact = _require_package_plan_artifact(state, plan)
    _assert_package_plan_source_unchanged(state, plan)
    with tempfile.TemporaryDirectory(prefix="optpilot-package-plan-smoke-") as tmp_dir:
        tmp = Path(tmp_dir)
        package_root = _contained_output_path(
            tmp,
            Path(str(plan.get("package_id") or LOCAL_PACKAGE_NAME)),
        )
        with _open_package_plan_artifact(state, plan) as immutable_root:
            validation = validate_package(
                immutable_root,
                check_source=True,
                check_setup_files=True,
                check_imports=True,
            )
            hint_errors = _package_plan_source_hint_errors(plan, immutable_root)
            if hint_errors:
                validation["errors"] = [*validation.get("errors", []), *hint_errors]
                validation["valid"] = False
            curation = _package_plan_curation_checks(
                plan,
                immutable_root,
                execute_callables=True,
            )
            if curation.get("errors"):
                validation["errors"] = [
                    *validation.get("errors", []),
                    *curation.get("errors", []),
                ]
                validation["valid"] = False
            retained_execution = _package_retained_execution_capability(validation)
            if validation.get("valid") and (
                plan.get("classification") != "environment-plus-method"
                or retained_execution is None
                or not retained_execution_blocks_smoke(retained_execution)
            ):
                shutil.copytree(immutable_root, package_root)
                _make_tree_user_writable(package_root)
        if (
            plan.get("classification") == "environment-plus-method"
            and retained_execution is not None
            and retained_execution_blocks_smoke(retained_execution)
        ):
            result = {
                "valid": False,
                "code": str(
                    retained_execution.get("code") or "retained_execution_unsupported"
                ),
                "errors": [
                    str(
                        retained_execution.get("reason")
                        or "This package is not eligible for retained execution."
                    )
                ],
                "validation": validation,
                "curation": curation,
            }
        elif not validation.get("valid"):
            result = {
                "valid": False,
                "errors": ["Package plan validation failed."],
                "validation": validation,
                "curation": curation,
            }
        else:
            study_path = _select_plan_study(
                package_root,
                plan,
                str(payload.get("study") or payload.get("study_path") or ""),
            )
            if study_path is None:
                result = {
                    "valid": False,
                    "errors": ["No study is available for a smoke run."],
                }
            else:
                max_trials = int(payload.get("max_trials") or 0)
                _apply_smoke_trial_limit(study_path, max_trials)
                result = _run_temporary_realm_smoke(
                    state,
                    package_root=package_root,
                    study_path=study_path,
                    temporary_root=tmp,
                    timeout_seconds=min(
                        max(int(payload.get("timeout_seconds") or 120), 10),
                        300,
                    ),
                )
                result["study"] = _relative_path(study_path, package_root)
    result["artifact_ref"] = artifact["content_ref"]
    result["artifact_plan_digest"] = artifact["plan_digest"]
    plan["smoke"] = result
    plan["curation"] = curation
    warnings = _package_plan_warnings(plan, validation)
    warnings.extend(
        str(item) for item in curation.get("warnings", []) or [] if str(item)
    )
    plan["warnings"] = warnings
    if result.get("valid"):
        plan["readiness"] = "run-ready"
    plan["updated_at"] = _now_iso()
    _write_package_plan(state, workspace_id, plan)
    setup = _record_registration_test(
        state, workspace_id=workspace_id, result=result
    )
    return {
        "package_plan": plan,
        "smoke": result,
        "setup": _public_registration_setup(setup),
    }


def _make_tree_user_writable(root: Path) -> None:
    """Make one private derived copy writable; its immutable source stays read-only."""

    for path in (root, *root.rglob("*")):
        if path.is_symlink():
            raise ValueError("Package artifact unexpectedly contains a symlink.")
        mode = path.stat().st_mode
        path.chmod(mode | (0o700 if path.is_dir() else 0o200))


def _package_plan_existing_publication_head(
    state: UiState,
    plan: JsonDict,
    artifact: JsonDict,
    owned_paths: List[str],
) -> CatalogPackageHead | None:
    publication = plan.get("publication")
    if (
        not isinstance(publication, dict)
        or publication.get("schema") != PACKAGE_PLAN_PUBLICATION_SCHEMA
        or publication.get("package_id") != plan.get("package_id")
        or publication.get("publisher_id") != _package_plan_publisher_id(plan)
        or publication.get("artifact_ref") != artifact.get("content_ref")
        or publication.get("plan_digest") != artifact.get("plan_digest")
    ):
        return None
    runtime = _package_plan_realm_runtime(state)
    head = runtime.catalog.read_head(package_id=str(plan["package_id"]))
    if head is None:
        return None
    manifest = runtime.catalog.read_revision(
        package_id=head.package_id,
        revision=head.revision,
    )
    try:
        application = manifest.application(_package_plan_publisher_id(plan))
    except KeyError:
        return None
    if (
        str(application.artifact_ref) != str(artifact.get("content_ref") or "")
        or application.owned_paths != tuple(owned_paths)
        or application.plan_digest != artifact.get("plan_digest")
    ):
        return None
    return head


def _begin_registration_publication_action(
    state: UiState,
    *,
    workspace_id: str,
    package_id: str,
    publisher_id: str,
    artifact: Mapping[str, Any],
    expected_head: CatalogPackageHead | None,
    validation_digest: str,
    core_operation_id: str,
) -> Any:
    setup = _current_registration_setup(state, workspace_id)
    if setup is None:
        return None
    check = setup.data.check
    if (
        setup.data.state
        not in {
            RegistrationSetupState.CHECKED,
            RegistrationSetupState.REGISTERED,
        }
        or check is None
        or not check.accepted
        or str(check.artifact_ref) != str(artifact.get("content_ref") or "")
        or setup.data.package_id != package_id
        or setup.data.publisher_id != publisher_id
        or (
            setup.data.test is not None
            and not setup.data.test.accepted
        )
    ):
        raise RealmConflict(
            "Workspace Setup changed; check the current files before registering."
        )
    artifact_digest = SnapshotRef.parse(str(artifact["content_ref"])).digest
    source = EntityCoordinate(
        kind="workspace",
        entity_id=workspace_id,
        revision=check.workspace_revision,
        digest=artifact_digest,
    )
    parameters = {
        "artifact_ref": str(check.artifact_ref),
        "expected_catalog_head": (
            None if expected_head is None else expected_head.to_dict()
        ),
        "package_id": package_id,
        "publisher_id": publisher_id,
        "validation_digest": validation_digest,
    }
    intent_id = "registration_" + request_digest(
        {
            "parameters": parameters,
            "schema": "optpilot.registration-publication-intent.v1",
            "source": source.to_dict(),
        }
    )
    expected_digest = ActionIntentRecord.compute_intent_digest(
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="catalog-publication",
        source=source,
        parameters=parameters,
    )
    try:
        current = state.coordination.get_action(intent_id)
    except CoordinationNotFound:
        current = None
    if current is not None:
        if current.intent_digest != expected_digest:
            raise CoordinationConflict(
                "Registration intent was already used for another checked version."
            )
        if current.core_operation_id != core_operation_id:
            raise CoordinationConflict("Registration Core operation identity changed.")
        if current.state is ActionState.FAILED:
            raise RealmConflict(
                current.error_message or "The previous registration attempt failed."
            )
        if current.state is ActionState.UNCERTAIN:
            return state.coordination.retry_action(
                operation_id=(
                    f"studio/action/{intent_id}/retry/{current.revision}"
                ),
                intent_id=intent_id,
            )
        return current
    return state.coordination.begin_action(
        operation_id=f"studio/action/{intent_id}/begin",
        intent_id=intent_id,
        actor_id=_studio_actor_id(state),
        action_kind="catalog-publication",
        source=source,
        parameters=parameters,
        core_operation_id=core_operation_id,
    )


def _complete_registration_publication(
    state: UiState,
    *,
    workspace_id: str,
    intent: Any,
    package_id: str,
    publisher_id: str,
    artifact: Mapping[str, Any],
    head: CatalogPackageHead,
) -> Any:
    if intent is None:
        return None
    result = EntityCoordinate(
        kind="catalog-package",
        entity_id=package_id,
        revision=head.revision,
        digest=head.manifest_digest,
    )
    if intent.state is not ActionState.SUCCEEDED:
        intent = state.coordination.complete_action(
            operation_id=f"studio/action/{intent.intent_id}/complete",
            intent_id=intent.intent_id,
            result=result,
            core_receipt={
                "artifact_ref": str(artifact["content_ref"]),
                "head": head.to_dict(),
                "package_id": package_id,
                "publisher_id": publisher_id,
            },
        )
    setup = _current_registration_setup(state, workspace_id)
    if setup is None:
        return None
    data = replace(
        setup.data,
        state=RegistrationSetupState.REGISTERED,
        publication_intent_id=intent.intent_id,
        publication_result=result,
    )
    return _save_registration_setup_data(
        state, workspace_id=workspace_id, data=data
    )


def _apply_package_plan(state: UiState, workspace_id: str, plan_id: str) -> JsonDict:
    plan = _read_package_plan(state, workspace_id, plan_id)
    if not isinstance(plan.get("artifact"), dict) or not plan.get("artifact"):
        plan = _validate_package_plan(state, workspace_id, plan_id)["package_plan"]
    artifact = _require_package_plan_artifact(state, plan)
    _assert_package_plan_source_unchanged(state, plan)
    if not plan.get("validation", {}).get("valid"):
        return {"package_plan": plan, "applied": False}
    if plan.get("validation", {}).get("artifact_ref") != artifact.get(
        "content_ref"
    ) or plan.get("validation", {}).get("artifact_plan_digest") != artifact.get(
        "plan_digest"
    ):
        raise RealmConflict("Package validation does not belong to this artifact.")
    requires_smoke = (
        plan.get("classification") == "environment-plus-method"
        and not _is_configured_whole_package_plan(plan)
    )
    if requires_smoke and not plan.get("smoke", {}).get("valid"):
        plan.setdefault("warnings", []).append(
            "Run and pass Test before registering an environment-plus-method package."
        )
        plan["readiness"] = "component-ready"
        plan["status"] = "blocked"
        _write_package_plan(state, workspace_id, plan)
        return {"package_plan": plan, "applied": False}
    if requires_smoke and (
        plan.get("smoke", {}).get("artifact_ref") != artifact.get("content_ref")
        or plan.get("smoke", {}).get("artifact_plan_digest")
        != artifact.get("plan_digest")
    ):
        raise RealmConflict("Package smoke result does not belong to this artifact.")
    package_id = _package_plan_package_id(plan.get("package_id"))
    software_change = dict(plan.get("software_change") or {"state": "unknown"})
    if (
        software_change.get("state") != "unchanged"
        and not plan.get("captured_image")
    ):
        # The package already holds an image, so where this addition goes is
        # the author's decision, and asking is not built yet. Saying so beats
        # silently placing it either way.
        plan.setdefault("warnings", []).append(
            "Software may have been installed in this workspace since it "
            "started, and the package already declares an image. Choosing "
            "where the addition goes is not supported yet, so the registered "
            "component records the package's existing image."
        )
    # Before anything is published: was this work built on the package as it now
    # stands? If not, it would replace work it never saw. Checked here rather
    # than at the folder write, which happens after publication and treats its
    # own failures as non-fatal.
    if not _is_configured_whole_package_plan(plan):
        _assert_package_selection_not_moved_on(
            state.cwd / CATALOG_DIR_NAME / package_id, plan, package_id=package_id
        )
    publisher_id = _package_plan_publisher_id(plan)
    owned_paths = _package_plan_owned_paths(plan)
    runtime = _package_plan_realm_runtime(state)
    expected_head = _package_plan_catalog_base_head(plan)
    validation_digest = _registration_validation_digest(plan)
    smoke_digest = (
        request_digest(
            {
                "schema": "optpilot.package-plan-smoke-evidence.v1",
                "artifact_ref": artifact["content_ref"],
                "smoke": plan.get("smoke", {}),
            }
        )
        if plan.get("smoke", {}).get("valid")
        else None
    )
    publication_identity = request_digest(
        {
            "schema": "optpilot.studio-package-plan-publication.v1",
            "artifact": {
                "content_ref": artifact["content_ref"],
                "owner_id": artifact["owner_id"],
                "owner_revision": artifact["owner_revision"],
                "store_id": artifact["store_id"],
            },
            "expected_head": (
                None if expected_head is None else expected_head.to_dict()
            ),
            "owned_paths": owned_paths,
            "package_id": package_id,
            "plan_digest": artifact["plan_digest"],
            "publisher_id": publisher_id,
            "smoke_digest": smoke_digest,
            "validation_digest": validation_digest,
        }
    )
    operation_id = "studio/package-plan/catalog-publish/" + publication_identity
    publication_intent = _begin_registration_publication_action(
        state,
        workspace_id=workspace_id,
        package_id=package_id,
        publisher_id=publisher_id,
        artifact=artifact,
        expected_head=expected_head,
        validation_digest=validation_digest,
        core_operation_id=operation_id,
    )
    registration_setup = None
    with _PACKAGE_PLAN_APPLY_LOCK:
        published_head = _package_plan_existing_publication_head(
            state,
            plan,
            artifact,
            owned_paths,
        )
        if published_head is None:
            try:
                receipt = runtime.catalog.publish(
                    operation_id=operation_id,
                    package_id=package_id,
                    publisher_id=publisher_id,
                    source_owner_id=str(artifact["owner_id"]),
                    expected_source_owner_revision=int(artifact["owner_revision"]),
                    source_store_id=str(artifact["store_id"]),
                    source_role=PACKAGE_PLAN_ARTIFACT_ROLE,
                    root_ref=SnapshotRef.parse(str(artifact["content_ref"])),
                    owned_paths=tuple(owned_paths),
                    plan_digest=str(artifact["plan_digest"]),
                    validation_digest=validation_digest,
                    smoke_digest=smoke_digest,
                    expected_head=expected_head,
                )
            except RealmConflict as error:
                if _is_configured_whole_package_plan(plan) and (
                    "catalog package head changed" in str(error).lower()
                ):
                    raise ConfiguredPackagePublishPublicError(
                        "The Catalog version changed after Check; check the current "
                        "folder again before registering.",
                        code="configured_package_head_changed",
                    ) from error
                raise
            except ValueError as error:
                if _is_configured_whole_package_plan(plan) and (
                    "overlapping path claims" in str(error)
                    or "owned by another" in str(error)
                ):
                    raise ConfiguredPackagePublishPublicError(
                        "Another Catalog publisher owns overlapping paths; "
                        "explicit curation or ownership transfer is required.",
                        code="configured_package_ownership_conflict",
                    ) from error
                raise
            published_head = receipt.head
            plan["publication"] = {
                "schema": PACKAGE_PLAN_PUBLICATION_SCHEMA,
                "operation_id": operation_id,
                "package_id": package_id,
                "publisher_id": publisher_id,
                "artifact_ref": artifact["content_ref"],
                "artifact_owner_id": artifact["owner_id"],
                "artifact_owner_revision": artifact["owner_revision"],
                "plan_digest": artifact["plan_digest"],
                "validation_digest": validation_digest,
                "smoke_digest": smoke_digest,
                "expected_head": (
                    None if expected_head is None else expected_head.to_dict()
                ),
                "published_head": receipt.head.to_dict(),
                "revision_owner_id": receipt.owner.owner_id,
                "published_at": _now_iso(),
            }
        # Publication is the durable outcome.  A filesystem projection is only
        # a rebuildable realization and must never turn a committed publication
        # into an apparent failure.
        now = _now_iso()
        plan["publication"]["current_head"] = published_head.to_dict()
        plan["publication"]["realization"] = {
            "status": "pending",
            "updated_at": now,
        }
        plan["owned_paths"] = owned_paths
        plan["status"] = "applied"
        plan["applied_at"] = now
        plan["updated_at"] = now
        _write_package_plan(state, workspace_id, plan)

        workspace = dict(_require_ui_workspace(state, workspace_id))
        applied_entries = _package_plan_workspace_registration_entries(
            plan,
            workspace=workspace,
            registered_at=now,
        )
        workspace["registered_entries"] = applied_entries
        publication_summary = {
            "schema": PACKAGE_PLAN_PUBLICATION_SCHEMA,
            "plan_id": str(plan.get("id") or ""),
            "package_id": package_id,
            "publisher_id": publisher_id,
            "revision": published_head.revision,
            "manifest_digest": published_head.manifest_digest,
            "entries": [
                {
                    "kind": str(item.get("kind") or ""),
                    "id": str(item.get("id") or ""),
                    "catalog_relative_path": str(
                        item.get("catalog_relative_path") or ""
                    ),
                }
                for item in applied_entries
            ],
            "published_at": str(plan["publication"].get("published_at") or now),
        }
        prior_publications = [
            item
            for item in workspace.get("catalog_publications", []) or []
            if isinstance(item, dict)
            and str(item.get("publisher_id") or "") != publisher_id
        ]
        workspace["catalog_publications"] = [
            *prior_publications,
            publication_summary,
        ]
        workspace = _upsert_ui_workspace(state, workspace)
        registration_setup = _complete_registration_publication(
            state,
            workspace_id=workspace_id,
            intent=publication_intent,
            package_id=package_id,
            publisher_id=publisher_id,
            artifact=artifact,
            head=published_head,
        )

        try:
            _refresh_realm_catalog_projections(state)
            projection_record = state._realm_catalog_projections.get(package_id)
            if (
                projection_record is None
                or projection_record.get("manifest_digest")
                != published_head.manifest_digest
            ):
                raise RealmIntegrityError(
                    "Published catalog head has no matching Studio realization."
                )
            _mirror_published_package_to_folder(
                state,
                plan=plan,
                package_id=package_id,
                projection_root=Path(str(projection_record["root"])),
            )
            # This registration is now the version of its own paths that the
            # package holds, so its base advances to match. Without this, an
            # author registering an update to their own component would be
            # refused for having moved the package on themselves.
            plan["catalog_selection_fingerprint"] = _package_selection_fingerprint(
                state.cwd / CATALOG_DIR_NAME / package_id,
                _package_plan_selection_paths(plan),
            )
        except Exception as error:
            plan["publication"]["realization"] = {
                "status": "pending",
                "reason_code": "catalog_projection_unavailable",
                "error_type": type(error).__name__,
                "updated_at": _now_iso(),
            }
        else:
            plan["publication"]["realization"] = {
                "status": "ready",
                "updated_at": _now_iso(),
            }
        plan["updated_at"] = _now_iso()
        _write_package_plan(state, workspace_id, plan)
    return {
        "package_plan": plan,
        "workspace": workspace,
        "setup": _public_registration_setup(registration_setup),
        "applied": True,
        "catalog": {
            "package_id": package_id,
            "head": published_head.to_dict(),
            "realization": deepcopy(plan["publication"]["realization"]),
        },
    }


def _package_plan_workspace_registration_entries(
    plan: JsonDict,
    *,
    workspace: JsonDict,
    registered_at: str,
) -> List[JsonDict]:
    """Build portable authoring and catalog coordinates for one publication."""

    workspace_root = Path(str(workspace.get("root") or ".")).resolve()
    package_id = _package_plan_package_id(plan.get("package_id"))

    def source_config_path(item: JsonDict) -> str:
        value = str(item.get("config_path") or "").strip()
        if not value:
            return ""
        path = Path(value)
        if path.is_absolute():
            try:
                return path.resolve().relative_to(workspace_root).as_posix()
            except ValueError as error:
                raise RealmConflict(
                    "Package-plan config path is outside its authoring workspace."
                ) from error
        return _safe_relative_plan_path(
            value, "package-plan authoring config path"
        ).as_posix()

    entries: List[JsonDict] = []
    if _is_configured_whole_package_plan(plan):
        for item in [
            *(plan.get("components", []) or []),
            *(plan.get("resources", []) or []),
            *(plan.get("studies", []) or []),
        ]:
            if not isinstance(item, dict) or not item.get("config_path"):
                continue
            relative = source_config_path(item)
            entries.append(
                {
                    "kind": str(item.get("kind") or ""),
                    "id": str(item.get("id") or ""),
                    "authoring_relative_path": relative,
                    "catalog_relative_path": relative,
                    "catalog_uri": _package_plan_catalog_destination(
                        package_id, relative
                    ),
                    "registered_at": registered_at,
                }
            )
        return entries
    for item in [
        *(plan.get("components", []) or []),
        *(plan.get("resources", []) or []),
    ]:
        if not isinstance(item, dict):
            continue
        config_name = str(
            item.get("registered_config_path")
            or _registered_config_filename(str(item.get("kind") or ""), "")
        )
        relative = (
            _safe_relative_plan_path(
                str(item.get("component_root") or ""),
                "package-plan component root",
            )
            / config_name
        ).as_posix()
        entries.append(
            {
                "kind": str(item.get("kind") or ""),
                "id": str(item.get("id") or ""),
                "authoring_relative_path": source_config_path(item),
                "catalog_relative_path": relative,
                "catalog_uri": _package_plan_catalog_destination(package_id, relative),
                "registered_at": registered_at,
            }
        )
    for item in plan.get("studies", []) or []:
        if not isinstance(item, dict):
            continue
        relative = _safe_relative_plan_path(
            str(item.get("registered_config_path") or ""),
            "package-plan study config path",
        ).as_posix()
        entries.append(
            {
                "kind": "study",
                "id": str(item.get("id") or ""),
                "authoring_relative_path": source_config_path(item),
                "catalog_relative_path": relative,
                "catalog_uri": _package_plan_catalog_destination(package_id, relative),
                "registered_at": registered_at,
            }
        )
    return entries


def _package_plan_owned_paths(plan: JsonDict) -> List[str]:
    if True:  # every plan now seals a complete package
        artifact = plan.get("artifact")
        paths = (
            artifact.get("owned_paths")
            if isinstance(artifact, Mapping)
            else None
        )
        if not isinstance(paths, list) or not paths:
            raise RealmConflict(
                "Configured package Check has no exact whole-package path claims."
            )
        canonical = [
            _safe_relative_plan_path(str(path), "configured package owned path").as_posix()
            for path in paths
        ]
        if canonical != sorted(set(canonical), key=lambda item: item.encode("utf-8")):
            raise RealmConflict("Configured package owned paths are not canonical.")
        return canonical
    paths: List[str] = []
    for item in [
        *(plan.get("components", []) or []),
        *(plan.get("resources", []) or []),
    ]:
        if not isinstance(item, dict):
            continue
        path = _safe_relative_plan_path(
            str(item.get("component_root") or ""),
            "package-plan owned component path",
        ).as_posix()
        paths.append(path)
    for item in plan.get("studies", []) or []:
        if not isinstance(item, dict):
            continue
        path = _safe_relative_plan_path(
            str(item.get("registered_config_path") or ""),
            "package-plan owned study path",
        ).as_posix()
        paths.append(path)
    ordered = sorted(set(paths))
    if not ordered:
        raise ValueError("Package plan does not contain any owned artifact paths.")
    if len(ordered) != len(paths):
        raise ValueError("Package plan contains duplicate owned paths.")
    for index, path in enumerate(ordered):
        for other in ordered[index + 1 :]:
            if _package_plan_paths_overlap(path, other):
                raise ValueError(
                    f"Package plan owned paths overlap: {path!r} and {other!r}."
                )
    return ordered


def _workspace_package_image(state: "UiState", workspace: JsonDict) -> Optional[str]:
    """The image this workspace should run in, or None for the default.

    A workspace runs in the image its package's code will run in, so what works
    while building works in a run. The image passes the same checks a run
    performs -- declared pinned, approved for study execution, present on this
    machine with the declared fingerprint and architecture -- because opening a
    workspace on an image executes that image just as surely as a run does.
    """

    root_text = str(workspace.get("root") or "")
    if not root_text:
        return None
    try:
        settings = load_package_settings(Path(root_text))
    except (ValueError, OSError):
        # A malformed settings file is reported by the catalog view; opening
        # the workspace on the default image keeps the folder reachable so the
        # file can be fixed from inside it.
        return None
    if settings is None or settings.container is None:
        return None
    container = settings.container
    from optpilot.container_engine import (
        ContainerEngineError,
        resolve_container_engine,
        verify_image_available,
    )
    from optpilot.realm.provider_trust_records import (
        PROVIDER_TRUST_EXECUTION_CONTRACT,
    )

    try:
        engine = resolve_container_engine()
    except ContainerEngineError as error:
        raise RuntimeError(
            f"This package declares an image, and {error}"
        ) from error
    runtime = _require_realm_runtime(state)
    approval = None
    trust = getattr(runtime, "provider_trust_policy", None)
    if trust is not None:
        try:
            approval = trust.read_active(
                image_ref=container.image.raw,
                contract=PROVIDER_TRUST_EXECUTION_CONTRACT,
            )
        except Exception:
            approval = None
    if approval is None:
        from optpilot.realm.provider_trust_records import image_approval_remedy

        raise _with_remedy(
            RuntimeError(
                f"The package's image {container.image.raw} has not been "
                "approved for study execution, and a workspace runs it just as "
                f"surely as a run does. "
                f"{image_approval_remedy(container.image.raw)}"
            ),
            _remedy(
                "Only the person can approve an image. Ask them to run this "
                "command, and do not retry until they say they have.",
                command=f"optpilot image approve {container.image.raw}",
                details={"image": container.image.raw, "purpose": "execution"},
            ),
        )
    try:
        verify_image_available(engine, container.image.raw, container.platform)
    except ContainerEngineError as error:
        raise RuntimeError(str(error)) from error
    return container.image.raw


def _bundled_catalog_root() -> Optional[Path]:
    """The catalog inside OptPilot's own source tree, if this is a checkout.

    A checkout's catalog folder is OptPilot's own tracked files: registering
    into one would edit OptPilot rather than the person's work, so it stays a
    read-only registration target. The copies in the person's own packages
    folder are not this, and are freely registerable -- which is the whole
    point of copying them out.
    """

    try:
        import optpilot

        module_root = Path(optpilot.__file__).resolve().parent  # .../src/optpilot
        return module_root.parent.parent / CATALOG_DIR_NAME
    except Exception:
        return None


def _is_bundled_catalog_package(package_root: Path) -> bool:
    """Whether this folder is one of the packages shipped with OptPilot.

    Those are tracked in OptPilot's own repository, so registering into one
    would edit OptPilot itself rather than the author's work. They are
    read-only registration targets: registering creates a package of the
    author's own instead.
    """

    bundled = _bundled_catalog_root()
    if bundled is None:
        return False
    try:
        package_root.resolve().relative_to(bundled.resolve())
    except (ValueError, OSError):
        return False
    return True


def _append_component_runtime_override(
    config_path: Path, *, image: str, platform: str
) -> None:
    """Record a component's image by appending to its settings file.

    Appending, never rewriting: a settings file a person wrote holds comments
    and formatting that a rewrite through the settings machinery would destroy,
    and the loss would be invisible to everything except the person who wrote
    them. The one case appending cannot handle -- the file already has a
    runtime section -- refuses with the exact lines to add, rather than writing
    a second section that contradicts the first.
    """

    text = config_path.read_text(encoding="utf-8")
    addition = (
        "\n"
        "# Recorded at registration: the software installed in the workspace,\n"
        "# captured as an image for this component only.\n"
        "runtime:\n"
        "  sandbox: container\n"
        "  container:\n"
        f"    image: {image}\n"
        f"    platform: {platform}\n"
    )
    if re.search(r"^runtime\s*:", text, re.MULTILINE):
        raise RealmConflict(
            f"{config_path.name} already has a runtime section, so the "
            "captured image cannot be recorded automatically without "
            "rewriting your file. Add these lines to its runtime section "
            "yourself, then check again:\n"
            f"    container:\n      image: {image}\n      platform: {platform}"
        )
    config_path.write_text(
        text.rstrip("\n") + "\n" + addition, encoding="utf-8"
    )


def _capture_installed_software(
    state: "UiState", plan: JsonDict, workspace_id: str
) -> None:
    """Registration's automatic image branch: capture into an image-less package.

    The design's step three has two halves. When the package has no image, the
    captured software BECOMES the package's image -- automatic, no question to
    ask, because there is nothing else in the package for the answer to affect.
    When the package already has an image, where the addition goes is the
    author's decision: the browser asks before Check, and unattended
    registration takes the default (the component).

    Runs at Check rather than at Register, because the fingerprint lands in the
    package's own settings file, which is part of the sealed, validated bytes.
    Capturing later would publish a package whose settings the validation never
    saw.
    """

    change = _workspace_software_change(state, workspace_id)
    plan["software_change"] = change
    plan.pop("captured_image", None)
    if change.get("state") == "unchanged":
        return
    package_id = _package_plan_package_id(plan.get("package_id"))
    try:
        existing = load_package_settings(state.cwd / CATALOG_DIR_NAME / package_id)
    except (ValueError, OSError):
        existing = None
    placement = str(plan.get("image_placement") or "component")
    if placement not in ("component", "package"):
        raise RealmConflict(
            "image_placement must be 'component' or 'package'."
        )
    captured = state.workspace_runtime.capture_workspace_image(
        workspace_id, tag=f"optpilot-capture-{_slug_text(package_id)[:40]}"
    )
    if captured is None:
        return
    plan["captured_image"] = captured
    if existing is not None and existing.container is not None:
        # The package already has an image, so where the addition goes is the
        # author's decision. The default is the narrower, reversible act:
        # record it on the components being registered, leaving everything
        # else in the package on the image it already uses. Unattended
        # registration takes the default without asking.
        plan["captured_image_placement"] = placement
    else:
        # No existing image: the capture becomes the package's, automatically,
        # because there is nothing else in the package for a choice to affect.
        plan["captured_image_placement"] = "package"


def _decorate_plan_software_state(
    state: "UiState", workspace_id: str, plan: JsonDict
) -> JsonDict:
    """Tell the browser, at Setup time, whether the placement question applies.

    The question -- where a captured image should be recorded -- is asked
    before Check runs, so the browser needs two advisory facts up front:
    whether software was installed since the workspace started, and whether
    the package already has an image (an image-less package takes the capture
    automatically, no question to ask). Check recomputes both; these are for
    the dialog, not the record.
    """

    plan["software_change"] = _workspace_software_change(state, workspace_id)
    package_id = _package_plan_package_id(plan.get("package_id"))
    try:
        existing = load_package_settings(state.cwd / CATALOG_DIR_NAME / package_id)
        plan["package_has_image"] = (
            existing is not None and existing.container is not None
        )
    except (ValueError, OSError):
        plan["package_has_image"] = False
    return plan


def _workspace_software_change(state: "UiState", workspace_id: str) -> JsonDict:
    """Whether software was installed in this workspace since it started.

    Three honest answers. "unchanged": the inventories match, so registering
    needs no image capture -- the starting image already describes what the
    code needs. "changed": something was installed; until capture is built,
    the registration says so rather than silently recording an image that no
    longer matches the workspace. "unknown": no baseline or no probe, which
    registration must treat as possibly-changed, never as clean.
    """

    manager = state.workspace_runtime
    try:
        record = manager._read_record(workspace_id)
    except Exception:
        return {"state": "unknown", "reason": "no workspace runtime record"}
    baseline = str(record.get("software_inventory_digest") or "")
    if not baseline:
        return {"state": "unknown", "reason": "no starting inventory"}
    current = manager.software_inventory(workspace_id)
    if current is None:
        return {"state": "unknown", "reason": "inventory probe failed"}
    if current["digest"] == baseline:
        return {"state": "unchanged"}
    return {"state": "changed", "baseline": baseline, "current": current["digest"]}


def _package_plan_catalog_folder(
    state: UiState, plan: JsonDict, package_id: str
) -> Optional[Path]:
    """Where this registration's package folder lives, or None to write none.

    A whole-package registration from a configured folder already has the
    folder as its source, so writing one back would be circular.
    """

    if _is_configured_whole_package_plan(plan):
        return None
    folder = (state.cwd / CATALOG_DIR_NAME / package_id).resolve()
    elsewhere = [
        root
        for root in state.catalog_roots
        if root.name == package_id and root.resolve() != folder
    ]
    if elsewhere:
        # The package already has a folder somewhere the author chose. Writing a
        # second one under the project's own catalog directory would leave two
        # folders claiming the same package, which reads as an ambiguous
        # identity and forks the package in two.
        return None
    if _is_bundled_catalog_package(folder):
        raise _with_remedy(
            RealmConflict(
                f"{package_id} ships with OptPilot and cannot be registered "
                "into. Register into a package of your own instead."
            ),
            _remedy(
                "Register into a package of your own. To build on this one, "
                "copy its folder under a new name and give the copy a "
                "different identity value, then register the copy.",
                details={"package": package_id, "reason": "ships_with_optpilot"},
            ),
        )
    return folder


#: All registrations write the whole published tree, so ownership is recorded
#: once per package rather than once per plan. Keeping it per-plan would leave a
#: folder holding only the most recent registration's files while the published
#: package held more, and nothing would ever reconcile the two.
CATALOG_FOLDER_OWNER_WORKSPACE = "catalog"
CATALOG_FOLDER_OWNER_PLAN = "published-head"


def _package_folder_fingerprint(package_root: Path) -> str:
    """A fingerprint of everything in a package folder that counts as content.

    OptPilot's own bookkeeping under `.optpilot` is skipped, matching what a seal
    of this folder would capture, so writing bookkeeping never looks like the
    author having edited the package.
    """

    entries: List[str] = []
    if package_root.is_dir():
        for path in sorted(package_root.rglob("*")):
            if any(part in CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS for part in path.parts):
                continue
            if not path.is_file() or path.is_symlink():
                continue
            relative = path.relative_to(package_root).as_posix()
            entries.append(f"{relative}:{hashlib.sha256(path.read_bytes()).hexdigest()}")
    return hashlib.sha256("\n".join(entries).encode("utf-8")).hexdigest()


def _package_selection_fingerprint(
    package_root: Path, selection_paths: Iterable[str]
) -> str:
    """Fingerprint only the parts of a package that one piece of work covers."""

    entries: List[str] = []
    for relative in sorted(selection_paths):
        target = package_root / relative
        if target.is_dir():
            for path in sorted(target.rglob("*")):
                if any(
                    part in CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS
                    for part in path.parts
                ):
                    continue
                if not path.is_file() or path.is_symlink():
                    continue
                entries.append(
                    f"{path.relative_to(package_root).as_posix()}:"
                    f"{hashlib.sha256(path.read_bytes()).hexdigest()}"
                )
        elif target.is_file():
            entries.append(
                f"{relative}:{hashlib.sha256(target.read_bytes()).hexdigest()}"
            )
        else:
            entries.append(f"{relative}:absent")
    return hashlib.sha256("\n".join(entries).encode("utf-8")).hexdigest()


def _assert_package_selection_not_moved_on(
    package_root: Path, plan: JsonDict, *, package_id: str
) -> None:
    """Refuse when what this work covers changed after the work started.

    Registering composes the package from the folder as it stands and replaces
    only the paths this work covers, so anything it does not cover is carried
    through untouched -- a second piece of work can never destroy an unrelated
    one. What it can destroy is a change made to its own paths since it began:
    an edit in the folder, or another registration of the same component.

    Scoping the comparison to those paths is what makes editing one component in
    the folder while registering a different one work, which it must, since the
    author may be holding an editable copy of a single component rather than the
    whole package.
    """

    base = plan.get("catalog_selection_fingerprint")
    if not isinstance(base, str):
        return
    current = _package_selection_fingerprint(
        package_root, _package_plan_selection_paths(plan)
    )
    if current == base:
        return
    raise RealmConflict(
        f"Part of the {package_id} package that this work changes has itself "
        "changed since the work started, so this was built on an older version "
        "of it. Nothing has been written. Bring your changes onto the current "
        "package and register again."
    )


def _assert_package_folder_not_moved_on(
    package_root: Path, ownership: JsonDict, *, package_id: str
) -> None:
    """Refuse to write when the folder changed since OptPilot last wrote it.

    The catalog belongs to one person, so there is exactly one lineage per
    package and registration only ever moves it forward. If the folder still
    matches what was last written, overwriting it loses nothing by definition.
    If it does not -- because the author edited it directly, or because another
    workspace registered into it -- then the work being registered was built on
    an older picture of the package, and writing it would silently discard
    whatever moved the folder on.

    Refusing is the whole point: there is no safe way to merge the two, and
    quietly preferring either one destroys work the author cannot get back.
    """

    recorded = ownership.get("folder_fingerprint")
    if not recorded:
        return
    current = _package_folder_fingerprint(package_root)
    if current == recorded:
        return
    raise RealmConflict(
        f"The {package_id} package folder has changed since it was last "
        "registered, so this work was built on an older version of it. Nothing "
        "has been written. Bring your changes onto the current package folder "
        "and register again."
    )


def _mirror_published_package_to_folder(
    state: UiState,
    *,
    plan: JsonDict,
    package_id: str,
    projection_root: Path,
) -> Optional[Path]:
    """Copy the published package into its catalog folder, and return it.

    The folder mirrors the published package as a whole -- not just the files
    this registration contributed -- so that a package built from two different
    workspaces is complete on disk rather than holding whichever piece was
    registered last.
    """

    folder = _package_plan_catalog_folder(state, plan, package_id)
    if folder is None:
        return None
    owned_paths = sorted(
        {entry.name for entry in projection_root.iterdir()},
        key=lambda value: value.encode("utf-8"),
    )
    if not owned_paths:
        raise ValueError("Published catalog package is empty.")
    _assert_package_folder_not_moved_on(
        folder, _read_package_plan_ownership(folder), package_id=package_id
    )
    # The installer stages beside the package folder, so the catalog directory
    # has to exist before it runs. For a package being registered for the first
    # time it does not.
    folder.parent.mkdir(parents=True, exist_ok=True)
    _apply_package_artifact_transaction(
        state,
        plan={
            "workspace_id": CATALOG_FOLDER_OWNER_WORKSPACE,
            "id": CATALOG_FOLDER_OWNER_PLAN,
        },
        package_root=folder,
        owned_paths=owned_paths,
        artifact_root=projection_root,
    )
    ensure_package_identity(folder)
    _record_package_folder_fingerprint(folder)
    _refresh_catalog_package_roots(state)
    return folder


def _record_package_folder_fingerprint(package_root: Path) -> None:
    """Remember what the folder looked like when OptPilot last wrote it."""

    ownership = _read_package_plan_ownership(package_root)
    ownership["folder_fingerprint"] = _package_folder_fingerprint(package_root)
    path = _package_plan_ownership_path(package_root)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        json.dumps(ownership, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )


def _apply_package_artifact_transaction(
    state: UiState,
    *,
    plan: JsonDict,
    package_root: Path,
    owned_paths: List[str],
    artifact_root: Path,
) -> None:
    """Replace one plan's paths through a complete, recoverable tree swap."""

    workspace_id = _safe_artifact_identifier(
        str(plan.get("workspace_id") or ""), "package plan workspace id"
    )
    plan_id = _safe_artifact_identifier(str(plan.get("id") or ""), "package plan id")
    ownership = _read_package_plan_ownership(package_root)
    current_application = _package_plan_application(
        ownership, workspace_id=workspace_id, plan_id=plan_id
    )
    current_paths = (
        list(current_application.get("paths", [])) if current_application else []
    )
    _preflight_package_plan_apply_collisions(
        package_root,
        ownership=ownership,
        workspace_id=workspace_id,
        plan_id=plan_id,
        current_paths=current_paths,
        owned_paths=owned_paths,
    )

    transaction_id = f"txn_{uuid.uuid4().hex}"
    stage_root, backup_root = _package_plan_transaction_paths(
        package_root, transaction_id
    )
    artifact_root = artifact_root.resolve()
    if not artifact_root.is_dir():
        raise ValueError("Package-plan artifact projection is unavailable.")
    journal_path = _package_plan_transaction_journal_path(package_root)
    try:
        for relative in owned_paths:
            artifact = _contained_output_path(artifact_root, Path(relative))
            if not artifact.exists():
                raise RuntimeError(
                    f"Validated package plan did not materialize owned path: {relative}."
                )

        if package_root.exists():
            if not package_root.is_dir():
                raise ValueError(
                    f"Local catalog package is not a directory: {package_root}."
                )
            shutil.copytree(package_root, stage_root, symlinks=True)
        else:
            stage_root.mkdir(mode=0o700)

        for relative in sorted(
            current_paths, key=lambda item: len(PurePosixPath(item).parts), reverse=True
        ):
            _remove_package_plan_path(
                _contained_output_path(stage_root, Path(relative))
            )
        for relative in owned_paths:
            source = _contained_output_path(artifact_root, Path(relative))
            destination = _contained_output_path(stage_root, Path(relative))
            destination.parent.mkdir(parents=True, exist_ok=True)
            if source.is_dir():
                shutil.copytree(source, destination)
                _make_tree_user_writable(destination)
            else:
                shutil.copy2(source, destination)
                destination.chmod(destination.stat().st_mode | 0o200)

        updated_ownership = _updated_package_plan_ownership(
            ownership,
            workspace_id=workspace_id,
            plan_id=plan_id,
            owned_paths=owned_paths,
        )
        ownership_path = _contained_output_path(
            stage_root, Path(PACKAGE_PLAN_OWNERSHIP_FILENAME)
        )
        ownership_path.parent.mkdir(parents=True, exist_ok=True)
        ownership_path.write_text(
            json.dumps(updated_ownership, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )

        transaction = {
            "schema": PACKAGE_PLAN_TRANSACTION_SCHEMA,
            "transaction_id": transaction_id,
            "phase": "prepared",
            "had_original": package_root.exists(),
        }
        _write_package_plan_transaction(journal_path, transaction)
        try:
            if transaction["had_original"]:
                _replace_package_plan_path(package_root, backup_root)
            transaction["phase"] = "original-moved"
            _write_package_plan_transaction(journal_path, transaction)
            _replace_package_plan_path(stage_root, package_root)
            transaction["phase"] = "installed"
            _write_package_plan_transaction(journal_path, transaction)
            _remove_package_plan_path(backup_root)
            journal_path.unlink(missing_ok=True)
        except BaseException:
            try:
                _recover_package_plan_transaction(package_root)
            except Exception as recovery_error:
                raise RuntimeError(
                    "Package-plan apply failed and its previous catalog package "
                    "could not be recovered."
                ) from recovery_error
            raise
    finally:
        if not journal_path.exists():
            _remove_package_plan_path(stage_root)
            _remove_package_plan_path(backup_root)


def _preflight_package_plan_apply_collisions(
    package_root: Path,
    *,
    ownership: JsonDict,
    workspace_id: str,
    plan_id: str,
    current_paths: List[str],
    owned_paths: List[str],
) -> None:
    for application in ownership.get("applications", []):
        if (
            application.get("workspace_id") == workspace_id
            and application.get("plan_id") == plan_id
        ):
            continue
        for existing in application.get("paths", []):
            for requested in owned_paths:
                if _package_plan_paths_overlap(str(existing), requested):
                    raise ValueError(
                        f"Package plan target is owned by another plan: {requested}."
                    )
    for requested in owned_paths:
        target = _contained_output_path(package_root, Path(requested))
        already_owned = any(
            requested == existing
            or PurePosixPath(requested).is_relative_to(PurePosixPath(existing))
            for existing in current_paths
        )
        if target.exists() and not already_owned:
            raise ValueError(
                "Package plan target collides with catalog content not owned by "
                f"this plan: {requested}."
            )


def _package_plan_paths_overlap(left: str, right: str) -> bool:
    left_path = PurePosixPath(left)
    right_path = PurePosixPath(right)
    return (
        left_path == right_path
        or left_path.is_relative_to(right_path)
        or right_path.is_relative_to(left_path)
    )


def _package_plan_ownership_path(package_root: Path) -> Path:
    return _contained_output_path(package_root, Path(PACKAGE_PLAN_OWNERSHIP_FILENAME))


def _read_package_plan_ownership(package_root: Path) -> JsonDict:
    if not package_root.exists():
        return {"schema": PACKAGE_PLAN_OWNERSHIP_SCHEMA, "applications": []}
    path = _package_plan_ownership_path(package_root)
    if not path.exists():
        return {"schema": PACKAGE_PLAN_OWNERSHIP_SCHEMA, "applications": []}
    if not path.is_file():
        raise ValueError("Package-plan ownership manifest must be a regular file.")
    raw = _read_json(path)
    if not isinstance(raw, dict):
        raise ValueError("Package-plan ownership manifest must be an object.")
    if raw.get("schema") != PACKAGE_PLAN_OWNERSHIP_SCHEMA:
        raise ValueError("Package-plan ownership manifest has an unsupported schema.")
    applications = raw.get("applications")
    if not isinstance(applications, list):
        raise ValueError("Package-plan ownership applications must be a list.")
    normalized: List[JsonDict] = []
    identities: set[tuple[str, str]] = set()
    claimed_paths: List[str] = []
    for application in applications:
        if not isinstance(application, dict):
            raise ValueError("Package-plan ownership entries must be objects.")
        if not isinstance(application.get("workspace_id"), str) or not isinstance(
            application.get("plan_id"), str
        ):
            raise ValueError("Package-plan ownership identities must be strings.")
        workspace_id = _safe_artifact_identifier(
            str(application.get("workspace_id") or ""),
            "package-plan ownership workspace id",
        )
        plan_id = _safe_artifact_identifier(
            str(application.get("plan_id") or ""),
            "package-plan ownership plan id",
        )
        identity = (workspace_id, plan_id)
        if identity in identities:
            raise ValueError("Package-plan ownership contains a duplicate owner.")
        identities.add(identity)
        raw_paths = application.get("paths")
        if not isinstance(raw_paths, list) or not raw_paths:
            raise ValueError("Package-plan ownership paths must be a non-empty list.")
        if not all(isinstance(item, str) for item in raw_paths):
            raise ValueError("Package-plan ownership paths must be strings.")
        applied_at = application.get("applied_at", "")
        if not isinstance(applied_at, str):
            raise ValueError("Package-plan ownership applied_at must be a string.")
        paths = sorted(
            _safe_relative_plan_path(
                str(item), "package-plan ownership path"
            ).as_posix()
            for item in raw_paths
        )
        if len(set(paths)) != len(paths):
            raise ValueError("Package-plan ownership contains duplicate paths.")
        for path in paths:
            for claimed in claimed_paths:
                if _package_plan_paths_overlap(path, claimed):
                    raise ValueError(
                        "Package-plan ownership contains overlapping claims: "
                        f"{path!r} and {claimed!r}."
                    )
            claimed_paths.append(path)
        normalized.append(
            {
                "workspace_id": workspace_id,
                "plan_id": plan_id,
                "paths": paths,
                "applied_at": applied_at,
            }
        )
    result: JsonDict = {
        "schema": PACKAGE_PLAN_OWNERSHIP_SCHEMA,
        "applications": sorted(
            normalized,
            key=lambda item: (item["workspace_id"], item["plan_id"]),
        ),
    }
    fingerprint = raw.get("folder_fingerprint")
    if fingerprint is not None:
        if not isinstance(fingerprint, str):
            raise ValueError(
                "Package-plan ownership folder_fingerprint must be a string."
            )
        result["folder_fingerprint"] = fingerprint
    return result


def _package_plan_application(
    ownership: JsonDict, *, workspace_id: str, plan_id: str
) -> Optional[JsonDict]:
    for application in ownership.get("applications", []):
        if (
            application.get("workspace_id") == workspace_id
            and application.get("plan_id") == plan_id
        ):
            return application
    return None


def _updated_package_plan_ownership(
    ownership: JsonDict,
    *,
    workspace_id: str,
    plan_id: str,
    owned_paths: List[str],
) -> JsonDict:
    applications = [
        dict(application)
        for application in ownership.get("applications", [])
        if not (
            application.get("workspace_id") == workspace_id
            and application.get("plan_id") == plan_id
        )
    ]
    applications.append(
        {
            "workspace_id": workspace_id,
            "plan_id": plan_id,
            "paths": list(owned_paths),
            "applied_at": _now_iso(),
        }
    )
    return {
        "schema": PACKAGE_PLAN_OWNERSHIP_SCHEMA,
        "applications": sorted(
            applications,
            key=lambda item: (str(item["workspace_id"]), str(item["plan_id"])),
        ),
    }


def _package_plan_transaction_journal_path(package_root: Path) -> Path:
    return package_root.parent / f".{package_root.name}.package-plan-transaction.json"


def _package_plan_transaction_paths(
    package_root: Path, transaction_id: str
) -> tuple[Path, Path]:
    safe_id = _safe_artifact_identifier(transaction_id, "package-plan transaction id")
    prefix = f".{package_root.name}.package-plan-{safe_id}"
    return (
        package_root.parent / f"{prefix}.staging",
        package_root.parent / f"{prefix}.backup",
    )


def _write_package_plan_transaction(path: Path, transaction: JsonDict) -> None:
    _atomic_write_text(path, json.dumps(transaction, indent=2, sort_keys=True) + "\n")


def _recover_package_plan_transaction(package_root: Path) -> None:
    """Finish a committed swap or restore the exact pre-commit package tree."""

    journal_path = _package_plan_transaction_journal_path(package_root)
    if not journal_path.exists():
        return
    if journal_path.is_symlink() or not journal_path.is_file():
        raise RuntimeError(
            "Package-plan transaction journal must be a regular local file."
        )
    transaction = _read_json(journal_path)
    if not isinstance(transaction, dict):
        raise RuntimeError("Package-plan transaction journal must be an object.")
    if transaction.get("schema") != PACKAGE_PLAN_TRANSACTION_SCHEMA:
        raise RuntimeError(
            "Package-plan transaction journal has an unsupported schema."
        )
    transaction_id = str(transaction.get("transaction_id") or "")
    stage_root, backup_root = _package_plan_transaction_paths(
        package_root, transaction_id
    )
    phase = str(transaction.get("phase") or "")
    if phase not in {"prepared", "original-moved", "installed"}:
        raise RuntimeError("Package-plan transaction journal has an invalid phase.")
    had_original = transaction.get("had_original")
    if not isinstance(had_original, bool):
        raise RuntimeError(
            "Package-plan transaction journal is missing its original-state proof."
        )

    if phase == "installed" and package_root.exists():
        _remove_package_plan_path(stage_root)
        _remove_package_plan_path(backup_root)
        journal_path.unlink(missing_ok=True)
        return

    if had_original:
        if backup_root.exists():
            _remove_package_plan_path(package_root)
            _replace_package_plan_path(backup_root, package_root)
        elif not package_root.exists():
            raise RuntimeError(
                "Package-plan recovery cannot find either the original package "
                "or its backup."
            )
    else:
        if phase == "prepared" and package_root.exists():
            raise RuntimeError(
                "Package-plan recovery found unexpected catalog content before "
                "the first install."
            )
        if phase != "prepared":
            _remove_package_plan_path(package_root)
    _remove_package_plan_path(stage_root)
    _remove_package_plan_path(backup_root)
    journal_path.unlink(missing_ok=True)


def _replace_package_plan_path(source: Path, destination: Path) -> None:
    source.replace(destination)


def _remove_package_plan_path(path: Path) -> None:
    if path.is_symlink() or path.is_file():
        path.unlink(missing_ok=True)
    elif path.exists():
        shutil.rmtree(path)


def _discover_workspace_package_configs(root: Path) -> List[JsonDict]:
    configs: List[JsonDict] = []
    for path in _iter_yaml_files(root):
        raw = _read_yaml(path)
        config = raw.get("config")
        if config not in OPT_CONFIGS or raw.get("apiVersion") != AUTHORING_API_VERSION:
            continue
        validation = validate_authoring_config(path)
        configs.append(
            {
                "path": str(path),
                "relative_path": _relative_path(path, root),
                "kind": config,
                "id": str(raw.get("id") or raw.get("name") or path.stem),
                "label": str(raw.get("name") or raw.get("id") or path.stem),
                "valid": bool(validation.get("valid")),
                "validation": validation,
                "focus_paths": _focus_paths_for_config(root, path, raw),
            }
        )
    return sorted(configs, key=lambda item: (item["kind"], item["relative_path"]))


def _package_plan_classification(
    components: List[JsonDict], resources: List[JsonDict]
) -> str:
    has_environment = any(item.get("kind") == "environment" for item in components)
    has_method = any(item.get("kind") == "method" for item in components)
    if has_environment and has_method:
        return "environment-plus-method"
    if has_environment:
        return "environment-only"
    if has_method:
        return "method-only"
    if resources:
        return "resource-only"
    return "not-yet-classifiable"


def _package_plan_readiness(plan: JsonDict, validation: JsonDict) -> str:
    retained_execution = _package_retained_execution_capability(validation)
    if (
        plan.get("classification") == "environment-plus-method"
        and retained_execution is not None
        and retained_execution_blocks_smoke(retained_execution)
    ):
        return "execution-unsupported"
    if not validation.get("valid"):
        return "schema-invalid"
    classification = str(plan.get("classification") or "")
    if classification == "resource-only":
        return "resource-ready"
    if classification in {"environment-only", "method-only"}:
        return "component-ready"
    if classification == "environment-plus-method":
        return "run-ready" if plan.get("smoke", {}).get("valid") else "component-ready"
    return "not-yet-classifiable"


def _package_plan_warnings(plan: JsonDict, validation: JsonDict) -> List[str]:
    warnings: List[str] = []
    dependency_closure = _package_dependency_closure_capability(validation)
    if (
        isinstance(dependency_closure, Mapping)
        and dependency_closure.get("code") == DEPENDENCY_HOST_PROVISIONED_CODE
    ):
        # A package whose components import undeclared host packages is not
        # component-ready anywhere but this machine; say so before registration.
        warnings.append(
            str(
                dependency_closure.get("reason")
                or "The package imports dependencies only the host provides."
            )
        )
    retained_execution = _package_retained_execution_capability(validation)
    if (
        plan.get("classification") in {"environment-plus-method", "method-only"}
        and retained_execution is not None
        and retained_execution_blocks_smoke(retained_execution)
    ):
        warnings.append(
            str(
                retained_execution.get("reason")
                or "The package is not eligible for retained execution."
            )
        )
    if plan.get("classification") == "environment-plus-method" and not plan.get(
        "studies"
    ):
        warnings.append("Environment-plus-method package has no Study available for Test.")
    elif (
        plan.get("classification") == "environment-plus-method"
        and (
            retained_execution is None
            or not retained_execution_blocks_smoke(retained_execution)
        )
        and not plan.get("smoke", {}).get("valid")
    ):
        warnings.append(
            "Environment-plus-method package is component-ready; run Test before registering it."
        )
    if (
        validation.get("valid")
        and plan.get("classification") in {"environment-only", "method-only"}
        and (
            plan.get("classification") != "method-only"
            or retained_execution is None
            or not retained_execution_blocks_smoke(retained_execution)
        )
    ):
        warnings.append(
            "Package is component-ready; pair it with a compatible counterpart before claiming run-ready."
        )
    return warnings


def _package_retained_execution_capability(
    validation: Mapping[str, Any],
) -> Optional[JsonDict]:
    capabilities = validation.get("capabilities")
    if not isinstance(capabilities, Mapping):
        return None
    capability = capabilities.get("retained_execution")
    return dict(capability) if isinstance(capability, Mapping) else None


def _package_dependency_closure_capability(
    validation: Mapping[str, Any],
) -> Optional[JsonDict]:
    capabilities = validation.get("capabilities")
    if not isinstance(capabilities, Mapping):
        return None
    capability = capabilities.get("dependency_closure")
    return dict(capability) if isinstance(capability, Mapping) else None


def _package_identity_for(state: UiState, package_id: str) -> str:
    """The package's identity, settling it now if the package is new.

    This writes the identity file if there is none, which claims the package's
    name on disk before anything else is registered into it. It has to be
    settled here rather than generated on demand: the publisher that owns the
    package is derived from it, so a fresh value each time would give the same
    package a different owner every time a registration was prepared.

    An existing identity always wins, so this never renames a package.
    """

    folder = state.cwd / CATALOG_DIR_NAME / package_id
    if _is_bundled_catalog_package(folder):
        raise _with_remedy(
            RealmConflict(
                f"{package_id} ships with OptPilot and cannot be registered "
                "into. Register into a package of your own instead."
            ),
            _remedy(
                "Register into a package of your own. To build on this one, "
                "copy its folder under a new name and give the copy a "
                "different identity value, then register the copy.",
                details={"package": package_id, "reason": "ships_with_optpilot"},
            ),
        )
    try:
        identity = ensure_package_identity(folder)
    except OSError as error:
        raise RealmConflict(
            f"The {package_id} package folder could not be created: {error}"
        ) from error
    # Record that the settings file just written belongs to OptPilot. Without
    # this the first folder write refuses it as pre-existing content it does not
    # own -- which is the check that protects the author's own files, doing its
    # job on a file we put there ourselves a moment earlier.
    ownership = _read_package_plan_ownership(folder)
    if not _package_plan_application(
        ownership,
        workspace_id=CATALOG_FOLDER_OWNER_WORKSPACE,
        plan_id=CATALOG_FOLDER_OWNER_PLAN,
    ):
        ownership = _updated_package_plan_ownership(
            ownership,
            workspace_id=CATALOG_FOLDER_OWNER_WORKSPACE,
            plan_id=CATALOG_FOLDER_OWNER_PLAN,
            owned_paths=[PACKAGE_SETTINGS_FILENAMES[0]],
        )
        path = _package_plan_ownership_path(folder)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            json.dumps(ownership, indent=2, sort_keys=True) + "\n", encoding="utf-8"
        )
    return identity


def _package_folder_publisher_id(package_id: str, identity: str) -> str:
    """One publisher per package, derived from the package's own identity.

    A catalog belongs to one person, so a package has one lineage and each
    registration replaces what the last one claimed rather than composing beside
    it. Deriving this from the workspace and plan made every registration a
    separate contributor, so two of them both claimed the package's settings file
    and publication refused the overlap.
    """

    return configured_package_publisher_id(
        package_id,
        configured_package_source_identity_digest(f"package-identity:{identity}"),
    )


def _package_plan_selection_paths(plan: JsonDict) -> List[str]:
    """The paths this work covers: one component, or the whole package."""

    paths: List[str] = []
    for item in [
        *(plan.get("components", []) or []),
        *(plan.get("resources", []) or []),
    ]:
        if not isinstance(item, dict):
            continue
        paths.append(
            _safe_relative_plan_path(
                str(item.get("component_root") or ""),
                "package-plan owned component path",
            ).as_posix()
        )
    for item in plan.get("studies", []) or []:
        if not isinstance(item, dict):
            continue
        paths.append(
            _safe_relative_plan_path(
                str(item.get("registered_config_path") or ""),
                "package-plan owned study path",
            ).as_posix()
        )
    return sorted(set(paths))


def _compose_package_candidate(
    state: UiState, plan: JsonDict, destination: Path
) -> None:
    """Build the package as it would be after registering, without touching it.

    The author may be editing the whole package or one component in it. Either
    way the answer is the same shape: start from the package as it stands, then
    replace whatever this work covers. Composing into a scratch directory rather
    than the real folder is what lets Check validate exactly the bytes that
    registering will publish while leaving the catalog untouched.
    """

    package_id = str(plan.get("package_id") or LOCAL_PACKAGE_NAME)
    folder = state.cwd / CATALOG_DIR_NAME / package_id
    destination.mkdir(parents=True, exist_ok=True)

    if folder.is_dir():
        for entry in folder.iterdir():
            if entry.name in CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS:
                continue
            target = destination / entry.name
            if entry.is_dir():
                shutil.copytree(entry, target, symlinks=True)
            else:
                shutil.copy2(entry, target)

    with tempfile.TemporaryDirectory() as staged_dir:
        staged = Path(staged_dir) / package_id
        _materialize_package_plan(state, plan, staged)
        for relative in _package_plan_selection_paths(plan):
            source = _contained_output_path(staged, Path(relative))
            target = _contained_output_path(destination, Path(relative))
            if not source.exists():
                raise RuntimeError(
                    f"Package plan did not materialize its own path: {relative}."
                )
            _remove_package_plan_path(target)
            target.parent.mkdir(parents=True, exist_ok=True)
            if source.is_dir():
                shutil.copytree(source, target, symlinks=True)
            else:
                shutil.copy2(source, target)

    _write_composed_package_settings(state, plan, destination)
    _make_tree_user_writable(destination)


def _write_composed_package_settings(
    state: UiState, plan: JsonDict, destination: Path
) -> None:
    """Put the package's own settings into the tree that gets sealed.

    They are part of the package -- they carry its identity and the image its
    components run in -- so a snapshot that omitted them could never equal the
    folder. Any image already declared is carried across; dropping it would
    silently change what the package's components run in.
    """

    identity = plan.get("package_identity")
    if not isinstance(identity, str) or not identity:
        identity = _package_identity_for(
            state, str(plan.get("package_id") or LOCAL_PACKAGE_NAME)
        )
        plan["package_identity"] = identity
    container = None
    description = None
    title = None
    category = None
    paper = None
    try:
        existing = load_package_settings(destination)
    except (ValueError, OSError):
        existing = None
    if existing is not None:
        container = existing.container
        description = existing.description
        title = existing.title
        category = existing.category
        paper = existing.paper
    captured = plan.get("captured_image")
    if (
        isinstance(captured, Mapping)
        and plan.get("captured_image_placement") == "package"
    ) or (container is None and isinstance(captured, Mapping)):
        # The software installed in the workspace, captured at Check, becomes
        # the package's image -- recorded in the same settings file that
        # carries the package's identity, sealed and validated with the rest.
        from optpilot.image_reference import parse_image_reference
        from optpilot.package_settings import ContainerImageDeclaration

        container = ContainerImageDeclaration(
            image=parse_image_reference(str(captured.get("image"))),
            platform=str(captured.get("platform")),
        )
    write_package_settings(
        destination,
        identity=identity,
        description=description,
        title=title,
        category=category,
        paper=paper,
        container=container,
    )


def _materialize_package_plan(
    state: UiState, plan: JsonDict, package_root: Path
) -> None:
    root = _workspace_operation_root(
        state,
        str(plan.get("workspace_id") or ""),
        str(plan.get("source_root") or ""),
        "Package plan source_root",
    )
    for item in [
        *(plan.get("components", []) or []),
        *(plan.get("resources", []) or []),
    ]:
        if isinstance(item, dict):
            _preflight_package_plan_target(item)
    for item in plan.get("studies", []) or []:
        if not isinstance(item, dict):
            continue
        _safe_relative_plan_path(
            str(item.get("config_path") or ""), "package study config path"
        )
        _safe_relative_plan_path(
            str(item.get("registered_config_path") or ""),
            "registered study config path",
        )
    package_root.mkdir(parents=True, exist_ok=True)
    captured = plan.get("captured_image")
    component_override = (
        captured
        if isinstance(captured, Mapping)
        and plan.get("captured_image_placement") == "component"
        else None
    )
    for item in plan.get("components", []) or []:
        if not isinstance(item, dict):
            continue
        destination = _contained_output_path(
            package_root,
            Path(str(item.get("component_root") or "")),
        )
        _copy_plan_target(root, item, destination)
        if component_override is not None and str(item.get("kind")) in (
            "environment",
            "method",
        ):
            _append_component_runtime_override(
                _contained_output_path(
                    destination,
                    Path(str(item.get("registered_config_path") or "")),
                ),
                image=str(component_override.get("image")),
                platform=str(component_override.get("platform")),
            )
    for item in plan.get("resources", []) or []:
        if not isinstance(item, dict):
            continue
        destination = _contained_output_path(
            package_root,
            Path(str(item.get("component_root") or "")),
        )
        if item.get("synthesized"):
            destination.mkdir(parents=True, exist_ok=True)
            _copy_plan_files(root, item, destination)
        else:
            _copy_plan_target(root, item, destination)
    component_config_map = _package_plan_component_config_map(plan)
    materialized_study = False
    for item in plan.get("studies", []) or []:
        if not isinstance(item, dict):
            continue
        config_path = _workspace_source_path(
            root,
            str(item.get("config_path") or ""),
            "package study config path",
        )
        if not config_path.exists():
            continue
        raw = _read_yaml(config_path)
        normalized = _normalize_registered_study(
            raw, root, config_path, component_config_map
        )
        output = _contained_output_path(
            package_root,
            Path(
                str(
                    item.get("registered_config_path")
                    or f"studies/{_slug_text(str(raw.get('name') or config_path.stem))}.yaml"
                )
            ),
        )
        output.parent.mkdir(parents=True, exist_ok=True)
        output.write_text(yaml.safe_dump(normalized, sort_keys=False), encoding="utf-8")
        materialized_study = True
    if not materialized_study:
        studies_root = package_root / "studies"
        if studies_root.exists() and not any(studies_root.iterdir()):
            studies_root.rmdir()


def _preflight_package_plan_target(item: JsonDict) -> None:
    _safe_relative_plan_path(
        str(item.get("component_root") or ""), "package component root"
    )
    if item.get("config_path"):
        _safe_relative_plan_path(str(item["config_path"]), "package config path")
    if item.get("registered_config_path"):
        _safe_relative_plan_path(
            str(item["registered_config_path"]), "registered config path"
        )
    for field_name in ("include", "exclude", "source_hints", "path_rewrites"):
        if field_name in item:
            _validated_package_plan_field(field_name, item[field_name])


def _copy_plan_target(root: Path, item: JsonDict, destination: Path) -> None:
    destination.mkdir(parents=True, exist_ok=True)
    config_source = (
        _workspace_source_path(
            root, str(item.get("config_path")), "package config path"
        )
        if item.get("config_path")
        else None
    )
    _copy_plan_files(root, item, destination, config_source=config_source)
    if config_source is not None and config_source.exists():
        output = _contained_output_path(
            destination,
            Path(
                str(
                    item.get("registered_config_path")
                    or _registered_config_filename(
                        str(item.get("kind") or ""), config_source.name
                    )
                )
            ),
        )
        if not output.exists():
            raw = _read_yaml(config_source)
            normalized = _normalize_registered_config(
                raw, root, config_source, destination, item
            )
            output.write_text(
                yaml.safe_dump(normalized, sort_keys=False), encoding="utf-8"
            )


def _copy_plan_files(
    root: Path,
    item: JsonDict,
    destination: Path,
    *,
    config_source: Optional[Path] = None,
) -> None:
    for pattern in _plan_include_patterns(item):
        for source in _match_workspace_pattern(root, str(pattern)):
            relative = source.relative_to(root)
            if _excluded_by_patterns(str(relative), item.get("exclude", [])):
                continue
            if config_source is not None and source.resolve() == config_source:
                output_relative = Path(
                    str(
                        item.get("registered_config_path")
                        or _registered_config_filename(
                            str(item.get("kind") or ""), config_source.name
                        )
                    )
                )
                output = _contained_output_path(destination, output_relative)
                raw = _read_yaml(source)
                normalized = _normalize_registered_config(
                    raw, root, source, destination, item
                )
                output.parent.mkdir(parents=True, exist_ok=True)
                output.write_text(
                    yaml.safe_dump(normalized, sort_keys=False), encoding="utf-8"
                )
            else:
                output_relative = (
                    _registration_output_relative(
                        root, source, config_source, str(item.get("kind") or ""), item
                    )
                    if config_source is not None
                    else _path_rewrite_for_item(item, str(relative), relative)
                )
                output = _contained_output_path(destination, output_relative)
                output.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, output)


def _package_plan_component_config_map(plan: JsonDict) -> Dict[str, str]:
    mapping: Dict[str, str] = {}
    for item in plan.get("components", []) or []:
        if not isinstance(item, dict):
            continue
        config_path = str(item.get("config_path") or "")
        registered = f"../{item.get('component_root')}/{item.get('registered_config_path') or _registered_config_filename(str(item.get('kind') or ''), '')}"
        if config_path:
            mapping[config_path] = registered
    return mapping


def _normalize_registered_study(
    raw: JsonDict, root: Path, config_source: Path, component_config_map: Dict[str, str]
) -> JsonDict:
    normalized = deepcopy(raw)
    for key in ("environmentConfig", "methodConfig"):
        value = normalized.get(key)
        if not isinstance(value, str):
            continue
        resolved = (config_source.parent / value).resolve()
        relative = (
            _relative_path(resolved, root)
            if _is_relative_to(resolved, root.resolve())
            else value
        )
        if relative in component_config_map:
            normalized[key] = component_config_map[relative]
    return normalized


def _select_plan_study(
    package_root: Path, plan: JsonDict, requested: str
) -> Optional[Path]:
    registered_paths = {
        str(item.get("registered_config_path") or "")
        for item in plan.get("studies", []) or []
        if isinstance(item, dict)
    }
    if requested:
        requested = requested.strip()
        requested_path = _safe_relative_plan_path(requested, "smoke study path")
        candidate = _contained_output_path(package_root, requested_path)
        # The path must be one this work registers. The package now holds every
        # component, not just this plan's, so accepting any file that happens to
        # exist would let a test of somebody else's component be recorded as
        # evidence for this one -- permanently, and looking entirely legitimate.
        if candidate.is_file() and requested_path.as_posix() in registered_paths:
            return candidate
        normalized_requested = _slug_text(requested)
        for item in plan.get("studies", []) or []:
            if not isinstance(item, dict):
                continue
            registered = str(item.get("registered_config_path") or "")
            candidates = {
                str(item.get("id") or ""),
                str(item.get("label") or ""),
                str(item.get("target_id") or ""),
                str(item.get("config_path") or ""),
                registered,
                Path(registered).name if registered else "",
                Path(registered).stem if registered else "",
            }
            if requested in candidates or normalized_requested in {
                _slug_text(value) for value in candidates if value
            }:
                if not registered:
                    return None
                candidate = _contained_output_path(package_root, Path(registered))
                return candidate if candidate.is_file() else None
        return None
    smoke_studies = [
        item
        for item in plan.get("studies", []) or []
        if isinstance(item, dict) and item.get("smoke")
    ]
    studies = smoke_studies or [
        item for item in plan.get("studies", []) or [] if isinstance(item, dict)
    ]
    if not studies:
        return None
    registered = str(studies[0].get("registered_config_path") or "")
    if not registered:
        return None
    candidate = _contained_output_path(package_root, Path(registered))
    return candidate if candidate.is_file() else None


def _parse_smoke_summary(stdout: str) -> JsonDict:
    text = (stdout or "").strip()
    if not text:
        return {}
    try:
        payload = json.loads(text)
        return payload if isinstance(payload, dict) else {}
    except json.JSONDecodeError:
        pass
    start = text.rfind("\n{")
    if start >= 0:
        try:
            payload = json.loads(text[start + 1 :])
            return payload if isinstance(payload, dict) else {}
        except json.JSONDecodeError:
            return {}
    return {}


def _smoke_summary_errors(
    completed: subprocess.CompletedProcess[str], summary: JsonDict, study_path: Path
) -> List[str]:
    errors: List[str] = []
    if not summary:
        if completed.returncode != 0:
            return [
                _process_error_summary(
                    stderr=completed.stderr,
                    stdout=completed.stdout,
                    returncode=completed.returncode,
                )
            ]
        return ["Smoke study completed without a parseable JSON summary."]

    if summary.get("schema") == RUN_SUMMARY_PROJECTION_SCHEMA:
        run_status = summary.get("run_status")
        stop_code = summary.get("stop_code")
        counts = (
            summary.get("counts", {}) if isinstance(summary.get("counts"), dict) else {}
        )
        logical = (
            counts.get("logical_trials", {})
            if isinstance(counts.get("logical_trials"), dict)
            else {}
        )
        terminal_trials = int(logical.get("terminal") or 0)
        final_failures = int(logical.get("final_failures") or 0)
        successful_objectives = int(
            logical.get("successful_objective_observations") or 0
        )
        if run_status != "succeeded":
            errors.append(
                "Smoke study did not succeed: "
                f"run_status={run_status}, stop_code={stop_code}, "
                f"final_logical_failures={final_failures}."
            )
        if final_failures:
            errors.append(
                f"Smoke study reported final_logical_failures={final_failures}."
            )
        if terminal_trials < 1:
            errors.append("Smoke study completed no logical trials.")
        if successful_objectives < 1:
            errors.append("Smoke study produced no successful objective observation.")
        if completed.returncode != 0 and run_status == "succeeded":
            errors.append(
                completed.stderr.strip()
                or "Smoke study exited nonzero despite a succeeded Realm summary."
            )
        return errors

    run_status = summary.get("run_status")
    stop_code = summary.get("stop_code")
    completed_trials = int(summary.get("completed_trials") or 0)
    failure_count = int(summary.get("failure_count") or 0)
    final_failure_count = int(summary.get("final_failure_count", failure_count) or 0)
    if run_status and run_status != "succeeded":
        errors.append(
            "Smoke study did not succeed: "
            f"run_status={run_status}, stop_code={stop_code}, "
            f"final_failure_count={final_failure_count}, failure_count={failure_count}."
        )
    elif final_failure_count != 0:
        errors.append(
            "Smoke study reported a non-clean terminal summary: "
            f"run_status={run_status or 'legacy'}, stop_code={stop_code}, "
            f"final_failure_count={final_failure_count}, failure_count={failure_count}."
        )
    elif completed.returncode != 0:
        errors.append(
            completed.stderr.strip()
            or f"Smoke study exited with code {completed.returncode} despite reporting run_status={run_status or 'legacy'}."
        )
    if completed_trials < 1:
        errors.append("Smoke study completed no trials.")
    if failure_count != 0 and not run_status:
        errors.append(f"Smoke study reported failure_count={failure_count}.")
    objective_metric = _study_objective_metric(study_path)
    if objective_metric:
        run_dir = Path(str(summary.get("run_dir") or ""))
        if not run_dir.is_absolute():
            run_dir = (study_path.parent / run_dir).resolve()
        if not _observations_include_metric(
            run_dir / "observations.jsonl", objective_metric
        ):
            errors.append(
                f"Smoke study observations did not include objective metric {objective_metric!r}."
            )
    return errors


def _study_objective_metric(study_path: Path) -> str:
    try:
        raw = _read_yaml(study_path)
    except Exception:
        return ""
    objective = (
        raw.get("objective", {}) if isinstance(raw.get("objective"), dict) else {}
    )
    return str(objective.get("metric") or "")


def _observations_include_metric(path: Path, metric: str) -> bool:
    if not path.exists():
        return False
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line.strip():
            continue
        try:
            item = json.loads(line)
        except json.JSONDecodeError:
            continue
        values = item.get("metric_values", {}) if isinstance(item, dict) else {}
        if isinstance(values, dict) and metric in values:
            return True
    return False


def _default_resource_config_include(
    root: Path, config_path: Path, raw: JsonDict
) -> List[str]:
    include = {_relative_path(config_path, root)}
    for item in _focus_paths_for_config(root, config_path, raw):
        include.add(item)
    for name in ("README.md", "readme.md", "assets", "docs", "data"):
        path = config_path.parent / name
        if path.exists():
            include.add(_relative_path(path, root) + ("/**" if path.is_dir() else ""))
    return sorted(include)


def _plan_include_patterns(item: JsonDict) -> List[str]:
    patterns = [str(value) for value in item.get("include", []) or [] if str(value)]
    for hint in item.get("source_hints", []) or []:
        path = hint.get("path") if isinstance(hint, dict) else hint
        if path:
            patterns.append(str(path))
    return list(dict.fromkeys(patterns))


def _package_plan_source_hint_errors(plan: JsonDict, package_root: Path) -> List[str]:
    errors: List[str] = []
    for item in [
        *(plan.get("components", []) or []),
        *(plan.get("resources", []) or []),
    ]:
        if not isinstance(item, dict):
            continue
        component_root = _contained_output_path(
            package_root,
            Path(str(item.get("component_root") or "")),
        )
        for hint in item.get("source_hints", []) or []:
            path_value = hint.get("path") if isinstance(hint, dict) else hint
            if not path_value:
                continue
            expected = _contained_output_path(
                component_root,
                _path_rewrite_for_item(item, str(path_value), Path(str(path_value))),
            )
            if not expected.exists():
                errors.append(
                    f"{item.get('kind')} {item.get('id')} source_hints path was not materialized: {path_value}"
                )
    return errors


def _package_plan_curation_checks(
    plan: JsonDict,
    package_root: Path,
    *,
    execute_callables: bool = False,
) -> JsonDict:
    errors: List[str] = []
    warnings: List[str] = []
    checks: List[JsonDict] = []
    source_root = Path(str(plan.get("source_root") or "")).resolve()
    source_top_level = _source_top_level_names(source_root)
    for item in plan.get("components", []) or []:
        if not isinstance(item, dict):
            continue
        kind = str(item.get("kind") or "")
        component_id = str(item.get("id") or "")
        component_root = _contained_output_path(
            package_root,
            Path(str(item.get("component_root") or "")),
        )
        config_path = _package_plan_component_config_path(package_root, item)
        if not config_path.exists():
            continue
        raw = _read_yaml(config_path)
        entry_errors: List[str] = []
        entry_warnings: List[str] = []
        prepared_runtime = uses_locked_python_runtime_setup(raw)
        if kind == "environment" and execute_callables and not prepared_runtime:
            entry_errors.extend(
                _curation_environment_callable_errors(
                    component_id, raw, config_path, package_root
                )
            )
        elif kind == "method":
            entry_errors.extend(
                _curation_method_protocol_errors(
                    component_id,
                    raw,
                    config_path,
                    package_root,
                    execute_callable=execute_callables and not prepared_runtime,
                )
            )
        entry_errors.extend(
            _curation_local_import_errors(
                component_id=component_id,
                component_root=component_root,
                config_path=config_path,
                raw=raw,
                package_root=package_root,
                source_top_level=source_top_level,
            )
        )
        entry_warnings.extend(
            _curation_env_var_warnings(kind, component_id, raw, component_root)
        )
        errors.extend(entry_errors)
        warnings.extend(entry_warnings)
        checks.append(
            {
                "kind": kind,
                "id": component_id,
                "path": str(config_path),
                "valid": not entry_errors,
                "errors": entry_errors,
                "warnings": entry_warnings,
            }
        )
    return {
        "valid": not errors,
        "errors": errors,
        "warnings": warnings,
        "checks": checks,
    }


def _package_plan_component_config_path(package_root: Path, item: JsonDict) -> Path:
    return _contained_output_path(
        package_root,
        Path(str(item.get("component_root") or ""))
        / str(
            item.get("registered_config_path")
            or _registered_config_filename(str(item.get("kind") or ""), "")
        ),
    )


def _curation_environment_callable_errors(
    component_id: str,
    raw: JsonDict,
    config_path: Path,
    package_root: Path,
) -> List[str]:
    evaluator = (
        raw.get("evaluator", {}) if isinstance(raw.get("evaluator"), dict) else {}
    )
    ref = evaluator.get("python")
    if not isinstance(ref, str) or not ref:
        return []
    return _curation_python_callable_shape_errors(
        label=f"environment {component_id} evaluator.python",
        ref=ref,
        python_paths=_config_python_paths(
            config_path, evaluator.get("pythonPath", []) or []
        ),
        package_root=package_root,
        mode="environment",
    )


def _curation_method_protocol_errors(
    component_id: str,
    raw: JsonDict,
    config_path: Path,
    package_root: Path,
    *,
    execute_callable: bool,
) -> List[str]:
    entrypoint = (
        raw.get("entrypoint", {}) if isinstance(raw.get("entrypoint"), dict) else {}
    )
    label = f"method {component_id} entrypoint"
    protocol = str(entrypoint.get("protocol") or "batch")
    if isinstance(entrypoint.get("command"), list):
        return [
            f"{label}.command is authoring-valid, but the retained process-study "
            "runner requires a Python batch method"
        ]
    if protocol != "batch":
        return [
            f"{label}.protocol {protocol!r} is authoring-valid, but the retained "
            "process-study runner requires protocol 'batch'"
        ]
    ref = entrypoint.get("python")
    if not execute_callable or not isinstance(ref, str) or not ref:
        return []
    return _curation_python_callable_shape_errors(
        label=f"{label}.python",
        ref=ref,
        python_paths=_config_python_paths(
            config_path, entrypoint.get("pythonPath", []) or []
        ),
        package_root=package_root,
        mode="method:batch",
    )


def _curation_python_callable_shape_errors(
    *,
    label: str,
    ref: str,
    python_paths: List[Path],
    package_root: Path,
    mode: str,
) -> List[str]:
    script = r"""
import importlib
import inspect
import sys

label, ref, mode = sys.argv[1:4]
try:
    module_name, sep, attr_path = ref.partition(":")
    if not sep:
        raise ValueError("Python reference must use module:attribute")
    module = importlib.import_module(module_name)
    value = module
    for part in attr_path.split("."):
        value = getattr(value, part)
    errors = []
    if mode == "environment":
        sig = inspect.signature(value)
        params = list(sig.parameters.values())
        positional = [
            p for p in params
            if p.kind in (inspect.Parameter.POSITIONAL_ONLY, inspect.Parameter.POSITIONAL_OR_KEYWORD)
            and p.default is inspect.Parameter.empty
        ]
        has_varargs = any(p.kind == inspect.Parameter.VAR_POSITIONAL for p in params)
        if not has_varargs and len(positional) > 2:
            errors.append(f"{label} must be callable as evaluate(candidate_runtime, context); signature is {sig}")
    elif mode.startswith("method:"):
        sig = inspect.signature(value)
        try:
            sig.bind({}, object(), object())
        except TypeError:
            errors.append(
                f"{label} must accept definition, study_spec, and rng and be "
                f"constructible as Method(definition, study_spec, rng); signature is {sig}"
            )
        has_propose = callable(getattr(value, "propose", None))
        if inspect.isclass(value) and not has_propose:
            errors.append(
                f"{label} protocol batch requires propose(...); "
                "start/poll/finalize-only methods are not supported by the retained runner"
            )
    if errors:
        print("\n".join(errors), file=sys.stderr)
        raise SystemExit(2)
except SystemExit:
    raise
except Exception as exc:
    print(f"{label} could not be inspected: {type(exc).__name__}: {exc}", file=sys.stderr)
    raise SystemExit(1)
"""
    env = dict(os.environ)
    path_values = [str(path) for path in python_paths]
    env["PYTHONPATH"] = os.pathsep.join(path_values) if path_values else ""
    completed = subprocess.run(
        [sys.executable, "-c", script, label, ref, mode],
        cwd=str(package_root),
        env=env,
        text=True,
        capture_output=True,
        timeout=30,
        check=False,
    )
    if completed.returncode == 0:
        return []
    detail = (
        completed.stderr.strip()
        or completed.stdout.strip()
        or f"exit code {completed.returncode}"
    )
    return [detail]


def _curation_local_import_errors(
    *,
    component_id: str,
    component_root: Path,
    config_path: Path,
    raw: JsonDict,
    package_root: Path,
    source_top_level: set[str],
) -> List[str]:
    if not component_root.exists():
        return []
    python_paths = _component_python_paths(config_path, raw)
    search_roots = _dedupe_existing_paths([component_root, *python_paths])
    errors: List[str] = []
    for path in sorted(component_root.rglob("*.py")):
        if _path_has_part(path, {".venv", "__pycache__", "node_modules"}):
            continue
        for module_name in _python_imports_in_file(path):
            top_level = module_name.split(".", 1)[0]
            if not top_level or top_level in _stdlib_module_names():
                continue
            if _module_exists_under_roots(module_name, search_roots):
                continue
            if top_level in source_top_level:
                relative = _relative_path(path, package_root)
                errors.append(
                    f"{component_id}: local import {module_name!r} in {relative} is not materialized in the package. "
                    f"Add the needed source directory/file to the package plan include or source_hints."
                )
    return list(dict.fromkeys(errors))


def _curation_env_var_warnings(
    kind: str, component_id: str, raw: JsonDict, component_root: Path
) -> List[str]:
    declared = _declared_component_env_from_host(raw)
    used = _source_env_var_names(component_root)
    warnings: List[str] = []
    for name in sorted(used):
        if name in declared:
            continue
        if _looks_like_required_secret(name):
            warnings.append(
                f"{kind} {component_id} reads environment variable {name!r} but does not declare it in runtime.envFromHost or interface grants.envFromHost/secretsFromHost."
            )
    label = f"{component_id} {' '.join(str(value) for value in raw.get('tags', []) or [])} {raw.get('description', '')}".lower()
    if any(token in label for token in ("llm", "openai", "openrouter", "anthropic")):
        provider_vars = {name for name in used if _looks_like_required_secret(name)}
        if not provider_vars:
            warnings.append(
                f"{kind} {component_id} is described as provider/LLM-related but no provider API key usage was detected. "
                "If it is only a seed or baseline method, rename it clearly."
            )
    return warnings


def _component_python_paths(config_path: Path, raw: JsonDict) -> List[Path]:
    if raw.get("config") == "environment":
        evaluator = (
            raw.get("evaluator", {}) if isinstance(raw.get("evaluator"), dict) else {}
        )
        return _config_python_paths(config_path, evaluator.get("pythonPath", []) or [])
    if raw.get("config") == "method":
        entrypoint = (
            raw.get("entrypoint", {}) if isinstance(raw.get("entrypoint"), dict) else {}
        )
        return _config_python_paths(config_path, entrypoint.get("pythonPath", []) or [])
    return [_config_dir(config_path)]


def _config_python_paths(config_path: Path, values: Iterable[Any]) -> List[Path]:
    roots = [_config_dir(config_path)]
    for value in values:
        if isinstance(value, str) and value:
            candidate = Path(value).expanduser()
            roots.append(
                candidate.resolve()
                if candidate.is_absolute()
                else (_config_dir(config_path) / candidate).resolve()
            )
    return _dedupe_existing_paths(roots)


def _dedupe_existing_paths(paths: Iterable[Path]) -> List[Path]:
    result: List[Path] = []
    seen: set[Path] = set()
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        if resolved.exists():
            result.append(resolved)
    return result


def _config_dir(path: Path) -> Path:
    return path.parent if path.is_file() else path


def _source_top_level_names(source_root: Path) -> set[str]:
    ignored = {".git", ".venv", "__pycache__", "node_modules", "runs", ".optpilot"}
    if not source_root.exists() or not source_root.is_dir():
        return set()
    names = set()
    for child in source_root.iterdir():
        if child.name in ignored or child.name.startswith("."):
            continue
        if child.is_dir() or child.suffix == ".py":
            names.add(child.stem if child.is_file() else child.name)
    return names


def _python_imports_in_file(path: Path) -> List[str]:
    try:
        tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
    except SyntaxError:
        return []
    modules: List[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name:
                    modules.append(alias.name)
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0 and node.module:
                modules.append(node.module)
    return modules


def _module_exists_under_roots(module_name: str, roots: Iterable[Path]) -> bool:
    parts = module_name.split(".")
    for root in roots:
        current = root.joinpath(*parts)
        if current.with_suffix(".py").exists() or (current / "__init__.py").exists():
            return True
        top = root / parts[0]
        if len(parts) == 1 and (
            top.with_suffix(".py").exists() or (top / "__init__.py").exists()
        ):
            return True
    return False


def _declared_component_env_from_host(raw: JsonDict) -> set[str]:
    names: set[str] = set()
    runtime = raw.get("runtime", {}) if isinstance(raw.get("runtime"), dict) else {}
    names.update(
        str(item) for item in runtime.get("envFromHost", []) or [] if str(item)
    )
    setup = runtime.get("setup", {}) if isinstance(runtime.get("setup"), dict) else {}
    names.update(str(item) for item in setup.get("envFromHost", []) or [] if str(item))
    kind = str(raw.get("config") or "")
    if kind in {"environment", "method", "resource"}:
        try:
            profiles = _compile_component_interface_profiles(
                raw.get("interface"),
                component_kind=kind,
            )
        except (TypeError, ValueError):
            profiles = []
        for profile in profiles:
            names.update(profile.grants.env_from_host)
            names.update(profile.grants.secrets_from_host)
    return names


def _source_env_var_names(component_root: Path) -> set[str]:
    names: set[str] = set()
    if not component_root.exists():
        return names
    pattern = re.compile(
        r"(?:os\.getenv|os\.environ\.get|environ\.get)\(\s*['\"]([A-Z][A-Z0-9_]{2,})['\"]|"
        r"(?:os\.)?environ\[\s*['\"]([A-Z][A-Z0-9_]{2,})['\"]\s*\]"
    )
    for path in component_root.rglob("*.py"):
        if _path_has_part(path, {".venv", "__pycache__", "node_modules"}):
            continue
        text = path.read_text(encoding="utf-8", errors="replace")
        for match in pattern.finditer(text):
            for group in match.groups():
                if group:
                    names.add(group)
    return names


def _looks_like_required_secret(name: str) -> bool:
    upper = name.upper()
    return any(
        token in upper
        for token in (
            "API_KEY",
            "TOKEN",
            "SECRET",
            "PASSWORD",
            "OPENAI",
            "OPENROUTER",
            "ANTHROPIC",
        )
    )


def _stdlib_module_names() -> set[str]:
    return set(getattr(sys, "stdlib_module_names", set())) | set(
        sys.builtin_module_names
    )


def _path_has_part(path: Path, names: set[str]) -> bool:
    return any(part in names for part in path.parts)


def _package_plan_path(state: UiState, workspace_id: str, plan_id: str) -> Path:
    safe_workspace_id = _safe_artifact_identifier(workspace_id, "workspace id")
    safe_plan_id = _safe_artifact_identifier(plan_id, "package plan id")
    return _contained_output_path(
        _workspace_artifact_root(state),
        Path(safe_workspace_id) / "package_plans" / f"{safe_plan_id}.json",
    )


def _read_package_plan(state: UiState, workspace_id: str, plan_id: str) -> JsonDict:
    path = _package_plan_path(state, workspace_id, plan_id)
    if not path.exists():
        raise FileNotFoundError(f"Package plan not found: {plan_id}")
    plan = _read_json(path)
    if (
        str(plan.get("id") or "") != plan_id
        or str(plan.get("workspace_id") or "") != workspace_id
    ):
        raise PermissionError(
            "Package plan identity does not match its storage location."
        )
    _assert_configured_package_plan_authority(state, plan)
    return plan


def _write_package_plan(state: UiState, workspace_id: str, plan: JsonDict) -> None:
    plan_id = str(plan.get("id") or "")
    if not plan_id:
        raise ValueError("Package plan id is required.")
    if str(plan.get("workspace_id") or "") != workspace_id:
        raise PermissionError(
            "Package plan workspace_id does not match its storage location."
        )
    path = _package_plan_path(state, workspace_id, plan_id)
    path.parent.mkdir(parents=True, exist_ok=True)
    path = _package_plan_path(state, workspace_id, plan_id)
    path.write_text(json.dumps(plan, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def _now_iso() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def slug_path(path: Path) -> str:
    encoded = (
        base64.urlsafe_b64encode(str(path.resolve()).encode("utf-8"))
        .decode("ascii")
        .rstrip("=")
    )
    return encoded[:24]


def _path_hash(path: Path) -> str:
    return hashlib.sha1(
        str(path.resolve()).encode("utf-8", errors="replace")
    ).hexdigest()[:10]


def _safe_workspace_root(state: UiState, root: Path) -> Path:
    root = root.resolve()
    allowed_roots = [
        state.cwd,
        *state.catalog_roots,
        *state.run_roots,
        state.sessions_dir,
        state.workspaces_dir,
    ]
    runtime = state.realm_runtime
    editable_workspaces = (
        getattr(runtime, "editable_workspaces", None)
        if runtime is not None and not getattr(runtime, "closed", False)
        else None
    )
    if editable_workspaces is not None:
        # Only the provider-owned editable-checkout namespace is a Studio
        # workspace root.  Other Realm directories remain private authority,
        # content, projection, process, and volume implementation details.
        allowed_roots.append(editable_workspaces.checkout_root)
    if any(_is_relative_to(root, allowed) for allowed in allowed_roots):
        return root
    if _is_active_catalog_workspace_projection_path(state, root):
        return root
    # Naming only the rejected path leaves nothing to act on: a person is told
    # where they cannot put a Workspace and not where they can. Name the two
    # places that are actually theirs to use -- the project folder Studio was
    # started in, and the folder it keeps Workspaces in. The rest of the
    # allowlist is catalog packages and Studio's own storage, which nobody
    # should be steered towards, so listing all of it would trade silence for
    # a wall of paths.
    raise PermissionError(
        f"Workspace root is outside allowed OptPilot paths: {root}. "
        f"Put it inside the project folder ({state.cwd}) "
        f"or Studio's Workspaces folder ({state.workspaces_dir})."
    )


def _is_local_catalog_path(state: UiState, path: Path) -> bool:
    return _is_relative_to(path.resolve(), _local_catalog_package_root(state).resolve())


def _relative_path(path: Path, root: Path) -> str:
    try:
        return str(path.resolve().relative_to(root.resolve()))
    except ValueError:
        return path.name


def _focus_paths_for_config(root: Path, config_path: Path, raw: JsonDict) -> List[str]:
    focus = [_relative_path(config_path, root)]
    config = raw.get("config")
    if config == "environment":
        evaluator = (
            raw.get("evaluator", {}) if isinstance(raw.get("evaluator"), dict) else {}
        )
        focus.extend(
            _likely_python_focus_paths(
                root, config_path, evaluator.get("python") or evaluator.get("adapter")
            )
        )
        command = evaluator.get("command")
        if isinstance(command, list):
            focus.extend(_command_focus_paths(root, config_path, command))
        method_context = (
            raw.get("methodContext", {})
            if isinstance(raw.get("methodContext"), dict)
            else {}
        )
        for item in method_context.get("instructions", []) or []:
            if isinstance(item, str):
                focus.append(_focus_path_value(root, config_path, item))
        for item in method_context.get("references", []) or []:
            if isinstance(item, dict) and item.get("path"):
                focus.append(_focus_path_value(root, config_path, str(item["path"])))
        for item in raw.get("trialWorkspace", []) or []:
            if isinstance(item, dict) and item.get("from"):
                focus.append(_focus_path_value(root, config_path, str(item["from"])))
    elif config == "method":
        entrypoint = (
            raw.get("entrypoint", {}) if isinstance(raw.get("entrypoint"), dict) else {}
        )
        focus.extend(
            _likely_python_focus_paths(root, config_path, entrypoint.get("python"))
        )
        command = entrypoint.get("command")
        if isinstance(command, list):
            focus.extend(_command_focus_paths(root, config_path, command))
    elif config == "study":
        for key in ("environmentConfig", "methodConfig"):
            if raw.get(key):
                focus.append(str(raw[key]))
    seen = set()
    result = []
    for item in focus:
        if not item or item in seen:
            continue
        seen.add(item)
        result.append(item)
    return result


def _likely_python_focus_paths(
    root: Path, config_path: Path, import_ref: Any
) -> List[str]:
    candidates = []
    if isinstance(import_ref, str) and ":" in import_ref:
        module_name = import_ref.split(":", 1)[0].split(".")[-1]
        candidates.append(f"{module_name}.py")
    candidates.extend(["evaluator.py", "method.py", "adapter.py", "main.py"])
    result = []
    for name in candidates:
        path = config_path.parent / name
        if path.exists() and path.is_file():
            result.append(_relative_path(path, root))
    return result


def _focus_path_value(root: Path, config_path: Path, value: str) -> str:
    config_relative = (config_path.parent / value).resolve()
    if config_relative.exists() and _is_relative_to(config_relative, root.resolve()):
        return _relative_path(config_relative, root)
    return value


def _command_focus_paths(
    root: Path, config_path: Path, command: List[Any]
) -> List[str]:
    result = []
    for item in command:
        if not isinstance(item, str) or item.startswith("{"):
            continue
        path = (config_path.parent / item).resolve()
        if path.exists() and path.is_file():
            result.append(_relative_path(path, root))
    return result


def _registered_config_filename(kind: str, fallback: str) -> str:
    if kind == "environment":
        return "environment.yaml"
    if kind == "method":
        return "method.yaml"
    if kind == "resource":
        return "optpilot.resource.yaml"
    return fallback or "config.yaml"


def _registration_output_relative(
    root: Path,
    source: Path,
    config_source: Optional[Path],
    kind: str,
    item: Optional[JsonDict] = None,
) -> Path:
    workspace_relative = str(source.resolve().relative_to(root.resolve()))
    if item is not None:
        rewritten = _path_rewrite_for_item(
            item, workspace_relative, Path(workspace_relative)
        )
        if str(rewritten) != workspace_relative:
            return rewritten
    if config_source is not None and source.resolve() == config_source.resolve():
        return Path(_registered_config_filename(kind, config_source.name))
    if config_source is not None and _is_relative_to(
        source.resolve(), config_source.parent.resolve()
    ):
        return source.resolve().relative_to(config_source.parent.resolve())
    return source.resolve().relative_to(root.resolve())


def _normalize_registered_config(
    raw: JsonDict,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict] = None,
) -> JsonDict:
    config = str(raw.get("config") or "")
    normalized = deepcopy(raw)
    if config == "environment":
        _normalize_python_path(normalized.get("evaluator"), "pythonPath")
        _rewrite_optional_path(
            normalized.get("evaluator"), "cwd", root, config_source, destination, item
        )
        _rewrite_command_paths(
            normalized.get("evaluator"),
            "command",
            root,
            config_source,
            destination,
            item,
        )
        _rewrite_method_context_paths(
            normalized.get("methodContext"), root, config_source, destination, item
        )
        for workspace_item in normalized.get("trialWorkspace", []) or []:
            if isinstance(workspace_item, dict):
                _rewrite_optional_path(
                    workspace_item, "from", root, config_source, destination, item
                )
        _rewrite_component_runtime_paths(
            normalized.get("runtime"), root, config_source, destination, item
        )
        _rewrite_interface_paths(
            normalized.get("interface"), root, config_source, destination, item
        )
    elif config == "method":
        _normalize_python_path(normalized.get("entrypoint"), "pythonPath")
        _rewrite_command_paths(
            normalized.get("entrypoint"),
            "command",
            root,
            config_source,
            destination,
            item,
        )
        _rewrite_component_runtime_paths(
            normalized.get("runtime"), root, config_source, destination, item
        )
        _rewrite_interface_paths(
            normalized.get("interface"), root, config_source, destination, item
        )
    elif config == "resource":
        _rewrite_interface_paths(
            normalized.get("interface"), root, config_source, destination, item
        )
    return normalized


def _normalize_python_path(section: Any, key: str) -> None:
    if not isinstance(section, dict):
        return
    ref = str(section.get("python") or section.get("adapter") or "")
    module_name = ref.partition(":")[0]
    if section.get(key):
        section[key] = ["."]
    elif module_name and "." not in module_name:
        section[key] = ["."]


def _rewrite_method_context_paths(
    method_context: Any,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(method_context, dict):
        return
    instructions = method_context.get("instructions")
    if isinstance(instructions, list):
        method_context["instructions"] = [
            _registered_path_value(value, root, config_source, destination, item)
            if isinstance(value, str)
            else value
            for value in instructions
        ]
    for reference in method_context.get("references", []) or []:
        if isinstance(reference, dict):
            _rewrite_optional_path(
                reference, "path", root, config_source, destination, item
            )


def _rewrite_component_runtime_paths(
    runtime: Any,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(runtime, dict):
        return
    _rewrite_optional_path(runtime, "workdir", root, config_source, destination, item)
    _rewrite_setup_paths(runtime.get("setup"), root, config_source, destination, item)
    container = (
        runtime.get("container") if isinstance(runtime.get("container"), dict) else None
    )
    build = (
        container.get("build")
        if isinstance(container, dict) and isinstance(container.get("build"), dict)
        else None
    )
    if isinstance(build, dict):
        _rewrite_optional_path(build, "context", root, config_source, destination, item)
        _rewrite_optional_path(
            build, "dockerfile", root, config_source, destination, item
        )


def _rewrite_interface_paths(
    interface: Any,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(interface, dict):
        return
    profiles = interface.get("launchProfiles")
    if isinstance(profiles, list):
        for profile in profiles:
            _rewrite_interface_profile_paths(
                profile,
                root,
                config_source,
                destination,
                item,
            )
        return
    _rewrite_interface_profile_paths(
        interface,
        root,
        config_source,
        destination,
        item,
    )


def _rewrite_interface_profile_paths(
    profile: Any,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(profile, dict):
        return
    _rewrite_optional_path(profile, "cwd", root, config_source, destination, item)
    _rewrite_command_paths(profile, "command", root, config_source, destination, item)
    runtime = profile.get("runtime") if isinstance(profile.get("runtime"), dict) else {}
    _rewrite_setup_paths(runtime.get("setup"), root, config_source, destination, item)
    container = (
        runtime.get("container") if isinstance(runtime.get("container"), dict) else {}
    )
    build = container.get("build") if isinstance(container.get("build"), dict) else None
    if isinstance(build, dict):
        _rewrite_optional_path(build, "context", root, config_source, destination, item)
        _rewrite_optional_path(
            build, "dockerfile", root, config_source, destination, item
        )


def _rewrite_setup_paths(
    setup: Any,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(setup, dict):
        return
    for step in setup.get("steps", []) or []:
        if not isinstance(step, dict):
            continue
        _rewrite_optional_path(step, "cwd", root, config_source, destination, item)
        requirements = step.get("requirements")
        if isinstance(requirements, list):
            step["requirements"] = [
                _registered_path_value(value, root, config_source, destination, item)
                if isinstance(value, str)
                else value
                for value in requirements
            ]
        _rewrite_command_paths(step, "command", root, config_source, destination, item)


def _rewrite_command_paths(
    section: Any,
    key: str,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(section, dict) or not isinstance(section.get(key), list):
        return
    rewritten = []
    for value in section[key]:
        if isinstance(value, str) and _looks_like_command_file_token(value):
            rewritten.append(
                _registered_path_value(value, root, config_source, destination, item)
            )
        else:
            rewritten.append(value)
    section[key] = rewritten


def _rewrite_optional_path(
    section: Any,
    key: str,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> None:
    if not isinstance(section, dict) or not isinstance(section.get(key), str):
        return
    section[key] = _registered_path_value(
        str(section[key]), root, config_source, destination, item
    )


def _registered_path_value(
    value: str,
    root: Path,
    config_source: Path,
    destination: Path,
    item: Optional[JsonDict],
) -> str:
    if not value or value == "." or value.startswith("{") or "://" in value:
        return value
    if "\x00" in value or "\\" in value:
        raise ValueError(
            f"Registered path must be portable and workspace-local: {value!r}."
        )
    root = root.resolve()
    value_path = Path(value).expanduser()
    candidates = (
        [value_path]
        if value_path.is_absolute()
        else [config_source.parent / value_path, root / value_path]
    )
    for candidate in candidates:
        _require_safe_workspace_match(root, candidate)
        if not candidate.exists():
            continue
        resolved = candidate.resolve()
        if resolved == root:
            return "."
        output_relative = _registration_output_relative(
            root,
            resolved,
            config_source,
            str(_read_yaml(config_source).get("config") or ""),
            item,
        )
        return str(output_relative)
    if value_path.is_absolute():
        raise ValueError(
            f"Registered absolute path is not a workspace file: {value!r}."
        )
    _safe_relative_plan_path(value, "registered path")
    return value


def _default_registration_include(
    root: Path, config_path: Path, raw: JsonDict
) -> List[str]:
    include = set(_focus_paths_for_config(root, config_path, raw))
    include.update(_declared_python_path_includes(root, config_path, raw))
    include.update(_import_source_root_includes(root, config_path, include))
    include.update(_locked_setup_registration_includes(root, config_path, raw))
    for name in ("assets", "prompts", "data", "cases"):
        if (config_path.parent / name).exists():
            include.add(_relative_path(config_path.parent / name, root) + "/**")
    include.add(_relative_path(config_path, root))
    return sorted(include)


def _locked_setup_registration_includes(
    root: Path,
    config_path: Path,
    raw: JsonDict,
) -> List[str]:
    """Follow the exact local files required by a supported locked setup."""

    runtime = raw.get("runtime") if isinstance(raw.get("runtime"), dict) else {}
    try:
        setup = validate_locked_python_setup_declaration(runtime.get("setup"))
    except LockedPythonRuntimeError:
        return []
    root = root.resolve()

    def local_path(base: Path, value: Any) -> Optional[Path]:
        if (
            not isinstance(value, str)
            or not value
            or "\x00" in value
            or "\\" in value
        ):
            return None
        portable = PurePosixPath(value)
        windows = PureWindowsPath(value)
        if portable.is_absolute() or windows.drive or windows.root:
            return None
        unresolved = base.joinpath(*portable.parts)
        try:
            _require_safe_workspace_match(root, unresolved)
        except (OSError, ValueError):
            return None
        resolved = unresolved.resolve()
        return resolved if _is_relative_to(resolved, root) else None

    step = setup["steps"][0]
    cwd = local_path(config_path.parent, step["cwd"])
    if cwd is None or not cwd.is_dir():
        return []
    includes: set[str] = set()
    for requirement in step["requirements"]:
        lock_path = local_path(cwd, requirement)
        if lock_path is None or not lock_path.is_file():
            continue
        includes.add(_relative_path(lock_path, root))
        try:
            locked_wheels = parse_locked_python_wheel_lock(lock_path.read_bytes())
        except (LockedPythonRuntimeError, OSError):
            continue
        for wheel_value, _digest in locked_wheels:
            wheel_path = local_path(lock_path.parent, wheel_value)
            if (
                wheel_path is not None
                and wheel_path.is_file()
                and wheel_path.suffix == ".whl"
            ):
                includes.add(_relative_path(wheel_path, root))
    return sorted(includes)


def _declared_python_path_includes(
    root: Path, config_path: Path, raw: JsonDict
) -> List[str]:
    config = raw.get("config")
    section: JsonDict = {}
    if config == "environment" and isinstance(raw.get("evaluator"), dict):
        section = raw["evaluator"]
    elif config == "method" and isinstance(raw.get("entrypoint"), dict):
        section = raw["entrypoint"]
    result: List[str] = []
    for value in section.get("pythonPath", []) or []:
        if not isinstance(value, str) or value in {"", "."}:
            continue
        path = (config_path.parent / value).resolve()
        if not _is_relative_to(path, root.resolve()) or not path.exists():
            continue
        if path.is_dir():
            result.append(_relative_path(path, root) + "/**")
        elif path.is_file():
            result.append(_relative_path(path, root))
    return result


def _import_source_root_includes(
    root: Path, config_path: Path, focus_paths: Iterable[str]
) -> List[str]:
    includes: List[str] = []
    for relative in focus_paths:
        path = (root / str(relative)).resolve()
        if not path.exists() or not path.is_file() or path.suffix != ".py":
            continue
        try:
            tree = ast.parse(path.read_text(encoding="utf-8"))
        except Exception:
            continue
        for module in _top_level_imports(tree):
            candidate_dir = root / module
            candidate_file = root / f"{module}.py"
            if candidate_dir.exists() and candidate_dir.is_dir():
                includes.append(f"{module}/**")
            elif candidate_file.exists() and candidate_file.is_file():
                includes.append(f"{module}.py")
    return sorted(set(includes))


def _top_level_imports(tree: ast.AST) -> List[str]:
    modules: List[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            modules.extend(
                alias.name.split(".", 1)[0] for alias in node.names if alias.name
            )
        elif isinstance(node, ast.ImportFrom) and node.level == 0 and node.module:
            modules.append(node.module.split(".", 1)[0])
    return modules


def _path_rewrite_for_item(
    item: Optional[JsonDict], relative: str, fallback: Path
) -> Path:
    if isinstance(item, dict):
        for rewrite in item.get("path_rewrites", []) or []:
            if not isinstance(rewrite, dict):
                continue
            if str(rewrite.get("from") or "") == relative and rewrite.get("to"):
                return _safe_relative_plan_path(
                    str(rewrite["to"]), "path rewrite destination"
                )
    return _safe_relative_plan_path(fallback.as_posix(), "package output path")


def _safe_relative_plan_path(value: str, label: str) -> Path:
    if not isinstance(value, str) or not value or "\x00" in value or "\\" in value:
        raise ValueError(f"{label} must be a non-empty portable relative path.")
    path = PurePosixPath(value)
    windows_path = PureWindowsPath(value)
    if (
        path.is_absolute()
        or windows_path.drive
        or windows_path.root
        or any(part in {"", ".", ".."} for part in path.parts)
    ):
        raise ValueError(
            f"{label} must not be absolute or contain traversal: {value!r}."
        )
    return Path(*path.parts)


def _safe_artifact_identifier(value: str, label: str) -> str:
    if (
        not isinstance(value, str)
        or not value
        or "\x00" in value
        or "/" in value
        or "\\" in value
    ):
        raise ValueError(f"{label} must be a single non-empty path component.")
    path = PurePosixPath(value)
    windows_path = PureWindowsPath(value)
    if (
        path.is_absolute()
        or windows_path.drive
        or windows_path.root
        or len(path.parts) != 1
        or path.parts[0] in {".", ".."}
    ):
        raise ValueError(
            f"{label} must not be absolute or contain traversal: {value!r}."
        )
    return value


def _workspace_artifact_root(state: UiState) -> Path:
    _require_no_symlink_path(
        state.cwd, state.workspaces_dir, "Studio workspace storage"
    )
    return state.workspaces_dir.resolve()


def _require_no_symlink_path(root: Path, path: Path, label: str) -> None:
    resolved_root = root.resolve()
    lexical_path = Path(os.path.abspath(path.expanduser()))
    try:
        relative = lexical_path.relative_to(resolved_root)
    except ValueError as exc:
        raise ValueError(f"{label} escapes its root: {path!s}.") from exc
    cursor = resolved_root
    for component in relative.parts:
        cursor = cursor / component
        if cursor.is_symlink():
            raise ValueError(f"{label} contains a symlink: {relative!s}.")


def _contained_output_path(destination: Path, relative: Path) -> Path:
    safe_relative = _safe_relative_plan_path(relative.as_posix(), "package output path")
    if destination.is_symlink():
        raise ValueError(f"Package destination must not be a symlink: {destination!s}.")
    root = destination.resolve()
    unresolved = root / safe_relative
    output = unresolved.resolve()
    if not _is_relative_to(output, root):
        raise ValueError(f"Package output escapes its destination: {relative!s}.")
    _require_no_symlink_path(root, unresolved, "Package output")
    return output


def _looks_like_command_file_token(value: str) -> bool:
    if not value or value.startswith("{") or "://" in value:
        return False
    if value in {
        "python",
        "python3",
        "uv",
        "npm",
        "node",
        "bash",
        "sh",
        "cmd",
        "powershell",
    }:
        return False
    suffix = Path(value).suffix.lower()
    return (
        suffix
        in {
            ".py",
            ".js",
            ".mjs",
            ".cjs",
            ".sh",
            ".bash",
            ".json",
            ".yaml",
            ".yml",
            ".toml",
            ".txt",
        }
        or "/" in value
        or "\\" in value
    )


def _require_catalog_destination(state: UiState, destination: Path) -> Path:
    cwd = state.cwd.resolve()
    local_catalog_path = cwd / CATALOG_DIR_NAME / LOCAL_PACKAGE_NAME
    _require_no_symlink_path(cwd, local_catalog_path, "Local catalog")
    local_catalog = local_catalog_path.resolve()
    unresolved = destination.expanduser()
    if not unresolved.is_absolute():
        unresolved = cwd / unresolved
    resolved = unresolved.resolve()
    if not _is_relative_to(resolved, local_catalog):
        raise PermissionError("Registration can only write into catalog/local_package.")
    _require_no_symlink_path(local_catalog, unresolved, "Catalog destination")
    return resolved


def _local_catalog_package_root(state: UiState) -> Path:
    return state.cwd / CATALOG_DIR_NAME / LOCAL_PACKAGE_NAME


def _match_workspace_pattern(root: Path, pattern: str) -> List[Path]:
    root = root.resolve()
    _validate_workspace_pattern(pattern)
    has_glob = any(char in pattern for char in "*?[]")
    unresolved = root / pattern
    if not has_glob:
        _require_safe_workspace_match(root, unresolved)
    path = unresolved.resolve()
    if not _is_relative_to(path, root):
        raise ValueError(f"Workspace pattern escapes its root: {pattern!r}.")
    if not has_glob:
        if path.is_file():
            return [path]
        if path.is_dir():
            matches = []
            for item in path.rglob("*"):
                _require_safe_workspace_match(root, item)
                if item.is_file():
                    matches.append(item)
            return [item.resolve() for item in matches]
        return []
    matches = []
    for item in root.glob(pattern):
        _require_safe_workspace_match(root, item)
        if item.is_file():
            matches.append(item)
    return [item.resolve() for item in matches]


def _workspace_source_path(root: Path, relative: str, label: str) -> Path:
    root = root.resolve()
    safe_relative = _safe_relative_plan_path(relative, label)
    unresolved = root / safe_relative
    resolved = unresolved.resolve()
    if not _is_relative_to(resolved, root):
        raise ValueError(f"{label} escapes its workspace root: {relative!r}.")
    _require_safe_workspace_match(root, unresolved)
    return resolved


def _workspace_operation_root(
    state: UiState, workspace_id: str, declared_root: str, label: str
) -> Path:
    if not declared_root:
        raise ValueError(f"{label} is required.")
    workspace = _require_ui_workspace(state, workspace_id)
    stored_root = Path(str(workspace["root"])).expanduser()
    if stored_root.is_symlink():
        raise ValueError(f"{label} workspace root must not be a symlink.")
    workspace_root = _safe_workspace_root(state, stored_root)
    if Path(declared_root).expanduser().resolve() != workspace_root:
        raise PermissionError(f"{label} no longer matches its workspace.")
    return workspace_root


def _validate_workspace_pattern(pattern: str) -> None:
    if (
        not isinstance(pattern, str)
        or not pattern
        or "\x00" in pattern
        or "\\" in pattern
    ):
        raise ValueError(
            "Workspace include pattern must be a non-empty portable relative pattern."
        )
    path = PurePosixPath(pattern)
    windows_path = PureWindowsPath(pattern)
    if (
        path.is_absolute()
        or windows_path.drive
        or windows_path.root
        or any(part == ".." for part in path.parts)
    ):
        raise ValueError(
            f"Workspace include pattern must not be absolute or traverse: {pattern!r}."
        )


def _require_safe_workspace_match(root: Path, path: Path) -> None:
    root = root.resolve()
    absolute = Path(os.path.abspath(path.expanduser()))
    lexical_root: Optional[Path] = None
    for ancestor in (absolute, *absolute.parents):
        if ancestor.resolve() == root:
            lexical_root = ancestor
    if lexical_root is None:
        raise ValueError(f"Workspace match escapes its root: {path!s}.")
    if lexical_root.is_symlink():
        raise ValueError(
            f"Workspace match reaches its root through a symlink: {path!s}."
        )
    relative = absolute.relative_to(lexical_root)
    cursor = lexical_root
    for component in relative.parts:
        cursor = cursor / component
        if cursor.is_symlink():
            raise ValueError(f"Workspace include matched a symlink: {relative!s}.")
    if not _is_relative_to(absolute.resolve(), root):
        raise ValueError(f"Workspace match escapes its root: {path!s}.")


def _excluded_by_patterns(relative: str, patterns: List[str]) -> bool:
    return any(fnmatch.fnmatch(relative, pattern) for pattern in patterns)


def _slug_text(value: str) -> str:
    text = "".join(
        char.lower() if char.isalnum() else "-" for char in str(value)
    ).strip("-")
    while "--" in text:
        text = text.replace("--", "-")
    return text or "component"


def _find_run_dirs(roots: Iterable[Path]) -> List[Path]:
    run_dirs: List[Path] = []
    for root in roots:
        root = root.resolve()
        if _is_run_dir(root):
            run_dirs.append(root)
            continue
        if not root.exists() or not root.is_dir():
            continue
        for path in root.rglob("*"):
            if _is_run_dir(path):
                run_dirs.append(path.resolve())
    return _dedupe_paths(run_dirs)


def _default_run_roots(cwd: Path) -> List[Path]:
    roots = [cwd / "runs"]
    return _dedupe_paths([path for path in roots if path.exists()])


def _default_catalog_roots(cwd: Path) -> List[Path]:
    """Where to look for packages when the operator names no roots.

    Two places, in this order: a catalog folder beside the project (how a
    source checkout and a project-local catalog work), and the person's own
    packages folder, which is where the examples OptPilot ships are copied on
    first use. Before this looked only beside the project, so an installed
    OptPilot started onto an empty catalog no matter what it shipped with.
    """

    roots: List[Path] = []
    catalog_root = cwd / CATALOG_DIR_NAME
    if catalog_root.exists():
        roots.extend(_expand_catalog_roots([catalog_root]))
    # Only when it actually holds packages: an empty folder as a catalog root
    # would be scanned forever and found to contain nothing.
    user_packages = _prepared_user_packages_root(cwd)
    if _catalog_package_roots(user_packages):
        roots.extend(
            _user_package_roots_not_shadowed(user_packages, roots)
        )
    if roots:
        return _dedupe_paths(roots)
    return [cwd]


def _user_package_roots_not_shadowed(
    user_packages: Path, existing: Iterable[Path]
) -> List[Path]:
    """The person's packages, minus any the open project already provides.

    Two folders claiming one package id is refused, and that refusal takes the
    whole catalog down rather than one entry -- so a copy in the person's own
    folder that shares a name with something in the project would leave them
    with no catalog at all. That happens easily: the copies OptPilot itself
    makes are named after the packages they came from.

    The project wins. It is what the person opened, and it is the copy they
    are more likely to be editing.
    """

    taken = {root.name for root in existing}
    return [
        root
        for root in _expand_catalog_roots([user_packages])
        if root.name not in taken
    ]


def _prepared_user_packages_root(cwd: Path | None = None) -> Path:
    """The person's packages folder, with the shipped examples copied in.

    Copying happens here rather than at install time because an installer
    cannot know which person will run it. It is safe to repeat: an existing
    folder is left exactly as it is, including one the person edited or
    deliberately emptied.

    Not copied when the examples being shipped ARE the folder already being
    scanned. In a source checkout with an editable install, the shipped
    examples resolve to the repository's own catalog; copying them out would
    produce a second copy of every package and the catalog would then refuse
    to load at all, every package id being duplicated.
    """

    from optpilot.example_packages import (
        install_example_packages,
        shipped_examples_root,
    )
    from optpilot.realm.config import default_packages_root

    root = default_packages_root()
    try:
        shipped = shipped_examples_root()
        already_scanned = (
            cwd is not None
            and shipped is not None
            and shipped.resolve() == (cwd / CATALOG_DIR_NAME).resolve()
        )
        if not already_scanned:
            install_example_packages(root)
    except OSError:
        # A read-only or full home directory must not stop Studio starting.
        # The catalog is then simply emptier than it could have been.
        pass
    return root


def _drop_catalog_roots_containing_others(roots: Iterable[Path]) -> List[Path]:
    """Drop any root that contains another, so a package is scanned once.

    The project directory itself is used as a catalog root when no catalog
    folder exists yet. Nothing ever created one, so that was harmless; now
    registering a package does. Left alone, the project root then contains the
    new package folder and every component in it is found twice -- the second
    time attributed to a package named after the project directory.
    """

    resolved = _dedupe_paths([Path(root).resolve() for root in roots])
    return [
        root
        for root in resolved
        if not any(
            other != root and other.is_relative_to(root) for other in resolved
        )
    ]


def _register_user_packages(state: UiState) -> List[str]:
    """Make the person's own packages launchable, not merely visible.

    A package folder has to be published -- captured as an immutable, numbered
    version -- before a Run setup drafted from it can be launched, because a
    launch records exactly which bytes produced its result. Nothing did that
    for the examples OptPilot ships, so a fresh install showed packages
    and refused to run any of them.

    Only the person's own packages folder is registered here. A source
    checkout's catalog is OptPilot's own tracked files, and publishing those
    on someone's behalf is not this function's business.

    Already-published packages are skipped without being re-read, so a normal
    start costs one cheap lookup per package and nothing else. Measured, a
    genuine first start publishes every configured example in about two seconds,
    which is why
    this runs before the UI is served rather than behind it: a person who
    clicks Launch immediately should not be told to publish first while a
    background thread is still working.
    """

    from optpilot.realm.config import default_packages_root

    runtime = state.realm_runtime
    if runtime is None:
        # No realm open (a read-only or partially configured Studio). Packages
        # stay visible; publishing is simply not possible here.
        return []
    packages_root = default_packages_root()
    # The open project wins over an older copy in the person's packages
    # folder for indexing, and it must win for first-start publication too.
    # Otherwise Studio can publish the stale user copy into a fresh Realm and
    # immediately shadow the newer project package with that old revision.
    configured_elsewhere = [
        root.resolve()
        for root in getattr(state, "catalog_roots", ())
        if not _is_relative_to(root.resolve(), packages_root.resolve())
    ]
    roots = [
        root
        for root in _user_package_roots_not_shadowed(
            packages_root, configured_elsewhere
        )
        if _looks_like_catalog_package(root)
    ]
    if not roots:
        return []

    from optpilot.realm.configured_package_ingress import (
        ConfiguredPackageIngressOutcome,
    )
    from optpilot.realm.content import AllowedTreeSource

    registered: List[str] = []
    for root in roots:
        package_id = _package_plan_package_id(root.name)
        try:
            if runtime.catalog.read_head(package_id=package_id) is not None:
                continue
        except Exception:
            # Never published, or unreadable: try to publish and let that
            # attempt report the real problem.
            pass
        try:
            receipt = runtime.configured_package_ingress.publish(
                operation_id=f"studio/first-start/{package_id}",
                package_id=package_id,
                source_identity_digest=_configured_package_source_identity_digest(root),
                validation_policy_digest=_configured_package_validation_policy_digest(),
                source_resolver=lambda captured=root: AllowedTreeSource(
                    captured.resolve(),
                    excluded_directory_names=CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS,
                ),
                validator=_configured_package_static_validator,
                excluded_directory_names=CONFIGURED_PACKAGE_CAPTURE_EXCLUDED_DIRS,
            )
        except Exception as error:
            # One unpublishable package must not stop Studio starting, nor
            # stop the others being published. It stays visible and reports
            # its own problem when the person tries to use it.
            print(
                f"OptPilot could not set up the package {package_id}: "
                f"{type(error).__name__}: {error}",
                file=sys.stderr,
            )
            continue
        if receipt.outcome is ConfiguredPackageIngressOutcome.PUBLISHED:
            registered.append(package_id)
    return registered


def _configured_package_source_identity_digest(root: Path) -> str:
    """A stable identity for one package folder, for publishing purposes.

    Derived from the identity the package declares, so the same package keeps
    the same publishing authority after being copied to another machine or
    moved to another folder -- which is what makes a later re-install update
    the package instead of colliding with it. A package that declares no
    identity falls back to its location, which is all there is to go on.
    """

    try:
        identity = package_identity(root)
    except ValueError:
        identity = None
    if identity is not None:
        return request_digest(
            {
                "schema": "optpilot.configured-package-source.v2",
                "identity": identity,
            }
        )
    return request_digest(
        {
            "schema": "optpilot.configured-package-source.v1",
            "root": str(root),
        }
    )


def _configured_package_validation_policy_digest() -> str:
    """Names the static checks a published package was accepted under.

    Part of the published record, so a later change to what the checks do is
    visible as a different policy rather than silently reinterpreting an old
    acceptance.
    """

    return request_digest(
        {
            "schema": "optpilot.configured-package-validation-policy.v1",
            "max_yaml_files": CONFIGURED_PACKAGE_MAX_YAML_FILES,
        }
    )


def _refresh_catalog_package_roots(state: UiState) -> None:
    catalog_root = state.cwd / CATALOG_DIR_NAME
    if catalog_root.exists():
        state.catalog_roots = _dedupe_paths(
            [*state.catalog_roots, *_expand_catalog_roots([catalog_root])]
        )
    # A package added to the person's own folder appears without a restart,
    # the same as one dropped beside the project -- but only when the roots
    # were not named explicitly.
    if getattr(state, "catalog_roots_are_explicit", False):
        state.catalog_roots = _drop_catalog_roots_containing_others(state.catalog_roots)
        state._configured_catalog_source_roots = {
            _configured_catalog_source_id(root): root for root in state.catalog_roots
        }
        return
    from optpilot.realm.config import default_packages_root

    user_packages = default_packages_root()
    if _catalog_package_roots(user_packages):
        state.catalog_roots = _dedupe_paths(
            [
                *state.catalog_roots,
                *_user_package_roots_not_shadowed(
                    user_packages, state.catalog_roots
                ),
            ]
        )
    state.catalog_roots = _drop_catalog_roots_containing_others(state.catalog_roots)
    state._configured_catalog_source_roots = {
        _configured_catalog_source_id(root): root for root in state.catalog_roots
    }


def _expand_catalog_roots(roots: Iterable[Path]) -> List[Path]:
    expanded: List[Path] = []
    for root in roots:
        root = root.resolve()
        packages = _catalog_package_roots(root)
        if packages and not _looks_like_catalog_package(root):
            expanded.extend(packages)
        else:
            expanded.append(root)
    return _dedupe_paths(expanded)


def _catalog_package_roots(catalog_root: Path) -> List[Path]:
    if _looks_like_catalog_package(catalog_root):
        return [catalog_root]
    if not catalog_root.exists() or not catalog_root.is_dir():
        return []
    return sorted(
        path
        for path in catalog_root.iterdir()
        if path.is_dir() and _looks_like_catalog_package(path)
    )


def _looks_like_catalog_package(path: Path) -> bool:
    return any((path / name).exists() for name in CATALOG_PACKAGE_DIRS)


def _newest_run_dir(root: Path, *, exclude: set[Path]) -> Optional[Path]:
    candidates = [
        path for path in _find_run_dirs([root]) if path.resolve() not in exclude
    ]
    if not candidates:
        return None
    return max(candidates, key=_path_mtime)


def _is_run_dir(path: Path) -> bool:
    if not path.exists() or not path.is_dir():
        return False
    return any((path / file_name).exists() for file_name in RUN_SENTINEL_FILES)


def _list_run_files(run_dir: Path) -> List[JsonDict]:
    files = []
    for path in sorted(run_dir.rglob("*")):
        if path.is_file():
            relative = path.relative_to(run_dir)
            stat = path.stat()
            files.append(
                {
                    "relative_path": str(relative),
                    "path": str(path),
                    "size": stat.st_size,
                    "modified_at": stat.st_mtime,
                }
            )
    return files[:500]


def _iter_yaml_files(root: Path) -> Iterable[Path]:
    root = root.resolve()
    if root.is_file():
        if root.suffix.lower() in {".yaml", ".yml"}:
            yield root
        return
    # ``Path.rglob`` cannot prune a subtree. Large local runtime caches (for
    # example node_modules inside an interface resource) were therefore fully
    # walked even though every descendant was discarded afterward. Prune at
    # the directory boundary so catalog refresh time depends on authored
    # source, not machine-local dependency caches.
    for directory, directory_names, file_names in os.walk(
        root, topdown=True, followlinks=False
    ):
        directory_path = Path(directory)
        retained_directories: List[str] = []
        for name in directory_names:
            if name in EXCLUDED_SCAN_DIRS:
                continue
            candidate = directory_path / name
            try:
                _require_safe_workspace_match(root, candidate)
            except ValueError:
                continue
            retained_directories.append(name)
        directory_names[:] = retained_directories

        for name in file_names:
            path = directory_path / name
            if path.suffix.lower() not in {".yaml", ".yml"}:
                continue
            try:
                _require_safe_workspace_match(root, path)
            except ValueError:
                continue
            yield path.resolve()


def _run_status(summary: JsonDict, job: Optional[JsonDict]) -> str:
    if not summary:
        return str(job.get("status")) if job and job.get("status") else "incomplete"
    run_status = summary.get("run_status")
    if run_status == "succeeded":
        return "completed"
    if run_status in {"failed", "cancelled"}:
        return str(run_status)
    if run_status == "running":
        job_status = str(job.get("status") or "") if job else ""
        if job_status == "cancelled":
            return "cancelled"
        if job_status in {"completed", "failed"}:
            return "failed"
        return "running"
    return "completed"


def _method_summary(study_spec: JsonDict) -> JsonDict:
    method = (
        study_spec.get("method", {})
        if isinstance(study_spec.get("method"), dict)
        else {}
    )
    implementation = (
        method.get("implementation", {})
        if isinstance(method.get("implementation"), dict)
        else {}
    )
    return {
        "id": method.get("id"),
        "implementation_type": implementation.get("type"),
        "implementation": implementation.get("callable")
        or implementation.get("command")
        or implementation.get("endpoint"),
        "protocol": implementation.get("protocol", "optpilot.method.batch.v1"),
    }


def _status_counts(observations: List[JsonDict]) -> JsonDict:
    counts: JsonDict = {}
    for observation in observations:
        status = observation.get("status", "unknown")
        counts[status] = counts.get(status, 0) + 1
    return counts


def _failure_count(status_counts: JsonDict) -> int:
    return sum(
        int(status_counts.get(status, 0) or 0)
        for status in {"failed", "invalid", "timeout", "partial"}
    )


def _query_value(query: Dict[str, List[str]], key: str) -> Optional[str]:
    values = query.get(key, [])
    if not values:
        return None
    if len(values) != 1:
        raise ValueError(f"Query parameter {key!r} must appear at most once.")
    value = values[0]
    return value if value != "" else None


def _require_allowed_query_keys(
    query: Mapping[str, Any], *, allowed: set[str], label: str
) -> None:
    extra = set(query) - allowed
    if extra:
        raise ValueError(
            f"{label} has unsupported query parameters: {sorted(extra)!r}."
        )


def _required_selection_content_session_query(
    query: Dict[str, List[str]],
) -> str:
    value = _query_value(query, "content_session_id")
    if value is None:
        raise ValueError("Query parameter 'content_session_id' is required.")
    return _canonical_selection_content_session_id(value)


def _bounded_query_int(
    query: Dict[str, List[str]],
    key: str,
    *,
    default: int,
    minimum: int = 1,
    maximum: Optional[int] = None,
) -> int:
    value = _query_value(query, key)
    if value is None:
        return default
    if len(value) > 20:
        raise ValueError(f"Query parameter {key!r} is too large.")
    try:
        parsed = int(value)
    except ValueError as exc:
        raise ValueError(f"Query parameter {key!r} must be an integer.") from exc
    if parsed < minimum:
        raise ValueError(f"Query parameter {key!r} must be at least {minimum}.")
    if maximum is not None and parsed > maximum:
        raise ValueError(f"Query parameter {key!r} must be at most {maximum}.")
    return parsed


def _positive_query_value(value: str, label: str) -> int:
    if not isinstance(value, str) or len(value) > 20:
        raise ValueError(f"Query parameter {label!r} must be a positive integer.")
    try:
        parsed = int(value)
    except ValueError as error:
        raise ValueError(
            f"Query parameter {label!r} must be a positive integer."
        ) from error
    if parsed <= 0 or str(parsed) != value:
        raise ValueError(f"Query parameter {label!r} must be a positive integer.")
    return parsed


def _required_query_int(query: Dict[str, List[str]], key: str) -> int:
    if _query_value(query, key) is None:
        raise ValueError(f"Query parameter {key!r} is required.")
    return _bounded_query_int(query, key, default=0, minimum=0)


def _stdout_run_summary_projection(
    payload: JsonDict,
    *,
    expected_run_id: str,
) -> JsonDict:
    """Accept only the exact public Realm summary projection envelope."""

    expected_fields = {
        "schema",
        "run_id",
        "run_status",
        "submission_state",
        "stop_code",
        "retention_state",
        "objective",
        "budget",
        "counts",
        "best",
        "cursor",
    }
    if (
        not isinstance(payload, dict)
        or set(payload) != expected_fields
        or payload.get("schema") != RUN_SUMMARY_PROJECTION_SCHEMA
        or payload.get("run_id") != expected_run_id
    ):
        return {}
    return deepcopy(payload)


def _parse_summary_from_stdout(path: Path) -> JsonDict:
    if not path.exists():
        return {}
    text = path.read_text(encoding="utf-8", errors="replace").strip()
    if not text:
        return {}
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        start = text.find("{")
        end = text.rfind("}")
        if start >= 0 and end > start:
            try:
                return json.loads(text[start : end + 1])
            except json.JSONDecodeError:
                return {}
    return {}


def _read_json(path: Path) -> JsonDict:
    if not path.exists():
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError:
        return {}


def _read_jsonl(path: Path) -> List[JsonDict]:
    if not path.exists():
        return []
    rows = []
    for line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        if not line.strip():
            continue
        try:
            rows.append(json.loads(line))
        except json.JSONDecodeError:
            rows.append({"_parse_error": True, "raw": line})
    return rows


def _read_yaml(path: Path) -> JsonDict:
    with path.open("r", encoding="utf-8") as handle:
        payload = yaml.safe_load(handle) or {}
    if not isinstance(payload, dict):
        return {}
    return payload


def _resolve_user_path(value: Any, cwd: Path) -> Path:
    if not value:
        raise ValueError("Path is required.")
    path = Path(str(value)).expanduser()
    if not path.is_absolute():
        path = cwd / path
    return path.resolve()


def _optional_user_path(value: Any, cwd: Path) -> Optional[Path]:
    if not value:
        return None
    return _resolve_user_path(value, cwd)


def _encode_id(path: Path) -> str:
    return (
        base64.urlsafe_b64encode(str(path.resolve()).encode("utf-8"))
        .decode("ascii")
        .rstrip("=")
    )


def _decode_id(value: str) -> Path:
    padding = "=" * (-len(value) % 4)
    return Path(
        base64.urlsafe_b64decode((value + padding).encode("ascii")).decode("utf-8")
    ).resolve()


def _try_decode_id(value: str) -> Optional[Path]:
    try:
        return _decode_id(value)
    except Exception:
        return None


def _path_mtime(path: Path) -> float:
    try:
        return path.stat().st_mtime
    except OSError:
        return 0.0


def _dedupe_paths(paths: Iterable[Path]) -> List[Path]:
    seen = set()
    result = []
    for path in paths:
        resolved = path.resolve()
        if resolved in seen:
            continue
        seen.add(resolved)
        result.append(resolved)
    return result


def _is_relative_to(path: Path, parent: Path) -> bool:
    try:
        path.relative_to(parent)
        return True
    except ValueError:
        return False


if __name__ == "__main__":
    raise SystemExit(main())
